-- PG dokumler.sql migration
-- MSSQL SQL metinlerini PG'ye cevrilmis /*PGX*/ metinlerle gunceller.
-- Dinamik placeholder'lar ($StokId$, KOSUL1 vb.) metin olarak korunur.

CREATE TABLE IF NOT EXISTS public.dokumler_sql_mssql_backup AS
SELECT id, sql, now() AS yedek_tarihi
FROM public.dokumler
WHERE false;

INSERT INTO public.dokumler_sql_mssql_backup(id, sql, yedek_tarihi)
SELECT d.id, d.sql, now()
FROM public.dokumler d
WHERE coalesce(d.sql, '') <> ''
  AND NOT EXISTS (
      SELECT 1
      FROM public.dokumler_sql_mssql_backup b
      WHERE b.id = d.id
  );

UPDATE public.dokumler SET sql = '/*PGX*/select S.KOD, S.STOKADI, S.BARKOD, F.FIYAT, F.KUR 
from STOKLAR S left outer join STOKFIYAT F on S.ID=F.STOKID and F.FIYATADI=1
where S.ID=''$StokId$'' and F.ID= ''$StokFiyatId$''' WHERE id = 133;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT FATURATARIH,BASLIK,ADRES,ILCE,IL,VD,VNO, KOD, F.AD,ADET,BIRIM,BIRIMFIYAT,TUTAR,
FATURA_MATRAHI,KDV_TUTARI,FATURA_TUTARI,FB.KUR,( fn_MoneyToText(FATURA_TUTARI,''TL'',''Kr'')) 
 AS YAZIYLATOPLAM FROM FATBASLIK FB inner join FATURA F on FB.ID=F.FATBASID 
WHERE FB.ID = ''$FatBasId$''' WHERE id = 142;
