UPDATE public.dokumler SET sql = '/*PGX*/select T.REHBERID,R.KOD,R.FIRMA,R.KATEGORI,T.ID,SEC,TARIH,MAAS,VERGI,YOL,YEMEK,MESAI,
PRIM ,TOPLAMMAAS, BANKA, KASA, AVANSBANKA, AVANSKASA,T.BELGENO,
ODEBANKA,ODEKASA, KUR, BORCLUBNK, ALACAKLIBNK, BORCLUKASA, EXCELISLENDI, TAHAKKUKISLENDI, BANKAISLENDI, KASAISLENDI, T.DURUM 
from PLANMTABLO T inner join REHBER R on R.ID=T.REHBERID
where TARIH >=''$Tarih1$ 00:00'' and TARIH<''$Tarih2$ 23:59''   
and ODEKASA > 0.1
and SEC=1
order by 1' WHERE id = 185;
