UPDATE public.dokumler SET sql = '/*PGX*/select
    	KOD,FIRMA,GRUP,KATEGORI,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=40 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS ISTEL ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=42 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS CEP ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=43 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS FAX ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=2 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS ADRES ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=6 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS ILCE ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=8 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS IL ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=4 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS PK ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and RB.YER_ID=-1 AND RA.VARSAYILAN=20 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS VERGIDAI ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and RB.YER_ID=-1 AND RA.VARSAYILAN=22 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS VERGINO ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=48 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS WEB ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and   RA.VARSAYILAN=46 INNER JOIN REHBERILETISIM RI  ON RI.REHBERID=R.ID AND RB.YERI=1 AND RI.VARSAYILAN=1 AND RB.YER_ID=RI.ID LIMIT 1 ) AS EMAIL ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI and RB.YER_ID=-1 AND RA.VARSAYILAN=10 LIMIT 1 )
    	
       AS FATURABASLIK from
      	REHBER R
      WHERE ID =''$RehberId$''' WHERE id = 237;
UPDATE public.dokumler SET sql = '/*PGX*/--
 --
-- 
set @IzınId = $IzınId$
select R1.*, PI.*, IZINVEREN= R2.FIRMA, 
BOLUMU = (select BILGI from REHBERBILGI where YERI=3 and  YER_ID =R1.ID and SIRA=12 LIMIT 1 ),  
IZINTURUADI = (select ANAHTAR from REHBERINI where BOLUM = ''CariKart_PerIzinTuru'' and DEGER = PI.IZINTURU LIMIT 1 ),
TC_NO=(SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=3 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=R1.ID AND RB.SIRA=22 LIMIT 1 ),
SICIL_NO=(SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=3 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=R1.ID  AND RA.SIRA=24 LIMIT 1 ),
GOREVI=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-2252 AND DEGER=R1.SEKTOR),
ROL.SUBEID,
DEPARTMAN=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-2251 AND DEGER = ROL.DEPARTMAN AND DIL=-1  LIMIT 1 ),
 GOREV=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-2252 AND DEGER = ROL.GOREVID AND DIL=-1  LIMIT 1 ) ,
 R3.FIRMA,
ISE_GIRIS=(select TARIH from PERS_HAREKET PH where PH.REHBERID = R1.ID and TUR=1 order by 1 desc LIMIT 1 )



from PERSONELIZIN PI
inner join REHBER R1 on PI.REHBERID=R1.ID
inner join REHBER R2 on PI.IZINVERENREHBERID=R2.ID
left outer join ROLLER ROL ON ROL.ID=R1.SINIF
INNER JOIN REHBER R3 ON R3.ID=ROL.SUBEID
where 
R1.ID=$RehberId$
and PI.ID=$IzinId$
' WHERE id = 258;
UPDATE public.dokumler SET sql = '/*PGX*/
		''$KasaTakipId$'' INT,
		@HESAPADI VARCHAR(50),
		@ILKTARIH DATETIME,
		@SONTARIH DATETIME,
		@ACILISTUTARI MONEY,
		@KAPANISTUTARI MONEY,
		@NAKITTAHSILAT MONEY




--ÖNCE AKTİF KASATAKIP kaydından değerleri alalım, 0 gelirse max kayıt alınıp son oturum gösterilebilir.
SELECT @ILKTARIH = ACILISTARIHI, @SONTARIH = coalesce(KAPANISTARIHI,now()), 
		@HESAPID = HESAPID, @ACILISTUTARI = coalesce(ACILISTUTARI,0) , @KAPANISTUTARI = coalesce(KAPANISTUTARI,0)
FROM KASATAKIP WHERE ID = ''$KasaTakipId$''

SELECT @HESAPADI = KASAKODU+''-''+KASAADI FROM KASALAR WHERE ID = @HESAPID

-- O Nakit tahsilatlarını değişkenlere alıyoruz toplam hesaplarında kullanılacak
SELECT 
	@NAKITTAHSILAT =SUM(K.ALACAK)
FROM 
	KASA K INNER JOIN REHBER R
ON
	K.REHBERID = R.ID
WHERE
	K.HESAPID = @HESAPID 
	AND ISLEMTARIHI BETWEEN @ILKTARIH AND @SONTARIH
        AND YERI = 401 AND YERID = ''$KasaTakipId$''



-- değerler alındıktan sonra sorgumuz çalışabilir  
SELECT GRUP, SIRA, ACIKLAMA, SUM(ADET) ADET, SUM(TOPLAM) TOPLAM , 
   BASLANGIC = @ILKTARIH, BITIS = @SONTARIH, HESAPID = @HESAPID, HESAPADI = @HESAPADI , KASATAKIPNO = ''$KasaTakipId$''
 FROM
(
SELECT 

   GRUP = ''Girişler'',
   SIRA = 0,
   ACIKLAMA = ''Kasa Açılış'',
   ADET = 1,
   TOPLAM = @ACILISTUTARI
UNION ALL
SELECT 
	GRUP =''Girişler'',
        SIRA = 1,
	R.FIRMA AS ACIKLAMA,
	ADET=COUNT(*),
	TOPLAM=SUM(K.ALACAK)
FROM 
	KASA K INNER JOIN REHBER R
ON
	K.REHBERID = R.ID
WHERE
	--K.HESAPID = @HESAPID AND 
	ISLEMTARIHI BETWEEN @ILKTARIH AND @SONTARIH
    AND YERI = 401 AND YERID = ''$KasaTakipId$''
GROUP BY 
	R.FIRMA
UNION ALL

SELECT

	GRUP =''Girişler Dağılımı'',
        SIRA =2,
	ACIKLAMA=CASE WHEN K.HESAPTURU=''K'' THEN (SELECT KASAADI  FROM KASALAR K1 WHERE K1.ID=K.HESAPID)
			 WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR K1 WHERE K1.ID=K.HESAPID)
			 WHEN K.HESAPTURU=''P'' THEN (SELECT ADI      FROM POS K1           WHERE K1.ID=K.HESAPID)
			ELSE ''X'' END
			 ,
	ADET=COUNT(*),
	TOPLAM= SUM(K.ALACAK)
FROM 
	KASA K 
WHERE
  ISLEMTARIHI BETWEEN @ILKTARIH AND @SONTARIH	
        AND YERI = 401 AND YERID = ''$KasaTakipId$''
GROUP BY
	HESAPTURU,HESAPID
HAVING SUM(K.BORC)-SUM(K.ALACAK)<>0


UNION ALL


SELECT
	GRUP=''Çıkışlar'',
	SIRA=3,
        ACIKLAMA=CASE WHEN K.HESAPTURU=''K'' THEN (SELECT KASAADI  FROM KASALAR K1       WHERE K1.ID=K.HESAPID)
			 WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR K1 WHERE K1.ID=K.HESAPID)
			 ELSE ''Y '' END,
	ADET=COUNT(*),
	TOPLAM=SUM(K.BORC)

FROM 
	KASA K 

WHERE
	    ISLEMTARIHI BETWEEN @ILKTARIH AND @SONTARIH
        AND YERI = 401 AND YERID = ''$KasaTakipId$'' 

GROUP BY HESAPTURU,HESAPID

UNION ALL
SELECT 

   GRUP = ''Kalan'',
   SIRA = 5,
   ACIKLAMA = ''Gerçekleşen Nakit'',
   ADET = 1,
   TOPLAM = @ACILISTUTARI + @NAKITTAHSILAT
 
UNION ALL
SELECT 
	GRUP = ''Kalan'',
	SIRA = 6,
	ACIKLAMA = ''Eldeki Nakit'',
	ADET = 1,
	TOPLAM = coalesce(@KAPANISTUTARI,0)
	
UNION ALL
SELECT 
	GRUP = ''Kalan'',
	SIRA = 7,
	ACIKLAMA = ''Fark'',
	ADET = 1,
	TOPLAM = @ACILISTUTARI + @NAKITTAHSILAT - coalesce(@KAPANISTUTARI,0)
UNION ALL
SELECT
	GRUP=''Belgeler'',
	SIRA=8 ,
    ACIKLAMA=CASE 
		WHEN TUR=8 THEN  ''Gider Pusulası''
		WHEN TUR=10 THEN ''Alış İrsaliyesi''
		WHEN TUR=11 THEN ''Alış Faturası''
		WHEN TUR=12 THEN ''Alış Fişi''
		WHEN TUR=13 THEN ''Alacak Tahakkuku''
		WHEN TUR=14 THEN ''Satış İrsaliyesi''
		WHEN TUR=15 THEN ''Satış Faturası''
		WHEN TUR=16 THEN ''Satış Fişi''
		WHEN TUR=17 THEN ''Borç Tahakkuku'' 
		ELSE ''XX'' 
	END,

	ADET=COUNT(*),
	TOPLAM=SUM(FATURA_TUTARI)

FROM
	FATBASLIK K 
WHERE
        KASATAKIPID = ''$KasaTakipId$''
GROUP BY K.TUR    
   ) AS X
   
   
GROUP BY GRUP, SIRA, ACIKLAMA   
order BY SIRA
' WHERE id = 294;
