UPDATE public.dokumler SET sql = '/*PGX*/
select @FatBaslikID=ID from FATBASLIK where ANAKAYITID = $FatBasID$ order by ID desc

select  *,
        (select BASLIK from FATBASLIK where ID=@FatBaslikID) AS BASLIK ,
        fn_MoneyToText(BORC-ALACAK,''TL'',''Kr'',0) AS YAZIYLATOPLAM ,
         Dateadd(month,6,ISLEMTARIHI) AS TARIH2 ,
    	(select FIRMA from REHBER where ID=-1) AS FIRMA ,
    	(SELECT BILGI FROM REHBERAYAR RA INNER JOIN REHBERBILGI RB ON RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=-1 AND RA.VARSAYILAN=2 LIMIT 1 ) AS ADRES ,
    	(SELECT BILGI FROM REHBERAYAR RA INNER JOIN REHBERBILGI RB ON RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=-1 AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
    	(SELECT BILGI FROM REHBERAYAR RA INNER JOIN REHBERBILGI RB ON RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=-1 AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
    	(SELECT BILGI FROM REHBERAYAR RA INNER JOIN REHBERBILGI RB ON RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=-1 AND RA.VARSAYILAN=4 LIMIT 1 ) AS PK ,
    	 (SELECT  BELGE FROM IMAJ I WHERE VARSAYILAN=1 AND YERI=11 AND YER_ID=-1  LIMIT 1 ) AS LOGO ,
        (SELECT BILGI FROM REHBERAYAR RA INNER JOIN REHBERBILGI RB ON RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=-1 AND RA.VARSAYILAN=20 LIMIT 1 )
      	||'' / ''||(SELECT BILGI FROM REHBERAYAR RA INNER JOIN REHBERBILGI RB ON RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=-1 AND RA.VARSAYILAN=22 LIMIT 1 )

 AS VERGI from KASA K where K.FATURAID = @FatBaslikID limit 1' WHERE id = 313;
UPDATE public.dokumler SET sql = '/*PGX*/select FB.*,F.*,
fn_MoneyToText(FB.FATURA_TUTARI,''TL'',''Kr'',0)
 AS YAZIYLATOPLAM from
FATBASLIK FB inner join 
FATURA F on FB.ID=F.FATBASID 


where FB.ID = (select ID from FATBASLIK where ANAKAYITID = $FatBasID$ order by ID desc LIMIT 1 )' WHERE id = 314;
UPDATE public.dokumler SET sql = '/*PGX*/




--SELECT TOP 1 @SONKAPANISTARIHI=KAPANISTARIHI FROM KASATAKIP K1 WHERE @KAPANISYAPANPERSONEL=K1.EKLEYEN ORDER BY KAPANISTARIHI

SELECT
* 
FROM 
(
SELECT 
ACILISTARIHI,
coalesce(KAPANISTARIHI,now()) AS KAPANISTARIHI, 
ATUTARI	=(SELECT KAPANISTUTARI FROM KASATAKIP K2 WHERE K2.ID=(KT.ID-1)),  

EKLEYENI       =(SELECT FIRMA FROM REHBER R1 WHERE R1.ID=KT.EKLEYEN),
RAPORNAKIT     =SUM(KT.YAZARKASA_NAKIT),
FIILINAKIT     =SUM(KT.KAPANISTUTARI),
GENTEGRENAKIT  =SUM(KT.SISTEMDEKI_NAKIT),
RAPORKREDI     =SUM(KT.YAZARKASA_KK),
FIILIPOS       =SUM(KT.POS_TOPLAMI),
GENTEGREKREDI  =SUM(SISTEMDEKI_KK),
IADESATISTUT   =(SELECT coalesce(SUM(F.FATURA_TUTARI),0) FROM FATBASLIK F WHERE F.KASATAKIPID=KT.EKLEYEN AND F.TUR IN (8)),
IADECEKIVERILEN=(SELECT coalesce(SUM(K.ALACAK-K.BORC),0) FROM KASA K      WHERE K.YERID=KT.ID AND K.TUR IN (38,39)),
IADECEKIKULL   =(SELECT coalesce(SUM(K.ALACAK-K.BORC),0) FROM KASA K      WHERE K.YERID=KT.ID AND K.TUR IN (28,29))

FROM		KASATAKIP KT

WHERE		KT.ID=''$KasaTakipId$'' 
		AND KT.ACILISTARIHI=''$AcilisTarihi$''

GROUP BY    ACILISTARIHI,KAPANISTARIHI,KT.ID ,KT.EKLEYEN
			

			
        
) AS X

--SELECT * FROM FATBASLIK
' WHERE id = 315;
UPDATE public.dokumler SET sql = '/*PGX*/select R.ID,R.KOD,R.FIRMA,fn_RehberEkBilgisiGetir(1,R.ID,8,0)  AS ILLER ,RSNF.ANAHTAR AS SINIF ,RGRP.ANAHTAR AS GRUP ,
	case when R.GRUP=335 then CariGorev.ANAHTAR  
				 else CariKategori.ANAHTAR 
				 end AS KATEGORI ,
ADSOYAD,R2.FIRMA AS TEMSILCIAD , 
 R.DURUM,R.NOTLAR,
 (SELECT KONUSU FROM AKTIVITELER A WHERE MUSTERIID = R.ID AND 
     1  = CASE WHEN A.TURU = 1 AND A.DURUM = 9 THEN 1  
               WHEN A.TURU <> 1 AND A.DURUM = 8 THEN 1 
               ELSE  0
         END 
         ORDER BY BITISTARIHI DESC
          LIMIT 1 ) AS SONAKTIVITEKONUSU ,
 to_char((SELECT BITISTARIHI FROM AKTIVITELER A WHERE MUSTERIID = R.ID AND 
     1  = CASE WHEN A.TURU = 1 AND A.DURUM = 9 THEN 1  
               WHEN A.TURU <> 1 AND A.DURUM = 8 THEN 1 
               ELSE  0
         END 
         ORDER BY BITISTARIHI DESC
          LIMIT 1 ),''MM/DD/YYYY'') 
 AS SONAKTIVITETARIHI , R.NOTLAR,
       to_char((SELECT FATURATARIH FROM FATBASLIK F WHERE F.REHBERID = R.ID AND 
       F.TUR  in (10,11,12,14,15,16)  ORDER BY FATURATARIH DESC  LIMIT 1 ),''DD/MM/YYYY'') AS SONSATBELGETARIHI ,
     (SELECT FATURA_TUTARI FROM FATBASLIK F WHERE F.REHBERID = R.ID AND 
       F.TUR  in (10,11,12,14,15,16)  ORDER BY FATURATARIH DESC  LIMIT 1 )  
 AS SONSATTUTARI ,R.OZELKOD
from 
    REHBER R 
          left outer join REHBERPERSONEL P on R.ID = P.REHBERID and  
          1 = CASE WHEN  0 = 1 THEN 1
				   WHEN  0 = 0 AND isnull (P.VARSAYILAN,1) = 1 THEN 1 
		       ELSE 0 END 
left outer join REHBER R2 on R2.ID=R.TEMSILCI	 
left outer join GENINI RSNF on RSNF.BOLUM=-2203 and RSNF.DEGER=R.SINIF 
left outer join GENINI RGRP on RGRP.BOLUM=-2202 and RGRP.DEGER=R.GRUP  
left outer join GENINI CariKategori on CariKategori.BOLUM=-2204 and CariKategori.DEGER=R.KATEGORI
left outer join GENINI CariGorev on CariGorev.BOLUM=-2205 and CariGorev.DEGER=R.KATEGORI
--left outer join REHBERBILGI RB on RB.YER_ID=R.ID and RB.YERI=1 and RB.SIRA=56

where --R.ID > 0
 R.ID=''$RehberId$''
 --and  R.FIRMA  LIKE ''ru%'' and R.DURUM=1  
 ORDER BY R.FIRMA limit 200' WHERE id = 336;
UPDATE public.dokumler SET sql = '/*PGX*/select R.* 
from REHBER R 
where 
R.ID=$RehberId$' WHERE id = 452;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
CASE WHEN F.TUR =11 THEN ''Faturaları''
     WHEN F.TUR =10 THEN ''İrsaliyeleri''
     WHEN F.TUR =12 THEN ''Fişleri''
     WHEN F.TUR =13 THEN ''Tahakkukları'' END AS TUR, 
to_char(FATURATARIH,''DD/MM/YYYY'') AS FATURA_TARIHI,
FATURANO,
R.KOD AS HESAP_KODU,
R.FIRMA AS HESAP_ADI,
--F.FATURA_MATRAHI  AS MATRAH,
CASE WHEN KDVDURUM=''Dahil'' THEN FATURA_TUTARI-KDV_TUTARI ELSE FATURA_MATRAHI END  AS MATRAH,   
KDV_TUTARI AS KDV,
FATURA_TUTARI  AS TOPLAM,
KUR   

FROM REHBER R 
INNER JOIN FATBASLIK F ON R.ID=F.REHBERID
WHERE
FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''
and TUR in (10,11,12,13)
order by  FATURATARIH        
---coalesce((SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ),0)' WHERE id = 749;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
CASE WHEN F.TUR =15 THEN ''Fatura''
     WHEN F.TUR =14 THEN ''İrsaliye''
     WHEN F.TUR =16 THEN ''Fiş''
     WHEN F.TUR =17 THEN ''Tahakkuk'' END AS TUR, 
to_char(FATURATARIH,''DD/MM/YYYY'') AS FATURA_TARIHI,
FATURANO,
R.KOD AS HESAP_KODU,
R.FIRMA AS HESAP_ADI,
--F.FATURA_MATRAHI  AS MATRAH,
CASE WHEN KDVDURUM=''Dahil'' THEN FATURA_TUTARI-KDV_TUTARI ELSE FATURA_MATRAHI END  AS MATRAH,   
KDV_TUTARI AS KDV,
FATURA_TUTARI  AS TOPLAM,
KUR   

FROM REHBER R 
INNER JOIN FATBASLIK F ON R.ID=F.REHBERID
WHERE
FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''
and TUR in (15)
order by  FATURATARIH        
---coalesce((SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ),0)' WHERE id = 754;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
CASE WHEN BH.TIPI=0 THEN ''Kurumsal'' ELSE ''Bireysel'' END AS TIPI,         
B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI,HESAPKODU,HESAPNO,HESAPADI,IBAN,KUR,CASE WHEN DURUM=1 THEN ''AKTİF'' ELSE ''PASİF'' END AS DURUM
  FROM BANKAHESAPLAR BH 
  INNER JOIN BANKASUBELER BS ON BH.BANKASUBELERID=BS.ID
  INNER JOIN BANKALAR B ON BS.BANKAKODU=B.BANKAKODU                                       
  where REHBERID=-1
  ORDER BY KUR,HESAPKODU' WHERE id = 758;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT SK.ID, SK.KOD, SK.STOKADI,R1.ANAHTAR AS ANABIRIM ,R2.ANAHTAR AS BIRIM2, SK.BIRIM2MIKTAR, MINSTOK AS MINIMUMSTOK, KDV FROM STOKLAR SK
LEFT OUTER JOIN (SELECT ANAHTAR,DEGER FROM REHBERINI R   WHERE BOLUM=''StokKart_Anabirim'') AS R1 ON R1.DEGER=SK.ANABIRIM 
LEFT OUTER JOIN (SELECT ANAHTAR,DEGER FROM REHBERINI R   WHERE BOLUM=''StokKart_Anabirim'') AS R2 ON R2.DEGER=SK.BIRIM2' WHERE id = 759;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
TARIH,
KOD,
ILGILI,
ISLEMACIKLAMA AS ACIKLAMA,
Dosya,
CASE WHEN YON NOT IN (''Tahsilat'',''Gelir Bütçesi'') THEN TUTAR ELSE 0 END AS ALACAK ,  
CASE WHEN YON IN (''Tahsilat'',''Gelir Bütçesi'') THEN TUTAR ELSE 0 END AS BORC ,  
KUR,YON,ACIKLAMA AS TUR

FROM (


select 
 to_char(to_char(PLANTARIHI,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
R.KOD AS KOD,R.FIRMA AS ILGILI,
 (
	case 
	 when K.DURUM=0 then ''Plan '' 
	 when K.DURUM=1 then ''Plan(Faturalı) '' 
	 else ''Plan '' end)
	 ||cast(case
	 when TUR in (61,62) then BORC
	 when TUR in (71,72) then ALACAK  
	 else 0
	end as varchar)     AS ISLEMACIKLAMA ,
--||RTRIM(coalesce(K.ACIKLAMA,'''')),
''KASA'' AS Dosya , 
TUR,
 case 
	  when TUR = 61 then      BORC
	 when TUR in (71,72) then ALACAK
	  else 0
		end AS TUTAR ,coalesce(K.KUR,''TL'') AS KUR,
case 
		when TUR in (61,62) then ''Tahsilat'' 
		when TUR in (71,72) then ''Ödeme''  
	 end AS YON , 
case 
		when TUR in (61,71) then 1 
		when TUR in (62,72) then 5 
	 end AS SIRA ,  
case 
		when TUR in (61, 71) then ''Açık Hesap'' 
		when TUR = 72 then ''Düzenli Ödeme'' 
	 end 	
 AS ACIKLAMA from 
	KASA K left outer join 
REHBER R on R.ID = K.REHBERID
where 
	PLANTARIHI between ''$Baslangic$ 00:00''  and ''$Bitis$ 23:59''  and 
  K.TUR in (61,62,63,71,72,73)

union all
 ---- Kredi Kartı Bölümü
select 
	
	 to_char(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
	'''' AS KOD,KK.ADI AS ILGILI,
	 SUM(PLKK.TUTAR) AS ISLEMACIKLAMA ,
	''KREDIKARTI'' AS Dosya , 
	351 AS TUR ,
	SUM(PLKK.TUTAR) AS TUTAR ,coalesce(PLKK.KUR,''TL'') AS KUR ,
	''Ödeme'' AS YON , 
	5 AS SIRA , 
	''KK Ödemesi''  	
 AS ACIKLAMA from 
	PLANKREDIKARTI PLKK inner join KREDIKARTI KK  on KK.ID = PLKK.KKID
where 
	TARIH between ''$Baslangic$ 00:00''  and  ''$Bitis$ 23:59''  
group by KK.ID,KK.ADI, TARIH, PLKK.KUR

union all
	
--Çek Bölümü
select   
	 to_char(to_char(VADE,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
	R.KOD AS KOD,R.FIRMA AS ILGILI,
	 ''Çek ''||'' ''
			||cast(TUTAR as varchar)||coalesce(KUR,''TL'')||'' '' 
		
			||coalesce(cast(B.BANKAADI as varchar),'''')||'' ''||coalesce(C.HESAPNO,'''')  
			||'' (Seri No:''||cast(C.SERINO as varchar)||'') '' AS ISLEMACIKLAMA ,
    ''CEKLER'' AS Dosya , 
    TUR,
    TUTAR,KUR,
	case 
		when TUR = 23 then ''Tahsilat'' 
		when TUR = 33 then ''Ödeme'' 
	 end AS YON , 
	 2 AS SIRA ,
	  ''Çek'' 
 AS AIKLAMA from CEKLER C inner join 
	REHBER R on R.ID=C.REHBERID left outer join
	BANKASUBELER BS on BS.ID=C.BANKASUBELERID left outer join 
	BANKALAR B on B.BANKAKODU=BS.BANKAKODU 
where 
	VADE >= ''$Baslangic$ 00:00''  and VADE <= ''$Bitis$ 23:59''	and TUR in (23,33) 
	 
--Senet Bölümü
union all 

select   
	
     to_char(to_char(VADE,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
    R.KOD AS KOD,R.FIRMA AS ILGILI,
     ''Senet ''||cast(TUTAR as varchar)||  coalesce( KUR,''TL'') AS ISLEMACIKLAMA ,
    ''SENETLER'' AS Dosya , 
    TUR,
    TUTAR,KUR,
	case 
		when TUR = 24 then ''Tahsilat'' 
		when TUR = 34 then ''Ödeme'' 
	 end AS YON , 
	 2 AS SIRA ,
	 ''Senet'' 
	 
 AS AIKLAMA from SENETLER C inner join REHBER R on R.ID=C.REHBERID
where 
	VADE >= ''$Baslangic$ 00:00''   and VADE <= ''$Bitis$ 23:59''
	and TUR in (24, 34) 
	
---- Personel Maaş Bölümü
union all 
select   
	 to_char(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
	'''' as kod,'''' as ILGILI,
	 ''Personel ''||cast(sum(TUTAR) as varchar)	|| KUR AS ISLEMACIKLAMA ,
	''PLANKREDI'' AS Dosya , 
	73 AS TUR ,
	sum(TUTAR) AS TUTAR ,KUR,
	''Ödeme'' AS YON ,
	3 AS SIRA , 
	''Personel''
 AS ACIKLAMA from PLANMAAS PM 
where 
	TARIH >= ''$Baslangic$ 00:00''  and TARIH <=  ''$Bitis$ 23:59''
group by TARIH, KUR
	--SELECT * FROM PLANMAAS
----- Personel Avans Tahsilat
union all 
select 
	 to_char(to_char(PLANTARIHI,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
	R.KOD AS KOD,R.FIRMA AS ILGILI,
	 ''Avans Tahsilat Planı '' ||cast(sum(BORC) as varchar)||coalesce(KUR,'''') AS ISLEMACIKLAMA ,
	''KASA'' AS Dosya , 
	TUR,
	 sum(BORC) AS TUTAR , KUR,
	''Avans Tahsilat'' AS YON , 
	1 AS SIRA ,  
	''Avans Tahsilat'' 
		 	
 AS ACIKLAMA from 
	KASA K left outer join REHBER R on R.ID = K.REHBERID
where 
	PLANTARIHI between ''$Baslangic$ 00:00''  and  ''$Bitis$ 23:59''
	and K.TUR = 63
group by PLANTARIHI, KUR, TUR,R.KOD,R.FIRMA

---- Kredi Bölümü
union all 

select   

	 to_char(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'')||'' 00:00'',''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
	KREDIKODU as kod,K.ADI as ILGILI,
	 ''Kredi ''||cast(KO.TAKSIT as varchar)||   K.KUR||'' ''|| coalesce(RTRIM(ACIKLAMA),'''') AS ISLEMACIKLAMA ,
	''PLANKREDI'' AS Dosya , 
	111 AS TUR ,
	KO.TAKSIT AS TUTAR , KO.KUR,
	''Ödeme'' AS YON , 4 AS SIRA ,  ''Kredi''
 AS ACIKLAMA from KREDILER K inner join PLANKREDI KO on K.ID =KO.KREDIID
where 
	TARIH >= ''$Baslangic$ 00:00''  and TARIH <=  ''$Bitis$ 23:59''
	and ODENMIS=0 


--- Bütçe Bölümü

union all 
select   
	
     to_char((cast(B.YIL as varchar)||''-''||cast(B.AY as varchar)||''-''||cast(B.GUN as varchar)||'' 00:00''),''YYYY-MM-DD HH24:MI:SS'')  AS TARIH ,
    M.KOD AS KOD,M.AD AS ILGILI,
     ''Bütçe ''||cast(B.PLANLANAN as varchar)||  coalesce( KUR,''TL'') AS ISLEMACIKLAMA ,
    ''Bütçe'' AS Dosya , 
      case  
		when M.GELIRMI=1 then 301  
		when M.GELIRMI=0 then 311
	end AS TUR ,
    B.PLANLANAN AS TUTAR ,KUR,
	case 
		when M.GELIRMI=1 then ''Gelir Bütçesi'' 
		when M.GELIRMI=0 then ''Masraf Bütçesi'' 
	 end AS YON , 
	 7 AS SIRA ,
	 ''Bütçe'' 
	 
 AS AIKLAMA from 
	BUTCE B inner join 
	MASRAFGELIR M on M.ID=B.MASRAFID
where
B.GOR=1 and 
cast((cast(B.YIL as varchar)||''-''||cast(B.AY as varchar)||''-''||cast(B.GUN as varchar)||'' 00:00'') as timestamp)
 >= ''$Baslangic$ 00:00'' 
and cast((cast(B.YIL as varchar)||''-''||cast(B.AY as varchar)||''-''||cast(B.GUN as varchar)||'' 00:00'') as timestamp)
 <= ''$Bitis$ 23:59''
and cast((cast(B.YIL as varchar)||''-''||cast(B.AY as varchar)||''-''||cast(B.GUN as varchar)||'' 00:00'') as timestamp)
 > now()	 
) AS X
ORDER BY TARIH' WHERE id = 760;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
TARIH AS ISLEM_TARIHI,
VADE AS VADE_TARIHI,
C.ACIKLAMA,
C.KOD AS HESAP_KODU,
H.HESAPADI,
R.KOD AS KOD,
R.FIRMA AS FIRMA,
BK.BANKAADI,
BK.SUBEADI,
BK.SUBEKODU,
G.ANAHTAR AS EVRAK_DURUM,   
C.SERINO,     
coalesce(C.TUTAR,0) AS TUTAR,

C.KUR,
''Çek (Müşteri Çeki)'' AS GRUP          
FROM REHBER R INNER JOIN CEKLER C ON C.REHBERID=R.ID 
LEFT OUTER JOIN ((SELECT B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI,BS.ID FROM BANKALAR B,BANKASUBELER BS WHERE B.BANKAKODU=BS.BANKAKODU)) AS BK ON C.BANKASUBELERID=BK.ID
LEFT OUTER JOIN HESAPPLANI H ON C.KOD=H.HESAPKODU 
LEFT OUTER JOIN GENINI G ON C.DURUM=G.DEGER AND BOLUM=-2601 and DIL=-1
WHERE
C.VADE BETWEEN ''$Baslangic$ 00:00:00'' AND ''$Bitis$ 23:59:00'' AND
C.TUR=23 AND
R.KOD LIKE ''$CariKod$%''

            
ORDER BY GRUP,VADE' WHERE id = 767;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
TARIH AS ISLEM_TARIHI,
VADE AS VADE_TARIHI,
C.ACIKLAMA,
C.KOD AS HESAP_KODU,
H.HESAPADI,
R.KOD AS KOD,
R.FIRMA AS FIRMA,
BK.BANKAADI,
BK.SUBEADI,
BK.SUBEKODU,
G.ANAHTAR AS EVRAK_DURUM,   
C.SERINO,     

CASE WHEN C.TUR =23 THEN (CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_TUTARI ELSE C.TUTAR END) ELSE 0 END  AS TUTAR,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else C.KUR end as KUR,
''Çek (Müşteri Çeki)'' AS GRUP          
FROM REHBER R INNER JOIN CEKLER C ON C.REHBERID=R.ID 
LEFT OUTER JOIN ((SELECT B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI,BS.ID FROM BANKALAR B,BANKASUBELER BS WHERE B.BANKAKODU=BS.BANKAKODU)) AS BK ON C.BANKASUBELERID=BK.ID
LEFT OUTER JOIN HESAPPLANI H ON C.KOD=H.HESAPKODU    
LEFT OUTER JOIN GENINI G ON C.DURUM=G.DEGER AND BOLUM=-2601 and DIL=-1

WHERE
C.VADE >=''$Baslangic$ 00:00:00'' AND
C.VADE <=''$Bitis$ 23:59:00'' AND
C.TUR=23 AND
R.KOD LIKE ''$CariKod$%''

UNION ALL

SELECT
 
TARIH AS ISLEM_TARIHI,
VADE AS VADE_TARIHI,
S.ACIKLAMA,
S.KOD AS HESAP_KODU,
H.HESAPADI,
R.KOD AS KOD,
R.FIRMA AS FIRMA,
'''' AS BANKAADI,
'''' AS SUBEADI,
'''' AS SUBEKODU,
G.ANAHTAR AS EVRAK_DURUM,    
S.SERINO,     
CASE WHEN S.TUR IN (24) THEN (CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_TUTARI ELSE S.TUTAR END) ELSE 0 END  AS TUTAR,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else S.KUR end as KUR,
''Senet (Müşteri Senedi)'' AS GRUP           
FROM REHBER R 
INNER JOIN SENETLER S ON S.REHBERID=R.ID 
LEFT OUTER JOIN HESAPPLANI H ON S.KOD=H.HESAPKODU
LEFT OUTER JOIN GENINI G ON S.DURUM=G.DEGER  AND BOLUM=-2651 and DIL=-1
WHERE
S.VADE >=''$Baslangic$ 00:00:00'' AND
S.VADE <=''$Bitis$ 23:59:00'' AND
S.TUR=24 AND
R.KOD LIKE ''$CariKod$%'' 
            
ORDER BY GRUP,VADE' WHERE id = 768;
