UPDATE public.dokumler SET sql = '/*PGX*/SELECT
CASE WHEN TUR=23 THEN ''Çek (Müşteri Çeki)''
     WHEN TUR=33 THEN ''Çek (Kendi Çekim)'' END AS GRUP, 
TARIH AS ISLEM_TARIHI,
VADE AS VADE_TARIHI,
R.FIRMA AS HESAP_ADI,
BK.BANKAADI,
BK.SUBEADI,
BK.SUBEKODU,
CASE WHEN C.DURUM=4 THEN ''Ciro Edildi''
     WHEN C.DURUM=1 THEN ''Portföyde'' ELSE '''' END AS EVRAK_DURUM,
C.SERINO AS EVRAK_NO,     
TUTAR  AS TUTAR      
FROM REHBER R INNER JOIN CEKLER C ON C.REHBERID=R.ID LEFT OUTER JOIN ((SELECT B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI,BS.ID FROM BANKALAR B,BANKASUBELER BS WHERE B.BANKAKODU=BS.BANKAKODU)) AS BK ON C.BANKASUBELERID=BK.ID
WHERE
C.VADE between ''$Baslangic$ 00:00:00'' AND ''$Bitis$ 23:59:00'' 

UNION

SELECT
CASE WHEN TUR=24 THEN ''Senet (Müşteri Senedi)''
     WHEN TUR=34 THEN ''Senet (Kendi Senedimiz)'' END AS GRUP, 
TARIH AS ISLEM_TARIHI,
VADE AS VADE_TARIHI,
R.FIRMA AS HESAP_ADI,
'''' AS BANKAADI,
'''' AS SUBEADI,
'''' AS SUBEKODU,
CASE WHEN S.DURUM=4 THEN ''Ciro Edildi''
     WHEN S.DURUM=1 THEN ''Portföyde'' ELSE '''' END AS EVRAK_DURUM,
S.SERINO AS EVRAK_NO,     
TUTAR  AS TUTAR      
FROM REHBER R INNER JOIN SENETLER S ON S.REHBERID=R.ID --LEFT OUTER JOIN ((SELECT B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI FROM BANKALAR B,BANKASUBELER BS WHERE B.BANKAKODU=BS.BANKAKODU)) AS BK ON S.BANKASUBELERID=BK.SUBEKODU
WHERE
S.VADE between ''$Baslangic$ 00:00:00'' AND ''$Bitis$ 23:59:00'' 
ORDER BY GRUP,VADE' WHERE id = 770;
