G.ANAHTAR AS EVRAK_DURUM,     
C.SERINO,     
CASE WHEN C.TUR IN (33) THEN (CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_TUTARI ELSE C.TUTAR END) ELSE 0 END  AS TUTAR,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else C.KUR end as KUR,
''Çek (Kendi Çekim)'' AS GRUP          
FROM REHBER R INNER JOIN CEKLER C ON C.REHBERID=R.ID LEFT OUTER JOIN ((SELECT B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI,BS.ID FROM BANKALAR B,BANKASUBELER BS WHERE B.BANKAKODU=BS.BANKAKODU)) AS BK ON C.BANKASUBELERID=BK.ID
LEFT OUTER JOIN HESAPPLANI H ON C.KOD=H.HESAPKODU
--LEFT OUTER JOIN DURUMLAR D ON C.TUR=D.TUR AND C.DURUM=D.DURUM  
LEFT OUTER JOIN GENINI G ON C.DURUM=G.DEGER AND BOLUM=-2601 and DIL=-1 

WHERE
C.VADE >=''$Baslangic$ 00:00:00'' AND
C.VADE <=''$Bitis$ 23:59:00'' AND
C.TUR=33 AND
R.KOD LIKE ''$CariKod$%''

UNION  ALL

SELECT
TARIH AS ISLEM_TARIHI,
VADE AS VADE_TARIHI,
S.ACIKLAMA,
S.KOD AS HESAP_KODU,
H.HESAPADI,
R.KOD AS KOD,
R.FIRMA AS FIRMA,
'''' AS BANKAADI,
'''' AS SUBEADI,
'''' AS SUBEKODU,
G.ANAHTAR AS ACIKLAMA,    
S.SERINO,     
CASE WHEN S.TUR IN (34) THEN (CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_TUTARI ELSE S.TUTAR END) ELSE 0 END  AS TUTAR,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else S.KUR end as KUR,
''Senet (Kendi Senedimiz)'' AS GRUP          
FROM REHBER R INNER JOIN SENETLER S ON S.REHBERID=R.ID --LEFT OUTER JOIN ((SELECT B.BANKAKODU,B.BANKAADI,BS.SUBEKODU,BS.SUBEADI FROM BANKALAR B,BANKASUBELER BS WHERE B.BANKAKODU=BS.BANKAKODU)) AS BK ON S.BANKASUBELERID=BK.SUBEKODU
LEFT OUTER JOIN HESAPPLANI H ON S.KOD=H.HESAPKODU
--LEFT OUTER JOIN DURUMLAR D ON S.TUR=D.TUR AND S.DURUM=D.DURUM
LEFT OUTER JOIN GENINI G ON S.DURUM=G.DEGER  AND BOLUM=-2651 and DIL=-1
WHERE
S.VADE >=''$Baslangic$ 00:00:00'' AND
S.VADE <=''$Bitis$ 23:59:00'' AND
S.TUR=34 AND
R.KOD LIKE ''$CariKod$%'' 
ORDER BY GRUP,VADE' WHERE id = 774;
