UPDATE public.dokumler SET sql = '/*PGX*/IF EXISTS (SELECT 1 FROM tempdb..sysobjects WHERE name LIKE ''gt_CARIEKSTRE_55_%'')
 DROP TABLE gt_CARIEKSTRE_55_
 
 
 
 
 
 
--SELECT 1 FROM tempdb..sysobjects WHERE name LIKE ''gt_CARIEKSTRE_55_%''


 CREATE TABLE gt_CARIEKSTRE_55_(
	SIRANO int IDENTITY(1,1) NOT NULL,
	CEKID int NULL,
	TARIH datetime NULL,
	AKSIYONTARIH datetime NULL,
	NO varchar(20) NULL,
	TUR smallint NULL,
        TURAD varchar(50) NULL,
	REHBERID int NULL,
	KOD varchar(20) NULL,
	AD varchar(50) NULL,
	ACIKLAMA varchar(100) NULL,
	HESAPID int NULL,
	HESAPKODU varchar(50) NULL,
	HESAPADI varchar(100) NULL,
	DURUM smallint NULL,	
	BORC money NULL,
	ALACAK money NULL,
	KUR varchar(6) NULL,
	MASRAFID int NULL,
	MASRAFKOD varchar(50) NULL,
	MASRAFAD varchar(100) NULL,
 	BORCBAKIYE money NULL, 
	ALACAKBAKIYE money NULL  
)
 INSERT INTO gt_CARIEKSTRE_55_
 select CEKID=K.ID, K.PLANTARIHI AS TARIH, K.ISLEMTARIHI AS AKSIYONTARIH,BELGENO AS
 NO,K.TUR, 
 TURAD=KasaTurleri.ANAHTAR , 
 HESAPID as REHBERID ,

KOD=(select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID),
AD=(select KASAADI from KASALAR K2 where K2.ID=K.HESAPID),
 K.ACIKLAMA, REHBERID as HESAPID, R.KOD AS HESAPKODU ,
 R.FIRMA as HESAPADI,K.DURUM,  BORC = ALACAK, ALACAK = BORC, KUR, K.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,BORCBAKIYE=0,ALACAKBAKIYE=0
 From KASA K 
 left outer join REHBER R on R.ID=K.REHBERID  left outer join GENINI KasaTurleri on K.TUR=KasaTurleri.DEGER AND KasaTurleri.DIL=-1 AND BOLUM=''-1005''  left outer join MASRAFGELIR M on M.ID=K.MASRAFID
 Where 
    K.ISLEMTARIHI>=dateadd(year,(select year(''$Baslangic$ 00:00''))-1900,''01-01-1900'') and K.ISLEMTARIHI<=''$Bitis$ 23:59''
 
 and K.HESAPTURU =''K'' and HESAPID=''$Hesapid$''
 order by KUR,TARIH


open CrsKur 
fetch next from CrsKur into @Kur 
while @@FETCH_STATUS = 0 
begin 
	
	
	open Crs   
	fetch next from Crs into @CurID 
	while @@FETCH_STATUS = 0 
	begin 
		select 
			0=case when TUR between 60 and 79 then 0 else 0+ALACAK-BORC end ,
			0=case when TUR between 60 and 79 then 0 else 0+BORC-ALACAK end 
		from gt_CARIEKSTRE_55_ where SIRANO=@CurID 
		update gt_CARIEKSTRE_55_ set 
			ALACAKBAKIYE=case when 0>0 then 0 else 0 end, 
			BORCBAKIYE=case when 0>0 then 0 else 0 end 
		where SIRANO=@CurID 
	fetch next from Crs into @CurID 
	End 
	close Crs 
	deallocate Crs 
fetch next from CrsKur into @Kur 
End 
close CrsKur 
deallocate CrsKur 
select 

	TARIH=''$Baslangic$ 00:00'',AKSIYONTARIH=''$Baslangic$ 00:00'',NO=null,TURAD=''Devir'',MASRAFAD='''',
	ACIKLAMA=''Devir'',HESAPKODU=null,HESAPADI=null,BORC=sum(BORC),ALACAK=sum(ALACAK),KUR, 
    BORCBAKIYE=case when sum(BORC-ALACAK)>0 then sum(BORC-ALACAK) else 0 end,ALACAKBAKIYE=case when sum(ALACAK-BORC)>0 then sum(ALACAK-BORC) else 0 end  
from gt_CARIEKSTRE_55_  
where TUR not between 60 and 79 and TARIH >= dateadd(year,(select year(''$Baslangic$ 00:00''))-1900,''01-01-1900'') and  TARIH < ''$Baslangic$ 00:00'' AND MASRAFAD LIKE ''$MasrafAd$''+''%''
group by KUR  
union all 
SELECT  TARIH, AKSIYONTARIH, NO, TURAD,MASRAFAD,
 ACIKLAMA,HESAPKODU,HESAPADI,BORC,ALACAK,KUR,
 BORCBAKIYE,ALACAKBAKIYE  
FROM gt_CARIEKSTRE_55_ 
where TARIH >= ''$Baslangic$ 00:00'' and  TARIH <= ''$Bitis$ 23:59'' AND MASRAFAD LIKE ''$MasrafAd$''+''%''
ORDER BY 2,KUR
DROP TABLE gt_CARIEKSTRE_55_
 SET FMTONLY OFF
' WHERE id = 780;
