UPDATE public.dokumler SET sql = '/*PGX*/SELECT ID,STOKADI,USTA,
SUM(ADET)
 AS ADET FROM
(

SELECT * FROM (

SELECT 
	S.ID,
	S.STOKADI,
	(coalesce(S.OZELKOD,''TANIMSIZ'')) AS USTA ,
	SD.ADET                                  
	FROM STOKLAR S
		INNER JOIN SIPARISDETAY SD ON S.ID=SD.URUNID
		INNER JOIN SIPARIS SP ON SP.ID=SD.SIPARISID
		INNER JOIN REHBER R ON R.ID=SD.REHBERID
	where 
	SD.EKLEMETARIHI BETWEEN ''$BASLANGIC$ 00:00'' AND ''$BITIS$ 23:59'' 
	GROUP BY S.ID,S.STOKADI,SD.ADET,S.OZELKOD
	
	) AS X
	
	WHERE USTA LIKE ''$OZELKOD$%''
	GROUP BY STOKADI,ID,USTA,ADET

) AS Y GROUP BY ID,STOKADI,USTA ORDER BY USTA' WHERE id = 783;
UPDATE public.dokumler SET sql = '/*PGX*/select L.ID,KOD,ACIKLAMA,D.DEPOADI
from LOKASYON L inner join DEPOLAR D on L.YERI=349 and L.YERID=D.ID
where 
	YERI=349 and
	KOD like ''$KOD$%'' and
	D.DEPOADI like ''$DEPOADI$%''
 
order by KOD' WHERE id = 785;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT    

	KOD,AD||'' Gideri'' AS AD,MERKEZKODU,MERKEZADI,SUM(BORC) AS BORC

FROM (
SELECT
	 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
	 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
	FB.TARIH,
	S.MERKEZKODU,S.MERKEZADI,
	''Alış Fat:''||''//''||to_char(FB.TARIH,''YYYY-MM-DD HH24:MI:SS'')||''//''||R.KOD||''//''||R.FIRMA||''//''||MG.KOD||''//''||MG.AD AS ACIKLAMA ,
	ROUND((F.TUTAR*(1+(F.KDV/100.0))),2)
 AS BORC FROM
FATBASLIK FB 
	INNER JOIN FATURA F ON
		FB.ID=F.FATBASID
	INNER JOIN SRMMERKEZI S ON
		F.MERKEZID=S.ID
	INNER JOIN REHBER R ON
		FB.REHBERID=R.ID
	INNER JOIN MASRAFGELIR MG ON
		MG.ID=F.MASRAFID

WHERE
	FB.TUR=11 AND
	coalesce(F.MERKEZID,'''')<>''''
) AS X

WHERE
	TARIH BETWEEN ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59'' and
	AD LIKE ''$Masraf$%'' and
	MERKEZADI LIKE ''$MerkezAdi$%''
	--TARIH BETWEEN ''2013-07-01 00:00'' and ''2013-07-31 23:59'' 
GROUP BY

KOD,AD,MERKEZKODU,MERKEZADI' WHERE id = 786;
UPDATE public.dokumler SET sql = '/*PGX*/









                            

SELECT @NT = NAKITTOPLAM,@NO=NAKITODEME,@KT=VISATOPLAM,@HT=HEDIYETOPLAM,@IT=IADECEKITOPLAM,@GT = GENELTOPLAM FROM fn_TURTOPLA2  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')
SELECT @FIS=FIS ,@FATURA=FATURA,@IADE=IADE,@TOPLAM=TOPLAM FROM fn_SATISBELGETOPLAM  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')                                                                          

select
         ANAHTAR,TUTAR,AD,SAYI,TURTOPLAMTUTAR,
         @NT AS NAKITTOPLAM,
         @NO AS NAKITODEME,
         @KT AS VISATOPLAM,
         @HT AS HEDIYETOPLAM,
         @IT AS IADECEKITOPLAM,
         @GT AS GENELTOPLAM  ,
         @FIS AS FIS ,
         @FATURA AS FATURA,
         @IADE AS IADE,
         @TOPLAM AS TOPLAM
FROM (

select
CASE WHEN coalesce(ANAHTAR,'''')='''' THEN ''GRUPSUZ'' ELSE ANAHTAR END AS ANAHTAR ,
ROUND((SUM(TUTAR)),2) AS TUTAR,
AD,
SUM(SAYI) AS SAYI,
TURTOPLAMTUTAR
FROM(

select

STOKGRUP.ANAHTAR,
CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*((F.KDV/100.0)+1.0) ELSE F.TUTAR END AS TUTAR ,
CASE WHEN F.TUR =1 THEN S.STOKADI ELSE MG.AD END AS AD ,
F.ADET as SAYI,
A.TUTAR AS TURTOPLAMTUTAR


from
FATBASLIK FB INNER JOIN FATURA F  ON FB.ID=F.FATBASID
	     LEFT OUTER JOIN MASRAFGELIR MG on F.URUNID = MG.ID
	     LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
             LEFT JOIN GENINI STOKGRUP ON STOKGRUP.DEGER=S.GRUBU AND STOKGRUP.BOLUM=-2704 AND STOKGRUP.DIL=-1
	     INNER JOIN fn_STOKTURTOPLAMI (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'') A ON coalesce(A.ANAHTAR,''GRUPSUZ'')=coalesce(STOKGRUP.ANAHTAR,''GRUPSUZ'')
             LEFT JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0

WHERE

            FB.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND     FB.TUR IN (15,16)
    AND  R.FIRMA LIKE ''$Sube$%''
                                                      

 
 ) AS X
 
GROUP  BY 
        ANAHTAR,AD,TURTOPLAMTUTAR
) AS Y 
--GROUP BY ANAHTAR,TUTAR,AD,SAYITURTOPLAMTUTAR
' WHERE id = 789;
UPDATE public.dokumler SET sql = '/*PGX*/

select @StokID = ID ,@StokAdi=STOKADI  from STOKLAR where KOD=''$StokKOD$'' 


select
	@StokAdi AS STOKADI ,TUR,URUNID,GTARIH,GFATNO,GBIRIMTUTAR,CTARIH,CFATNO,CBIRIMTUTAR,ADET,CFATID,CFATBASID,GFATID,GFATBASID,
	 CBIRIMTUTAR-GBIRIMTUTAR AS BIRIMKARLILIK ,
	(CBIRIMTUTAR-GBIRIMTUTAR)*ADET AS KARLILIK ,
	case when GBIRIMTUTAR <> 0.0 then (CBIRIMTUTAR/GBIRIMTUTAR-1.0)*100.0 else null end
 AS YUZDEKARLILIK from(
		select 
			GG.TUR,GG.URUNID,
			GG.GFATNO,CC.CFATNO,
			CFATID,CFATBASID,GFATID,GFATBASID,
			--GMIKTAR,
			--GKUMBASMIKTAR,
			--GKUMBITMIKTAR=GKUMBASMIKTAR+GMIKTAR,	
			--CMIKTAR,
			--CKUMBASMIKTAR,	
			--CKUMBITMIKTAR=CKUMBASMIKTAR+CMIKTAR,
			CBIRIMTUTAR,CTARIH,
			GBIRIMTUTAR,GTARIH,
			--GIRIS=(CKUMBASMIKTAR+CMIKTAR-GKUMBASMIKTAR),
			--CIKIS=(GKUMBASMIKTAR+GMIKTAR-CKUMBASMIKTAR),
			--YARIM=(case when GKUMBASMIKTAR>CKUMBASMIKTAR then GMIKTAR else CMIKTAR end),
			case 
				when ((CKUMBASMIKTAR+CMIKTAR-GKUMBASMIKTAR)<=(GKUMBASMIKTAR+GMIKTAR-CKUMBASMIKTAR))and((CKUMBASMIKTAR+CMIKTAR-GKUMBASMIKTAR)<=(case when GKUMBASMIKTAR>CKUMBASMIKTAR then GMIKTAR else CMIKTAR end)) then (CKUMBASMIKTAR+CMIKTAR-GKUMBASMIKTAR)
				when ((GKUMBASMIKTAR+GMIKTAR-CKUMBASMIKTAR)<=(CKUMBASMIKTAR+CMIKTAR-GKUMBASMIKTAR))and((GKUMBASMIKTAR+GMIKTAR-CKUMBASMIKTAR)<=(case when GKUMBASMIKTAR>CKUMBASMIKTAR then GMIKTAR else CMIKTAR end)) then (GKUMBASMIKTAR+GMIKTAR-CKUMBASMIKTAR)
				when ((case when GKUMBASMIKTAR>CKUMBASMIKTAR then GMIKTAR else CMIKTAR end)<=(CKUMBASMIKTAR+CMIKTAR-GKUMBASMIKTAR))and((case when GKUMBASMIKTAR>CKUMBASMIKTAR then GMIKTAR else CMIKTAR end)<=(GKUMBASMIKTAR+GMIKTAR-CKUMBASMIKTAR)) then (case when GKUMBASMIKTAR>CKUMBASMIKTAR then GMIKTAR else CMIKTAR end)
				else 0 end
		 AS ADET from
				(select 
					FG.ID AS GFATID ,
					FBG.ID AS GFATBASID , 
					FG.TUR AS TUR ,
					FBG.FATURANO AS GFATNO ,
					FG.URUNID AS URUNID ,
					FG.MIKTAR AS GMIKTAR ,
					coalesce((select sum(MIKTAR) from FATURA FK inner join FATBASLIK FBK on FK.FATBASID=FBK.ID where FBK.TUR<>20 and FK.TUR=1 and FK.URUNID=@StokID and ((coalesce(FBK.GIRISDEPO,0) <> 0 and FK.MIKTAR>0.0)or(coalesce(FBK.CIKISDEPO,0) <> 0 and FK.MIKTAR<0.0)) and FK.STOKDURUMDEGIS = 1 and dateadd(MILLISECOND,FK.ID,FBK.FATURATARIH)<dateadd(MILLISECOND,FG.ID,FBG.FATURATARIH)),0.0) AS GKUMBASMIKTAR ,
					FG.TUTAR/FG.MIKTAR AS GBIRIMTUTAR ,
					dateadd(MILLISECOND,FG.ID,FBG.FATURATARIH)
				 AS GTARIH from 
					FATURA FG inner join FATBASLIK FBG on FG.FATBASID=FBG.ID
				where
					FBG.TUR<>20 and 
					FG.TUR=1 and 
					FG.URUNID=@StokID and 
					((coalesce(FBG.GIRISDEPO,0) <> 0 and FG.MIKTAR>0.0)or(coalesce(FBG.CIKISDEPO,0) <> 0 and FG.MIKTAR<0.0)) and 
					FG.STOKDURUMDEGIS = 1
				) as GG
			join
				(select
					FC.ID AS CFATID ,
					FBC.ID AS CFATBASID ,
					FC.TUR AS TUR ,
					FBC.FATURANO AS CFATNO ,
					FC.URUNID AS URUNID ,
					FC.MIKTAR AS CMIKTAR ,
					coalesce((select sum(MIKTAR) from FATURA FK inner join FATBASLIK FBK on FK.FATBASID=FBK.ID where FBK.TUR<>20 and FK.TUR=1 and FK.URUNID=@StokID and ((coalesce(FBK.CIKISDEPO,0) <> 0 and FK.MIKTAR>0.0)or(coalesce(FBK.GIRISDEPO,0) <> 0 and FK.MIKTAR<0.0)) and FK.STOKDURUMDEGIS = 1 and dateadd(MILLISECOND,FK.ID,FBK.FATURATARIH)<dateadd(MILLISECOND,FC.ID,FBC.FATURATARIH)),0.0) AS CKUMBASMIKTAR ,
					FC.TUTAR/FC.MIKTAR AS CBIRIMTUTAR ,
					dateadd(MILLISECOND,FC.ID,FBC.FATURATARIH)
				 AS CTARIH from 
					FATURA FC inner join FATBASLIK FBC on FC.FATBASID=FBC.ID
				where
					FBC.TUR<>20 and 
					FC.TUR=1 and 
					FC.URUNID=@StokID and 
					((coalesce(FBC.CIKISDEPO,0) <> 0 and FC.MIKTAR>0.0)or(coalesce(FBC.GIRISDEPO,0) <> 0 and FC.MIKTAR<0.0)) and 
					FC.STOKDURUMDEGIS = 1
				) as CC
			on 
				GG.TUR=CC.TUR and
				GG.URUNID=CC.URUNID and 
				GKUMBASMIKTAR<CKUMBASMIKTAR+CMIKTAR and
				CKUMBASMIKTAR<GKUMBASMIKTAR+GMIKTAR
)as FIFO
' WHERE id = 809;
UPDATE public.dokumler SET sql = '/*PGX*/select R1.*, PI.*,  R2.FIRMA AS IZINVEREN , 
 (select R.ROL from PERS_HAREKET PH inner join ROLLER R on R.ID=PH.POZISYON order by TARIH desc LIMIT 1 ) AS BOLUMU ,  
 (select ANAHTAR from GENINI where BOLUM = -2208 and DEGER = PI.IZINTURU LIMIT 1 )

 AS IZINTURUADI from PERSONELIZIN PI
inner join REHBER R1 on PI.REHBERID=R1.ID
inner join REHBER R2 on PI.IZINVERENREHBERID=R2.ID
where 
R1.ID=$RehberId$
and PI.ID=$IzinId$' WHERE id = 810;
UPDATE public.dokumler SET sql = '/*PGX*/








;WITH CTE AS (
SELECT 
Num=0,
STOKADI=(
SELECT 
S.STOKADI
FROM 
	STOKBARKOD SB INNER JOIN STOKLAR S ON SB.STOKID=S.ID 

WHERE S.KOD=''$UrunKodu$'' AND BARKOD LIKE ''%$%''
),
URUNADET=''$UrunAdet$'',
BARKOD=(
SELECT BARKODU=BARKODU+Ean_chkdigit (BARKODU)
FROM(
SELECT 

BARKODU=CASE WHEN length(''$UrunAdet$'')=1 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''0000''+cast(''$UrunAdet$'' as varchar)
		     WHEN length(''$UrunAdet$'')=2 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''000''+cast(''$UrunAdet$'' as varchar) 
			 WHEN length(''$UrunAdet$'')=3 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''00''+cast(''$UrunAdet$'' as varchar) 
			 WHEN length(''$UrunAdet$'')=4 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''0''+cast(''$UrunAdet$'' as varchar)  

		ELSE SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+cast(''$UrunAdet$'' as varchar)  END

FROM 
	STOKBARKOD SB INNER JOIN STOKLAR S ON SB.STOKID=S.ID 

WHERE S.KOD=''$UrunKodu$'' AND BARKOD LIKE ''%$%''
) AS X
)
UNION ALL
SELECT 
Num + 1,
STOKADI=(
SELECT 
S.STOKADI
FROM 
	STOKBARKOD SB INNER JOIN STOKLAR S ON SB.STOKID=S.ID 

WHERE S.KOD=''$UrunKodu$'' AND BARKOD LIKE ''%$%''
),
URUNADET=''$UrunAdet$'',
BARKOD=(
SELECT BARKODU=BARKODU+Ean_chkdigit (BARKODU)
FROM(

SELECT 

BARKODU=CASE WHEN length(''$UrunAdet$'')=1 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''0000''+cast(''$UrunAdet$'' as varchar)
		     WHEN length(''$UrunAdet$'')=2 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''000''+cast(''$UrunAdet$'' as varchar) 
			 WHEN length(''$UrunAdet$'')=3 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''00''+cast(''$UrunAdet$'' as varchar) 
			 WHEN length(''$UrunAdet$'')=4 THEN SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+''0''+cast(''$UrunAdet$'' as varchar)  

		ELSE SUBSTRING(SB.BARKOD,0,CHARINDEX(''$'',SB.BARKOD))+cast(''$UrunAdet$'' as varchar)  END

FROM 
	STOKBARKOD SB INNER JOIN STOKLAR S ON SB.STOKID=S.ID 

WHERE S.KOD=''$UrunKodu$'' AND BARKOD LIKE ''%$%'') AS X )

FROM CTE WHERE Num < ''$EtiketAdedi$''
)

SELECT STOKADI,URUNADET,BARKOD FROM CTE   WHERE coalesce(STOKADI,'''')<>''''
' WHERE id = 812;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
R.FIRMA,
EK.KOD,
EK.AD AS EKIPMAN,
ER.SERINO,
ER.ACIKLAMA,
L.ACIKLAMA AS LOKASYON,
RP.ADSOYAD AS ILGILI,
Marka                =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Marka'' AND RB.YER_ID=ER.ID) ,
Teknoloji            =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Teknoloji'' AND RB.YER_ID=ER.ID) ,
Kapasite             =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Kapasite'' AND RB.YER_ID=ER.ID) ,
Laser Tipi           =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Laser Tipi'' AND RB.YER_ID=ER.ID) ,
Çalışma Alanı        =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Çalışma Alanı'' AND RB.YER_ID=ER.ID) ,
İlave Özellik        =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''İlave Özellik'' AND RB.YER_ID=ER.ID) ,
Yatırım Şekli        =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Yatırım Şekli'' AND RB.YER_ID=ER.ID) ,
Yatırım Yılı         =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Yatırım Yılı'' AND RB.YER_ID=ER.ID) ,
Bakım Anlş. Bitiş Tarihi=(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Bakım Anş. Bitiş Tarihi'' AND RB.YER_ID=ER.ID) ,
Özel Kod 1           =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Özel Kod 1'' AND RB.YER_ID=ER.ID) ,
Özel Kod 2           =(select BILGI from  REHBERBILGI RB WHERE RB.YERI=181 AND ETIKET=''Özel Kod 2'' AND RB.YER_ID=ER.ID)  
FROM 

EKIPMANREHBER ER
	LEFT OUTER JOIN REHBER R ON
		ER.REHBERID=R.ID
	LEFT OUTER JOIN EKIPMANLAR EK ON
		ER.EKIPMANID=EK.ID
	LEFT OUTER JOIN LOKASYON L ON
		ER.LOKASYONID=L.ID
	LEFT OUTER JOIN REHBERPERSONEL RP ON
		ER.MUS_ILGILI=RP.ID
WHERE
	R.FIRMA LIKE ''$Firma$%'' AND
	EK.AD LIKE ''$Ekipman$%''
 
 order by R.FIRMA,EK.KOD,EK.AD' WHERE id = 813;
UPDATE public.dokumler SET sql = '/*PGX*/select
	SUBE,KOD,DEPOADI,STOKADI,BIRIM,GIREN,CIKAN,KALAN,Max.Stok,Min.Stok,Kri.Stok,Min.Fark,
	Sipariş Giriş,Sipariş Çıkış,Sipariş Kalan,
	Tavsiye=Min.Fark-Sipariş Kalan
FROM(
	
select 
	coalesce(R.FIRMA,'''') AS SUBE,S.KOD,D.DEPOADI,S.STOKADI,
	(SELECT ANAHTAR FROM GENINI G WHERE G.DEGER=S.ANABIRIM AND G.DIL=''-1'' AND BOLUM=''-2702'') AS BIRIM ,
	coalesce(SD.GIREN,0) AS GIREN,
	coalesce(SD.CIKAN,0) AS CIKAN,
	coalesce(SD.KALAN,0) AS KALAN,
	coalesce(SS.MAKSIMUM,0) AS Max.Stok,
	coalesce(SS.MINIMUM,0)  AS Min.Stok,
	coalesce(SS.KRITIK,0)   AS Kri.Stok,
	Min.Fark=coalesce(SS.KRITIK,0)-coalesce(SS.MINIMUM,0),
	Sipariş Giriş=(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Girecek'' ),
	Sipariş Çıkış=(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Çıkacak'' ),
	Sipariş Kalan=(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Girecek'' )-(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Çıkacak'' )
	 
from 
	STOKLAR S 
	
		LEFT JOIN STOKDURUM SD  ON 
			S.ID=SD.STOKID
		INNER JOIN DEPOLAR D ON 
			SD.DEPOID=D.ID
		LEFT JOIN STOKSEVIYE SS ON
			SS.DEPOID=SD.DEPOID AND SS.STOKID=S.ID
		LEFT JOIN REHBER R ON 
			R.ID=SD.SUBEID AND R.ID<0
			
) AS X

WHERE
	coalesce(SUBE,'''') LIKE ''$Subeler$%'' AND
	coalesce(DEPOADI,'''') LIKE ''$DepoAdi$%'' AND
	coalesce(KOD,'''') LIKE ''$StokKod$%'' AND
	coalesce(STOKADI,'''') LIKE ''$StokAdi$%''
 
 order by SUBE,DEPOADI,KOD' WHERE id = 815;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT  * FROM (
SELECT
	 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
	 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
	FB.TARIH,
	S.MERKEZKODU,S.MERKEZADI,
	''Alış Fat:''||''//''||to_char(FB.TARIH,''YYYY-MM-DD HH24:MI:SS'')||''//''||R.KOD||''//''||R.FIRMA||''//''||MG.KOD||''//''||MG.AD AS ACIKLAMA ,
	ROUND((F.TUTAR*(1+(F.KDV/100.0))),2)
 AS BORC FROM
FATBASLIK FB 
	INNER JOIN FATURA F ON
		FB.ID=F.FATBASID
	INNER JOIN SRMMERKEZI S ON
		F.MERKEZID=S.ID
	INNER JOIN REHBER R ON
		FB.REHBERID=R.ID
	INNER JOIN MASRAFGELIR MG ON
		MG.ID=F.MASRAFID

WHERE
	FB.TUR=11 AND
	coalesce(F.MERKEZID,'''')<>''''
) AS X

WHERE
	TARIH BETWEEN ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59'' and
	AD LIKE ''$Masraf$%'' and
	MERKEZADI LIKE ''$MerkezAdi$%''
ORDER BY MERKEZKODU,AD,TARIH' WHERE id = 817;
UPDATE public.dokumler SET sql = '/*PGX*/

SELECT @StartDate = ''$Baslangic$ 00:00'',
       @EndDate   = ''$Bitis$ 23:59''

SELECT
        R.ID,
	R.FIRMA, 
	 DATEADD(DAY, DATEDIFF(DAY, 0, DATEADD(DAY, v.number, @StartDate)), 0) AS GUN ,
	 DATENAME(WEEKDAY,(DATEADD(DAY, DATEDIFF(DAY, 0, DATEADD(DAY, v.number, @StartDate)), 0))) AS GUNAD ,
	0 AS VARDIYAGUN ,
	CAST(NULL AS DATETIME) AS VARDIYAGIRIS ,
	CAST(NULL AS DATETIME) AS VARDIYACIKIS ,
	CAST(NULL AS DATETIME) AS GIRISSAAT ,
	CAST(NULL AS DATETIME) AS CIKISSAAT ,
	0 AS GELDI ,
	0 AS GELMEDI ,
	0 AS ERKENCIKTI ,
	0 AS GECGELDI ,
	0
	
	

INTO #Gunler
 AS CIKISYOK FROM master.spt_values v cross join REHBER R 
WHERE v.type = ''P''
	 AND DATEDIFF(DAY, @StartDate, @EndDate) >= v.number
	 AND KOD LIKE ''335%''
	
UPDATE #Gunler SET GUNAD=case 
							when GUNAD=''Sunday''		then ''Pazar''
							when GUNAD=''Monday''		then ''Pazartesi''
							when GUNAD=''Tuesday''	then ''Salı''
							when GUNAD=''Wednesday''	then ''Çarşamba''
							when GUNAD=''Thursday ''	then ''Perşembe'' 
							when GUNAD=''Friday''		then ''Cuma''
							when GUNAD=''Saturday''	then ''Cumartesi''
						else '''' end


UPDATE 	#Gunler SET VARDIYAGUN=1		FROM  #Gunler G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI
UPDATE 	#Gunler SET VARDIYAGIRIS=cast((cast(GIRIS as varchar)) as timestamp)	FROM  #Gunler G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI
UPDATE 	#Gunler SET VARDIYACIKIS=cast((cast(CIKIS as varchar)) as timestamp)	FROM  #Gunler G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI
UPDATE 	#Gunler SET GIRISSAAT   =cast((cast(GIRIS as varchar)) as timestamp)	FROM  #Gunler G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#Gunler SET CIKISSAAT   =cast((cast(CIKIS as varchar)) as timestamp)	FROM  #Gunler G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#Gunler SET GELDI=1				FROM  #Gunler G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#Gunler SET GELMEDI=1			FROM  #Gunler G WHERE NOT EXISTS (SELECT P.REHBERID FROM PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp))
UPDATE 	#Gunler SET CIKISYOK=1			FROM  #Gunler G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) AND coalesce(CIKIS,'''')=''''
UPDATE  #Gunler SET ERKENCIKTI=1		FROM  #Gunler G WHERE VARDIYACIKIS>CIKISSAAT
UPDATE  #Gunler SET GECGELDI=1		    FROM  #Gunler G WHERE VARDIYAGIRIS<GIRISSAAT
	
--SELECT * FROM #Gunler	 WHERE ID IN (6009,6010)
SELECT  ID,FIRMA AS AD,
		SUM(CIKISYOK) AS CIKISYOK ,
		SUM(VARDIYAGUN)-SUM(GELDI) AS GELMEDIGIGUN ,
		SUM(ERKENCIKTI) AS ERKENCIKTI ,
		SUM(GECGELDI)
 AS GECGELDI FROM #Gunler
WHERE ID IN (6009,6010)
GROUP BY ID,FIRMA
ORDER BY FIRMA

DROP TABLE #Gunler
' WHERE id = 830;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	TUR,AD,ISLEMTARIHI,BELGENO,ACIKLAMASI,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN GONDERENKOD WHEN GONDERENBORC>0 AND REHBERID<>0 THEN GONDERENKOD WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN ALANCARIKOD ELSE ALANKOD END AS GONDERENKOD ,
	CASE WHEN GONDERENBORC>0   AND REHBERID=0 THEN GONDERENAD  WHEN GONDERENBORC>0 AND REHBERID<>0 THEN GONDERENAD  WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN ALANCARIAD  ELSE ALANAD END AS GONDERENAD ,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN ALANKOD     WHEN GONDERENBORC>0 AND REHBERID<>0 THEN ALANCARIKOD WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN GONDERENKOD ELSE GONDERENKOD END AS ALANKOD ,
	CASE WHEN GONDERENBORC>0   AND REHBERID=0 THEN ALANAD      WHEN GONDERENBORC>0 AND REHBERID<>0 THEN ALANCARIAD  WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN GONDERENAD  ELSE GONDERENAD END AS ALANAD ,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN ABS(ALANBORC-ALANALACAK) WHEN GONDERENBORC>0 AND REHBERID<>0 AND coalesce(TURU,'''')='''' THEN ABS(GONDERENBORC-GOND then K.ACIKLAMA else '''' end,
TURU='''', 
GONDERENKOD=case when K.HESAPTURU=''K'' then (select KS.KASAKODU  from KASALAR KS where KS.ID=K.HESAPID)
			     when K.HESAPTURU=''B'' then (select BS.HESAPKODU from BANKAHESAPLAR BS where BS.ID=K.HESAPID)
			     when K.HESAPTURU=''V'' then (select KK.KODU from KREDIKARTI KK where KK.ID=K.HESAPID)
			     when K.HESAPTURU=''P'' then (select P.KODU from POS P where P.ID=K.HESAPID)

			end,
GONDERENAD=case when K.HESAPTURU=''K'' then (select KS.KASAADI from KASALAR KS where KS.ID=K.HESAPID)
				when K.HESAPTURU=''B'' then (select BS.HESAPADI from BANKAHESAPLAR BS where BS.ID=K.HESAPID)
				when K.HESAPTURU=''V'' then (select KK.ADI from KREDIKARTI KK where KK.ID=K.HESAPID)
				when K.HESAPTURU=''P'' then (select P.ADI from POS P where P.ID=K.HESAPID)

			end,

ALANKOD=(select case when K2.HESAPTURU=''K'' AND REHBERID=0 then (select KS.KASAKODU  from KASALAR KS where KS.ID=K2.HESAPID ) 
					 when K2.HESAPTURU=''B'' then (select BS.HESAPKODU from BANKAHESAPLAR BS where BS.ID=K2.HESAPID )
					 when K2.HESAPTURU=''V'' then (select KK.KODU from KREDIKARTI KK where KK.ID=K2.HESAPID)
					 when K2.HESAPTURU=''P'' then (select P.KODU from POS P where P.ID=K2.HESAPID)
						END
		  FROM 
			KASA K2 
		  WHERE 
			K2.GERIDONUSID=K.ID),
ALANAD=(select case when K2.HESAPTURU=''K'' AND REHBERID=0 then (select KS.KASAADI  from KASALAR KS where KS.ID=K2.HESAPID ) 
					when K2.HESAPTURU=''B'' AND REHBERID=0 then (select BS.HESAPADI from BANKAHESAPLAR BS where BS.ID=K2.HESAPID )
					when K2.HESAPTURU=''V'' AND REHBERID=0 then (select KK.ADI from KREDIKARTI KK where KK.ID=K2.HESAPID)
					when K2.HESAPTURU=''P'' AND REHBERID=0 then (select P.ADI from POS P where P.ID=K2.HESAPID)
						END
					FROM KASA K2 WHERE K2.GERIDONUSID=K.ID),

ALANCARIKOD		= (SELECT KOD FROM REHBER R WHERE R.ID=K.REHBERID),
ALANCARIAD		= (SELECT FIRMA FROM REHBER R WHERE R.ID=K.REHBERID),
GONDERENBORC	= BORC,
GONDERENALACAK	= ALACAK,
GONDERENKUR		= KUR,

ALANBORC  =(SELECT BORC FROM KASA K1 WHERE K1.GERIDONUom REHBER R where R.ID=C.REHBERID)
					   when C.TUR=33 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
				  --SELECT * FROM HESAPPLANI
	GONDERENAD	= case when C.TUR=23 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=33 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
	ALANKOD		= case when C.TUR=33 then (select KOD from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=23 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
	ALANAD		= case when C.TUR=33 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=23 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
				  
	ALANCARIKOD		= case when C.TUR=33 then (select KOD from REHBER R where R.ID=C.REHBERID)
					       when C.TUR=23 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
	ALANCARIAD		= case when C.TUR=33 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					       when C.TUR=23 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
	GONDERENBORC	= TUTAR,
	GONDERENALACAK	= TUTAR,
	GONDERENKUR	= KUR,

	ALANBORC  = TUTAR,
	ALANALACAK= TUTAR,
	ALANKUR   = KUR,

	ALANCARIBORC  = TUTAR,
	ALANCARIALACAK= TUTAR,
	ALANCARIKUR   = KUR
from
CEKLER C
	inner join ISLEMTURLERI I on C.TUR=I.TUR
	INNER JOIN BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
    INNER JOIN BANKALAR B ON B.BANKAKODU = BS.BANKAKODU

--WHERE C.ID=104 AND C.TUR = 33
where C.ID = ''$ID$'' AND C.TUR = ''$TUR$''


) AS X AS GONDERENTUTAR ' WHERE id = 838;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	TUR,AD,ISLEMTARIHI,BELGENO,ACIKLAMASI,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN GONDERENKOD WHEN GONDERENBORC>0 AND REHBERID<>0 THEN GONDERENKOD WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN ALANCARIKOD ELSE ALANKOD END AS GONDERENKOD ,
	CASE WHEN GONDERENBORC>0   AND REHBERID=0 THEN GONDERENAD  WHEN GONDERENBORC>0 AND REHBERID<>0 THEN GONDERENAD  WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN ALANCARIAD  ELSE ALANAD END AS GONDERENAD ,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN ALANKOD     WHEN GONDERENBORC>0 AND REHBERID<>0 THEN ALANCARIKOD WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN GONDERENKOD ELSE GONDERENKOD END AS ALANKOD ,
	CASE WHEN GONDERENBORC>0   AND REHBERID=0 THEN ALANAD      WHEN GONDERENBORC>0 AND REHBERID<>0 THEN ALANCARIAD  WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN GONDERENAD  ELSE GONDERENAD END AS ALANAD ,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN ABS(ALANBORC-ALANALACAK) WHEN GONDERENBORC>0 AND REHBERID<>0 AND coalesce(TURU,'''')='''' THEN ABS(GONDERENBORC-GONDERENALACAK) WHEN GONDERENALACAK>0 AND REHBERID<>0 AND coalesce(TURU,'''')='''' THEN ABS(GONDERENBORC-GONDERENALACAK) WHEN GONDERENALACAK>0 AND REHBERID<>0 AND coalesce(TURU,'''')=''ÇEKLER'' THEN GONDERENBORC ELSE ABS(GONDERENBORC-GONDERENALACAK) END AS GONDERENTUTAR ,
	CASE WHEN GONDERENALACAK>0 AND REHBERID=0 THEN ALANKUR     WHEN GONDERENBORC>0 AND REHBERID<>0 THEN GONDERENKUR WHEN GONDERENALACAK>0 AND REHBERID<>0 THEN ALANCARIKUR ELSE GONDERENKUR END AS GONDERENKUR ,
	CASE WHEN GONDERENBORC>0   AND REHBERID=0 THEN ABS(ALANBORC-ALANALACAK) WHEN GONDERENBORC>0 AND REHBERID<>0 AND coalesce(TURU,'''')='''' THEN ABS(ALANCARIBORC-ALANCARIALACAK) WHEN GONDERENBORC>0 AND REHBERID<>0 AND coalesce(TURU,'''')=''ÇEKLER'' THEN GONDERENALACAK ELSE ABS(GONDERENBORC-GONDERENALACAK) END AS ALANTUTAR ,
	CASE WHEN GONDERENBORC>0   AND REHBERID=0 THEN ALANKUR     WHEN GONDERENBORC>0 AND REHBERID<>0 THEN ALANCARIKUR ELSE GONDERENKUR END

 AS ALANKUR FROM(
select 
K.TUR,I.AD,K.ISLEMTARIHI,K.BELGENO,
K.REHBERID,
case when K.HESAPTURU IN (''P'',''V'') AND KREDIID>1 then K.ACIKLAMA else '''' end AS ACIKLAMASI ,
'''' AS TURU , 
case when K.HESAPTURU=''K'' then (select KS.KASAKODU  from KASALAR KS where KS.ID=K.HESAPID)
			     when K.HESAPTURU=''B'' then (select BS.HESAPKODU from BANKAHESAPLAR BS where BS.ID=K.HESAPID)
			     when K.HESAPTURU=''V'' then (select KK.KODU from KREDIKARTI KK where KK.ID=K.HESAPID)
			     when K.HESAPTURU=''P'' then (select P.KODU from POS P where P.ID=K.HESAPID)

			end AS GONDERENKOD ,
case when K.HESAPTURU=''K'' then (select KS.KASAADI from KASALAR KS where KS.ID=K.HESAPID)
				when K.HESAPTURU=''B'' then (select BS.HESAPADI from BANKAHESAPLAR BS where BS.ID=K.HESAPID)
				when K.HESAPTURU=''V'' then (select KK.ADI from KREDIKARTI KK where KK.ID=K.HESAPID)
				when K.HESAPTURU=''P'' then (select P.ADI from POS P where P.ID=K.HESAPID)

			end AS GONDERENAD ,

(select case when K2.HESAPTURU=''K'' AND REHBERID=0 then (select KS.KASAKODU  from KASALAR KS where KS.ID=K2.HESAPID ) 
					 when K2.HESAPTURU=''B'' then (select BS.HESAPKODU from BANKAHESAPLAR BS where BS.ID=K2.HESAPID )
					 when K2.HESAPTURU=''V'' then (select KK.KODU from KREDIKARTI KK where KK.ID=K2.HESAPID)
					 when K2.HESAPTURU=''P'' then (select P.KODU from POS P where P.ID=K2.HESAPID)
						END
		  FROM 
			KASA K2 
		  WHERE 
			K2.GERIDONUSID=K.ID) AS ALANKOD ,
(select case when K2.HESAPTURU=''K'' AND REHBERID=0 then (select KS.KASAADI  from KASALAR KS where KS.ID=K2.HESAPID ) 
					when K2.HESAPTURU=''B'' AND REHBERID=0 then (select BS.HESAPADI from BANKAHESAPLAR BS where BS.ID=K2.HESAPID )
					when K2.HESAPTURU=''V'' AND REHBERID=0 then (select KK.ADI from KREDIKARTI KK where KK.ID=K2.HESAPID)
					when K2.HESAPTURU=''P'' AND REHBERID=0 then (select P.ADI from POS P where P.ID=K2.HESAPID)
						END
					FROM KASA K2 WHERE K2.GERIDONUSID=K.ID) AS ALANAD ,

 (SELECT KOD FROM REHBER R WHERE R.ID=K.REHBERID) AS ALANCARIKOD ,
 (SELECT FIRMA FROM REHBER R WHERE R.ID=K.REHBERID) AS ALANCARIAD ,
 BORC AS GONDERENBORC ,
 ALACAK AS GONDERENALACAK ,
 KUR AS GONDERENKUR ,

(SELECT BORC FROM KASA K1 WHERE K1.GERIDONUSID=K.ID) AS ALANBORC ,
(SELECT ALACAK FROM KASA K1 WHERE K1.GERIDONUSID=K.ID) AS ALANALACAK ,
(SELECT KUR FROM KASA K1 WHERE K1.GERIDONUSID=K.ID) AS ALANKUR ,

(SELECT BORC FROM KASA K1 WHERE K1.ID=K.ID) AS ALANCARIBORC ,
(SELECT ALACAK FROM KASA K1 WHERE K1.ID=K.ID) AS ALANCARIALACAK ,
(SELECT KUR FROM KASA K1 WHERE K1.ID=K.ID)

 AS ALANCARIKUR from 
	KASA K
		inner join ISLEMTURLERI I on K.TUR=I.TUR
		

where K.ID = ''$CEKID$'' AND K.TUR = ''$TUR$''
--where K.ID = 104 AND K.TUR=33

UNION ALL


select 
	C.TUR,I.AD,C.TARIH,C.MAKBUZNO AS BELGENO ,C.REHBERID,
	case when C.TUR=23 then LTRIM(RTRIM(coalesce(C.ACIKLAMA,''''))||'' ''||RTRIM(B.BANKAADI)||''''||RTRIM(BS.SUBEADI)||
					'' Seri No:''||RTRIM(C.SERINO)||'' Vade:''||to_char(C.VADE,''DD.MM.YYYY''))
				else  LTRIM(RTRIM(coalesce(C.ACIKLAMA,''''))||'' ''||RTRIM(B.BANKAADI)||''''||RTRIM(BS.SUBEADI)||
					'' Hs.No:''||RTRIM(coalesce(C.HESAPNO,''0''))||'' Seri No:''||RTRIM(C.SERINO)||'' Vade:''||to_char(C.VADE,''DD.MM.YYYY''))end AS ACIKLAMASI ,
	''Çekler'' AS TURU ,
         case when C.TUR=23 then (select KOD from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=33 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end AS GONDERENKOD ,
				  --SELECT * FROM HESAPPLANI
	GONDERENAD	= case when C.TUR=23 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=33 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
	 case when C.TUR=33 then (select KOD from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=23 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end AS ALANKOD ,
	 case when C.TUR=33 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=23 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end AS ALANAD ,
				  
	 case when C.TUR=33 then (select KOD from REHBER R where R.ID=C.REHBERID)
					       when C.TUR=23 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end AS ALANCARIKOD ,
	 case when C.TUR=33 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					       when C.TUR=23 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end AS ALANCARIAD ,
	 TUTAR AS GONDERENBORC ,
	 TUTAR AS GONDERENALACAK ,
	 KUR AS GONDERENKUR ,

	 TUTAR AS ALANBORC ,
	 TUTAR AS ALANALACAK ,
	 KUR AS ALANKUR ,

	 TUTAR AS ALANCARIBORC ,
	 TUTAR AS ALANCARIALACAK ,
	 KUR
 AS ALANCARIKUR from
CEKLER C
	inner join ISLEMTURLERI I on C.TUR=I.TUR
	INNER JOIN BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
    INNER JOIN BANKALAR B ON B.BANKAKODU = BS.BANKAKODU

--WHERE C.ID=104 AND C.TUR = 33
where C.ID = ''$CEKID$'' AND C.TUR = ''$TUR$''


) AS X' WHERE id = 839;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
