K.TUR,I.AD,K.ISLEMTARIHI,K.BELGENO,
K.REHBERID,
case when K.HESAPTURU IN (''P'',''V'') AND KREDIID>1 then K.ACIKLAMA else '''' end AS ACIKLAMASI ,
'''' AS TURU , 
case when K.HESAPTURU=''K'' then (select KS.KASAKODU  from KASALAR KS where KS.ID=K.HESAPID)
			     when K.HESAPTURU=''B'' then (select BS.HESAPKODU from BANKAHESAPLAR BS where BS.ID=K.HESAPID)
			     when K.HESAPTURU=''V'' then (select KK.KODU from KREDIKARTI KK where KK.ID=K.HESAPID)
			     when K.HESAPTURU=''P'' then (select P.KODU from POS P where P.ID=K.HESAPID)

			end AS GONDERENKOD ,
case when K.HESAPTURU=''K'' then (select KS.KASAADI from KASALAR KS where KS.ID=K.HESAPID)
				when K.HESAPTURU=''B'' then (select BS.HESAPADI from BANKAHESAPLAR BS where BS.ID=K.HESAPID)
				when K.HESAPTURU=''V'' then (select KK.ADI from KREDIKARTI KK where KK.ID=K.HESAPID)
				when K.HESAPTURU=''P'' then (select P.ADI from POS P where P.ID=K.HESAPID)

			end AS GONDERENAD ,

(select case when K2.HESAPTURU=''K'' AND REHBERID=0 then (select KS.KASAKODU  from KASALAR KS where KS.ID=K2.HESAPID ) 
					 when K2.HESAPTURU=''B'' then (select BS.HESAPKODU from BANKAHESAPLAR BS where BS.ID=K2.HESAPID )
					 when K2.HESAPTURU=''V'' then (select KK.KODU from KREDIKARTI KK where KK.ID=K2.HESAPID)
					 when K2.HESAPTURU=''P'' then (select P.KODU from POS P where P.ID=K2.HESAPID)
						END
		  FROM 
			KASA K2 
		  WHERE 
			K2.GERIDONUSID=K.ID) AS ALANKOD ,
(select case when K2.HESAPTURU=''K'' AND REHBERID=0 then (select KS.KASAADI  from KASALAR KS where KS.ID=K2.HESAPID ) 
					when K2.HESAPTURU=''B'' AND REHBERID=0 then (select BS.HESAPADI from BANKAHESAPLAR BS where BS.ID=K2.HESAPID )
