	GONDERENAD	= case when C.TUR=23 then (select FIRMA from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=33 then (select HESAPADI from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
				  end,
	 case when C.TUR=33 then (select KOD from REHBER R where R.ID=C.REHBERID)
					   when C.TUR=23 then (select HESAPKODU from HESAPPLANI HP where HP.HESAPKODU=C.MUHKODU)
