UPDATE public.dokumler SET sql = '/*PGX*/IF EXISTS (SELECT id FROM tempdb.SYSobjects  where name like ''%GunHareket_Kisi_Bazli%'' )
BEGIN
 	DROP TABLE #GunHareket_Kisi_Bazli
END



SELECT @StartDate = ''$Baslangic$ 00:00'',
	   @EndDate   = ''$Bitis$ 23:59''

SELECT
	R.ID,
	R.FIRMA, 
	KARTNO          = 0,
	GUN             = DATEADD(DAY, DATEDIFF(DAY, 0, DATEADD(DAY, v.number, @StartDate)), 0),
	GUNAD           = DATENAME(WEEKDAY,(DATEADD(DAY, DATEDIFF(DAY, 0, DATEADD(DAY, v.number, @StartDate)), 0))),
	VARDIYAGUN      = 0,
	VARDIYAGIRIS    = CAST(NULL AS DATETIME),
	VARDIYACIKIS    = CAST(NULL AS DATETIME),
	VARDIYAGIRISSAAT= CAST(NULL AS VARCHAR(20)),
	VARDIYACIKISSAAT= CAST(NULL AS VARCHAR(20)),
	GIRISSAAT       = CAST(NULL AS DATETIME),
	CIKISSAAT       = CAST(NULL AS DATETIME),
	GIRISTARIH      = CAST(NULL AS DATETIME),
	CIKISTARIH      = CAST(NULL AS DATETIME),
	VARDIYADAKIKASURE= 0,
	CALISMASAATI    = 0,
	CALISMADAKIKASI = 0,
	GIRISDURUMSAAT  = 0,
	GIRISDURUMDAKIKA= 0,
	CIKISDURUMSAAT  = 0,
	CIKISDURUMDAKIKA= 0

INTO #GunHareket_Kisi_Bazli
FROM master.spt_values v cross join REHBER R 
WHERE v.type = ''P''
	 AND DATEDIFF(DAY, @StartDate, @EndDate) >= v.number
	 AND KOD LIKE ''335%''

UPDATE #GunHareket_Kisi_Bazli SET GUNAD=case 
							when GUNAD=''Sunday''		then ''Pazar''
							when GUNAD=''Monday''		then ''Pazartesi''
							when GUNAD=''Tuesday''	then ''Salı''
							when GUNAD=''Wednesday''	then ''Çarşamba''
							when GUNAD=''Thursday ''	then ''Perşembe'' 
							when GUNAD=''Friday''		then ''Cuma''
							when GUNAD=''Saturday''	then ''Cumartesi''
						else '''' end	 
UPDATE 	#GunHareket_Kisi_Bazli SET VARDIYAGIRIS	  = cast((cast(GIRIS as varchar)) as timestamp)	FROM  #GunHareket_Kisi_Bazli G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI
UPDATE 	#GunHareket_Kisi_Bazli SET VARDIYACIKIS	  = cast((cast(CIKIS as varchar)) as timestamp)	FROM  #GunHareket_Kisi_Bazli G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI	
UPDATE 	#GunHareket_Kisi_Bazli SET VARDIYAGIRISSAAT  = GIRIS	FROM  #GunHareket_Kisi_Bazli G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI
UPDATE 	#GunHareket_Kisi_Bazli SET VARDIYACIKISSAAT  = CIKIS	FROM  #GunHareket_Kisi_Bazli G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI											
UPDATE 	#GunHareket_Kisi_Bazli SET KARTNO=P.KARTNO	FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID 
UPDATE 	#GunHareket_Kisi_Bazli SET GIRISSAAT         = cast((cast(GIRIS as varchar)) as timestamp)	FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket_Kisi_Bazli SET CIKISSAAT         = cast((cast(CIKIS as varchar)) as timestamp)	FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket_Kisi_Bazli SET GIRISTARIH        = GIRIS	FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket_Kisi_Bazli SET CIKISTARIH        = CIKIS	FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket_Kisi_Bazli SET CALISMASAATI      = abs(datediff(minute,GIRIS,CIKIS)/60) FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) and coalesce(GIRIS,'''')<>'''' AND  coalesce(CIKIS,'''')<>''''
UPDATE  #GunHareket_Kisi_Bazli SET CALISMADAKIKASI	  = ((datediff(minute,GIRIS,CIKIS))%60) FROM  #GunHareket_Kisi_Bazli G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) and coalesce(GIRIS,'''')<>'''' AND  coalesce(CIKIS,'''')<>''''
UPDATE 	#GunHareket_Kisi_Bazli SET GIRISDURUMSAAT    = abs(datediff(minute,VARDIYAGIRIS,GIRISSAAT))/60     FROM  #GunHareket_Kisi_Bazli WHERE coalesce(VARDIYAGIRIS,'''')<>'''' AND coalesce(GIRISSAAT,'''')<>''''
UPDATE  #GunHareket_Kisi_Bazli SET GIRISDURUMDAKIKA  = ((datediff(minute,VARDIYAGIRIS,GIRISSAAT))%60)		FROM  #GunHareket_Kisi_Bazli WHERE coalesce(VARDIYAGIRIS,'''')<>'''' AND coalesce(GIRISSAAT,'''')<>''''
UPDATE 	#GunHareket_Kisi_Bazli SET CIKISDURUMSAAT    = CASE WHEN VARDIYACIKIS>CIKISSAAT THEN -1*(datediff(minute,CIKISSAAT,VARDIYACIKIS)/60) ELSE datediff(minute,VARDIYACIKIS,CIKISSAAT)/60 END		FROM  #GunHareket_Kisi_Bazli WHERE coalesce(VARDIYACIKIS,'''')<>'''' AND coalesce(CIKISSAAT,'''')<>''''
UPDATE  #GunHareket_Kisi_Bazli SET CIKISDURUMDAKIKA  = CASE WHEN VARDIYACIKIS>CIKISSAAT THEN -1*(((datediff(minute,CIKISSAAT,VARDIYACIKIS))%60))   ELSE -1*(((datediff(minute,CIKISSAAT,VARDIYACIKIS))%60)) END   FROM  #GunHareket_Kisi_Bazli WHERE coalesce(VARDIYACIKIS,'''')<>'''' AND coalesce(CIKISSAAT,'''')<>''''


SELECT  ID,KARTNO,AD,GIRISTARIH,CIKISTARIH,CALISMASURE,VARDIYAGIRISSAAT,VARDIYACIKISSAAT,VARDIYASURE,
		GIRISDURUM,CIKISDURUM,
		CALISMAFARK=CASE WHEN CALISMAFARK=''00:00'' THEN '''' ELSE CALISMAFARK END
FROM (
SELECT 
		ID,AD,KARTNO,GIRISTARIH,CIKISTARIH,CALISMASURE,VARDIYAGIRISSAAT,VARDIYACIKISSAAT,
		VARDIYASURE= VARDIYASURESAAT+'':''+VARDIYASUREDAKIKA,
		GIRISDURUM = CASE WHEN GIRISDURUM=''ERKEN'' AND coalesce(GDURUMDAKIKA,'''')<>'''' THEN GDURUMSAAT+'':''+GDURUMDAKIKA+'' ERKEN''
						WHEN GIRISDURUM=''GEÇ''   AND coalesce(GDURUMDAKIKA,'''')<>'''' THEN GDURUMSAAT+'':''+GDURUMDAKIKA+'' GEÇ'' ELSE '''' END,
		CIKISDURUM = CASE WHEN CIKISDURUM=''ERKEN'' AND coalesce(CDURUMDAKIKA,'''')<>'''' THEN CDURUMSAAT+'':''+CDURUMDAKIKA+'' ERKEN''
						WHEN CIKISDURUM=''GEÇ''   AND coalesce(CDURUMDAKIKA,'''')<>'''' THEN CDURUMSAAT+'':''+CDURUMDAKIKA+'' GEÇ'' ELSE '''' END,
		CALISMAFARK=(CASE WHEN length(DURUMSURE/60)=1 THEN ''0''+cast((DURUMSURE/60) as varchar) ELSE cast((DURUMSURE/60) as varchar) END)+'':''+					
		            (CASE WHEN length(DURUMSURE%60)=1 THEN ''0''+cast((DURUMSURE%60) as varchar) ELSE cast((DURUMSURE%60) as varchar) END)+'' ''+
		            DURUMHAL

		
FROM(
SELECT	ID,AD,KARTNO,GIRISTARIH,
		CIKISTARIH,VARDIYAGIRISSAAT,VARDIYACIKISSAAT,
		VARDIYASURESAAT	  = CASE WHEN length(VARDIYASURE/60)=1 THEN ''0''+cast(VARDIYASURE/60 as varchar)   ELSE cast(VARDIYASURE/60 as varchar) END,
		VARDIYASUREDAKIKA = CASE WHEN length(VARDIYASURE%60)=1 THEN ''0''+cast(VARDIYASURE%60 as varchar)   ELSE cast(VARDIYASURE%60 as varchar) END,
		CALISMASURE		  = CASE WHEN CALISMASAATI+'':''+CALISMADAKIKASI=''00:00'' THEN '''' ELSE CALISMASAATI+'':''+CALISMADAKIKASI END,
		GIRISDURUM,CIKISDURUM,GIRISDAKIKAGECIKMETOP,CIKISDAKIKAGECIKMETOP,
		DURUMHAL	  =CASE WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN ''-''
							WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP >0   THEN ''+''
						    WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''GEÇ''   THEN ''+''
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''ERKEN'' THEN ''-''
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN ''+''
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) >0 THEN ''-''
						ELSE '''' END,
		DURUMSURE	  =CASE WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN -1*(GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
							WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) >0 THEN (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
						    WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''GEÇ''   THEN GIRISDAKIKAGECIKMETOP+CIKISDAKIKAGECIKMETOP
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''ERKEN'' THEN GIRISDAKIKAGECIKMETOP+CIKISDAKIKAGECIKMETOP 
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN -1*(GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) >0 THEN (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
						ELSE 0 END,
		GDURUMSAAT   = CASE WHEN length(GIRISDAKIKAGECIKMETOP/60)=1 THEN ''0''+cast(GIRISDAKIKAGECIKMETOP/60 as varchar)   ELSE cast(GIRISDAKIKAGECIKMETOP/60 as varchar) END,
		GDURUMDAKIKA = CASE WHEN length(GIRISDAKIKAGECIKMETOP%60)=1 THEN ''0''+cast((GIRISDAKIKAGECIKMETOP%60) as varchar) ELSE cast((GIRISDAKIKAGECIKMETOP%60) as varchar) END,
		CDURUMSAAT   = CASE WHEN length(CIKISDAKIKAGECIKMETOP/60)=1 THEN ''0''+cast(CIKISDAKIKAGECIKMETOP/60 as varchar)   ELSE cast(CIKISDAKIKAGECIKMETOP/60 as varchar) END,
		CDURUMDAKIKA = CASE WHEN length(CIKISDAKIKAGECIKMETOP%60)=1 THEN ''0''+cast((CIKISDAKIKAGECIKMETOP%60) as varchar) ELSE cast((CIKISDAKIKAGECIKMETOP%60) as varchar) END
	

FROM
(
SELECT	ID,FIRMA AS AD,KARTNO,
		GIRISTARIH,CIKISTARIH,
		VARDIYAGIRISSAAT,
		VARDIYACIKISSAAT,
		VARDIYASURE = (datediff(minute,VARDIYAGIRISSAAT,VARDIYACIKISSAAT)),
		GIRISDURUM	= CASE WHEN (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)<0 THEN ''ERKEN'' WHEN (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)=0 THEN '''' ELSE ''GEÇ'' END,
		CIKISDURUM	= CASE WHEN (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)<0 THEN ''ERKEN'' WHEN (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)=0 THEN '''' ELSE ''GEÇ'' END,
		GIRISDAKIKAGECIKMETOP = CASE WHEN (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)<0 THEN -1*((GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)) ELSE (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA) END,
		CIKISDAKIKAGECIKMETOP = CASE WHEN (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)<0 THEN -1*((CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)) ELSE (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA) END,
		CALISMASAATI	= CASE WHEN length(cast(REPLACE(CALISMASAATI,''-'','''') as varchar))    =1 THEN ''0''+cast(REPLACE(CALISMASAATI,''-'','''') as varchar)    ELSE cast(REPLACE(CALISMASAATI,''-'','''') as varchar) END,
		CALISMADAKIKASI = CASE WHEN length(cast(REPLACE(CALISMADAKIKASI,''-'','''') as varchar)) =1 THEN ''0''+cast(REPLACE(CALISMADAKIKASI,''-'','''') as varchar) ELSE cast(REPLACE(CALISMADAKIKASI,''-'','''') as varchar) END


FROM #GunHareket_Kisi_Bazli
) AS X
) AS Y
) AS Z

WHERE AD LIKE ''$AdSoyad$%''
ORDER BY AD
--DROP TABLE #GunHareket_Kisi_Bazli
' WHERE id = 845;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT MUSTERI,SUM(Aktivite) AS Aktivite,SUM(Görev) AS Görev  ,SUM(Toplam) AS Toplam
FROM(
select
	Musteri.FIRMA MUSTERI,
        Aktivite    =SUM(CASE WHEN TURU=2 THEN 1  ELSE 0 END) ,
        Görev       =SUM(CASE WHEN TURU=1 THEN 1  ELSE 0 END) , 
	Toplam      =COUNT(A.ID)
	
from 
	AKTIVITELER A
		   left outer join REHBER Musteri on Musteri.ID=A.MUSTERIID
where
	 A.BITISTARIHI > ''$Baslangic$ 00:00'' 
 and A.BITISTARIHI <''$Bitis$ 23:59'' 
 and A.DURUM<>4 
 GROUP BY Musteri.FIRMA,TURU 
 ) AS X
 GROUP BY 
 MUSTERI
 ORDER BY 4 DESC' WHERE id = 846;
UPDATE public.dokumler SET sql = '/*PGX*/select
	A.KONUSU,
	Toplam      =COUNT(A.ID)
	
from 
	AKTIVITELER A

where
     A.BITISTARIHI >''$Baslangic$ 00:00'' 
 and A.BITISTARIHI <''$Bitis$ 23:59'' 
 and A.DURUM<>4 
 GROUP BY KONUSU
 ORDER BY 2 DESC' WHERE id = 847;
UPDATE public.dokumler SET sql = '/*PGX*/
        @SURE INT,
        1 INT,
        0 INT





select
A.ID,
AKTIVITEILISKI = CASE WHEN A.SORUMLU = 6006 THEN ''Sorumlu''
                              WHEN A.ATAYAN = 6006 THEN ''Aktivite Atayan''
                              WHEN A.TAKIPCI = 6006 THEN ''Takipçi''
                              WHEN A.BILGILENDIRILECEK = 6006 THEN ''Bilgilendirilecek''
                              WHEN SorumluVekil.VEKIL = 6006 THEN ''Vekil Sorumlu''
                              WHEN AtayanVekil.VEKIL = 6006 THEN ''Vekil Atayan''
                              WHEN TakipVekil.VEKIL = 6006 THEN ''Vekil Takipçi''
                              WHEN BilgiVekil.VEKIL = 6006 THEN ''Vekil Bilgilendirilecek''
                      ELSE '''' END,
SIRA = CASE WHEN A.SORUMLU = 6006 THEN 1
                              WHEN A.ATAYAN = 6006 THEN 2
                              WHEN A.TAKIPCI = 6006 THEN 3
                              WHEN A.BILGILENDIRILECEK = 6006 THEN 4
                              WHEN SorumluVekil.VEKIL = 6006 THEN 5
                              WHEN AtayanVekil.VEKIL = 6006 THEN 6
                              WHEN TakipVekil.VEKIL = 6006 THEN 7
                              WHEN BilgiVekil.VEKIL = 6006 THEN 8
                      ELSE 99 END,
       A.MUSTERIID,
       Musteri.FIRMA MUSTERI,
       A.TURU,A.TIPI,              
       A.BASLAMATARIHI,A.BITISTARIHI,A.KONUSU,
       A.KONUM,
    coalesce(A.SORUMLU,'''') SORUMLU ,
       coalesce(SorumluPers.FIRMA,'''') as SORUMLUAD,
       ILGILI1AD=MusteriIlgi1.ADSOYAD,
       ILGILI2AD=MusteriIlgi2.ADSOYAD,
       A.SONUC,
       A.DURUM,
       A.NOTLAR,
       -- A.ILGILI1,
       -- A.ILGILI2,
       MusteriIlgi1.ADSOYAD,
       MusteriIlgi2.ADSOYAD,
       A.ATAYAN,
       ATAYANAD=AtayanPers.FIRMA,
       BILGILENDIRILECEKAD=BilgiPers.FIRMA,
       TAKIPCIAD=TakipciPers.FIRMA,
       ANIMSATICI =  CASE WHEN (A.ANIMSAT >0 AND coalesce(A.ANIMSATMATARIHI,''1900-01-01'')>''1900-01-01'') THEN 1 ELSE 0 END,
    DOSYAVAR = CASE WHEN  (SELECT COUNT(ID) FROM DOKUMAN WHERE  MODUL =12 AND MODULID = A.ID  AND KLASOR <> -1  LIMIT 1 )  >0  THEN 1 ELSE 0 END,
   Proje.KONUSU PROJEKONU, Proje.PROJEKODU,
Proje.DURUM as PDURUM , 
 Proje.SONUC as PSONUC ,
Proje.ASAMA as  PASAMA,
A.ATAYAN_EPOSTA,
A.ATAYAN_SMS,
A.SORUMLU_EPOSTA,
A.SORUMLU_SMS,
A.BILGI_EPOSTA,
A.BILGI_SMS,
A.SUBEID,
A.TAKIPCI_EPOSTA,
A.TAKIPCI_SMS,
A.TAMAMLANMAORANI,
A.BAGLIAKTIVITEID,
BagliAktivite.KONUSU BAGLIAKTIVITEKONUSU,
BagliAktivite.ID BAGLIAKTID,
A.TAKIPCI,
A.BILGILENDIRILECEK,
A.ATAYAN,
A.OKUNDU,
       BASLAMAAY=month(A.BASLAMATARIHI),
       BASLAMAYIL=year(A.BASLAMATARIHI),
       BITISAY=month(A.BITISTARIHI),
       BITISYIL=year(A.BITISTARIHI),
Musteri.BOLGE
from 
       AKTIVITELER A
                              left outer join REHBER Musteri on Musteri.ID=A.MUSTERIID
                        inner join REHBER SorumluPers on SorumluPers.ID=A.SORUMLU
                        left outer join REHBERPERSONEL MusteriIlgi1 on MusteriIlgi1.ID=A.ILGILI1
                        left outer join REHBERPERSONEL MusteriIlgi2 on MusteriIlgi2.ID=A.ILGILI2
                        left outer join REHBER AtayanPers on AtayanPers.ID=A.ATAYAN
                              left outer join REHBER BilgiPers on BilgiPers.ID=A.BILGILENDIRILECEK
                              left outer join REHBER TakipciPers on TakipciPers.ID=A.TAKIPCI
                           LEFT OUTER JOIN PERSONELIZIN SorumluVekil on
                                                                          A.SORUMLU = SorumluVekil.REHBERID
                                                                          AND SorumluVekil.VEKIL = 6006
                                                                          AND A.BITISTARIHI BETWEEN SorumluVekil.IZINBASLANGIC AND SorumluVekil.IZINBITIS
                           LEFT OUTER JOIN PERSONELIZIN AtayanVekil on 
                                                                          A.ATAYAN = AtayanVekil.REHBERID
                                                                          AND AtayanVekil.VEKIL = 6006
                                                                          AND A.BITISTARIHI BETWEEN AtayanVekil.IZINBASLANGIC AND AtayanVekil.IZINBITIS
                           LEFT OUTER JOIN PERSONELIZIN TakipVekil on 
                                                                          A.SORUMLU = TakipVekil.REHBERID
                                                                          AND TakipVekil.VEKIL = 6006
                                                                          AND A.BITISTARIHI BETWEEN TakipVekil.IZINBASLANGIC AND TakipVekil.IZINBITIS
                           LEFT OUTER JOIN PERSONELIZIN BilgiVekil on 
                                                                          A.BILGILENDIRILECEK = BilgiVekil.REHBERID
                                                                          AND BilgiVekil.VEKIL = 6006
                                                                          AND A.BITISTARIHI BETWEEN BilgiVekil.IZINBASLANGIC AND BilgiVekil.IZINBITIS     
                                LEFT OUTER JOIN PROJELER Proje ON Proje.ID = A.PROJEID
   LEFT OUTER JOIN AKTIVITELER BagliAktivite on A.BAGLIAKTIVITEID = BagliAktivite.ID

where
      1 = CASE WHEN 0 = 0 THEN 1
      WHEN 
         EXISTS (   SELECT REHBERID, Detay.FIRMA AS DETAYKULLANICI 
                                  FROM YETKIALANI Alan INNER JOIN REHBER Sahip  ON Alan.SAHIPREHBERID = Sahip.ID
                                                              INNER JOIN Rehber Detay ON Alan.REHBERID = Detay.ID
                                  WHERE
                                  Alan.SAHIPREHBERID = 6006 AND ALANTURU = 1
                                  AND (REHBERID = A.ATAYAN OR 
                                       REHBERID = A.BILGILENDIRILECEK  OR
                                       REHBERID = A.TAKIPCI OR
                                       REHBERID = A.SORUMLU OR
                                       REHBERID = SorumluVekil.VEKIL OR
                                       REHBERID = AtayanVekil.VEKIL OR
                                       REHBERID = TakipVekil.VEKIL OR
                                       REHBERID = BilgiVekil.VEKIL 
                                         )
                           ) THEN 1
     ELSE 0 
    END



and A.BITISTARIHI  >''$Baslangic$ 00:00'' 
 and A.BITISTARIHI <''$Bitis$ 23:59'' 
 and A.DURUM<>4 

AND Musteri.BOLGE LIKE ''$Bolge$%''
order by SIRA, A.BITISTARIHI DESC
' WHERE id = 855;
UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Kolon
--Kategori
--YIL
--Seriler
--Seri TOPLAM/Toplam
--Seri MUSTERISAYI/Müşteri

SET LANGUAGE Turkish

SELECT YIL,SUM(TOPLAM) AS TOPLAM,SUM(MUSTERISAYI) AS MUSTERISAYI
FROM(
select YIL=YEAR(BASLAMATARIHI),TOPLAM=count(P.BASLAMATARIHI),
	 MUSTERISAYI=(select count(DISTINCT REHBERID) FROM PROJELER P1 
				WHERE  YEAR(P1.BASLAMATARIHI)= YEAR(P.BASLAMATARIHI) AND P1.PRJ_SORUMLUSU_ID = P.PRJ_SORUMLUSU_ID AND P1.TURU=P.TURU )
from PROJELER P
where 
        year(BASLAMATARIHI) between ''$Basl$'' and ''$Bit$''
    and PRJ_SORUMLUSU_ID like ''$Sorumlu$%''
    and TURU like ''$Türü$%''
group by YEAR(BASLAMATARIHI),P.PRJ_SORUMLUSU_ID,P.TURU
) AS X
GROUP BY
	YIL
order by 1

SET LANGUAGE us_english' WHERE id = 856;
UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Kolon
--Aylık Kabuller
--Kategori
--AYADI
--Seriler
--Seri TOPLAM/Toplam
--Seri MUSTERISAYI/Müşteri


SET LANGUAGE Turkish

SELECT AY,AYADI,SUM(TOPLAM) AS TOPLAM,SUM(MUSTERISAYI) AS MUSTERISAYI
FROM(
select 
	AY=month(BASLAMATARIHI), AYADI= DATENAME(month, BASLAMATARIHI),YIL=YEAR(BASLAMATARIHI), TOPLAM=count(ID),
	MUSTERISAYI=(select count(DISTINCT REHBERID) FROM PROJELER P1 
				WHERE  YEAR(P1.BASLAMATARIHI)= YEAR(P.BASLAMATARIHI) AND month(P1.BASLAMATARIHI)=month(P.BASLAMATARIHI) and P1.PRJ_SORUMLUSU_ID = P.PRJ_SORUMLUSU_ID AND P1.TURU=P.TURU )
from 
	PROJELER P
where 
		year(BASLAMATARIHI)=''$Yil$'' 
    and PRJ_SORUMLUSU_ID like ''$Sorumlu$%''
    and TURU like ''$Türü$%''
group by YEAR(BASLAMATARIHI) ,month(BASLAMATARIHI), DATENAME(month, BASLAMATARIHI),P.PRJ_SORUMLUSU_ID,P.TURU
) AS X
GROUP BY
	AY,AYADI

order by 1

SET LANGUAGE us_english' WHERE id = 857;
UPDATE public.dokumler SET sql = '/*PGX*/









                        
                                           
SELECT @NT = NAKITTOPLAM,@NO=NAKITODEME,@KT=VISATOPLAM,@HT=HEDIYETOPLAM,@IT=IADECEKITOPLAM,@GT = GENELTOPLAM FROM fn_TURTOPLA2  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')
SELECT @FIS=FIS ,@FATURA=FATURA,@IADE=IADE,@TOPLAM=TOPLAM FROM fn_SATISBELGETOPLAM  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')                                                                          

select
         ANAHTAR,TUTAR,AD,MARKA,SAYI,TURTOPLAMTUTAR,
         @NT AS NAKITTOPLAM,
         @NO AS NAKITODEME,
         @KT AS VISATOPLAM,
         @HT AS HEDIYETOPLAM,
         @IT AS IADECEKITOPLAM,
         @GT AS GENELTOPLAM  ,
         @FIS AS FIS ,
         @FATURA AS FATURA,
         @IADE AS IADE,
         @TOPLAM AS TOPLAM
FROM (

select
CASE WHEN coalesce(ANAHTAR,'''')='''' THEN ''KATEGORISIZ'' ELSE ANAHTAR END AS ANAHTAR ,
ROUND((SUM(TUTAR)),2) AS TUTAR,
AD, MARKA,
SUM(SAYI) AS SAYI,
TURTOPLAMTUTAR
FROM(

select

KTG.AD AS ANAHTAR,
CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*((F.KDV/100.0)+1.0) ELSE F.TUTAR END AS TUTAR ,
CASE WHEN F.TUR =1 THEN S.STOKADI ELSE MG.AD END AS AD ,
G3.ANAHTAR AS MARKA ,
F.ADET as SAYI,
A.TUTAR AS TURTOPLAMTUTAR


from
FATBASLIK FB INNER JOIN FATURA F  ON FB.ID=F.FATBASID
			 LEFT OUTER JOIN MASRAFGELIR MG on F.URUNID = MG.ID
			 LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
                         LEFT JOIN KATEGORI KTG ON S.KATEGORI=KTG.ID
			 INNER JOIN fn_STOKTURTOPLAMI_KATEGORI (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'') A ON coalesce(A.ANAHTAR,''KATEGORISIZ'')=coalesce(KTG.AD,''KATEGORISIZ'')
                         left join REHBER R on FB.SUBEID=R.ID AND R.ID<0
                         LEFT JOIN GENINI G3 ON G3.DEGER=S.MARKA AND G3.BOLUM=-2701 AND g3.DIL=-1

WHERE

            FB.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND     FB.TUR IN (15,16)
        AND  R.FIRMA LIKE ''$Sube$%''
                                                      

 
 ) AS X
 
GROUP  BY 
        ANAHTAR,AD,MARKA,TURTOPLAMTUTAR
) AS Y 
--GROUP BY ANAHTAR,TUTAR,AD,SAYITURTOPLAMTUTAR
' WHERE id = 860;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	SAAT,SUM(TUTAR)

FROM(

select
	to_char(FB.TARIH,''YYYY-MM-DD HH24:MI:SS'') as TARIH,
        --K.AD,S.STOKADI,
	DATEPART(HOUR,FB.TARIH) AS SAAT ,
	CASE WHEN coalesce(LOKASYON,'''')<>0 AND FB.KDVDURUM=''Hariç'' THEN ROUND((ROUND((F.BIRIMFIYAT*F.ADET),2))*(1+(F.KDV/100.0)),2) 
		   WHEN coalesce(LOKASYON,'''')<>0 AND FB.KDVDURUM=''Dahil'' THEN ROUND((F.BIRIMFIYAT*F.ADET),2)
						ELSE 0 END
 AS TUTAR FROM
	FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                     INNER JOIN STOKLAR S ON F.URUNID=S.ID
                     INNER JOIN KATEGORI K ON S.KATEGORI=K.ID
where
	FB.TUR IN (15,16) and
	TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''  AND
        K.AD LIKE ''$Kategori$%'' AND
        S.STOKADI LIKE ''$StokAdi$%''
) AS X

GROUP BY
	SAAT

ORDER BY SAAT' WHERE id = 865;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	TARIH,CIKISDEPO,GIRISDEPO,KOD,STOKADI,
	(KALAN+SATIS+BAYAT)-BUGUNGELEN AS DEVIR ,
	BUGUNGELEN,SATIS,BAYAT,KALAN
FROM(
SELECT

	TARIH,
	CIKISDEPO,
	GIRISDEPO,
	KOD,
	STOKADI,
	BUGUNGELEN,
        coalesce((
			SELECT SUM(F1.ADET) FROM FATBASLIK FB1 INNER JOIN FATURA F1 ON FB1.ID=F1.FATBASID
				WHERE FB1.TUR IN (15,16) AND F1.URUNID=X.URUNID AND FB1.CIKISDEPO=X.GIRISDEPOID AND to_char(FB1.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')=X.TARIH   
		  ) ,0) AS SATIS ,
	coalesce((
			SELECT SUM(F1.ADET) FROM FATBASLIK FB1,FATURA F1,DEPOLAR D WHERE FB1.ID=F1.FATBASID AND FB1.CIKISDEPO=D.ID
				AND FB1.TUR IN (20) AND F1.URUNID=X.URUNID AND to_char(FB1.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')=X.TARIH 
				AND D.DEPOADI LIKE ''BAYAT%''  
		  ) ,0) AS BAYAT ,
	(SELECT KALAN FROM STOKDURUM SD WHERE SD.STOKID=X.URUNID AND SD.DEPOID=X.GIRISDEPOID)

 AS KALAN FROM (
SELECT     
	to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'') AS TARIH,
	D1.DEPOADI AS CIKISDEPO ,
        D.DEPOADI AS GIRISDEPO ,
	FB.GIRISDEPO AS GIRISDEPOID ,
        FB.CIKISDEPO AS CIKISDEPOID ,
        S.KOD,
	S.STOKADI,
	F.URUNID,
	SUM(F.ADET)

 AS BUGUNGELEN FROM 
	FATBASLIK FB 
		INNER JOIN FATURA F ON 
			FB.ID=F.FATBASID
		LEFT JOIN STOKLAR S ON
			F.URUNID=S.ID
		LEFT JOIN DEPOLAR D ON
			FB.GIRISDEPO=D.ID
		LEFT JOIN DEPOLAR D1 ON
			FB.CIKISDEPO=D1.ID

WHERE
	to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')=  to_char((cast(''$Baslangic$'' as timestamp)),''YYYY-MM-DD HH24:MI:SS'') AND
	FB.TUR IN  (20) AND
         D.DEPOADI=''$Subesi$''
GROUP BY
	to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS''),D1.DEPOADI,FB.CIKISDEPO,D.DEPOADI,FB.GIRISDEPO,F.URUNID,S.KOD,S.STOKADI
) AS X
--WHERE
--	GIRISDEPO=''$Subesi$''

) AS Y
ORDER BY TARIH,CIKISDEPO,GIRISDEPO' WHERE id = 867;
