UPDATE public.dokumler SET sql = '/*PGX*/BEGIN TRY
truncate table #StokKalanGunluk
END TRY

BEGIN CATCH
CREATE TABLE #StokKalanGunluk (	
	SIRANO int IDENTITY(1,1) NOT NULL,
	STOKID int NULL, 
	DEPOID int NULL,
	KALAN FLOAT NULL
	
	)
END CATCH

INSERT INTO #StokKalanGunluk (STOKID,DEPOID,KALAN)


SELECT STOKID,DEPOID,KALAN FROM fn_Rapor_StokSayimButun(''$Baslangic$ 00:00'',''$Subesi$'')

SELECT
	TARIH,CIKISDEPO,GIRISDEPO,KOD,STOKADI,
	DEVIR=(KALAN+SATIS+BAYAT)-BUGUNGELEN,
	BUGUNGELEN,
	SATIS,BAYAT,
	KALAN
FROM(
SELECT

	TARIH,
	CIKISDEPO,
	GIRISDEPO,
	KOD,
	STOKADI,
	BUGUNGELEN,
    SATIS=coalesce((
			SELECT 
				SUM(F1.MIKTAR) 
			FROM 
				FATBASLIK FB1 
					INNER JOIN FATURA F1 ON 
						FB1.ID=F1.FATBASID
			WHERE 
				FB1.TUR IN (15,16) AND 
				F1.URUNID=X.URUNID AND 
				FB1.CIKISDEPO=X.GIRISDEPOID AND 
				to_char(FB1.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')=X.TARIH   
		  ) ,0),
	BAYAT=coalesce((
			SELECT SUM(F1.ADET) FROM FATBASLIK FB1,FATURA F1,DEPOLAR D WHERE FB1.ID=F1.FATBASID AND FB1.CIKISDEPO=D.ID
				AND FB1.TUR IN (20) AND F1.URUNID=X.URUNID AND to_char(FB1.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')=X.TARIH 
				AND D.DEPOADI LIKE ''BAYAT%''  
		  ) ,0),
	
	KALAN=S.KALAN

FROM (
SELECT     
	to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'') AS TARIH,
	CIKISDEPO=D1.DEPOADI,
    GIRISDEPO=D.DEPOADI,
	GIRISDEPOID=FB.GIRISDEPO,
    CIKISDEPOID=FB.CIKISDEPO,
    S.KOD,
	S.STOKADI,
	F.URUNID,
	BUGUNGELEN=SUM(F.ADET)

FROM 
	FATBASLIK FB 
		INNER JOIN FATURA F ON 
			FB.ID=F.FATBASID
		LEFT JOIN STOKLAR S ON
			F.URUNID=S.ID
		LEFT JOIN DEPOLAR D ON
			FB.GIRISDEPO=D.ID
		LEFT JOIN DEPOLAR D1 ON
			FB.CIKISDEPO=D1.ID

WHERE
	to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'') =  to_char((cast(''$Baslangic$ 00:00'' as timestamp)),''YYYY-MM-DD HH24:MI:SS'') AND
	FB.TUR IN  (20) AND
    FB.GIRISDEPO =''$Subesi$''
GROUP BY
	to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS''),D1.DEPOADI,FB.CIKISDEPO,D.DEPOADI,FB.GIRISDEPO,F.URUNID,S.KOD,S.STOKADI
) AS X LEFT JOIN #StokKalanGunluk S ON X.GIRISDEPOID=S.DEPOID AND X.URUNID=S.STOKID

) AS Y
ORDER BY TARIH,CIKISDEPO,GIRISDEPO' WHERE id = 878;
UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Pasta
--Kategori
--DURUMU
--Seriler
--Seri TOPLAM/Toplam
select DURUMU = (select ANAHTAR from GENINI 
       where BOLUM=-2101 and DEGER=A.TIPI and DIL=-1 ),TOPLAM=count(A.TIPI)  
from AKTIVITELER A
where 
   BASLAMATARIHI between ''$Basl$'' and ''$Bit$''  
   and SORUMLU like ''$Sorumlu$%''
--and DURUM<>5 --revizeler dışında

group by TIPI' WHERE id = 880;
UPDATE public.dokumler SET sql = '/*PGX*/--Kategori
--DURUMU
--Seriler
--Seri TOPLAM/Toplam
select DURUMU = (select ANAHTAR from GENINI 
       where BOLUM=-3007 and DEGER=S.DURUM and DIL=-1 ),TOPLAM=count(S.DURUM)  
from SERVIS S
where 
BASLAMATARIHI between ''$Basl$'' and ''$Bit$''  
group by DURUM' WHERE id = 881;
UPDATE public.dokumler SET sql = '/*PGX*/--Aylık Kabuller
--Kategori
--AYADI
--Seriler
--Seri TOPLAM/Toplam
SET LANGUAGE Turkish

select month(BASLAMATARIHI), AYADI= DATENAME(month, BASLAMATARIHI), TOPLAM=count(ID)
