UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Pasta
--Kategori
--TUR
--Seriler
--Seri SAYI/Sayı
--Seri TUTAR/Tutar
 


select TUR=''KABUL'',
SAYI = (select count(TEKLIF_TUTARI) from TEKLIF where  DURUM=7 and TARIH between ''$Basl$ 00:00'' and ''$Bit$ 23:59''),
TUTAR = (select sum(TEKLIF_TUTARI) from TEKLIF where  DURUM=7 and TARIH between ''$Basl$ 00:00'' and ''$Bit$ 23:59'')
union all 
select TUR=''RED'', 
SAYI =(select count(TEKLIF_TUTARI) from TEKLIF where  DURUM=6 and TARIH between ''$Basl$ 00:00'' and ''$Bit$ 23:59''),
TUTAR = (select sum(TEKLIF_TUTARI) from TEKLIF where  DURUM=6 and TARIH between ''$Basl$ 00:00'' and ''$Bit$ 23:59'')
union all  
select TUR=''DIGER'',
SAYI = (select count(TEKLIF_TUTARI) from TEKLIF where  DURUM<>6 and DURUM <>7 and TARIH between ''$Basl$ 00:00'' and ''$Bit$ 23:59''),
TUTAR = (select sum(TEKLIF_TUTARI) from TEKLIF where  DURUM<>6 and DURUM <>7 and TARIH between ''$Basl$ 00:00'' and ''$Bit$ 23:59'')

 

' WHERE id = 884;
UPDATE public.dokumler SET sql = '/*PGX*/--GrafikTipi
--Kolon
--Kategori
--YIL
--Seriler
--Seri TOPLAM/Toplam
--Seri KABUL/Kabul

select YIL, 
TOPLAM=SUM(TOPLAM_GIREN), 
KABUL=SUM(TOPLAM_KABUL)  
from(

SELECT   
YIL=YEAR(TARIH) , 
TOPLAM_GIREN=SUM(TEKLIF_TUTARI),
TOPLAM_KABUL=CASE WHEN DURUM = 7 THEN SUM(TEKLIF_TUTARI) ELSE 0 END
FROM  TEKLIF T
group by DURUM, year(TARIH)


) as YILLAR
group by YIL
 order by 1
' WHERE id = 887;
