UPDATE public.dokumler SET sql = '/*PGX*/ --GrafikTipi
--Kolon
--Altayaz
--$Yil$ Aylar
--Kategori
--AYADI
--Seriler
--Seri CIKAN/Hedef
--Seri GIREN/Gerçekleşen
SET LANGUAGE Turkish
SELECT
AY,
AYADI,
GIREN=SUM(TOPLAM_GIREN),
CIKAN=SUM(TOPLAM_CIKAN)
FROM (
SELECT
AY=MONTH(FATURATARIH) ,
AYADI= DATENAME(month, FATURATARIH),

TOPLAM_GIREN=CASE 
			--WHEN (FB.KDVDURUM=''Hariç'') AND (FB.TUR IN(8,10,11,12)) THEN -TUTAR*(100+KDV)/100
			WHEN (FB.KDVDURUM=''Hariç'') AND (FB.TUR IN(14,15,16)) THEN TUTAR*(100+KDV)/100		
			--WHEN (FB.KDVDURUM=''Dahil'') AND (FB.TUR IN(8,10,11,12)) THEN -TUTAR	
			WHEN (FB.KDVDURUM=''Dahil'') AND (FB.TUR IN(14,15,16)) THEN TUTAR			
		END,
TOPLAM_CIKAN=0
FROM FATURA F INNER JOIN 
		FATBASLIK FB ON F.FATBASID=FB.ID 
where year(FATURATARIH)= $Yil$ 
group by FB.TUR, MONTH(FATURATARIH), DATENAME(month, FATURATARIH),FB.KDVDURUM,F.TUTAR,F.KDV

UNION ALL
SELECT
AY,
AYADI= CASE WHEN AY=1  THEN ''Ocak''
			WHEN AY=2  THEN ''Şubat''
			WHEN AY=3  THEN ''Mart''
			WHEN AY=4  THEN ''Nisan''
			WHEN AY=5  THEN ''Mayıs''
			WHEN AY=6  THEN ''Haziran''
			WHEN AY=7  THEN ''Temmuz''
			WHEN AY=8  THEN ''Ağustos''
			WHEN AY=9  THEN ''Eylül''
			WHEN AY=10 THEN ''Ekim''
			WHEN AY=11 THEN ''Kasım''
			WHEN AY=12 THEN ''Aralık'' ELSE '''' END,
			
TOPLAM_GIREN=0,
TOPLAM_CIKAN=PLANLANAN
FROM BUTCE B INNER JOIN MASRAFGELIR MG ON B.MASRAFID=MG.ID
where YIL= $Yil$ AND GELIRMI=1
group by AY,PLANLANAN
) AS ASD
GROUP BY
AY,
AYADI
order by 1
SET LANGUAGE us_english

' WHERE id = 891;
