UPDATE public.dokumler SET sql = '/*PGX*/SELECT * FROM (
SELECT 
	SUBE,KATEGORI,SUM(ADET) AS ADET,SUM(TUTAR) AS TUTAR,
	ROUND((SUM(TUTAR)*100.0/TOPLAMTUTAR),2)
 AS YUZDE FROM(                         
       
SELECT 
	SUBE,
	 cast(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'') as timestamp) AS TARIH ,
	KATEGORI,
	ADET,
	TUTAR,
	SUM(TUTAR) OVER (PARTITION BY SUBE)

 AS TOPLAMTUTAR FROM uv_Ciro_Genel 
                                      
WHERE 
	TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
        AND KATEGORI LIKE ''$Kategori$%''
	AND SUBE LIKE ''$Sube$%''
) AS X

GROUP BY SUBE,KATEGORI,TOPLAMTUTAR
) AS Y

ORDER BY SUBE ASC , TUTAR DESC' WHERE id = 896;
