UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
	SUBE,
	HESAPADI,
	SUM(TUTAR) AS TUTAR ,
	ROUND((SUM(TUTAR)*100.0/TOPLAMTUTAR),2)
 AS YUZDE FROM(

select                                     
	 SUBE AS SUBE ,
	 cast(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'') as timestamp)  AS TARIH ,
	HESAPADI,
	case 
				 when HESAPTURU=''B'' then 3
				 when HESAPTURU=''H'' AND coalesce(CEKSENETID,'''')<>'''' then 4
				 when HESAPTURU=''H'' AND coalesce(CEKSENETID,'''')=''''  then 5
				 when HESAPTURU=''K'' then 1
				 when HESAPTURU=''P'' then 2
				 when HESAPTURU=''V'' then 6 END AS SIRALAMA ,
	 TUTAR AS TUTAR ,
	SUM(TUTAR) OVER (PARTITION BY SUBE)

 AS TOPLAMTUTAR FROM uv_Tahsilat_Genel 
WHERE  
		TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
	--AND HESAPADI LIKE ''$HesapAdi$%''
	AND SUBE LIKE ''$Sube$%''

) AS X

GROUP BY SUBE,HESAPADI,TOPLAMTUTAR,SIRALAMA

ORDER BY SUBE,SIRALAMA' WHERE id = 902;
