	 cast(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'') as timestamp)  AS TARIH ,
	HESAPADI,
	case 
				 when HESAPTURU=''B'' then 3
				 when HESAPTURU=''H'' AND coalesce(CEKSENETID,'''')<>'''' then 4
				 when HESAPTURU=''H'' AND coalesce(CEKSENETID,'''')=''''  then 5
				 when HESAPTURU=''K'' then 1
				 when HESAPTURU=''P'' then 2
				 when HESAPTURU=''V'' then 6 END AS SIRALAMA ,
	 TUTAR AS TUTAR ,
	SUM(TUTAR) OVER (PARTITION BY SUBE)

 AS TOPLAMTUTAR FROM uv_Tahsilat_Genel 
WHERE  
		 cast(to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'') as timestamp)=''$Baslangic$''
AND	SUBE LIKE ''$Sube$%''

) AS X

GROUP BY SUBE,HESAPADI,TOPLAMTUTAR' WHERE id = 903;
UPDATE public.dokumler SET sql = '/*PGX*/


















SELECT @NT = NAKITTOPLAM,@NO=NAKITODEME,@KT=VISATOPLAM,@HT=HEDIYETOPLAM,@IT=IADECEKITOPLAM,@GT = GENELTOPLAM FROM fn_TURTOPLA2  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'')
SELECT @FIS=FIS ,@FATURA=FATURA,@IADE=IADE,@TOPLAM=TOPLAM FROM fn_SATISBELGETOPLAM  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'')                                                                              







--SELECT * FROM gt_TMP_SaticiGrupTutar

IF EXISTS (SELECT id FROM tempdb.SYSobjects  where name like ''%TMP_SaticiGrupTutar%'' )
BEGIN
	DROP TABLE gt_TMP_SaticiGrupTutar
END

CREATE TABLE gt_TMP_SaticiGrupTutar ( GRUP VARCHAR(50))

DECLAINI STOKGRUP ON STOKGRUP.DEGER=S.GRUBU AND STOKGRUP.BOLUM=''StokKart_Grubu''
	WHERE
		FB.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
		AND FB.TUR IN (15,16)	
--		AND @GRUP=CASE WHEN coalesce(STOKGRUP.ANAHTAR,'''')='''' THEN ''Grupsuz'' ELSE STOKGRUP.ANAHTAR END

	
        
	
	
	
	OPEN SATICILAR
	FETCH NEXT FROM SATICILAR Into @SATICI
	WHILE @@FETCH_STATUS = 0
	BEGIN
		
		
		
	FETCH NEXT FROM SATICILAR Into @SATICI
	END
	CLOSE SATICILAR
	DEALLOCATE SATICILAR
	
	
	
	--PRINT (SUBSTRING('''',1,length('''')-1)||''[''||@SATICI||'']=SUM(ISNULL([''||@SATICI||''],0))''||'','')


	
		'','' || cast(@KT as varchar) ||'' AS K_TOPLAM'' || '','' || cast(@HT as varchar) ||'' AS H_TOPLAM'' ||
                '','' || cast(@IT as varchar) ||'' AS I_TOPLAM'' || '','' || cast(@GT as varchar) ||'' AS G_TOPLAM'' ||
                '','' || cast(@FIS as varchar)||'' AS FIS_''     || '','' || cast(@FATURA as varchar)||'' AS FATURA_'' ||
                '','' || cast(@IADE as varchar)||'' AS IADE_''   || '','' || cast(@TOPLAM as varchar)||'' AS TOPLAM_'' ||
                '',''||SUBSTRING(''''||''SUM(ISNULL([''||@SATICI||''],0))''||''+'',1,length(''''||''SUM(ISNULL([''||@SATICI||''],0))''||''+'')-1)||'' AS GrupToplam'' ||
                '' FROM  gt_TMP_SaticiGrupTutar 
              	GROUP BY GRUP''
		
	EXEC(''SELECT GRUP,''||@SATICIKOLONLARI||'','' || cast(@NT as varchar) ||'' AS N_TOPLAM'' || '','' || cast(@NO as varchar) ||'' AS N_ODEME'' ||)
' WHERE id = 908;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT   
TARIH,        
BASLAMATARIHI,
BITISTARIHI,
DATEDIFF(MINUTE,BASLAMATARIHI,BITISTARIHI) AS CALISMASURE ,
KURUM.FIRMA AS KURUM ,
KEden.FIRMA AS KABUL_EDEN ,
Sorumlu.FIRMA AS SORUMLU ,
BOLUM.ANAHTAR
 AS DURUM FROM SERVIS S
LEFT JOIN REHBER R ON S.ID=R.ID
LEFT JOIN REHBER Sorumlu  ON Sorumlu.ID=S.SORUMLU
LEFT JOIN REHBER KURUM  ON KURUM.ID=S.REHBERID
LEFT JOIN REHBER KEDEN  ON KEDEN.ID=S.KABUL_EDEN
LEFT JOIN GENINI BOLUM ON BOLUM.DEGER=S.DURUM AND BOLUM.BOLUM=-3007
where
	
	S.TARIH >= ''$Baslangic$ 00:00'' AND
        S.TARIH <=  ''$Bitis$ 23:59''   AND
        KURUM.FIRMA LIKE  ''$KURUM$%'' AND
        KEden.FIRMA LIKE  ''$KABUL_EDEN$%''  AND 
        SORUMLU.FIRMA LIKE ''$SORUMLU$%''  AND
        BOLUM.ANAHTAR LIKE ''$DURUM$%''' WHERE id = 910;
