UPDATE public.dokumler SET sql = '/*PGX*/SELECT GRUP,UNVAN,ULKE,VGNO,TCNO,SUM(TUTAR) AS TUTAR,SUM(ADET) AS ADET FROM ( 
SELECT GRUP,UNVAN,ULKE,VGNO,TCNO,
SUM(TUTAR) AS TUTAR,SUM(ADET)
 AS ADET FROM( 
SELECT                             
       FB.ID AS FBID,R.ID AS RID,
       R.KOD AS HESAP_KODU,
       R.FIRMA AS UNVAN,
       1 AS ADET ,
       (SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERILETISIM RI ON RB.YER_ID=RI.ID WHERE RI.REHBERID=R.ID AND ETIKET=''Ülke'' LIMIT 1 ) AS ULKE ,
       --VGNO,
       R.STATU,
      -- TCNO=CASE WHEN STATU=0 THEN VGNO END,
      -- VGNO=CASE WHEN STATU=1 THEN VGNO END,
       case wheN R.STATU=0 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END AS TCNO ,
--      VGNO = case wheN R.STATU=1 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END,
       (SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ) AS VGNO ,
        CASE WHEN coalesce(KDVDURUM,'''')=''Dahil'' THEN FATURA_MATRAHI-KDV_TUTARI ELSE FATURA_MATRAHI END  AS TUTAR ,
        CASE WHEN FB.TUR=11 THEN ''BA''
                 WHEN FB.TUR=12 THEN ''BA''
                 WHEN FB.TUR=15 THEN ''BS''
                 WHEN FB.TUR=16 THEN ''BS'' END   
 AS GRUP FROM REHBER R INNER JOIN FATBASLIK FB ON R.ID=FB.REHBERID
WHERE
	--FATURATARIH BETWEEN ''2014-01-01 00:00:00'' AND ''2014-01-31 23:59:00'' 
	    FATURATARIH BETWEEN ''$Baslama$ 00:00:00'' AND ''$Bitis$ 23:59:00'' 
	AND FB.TUR IN (11,12,15,16)
	AND FB.DURUM NOT IN (6)
AND coalesce(FB.FATURASERI,'''') NOT LIKE ''X%''

) AS X	
GROUP BY 
GRUP,UNVAN,ULKE,VGNO,TCNO
) AS Y
WHERE
	TUTAR>=5000 
	AND GRUP LIKE ''$Grup$%''
 GROUP BY GRUP,UNVAN,ULKE,VGNO,TCNO' WHERE id = 924;
