--K.KOD AS PERSONEL,
--F.SKT AS SON_KULLANMA_TARIHI

--,F.BIRIMFIYAT - coalesce(F.ISKONTO,0) AS ''YSK.B.FYYAT''
FROM FATBASLIK FB 
INNER JOIN FATURA F ON FB.ID = F.FATBASID 
LEFT OUTER JOIN (SELECT ANAHTAR,DEGER FROM REHBERINI WHERE BOLUM=''StokKart_Anabirim'') RI ON F.BIRIM = RI.DEGER
LEFT OUTER JOIN KULLANICI K ON K.REHBERID=F.EKLEYEN
LEFT OUTER JOIN STOKLAR S ON F.URUNID=S.ID 
WHERE
