--coalesce(FB.GIRISDEPO,'''')<>'''' AND
FB.TUR IN (''19'') AND
FB.REHBERID=''-99'' 
AND S.KOD LIKE ''$Kod$%''
AND FB.FATURATARIH >=''$Baslangic$ 00:00''
AND FB.FATURATARIH <=''$Bitis$ 23:59 '' ) AS X
WHERE CIKIS_YERI LIKE ''$CikisDepo$%''' WHERE id = 925;
UPDATE public.dokumler SET sql = '/*PGX*/


SELECT * FROM(
SELECT
1 AS SIRA,
''Satış Fatura'' AS TUR,
''Toplam'' AS DATA,
coalesce(OCAK.TUTAR,0) AS OCAK,
coalesce(SUBAT.TUTAR,0) AS SUBAT,
coalesce(MART.TUTAR,0) AS MART,
coalesce(NISAN.TUTAR,0) AS NISAN,
coalesce(MAYIS.TUTAR,0) AS MAYIS,
coalesce(HAZIRAN.TUTAR,0) AS HAZIRAN,
coalesce(TEMMUZ.TUTAR,0) AS TEMMUZ,
coalesce(AGUSTOS.TUTAR,0) AS AGUSTOS,
coalesce(EYLUL.TUTAR,0) AS EYLUL,
coalesce(EKIM.TUTAR,0) AS EKIM,
coalesce(KASIM.TUTAR,0) AS KASIM,
coalesce(ARALIK.TUTAR,0) AS ARALIK,
KURLAR.KUR
FROM
(SELECT ANAHTAR AS KUR FROM REHBERINI WHERE BOLUM LIKE ''KURLAR'') KURLAR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 1  AND FB.TUR IN (15,16) GROUP BY KUR) OCAK ON OCAK.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 2  AND FB.TUR IN (15,16) GROUP BY KUR) SUBAT ON SUBAT.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 3  AND FB.TUR IN (15,16) GROUP BY KUR) MART ON MART.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 4  AND FB.TUR IN (15,16) GROUP BY KUR) NISAN ON NISAN.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 5  AND FB.TUR IN (15,16) GROUP BY KUR) MAYIS ON MAYIS.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 6  AND FB.TUR IN (15,16) GROUP BY KUR) HAZIRAN ON HAZIRAN.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 7  AND FB.TUR IN (15,16) GROUP BY KUR) TEMMUZ ON TEMMUZ.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 8  AND FB.TUR IN (15,16) GROUP BY KUR) AGUSTOS ON AGUSTOS.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 9  AND FB.TUR IN (15,16) GROUP BY KUR) EYLUL ON EYLUL.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 10  AND FB.TUR IN (15,16) GROUP BY KUR) EKIM ON EKIM.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 11 AND FB.TUR IN (15,16) GROUP BY KUR) KASIM ON KASIM.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 12  AND FB.TUR IN (15,16) GROUP BY KUR) ARALIK ON ARALIK.KUR=KURLAR.KUR

UNION ALL

SELECT
1 AS SIRA,
''Alış Fatura'' AS TUR,
''Toplam'' AS DATA,
coalesce(OCAK.TUTAR,0) AS OCAK,
coalesce(SUBAT.TUTAR,0) AS SUBAT,
coalesce(MART.TUTAR,0) AS MART,
coalesce(NISAN.TUTAR,0) AS NISAN,
coalesce(MAYIS.TUTAR,0) AS MAYIS,
coalesce(HAZIRAN.TUTAR,0) AS HAZIRAN,
coalesce(TEMMUZ.TUTAR,0) AS TEMMUZ,
coalesce(AGUSTOS.TUTAR,0) AS AGUSTOS,
coalesce(EYLUL.TUTAR,0) AS EYLUL,
coalesce(EKIM.TUTAR,0) AS EKIM,
coalesce(KASIM.TUTAR,0) AS KASIM,
coalesce(ARALIK.TUTAR,0) AS ARALIK,
KURLAR.KUR
FROM
(SELECT ANAHTAR AS KUR FROM REHBERINI WHERE BOLUM LIKE ''KURLAR'') KURLAR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 1  AND FB.TUR IN (10,11) GROUP BY KUR) OCAK ON OCAK.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 2  AND FB.TUR IN (10,11) GROUP BY KUR) SUBAT ON SUBAT.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 3  AND FB.TUR IN (10,11) GROUP BY KUR) MART ON MART.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 4  AND FB.TUR IN (10,11) GROUP BY KUR) NISAN ON NISAN.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 5  AND FB.TUR IN (10,11) GROUP BY KUR) MAYIS ON MAYIS.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 6  AND FB.TUR IN (10,11) GROUP BY KUR) HAZIRAN ON HAZIRAN.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 7  AND FB.TUR IN (10,11) GROUP BY KUR) TEMMUZ ON TEMMUZ.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 8  AND FB.TUR IN (10,11) GROUP BY KUR) AGUSTOS ON AGUSTOS.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 9  AND FB.TUR IN (10,11) GROUP BY KUR) EYLUL ON EYLUL.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 10  AND FB.TUR IN (10,11) GROUP BY KUR) EKIM ON EKIM.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 11 AND FB.TUR IN (10,11) GROUP BY KUR) KASIM ON KASIM.KUR=KURLAR.KUR
LEFT OUTER JOIN
(SELECT ROUND(SUM(FB.FATURA_TUTARI),2) AS TUTAR,KUR FROM FATBASLIK FB WHERE YEAR(FB.FATURATARIH) = ''$Yil$'' AND MONTH(FB.FATURATARIH) = 12  AND FB.TUR IN (10,11) GROUP BY KUR) ARALIK ON ARALIK.KUR=KURLAR.KUR
)AS X
 WHERE (OCAK+SUBAT+MART+NISAN+MAYIS+HAZIRAN+TEMMUZ+AGUSTOS+EYLUL+EKIM+KASIM+ARALIK) >0
' WHERE id = 927;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
 YEAR(FATURATARIH) AS YIL,
''Giriş'' AS TUR,
S.KOD,
S.STOKADI,
R.FIRMA,
FB.FATURATARIH,
FB.FATURANO,
F.ADET,
RI.ANAHTAR AS BIRIM,
F.BIRIMFIYAT,
F.ISKONTO,
F.TUTAR,
F.KDV,
D.DEPOADI
FROM FATBASLIK FB 
INNER JOIN FATURA F ON FB.ID = F.FATBASID 
INNER JOIN DEPOLAR D ON FB.GIRISDEPO = D.ID
LEFT OUTER JOIN STOKLAR S ON F.URUNID=S.ID
LEFT OUTER JOIN REHBER R ON FB.REHBERID = R.ID
INNER JOIN (SELECT ANAHTAR,DEGER FROM REHBERINI WHERE BOLUM=''StokKart_Anabirim'') RI ON F.BIRIM = RI.DEGER
 
WHERE
coalesce(FB.GIRISDEPO,'''')<>'''' AND
FB.TUR IN (''11'',''12'') 
AND S.KOD LIKE ''$Kod$%''
AND FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND D.DEPOADI LIKE ''$DepoAdi$%''

UNION  ALL

SELECT
YEAR(FATURATARIH) AS YIL,
''Transfer'' AS TUR,
S.KOD,
S.STOKADI,
D.DEPOADI AS FIRMA,
FB.FATURATARIH,
FB.FATURANO,
F.ADET,
RI.ANAHTAR AS BIRIM,
cast(0 as double precision) AS BIRIMFIYAT,
0 AS ISKONTO,
cast(0 as double precision)AS TUTAR,
0 AS KDV,
D.DEPOADI
FROM FATBASLIK FB 
INNER JOIN FATURA F ON FB.ID = F.FATBASID 
INNER JOIN DEPOLAR D ON FB.GIRISDEPO = D.ID
LEFT OUTER JOIN STOKLAR S ON F.URUNID=S.ID
INNER JOIN (SELECT ANAHTAR,DEGER FROM REHBERINI WHERE BOLUM=''StokKart_Anabirim'') RI ON F.BIRIM = RI.DEGER 
WHERE
FB.TUR IN (''19'') AND
FB.REHBERID=''-99'' 
AND S.KOD LIKE ''$Kod$%''
AND FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND D.DEPOADI LIKE ''$DepoAdi$%''

UNION ALL

SELECT
YEAR(SS.SAYIMTARIHI) AS YIL,
''Devir'' AS TUR,
S.KOD,
S.STOKADI, 
'''' AS FIRMA,
'''' AS FATURATARIH,
'''' AS FATURANO,
SSK.SAYIMMIKTAR AS ADET,
RI.ANAHTAR AS BIRIM,
SSK.BIRIMFIYAT,
0 AS ISKONTO,
0 AS TUTAR,
0 AS KDV,
D.DEPOADI
FROM STOKSAYIM SS 
INNER JOIN STOKSAYIMKALEMLERI SSK ON SS.ID = SSK.SAYIMID 
INNER JOIN DEPOLAR D ON SS.SAYIMDEPO = D.ID
LEFT OUTER JOIN STOKLAR S ON S.ID = SSK.STOKID
INNER JOIN (SELECT ANAHTAR,DEGER FROM REHBERINI WHERE BOLUM=''StokKart_Anabirim'') RI ON S.ID = RI.DEGER
WHERE S.KOD LIKE ''$Kod$%'' AND

cast(SS.SAYIMDEPO as varchar)||''-''||cast(SSK.STOKID as varchar)||''-''||to_char(SAYIMTARIHI,''DD/MM/YYYY'') IN

(SELECT cast(X.SAYIMDEPO as varchar)||''-''||cast(X.STOKID as varchar)||''-''||to_char(SAYIMTARIHI,''DD/MM/YYYY'') FROM 
(SELECT SS.SAYIMDEPO,SSK.STOKID,MAX(SS.SAYIMTARIHI) AS SAYIMTARIHI 
FROM STOKSAYIM SS 
INNER JOIN STOKSAYIMKALEMLERI SSK ON SS.ID = SSK.SAYIMID 
INNER JOIN STOKLAR S ON S.ID = SSK.STOKID 
GROUP BY SS.SAYIMDEPO ,SSK.STOKID )  X)
ORDER BY D.DEPOADI,TUR' WHERE id = 929;
UPDATE public.dokumler SET sql = '/*PGX*/--GrafikTipi
--Kolon
--Altayaz
--$Yil$ Aylar
--Kategori
--AYADI
--Seriler
--Seri GIREN/Alış
--Seri CIKAN/Satış
SET LANGUAGE Turkish
SELECT 
AY,
AYADI,    
GIREN=SUM(TOPLAM_GIREN), 
CIKAN=SUM(TOPLAM_CIKAN)  
FROM (
SELECT   
AY=MONTH(FATURATARIH) , 
AYADI= DATENAME(month, FATURATARIH),

TOPLAM_GIREN=CASE WHEN TUR IN(11,12) THEN SUM(FATURA_MATRAHI) ELSE 0 END,
TOPLAM_CIKAN=CASE WHEN TUR IN(15,16) THEN SUM(FATURA_MATRAHI) ELSE 0 END
FROM  FATBASLIK
where year(FATURATARIH)= $Yil$ 
group by TUR, MONTH(FATURATARIH), DATENAME(month, FATURATARIH)
 ) AS ASD
 GROUP BY 
 AY,
AYADI
 order by 1
SET LANGUAGE us_english' WHERE id = 930;
UPDATE public.dokumler SET sql = '/*PGX*/--GrafikTipi
--Kolon
--Kategori
--YIL
--Seriler
--Seri GIREN/Alış
--Seri CIKAN/Satış

select YIL, 
GIREN=SUM(TOPLAM_GIREN), 
CIKAN=SUM(TOPLAM_CIKAN)  
from(
SELECT   
YIL=YEAR(FATURATARIH) , 
TOPLAM_GIREN=CASE WHEN TUR IN(11,12,13) THEN SUM(FATURA_MATRAHI) ELSE 0 END,
TOPLAM_CIKAN=CASE WHEN TUR IN(15,16,17) THEN SUM(FATURA_MATRAHI) ELSE 0 END
FROM  FATBASLIK
where 
FATURATARIH between ''$Basl$-01-01 00:00'' and ''$Bit$-12-31 23:59''
group by TUR, year(FATURATARIH)
) as YILLAR
group by YIL
 order by 1' WHERE id = 931;
UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Kolon
--Kategori
--YIL
--Seriler
--Seri TOPLAM/Toplam
select YIL=YEAR(EKLEMETARIHI),TOPLAM=count(G.ID)  
from GOREVLER G
where 
  EKLEYEN like ''$Sorumlu$%''
  and coalesce(TURU,'''') like ''$Turu$%''
  and coalesce(KONUSU,'''') like ''$Konusu$%''

group by YEAR(EKLEMETARIHI)' WHERE id = 932;
UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Kolon
--Aylık Kabuller
--Kategori
--AYADI
--Seriler
--Seri TOPLAM/Toplam
SET LANGUAGE Turkish

select month(BASLAMATARIHI), AYADI= DATENAME(month, BASLAMATARIHI), TOPLAM=count(ID)
from GOREVLER G
where 
      year(BASLAMATARIHI)= $Yil$  
  and EKLEYEN like ''$Sorumlu$%''
  and coalesce(TURU,'''') like ''$Turu$%''
  and coalesce(KONUSU,'''') like ''$Konusu$%''
group by month(BASLAMATARIHI), DATENAME(month, BASLAMATARIHI)  
order by 1

SET LANGUAGE us_english' WHERE id = 933;
UPDATE public.dokumler SET sql = '/*PGX*/--Grafiktipi
--Kolon
--Aylık Kabuller
--Kategori
--GUN
--Seriler
--Seri TOPLAM/Toplam

select  GUN= day(BASLAMATARIHI), TOPLAM=count(ID)

 from GOREVLER G
where 
      year(BASLAMATARIHI)= $Yil$  
  and month(BASLAMATARIHI)= $Ay$  
  and EKLEYEN like ''$Sorumlu$%''
  and coalesce(TURU,'''') like ''$Turu$%''
  and coalesce(KONUSU,'''') like ''$Konusu$%''
group by month(BASLAMATARIHI), DAY(BASLAMATARIHI)  
order by 1' WHERE id = 934;
UPDATE public.dokumler SET sql = '/*PGX*/--GrafikTipi
--Kolon
--Altayaz
--$Yil$ Aylar
--Kategori
--AYADI
--Seriler
--Seri CIKAN/Hedef
--Seri GIREN/Gerçekleşen
SET LANGUAGE Turkish
SELECT
AY,
AYADI,
GIREN=SUM(TOPLAM_GIREN),
CIKAN=SUM(TOPLAM_CIKAN)
FROM (
SELECT
AY=MONTH(ISLEMTARIHI) ,
AYADI= DATENAME(month, ISLEMTARIHI),

TOPLAM_GIREN=coalesce(sum(ALACAK-BORC),0.0),
TOPLAM_CIKAN=0
FROM KASA K 
where year(ISLEMTARIHI)= $Yil$
AND TUR IN (21,22,23,24,25)
AND coalesce(MASRAFID,'''')<>''''
group by MONTH(ISLEMTARIHI), DATENAME(month, ISLEMTARIHI)

UNION ALL
SELECT
AY,
AYADI= CASE WHEN AY=1  THEN ''Ocak''
			WHEN AY=2  THEN ''Şubat''
			WHEN AY=3  THEN ''Mart''
			WHEN AY=4  THEN ''Nisan''
			WHEN AY=5  THEN ''Mayıs''
			WHEN AY=6  THEN ''Haziran''
			WHEN AY=7  THEN ''Temmuz''
			WHEN AY=8  THEN ''Ağustos''
			WHEN AY=9  THEN ''Eylül''
			WHEN AY=10 THEN ''Ekim''
			WHEN AY=11 THEN ''Kasım''
			WHEN AY=12 THEN ''Aralık'' ELSE '''' END,
			
TOPLAM_GIREN=0,
TOPLAM_CIKAN=PLANLANAN
FROM BUTCE B INNER JOIN MASRAFGELIR MG ON B.MASRAFID=MG.ID
where YIL= $Yil$ AND GELIRMI=1
group by AY,PLANLANAN
) AS ASD
GROUP BY
AY,
AYADI
order by 1
SET LANGUAGE us_english' WHERE id = 935;
UPDATE public.dokumler SET sql = '/*PGX*/--GrafikTipi
--Kolon
--Altayaz
--$Yil$ Aylar
--Kategori
--AYADI
--Seriler
--Seri CIKAN/Hedef
--Seri GIREN/Gerçekleşen
SET LANGUAGE Turkish
SELECT
AY,
AYADI,
GIREN=SUM(TOPLAM_GIREN),
CIKAN=SUM(TOPLAM_CIKAN)
FROM (
SELECT
AY=MONTH(ISLEMTARIHI) ,
AYADI= DATENAME(month, ISLEMTARIHI),

TOPLAM_GIREN=abs(coalesce(sum(ALACAK-BORC),0.0)),
TOPLAM_CIKAN=0
FROM KASA K 
where year(ISLEMTARIHI)= $Yil$
AND TUR IN (31,32,33,34,35)
AND coalesce(MASRAFID,'''')<>''''
group by MONTH(ISLEMTARIHI), DATENAME(month, ISLEMTARIHI)

UNION ALL
SELECT
AY,
AYADI= CASE WHEN AY=1  THEN ''Ocak''
			WHEN AY=2  THEN ''Şubat''
			WHEN AY=3  THEN ''Mart''
			WHEN AY=4  THEN ''Nisan''
			WHEN AY=5  THEN ''Mayıs''
			WHEN AY=6  THEN ''Haziran''
			WHEN AY=7  THEN ''Temmuz''
			WHEN AY=8  THEN ''Ağustos''
			WHEN AY=9  THEN ''Eylül''
			WHEN AY=10 THEN ''Ekim''
			WHEN AY=11 THEN ''Kasım''
			WHEN AY=12 THEN ''Aralık'' ELSE '''' END,
			
TOPLAM_GIREN=0,
TOPLAM_CIKAN=PLANLANAN
FROM BUTCE B INNER JOIN MASRAFGELIR MG ON B.MASRAFID=MG.ID
where YIL= $Yil$ AND GELIRMI=1
group by AY,PLANLANAN
) AS ASD
GROUP BY
AY,
AYADI
order by 1
SET LANGUAGE us_english' WHERE id = 936;
UPDATE public.dokumler SET sql = '/*PGX*/












SELECT @NT = NAKITTOPLAM,@NO=NAKITODEME,@KT=VISATOPLAM,@HT=HEDIYETOPLAM,@IT=IADECEKITOPLAM,@GT = GENELTOPLAM FROM fn_TURTOPLA2  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')
SELECT @FIS=FIS ,@FATURA=FATURA,@IADE=IADE,@TOPLAM=TOPLAM FROM fn_SATISBELGETOPLAM  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')                                                                              

select
         ANAHTAR,cast(TUTAR as double precision)AS TUTAR,SATICI,TURTOPLAMTUTAR,
         @NT AS NAKITTOPLAM,
         @NO AS NAKITODEME,
         @KT AS VISATOPLAM,
         @HT AS HEDIYETOPLAM,
         @IT AS IADECEKITOPLAM,
         @GT AS GENELTOPLAM,
         @FIS AS FIS,
         @FATURA AS FATURA,
         @IADE AS IADE,
         @TOPLAM AS TOPLAM
FROM (

SELECT

CASE WHEN coalesce(ANAHTAR,'''')='''' THEN ''Kategorisiz'' ELSE ANAHTAR END AS ANAHTAR ,
round((SUM(TUTAR)),2) AS TUTAR,
SATICI,
TURTOPLAMTUTAR
FROM (



select

KTG.AD AS ANAHTAR,
CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*((F.KDV/100.0)+1.0) ELSE F.TUTAR END AS TUTAR ,
(SELECT FIRMA FROM REHBER R1 WHERE R1.ID=FB.SATICIKODU)  AS SATICI ,
A.TUTAR AS TURTOPLAMTUTAR


from
FATBASLIK FB left JOIN FATURA F  ON FB.ID=F.FATBASID
	     left outer join MASRAFGELIR MG on F.URUNID = MG.ID
	     LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
             LEFT JOIN KATEGORI KTG ON S.KATEGORI=KTG.ID
	     LEFT JOIN fn_STOKTURTOPLAMI (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'') A ON coalesce(A.ANAHTAR,''Kategorisiz'')=coalesce(KTG.AD,''Kategorisiz'')
             LEFT JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0


WHERE

        FB.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND FB.TUR IN (15,16)
    AND R.FIRMA LIKE ''$Sube$%''


 ) AS X

GROUP BY ANAHTAR,SATICI,TURTOPLAMTUTAR
 
 ) AS Y
' WHERE id = 937;
