UPDATE public.dokumler SET sql = '/*PGX*/select 
(case when length(cast(datepart(hh,FATURATARIH) as varchar))=1 then ''0''||cast(datepart(hh,FATURATARIH) as varchar) else cast(datepart(hh,FATURATARIH) as varchar) end)||'':00 - ''||(case when length(cast(datepart(hh,FATURATARIH) as varchar))=1 then ''0''||cast(datepart(hh,FATURATARIH) as varchar) else cast(datepart(hh,FATURATARIH) as varchar) end)||'':59'' AS SAAT ,
(select count(*) from TEKLIF T where datepart(hh,T.TARIH)=datepart(hh,FATURATARIH)) AS TEKLIFMIKTAR ,
coalesce((select sum(TEKLIF_MATRAHI)  from TEKLIF T where datepart(hh,T.TARIH)=datepart(hh,FATURATARIH)),0) AS TEKLIFTUTAR ,
(select count(*) from SIPARIS S where S.TUR=19 and datepart(hh,S.SIPARISTARIH)=datepart(hh,FATURATARIH)) AS SIPARISMIKTAR ,
coalesce((select sum(SIPARIS_MATRAHI) from SIPARIS S where S.TUR=19 and datepart(hh,S.SIPARISTARIH)=datepart(hh,FATURATARIH)),0) AS SIPARISTUTAR ,
sum(case when FB.TUR=14 then 1 else 0 end) AS IRSALIYEMIKTAR ,
sum(case when FB.TUR=14 then FATURA_MATRAHI else 0.0 end) AS IRSALIYEMATRAH ,
sum(case when FB.TUR=15 then 1 else 0 end) AS FATURAMIKTAR ,
sum(case when FB.TUR=15 then FATURA_MATRAHI else 0.0 end) AS FATURAMATRAH ,
sum(case when FB.TUR=16 then 1 else 0 end) AS FISMIKTAR ,
sum(case when FB.TUR=16 then FATURA_MATRAHI else 0.0 end)

 AS FISMATRAH from FATBASLIK FB
where
       FB.TUR in (14,15,16)and
       FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
group by datepart(hh,FATURATARIH)
order by datepart(hh,FATURATARIH)' WHERE id = 960;
