UPDATE public.dokumler SET sql = '/*PGX*/



SELECT FIRMA AS KURUM ,
	   SUM(OCAK) AS OCAK,
	   SUM(SUBAT) AS SUBAT,
	   SUM(MART) AS MART,
	   SUM(NISAN) AS NISAN,
	   SUM(MAYIS) AS MAYIS,
	   SUM(HAZIRAN) AS HAZIRAN,
	   SUM(TEMMUZ) AS TEMMUZ,
	   SUM(AGUSTOS) AS AGUSTOS,
	   SUM(EYLUL) AS EYLUL,
	   SUM(EKIM) AS EKIM,
	   SUM(KASIM) AS KASIM,
	   SUM(ARALIK) AS ARALIK,
           SUM(TOPLAM) AS TOPLAM
 FROM (
SELECT R.FIRMA,COUNT(S.ID) AS OCAK ,0 AS SUBAT ,0 AS MART ,0 AS NISAN ,0 AS MAYIS ,0 AS HAZIRAN ,0 AS TEMMUZ ,0 AS AGUSTOS ,0 AS EYLUL ,0 AS EKIM ,0 AS KASIM ,0 AS ARALIK ,0
