SELECT R.FIRMA,0 AS OCAK ,0 AS SUBAT ,0 AS MART ,0 AS NISAN ,0 AS MAYIS ,0 AS HAZIRAN ,0 AS TEMMUZ ,0 AS AGUSTOS ,COUNT(S.ID) AS EYLUL ,0 AS EKIM ,0 AS KASIM ,0 AS ARALIK ,0
