' WHERE id = 970;
UPDATE public.dokumler SET sql = '/*PGX*/



SELECT * FROM (
SELECT 
       SB.ACIKLAMA,
       SB.COZUM,
       CASE WHEN ASAMA=10 THEN ''Analiz''
				  WHEN ASAMA=20 THEN ''Tasarım''
				  WHEN ASAMA=30 THEN ''Geliştirme''
				  WHEN ASAMA=40 THEN ''Alfa Test''
				  WHEN ASAMA=41 THEN ''Beta Test''
				  WHEN ASAMA=42 THEN ''Yayınlama''
			 END AS ASAMA ,
       SA.ACIKLAMA AS AS_ACIKLAMA ,
       RR.FIRMA AS SORUMLU ,
       SA.BASTAR,
       SA.BITTAR,
       G.ANAHTAR,
       DATEDIFF(DAY,SA.BASTAR,SA.BITTAR)
 AS SURE FROM SERVISASAMA SA INNER JOIN SERVIS S ON S.ID=SA.SERVISID
                    INNER JOIN SERVISBILGI SB ON SB.SERVISID=S.ID
                    INNER JOIN GENINI G ON G.DEGER=SA.DURUM AND G.BOLUM=-3027
                    INNER JOIN REHBER RR ON RR.ID=SA.REHBERID
WHERE S.REHBERID=''9360''
      AND S.EKIPMANID=5
      AND S.EKLEYEN=6019 ) AS X
WHERE ASAMA LIKE ''$Asama$''||''%''
' WHERE id = 974;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT ANAHTAR,SURE,COUNT(ANAHTAR)  AS SAYI FROM (
SELECT 
       ANAHTAR,DATEDIFF(DAY,BASTAR,BITTAR)
 AS SURE FROM SERVISASAMA SA INNER JOIN SERVIS S ON S.ID=SA.SERVISID
                    INNER JOIN GENINI G ON G.DEGER=SA.ASAMA AND BOLUM=-30025
WHERE S.REHBERID=''9360''
      AND S.EKLEYEN=6019
	  AND ASAMA=10
) AS X
GROUP BY ANAHTAR,SURE' WHERE id = 975;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT R.FIRMA,D.AD
FROM DOKUMANGECMIS DG INNER JOIN DOKUMAN D ON D.ID=DG.DOKUMANID
					 INNER JOIN REHBER R ON R.ID=DG.EKLEYEN
WHERE ACIKLAMA=''Belge görüldü''
	  AND (AD LIKE ''FRM%''
	  OR AD LIKE ''GEN%''
	  OR AD LIKE ''KALİTE HEDEFLERİ 2015.docx%''
	  OR AD LIKE ''MTD%''
	  OR AD LIKE ''RPR%'')
ORDER BY 2' WHERE id = 979;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT to_char(FATURATARIH,''DD/MM/YYYY'') AS FATURA_TARIHI,FATURANO,R.KOD AS HESAP_KODU,R.FIRMA AS HESAP_ADI,
F.FATURA_MATRAHI+coalesce((SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ),0) AS ARA_TOPLAM,
KDV_TUTARI AS KDV,
(SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ) AS INDIRIM,
FATURA_TUTARI AS NET_TOPLAM  FROM REHBER R INNER JOIN FATBASLIK F ON R.ID=F.REHBERID
WHERE
FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''
and TUR in (11)
order by  FATURATARIH' WHERE id = 980;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
     TUR AS ISLEM_TURU,
     CARIKOD,
     CARIAD,
     KASAKODU,
     KASAADI,
     coalesce(BORC,0) AS BORC,
     coalesce(ALACAK,0) AS ALACAK,
     KUR
     FROM
(SELECT
RI2.ANAHTAR AS TUR,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
KS.KASAKODU,
KS.KASAADI,
case when K.BORC>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.BORC end AS  BORC,                            
case when K.ALACAK>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.ALACAK end AS ALACAK,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else K.KUR end as KUR

FROM KASA K 
LEFT OUTER JOIN REHBER R ON K.REHBERID=R.ID
LEFT OUTER JOIN (SELECT KL.REHBERID,KL.KOD,R.FIRMA FROM KULLANICI KL INNER JOIN REHBER R ON R.ID=KL.REHBERID) X ON K.EKLEYEN = X.REHBERID
LEFT OUTER JOIN BANKAHESAPLAR BH ON K.HESAPID=BH.ID AND K.HESAPTURU=''B''
LEFT OUTER JOIN KASALAR KS ON K.HESAPID=KS.ID AND K.HESAPTURU=''K''
LEFT OUTER JOIN MASRAFGELIR MG ON K.MASRAFID=MG.ID
LEFT OUTER JOIN REHBERINI RI2 ON RI2.BOLUM =''Kasa Türleri'' AND RI2.DEGER=K.TUR
  
WHERE 
     ISLEMTARIHI >=''$Baslangic$ 00:00'' AND
     ISLEMTARIHI <=''$Bitis$ 23:59'' AND
     coalesce(KS.KASAKODU,'''') LIKE ''$KasaKodu$%'' AND
     K.TUR IN (1,2,21,22,25,31,32,35,41,42,43,45,46,47,48,51,52,53,54,71,72,73,111,121,122) AND
     coalesce(KS.KASAKODU,'''')<>''''
     
) AS X WHERE coalesce(KASAKODU,'''') LIKE ''$KasaKodu$%''
ORDER BY KASAKODU
/*
SELECT
CASE WHEN X.TUR=41 THEN ''Kasadan Bankaya Transfer'' 
     WHEN X.TUR=42 THEN ''Bankadan Kasaya Transfer''
     WHEN X.TUR=43 THEN ''Banka Hesaplar Arası Transfer''
     WHEN X.TUR=45 THEN ''Kasadaki TL İle Döviz Alma''
     WHEN X.TUR=46 THEN ''Kasadaki Dövizle TL ALma''
     WHEN X.TUR=47 THEN ''Bankadaki TL İle Döviz Alma''
     WHEN X.TUR=48 THEN ''Bankadaki Döviz İle TL Alma''
     WHEN X.TUR=51 THEN ''Bankadan Çek Tahsil Etme''
     WHEN X.TUR=52 THEN ''Bankadan Senet Tahsil Etme''
     WHEN X.TUR=53 THEN ''Verilen Çek Banka Ödeme''
     WHEN X.TUR=54 THEN ''Verilen Senet Banka Ödeme''
     WHEN X.TUR=111 THEN ''Alınmış Kredi Taksit Ödeme''
     WHEN X.TUR=121 THEN ''Bankodan Kredi Kart Girişi''
     WHEN X.TUR=122 THEN ''Bankodan Nakit Girişi''
     WHEN X.TUR =11 THEN ''Alış Fatura''
     WHEN X.TUR =11 THEN ''Alış Fiş''
     WHEN X.TUR =15 THEN ''Borç Fatura''
     WHEN X.TUR =15 THEN ''Borç Fiş''
     WHEN X.TUR= 21 THEN ''Müşteriden Nakit Girişi''
     WHEN X.TUR= 22 THEN ''Müşteriden Bankaya Gönderim''
     WHEN X.TUR= 23 THEN ''Müşteriden Çek Senet Alma''
     WHEN X.TUR= 24 THEN ''Müşteriden Çek Senet Alma''
     WHEN X.TUR= 25 THEN ''Kredi Kartı İle Tahsilat''
     WHEN X.TUR= 31 THEN ''Müşteriye Nakit Çıkışı''
     WHEN X.TUR= 32 THEN ''Müşteri Banka Hesabına Ödeme''
     WHEN X.TUR= 33 THEN ''Müşteriye Çek Senetle Ödeme''
     WHEN X.TUR= 34 THEN ''Müşteriye Çek Senetle Ödeme''
     WHEN X.TUR= 35 THEN ''Kredi Kartı ile ödeme''
     WHEN X.TUR= 61 THEN ''Tahsilat Planı''
     WHEN X.TUR= 62 THEN ''Düzenli Tahsilat''
     WHEN X.TUR= 71 THEN ''Ödeme Planı''
     WHEN X.TUR= 72 THEN ''Düzenli Ödeme''
     WHEN X.TUR= 73 THEN ''Personel Maaş'' ELSE '''' END AS ''ISLEM_TURU'',
     TUR,
     CARIKOD,
     CARIAD,
     ACIKLAMA,
     HESAPTURU,
     HESAPADI,
     HESAPKODU,
     KASAKODU,
     KASAADI,
     BORC,
     ALACAK,
     KUR,
     MASRAFKOD,
     MASRAFAD,
     KULLANICI_KODU,
     KULLANICI
     FROM
(SELECT
K.TUR AS TUR,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
CASE WHEN coalesce(K.ACIKLAMA,'''')<>'''' THEN K.ACIKLAMA ELSE KX.HEDEF_HESAPADI+(CASE WHEN K.ID <K.GERIDONUSID THEN ''==>''||cast(KX.ID as varchar) ELSE ''<==''||cast(K.ID as varchar) END) END AS ACIKLAMA ,
CASE coalesce(K.HESAPTURU,'''') WHEN ''B'' THEN ''BANKA''
                            WHEN ''K'' THEN ''KASA''
                            WHEN ''V'' THEN ''VISA''
                            WHEN ''P'' THEN ''POS'' END AS HESAPTURU,

CASE coalesce(K.HESAPTURU,'''') WHEN ''B'' THEN BH.HESAPADI
                            WHEN ''K'' THEN KS.KASAADI ELSE '''' END AS HESAPADI,

CASE coalesce(K.HESAPTURU,'''') WHEN ''B'' THEN BH.HESAPKODU
                            WHEN ''K'' THEN KS.KASAKODU ELSE '''' END AS HESAPKODU,
                                                        
KS.KASAKODU,
KS.KASAADI,
case when K.BORC>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.BORC end AS  BORC,                            
case when K.ALACAK>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.ALACAK end AS ALACAK,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else K.KUR end as KUR,
MG.KOD AS MASRAFKOD,
MG.AD AS MASRAFAD,                            
X.KOD AS KULLANICI_KODU,
X.FIRMA AS KULLANICI                                                        
FROM KASA K 
LEFT OUTER JOIN REHBER R ON K.REHBERID=R.ID
LEFT OUTER JOIN (SELECT KL.REHBERID,KL.KOD,R.FIRMA FROM KULLANICI KL INNER JOIN REHBER R ON R.ID=KL.REHBERID) X ON K.EKLEYEN = X.REHBERID
LEFT OUTER JOIN BANKAHESAPLAR BH ON K.HESAPID=BH.ID AND K.HESAPTURU=''B''
LEFT OUTER JOIN KASALAR KS ON K.HESAPID=KS.ID AND K.HESAPTURU=''K''
LEFT OUTER JOIN MASRAFGELIR MG ON K.MASRAFID=MG.ID
LEFT OUTER JOIN 
             (SELECT K2.GERIDONUSID,K2.ID,CASE coalesce(K2.HESAPTURU,'''') WHEN ''B'' THEN BH2.HESAPADI WHEN ''K'' THEN KS2.KASAADI ELSE '''' END AS HEDEF_HESAPADI 
              FROM KASA K2 
              LEFT OUTER JOIN KASALAR KS2 ON K2.HESAPID=KS2.ID AND K2.HESAPTURU=''K''
              LEFT OUTER JOIN BANKAHESAPLAR BH2 ON K2.HESAPID=BH2.ID AND K2.HESAPTURU=''B'' 
              WHERE ISLEMTARIHI >=''$Baslangic$ 00:00'' AND ISLEMTARIHI <=''$Bitis$ 23:59'' ) KX ON KX.GERIDONUSID=K.ID   
WHERE 
     ISLEMTARIHI >=''$Baslangic$ 00:00'' AND
     ISLEMTARIHI <=''$Bitis$ 23:59'' AND
     K.TUR IN (1,2,21,22,25,31,32,35,41,42,43,45,46,47,48,51,52,53,54,71,72,73,111,121,122)
     
) AS X WHERE coalesce(KASAKODU,'''') LIKE ''$KasaKodu$%''
ORDER BY HESAPKODU
*/' WHERE id = 981;
UPDATE public.dokumler SET sql = '/*PGX*/
		@KASAID			VARCHAR(20),
		@HESAPADI		VARCHAR(50),
		@YERID			INT,
		''$Baslangic$ 00:00''		DATETIME,
		''$Bitis$ 23:59''		DATETIME,
		@ACILISTUTARI	MONEY,
		@KAPANISTUTARI	MONEY,
		@NAKITTAHSILAT	MONEY

                                    






--ÖNCE AKTİF KASATAKIP kaydından değerleri alalım, 0 gelirse max kayıt alınıp son oturum gösterilebilir.
SELECT --''$Baslangic$ 00:00'' = ACILISTARIHI, ''$Bitis$ 23:59'' = coalesce(KAPANISTARIHI,now()), 
		@HESAPID = HESAPID,  @ACILISTUTARI = coalesce(ACILISTUTARI,0) , 
		@KAPANISTUTARI = coalesce(KAPANISTUTARI,0),
		@YERID=ID
FROM	KASATAKIP 

WHERE	
		--HESAPID=@KASAID 
		ACILISTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''

SELECT @HESAPADI = KASAKODU+''-''+KASAADI FROM KASALAR WHERE ID = @HESAPID

-- O Nakit tahsilatlarını değişkenlere alıyoruz toplam hesaplarında kullanılacak
SELECT 
	@NAKITTAHSILAT =SUM(coalesce(K.ALACAK,0))
FROM 
	KASA K INNER JOIN REHBER R
ON
	K.REHBERID = R.ID
WHERE
	
	--K.HESAPID = @KASAID AND
	K.YERID   = @YERID AND 
	ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND YERI = 401 


 --değerler alındıktan sonra sorgumuz çalışabilir  
SELECT GRUP, SIRA, ACIKLAMA, SUM(ADET) ADET, SUM(TOPLAM) TOPLAM , 
   BASLANGIC = ''$Baslangic$ 00:00'', BITIS = ''$Bitis$ 23:59'', HESAPID = @HESAPID, HESAPADI = @HESAPADI , KASATAKIPNO = @HESAPID,YERID
 FROM
(
SELECT 

   GRUP = ''Girişler'',
   SIRA = 0,
   ACIKLAMA = ''Kasa Açılış'',
   ADET = 1,
   TOPLAM = ACILISTUTARI,
   YERID=ID
   
   FROM KASATAKIP K
   
   WHERE
   
   ACILISTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
UNION ALL
SELECT 
	GRUP =''Girişler'',
    SIRA = 1,
	R.FIRMA AS ACIKLAMA,
	ADET=COUNT(*),
	TOPLAM=SUM(K.ALACAK),
	coalesce(K.YERID,0)
FROM 
	KASA K INNER JOIN REHBER R
ON
	K.REHBERID = R.ID
WHERE
	    ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND YERI = 401 
    --AND HESAPID = @KASAID
GROUP BY 
	R.FIRMA,YERID
UNION ALL

SELECT

	GRUP =''Girişler Dağılımı'',
        SIRA =2,
	ACIKLAMA=CASE WHEN K.HESAPTURU=''K'' THEN (SELECT KASAADI  FROM KASALAR K1 WHERE K1.ID=K.HESAPID)
			 WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR K1 WHERE K1.ID=K.HESAPID)
			 WHEN K.HESAPTURU=''P'' THEN (SELECT ADI      FROM POS K1           WHERE K1.ID=K.HESAPID)
			ELSE ''X'' END
			 ,
	ADET=COUNT(*),
	TOPLAM= SUM(K.ALACAK),
	K.YERID
FROM 
	KASA K  INNER JOIN KASATAKIP KT ON K.YERID=KT.ID
WHERE
            K.ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''	
        AND K.YERI = 401 
        AND K.HESAPID = KT.HESAPID
GROUP BY
	K.HESAPTURU,K.HESAPID,K.YERID
HAVING SUM(K.BORC)-SUM(K.ALACAK)<>0


UNION ALL


SELECT
	GRUP=''Çıkışlar'',
	SIRA=3,
        ACIKLAMA=CASE WHEN K.HESAPTURU=''K'' THEN (SELECT KASAADI  FROM KASALAR K1       WHERE K1.ID=K.HESAPID)
		      WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR K1 WHERE K1.ID=K.HESAPID)
			 ELSE ''Y '' END,
	ADET=COUNT(*),
	TOPLAM=SUM(K.BORC),
	YERID

FROM 
	KASA K 

WHERE
	    ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
        AND YERI = 401 
        --AND HESAPID = @KASAID 

GROUP BY HESAPTURU,HESAPID,YERID

UNION ALL

SELECT 

   GRUP = ''Kalan'',
   SIRA = 5,
   ACIKLAMA = ''Gerçekleşen Nakit'',
   ADET = 1,
   TOPLAM = coalesce(ACILISTUTARI,0) + SUM(coalesce(K.ALACAK,0)),
   YERID=KT.ID
   
   FROM KASATAKIP KT INNER JOIN  KASA K ON KT.ID=K.YERID
   
   WHERE
   
   KT.EKLEMETARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''   AND
   K.YERI=401  and
   K.HESAPTURU=''K'' AND
   K.HESAPID=KT.HESAPID
   
   GROUP BY KT.ID,KT.ACILISTARIHI,KT.ACILISTUTARI
 
UNION ALL
SELECT 
	GRUP = ''Kalan'',
	SIRA = 6,
	ACIKLAMA = ''Eldeki Nakit'',
	ADET = 1,
	TOPLAM =coalesce(KAPANISTUTARI,0),
        YERID=ID
   
   FROM KASATAKIP K
   
   WHERE
   
   KAPANISTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
	
UNION ALL
SELECT 
	GRUP = ''Kalan'',
	SIRA = 7,
	ACIKLAMA = ''Fark'',
	ADET = 1,
	TOPLAM = coalesce(ACILISTUTARI,0) + SUM(coalesce(K.ALACAK,0)) - KAPANISTUTARI,
	YERID=KT.ID
 
FROM KASATAKIP KT INNER JOIN  KASA K ON KT.ID=K.YERID
   
WHERE
   
   KT.EKLEMETARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''   AND
   K.YERI=401 and
   K.HESAPTURU=''K''  AND
   K.HESAPID=KT.HESAPID
   
GROUP BY KT.ID,KT.ACILISTARIHI,KT.ACILISTUTARI,KT.KAPANISTUTARI
 
UNION ALL
SELECT
	GRUP=''Belgeler'',
	SIRA=8 ,
    ACIKLAMA=CASE 
		WHEN K.TUR=8 THEN  ''Gider Pusulası''
		WHEN K.TUR=10 THEN ''Alış İrsaliyesi''
		WHEN K.TUR=11 THEN ''Alış Faturası''
		WHEN K.TUR=12 THEN ''Alış Fişi''
		WHEN K.TUR=13 THEN ''Alacak Tahakkuku''
		WHEN K.TUR=14 THEN ''Satış İrsaliyesi''
		WHEN K.TUR=15 THEN ''Satış Faturası''
		WHEN K.TUR=16 THEN ''Satış Fişi''
		WHEN K.TUR=17 THEN ''Borç Tahakkuku'' 
		ELSE ''XX'' 
	END,

	ADET=COUNT(*),
	TOPLAM=SUM(FATURA_TUTARI),
	YERID=KASATAKIPID

FROM
	FATBASLIK K INNER JOIN KASATAKIP KT ON K.KASATAKIPID=KT.ID
WHERE
        --KT.HESAPID = @KASAID AND
        K.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
GROUP BY K.TUR,KASATAKIPID    
 
 
   ) AS X
   
   
GROUP BY YERID,GRUP, SIRA, ACIKLAMA 
order BY YERID,SIRA
' WHERE id = 985;
UPDATE public.dokumler SET sql = '/*PGX*/
		@KASAID		VARCHAR(20),
		@HESAPADI	VARCHAR(50),
		''$Baslangic$''	DATETIME,
		--''$Bitis$ 23:59''	DATETIME,
		@ACILISTUTARI	MONEY,
		@KAPANISTUTARI	MONEY,
		@NAKITTAHSILAT	MONEY,
		@ACILISTARIHI   DATETIME,
		@KAPANISTARIHI  DATETIME



--


--ÖNCE AKTİF KASATAKIP kaydından değerleri alalım, 0 gelirse max kayıt alınıp son oturum gösterilebilir.
SELECT --''$Baslangic$'' = ACILISTARIHI, ''$Bitis$ 23:59'' = coalesce(KAPANISTARIHI,now()), 
		@HESAPID = HESAPID,  @ACILISTUTARI = coalesce(ACILISTUTARI,0) , 
		@KAPANISTUTARI = coalesce(KAPANISTUTARI,0)
FROM	KASATAKIP 

WHERE	
		
		to_char(ACILISTARIHI,''YYYY-MM-DD HH24:MI:SS'')=''$Baslangic$''

SELECT @HESAPADI = KASAKODU+''-''+KASAADI FROM KASALAR WHERE ID = @HESAPID

-- O Nakit tahsilatlarını değişkenlere alıyoruz toplam hesaplarında kullanılacak
SELECT 
	@NAKITTAHSILAT =SUM(coalesce(K.ALACAK,0))
FROM 
	KASA K INNER JOIN REHBER R
ON
	K.REHBERID = R.ID
WHERE
	
        to_char(ISLEMTARIHI,''YYYY-MM-DD HH24:MI:SS'')=''$Baslangic$'' 
    AND YERI = 401 


 --değerler alındıktan sonra sorgumuz çalışabilir  
SELECT GRUP, SIRA, ACIKLAMA, SUM(ADET) ADET, SUM(TOPLAM) TOPLAM , 
       ACILISTARIHI, KAPANISTARIHI, 
       --HESAPID = @HESAPID, HESAPADI = @HESAPADI , KASATAKIPNO = @HESAPID,
       KASA
 FROM
(
SELECT DISTINCT

   GRUP = ''Açılış'',
   SIRA = 0,
   ACIKLAMA = ''Kasa Açılış'',
   ADET = 1,
   TOPLAM = coalesce((SELECT SUM(ALACAK-BORC) FROM KASA K2 WHERE HESAPTURU=''K'' AND TUR NOT BETWEEN 60 AND 79 AND K2.HESAPID=K.HESAPID AND to_char(to_char(K2.ISLEMTARIHI,''DD/MM/YYYY''),''DD/MM/YYYY'')<=to_char(to_char(DATEADD(DAY,-1,K.ISLEMTARIHI),''DD/MM/YYYY''),''DD/MM/YYYY'')),0),
   ACILISTARIHI =to_char(ISLEMTARIHI,''DD/MM/YYYY''),
   KAPANISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
   KASA=(SELECT KASAADI FROM KASALAR K1 WHERE K1.ID=K.HESAPID LIMIT 1 )
   
    FROM KASA K INNER JOIN KASALAR K1 ON K.HESAPID=K1.ID
   
   WHERE
   
		to_char(ISLEMTARIHI,''YYYY-MM-DD HH24:MI:SS'')= ''$Baslangic$''
	AND HESAPTURU=''K'' AND TUR NOT BETWEEN 60 AND 79
	AND coalesce(ACIKLAMA,'''')<>''''
 AND K1.KASATUR NOT IN (''1'')
   
UNION ALL
SELECT DISTINCT

   GRUP = ''Kapanış'',
   SIRA = 9,
   ACIKLAMA = ''Kasa Kapanış'',
   ADET = 1,
   TOPLAM = coalesce((SELECT SUM(ALACAK-BORC) FROM KASA K3 WHERE HESAPTURU=''K'' AND TUR NOT BETWEEN 60 AND 79 AND K3.HESAPID=K.HESAPID AND to_char(to_char(K3.ISLEMTARIHI,''DD/MM/YYYY''),''DD/MM/YYYY'')<=to_char(to_char(K.ISLEMTARIHI,''DD/MM/YYYY''),''DD/MM/YYYY'')),0),
   ACILISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
   KAPANISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
   KASA=(SELECT KASAADI FROM KASALAR K1 WHERE K1.ID=K.HESAPID LIMIT 1 )
   
   FROM KASA K INNER JOIN KASALAR K1 ON K.HESAPID=K1.ID
   
   WHERE
   
            to_char(ISLEMTARIHI,''YYYY-MM-DD HH24:MI:SS'')= ''$Baslangic$''
	AND HESAPTURU=''K'' AND TUR NOT BETWEEN 60 AND 79
	AND coalesce(ACIKLAMA,'''')<>''''
        AND K1.KASATUR NOT IN (''1'')
	
UNION ALL

SELECT 
	GRUP =''Girişler'',
        SIRA = 1,
	R.FIRMA AS ACIKLAMA,
	ADET  =COUNT(*),
	TOPLAM=SUM(F.FATURA_TUTARI),
	ACILISTARIHI =to_char(TARIH,''DD/MM/YYYY''),
        KAPANISTARIHI=to_char(TARIH,''DD/MM/YYYY''),
        KASA=(SELECT KASAADI FROM KASALAR K1,FATBASLIK KT WHERE K1.ID=KT.KASATAKIPID LIMIT 1 )
FROM 
	FATBASLIK F INNER JOIN REHBER R     ON F.REHBERID = R.ID
	 		
WHERE
	to_char(TARIH,''YYYY-MM-DD HH24:MI:SS'')=''$Baslangic$''
    AND TUR IN (''15'',''16'') 
 
GROUP BY F.REHBERID,FIRMA,TARIH
UNION ALL


SELECT
	GRUP =''Girişler Dağılımı'',
    SIRA =2,
	ACIKLAMA=CASE WHEN K.HESAPTURU IN (''K'') THEN (SELECT KASAADI  FROM KASALAR K1 WHERE K1.ID=K.HESAPID)
				  WHEN K.HESAPTURU IN (''H'') THEN (SELECT KASAADI+'' Hediye Çeki''  FROM KASALAR K1 WHERE K1.ID=K.HESAPID)
				  WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR K1 WHERE K1.ID=K.HESAPID)
				  WHEN K.HESAPTURU=''P'' THEN (SELECT ADI      FROM POS K1           WHERE K1.ID=K.HESAPID)
			ELSE ''X'' END,
	ADET=COUNT(*),
	TOPLAM=CASE WHEN TUR=40 THEN SUM(K.BORC) ELSE SUM(K.ALACAK)END,
	ACILISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
    KAPANISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
	KASA=(SELECT DISTINCT KASAADI FROM KASALAR K1,FATBASLIK KT WHERE K1.ID=KT.KASATAKIPID)	
FROM 
	KASA K
WHERE
        to_char(k.ISLEMTARIHI,''YYYY-MM-DD HH24:MI:SS'')=''$Baslangic$''
    AND 
    CASE WHEN TUR=40 AND (HESAPID IN(SELECT ID FROM KASALAR WHERE KASATUR<>1)) THEN ALACAK ELSE BORC-ALACAK END <>0
      
GROUP BY
	K.HESAPTURU,K.HESAPID,K.ISLEMTARIHI,K.TUR 
HAVING 
CASE WHEN TUR=40 THEN SUM(K.BORC) ELSE SUM(K.ALACAK)END<>0




UNION ALL

SELECT
--SELECT * FROM REHBERINI WHERE BOLUM = ''Kasa Türleri''
	GRUP=''Çıkışlar'',
	SIRA=3,
    ACIKLAMA=CASE WHEN TUR=40 THEN (SELECT KASAADI FROM KASALAR K5 INNER JOIN KASA K6 ON K5.ID=K6.HESAPID AND K6.ID=K.GERIDONUSID)
				WHEN TUR=31 THEN (SELECT FIRMA FROM REHBER R WHERE R.ID=K.REHBERID)
				WHEN K.HESAPTURU=''K'' THEN (SELECT KASAADI  FROM KASALAR K1       WHERE K1.ID=K.HESAPID)
				WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR K1 WHERE K1.ID=K.HESAPID)
			 ELSE ''Y '' END,
	ADET=COUNT(*),
	TOPLAM=SUM(K.BORC),
	ACILISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
    KAPANISTARIHI=to_char(ISLEMTARIHI,''DD/MM/YYYY''),
    KASA=(SELECT KASAADI FROM KASALAR K1 WHERE K1.ID=K.HESAPID LIMIT 1 )

FROM 
	KASA K  
WHERE BORC>0 AND
      to_char(ISLEMTARIHI,''YYYY-MM-DD HH24:MI:SS'')=''$Baslangic$'' AND
    CASE WHEN TUR=40 AND (HESAPID IN(SELECT ID FROM KASALAR WHERE KASATUR=1)) THEN ALACAK ELSE BORC-ALACAK END <>0      
GROUP BY K.HESAPTURU,K.HESAPID,K.ISLEMTARIHI,GERIDONUSID,K.TUR,REHBERID 
	    


UNION ALL
SELECT
	GRUP=''Belgeler'',
	SIRA=8 ,
    ACIKLAMA=CASE 
		WHEN K.TUR=8 THEN  ''Gider Pusulası''
		WHEN K.TUR=10 THEN ''Alış İrsaliyesi''
		WHEN K.TUR=11 THEN ''Alış Faturası''
		WHEN K.TUR=12 THEN ''Alış Fişi''
		WHEN K.TUR=13 THEN ''Alacak Tahakkuku''
		WHEN K.TUR=14 THEN ''Satış İrsaliyesi''
		WHEN K.TUR=15 THEN ''Satış Faturası''
		WHEN K.TUR=16 THEN ''Satış Fişi''
		WHEN K.TUR=17 THEN ''Borç Tahakkuku'' 
		ELSE ''XX'' 
	END,

	ADET=COUNT(*),
	TOPLAM=SUM(FATURA_TUTARI),
	ACILISTARIHI=to_char(K.TARIH,''DD/MM/YYYY''),
    KAPANISTARIHI=to_char(K.TARIH,''DD/MM/YYYY''),
	KASA=(SELECT KASAADI FROM KASALAR K1 WHERE K1.ID=K.KASATAKIPID LIMIT 1 )

FROM
	FATBASLIK K 
WHERE
        
    to_char(K.TARIH,''YYYY-MM-DD HH24:MI:SS'')=''$Baslangic$''
    AND coalesce(K.KASATAKIPID,'''')<>'''' 
    
GROUP BY K.TUR,KASATAKIPID,TARIH
 
 
   ) AS X
   
   
GROUP BY KASA, GRUP, SIRA, ACIKLAMA,ACILISTARIHI,KAPANISTARIHI 

order BY ACILISTARIHI,KASA,SIRA,GRUP


--select * from FATBASLIK
' WHERE id = 986;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
to_char(F.EKLEMETARIHI,''DD/MM/YYYY'') AS TARIH,
CASE WHEN TUR=11 THEN ''Alış Faturası''
                WHEN TUR=15 THEN ''Satış Faturası'' 
                WHEN TUR=12 THEN ''Alacak Fiş''
                WHEN TUR=16 THEN ''Satış Fiş'' END AS ISLEM_TIPI ,
R.FIRMA AS HESAP_ADI,
F.ACIKLAMA,
CASE WHEN (TUR=15 OR TUR=16) THEN FATURA_TUTARI ELSE '''' END AS BORC,
CASE WHEN (TUR=11 OR TUR=12) THEN FATURA_TUTARI ELSE '''' END AS ALACAK,
KUR   
FROM REHBER R INNER JOIN FATBASLIK F ON R.ID=F.REHBERID
WHERE
F.EKLEMETARIHI>=''$Baslangic$ 00:00:00'' AND
F.EKLEMETARIHI<=''$Bitis$ 23:59:00''
order by  FATURATARIH' WHERE id = 987;
UPDATE public.dokumler SET sql = '/*PGX*/





SELECT  @NT = NAKITTOPLAM,
        @KT = VISATOPLAM,
        @HT = HEDIYETOPLAM,
        @IT = IADECEKITOPLAM,
        @GT = GENELTOPLAM 
FROM fn_TURTOPLA2  (''$Baslangic$ 00:00'',''$Bitis$ 23:59'',''$Sube$'')
                                                                           

select
         AD,cast(TUTAR as double precision)AS TUTAR,HESAPTURU,TARIH,BELGETURU,BELGENO,SATICI,ISKONTOSU,
         @NT AS NAKITTOPLAM,
         @KT AS VISATOPLAM,
         @HT AS HEDIYETOPLAM,
         @IT AS IADECEKITOPLAM,
         @GT AS GENELTOPLAM
FROM (

SELECT
	AD,TUTAR,HESAPTURU,TARIH,BELGETURU,BELGENO,SATICI,ISKONTOSU
FROM  (
SELECT
CASE WHEN F.TUR =1 THEN S.STOKADI ELSE MG.AD END AS AD ,
CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*((F.KDV/100.0)+1.0) ELSE F.TUTAR END AS TUTAR ,
(CASE (SELECT COUNT(*) FROM KASA K WHERE K.FATURAID=FB.ID)  
			WHEN 0 THEN ''Tahsilat Yok''
			WHEN 1 THEN (SELECT CASE WHEN HESAPTURU=''K'' THEN ''NAKİT''
			      WHEN HESAPTURU=''P'' THEN ''K.KARTI''
			      WHEN HESAPTURU=''H'' AND TUR=''28'' THEN ''HEDİYEÇEKİ''
			      WHEN HESAPTURU=''H'' AND TUR=''29'' THEN ''İADEÇEKİ''
						  ELSE ''HATA'' END FROM KASA K WHERE K.FATURAID=FB.ID)
			ELSE ''Çoklu Tahsilat'' 
			END) AS HESAPTURU ,
FB.TARIH,
FB.FATURANO AS BELGENO,
(SELECT FIRMA FROM  REHBER R1  WHERE R1.ID=FB.SATICIKODU AND GRUP=''335'') AS SATICI ,
CASE WHEN FB.TUR=15 THEN ''FATURA''
			   WHEN FB.TUR=16 THEN ''FİŞ'' 
                            WHEN FB.TUR=8 THEN ''İADE''   ELSE ''HATA'' END AS BELGETURU ,


(100.0-(((100.0-ISKONTO)*(100.0-ISKONTO2))/100))
 AS ISKONTOSU FROM 
      FATBASLIK FB LEFT OUTER JOIN FATURA F ON FB.ID=F.FATBASID
		   LEFT OUTER JOIN MASRAFGELIR MG on F.URUNID = MG.ID
		   LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
                   LEFT OUTER JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0
WHERE 
	TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
 AND FB.TUR IN (15,16)
 AND R.FIRMA LIKE ''$Sube$%''

) AS XX   

) AS XY   

ORDER BY TARIH,AD
' WHERE id = 988;
UPDATE public.dokumler SET sql = '/*PGX*/select
         AD,TUTAR,HESAPTURU,TURU,TARIH,BELGETURU,BELGENO,SATICI,
         CASE WHEN TURU=''NAKİT''   THEN SUM(TUTAR) ELSE 0 END AS NAKITTOPLAM ,
         CASE WHEN TURU=''K.KARTI'' THEN SUM(TUTAR) ELSE 0 END
 AS KREDITOPLAM FROM (

SELECT                    
		AD,cast(TUTAR as double precision)AS TUTAR,HESAPTURU,
		HESAPTURU AS TURU ,
		TARIH,BELGETURU,BELGENO,SATICI
FROM  (
SELECT 
 CASE WHEN F.TUR =1 THEN S.STOKADI ELSE MG.AD END AS AD ,
F.TUTAR,
(CASE (SELECT COUNT(*) FROM KASA K WHERE K.FATURAID=FB.ID)  
			WHEN 0 THEN ''Tahsilat Yok''
			WHEN 1 THEN (SELECT CASE WHEN HESAPTURU=''K'' THEN ''NAKİT''
			      WHEN HESAPTURU=''P'' THEN ''K.KARTI''
			      WHEN HESAPTURU=''H'' AND TUR=''28'' THEN ''HEDİYEÇEKİ''
			      WHEN HESAPTURU=''H'' AND TUR IN (''29'',''39'') THEN ''İADEÇEKİ''
						  ELSE ''HATA'' END FROM KASA K WHERE K.FATURAID=FB.ID)
			ELSE ''Çoklu Tahsilat'' 
			END) AS HESAPTURU ,
FB.TARIH,
FB.FATURANO AS BELGENO,
(SELECT FIRMA FROM REHBER R1 WHERE R1.ID=F.EKLEYEN) AS SATICI ,
CASE WHEN FB.TUR=15 THEN ''FATURA''
               WHEN FB.TUR=16 THEN ''FİŞ''   
               WHEN FB.TUR=8  THEN ''İADE'' 
            ELSE ''HATA'' END AS BELGETURU ,
CASE 
		WHEN K.HESAPTURU=''K'' THEN (SELECT KASAADI  FROM KASALAR K1       WHERE K1.ID=K.HESAPID)
		WHEN K.HESAPTURU=''B'' THEN (SELECT HESAPADI FROM BANKAHESAPLAR B1 WHERE B1.ID=K.HESAPID)
		WHEN K.HESAPTURU=''P'' THEN (SELECT ADI      FROM POS P1           WHERE P1.ID=K.HESAPID)
	ELSE ''X'' END
 AS TUR FROM 

FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
			 INNER JOIN KASA   K ON K.FATURAID=FB.ID
			 LEFT OUTER JOIN MASRAFGELIR MG on F.URUNID = MG.ID
			 LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
			 LEFT JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0


WHERE 
	TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
	AND R.FIRMA LIKE ''$Sube$%''

) AS XX   

GROUP BY  AD,TUTAR,HESAPTURU,TARIH,BELGETURU,BELGENO,SATICI 
) AS XY
GROUP BY  AD,TUTAR,HESAPTURU,TURU,TARIH,BELGETURU,BELGENO,SATICI
ORDER BY BELGETURU,BELGENO' WHERE id = 989;
