IF EXISTS (SELECT id FROM tempdb.SYSobjects where name like ''%TMP_SaticiGrupTutar%'' )
BEGIN
DROP TABLE gt_TMP_SaticiGrupTutar
END

CREATE TABLE gt_TMP_SaticiGrupTutar ( GRUP VARCHAR(50))

SELECT DISTINCT
ANAHTAR=CASE WHEN coalesce(STOKGRUP.ANAHTAR,'''')='''' THEN ''Grupsuz'' ELSE STOKGRUP.ANAHTAR END
from
FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
LEFT JOIN GENINI STOKGRUP ON STOKGRUP.DEGER=S.GRUBU AND STOKGRUP.BOLUM=-2704 AND STOKGRUP.DIL=-1
LEFT JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0
WHERE
FB.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND FB.TUR IN (15,16)
AND R.FIRMA LIKE ''$Sube$%''



OPEN GRUPLAR
FETCH NEXT FROM GRUPLAR Into @GRUP
WHILE @@FETCH_STATUS = 0
BEGIN
------- SATICILAR
SELECT DISTINCT
SATICI=coalesce((SELECT SUBSTRING(FIRMA,1,CHARINDEX('' '',FIRMA))+''''+SUBSTRING(FIRMA,CHARINDEX('' '',FIRMA),2) FROM REHBER R1 WHERE R1.ID=F.EKLEYEN),''İsimsizKullanıcı'')
from
FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
LEFT JOIN GENINI STOKGRUP ON STOKGRUP.DEGER=S.GRUBU AND STOKGRUP.BOLUM=-2704 AND STOKGRUP.DIL=-1
LEFT JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0
WHERE
FB.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND FB.TUR IN (15,16)
AND @GRUP=CASE WHEN coalesce(STOKGRUP.ANAHTAR,'''')='''' THEN ''Grupsuz'' ELSE STOKGRUP.ANAHTAR END
AND R.FIRMA LIKE ''$Sube$%''

OPEN SATICILAR
FETCH NEXT FROM SATICILAR Into @SATICI
WHILE @@FETCH_STATUS = 0
BEGIN
-- KODOMUZU BURAYA YAZACAĞIZ
-- SATICIYI TEMP TABLOYA ALAN OLARAK EKLE
-- TUTARI HESAPLATIP INSERT ET

tempdb.sys.columns c on o.object_id=c.object_id
where o.name = ''''gt_TMP_saticigruptutar'''' and c.name=''''''+@SATICI+'''''')
ALTER TABLE gt_TMP_SaticiGrupTutar ADD ''+@SATICI+'' MONEY''
EXEC (''Select ''''Kayıt Bulunamadı'''' AS SONUC '')
--PRINT (''Select ''''Kayıt Bulunamadı'''' AS SONUC '')



''select
''''''+@GRUP+'''''',
TUTAR=CASE WHEN FB.KDVDURUM=''''Hariç'''' THEN F.TUTAR*((F.KDV/100.0)+1.0) ELSE F.TUTAR END

from
FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
LEFT OUTER JOIN MASRAFGELIR MG ON F.URUNID = MG.ID
LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
LEFT JOIN GENINI STOKGRUP ON STOKGRUP.DEGER=S.GRUBU AND STOKGRUP.BOLUM=-2704 AND STOKGRUP.DIL=-1
LEFT JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0
WHERE

FB.TARIH BETWEEN ''''$Baslangic$ 00:00'''' AND ''''$Bitis$ 23:59''''
AND R.FIRMA LIKE ''''$Sube$''''+''''%''''
AND FB.TUR IN (15,16)
AND ''''''+@GRUP+''''''=CASE WHEN coalesce(STOKGRUP.ANAHTAR,'''''''')='''''''' THEN ''''Grupsuz'''' ELSE STOKGRUP.ANAHTAR END
AND ''''''+@SATICI+''''''=coalesce((SELECT SUBSTRING(FIRMA,1,CHARINDEX('''' '''',FIRMA))+''''''''+SUBSTRING(FIRMA,CHARINDEX('''' '''',FIRMA),2) FROM REHBER R1 WHERE R1.ID=F.EKLEYEN),''''İsimsizKullanıcı'''')
--GROUP BY
--FB.KDVDURUM,F.TUTAR,F.KDV
''
EXEC (''Select ''''Kayıt Bulunamadı'''' AS SONUC '')
--PRINT (''Select ''''Kayıt Bulunamadı'''' AS SONUC '')
FETCH NEXT FROM SATICILAR Into @SATICI
END
CLOSE SATICILAR
DEALLOCATE SATICILAR

FETCH NEXT FROM GRUPLAR Into @GRUP
END
CLOSE GRUPLAR
DEALLOCATE GRUPLAR

