SELECT DISTINCT
--SATICI=ISNULL((SELECT REPLACE(FIRMA,'' '','''') FROM REHBER R1 WHERE R1.ID=FB.SATICIKODU),''İsimsizKullanıcı'')
SATICI= ISNULL((SELECT SUBSTRING(FIRMA,1,CHARINDEX('' '',FIRMA))+''''+SUBSTRING(FIRMA,CHARINDEX('' '',FIRMA),2) FROM REHBER R1 WHERE R1.ID=F.EKLEYEN),''İsimsizKullanıcı'')
