UPDATE public.dokumler SET sql = '/*PGX*/SELECT
FIRMA,KONSINYETARIHI,KONSINYENO,URUNGRUBU,URUNKOD,URUNAD,
KONSADET,FATADET,KONSADET-FATADET AS KALAN ,SKT,LOT
,datediff(day,now(),SKT)
 AS KALANGUN FROM(
select
R.FIRMA AS FIRMA,
FB.FATURATARIH AS KONSINYETARIHI,
FATURANO AS KONSINYENO,
 (SELECT ANAHTAR FROM GENINI G,STOKLAR S WHERE G.BOLUM=''-2704'' AND G.DEGER=S.GRUBU AND S.ID=F.URUNID) AS URUNGRUBU ,
 (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID)  AS URUNKOD ,
 (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID)  AS URUNAD ,
 coalesce(SI.MIKTAR,F.MIKTAR) AS KONSADET ,
 coalesce((select sum (coalesce(SI2.MIKTAR,F2.MIKTAR)) from FATURA F2 left outer join STOKIZLEME SI2 on SI2.BASLIKID=F2.FATBASID and SI2.SATIRID=F2.ID where F2.YERI=462 and F2.YERID=F.ID),0) AS FATADET ,
 SI.SKT AS SKT ,
 SI.ACIKLAMA
 AS LOT from
FATURA F inner join
FATBASLIK FB on F.FATBASID=FB.ID LEFT OUTER JOIN
STOKIZLEME SI on SI.BASLIKID=F.FATBASID and SI.SATIRID=F.ID
LEFT JOIN REHBER R ON FB.REHBERID=R.ID
--select * from REHBER
where
FB.TUR=119 and
0=case when ''$Bolge$''=0 then 0 when ''$Bolge$''=R.BOLGE then 0 else 1 end and
R.FIRMA like ''$FirmaAdi$%'' and
FB.FATURATARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''

) AS X
WHERE
KONSADET-FATADET>0.0' WHERE id = 998;
UPDATE public.dokumler SET sql = '/*PGX*/

SELECT  @StartDate = ''$Baslangic$ 00:00'',
	   @EndDate   = ''$Bitis$ 23:59''

SELECT
	R.ID,
	R.FIRMA, 
	 0 AS KARTNO ,
	 DATEADD(DAY, DATEDIFF(DAY, 0, DATEADD(DAY, v.number, @StartDate)), 0) AS GUN ,
	 DATENAME(WEEKDAY,(DATEADD(DAY, DATEDIFF(DAY, 0, DATEADD(DAY, v.number, @StartDate)), 0))) AS GUNAD ,
	 0 AS VARDIYAGUN ,
	 CAST(NULL AS DATETIME) AS VARDIYAGIRIS ,
	 CAST(NULL AS DATETIME) AS VARDIYACIKIS ,
	 CAST(NULL AS DATETIME) AS GIRISSAAT ,
	 CAST(NULL AS DATETIME) AS CIKISSAAT ,
	 CAST(NULL AS DATETIME) AS GIRISTARIH ,
	 CAST(NULL AS DATETIME) AS CIKISTARIH ,
	 0 AS VARDIYADAKIKASURE ,
	 0 AS CALISMASAATI ,
	 0 AS CALISMADAKIKASI ,
	 0 AS GIRISDURUMSAAT ,
	 0 AS GIRISDURUMDAKIKA ,
	 0 AS CIKISDURUMSAAT ,
	 0

INTO #GunHareket
 AS CIKISDURUMDAKIKA FROM master.spt_values v cross join REHBER R 
WHERE v.type = ''P''
	 AND DATEDIFF(DAY, @StartDate, @EndDate) >= v.number
	 AND KOD LIKE ''335%''

UPDATE #GunHareket SET GUNAD=case 
							when GUNAD=''Sunday''		then ''Pazar''
							when GUNAD=''Monday''		then ''Pazartesi''
							when GUNAD=''Tuesday''	then ''Salı''
							when GUNAD=''Wednesday''	then ''Çarşamba''
							when GUNAD=''Thursday ''	then ''Perşembe'' 
							when GUNAD=''Friday''		then ''Cuma''
							when GUNAD=''Saturday''	then ''Cumartesi''
						else '''' end	 
UPDATE 	#GunHareket SET VARDIYAGIRIS	  = cast((cast(GIRIS as varchar)) as timestamp)	FROM  #GunHareket G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI
UPDATE 	#GunHareket SET VARDIYACIKIS	  = cast((cast(CIKIS as varchar)) as timestamp)	FROM  #GunHareket G,PERS_VARDIYATANIM P WHERE G.ID=P.REHBERID AND G.GUNAD=P.GUNADI						
UPDATE 	#GunHareket SET KARTNO=P.KARTNO	FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID 
UPDATE 	#GunHareket SET GIRISSAAT         = cast((cast(GIRIS as varchar)) as timestamp)	FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket SET CIKISSAAT         = cast((cast(CIKIS as varchar)) as timestamp)	FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket SET GIRISTARIH        = GIRIS	FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket SET CIKISTARIH        = CIKIS	FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp)
UPDATE 	#GunHareket SET CALISMASAATI      = abs(datediff(minute,GIRIS,CIKIS)/60) FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) and coalesce(GIRIS,'''')<>'''' AND  coalesce(CIKIS,'''')<>''''
UPDATE  #GunHareket SET CALISMADAKIKASI	  = ((datediff(minute,GIRIS,CIKIS))%60) FROM  #GunHareket G,PERS_PDKS P WHERE G.ID=P.REHBERID AND G.GUN=cast((to_char(GIRIS,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) and coalesce(GIRIS,'''')<>'''' AND  coalesce(CIKIS,'''')<>''''
UPDATE 	#GunHareket SET GIRISDURUMSAAT    = abs(datediff(minute,VARDIYAGIRIS,GIRISSAAT))/60     FROM  #GunHareket WHERE coalesce(VARDIYAGIRIS,'''')<>'''' AND coalesce(GIRISSAAT,'''')<>''''
UPDATE  #GunHareket SET GIRISDURUMDAKIKA  = ((datediff(minute,VARDIYAGIRIS,GIRISSAAT))%60)		FROM  #GunHareket WHERE coalesce(VARDIYAGIRIS,'''')<>'''' AND coalesce(GIRISSAAT,'''')<>''''
UPDATE 	#GunHareket SET CIKISDURUMSAAT    = CASE WHEN VARDIYACIKIS>CIKISSAAT THEN -1*(datediff(minute,CIKISSAAT,VARDIYACIKIS)/60) ELSE datediff(minute,VARDIYACIKIS,CIKISSAAT)/60 END		FROM  #GunHareket WHERE coalesce(VARDIYACIKIS,'''')<>'''' AND coalesce(CIKISSAAT,'''')<>''''
UPDATE  #GunHareket SET CIKISDURUMDAKIKA  = CASE WHEN VARDIYACIKIS>CIKISSAAT THEN -1*(((datediff(minute,CIKISSAAT,VARDIYACIKIS))%60))   ELSE -1*(((datediff(minute,CIKISSAAT,VARDIYACIKIS))%60)) END   FROM  #GunHareket WHERE coalesce(VARDIYACIKIS,'''')<>'''' AND coalesce(CIKISSAAT,'''')<>''''


SELECT  ID,AD,CASE WHEN KARTNO=0 THEN '''' ELSE KARTNO END AS KARTNO ,GIRISTARIH,CIKISTARIH,CALISMASURE,GIRISDURUM,CIKISDURUM,
	CASE WHEN CALISMAFARK=''00:00'' THEN '''' ELSE CALISMAFARK END
 AS CALISMAFARK FROM (
SELECT 
		ID,AD,cast(KARTNO as varchar) AS KARTNO,
                GIRISTARIH,CIKISTARIH,CALISMASURE,
		CASE WHEN GIRISDURUM=''ERKEN'' AND coalesce(GDURUMDAKIKA,'''')<>'''' THEN GDURUMSAAT||'':''||GDURUMDAKIKA||'' ERKEN''
						WHEN GIRISDURUM=''GEÇ''   AND coalesce(GDURUMDAKIKA,'''')<>'''' THEN GDURUMSAAT||'':''||GDURUMDAKIKA||'' GEÇ'' ELSE '''' END AS GIRISDURUM ,
		CASE WHEN CIKISDURUM=''ERKEN'' AND coalesce(CDURUMDAKIKA,'''')<>'''' THEN CDURUMSAAT||'':''||CDURUMDAKIKA||'' ERKEN''
						WHEN CIKISDURUM=''GEÇ''   AND coalesce(CDURUMDAKIKA,'''')<>'''' THEN CDURUMSAAT||'':''||CDURUMDAKIKA||'' GEÇ'' ELSE '''' END AS CIKISDURUM ,
		(CASE WHEN length(DURUMSURE/60)=1 THEN ''0''||cast((DURUMSURE/60) as varchar) ELSE cast((DURUMSURE/60) as varchar) END)||'':''||					
		            (CASE WHEN length(DURUMSURE%60)=1 THEN ''0''||cast((DURUMSURE%60) as varchar) ELSE cast((DURUMSURE%60) as varchar) END)||'' ''||
		            DURUMHAL

		
 AS CALISMAFARK FROM(
SELECT	ID,AD,KARTNO,GIRISTARIH,
		CIKISTARIH,
		 CASE WHEN CALISMASAATI||'':''||CALISMADAKIKASI=''00:00'' THEN '''' ELSE CALISMASAATI||'':''||CALISMADAKIKASI END AS CALISMASURE ,
		GIRISDURUM,CIKISDURUM,GIRISDAKIKAGECIKMETOP,CIKISDAKIKAGECIKMETOP,
		CASE WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN ''-''
							WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP >0   THEN ''+''
						    WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''GEÇ''   THEN ''+''
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''ERKEN'' THEN ''-''
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN ''+''
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) >0 THEN ''-''
						ELSE '''' END AS DURUMHAL ,
		CASE WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN -1*(GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
							WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''ERKEN'' AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) >0 THEN (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
						    WHEN GIRISDURUM=''ERKEN'' AND CIKISDURUM=''GEÇ''   THEN GIRISDAKIKAGECIKMETOP+CIKISDAKIKAGECIKMETOP
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''ERKEN'' THEN GIRISDAKIKAGECIKMETOP+CIKISDAKIKAGECIKMETOP 
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) <0 THEN -1*(GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
						    WHEN GIRISDURUM=''GEÇ''   AND CIKISDURUM=''GEÇ''   AND (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP) >0 THEN (GIRISDAKIKAGECIKMETOP-CIKISDAKIKAGECIKMETOP)
						ELSE 0 END AS DURUMSURE ,
		 CASE WHEN length(GIRISDAKIKAGECIKMETOP/60)=1 THEN ''0''||cast(GIRISDAKIKAGECIKMETOP/60 as varchar)   ELSE cast(GIRISDAKIKAGECIKMETOP/60 as varchar) END AS GDURUMSAAT ,
		 CASE WHEN length(GIRISDAKIKAGECIKMETOP%60)=1 THEN ''0''||cast((GIRISDAKIKAGECIKMETOP%60) as varchar) ELSE cast((GIRISDAKIKAGECIKMETOP%60) as varchar) END AS GDURUMDAKIKA ,
		 CASE WHEN length(CIKISDAKIKAGECIKMETOP/60)=1 THEN ''0''||cast(CIKISDAKIKAGECIKMETOP/60 as varchar)   ELSE cast(CIKISDAKIKAGECIKMETOP/60 as varchar) END AS CDURUMSAAT ,
		 CASE WHEN length(CIKISDAKIKAGECIKMETOP%60)=1 THEN ''0''||cast((CIKISDAKIKAGECIKMETOP%60) as varchar) ELSE cast((CIKISDAKIKAGECIKMETOP%60) as varchar) END
	

 AS CDURUMDAKIKA FROM
(
SELECT	ID,FIRMA AS AD,KARTNO,
		GIRISTARIH,CIKISTARIH,
		 CASE WHEN (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)<0 THEN ''ERKEN'' WHEN (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)=0 THEN '''' ELSE ''GEÇ'' END AS GIRISDURUM ,
		 CASE WHEN (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)<0 THEN ''ERKEN'' WHEN (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)=0 THEN '''' ELSE ''GEÇ'' END AS CIKISDURUM ,
		 CASE WHEN (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)<0 THEN -1*((GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA)) ELSE (GIRISDURUMSAAT*60)+(GIRISDURUMDAKIKA) END AS GIRISDAKIKAGECIKMETOP ,
		 CASE WHEN (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)<0 THEN -1*((CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA)) ELSE (CIKISDURUMSAAT*60)+(CIKISDURUMDAKIKA) END AS CIKISDAKIKAGECIKMETOP ,
		 CASE WHEN length(cast(REPLACE(CALISMASAATI,''-'','''') as varchar))    =1 THEN ''0''||cast(REPLACE(CALISMASAATI,''-'','''') as varchar)    ELSE cast(REPLACE(CALISMASAATI,''-'','''') as varchar) END AS CALISMASAATI ,
		 CASE WHEN length(cast(REPLACE(CALISMADAKIKASI,''-'','''') as varchar)) =1 THEN ''0''||cast(REPLACE(CALISMADAKIKASI,''-'','''') as varchar) ELSE cast(REPLACE(CALISMADAKIKASI,''-'','''') as varchar) END


 AS CALISMADAKIKASI FROM #GunHareket
) AS X
) AS Y
) AS Z

--WHERE ID=6007
ORDER BY AD
DROP TABLE #GunHareket
' WHERE id = 999;
UPDATE public.dokumler SET sql = '/*PGX*/--Hesaplanan Kdv Özet Dökümü
                                                



SELECT KDV,SUM(KDVTUTARI) AS KDVTUTARI FROM (
SELECT 
	F.KDV, 
	KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' THEN (F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR
			   WHEN FB.KDVDURUM=''Dahil'' THEN cast(F.TUTAR as double precision)-(F.TUTAR/(1+(F.KDV/100.0)))
				   END),
        TIPI=CASE WHEN IT.TIP IN (1,3,4) AND FB.TUR IN (15,16) THEN ''Satış'' 
		  WHEN IT.TIP IN (2)     AND FB.TUR IN (15,16) THEN ''Alış İade'' 
			 END
FROM
	FATURA AS F 
		INNER JOIN FATBASLIK FB ON 
			F.FATBASID = FB.ID 
		INNER JOIN ISLEMTURLERI IT ON 
			FB.TUR = IT.TUR and 
			FB.TIPI=IT.TIP
WHERE 
	    FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
	AND FB.TUR IN (15,16) AND coalesce(FB.DURUM,0)<>6
GROUP BY 
	F.KDV,FB.TUR,IT.TIP
) AS X
WHERE 
	    coalesce(TIPI,'''')<>''''
	AND coalesce(KDV,'''') LIKE  CASE WHEN ''$Kdv$''='''' THEN ''%'' ELSE ''$Kdv$'' END 
GROUP BY KDV
' WHERE id = 1000;
UPDATE public.dokumler SET sql = '/*PGX*/--İndirilecek Kdv Dökümü
           
           
                               



SELECT * FROM (
SELECT                                                       
                FB.FATURATARIH,FB.FATURANO,F.KDV, 
                --KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' THEN (F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR
                --                                               WHEN FB.KDVDURUM=''Dahil'' THEN F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))
                --                                               END),
matrah=  SUM(CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN cast(F.TUTAR as double precision)
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN F.TUTAR/(1+(F.KDV/100.0))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN f.tutar * (1.0-(KDVMUHAFIYETI/100.0))
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR/(1+(F.KDV/100.0))) * (1.0-(KDVMUHAFIYETI/100.0))
                                                                  END) ,
KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN (cast(F.TUTAR as double precision)*(1+(F.KDV/100.0)))-F.TUTAR
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN ((F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR) * (1.0-(KDVMUHAFIYETI/100.0))
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))) * (1.0-(KDVMUHAFIYETI/100.0))
                                                                  END) ,
                IT.AD AS ISLEMADI,FB.ACIKLAMA,R.FIRMA,
                TIPI=CASE WHEN IT.TIP IN (1,3,4,5) AND FB.TUR IN (11,12) THEN ''Alış'' 
                                 WHEN IT.TIP IN (2)     AND FB.TUR IN (11,12) THEN ''İade'' 
                  WHEN FB.TUR IN (8) THEN ''Gider Pusulası''  
                                                END
FROM
                FATURA AS F 
                               INNER JOIN FATBASLIK FB ON 
                                               F.FATBASID = FB.ID 
                               INNER JOIN ISLEMTURLERI IT ON 
                                               FB.TUR  = IT.TUR and 
                                               FB.TIPI = coalesce(IT.TIP,'''')
                LEFT JOIN REHBER R ON
                        FB.REHBERID=R.ID
WHERE 
                    FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
                AND FB.TUR IN (8,11,12) AND coalesce(FB.DURUM,0)<>6
GROUP BY 
                F.KDV, IT.AD,FB.ACIKLAMA,FB.FATURANO,R.FIRMA,FB.FATURATARIH,FB.TUR,IT.TIP
) AS X
WHERE 
                coalesce(TIPI,'''') LIKE ''$IslemAdi$%''    
                AND coalesce(KDV,'''') LIKE  CASE WHEN ''$Kdv$''='''' THEN ''%'' ELSE ''$Kdv$'' END 
ORDER BY ISLEMADI,KDV
' WHERE id = 1001;
