UPDATE public.dokumler SET sql = '/*PGX*/--Kdv Özet Dökümü
                                                    
--
--

SELECT KDV,TUR,
       KDVTUTARI =CASE WHEN TUR=''Hesaplanan KDV'' THEN SUM(KDVTUTARI)
		       WHEN TUR=''İndirilen KDV''  THEN -1*SUM(KDVTUTARI) END,
       KDVMATRAHI=CASE WHEN TUR=''Hesaplanan KDV'' THEN SUM(MATRAH)
		       WHEN TUR=''İndirilen KDV''  THEN -1*SUM(MATRAH) END
            
FROM (
SELECT 
	F.KDV, 
	TUR=CASE WHEN FB.TUR IN (15,16)   THEN ''Hesaplanan KDV''
		 WHEN FB.TUR IN (8,11,12) THEN ''İndirilen KDV'' END,
	KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN (F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR
			   WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN cast(F.TUTAR as double precision)-(F.TUTAR/(1+(F.KDV/100.0)))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN ((F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR) * (1.0-(KDVMUHAFIYETI/100.0))
			   WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))) * (1.0-(KDVMUHAFIYETI/100.0))
				   END) ,
        MATRAH= SUM(CASE WHEN FB.KDVDURUM=''Hariç''  THEN cast(F.TUTAR as double precision)
			 WHEN FB.KDVDURUM=''Dahil''  THEN F.TUTAR-(F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0))))
				   END )
FROM
	FATURA AS F 
		INNER JOIN FATBASLIK FB ON 
			F.FATBASID = FB.ID 
		INNER JOIN ISLEMTURLERI IT ON 
			FB.TUR = IT.TUR and 
			FB.TIPI=IT.TIP
WHERE 
	    FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
	AND FB.TUR IN (8,11,12,15,16) AND coalesce(FB.DURUM,0)<>6
GROUP BY 
	F.KDV,FB.TUR,IT.TIP
) AS X
WHERE 
    
    TUR LIKE ''$KDVTURU$%''
	
GROUP BY KDV,TUR

ORDER BY TUR,KDV
' WHERE id = 1004;
UPDATE public.dokumler SET sql = '/*PGX*/select
	SUBE,KOD,DEPOADI,STOKADI,BIRIM,GIREN,CIKAN,KALAN,Max.Stok,Min.Stok,Kri.Stok,Max.Fark=Max.Stok-KALAN,Min.Fark= Min.Stok-KALAN
FROM(
	
select 
	coalesce(R.FIRMA,'''') AS SUBE,S.KOD,D.DEPOADI,S.STOKADI,
	(SELECT ANAHTAR FROM GENINI G WHERE G.DEGER=S.ANABIRIM AND G.DIL=''-1'' AND BOLUM=''-2702'') AS BIRIM ,
	coalesce(SD.GIREN,0) AS GIREN,
	coalesce(SD.CIKAN,0) AS CIKAN,
	coalesce(SD.KALAN,0) AS KALAN,
	coalesce(SS.MAKSIMUM,0) AS Max.Stok,
	coalesce(SS.MINIMUM,0)  AS Min.Stok,
	coalesce(SS.KRITIK,0)   AS Kri.Stok,
	Min.Fark=coalesce(SS.KRITIK,0)-coalesce(SS.MINIMUM,0)
	--Sipariş Giriş=(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Girecek'' ),
	--Sipariş Çıkış=(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Çıkacak'' ),
	--Sipariş Kalan=(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Girecek'' )-(select ADET FROM fn_StokDurumDetay(SD.STOKID,SD.DEPOID) WHERE TIP=''Sipariş Çıkacak'' )
	 
from 
	STOKLAR S 
	
		LEFT JOIN STOKDURUM SD  ON 
			S.ID=SD.STOKID
		INNER JOIN DEPOLAR D ON 
			SD.DEPOID=D.ID
		LEFT JOIN STOKSEVIYE SS ON
			SS.DEPOID=SD.DEPOID AND SS.STOKID=S.ID
		LEFT JOIN REHBER R ON 
			R.ID=SD.SUBEID AND R.ID<0
			
) AS X

WHERE
	coalesce(SUBE,'''') LIKE ''$Subeler$%'' AND
	coalesce(DEPOADI,'''') LIKE ''$DepoAdi$%'' AND
	coalesce(KOD,'''') LIKE ''$StokKod$%'' AND
	coalesce(STOKADI,'''') LIKE ''$StokAdi$%''
 
 order by SUBE,DEPOADI,KOD' WHERE id = 1005;
UPDATE public.dokumler SET sql = '/*PGX*/--SELECT
--GRUP='''',UNVAN='''',ULKE='''',VGNO='''',TCNO='''',TUTAR=0,ADET=0,
--YIL=NULL,AY=NULL,
              
--SONRAKIAY=NULL,
--FIRMA='''',ISTEL='''',FAX='''',EPOSTA='''',ADRES='''',ADRES1='''' 
--UNION ALL

SELECT 
GRUP,UNVAN,ULKE,VGNO,TCNO,SUM(TUTAR) AS TUTAR,SUM(ADET) AS ADET,
YIL,AY=CASE WHEN AY=1 THEN ''Ocak''  WHEN AY=2  THEN ''Şubat''    WHEN AY=3  THEN ''Mart''   WHEN AY=4  THEN ''Nisan''
            WHEN AY=5 THEN ''Mayıs'' WHEN AY=6  THEN ''Haziran''  WHEN AY=7  THEN ''Temmuz'' WHEN AY=8  THEN ''Ağustos''
            WHEN AY=9 THEN ''Eylül'' WHEN AY=10 THEN ''Ekim''     WHEN AY=11 THEN ''Kasım''  WHEN AY=12 THEN ''Aralık'' end  ,
              
SONRAKIAY=CASE WHEN SONRAKIAY=1 THEN ''Ocak''  WHEN SONRAKIAY=2  THEN ''Şubat''    WHEN SONRAKIAY=3  THEN ''Mart''    WHEN SONRAKIAY=4  THEN ''Nisan''
               WHEN SONRAKIAY=5 THEN ''Mayıs'' WHEN SONRAKIAY=6  THEN ''Haziran''  WHEN SONRAKIAY=7  THEN ''Temmuz''  WHEN SONRAKIAY=8  THEN ''Ağustos''
               WHEN SONRAKIAY=9 THEN ''Eylül'' WHEN SONRAKIAY=10 THEN ''Ekim''     WHEN SONRAKIAY=11 THEN ''Kasım''   WHEN SONRAKIAY=12 THEN ''Aralık'' end,
FIRMA,ISTEL,FAX,FAX_FIRMA,EPOSTA,ADRES,ADRES1     
FROM ( 
SELECT GRUP,UNVAN,ULKE,VGNO,TCNO,
SUM(TUTAR) AS TUTAR,ADET=SUM(ADET),
YIL,AY ,SONRAKIAY=CASE WHEN AY=12 THEN 1 ELSE AY+1 END,
FIRMA,ISTEL,FAX,FAX_FIRMA,EPOSTA ,ADRES,ADRES1=PK+''  ''+ILCE+'' ''+IL
FROM( 
SELECT 
       FB.ID AS FBID,R.ID AS RID,
       R.KOD AS HESAP_KODU,
       R.FIRMA AS UNVAN,
       ADET=1,
       ULKE =(SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERILETISIM RI ON RB.YER_ID=RI.ID WHERE RI.REHBERID=R.ID AND ETIKET=''Ülke'' LIMIT 1 ),
       TCNO = case wheN R.STATU=0 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END,
       VGNO = case wheN R.STATU=1 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END,
       TUTAR= CASE WHEN coalesce(KDVDURUM,'''')=''Dahil'' THEN FATURA_MATRAHI-KDV_TUTARI ELSE FATURA_MATRAHI END ,
       ISTEL= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İş Tel'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       FAX= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Faks'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       FAX_FIRMA= (SELECT RB.BILGI FROM REHBERILETISIM RI INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE RB.ETIKET=''Faks'' AND YERI=1 AND R.ID=RI.REHBERID LIMIT 1 ),
       EPOSTA= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Eposta'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       ADRES= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Adres'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       PK= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''PK'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       ILCE= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İlçe'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       IL= (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İl'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
       GRUP = CASE WHEN FB.TUR=11 THEN ''BA''
                 WHEN FB.TUR=12 THEN ''BA''
                 WHEN FB.TUR=15 THEN ''BS''
                 WHEN FB.TUR=16 THEN ''BS'' END ,
      YIL=YEAR(FATURATARIH) ,
      AY=MONTH(FATURATARIH) ,
      FIRMA = (SELECT FIRMA FROM REHBER R1 WHERE R1.ID=FB.SUBEID LIMIT 1 ) 
FROM REHBER R INNER JOIN FATBASLIK FB ON R.ID=FB.REHBERID
WHERE
	--FATURATARIH BETWEEN ''2014-01-01 00:00:00'' AND ''2014-01-31 23:59:00'' 
	    FATURATARIH BETWEEN ''$Baslama$ 00:00:00'' AND ''$Bitis$ 23:59:00'' 
	AND FB.TUR IN (11,12,15,16)
	AND FB.DURUM NOT IN (6)
        AND coalesce(FB.FATURASERI,'''') NOT LIKE ''X%''

) AS X	
GROUP BY 
YIL,AY,GRUP,UNVAN,ULKE,VGNO,TCNO,FIRMA,ISTEL,FAX,FAX_FIRMA,EPOSTA,ADRES,PK,ILCE,IL
) AS Y
WHERE
	TUTAR>=5000 
	AND GRUP LIKE ''$Grup$%''
        AND UNVAN LIKE ''%$Unvani$%''
GROUP BY --YIL,AY,SONRAKIAY,GRUP,UNVAN,ULKE,VGNO,TCNO,FIRMA,ISTEL,FAX,EPOSTA,ADRES,ADRES1
       GRUP,UNVAN,ULKE,VGNO,TCNO ,YIL,AY,SONRAKIAY,FIRMA,ISTEL,FAX,FAX_FIRMA,EPOSTA,ADRES,ADRES1' WHERE id = 1006;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
 * 
FROM 
(                                         
SELECT     FB.FATURATARIH,
	   FB.FATURANO,
	   D1.DEPOADI AS CIKISDEPO ,
           D.DEPOADI AS GIRISDEPO ,
           S.KOD,
	   S.STOKADI,
	   G.ANAHTAR,
	   F.ADET
FROM 
	FATBASLIK FB 
		INNER JOIN FATURA F ON 
			FB.ID=F.FATBASID
		LEFT JOIN STOKLAR S ON
			F.URUNID=S.ID
		INNER JOIN GENINI G ON
			F.BIRIM=G.DEGER AND G.BOLUM=-2702 AND G.DIL=-1
		LEFT JOIN DEPOLAR D ON
			FB.GIRISDEPO=D.ID
		LEFT JOIN DEPOLAR D1 ON
			FB.CIKISDEPO=D1.ID
WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' AND
FB.TUR=20 
) AS X
WHERE

	CIKISDEPO LIKE ''$CikisDepo$%'' AND
        GIRISDEPO LIKE ''$GirisDepo$%'' AND
	KOD LIKE ''$Kod$%'' AND
	STOKADI LIKE ''$StokAdi$%''
ORDER BY FATURATARIH,FATURANO' WHERE id = 1008;
