UPDATE public.dokumler SET sql = '/*PGX*/SELECT * FROM (

SELECT 
	
	CASE WHEN FB.TUR IN (15,16)  THEN ''Satış''
			  WHEN FB.TUR=110 THEN ''Adisyon''
			  END AS TURU ,
	ID		 = CASE WHEN FB.TUR IN (15,16,110) THEN FB.YERID END,
	 CASE WHEN FB.TUR IN (15,16,110) THEN FB.FATURATARIH END AS TARIH ,
	 CASE WHEN FB.TUR IN (15,16,110) THEN FB.TUR END AS TUR ,
	 CASE WHEN FB.TUR IN (15,16,110) THEN FB.FATURANO END AS FATURANO ,
	 R.FIRMA AS SUBE ,
	 CASE WHEN FB.TUR IN (15,16,110) THEN FB.BASLIK END AS BASLIK ,
	 NULL AS TAHSILTUR ,
	 (SELECT SUM(BIRIMFIYAT*ADET) FROM FATURA F WHERE FB.ID=F.FATBASID) AS BIRIMFIYAT ,
	 CASE WHEN FB.TUR IN (15,16,110) THEN FB.FATURA_TUTARI END
 AS FATURATUTARI FROM 
	FATBASLIK FB INNER JOIN REHBER R ON FB.SUBEID=R.ID AND R.ID<0
				 
WHERE 
      FATURATARIH>=''$Baslangic$ $BasSaat$'' AND 
      FATURATARIH<=''$Bitis$ $BitSaat$''
      and FB.TUR IN (15,16,110)

UNION ALL

SELECT 
	
	''Tahsilat'' AS TURU ,	
	ID		 = FB.YERID,
	 K.ISLEMTARIHI AS TARIH ,
	 K.TUR AS TUR ,
	 K.BELGENO AS FATURANO ,
	 R.FIRMA AS SUBE ,
	 K.ACIKLAMA AS BASLIK ,
	 CASE WHEN HESAPTURU = ''K'' THEN ''Nakit''  WHEN HESAPTURU = ''P'' THEN ''Kredi Kartı'' ELSE HESAPTURU END AS TAHSILTUR ,
	 0 AS BIRIMFIYAT ,
	 ABS(BORC-ALACAK)
 AS FATURATUTARI FROM 
	KASA K INNER JOIN FATBASLIK FB ON K.YERID=FB.ID AND FB.TUR IN (15,16)
		   INNER JOIN REHBER R ON K.SUBEID=R.ID AND R.ID<0
				 
WHERE K.ISLEMTARIHI BETWEEN ''$Baslangic$ $BasSaat$'' AND ''$Bitis$ $BitSaat$''


) AS X
WHERE
SUBE LIKE ''$Sube$%''
ORDER BY
	ID,TURU' WHERE id = 1013;
UPDATE public.dokumler SET sql = '/*PGX*/BEGIN TRY

truncate table #tmp_StokDevirli_Durum
         
END TRY

BEGIN CATCH
CREATE TABLE #tmp_StokDevirli_Durum 
(
	SIRANO int   IDENTITY(1,1) NOT NULL,
	ETIKET Varchar (25) NULL,
	URUNID int   NULL,
	STOKKOD Varchar (55) NULL,
	STOKADI Varchar (255) NULL,
	DEPOID int   NULL,
	GIREN  Float NULL,
	CIKAN  Float NULL,
	KALAN  Float NULL,
	YILI	 int   NULL
)
END 
CATCH


		''$Bitis$ 23:59'' datetime







INSERT INTO #tmp_StokDevirli_Durum


SELECT

	ETIKET,URUNID,KOD AS STOKKOD,STOKADI,DEPOID,GIREN,CIKAN,KALAN=GIREN-CIKAN,YIL AS YILI
FROM(

--GIRIS DEPOLARI DEVIR

select 
	ETIKET  = ''Genel'',
	DEPOID  = D.ID,
	F.URUNID,
	S.KOD,
	S.STOKADI,
	GIREN =  F.MIKTAR ,
	CIKAN =  0 ,
	YIL = Year(FATURATARIH)

from 
	FATURA F 
			 INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
			 INNER JOIN STOKLAR S ON F.URUNID=S.ID
			 INNER JOIN DEPOLAR D ON D.ID=FB.GIRISDEPO
WHERE 
	coalesce(F.STOKDURUMDEGIS,'''')<>0
	AND FB.TUR IN (3,7,8,10,11,12,20,109)
	AND FB.FATURATARIH between ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

UNION ALL

select 
	ETIKET  = Year(FATURATARIH)+''-''+ ''YilBasiDevir'',
	DEPOID  = D.ID,
	F.URUNID,
	S.KOD,
	S.STOKADI,
	GIREN =  F.MIKTAR ,
	CIKAN =  0 ,
	YIL = Year(FATURATARIH)

from 
	FATURA F 
			 INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
			 INNER JOIN STOKLAR S ON F.URUNID=S.ID
			 INNER JOIN DEPOLAR D ON D.ID=FB.GIRISDEPO
WHERE 
	coalesce(F.STOKDURUMDEGIS,'''')<>0
	AND FB.TUR IN (2)
	AND FB.FATURATARIH between ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

UNION ALL

-- URETIM FISLERI IÇIN GIRIS DEPO DEVIR

select 
	ETIKET = ''Genel'',
	DEPOID=D.ID,
	F.URUNID,
	S.KOD,
	S.STOKADI,
	GIREN = F.MIKTAR ,
	CIKAN = 0 ,
	YIL = Year(FATURATARIH)
from 
	FATURA F 
			 INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
			 INNER JOIN STOKLAR S ON F.URUNID=S.ID
			 INNER JOIN DEPOLAR D ON D.ID=FB.GIRISDEPO
WHERE 
	coalesce(F.STOKDURUMDEGIS,'''')<>0
	AND FB.TUR = 6
	AND ADET > 0
	AND FB.FATURATARIH between ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

UNION ALL

--ÇIKIS DEPOLARI DEVIR

select 
	ETIKET = ''Genel'',
	DEPOID = D.ID,
	F.URUNID,
	S.KOD,
	S.STOKADI,
	GIREN = 0,
	CIKAN = F.MIKTAR,
	YIL = Year(FATURATARIH)
 
from 
	FATURA F 
			 INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
			 INNER JOIN STOKLAR S ON F.URUNID=S.ID
			 INNER JOIN DEPOLAR D ON D.ID=FB.CIKISDEPO
WHERE 
	coalesce(F.STOKDURUMDEGIS,'''')<>0
	AND FB.TUR IN (4,14,15,16,20,110,119)
	AND FB.FATURATARIH between ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

UNION ALL

select 
	ETIKET = Year(FATURATARIH)+''-''+''YilSonuDevir'',
	DEPOID = D.ID,
	F.URUNID,
	S.KOD,
	S.STOKADI,
	GIREN = 0,
	CIKAN = F.MIKTAR,
	YIL = Year(FATURATARIH)
 
from 
	FATURA F 
			 INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
			 INNER JOIN STOKLAR S ON F.URUNID=S.ID
			 INNER JOIN DEPOLAR D ON D.ID=FB.CIKISDEPO
WHERE 
	coalesce(F.STOKDURUMDEGIS,'''')<>0
	AND FB.TUR IN (2)
	AND FB.FATURATARIH between ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

UNION ALL

-- URETIM FISLERI IÇIN ÇIKIS DEPO DEVIR

select 
	ETIKET = ''Genel'',
	DEPOID=D.ID,
	F.URUNID,
	S.KOD,
	S.STOKADI,
	GIREN = 0,
	CIKAN = -1*F.MIKTAR,
	YIL = Year(FATURATARIH)
 
from 
	FATURA F 
			 INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
			 INNER JOIN STOKLAR S ON F.URUNID=S.ID
			 INNER JOIN DEPOLAR D ON D.ID=FB.CIKISDEPO
WHERE 
	coalesce(F.STOKDURUMDEGIS,'''')<>0
	AND FB.TUR = 6 
	AND F.ADET < 0
	AND FB.FATURATARIH between ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''


) as x

--group by YIL,URUNID,STOKADI,DEPOID

ORDER BY 1,2

select 
	 STOKKOD,STOKADI,DEVIR=coalesce((SELECT KALAN FROM #tmp_StokDevirli_Durum S1 WHERE ETIKET LIKE ''%YilBasiDevir%'' AND S.URUNID=S1.URUNID AND S.DEPOID=S1.DEPOID ),0),
	 SUM(GIREN) AS GIREN,
	 SUM(CIKAN) AS CIKAN,
	 round (SUM(GIREN-CIKAN),2) AS KALAN
from 

#tmp_StokDevirli_Durum S 
	LEFT JOIN STOKKATEGORI SK ON S.URUNID=SK.STOKID 
        INNER JOIN DEPOLAR D ON S.DEPOID=D.ID

WHERE

		STOKKOD LIKE ''$StokKod$%'' 
	AND coalesce(SK.AD,'''') LIKE ''$Kategori$%''
        AND DEPOADI LIKE ''$DepoAdi$%''
        AND ETIKET NOT LIKE ''%YilSonuDevir%''

GROUP BY DEPOID,STOKKOD,URUNID,STOKADI


