UPDATE public.dokumler SET sql = '/*PGX*/





-- select * from cekler
             select KOD,FIRMA,HESAPKODU,HESAPADI,ALISTARIHI,BANKAHESAPNO,BANKAHESAPADI,
                    HAREKETTARIH=''$Baslangic$'',VADE=''$Baslangic$'',SERINO=''Devir'',
                    BORC=case when SUM(BAKIYE)>0 then SUM(BAKIYE) else 0.0 end,
                    ALACAK=case when SUM(BAKIYE)>0 then 0.0 else -SUM(BAKIYE)end,
                    BAKIYE=SUM(BAKIYE),
                    KUR
             from (
                           --devir borc
                           select KOD=NULL,FIRMA=NULL,H.HESAPKODU,H.HESAPADI,ALISTARIHI=NULL,BANKAHESAPNO=NULL,BANKAHESAPADI=NULL,
                           BORC=CH.DOVIZ_TUTARI,ALACAK=0.0,BAKIYE=CH.DOVIZ_TUTARI,KUR=CH.DOVIZ_KURU
                           from 
                                  CEKLER C inner join 
                                  CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                                  HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM
                                  --left JOIN REHBER R ON C.REHBERID = R.ID
                           where CH.TARIH < ''$Baslangic$''
                           union all
                           --devir alacak
                           select  KOD=NULL,FIRMA=NULL,H.HESAPKODU,H.HESAPADI,ALISTARIHI=NULL,BANKAHESAPNO=NULL,BANKAHESAPADI=NULL,
                           BORC=0.0,ALACAK=CH.DOVIZ_TUTARI,BAKIYE=-CH.DOVIZ_TUTARI,KUR=CH.DOVIZ_KURU
                           from 
                                  CEKLER C inner join 
                                  CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                                  CEKHAREKET CHD on CH.GERIDONUSID=CHD.ID inner join 
                                  HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CHD.ISLEM
                                  --left JOIN REHBER R ON C.REHBERID = R.ID
                           where CH.TARIH < ''$Baslangic$'' 
             )as XX
             group by KOD,FIRMA,HESAPKODU,HESAPADI,ALISTARIHI,KUR,BANKAHESAPNO,BANKAHESAPADI

             union all
             -- SELECT * FROM CEKHAREKET
             -- SELECT * FROM BANKAHESAPLAR
             --çekin ilgili tarihteki hareketi /hesabın borcuna
             select 
                    R.KOD,R.FIRMA,H.HESAPKODU,H.HESAPADI,ALISTARIHI=C.TARIH,BH.HESAPNO AS BANKAHESAPNO,BH.HESAPADI AS BANKAHESAPADI,
                    HAREKETTARIH=CH.TARIH,C.VADE,cast(C.SERINO as varchar),
                    BORC=CH.DOVIZ_TUTARI,ALACAK=0.0,BAKIYE=CH.DOVIZ_TUTARI,KUR=CH.DOVIZ_KURU
             from 
                    CEKLER C inner join 
                    CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                    HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM
                    left JOIN REHBER R ON C.REHBERID = R.ID
                    LEFT JOIN BANKAHESAPLAR BH ON CH.BANKAHESAPLARID=BH.ID
             where CH.TARIH between ''$Baslangic$'' and ''$Bitis$''
             union all
             --çekin ilgili tarihteki hareketinin karşı hesabı /hesabın alacağına
             select 
                    R.KOD,R.FIRMA,H.HESAPKODU,H.HESAPADI,ALISTARIHI=C.TARIH,BH.HESAPNO AS BANKAHESAPNO,BH.HESAPADI AS BANKAHESAPADI,
                    HAREKETTARIH=CH.TARIH,C.VADE,cast(C.SERINO as varchar),
                    BORC=0.0,ALACAK=CH.DOVIZ_TUTARI,BAKIYE=-CH.DOVIZ_TUTARI,KUR=CH.DOVIZ_KURU
             from 
                    CEKLER C inner join 
                    CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                    CEKHAREKET CHD on CH.GERIDONUSID=CHD.ID inner join 
                    HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CHD.ISLEM
                    left JOIN REHBER R ON C.REHBERID = R.ID
                    LEFT JOIN BANKAHESAPLAR BH ON CH.BANKAHESAPLARID=BH.ID
             where CH.TARIH between ''$Baslangic$'' and ''$Bitis$''
order by 1,2,3
' WHERE id = 1018;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT           
                 FB.ID, 
    R.FIRMA,
    FB.FATURATARIH,
    FB.FATURANO,
     CASE WHEN F.TUR = 0 THEN ''Hizmet'' ELSE ''Malzeme'' END AS ISLEMTUR ,
	S.STOKADI,
	F.ADET,
    (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2702 AND G.DEGER=S.ANABIRIM) AS BIRIM ,	
    K.AD as KATEGORI,
    (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2804 AND G.DEGER=S.MARKA) AS MARKA ,
     (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer)) AS MODEL ,          
    (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2704 AND G.DEGER=S.GRUBU) AS GRUBU ,

    D.DEPOADI ,
	SI.IZLEM,SI.MIKTAR
FROM 
	FATBASLIK FB 
	INNER JOIN FATURA F ON FB.ID=F.FATBASID
    INNER JOIN STOKLAR S ON S.ID=F.URUNID
    INNER JOIN KATEGORI K ON K.ID=S.KATEGORI
    INNER JOIN REHBER R ON R.ID=FB.REHBERID
    INNER JOIN DEPOLAR D ON D.ID=FB.GIRISDEPO
	LEFT OUTER JOIN STOKIZLEME SI ON SI.STOKID=S.ID AND SI.BASLIKID=FB.ID AND SI.SATIRID=F.ID
WHERE 
	FB.TUR=11                   
	AND FATURATARIH  between ''$baslama$ 00:00'' and ''$bitis$ 23:59''
	AND R.FIRMA LIKE ''%$firma$%''
	AND K.AD LIKE ''%$kategori$%''
	AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
	AND coalesce(S.GRUBU,'''') LIKE ''$grubu$%''
	AND coalesce(S.MODEL,'''') LIKE ''$model$%''
ORDER BY 
	F.BIRIM' WHERE id = 1022;
UPDATE public.dokumler SET sql = '/*PGX*/
	    ''$Sorumlu$'' VARCHAR(100)




SELECT PERSONEL=FIRMA,
	   SUM(OCAK) AS OCAK,
	   SUM(SUBAT) AS SUBAT,
	   SUM(MART) AS MART,
	   SUM(NISAN) AS NISAN,
	   SUM(MAYIS) AS MAYIS,
	   SUM(HAZIRAN) AS HAZIRAN,
	   SUM(TEMMUZ) AS TEMMUZ,
	   SUM(AGUSTOS) AS AGUSTOS,
	   SUM(EYLUL) AS EYLUL,
	   SUM(EKIM) AS EKIM,
	   SUM(KASIM) AS KASIM,
	   SUM(ARALIK) AS ARALIK,
           SUM(TOPLAM) AS TOPLAM
 FROM (
SELECT R.FIRMA,OCAK=COUNT(S.ID),SUBAT=0,MART=0,NISAN=0,MAYIS=0,HAZIRAN=0,TEMMUZ=0,AGUSTOS=0,EYLUL=0,EKIM=0,KASIM=0,ARALIK=0,TOPLAM=0
