UPDATE public.dokumler SET sql = '/*PGX*/SELECT CASE WHEN SERVISNO LIKE ''G.KK%'' THEN cast(SIRA-1 as varchar)||''. ''||SERVISNO ELSE cast(SIRA as varchar)||''. ''||SERVISNO END AS NO , * FROM (
SELECT DENSE_RANK() OVER(Order By SERVISNO) AS SIRA ,
	   SERVISNO, 
           KONUSU,
           SB.SERVISTUR,
	   CASE WHEN SERVISNO LIKE ''G.K%'' THEN ''Kayıt Kabul'' ELSE ''Laboratuvar'' END AS MODUL ,
	   CASE WHEN SB.SERVISTUR=210 THEN ''Gereksinim'' 
                    WHEN SB.SERVISTUR=220 THEN ''Test''||'' ''||SL.AD
                    WHEN SB.SERVISTUR=230 THEN ''Test Sonucu''||'' (''||SL.AD||'')''
                    ELSE '''' END AS TIP ,
	   SL.AD AS TESTTURU ,
	   SB.ACIKLAMA,
	   SB.COZUM

FROM SERVIS S INNER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID 
              INNER JOIN SERVISLISTE SL ON SL.ID=SB.SERVISLISTEID
WHERE SERVISNO LIKE ''G.%'') AS X
WHERE MODUL LIKE ''%''      
ORDER BY 2,4' WHERE id = 1029;
