UPDATE public.dokumler SET sql = '/*PGX*/


IF ''$ServisNo$'' LIKE ''G.K%''
BEGIN
SELECT NO=SIRA+''. ''+SERVISNO,* FROM (
SELECT SIRA=0,
	   --CASE WHEN SERVISNO=''G.KK'' THEN 0 ELSE DENSE_RANK() OVER(Order By SERVISNO) END,
	   SERVISNO, 
       KONUSU,
	   MODUL=CASE WHEN SERVISNO LIKE ''G.K%'' THEN ''Kayıt Kabul'' ELSE ''Laboratuvar'' END,
	   TIP=CASE WHEN SB.SERVISTUR=210 THEN ''Gereksinim'' 
                    WHEN SB.SERVISTUR=220 THEN ''Test''+'' ''+SL.AD
                    ELSE '''' END,
	   SB.ACIKLAMA,
	   SB.COZUM
FROM SERVIS S INNER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID 
              INNER JOIN SERVISLISTE SL ON SL.ID=SB.SERVISLISTEID
WHERE SERVISNO=''G.KK''
	  AND SB.SERVISTUR IN(210,220)
UNION
SELECT SIRA=DENSE_RANK() OVER(Order By SERVISNO),
	   --CASE WHEN SERVISNO=''G.KK'' THEN 0 ELSE DENSE_RANK() OVER(Order By SERVISNO) END,
	   SERVISNO, 
       KONUSU,
	   MODUL=CASE WHEN SERVISNO LIKE ''G.K%'' THEN ''Kayıt Kabul'' ELSE ''Laboratuvar'' END,
	   TIP=CASE WHEN SB.SERVISTUR=210 THEN ''Gereksinim'' 
                    WHEN SB.SERVISTUR=220 THEN ''Test''+'' ''+SL.AD
                    ELSE '''' END,
	   SB.ACIKLAMA,
	   SB.COZUM
FROM SERVIS S INNER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID 
              INNER JOIN SERVISLISTE SL ON SL.ID=SB.SERVISLISTEID
WHERE SERVISNO LIKE ''$ServisNo$''+''%''
      AND SERVISNO<>''G.KK''
	  AND SB.SERVISTUR IN(210,220)  ) AS X
ORDER BY 2,4     
END
ELSE
BEGIN
SELECT NO=SIRA+''. ''+SERVISNO,* FROM (
SELECT SIRA=DENSE_RANK() OVER(Order By SERVISNO),
	   --CASE WHEN SERVISNO=''G.KK'' THEN 0 ELSE DENSE_RANK() OVER(Order By SERVISNO) END,
	   SERVISNO, 
       KONUSU,
	   MODUL=CASE WHEN SERVISNO LIKE ''G.K%'' THEN ''Kayıt Kabul'' ELSE ''Laboratuvar'' END,
	   TIP=CASE WHEN SB.SERVISTUR=210 THEN ''Gereksinim'' 
                    WHEN SB.SERVISTUR=220 THEN ''Test''+'' ''+SL.AD
                    ELSE '''' END,
	   SB.ACIKLAMA,
	   SB.COZUM
FROM SERVIS S INNER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID 
              INNER JOIN SERVISLISTE SL ON SL.ID=SB.SERVISLISTEID
WHERE SERVISNO LIKE ''$ServisNo$''+''%''
	  AND SB.SERVISTUR IN(210,220)
                                                                      ) AS X
ORDER BY 2,4
END
' WHERE id = 1031;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT LTRIM(SUBSTRING(D.AD,14,length(D.AD)-1)) AS ADI ,
