UPDATE public.dokumler SET sql = '/*PGX*/SELECT *,
	   DATEDIFF(DAY,PLANBASLANGIC,PLANBITIS) AS PLANSURE ,
	   DATEDIFF(DAY,GERCEKLESENBASLANGIC,GERCEKLESENBITIS) AS GERCEKSURE ,
	   CASE WHEN DATEDIFF(DAY,GERCEKLESENBASLANGIC,GERCEKLESENBITIS)>DATEDIFF(DAY,PLANBASLANGIC,PLANBITIS)
				  THEN ROUND((CAST(DATEDIFF(DAY,GERCEKLESENBASLANGIC,GERCEKLESENBITIS)AS DECIMAL(15,2))-
						CAST(DATEDIFF(DAY,PLANBASLANGIC,PLANBITIS)AS DECIMAL(15,2))),2)
						
				  ELSE 0
			 END  AS SAPMA FROM (
SELECT DISTINCT
	   --MODUL=''Kayıt Kabul Projesi'',
	   A.ASAMA,
	   to_char(to_char(P.BASTAR,''DD.MM.YYYY''),''DD.MM.YYYY'') AS PLANBASLANGIC ,
	   to_char(to_char(P.BITTAR,''DD.MM.YYYY''),''DD.MM.YYYY'') AS PLANBITIS ,
	   --DURUM=G.ANAHTAR,
	   (SELECT BASLAMA FROM SERVISHAREKET SHH WHERE SHH.SERVISID=SH.SERVISID AND SHH.DURUM=SH.DURUM ORDER BY BASLAMA LIMIT 1 ) AS GERCEKLESENBASLANGIC ,
	   (SELECT BITIS FROM SERVISHAREKET SHH WHERE SHH.SERVISID=SH.SERVISID AND SHH.DURUM=SH.DURUM ORDER BY BASLAMA DESC LIMIT 1 )
 AS GERCEKLESENBITIS FROM SERVISHAREKET SH INNER JOIN GENINI G ON G.DEGER=SH.DURUM AND G.BOLUM=-3007
					  INNER JOIN ASAMAESLESTIR A ON A.DURUMKOD=SH.DURUM 
					  INNER JOIN PROJEASAMA P ON P.ASAMA=A.ASAMAKOD AND P.ID=A.ID AND P.PROJEID=6
WHERE SERVISID=44029 ) AS X
ORDER BY PLANBASLANGIC' WHERE id = 1033;
