UPDATE public.dokumler SET sql = '/*PGX*/SELECT KS.KASAKODU,KS.KASAADI AS KASA,cast(YEAR(K.ISLEMTARIHI) as varchar)||'' - ''||(CASE 
                                                        WHEN MONTH(ISLEMTARIHI)=1 THEN ''OCAK''
                                                        WHEN MONTH(ISLEMTARIHI)=2 THEN ''ŞUBAT''
                                                        WHEN MONTH(ISLEMTARIHI)=3 THEN ''MART''
                                                        WHEN MONTH(ISLEMTARIHI)=4 THEN ''NİSAN''
                                                        WHEN MONTH(ISLEMTARIHI)=5 THEN ''MAYIS''
                                                        WHEN MONTH(ISLEMTARIHI)=6 THEN ''HAZİRAN''
                                                        WHEN MONTH(ISLEMTARIHI)=7 THEN ''TEMMUZ''
                                                        WHEN MONTH(ISLEMTARIHI)=8 THEN ''AĞUSTOS''
                                                        WHEN MONTH(ISLEMTARIHI)=9 THEN ''EYLÜL'' 
                                                        WHEN MONTH(ISLEMTARIHI)=10 THEN ''EKİM''
                                                        WHEN MONTH(ISLEMTARIHI)=11 THEN ''KASIM''
                                                        WHEN MONTH(ISLEMTARIHI)=12 THEN ''ARALIK''
                                                        END) AS AY,
SUM(BORC) AS TAHSIL,SUM(ALACAK) AS ODEME ,(SELECT SUM(BORC)-SUM(ALACAK) FROM KASA K2 WHERE YEAR(K2.ISLEMTARIHI)<=YEAR(K.ISLEMTARIHI) AND MONTH(K2.ISLEMTARIHI)<=MONTH(K.ISLEMTARIHI) AND K2.HESAPTURU=''K'' AND K.HESAPID=K2.HESAPID) AS BAKIYE                                                       

FROM KASA K,KASALAR KS

WHERE K.HESAPID =KS.ID AND K.HESAPTURU=''K'' AND KS.KASAADI LIKE ''$KasaAdi$%'' AND 
      K.ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$''
GROUP BY coalesce(K.KASA,''''),cast(YEAR(ISLEMTARIHI) as varchar)||'' - ''||(CASE 
                                                        WHEN MONTH(ISLEMTARIHI)=1 THEN ''OCAK''
                                                        WHEN MONTH(ISLEMTARIHI)=2 THEN ''ŞUBAT''
                                                        WHEN MONTH(ISLEMTARIHI)=3 THEN ''MART''
                                                        WHEN MONTH(ISLEMTARIHI)=4 THEN ''NİSAN''
                                                        WHEN MONTH(ISLEMTARIHI)=5 THEN ''MAYIS''
                                                        WHEN MONTH(ISLEMTARIHI)=6 THEN ''HAZİRAN''
                                                        WHEN MONTH(ISLEMTARIHI)=7 THEN ''TEMMUZ''
                                                        WHEN MONTH(ISLEMTARIHI)=8 THEN ''AĞUSTOS''
                                                        WHEN MONTH(ISLEMTARIHI)=9 THEN ''EYLÜL'' 
                                                        WHEN MONTH(ISLEMTARIHI)=10 THEN ''EKİM''
                                                        WHEN MONTH(ISLEMTARIHI)=11 THEN ''KASIM''
                                                        WHEN MONTH(ISLEMTARIHI)=12 THEN ''ARALIK''
                                                        END)
,YEAR(K.ISLEMTARIHI),MONTH(K.ISLEMTARIHI),K.HESAPTURU,K.HESAPID,KS.KASAKODU,KS.KASAADI
ORDER BY KS.KASAKODU,cast(YEAR(K.ISLEMTARIHI) as varchar)||'' - ''||cast(MONTH(ISLEMTARIHI) as varchar)' WHERE id = 1126;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT KASAKODU,KASA,KUR,AY,SUM(coalesce(TAHSIL,0)) AS TAHSIL,SUM(coalesce(ODEME,0)) AS ODEME,SUM(coalesce(TAHSIL,0))-SUM(coalesce(ODEME,0)) AS BAKIYE FROM
(SELECT KS.KASAKODU,KS.KASAADI AS KASA,KS.KUR,cast(YEAR(K.ISLEMTARIHI) as varchar)||'' - ''||(CASE 
                                                        WHEN MONTH(ISLEMTARIHI)=1 THEN ''OCAK''
                                                        WHEN MONTH(ISLEMTARIHI)=2 THEN ''ŞUBAT''
                                                        WHEN MONTH(ISLEMTARIHI)=3 THEN ''MART''
                                                        WHEN MONTH(ISLEMTARIHI)=4 THEN ''NİSAN''
                                                        WHEN MONTH(ISLEMTARIHI)=5 THEN ''MAYIS''
                                                        WHEN MONTH(ISLEMTARIHI)=6 THEN ''HAZİRAN''
                                                        WHEN MONTH(ISLEMTARIHI)=7 THEN ''TEMMUZ''
                                                        WHEN MONTH(ISLEMTARIHI)=8 THEN ''AĞUSTOS''
                                                        WHEN MONTH(ISLEMTARIHI)=9 THEN ''EYLÜL'' 
                                                        WHEN MONTH(ISLEMTARIHI)=10 THEN ''EKİM''
                                                        WHEN MONTH(ISLEMTARIHI)=11 THEN ''KASIM''
                                                        WHEN MONTH(ISLEMTARIHI)=12 THEN ''ARALIK''
                                                        END) AS AY,
cast(YEAR(K.ISLEMTARIHI) as varchar)||''-''||cast(MONTH(ISLEMTARIHI) as varchar) AS ISLEMSIRA,

SUM(case when K.BORC>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.BORC end  ) AS TAHSIL,
SUM(case when K.ALACAK>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.ALACAK end) AS ODEME 

FROM KASA K,KASALAR KS

WHERE K.HESAPID =KS.ID AND K.HESAPTURU=''K'' AND K.ISLEMTARIHI >=''$Baslangic$ 00:00'' AND K.ISLEMTARIHI <=''$Bitis$ 23:59''
AND K.TUR IN (1,2,21,22,25,31,32,35,41,42,43,45,46,47,48,51,52,53,54,71,72,73,111,121,122) AND K.REHBERID <>''-99''  
GROUP BY coalesce(K.KASA,''''),cast(YEAR(ISLEMTARIHI) as varchar)||'' - ''||(CASE 
                                                        WHEN MONTH(ISLEMTARIHI)=1 THEN ''OCAK''
                                                        WHEN MONTH(ISLEMTARIHI)=2 THEN ''ŞUBAT''
                                                        WHEN MONTH(ISLEMTARIHI)=3 THEN ''MART''
                                                        WHEN MONTH(ISLEMTARIHI)=4 THEN ''NİSAN''
                                                        WHEN MONTH(ISLEMTARIHI)=5 THEN ''MAYIS''
                                                        WHEN MONTH(ISLEMTARIHI)=6 THEN ''HAZİRAN''
                                                        WHEN MONTH(ISLEMTARIHI)=7 THEN ''TEMMUZ''
                                                        WHEN MONTH(ISLEMTARIHI)=8 THEN ''AĞUSTOS''
                                                        WHEN MONTH(ISLEMTARIHI)=9 THEN ''EYLÜL'' 
                                                        WHEN MONTH(ISLEMTARIHI)=10 THEN ''EKİM''
                                                        WHEN MONTH(ISLEMTARIHI)=11 THEN ''KASIM''
                                                        WHEN MONTH(ISLEMTARIHI)=12 THEN ''ARALIK''
                                                        END)
,YEAR(K.ISLEMTARIHI),MONTH(K.ISLEMTARIHI),K.HESAPTURU,K.HESAPID,KS.KASAKODU,KS.KUR,KS.KASAADI 

) AS X
GROUP BY KASAKODU,KASA,AY,ISLEMSIRA,KUR
ORDER BY KASAKODU,ISLEMSIRA

/*
(KASAKODU,KASA,AY,ISLEMSIRA,TAHSIL,ODEME) AS(
SELECT KS.KASAKODU,KS.KASAADI AS KASA,cast(YEAR(K.ISLEMTARIHI) as varchar)||'' - ''||(CASE 
                                                        WHEN MONTH(ISLEMTARIHI)=1 THEN ''OCAK''
                                                        WHEN MONTH(ISLEMTARIHI)=2 THEN ''ŞUBAT''
                                                        WHEN MONTH(ISLEMTARIHI)=3 THEN ''MART''
                                                        WHEN MONTH(ISLEMTARIHI)=4 THEN ''NİSAN''
