cast(YEAR(K.ISLEMTARIHI) as varchar)||''-''||cast(MONTH(ISLEMTARIHI) as varchar) AS ISLEMSIRA,

SUM(case when K.BORC>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.BORC end  ) AS TAHSIL,
SUM(case when K.ALACAK>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.ALACAK end) AS ODEME 

