WHERE K.HESAPID =KS.ID AND K.HESAPTURU=''K'' AND K.ISLEMTARIHI >=''$Baslangic$ 00:00'' AND K.ISLEMTARIHI <=''$Bitis$ 23:59''
AND K.TUR IN (1,2,21,22,25,31,32,35,41,42,43,45,46,47,48,51,52,53,54,71,72,73,111,121,122) AND K.REHBERID <>''-99''  
GROUP BY coalesce(K.KASA,''''),cast(YEAR(ISLEMTARIHI) as varchar)||'' - ''||(CASE 
                                                        WHEN MONTH(ISLEMTARIHI)=1 THEN ''OCAK''
                                                        WHEN MONTH(ISLEMTARIHI)=2 THEN ''ŞUBAT''
                                                        WHEN MONTH(ISLEMTARIHI)=3 THEN ''MART''
                                                        WHEN MONTH(ISLEMTARIHI)=4 THEN ''NİSAN''
                                                        WHEN MONTH(ISLEMTARIHI)=5 THEN ''MAYIS''
                                                        WHEN MONTH(ISLEMTARIHI)=6 THEN ''HAZİRAN''
                                                        WHEN MONTH(ISLEMTARIHI)=7 THEN ''TEMMUZ''
                                                        WHEN MONTH(ISLEMTARIHI)=8 THEN ''AĞUSTOS''
                                                        WHEN MONTH(ISLEMTARIHI)=9 THEN ''EYLÜL'' 
                                                        WHEN MONTH(ISLEMTARIHI)=10 THEN ''EKİM''
