)

SELECT KASAKODU,KASA,AY,SUM(coalesce(TAHSIL,0)) AS TAHSIL,SUM(coalesce(ODEME,0)) AS ODEME,SUM(coalesce(TAHSIL,0))-SUM(coalesce(ODEME,0)) AS BAKIYE FROM arcq_cte
GROUP BY KASAKODU,KASA,AY,ISLEMSIRA
ORDER BY KASAKODU,ISLEMSIRA
*/' WHERE id = 1128;
UPDATE public.dokumler SET sql = '/*PGX*/
''$Bitis$'' DATETIME,
''$Kod$'' VARCHAR(10)







SELECT 
''$Baslangic$'' AS ISLEMTARIHI,
''Devir'' AS TUR,
'''' AS CARIKOD,
'''' AS CARIAD,
'''' AS KASAKODU,
'''' AS KASAADI,
BORC=(SELECT
SUM(coalesce( K.ALACAK,0)-coalesce(K.BORC,0) )
FROM KASA K inner join KASALAR KK on K.HESAPID = KK.ID  AND K.HESAPTURU=''K''
WHERE 
     ISLEMTARIHI >= cast(YEAR(''$Baslangic$'') as varchar(4))+''-01-01 00:00'' AND  
     ISLEMTARIHI < ''$Baslangic$''+'' 00:00'' AND
     KK.KASAKODU = ''$Kod$'' 
), 
0 AS ALACAK

UNION ALL

SELECT 
 ISLEMTARIHI,
 RI2.ANAHTAR AS TUR,
 R.KOD AS CARIKOD,
 R.FIRMA AS CARIAD,
 KS.KASAKODU,
 KS.KASAADI,
 coalesce(K.ALACAK,0) AS ALACAK,
 coalesce(K.BORC,0) AS  BORC 
 
 --NULL AS DEVIR


FROM KASA K 
LEFT OUTER JOIN REHBER R ON K.REHBERID=R.ID
LEFT OUTER JOIN KASALAR KS ON K.HESAPID=KS.ID AND K.HESAPTURU=''K''
LEFT OUTER JOIN REHBERINI RI2 ON RI2.BOLUM =''Kasa Türleri'' AND RI2.DEGER=K.TUR
  
WHERE 
     ISLEMTARIHI >=  ''$Baslangic$''+'' 00:00'' AND        
     ISLEMTARIHI <=  ''$Bitis$''+'' 23:59'' AND        
     KS.KASAKODU = ''$Kod$''      
 ORDER BY ISLEMTARIHI
' WHERE id = 1129;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT to_char(FATURATARIH,''DD/MM/YYYY'') AS FATURA_TARIHI,FATURANO,R.KOD AS HESAP_KODU,R.FIRMA AS HESAP_ADI
--CASE WHEN coalesce(FT.BIRIMFIYAT,0)=0 THEN F.FATURA_TUTARI ELSE FT.TUTAR END AS TUTAR,
--CASE WHEN coalesce(FT.BIRIMFIYAT,0)=0 THEN F.FATURA_MATRAHI ELSE FT.BIRIMFIYAT END AS ARA_TOPLAM
--KDV_TUTARI AS KDV,
--(SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ) AS INDIRIM,
--FATURA_TUTARI AS NET_TOPLAM
,case when FT.TUR=0 then (select AD from MASRAFGELIR MG where MG.ID=FT.URUNID)
 else (select STOKADI from STOKLAR S where S.ID=FT.URUNID) end||'' ''||coalesce(FT.ACIKLAMA,'''') AS CINSI ,
cast(FT.ADET as varchar) AS MIKTARI ,
KDVDURUM,
CASE WHEN coalesce(FT.BIRIMFIYAT,0)=0 THEN F.FATURA_MATRAHI ELSE FT.BIRIMFIYAT-FT.BIRIMFIYAT/100*coalesce(FT.ISKONTO,0) END AS BIRIMFIYAT,
CASE WHEN coalesce(FT.BIRIMFIYAT,0)=0 THEN F.KDV_TUTARI ELSE((FT.BIRIMFIYAT-FT.BIRIMFIYAT/100*coalesce(FT.ISKONTO,0))/100)*FT.KDV END AS KDV,
CASE WHEN coalesce(FT.BIRIMFIYAT,0)=0 THEN 0 ELSE FT.ISKONTO END AS ISKONTO,
CASE WHEN coalesce(FT.BIRIMFIYAT,0)=0 THEN F.FATURA_TUTARI ELSE cast(FT.TUTAR as double precision)/*FT.TUTAR*FT.ADET*/ END AS TOPLAM,
F.KUR   
FROM REHBER R INNER JOIN FATBASLIK F ON R.ID=F.REHBERID INNER  JOIN FATURA FT ON FT.FATBASID=F.ID
WHERE
FATURATARIH>=''$Baslangic$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00'' AND
F.TUR in (11)
order by  FATURATARIH' WHERE id = 1130;
UPDATE public.dokumler SET sql = '/*PGX*/--İÇERİK HALİ


''$Bitis$ 23:59'' DATETIME,   
''$StokKod$%'' VARCHAR(10),
''$DepoAdi$'' VARCHAR(50)





SELECT HAREKET AS GRUP,BELGETARIH,TARIH,X.KOD,X.STOKADI,'''' AS CARIKOD,'''' AS CARIAD,''$DepoAdi$'' AS DEPO,SUM(MIKTAR) AS GIREN,0 AS CIKAN,
--SUM(MIKTAR) AS KALAN,
R.ANAHTAR FROM 
(
                                               SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI, F.MIKTAR, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, GIRDEPO.ID AS STOKDEPOID, 
                                                                     GIRDEPO.DEPOADI AS STOKDEPO, coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID
                                               WHERE    F.STOKDURUMDEGIS=1 and   (F.TUR = 1) AND (FB.TARIH > coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND (FB.TUR IN (10, 11, 12, 19)) AND FB.TARIH < ''$Baslangic$ 00:00'' AND S.KOD LIKE ''$StokKod$%''+''%'' AND GIRDEPO.DEPOADI LIKE ''$DepoAdi$''+''%'' 
                                               UNION ALL
                                               SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI, -1*(F.MIKTAR) AS MIKTAR, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, CIKDEPO.ID AS STOKDEPOID, 
                                                                     CIKDEPO.DEPOADI AS STOKDEPO, coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID
                                               WHERE    F.STOKDURUMDEGIS=1 and   (F.TUR = 1) AND (FB.TARIH > coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND FB.TARIH < ''$Baslangic$ 00:00'' AND (FB.TUR IN (14, 15, 16, 19)) AND S.KOD LIKE ''$StokKod$%''+''%'' AND CIKDEPO.DEPOADI LIKE ''$DepoAdi$''+''%''  
) AS X INNER JOIN STOKLAR S ON X.KOD=S.KOD  LEFT OUTER JOIN  REHBERINI R   ON R.DEGER=S.ANABIRIM AND  BOLUM=''StokKart_Anabirim''
GROUP BY HAREKET,BELGETARIH,TARIH,X.KOD,X.STOKADI,R.ANAHTAR
-------------------------------------------------------------------------
UNION ALL
-------------------------------------------------------------------------
  SELECT HAREKET AS GRUP,BELGETARIH,TARIH,X.KOD,X.STOKADI, CARIKOD,FIRMA AS CARIAD,DEPO AS DEPO,GIREN,CIKAN,
  --GIREN-CIKAN AS KALAN,
  R.ANAHTAR FROM 
(
                                               SELECT     ''Giren'' AS HAREKET,FATURATARIH AS BELGETARIH,TARIH AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI,R.KOD AS CARIKOD,R.FIRMA, F.MIKTAR AS GIREN ,0 AS CIKAN, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS DEPO,GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, GIRDEPO.ID AS STOKDEPOID, 
                                                                     GIRDEPO.DEPOADI AS STOKDEPO, coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID LEFT OUTER JOIN 
                                                                     REHBER AS R ON R.ID=FB.REHBERID
                                               WHERE   F.STOKDURUMDEGIS=1 and    (F.TUR = 1) AND (FB.TARIH > coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND (FB.TUR IN (10, 11, 12, 19)) AND FB.TARIH < ''$Bitis$ 23:59'' AND S.KOD LIKE ''$StokKod$%''+''%'' AND GIRDEPO.DEPOADI LIKE ''$DepoAdi$''+''%'' 
                                               UNION ALL
                                               SELECT     ''Çıkan'' AS HAREKET,FATURATARIH AS BELGETARIH,TARIH AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI,R.KOD AS CARIKOD,R.FIRMA, 0 AS GIREN,F.MIKTAR AS CIKAN, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, CIKDEPO.DEPOADI AS DEPO,GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, CIKDEPO.ID AS STOKDEPOID, 
                                                                     CIKDEPO.DEPOADI AS STOKDEPO, coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID LEFT OUTER JOIN
                                                                     REHBER AS R ON R.ID=FB.REHBERID
                                               WHERE   F.STOKDURUMDEGIS=1 and  (F.TUR = 1) AND (FB.TARIH > coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND FB.TARIH < ''$Bitis$ 23:59'' AND (FB.TUR IN (14, 15, 16, 19)) AND S.KOD LIKE ''$StokKod$%''+''%'' AND CIKDEPO.DEPOADI LIKE ''$DepoAdi$''+''%''  
) AS X LEFT OUTER JOIN STOKLAR S ON X.KOD=S.KOD  LEFT OUTER JOIN  REHBERINI R   ON R.DEGER=S.ANABIRIM AND  BOLUM=''StokKart_Anabirim''
ORDER BY KOD,TARIH,GRUP
' WHERE id = 1131;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
ID,STOKADI,
SUM(A) AS A ,
SUM(B) AS B ,
SUM(C) AS C ,               
SUM(D) AS D ,
SUM(TOPLAM)
 AS TOPLAM FROM 
(

SELECT 
	ID,STOKADI,
	CASE WHEN REHBERID=''-4'' THEN SUM(ADET) ELSE 0 END AS A ,
	CASE WHEN REHBERID=''-3'' THEN SUM(ADET) ELSE 0 END AS B ,
	CASE WHEN REHBERID=''-2'' THEN SUM(ADET) ELSE 0 END AS C ,
	CASE WHEN REHBERID=''-1'' THEN SUM(ADET) ELSE 0 END AS D ,
	SUM(ADET)
 AS TOPLAM FROM(
	SELECT 
	S.ID,
	S.STOKADI,
	SD.REHBERID,
	SD.ADET
	FROM STOKLAR S
		INNER JOIN SIPARISDETAY SD ON S.ID=SD.URUNID
		INNER JOIN SIPARIS SP ON SP.ID=SD.SIPARISID
		INNER JOIN REHBER R ON R.ID=SD.REHBERID
	where 
	SD.EKLEMETARIHI BETWEEN ''$BASLANGIC$ 00:00'' AND ''$BITIS$ 23:59''  and SD.REHBERID like ''$ID$%''
    ) AS X WHERE ID=X.ID      

GROUP BY ID,STOKADI,REHBERID         

) AS Y GROUP BY ID,STOKADI ORDER BY STOKADI
--SELECT * FROM SIPARISDETAY' WHERE id = 1133;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT TUR,MASRAFKOD,MASRAFAD ,
       SUM(Ocak) as Ocak,SUM(Şubat) as Şubat,SUM(Mart) as Mart,SUM(Nisan) as Nisan,SUM(Mayıs) as Mayıs,SUM(Haziran) as Haziran,
       SUM(Temmuz) as Temmuz,SUM(Ağustos) as Ağustos,SUM(Eylül) as Eylül,SUM(Ekim) as Ekim,SUM(Kasım) as Kasım,SUM(Aralık) as Aralık,
       SUM(Toplam) as Toplam
FROM(
SELECT * FROM(
SELECT TUR,MASRAFKOD,MASRAFAD,
Ocak	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=1  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Şubat	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=2  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Mart      =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=3  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Nisan	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=4  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Mayıs	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=5  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Haziran   =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=6  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Temmuz    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=7  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Ağustos   =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=8  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Eylül	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=9  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Ekim      =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=10 AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Kasım     =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=11 AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Aralık    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=12 AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Toplam    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0)  AS MONEY)
FROM(
	SELECT TUR,MASRAFKOD,MASRAFAD
	FROM(
		SELECT
		''Gelir'' AS TUR ,
		MG.KOD AS MASRAFKOD,
		MG.AD  AS MASRAFAD
		FROM MASRAFGELIR MG 
		WHERE GELIRMI=1
		UNION ALL 
		SELECT 
		''Gelir'' AS TUR ,
		HESAPKODU,HESAPADI 
		FROM HESAPPLANI H WHERE H.VARSAYILAN IN (3)
	)AS ASD
 ) AS X
) AS XYZ
WHERE
Toplam>0

UNION ALL

SELECT * FROM(
SELECT TUR,MASRAFKOD,MASRAFAD,
Ocak	    =CAST(coalesce((SELECT SUM(FATURA_TUTARI) FROM FATBASLIK FT WHERE FT.TUR=17 AND FT.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=1   AND FT.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
