Ekim      =CAST(coalesce((SELECT SUM(FATURA_TUTARI) FROM FATBASLIK FT WHERE FT.TUR=17 AND FT.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND MONTH(FT.FATURATARIH)=10  AND FT.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
