UPDATE public.dokumler SET sql = '/*PGX*/SELECT TUR,MASRAFKOD,MASRAFAD,MERKEZADI,
       SUM(Ocak) as Ocak,SUM(Şubat) as Şubat,SUM(Mart) as Mart,SUM(Nisan) as Nisan,SUM(Mayıs) as Mayıs,SUM(Haziran) as Haziran,
       SUM(Temmuz) as Temmuz,SUM(Ağustos) as Ağustos,SUM(Eylül) as Eylül,SUM(Ekim) as Ekim,SUM(Kasım) as Kasım,SUM(Aralık) as Aralık,
       SUM(Toplam) as Toplam
FROM(
SELECT * FROM (
SELECT TUR,MASRAFKOD,MASRAFAD,SR1.MERKEZADI,
Ocak	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND F1.MERKEZID=SR1.ID AND MONTH(FT.FATURATARIH)=1  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Şubat	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND F1.MERKEZID=SR1.ID AND MONTH(FT.FATURATARIH)=2  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
Mart	    =CAST(coalesce((SELECT SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END) FROM FATURA F1 INNER JOIN FATBASLIK FT ON F1.FATBASID=FT.ID WHERE FT.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 00:00'' AND F1.MERKEZID=SR1.ID AND MONTH(FT.FATURATARIH)=3  AND F1.MASRAFID IN (SELECT ID FROM MASRAFGELIR MG1 WHERE MG1.KOD LIKE X.MASRAFKOD||''%'' )),0) AS MONEY),
