UPDATE public.dokumler SET sql = '/*PGX*/SELECT  
             
F.EKLEMETARIHI AS  ISLEMTARIHI,
MG.KOD AS MASRAFKOD,
MG.AD AS MASRAFAD,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
SUM(CASE WHEN FT.KDVDURUM=''Dahil'' THEN cast(F.TUTAR as double precision)/(1+(F.KDV/100.0)) ELSE F.TUTAR END) AS BORC ,
F.KUR

FROM FATURA F INNER JOIN FATBASLIK FT ON F.FATBASID=FT.ID
			  LEFT JOIN MASRAFGELIR MG ON F.MASRAFID=MG.ID
			  LEFT OUTER JOIN REHBER R ON F.REHBERID=R.ID
			  LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
			
  
WHERE 
     F.EKLEMETARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' AND
      -- F.EKLEMETARIHI BETWEEN ''2013-10-01 00:00'' AND ''2013-10-25 23:59'' AND
     coalesce(F.MASRAFID,'''')<>'''' AND
     MG.KOD LIKE ''$Kod$%''
GROUP BY F.EKLEMETARIHI,MG.KOD,MG.AD,R.KOD,R.FIRMA,F.KUR
ORDER BY MG.KOD,F.EKLEMETARIHI' WHERE id = 1138;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 

ID,TUR,AD,BELGENO,ISLEMTARIHI,MASRAFKOD,MASRAFAD,CARIKOD,CARIAD,KODU,ADI,
ROUND(coalesce(SUM(BORC),0),2) AS BORC,
ROUND(coalesce(SUM(ALACAK),0),2) AS ALACAK,
KUR 
                    
                
FROM (
SELECT
F.ID,                         
FB.TUR,
IT.AD,
FB.FATURANO AS BELGENO,                  
FB.FATURATARIH AS ISLEMTARIHI,
MG.KOD AS MASRAFKOD,
MG.AD AS MASRAFAD,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
 CASE WHEN F.TUR = 1 THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS KODU ,
 CASE WHEN F.TUR = 1 THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS ADI ,
CASE WHEN FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR IN (''€'',''$'') THEN F.DOVIZ_TUTARI /(1+(F.KDV/100.0))
          WHEN FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR IN (''€'',''$'') THEN cast(F.DOVIZ_TUTARI as double precision) /(1+(F.KDV/100.0)) + coalesce((-1*FB.EKVERGI),0)
      
          
          WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) 
          WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)
          WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) + coalesce((-1*FB.EKVERGI),0)
          WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)  + coalesce((-1*FB.EKVERGI),0)
        END AS BORC ,
CASE WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (15,16) and FB.KUR IN (''€'',''$'') THEN (F.DOVIZ_TUTARI)/(1+(F.KDV/100.0)) 
            WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (15,16) and FB.KUR IN (''€'',''$'') THEN (F.DOVIZ_TUTARI)

            WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (15,16) and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) 
            WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (15,16) and FB.KUR NOT IN (''€'',''$'') THEN (cast(F.TUTAR as double precision))
END AS ALACAK ,
F.KUR

FROM FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
                                                 LEFT JOIN MASRAFGELIR MG ON F.TUR=0 AND F.URUNID=MG.ID
                                                 LEFT OUTER JOIN REHBER R ON F.REHBERID=R.ID
                                                 LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
                                               
  
WHERE 
     FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
