UPDATE public.dokumler SET sql = '/*PGX*/SELECT           
--to_char(ISLEMTARIHI,''YYYY.MM.DD'') AS ISLEMTARIHI,
MG.KOD AS MASRAFKOD,
MG.AD AS MASRAFAD,
SUM(K.BORC) AS BORC,
K.KUR
/*
case when K.BORC>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.BORC end AS  BORC,                            
case when K.ALACAK>0 and K.DOVIZ_TUTARI>0 then K.DOVIZ_TUTARI else K.ALACAK end AS ALACAK,
CASE WHEN coalesce(DOVIZ_TUTARI,0)>0 THEN DOVIZ_KURU else K.KUR end as KUR
 */
FROM KASA K 
INNER JOIN MASRAFGELIR MG ON K.MASRAFID=MG.ID

  
WHERE 
     ISLEMTARIHI >=''$Baslangic$ 00:00'' AND
     ISLEMTARIHI <=''$Bitis$ 23:59'' AND
     coalesce(K.BORC,0)<>0 AND
     --K.TUR IN (1,2,21,22,25,31,32,35,41,42,43,45,46,47,48,51,52,53,54,71,72,73,111,121,122) AND
     --coalesce(KS.KASAKODU,'''')<>'''' AND
     coalesce(MASRAFID,'''')<>'''' AND
     MG.KOD LIKE ''$Kod$%''
GROUP BY --to_char(ISLEMTARIHI,''YYYY.MM.DD''),
MG.KOD,MG.AD,K.KUR     
ORDER BY MG.KOD,--to_char(ISLEMTARIHI,''YYYY.MM.DD''),
K.KUR' WHERE id = 1141;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                  
RI2.ANAHTAR AS TUR,
K.ISLEMTARIHI,
MG.KOD AS  MASRAFKOD,
MG.AD AS MASRAFAD,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
K.BORC,
K.KUR

FROM KASA K 
INNER JOIN MASRAFGELIR MG ON K.MASRAFID=MG.ID
LEFT OUTER JOIN REHBER R ON K.REHBERID=R.ID
LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
LEFT OUTER JOIN REHBERINI RI2 ON RI2.BOLUM =''Kasa Türleri'' AND RI2.DEGER=K.TUR
  
WHERE 
     ISLEMTARIHI >=''$Baslangic$ 00:00'' AND
     ISLEMTARIHI <=''$Bitis$ 23:59'' AND
     coalesce(K.BORC,0)<>0 AND
     coalesce(MASRAFID,'''')<>'''' AND
     MG.KOD LIKE ''$Kod$%''
ORDER BY MG.KOD,K.ISLEMTARIHI' WHERE id = 1142;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
       SUBE,FATURATARIH,FATURANO,MUSTERI,SATICIADI,PROJEKODU,MATRAH,MALIYET,MATRAH-MALIYET
 AS KAR FROM(
select 
       R2.FIRMA AS SUBE ,FB.FATURATARIH,FB.FATURANO,R.FIRMA AS MUSTERI,R1.FIRMA AS SATICIADI,P.PROJEKODU,FB.FATURA_MATRAHI AS MATRAH ,
       coalesce(FATURA_MALIYETI_ORT,0)
 AS MALIYET from 
       FATBASLIK FB INNER JOIN REHBER R   ON FB.REHBERID=R.ID 
		    LEFT JOIN  REHBER R1  ON FB.SATICIKODU=R.ID
		    INNER JOIN REHBER R2  ON R.SUBEID=R2.ID AND R2.ID<0  
		    LEFT JOIN  PROJELER P ON FB.PROJEID=P.ID
WHERE 
        FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND R.FIRMA LIKE ''$Firma$%''
    AND FB.TUR IN (15,16)
) AS X
WHERE
        coalesce(SUBE,'''') LIKE ''$Subesi$%''
    AND coalesce(SATICIADI,'''') LIKE ''$SaticiAdi$%''
    AND coalesce(PROJEKODU,'''') LIKE ''$ProjeKodu$%''' WHERE id = 1145;
UPDATE public.dokumler SET sql = '/*PGX*/
		''$BitTar$ 23:59'' DATETIME




SELECT TOP 100 R.FIRMA,SAYI=COUNT(REHBERID) 
