' WHERE id = 1148;
UPDATE public.dokumler SET sql = '/*PGX*/

SET language turkish
IF ''$OnemDerecesi$''=''Acil''
BEGIN
SELECT AY=MONTH(S.BASLAMATARIHI), 
       AYADI= DATENAME(MONTH,S.BASLAMATARIHI), 
       TOPLAM=COUNT(S.ID),	   	   
       YUZDE=CAST((CAST(COUNT(S.ID)*100 AS NUMERIC(10,2))/(SELECT COUNT(S1.ID) FROM SERVIS S1 WHERE YEAR(S1.BASLAMATARIHI)=''$Yil$'')) AS NUMERIC(10,2))
FROM SERVIS S INNER JOIN REHBER R ON S.REHBERID=R.ID
              LEFT OUTER JOIN GENINI G ON G.DEGER=S.TURU AND G.BOLUM=-3006
              LEFT OUTER JOIN PROJELER P ON S.PROJEID=P.ID
              LEFT OUTER JOIN EKIPMANLAR E ON S.EKIPMANID=E.ID
WHERE 
	YEAR(S.BASLAMATARIHI)= ''$Yil$''  AND 
	coalesce(FIRMA,'''') LIKE ''$Firma$%'' AND 
	--coalesce(PROJEKODU,'''') LIKE ''$ProjeKodu$%'' AND 
	coalesce(E.AD,'''') LIKE ''$ÜrünAdı$%'' AND
    coalesce(G.ANAHTAR,'''') LIKE ''$Turu$%'' AND 
	S.ACIL=1	
GROUP BY MONTH(S.BASLAMATARIHI), 
         DATENAME(MONTH,S.BASLAMATARIHI)  
ORDER BY 1
END
IF ''$OnemDerecesi$''=''Önemli''
BEGIN
SELECT AY=MONTH(S.BASLAMATARIHI), 
       AYADI= DATENAME(MONTH,S.BASLAMATARIHI), 
       TOPLAM=COUNT(S.ID),	   	   
       YUZDE=CAST((CAST(COUNT(S.ID)*100 AS NUMERIC(10,2))/(SELECT COUNT(S1.ID) FROM SERVIS S1 WHERE YEAR(S1.BASLAMATARIHI)=''$Yil$'')) AS NUMERIC(10,2))
FROM SERVIS S INNER JOIN REHBER R ON S.REHBERID=R.ID
              LEFT OUTER JOIN GENINI G ON G.DEGER=S.TURU AND G.BOLUM=-3006
              LEFT OUTER JOIN PROJELER P ON S.PROJEID=P.ID
              LEFT OUTER JOIN EKIPMANLAR E ON S.EKIPMANID=E.ID
WHERE 
	YEAR(S.BASLAMATARIHI)= ''$Yil$''  AND 
	coalesce(FIRMA,'''') LIKE ''$Firma$%'' AND 
	--coalesce(PROJEKODU,'''') LIKE ''$ProjeKodu$%'' AND 
	coalesce(E.AD,'''') LIKE ''$ÜrünAdı$%'' AND
    coalesce(G.ANAHTAR,'''') LIKE ''$Turu$%'' AND 
	S.ONEMLI=1
GROUP BY MONTH(S.BASLAMATARIHI),
         DATENAME(MONTH,S.BASLAMATARIHI)  
ORDER BY 1
END

IF coalesce(''$OnemDerecesi$'','''')=''''
BEGIN
SELECT AY=MONTH(S.BASLAMATARIHI), 
       AYADI= DATENAME(MONTH,S.BASLAMATARIHI), 
       TOPLAM=COUNT(S.ID),	   	   
       YUZDE=CAST((CAST(COUNT(S.ID)*100 AS NUMERIC(10,2))/(SELECT COUNT(S1.ID) FROM SERVIS S1 WHERE YEAR(S1.BASLAMATARIHI)=''$Yil$'')) AS NUMERIC(10,2))
FROM SERVIS S INNER JOIN REHBER R ON S.REHBERID=R.ID
              LEFT OUTER JOIN GENINI G ON G.DEGER=S.TURU AND G.BOLUM=-3006
              LEFT OUTER JOIN PROJELER P ON S.PROJEID=P.ID
              LEFT OUTER JOIN EKIPMANLAR E ON S.EKIPMANID=E.ID
WHERE 
	YEAR(S.BASLAMATARIHI)= ''$Yil$''  AND 
	coalesce(FIRMA,'''') LIKE ''$Firma$%'' AND 
	--coalesce(PROJEKODU,'''') LIKE ''$ProjeKodu$%'' AND 
	coalesce(E.AD,'''') LIKE ''$ÜrünAdı$%'' AND
    coalesce(G.ANAHTAR,'''') LIKE ''$Turu$%''
GROUP BY MONTH(S.BASLAMATARIHI),
         DATENAME(MONTH,S.BASLAMATARIHI)  
ORDER BY 1
END
' WHERE id = 1152;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
