                           WHEN coalesce(KDVMUHAFIYETI,0)=90 then ''(9/10)''
                           WHEN coalesce(KDVMUHAFIYETI,0)=70 then ''(7/10)''
                           WHEN coalesce(KDVMUHAFIYETI,0)=50 then ''(5/10)''
                           WHEN coalesce(KDVMUHAFIYETI,0)=20 then ''(2/10)''
                           WHEN coalesce(KDVMUHAFIYETI,0)=100 then''(Tam)''
end AS TEVKIFAT_ORANI ,
 CASE WHEN KDVDURUM =''Dahil'' THEN TUTAR-round((TUTAR*(100.0/(100.0+KDV))),2) 
						when OTVMIKTAR>0.0 then  round(((TUTAR+((CASE WHEN F.OTVYUZDE =0 THEN round((ADET*OTVMIKTAR),2) ELSE round((OTVMIKTAR*(round((F.BIRIMFIYAT*F.ADET),2)/100.0)),2)  END)))*KDV/100.0),2)  
						ELSE round((KDV*(F.TUTAR/100.0)),2)  END AS HESAPLANAN_KDV ,
 CASE WHEN KDVDURUM =''Dahil'' THEN TUTAR-(TUTAR*(100.0/(100.0+((KDV*(100.0-coalesce(KDVMUHAFIYETI,0))/100.0))))) ELSE ((KDV*(100.0-coalesce(KDVMUHAFIYETI,0))/100.0)*(TUTAR/100.0))  END AS TEVKIFAT_BEYAN ,
 round((CASE WHEN KDVDURUM =''Dahil'' THEN TUTAR-round((TUTAR*(100.0/(100.0+((KDV*(coalesce(KDVMUHAFIYETI,0))/100.0))))),2) 
						ELSE round(((KDV*(coalesce(KDVMUHAFIYETI,0))/100.0)*(TUTAR/100.0)),2)  END),2) AS TEVKIFAT ,
F.TUTAR+CASE WHEN KDVDURUM =''Dahil'' THEN TUTAR-(TUTAR*(100.0/(100.0+((KDV*(100.0-coalesce(KDVMUHAFIYETI,0))/100.0))))) ELSE ((KDV*(100.0-coalesce(KDVMUHAFIYETI,0))/100.0)*(TUTAR/100.0))  END
 AS TOPLAM FROM
       FATBASLIK FB INNER JOIN FATURA F ON FB.ID = F.FATBASID
	   INNER JOIN REHBER R ON FB.REHBERID=R.ID
WHERE
       FB.ID >0 and coalesce(KDVMUHAFIYETI,0)>0	   
       AND FATURATARIH>=''$Baslama$ 00:00:00'' AND FATURATARIH<=''$Bitis$ 23:59:00''' WHERE id = 1153;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT  CASE WHEN FB.TUR = 11 THEN ''Alış Faturası'' ELSE ''Satış Faturası'' END AS TUR ,
R.FIRMA,FB.FATURATARIH,FB.FATURANO AS BELGENO,FB.FATURA_MATRAHI,FB.EKVERGI AS STOPAJ 
FROM FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
              INNER JOIN REHBER R ON R.ID=FB.REHBERID
WHERE FB.TUR IN (11,15) AND FB.EKVERGI<0    AND  FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''  order by 1' WHERE id = 1154;
