UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
       R2.FIRMA AS SUBE,XXX.KOD,XXX.FIRMA,SINIFADI,GRUPADI,BORC,ALACAK,cast(BAKIYE as float) AS BAKIYE ,KUR  
FROM (
select  DISTINCT R.SUBEID,R.KOD ,R.FIRMA,GSnf.ANAHTAR AS SINIFADI ,GGrp.ANAHTAR AS GRUPADI ,cast(TOPLAM_BORC as float) AS BORC ,cast(TOPLAM_ALACAK as float) AS ALACAK,KUR ,TOPLAM_BORC-TOPLAM_ALACAK 

  AS BAKIYE FROM(
    select
		REHBERID,SUM(coalesce(BORC,0)) AS TOPLAM_BORC ,SUM(coalesce(ALACAK,0)) AS TOPLAM_ALACAK ,coalesce(KUR,''TL'')
	 AS KUR from (
	   SELECT
		REHBERID,
		SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
		0 AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR

		--KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
		FROM FATBASLIK F
		WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17)) 
		AND FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
		GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

	UNION ALL

		SELECT REHBERID,
		0 AS BORC,
		SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
		FROM FATBASLIK F
		WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13)) 
		AND FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
		GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

	UNION ALL

		SELECT REHBERID,
		SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
		SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR
		FROM KASA K
		WHERE TUR not between 60 and 79  AND 
		ISLEMTARIHI  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
		GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

	UNION ALL
		SELECT CH.REHBERID,
		SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end) AS BORC ,
		SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end) AS ALACAK ,
		CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR
		FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
		WHERE CH.ISLEM in(130,131,132,134,137,140,141) and 
		CH.TARIH  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
		GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_KURU else c.KUR end

	UNION ALL

		SELECT REHBERID,
		0 AS BORC,
		SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
		FROM SENETLER S
		WHERE TUR = 24   
		AND TARIH  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
		GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END

	UNION ALL

		SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
		BORC,0 AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
		FROM SENETLER S
		WHERE TUR = 34  
		AND TARIH  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
		GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

		) as asd
	group by REHBERID,KUR) AS DSA
	INNER JOIN REHBER R ON 	DSA.REHBERID=R.ID
	LEFT OUTER JOIN 	REHBERPERSONEL P on R.ID = P.REHBERID 


		--( 1 = CASE WHEN  @ILGILIARAMA = 1 THEN 1
		--		   WHEN  @ILGILIARAMA = 0 AND isnull (P.VARSAYILAN,1) = 1 THEN 1 ELSE 0
		--		   END  )

 left outer join REHBER R2 on R2.ID=R.TEMSILCI  
 left outer join (Select R1.ID,RB.BILGI from REHBER R1 
 left outer join REHBERILETISIM RI on R1.ID=RI.REHBERID 
 Left outer join REHBERBILGI RB on RB.YER_ID=RI.ID  
 left outer join REHBERAYAR RA on RA.SIRA=RB.SIRA Where RI.VARSAYILAN=1 and RB.YERI=1 and RA.VARSAYILAN=8) X on X.ID=R.ID 
 left outer join GENINI GSnf on R.SINIF=GSnf.DEGER and GSnf.BOLUM=-2203 and GSnf.DIL=-1 --2203  sınıf
 left outer join GENINI GGrp on R.GRUP=GGrp.DEGER and GGrp.BOLUM=-2202 and GGrp.DIL=-1  --2202  grup
   
 where R.GRUP<>335 and R.ID > 0 
 and R.DURUM>0  and  coalesce(R.ID,'''')<>'''' --and (coalesce(TOPLAM_BORC,0.0) - coalesce(TOPLAM_ALACAK,0.0)) > 1.0 
 AND R.KOD like ''$Kod$%'' 
 AND coalesce(GSnf.ANAHTAR,'''') LIKE ''$SinifAdi$%''   AND
 1 = case when (''$BA$'' in (''B'',''''))and(TOPLAM_BORC>=TOPLAM_ALACAK) then 1
          when (''$BA$'' in (''A'',''''))and (TOPLAM_ALACAK>=TOPLAM_BORC) then 1
          else 0 end
   ) AS XXX       
 INNER JOIN REHBER R2  ON  XXX.SUBEID=R2.ID
 ORDER BY KUR,XXX.FIRMA' WHERE id = 1163;
UPDATE public.dokumler SET sql = '/*PGX*/











SELECT * FROM (    
select 
                R.FIRMA,
--            FB.ID,F.ID AS FATURAID,
                FB.FATURATARIH,FB.FATURANO,

        (SELECT ANAHTAR FROM GENINI G WHERE SI.BELGETUR=G.DEGER AND G.BOLUM=''-1005'' AND G.DIL=-1) AS BELGETUR ,
        S.KOD,S.STOKADI,
                F.ISKONTOLUBRMFIYAT AS BIRIMFIYAT ,--CASE WHEN F.TUTAR=0 THEN 0 ELSE F.TUTAR/F.ADET END,
       -- F.BIRIMFIYAT AS BFIYAT,F.ISKONTO,F.TUTAR AS FTUTAR,
                SI.MIKTAR,
        --G1.ANAHTAR AS BIRIM,
        (SELECT ANAHTAR FROM GENINI G1 WHERE F.BIRIM = G1.DEGER AND G1.BOLUM=''-2702'' AND G1.DIL=-1)  AS BIRIM ,
                (F.TUTAR/F.ADET)*SI.MIKTAR AS TUTAR ,
                SI.ACIKLAMA AS LOTNO,
        CASE WHEN IZLEMTUR=2 THEN SI.SKT ELSE NULL END AS SKT ,
                 CASE WHEN IZLEMTUR=1 THEN IZLEM ELSE NULL END
 AS SERINO from 
                STOKIZLEME SI 
                               INNER JOIN FATBASLIK FB ON 
                                               SI.BASLIKID=FB.ID 
                               INNER JOIN FATURA F ON
                                               SI.SATIRID=F.ID
                               INNER JOIN STOKLAR S ON
                                               SI.STOKID=S.ID
                               INNER JOIN REHBER R ON
                                               FB.REHBERID=R.ID

WHERE
                FB.FATURATARIH BETWEEN coalesce(''$FBaslangic$ 00:00'',''1900-01-01 00:00'') AND coalesce(''$FBitis$ 00:00'',''2200-01-01 23:59'') and
                FB.FATURANO LIKE ''$FaturaNo$%''
        and FB.DURUM <> 6 AND F.MIKTAR>0
) AS X
WHERE
                coalesce(FIRMA,'''') LIKE ''$Firma$%'' AND
                coalesce(BELGETUR,'''') LIKE ''$BelgeTur$%'' AND
                coalesce(KOD,'''') LIKE ''$Kod$%'' AND
                coalesce(STOKADI,'''') LIKE ''$StokAdi$%'' AND
                coalesce(LOTNO,'''') LIKE ''$LotNo$%'' AND
        coalesce(SERINO,'''') LIKE ''$SeriNo$%'' AND
                ((SKT IS NULL)OR(SKT BETWEEN coalesce(''$SBaslangic$ 00:00'',''1900-01-01 00:00'') AND coalesce(''$SBitis$ 00:00'',''2200-01-01 23:59'') ))

 order by FATURANO,FATURATARIH,LOTNO,SERINO,SKT,FIRMA
' WHERE id = 1166;
UPDATE public.dokumler SET sql = '/*PGX*/select  
R1.KOD,R1.FIRMA,PI.IZINBASLANGIC,PI.IZINBITIS,PI.HAK,PI.ACIKLAMA,PI.DONEM,PI.IZINLIGUNSAYISI,
 R2.FIRMA AS IZINVEREN , 
 (select BILGI from REHBERBILGI where YERI=3 and  YER_ID =R1.ID and SIRA=12 LIMIT 1 ) AS BOLUMU ,  
 (select ANAHTAR from REHBERINI where BOLUM = ''CariKart_PerIzinTuru'' and DEGER = PI.IZINTURU LIMIT 1 )   AS IZINTURUADI ,
PI.HAK-PI.IZINLIGUNSAYISI

 AS KALAN from PERSONELIZIN PI
inner join REHBER R1 on PI.REHBERID=R1.ID
inner join REHBER R2 on PI.IZINVERENREHBERID=R2.ID
where 
R1.FIRMA LIKE ''$Calisan$%''
and DONEM LIKE ''$Donem$%''' WHERE id = 1168;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                           
                   G.ID AS GOREVID,
                   CASE ACKAPA WHEN 1 THEN ''KAPALI'' WHEN 0 THEN ''AÇIK'' END AS DURUM ,
                   G.BASLAMATARIHI,GEN.ANAHTAR AS TÜR,GY.YORUM,RB.FIRMA AS EKLEYEN,R.FIRMA AS CARİ,RP.FIRMA AS İLGİLİ,
                   REH.FIRMA AS YORUMYAPAN,GY.EKLEMETARIHI, G.KONUSU,GY.TUR,
                   (select ANAHTAR from GENINI where BOLUM=-2210 and DEGER=R.BOLGE and DIL = -1) AS BOLGE ,
                   (select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=R.ALTBOLGE AND GB.DEGER=R.BOLGE
                                where GALT.BOLUM like ''-2210%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2210 ) AS ALTBOLGE ,
                                 (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
(select FIRMA from REHBER where ID=R.SUBEID) AS SUBEAD ,
                   CASE GY.TUR WHEN 1 THEN ''NOTLAR'' WHEN 2 THEN ''YORUM'' END AS TÜRÜ,
       CASE ACKAPA WHEN 1 THEN ''KAPALI'' WHEN 0 THEN ''AÇIK'' END AS DURUM
FROM GOREVLER G 
                            LEFT OUTER JOIN GOREVYORUM GY  ON G.ID=GY.GOREVID
                            LEFT OUTER JOIN REHBER R ON R.ID=G.REHBERID
                            LEFT OUTER JOIN REHBERILETISIM RI ON RI.REHBERID=R.ID  AND RI.VARSAYILAN=1
                            LEFT OUTER JOIN REHBER RB  ON G.EKLEYEN=RB.ID
                            LEFT OUTER JOIN REHBER RP ON RP.ID=G.MUS_ILGILI
                            LEFT OUTER JOIN GENINI GEN ON GEN.DEGER=G.TURU and GEN.BOLUM=-21044
                            LEFT OUTER JOIN REHBER REH ON GY.EKLEYEN=REH.ID
WHERE    G.BASLAMATARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND   cast(G.EKLEYEN as varchar) LIKE ''$Ekleyen$%''
AND cast(coalesce(GEN.DEGER,'''') as varchar) LIKE ''%$Tur$%''
AND coalesce((select ANAHTAR from GENINI where BOLUM=-2210 and DEGER=R.BOLGE and DIL = -1),'''') LIKE ''$Bolge$%''
            
            and  coalesce((select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=R.ALTBOLGE AND GB.DEGER=R.BOLGE
                                where GALT.BOLUM like ''-2210%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2210 ),'''')  like ''$Altbolge$%'' 
            and coalesce((SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ),'''') LIKE ''$Il$%''
            AND coalesce((select FIRMA from REHBER where ID=R.SUBEID),'''') like ''$Sube$%''
            AND   R.FIRMA LIKE ''%$Firma$%''
ORDER BY G.BASLAMATARIHI' WHERE id = 1171;
UPDATE public.dokumler SET sql = '/*PGX*/
	''$BitTar$ 23:59'' DATETIME,
	''$Asama$'' VARCHAR(50),
        ''$Durum$'' VARCHAR(50),
        ''$Firma$'' VARCHAR(200),
        ''$Personel$'' VARCHAR(200)








--bitmiş
SELECT X.DURUM,AD,PERSONEL,X.FIRMA,ACIKLAMA,COZUM,ASAMA,ASAMADETAY,BASTAR,BITTAR,X.ID FROM (
SELECT 
	   DURUM=''Bitmiş'',
	   E.AD,
	   PERSONEL=(SELECT fn_GorevVerilenKisilerUzunAd(12, S.ID)),
	   R.FIRMA,
	   SB.ACIKLAMA,
	   SB.COZUM,
	   ASAMA=CASE WHEN SA.ASAMA=10 THEN ''Analiz''
				  WHEN SA.ASAMA=20 THEN ''Tasarım''
				  WHEN SA.ASAMA=30 THEN ''Geliştirme''
				  WHEN SA.ASAMA=40 THEN ''Alfa Test''
				  WHEN SA.ASAMA=41 THEN ''Beta Test''
				  WHEN SA.ASAMA=42 THEN ''Yayınlama''
			 END,
	   ASAMADETAY=SA.ACIKLAMA,
	   SA.BASTAR,
	   SA.BITTAR,
           S.ID
FROM SERVIS S INNER JOIN SERVISASAMA SA ON SA.SERVISID=S.ID
			  INNER JOIN REHBER R ON R.ID=S.REHBERID
			  INNER JOIN EKIPMANLAR E ON E.ID=S.EKIPMANID
			  INNER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID
WHERE S.BASLAMATARIHI BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
	  AND coalesce(SA.BITTAR,'''')<>''''	  
UNION ALL
SELECT 
	   DURUM=''Bitmemiş'',
	   E.AD,
	   PERSONEL=(SELECT fn_GorevVerilenKisilerUzunAd(12, S.ID)),
	   R.FIRMA,
	   SB.ACIKLAMA,
	   SB.COZUM,
	   ASAMA=CASE WHEN SA.ASAMA=10 THEN ''Analiz''
				  WHEN SA.ASAMA=20 THEN ''Tasarım''
				  WHEN SA.ASAMA=30 THEN ''Geliştirme''
				  WHEN SA.ASAMA=40 THEN ''Alfa Test''
				  WHEN SA.ASAMA=41 THEN ''Beta Test''
				  WHEN SA.ASAMA=42 THEN ''Yayınlama''
			 END,
	   ASAMADETAY=SA.ACIKLAMA,
	   SA.BASTAR,
	   SA.BITTAR,
           S.ID
FROM SERVIS S INNER JOIN SERVISASAMA SA ON SA.SERVISID=S.ID
			  INNER JOIN REHBER R ON R.ID=S.REHBERID
			  INNER JOIN EKIPMANLAR E ON E.ID=S.EKIPMANID
			  INNER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID
WHERE S.BASLAMATARIHI BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
	  AND coalesce(SA.BITTAR,'''')='''' 
) AS X
     LEFT JOIN GOREVKULLANICI GK ON GK.LISTGOREVID=X.ID
     LEFT JOIN REHBER RR ON RR.ID=GK.REHBERID
WHERE X.DURUM LIKE ''$Durum$''+''%''
      AND ASAMA LIKE ''$Asama$''+''%''
      AND X.FIRMA LIKE ''$Firma$''+''%''
      AND RR.FIRMA LIKE ''$Personel$''+''%''
ORDER BY ID
' WHERE id = 1174;
UPDATE public.dokumler SET sql = '/*PGX*/
	:PDonemSon DATETIME




SELECT 
       XXX.KOD,XXX.FIRMA,BAKIYE=cast(BAKIYE as double precision),KUR,TLKARSILIK=cast((BAKIYE*(select D.SATIS from DOVIZ D where D.CINSI=XXX.KUR order by D.TARIH desc LIMIT 1 )) as double precision)  
FROM (
select  DISTINCT R.SUBEID,R.KOD ,R.FIRMA,cast(TOPLAM_BORC as float) AS BORC ,cast(TOPLAM_ALACAK as float) AS ALACAK,KUR ,BAKIYE=TOPLAM_BORC-TOPLAM_ALACAK 

 FROM(
    select
		REHBERID,TOPLAM_BORC=SUM(coalesce(BORC,0)),TOPLAM_ALACAK=SUM(coalesce(ALACAK,0)),KUR=coalesce(KUR,''TL'')
	from (
	   SELECT
		REHBERID,
		SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
		0 AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR

		--KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
		FROM FATBASLIK F
		WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17)) 
		AND FATURATARIH BETWEEN :PDonemBas AND :PDonemSon
		GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

	UNION ALL

		SELECT REHBERID,
		0 AS BORC,
		SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
		FROM FATBASLIK F
		WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13)) 
		AND FATURATARIH BETWEEN :PDonemBas AND :PDonemSon
		GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

	UNION ALL

		SELECT REHBERID,
		SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
		SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR
		FROM KASA K
		WHERE TUR not between 60 and 79  
		AND ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon
		GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

	UNION ALL
		SELECT CH.REHBERID,
		BORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
		ALACAK=SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
		CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR
		FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
		WHERE CH.ISLEM in(130,131,132,134,137,140,141) 
		AND CH.TARIH BETWEEN :PDonemBas AND :PDonemSon
		GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_KURU else c.KUR end

	UNION ALL

		SELECT REHBERID,
		0 AS BORC,
		SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
		FROM SENETLER S
		WHERE TUR = 24   
		AND TARIH BETWEEN :PDonemBas AND :PDonemSon
		GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END

	UNION ALL

		SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
		BORC,0 AS ALACAK,
		CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
		FROM SENETLER S
		WHERE TUR = 34  
		AND TARIH BETWEEN :PDonemBas AND :PDonemSon
		GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

		) as asd
	group by REHBERID,KUR) AS DSA
	INNER JOIN REHBER R ON 	DSA.REHBERID=R.ID AND coalesce(R.KDR_Disi,''False'') =''False''
    where  
		R.ID > 0 and coalesce(R.ID,'''')<>'''' and R.GRUP <> 335 
		AND TOPLAM_BORC>TOPLAM_ALACAK          
   ) AS XXX       
 INNER JOIN REHBER R2  ON  XXX.SUBEID=R2.ID
 ORDER BY KUR,XXX.FIRMA
' WHERE id = 1177;
