UPDATE public.dokumler SET sql = '/*PGX*/
	:PDonemSon DATETIME




select
	HESAPKODU,HESAPADI,BAKIYE=SUM(ALACAK-BORC),K1.KUR,TLKARSILIK=cast((SUM(ALACAK-BORC)*(select D.SATIS from DOVIZ D where D.CINSI=K1.KUR order by D.TARIH desc LIMIT 1 )) as double precision)
from  
	BANKAHESAPLAR BH inner join KASA K1 on BH.ID=K1.HESAPID
where 
	K1.ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon
	and K1.HESAPTURU=''B'' AND coalesce(ONLINEHESAPHAREKETI,''0'') = 0
group by HESAPKODU,HESAPADI,K1.KUR
' WHERE id = 1179;
