UPDATE public.dokumler SET sql = '/*PGX*/
	:PDonemSon DATETIME



SELECT
	C.KOD,ACIKLAMA=R.FIRMA+''-''+cast(C.SERINO as varchar),IT.AD AS TUR,C.VADE,TUTAR=cast(C.TUTAR as double precision),KUR=C.KUR,TLKARSILIK=CASE WHEN DOVIZ_KURU = ''TL'' THEN cast(DOVIZ_TUTARI as double precision)WHEN C.KUR = ''TL'' THEN cast(C.TUTAR as double precision) END 
FROM 
	CEKLER C inner join REHBER R on C.REHBERID=R.ID INNER JOIN ISLEMTURLERI IT ON IT.TUR = C.TUR 
WHERE 
	C.TUR in (130,132,133,134,135,138) AND C.CEKSENET = 101
	AND C.VADE BETWEEN :PDonemBas AND :PDonemSon
ORDER BY C.VADE
' WHERE id = 1184;
