UPDATE public.dokumler SET sql = '/*PGX*/
	:PDonemSon DATETIME




select 
	KREDIKODU,ADI,
	KREDI_TUTARI=sum(P.TAKSIT),
	KALAN_TUTAR=sum(case when P.ODENMIS=1 and P.TARIH<=:PDonemSon then 0.0 else P.TAKSIT end) ,KR.KUR  ,
 TLKARSILIK=cast((sum(case when P.ODENMIS=1 and P.TARIH<=:PDonemSon then 0.0 else P.TAKSIT end)*(select D.SATIS from DOVIZ D where D.CINSI=KR.KUR order by D.TARIH desc LIMIT 1 )) as double precision)
from KREDILER KR
	left join PLANKREDI P on P.KREDIID=KR.ID
where 
	KR.DURUM>0 and 
	GENELKREDITIPI=1 
	and exists(select 1 from PLANKREDI P2 where P2.KREDIID=KR.ID and P2.TARIH>=:PDonemSon and coalesce(P2.ODENMIS,0)=0)
GROUP BY 
	KR.ID,KREDIKODU,ADI,SOZLESMENO,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KAPANISTARIHI,KREDITAKSIT
union all
select 
	KREDIKODU,ADI,
	KREDI_TUTARI=0,KALAN_TUTAR=coalesce(sum(BORC),0)-coalesce(sum(ALACAK),0) ,KR.KUR ,
 TLKARSILIK=cast((coalesce(sum(BORC),0)-coalesce(sum(ALACAK),0)*(select D.SATIS from DOVIZ D where D.CINSI=KR.KUR order by D.TARIH desc LIMIT 1 )) as double precision)

from KREDILER KR
	left outer join KASA KS on HESAPTURU=''R'' and KS.HESAPID=KR.ID
where 
	KR.DURUM>0 
	and KS.TUR<>2
	and GENELKREDITIPI=2  
    and	KS.ISLEMTARIHI<=:PDonemSon
GROUP BY 
	KR.ID,KREDIKODU,ADI,SOZLESMENO,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KAPANISTARIHI,KREDITAKSIT
' WHERE id = 1186;
