UPDATE public.dokumler SET sql = '/*PGX*/


SELECT @TopTutar=SUM(FATURA_MATRAHI) 
FROM FATBASLIK FB INNER JOIN REHBER R ON R.ID=FB.REHBERID AND TUR=15
WHERE FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''
having SUM(FATURA_MATRAHI)>0

SELECT FIRMA,TUTAR,ORAN,KUMULATIF FROM (
SELECT R.FIRMA, SUM(FATURA_MATRAHI) AS TUTAR,@TopTutar AS TOPLAMTUTAR,
100.0*SUM(FATURA_MATRAHI)/@TopTutar AS ORAN ,
 sum(100.0*SUM(FATURA_MATRAHI)/@TopTutar) over(order by SUM(FATURA_MATRAHI)DESC) 
 AS KUMULATIF FROM FATBASLIK FB  INNER JOIN REHBER R ON R.ID=FB.REHBERID AND TUR=15
WHERE FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''
GROUP BY R.FIRMA
having SUM(FATURA_MATRAHI)>0
)AS XX where KUMULATIF <=''$Yuzde$''
ORDER BY 2 DESC
' WHERE id = 1190;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                               
         RB.FIRMA AS EKLEYEN,
         coalesce(GEN.ANAHTAR,''BOŞ'') AS TÜR,
         FİRMA SAYISI=(SELECT COUNT(DISTINCT G1.REHBERID) FROM GOREVLER G1 WHERE G1.EKLEYEN=RB.ID AND G1.BASLAMATARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''),
         COUNT(*)
 AS SAYI FROM GOREVLER G  
                            LEFT OUTER JOIN GOREVYORUM GY ON G.ID=GY.GOREVID
                            LEFT OUTER JOIN REHBER R ON R.ID=G.REHBERID
                            LEFT OUTER JOIN REHBER RB  ON G.EKLEYEN=RB.ID
                            LEFT OUTER JOIN REHBER RP ON RP.ID=G.MUS_ILGILI
                            LEFT OUTER JOIN GENINI GEN ON GEN.DEGER=G.TURU and GEN.BOLUM=-21044
                            LEFT OUTER JOIN REHBER REH ON GY.EKLEYEN=REH.ID
WHERE   G.BASLAMATARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND   cast(G.EKLEYEN as varchar) LIKE ''$Ekleyen$%''
AND cast(coalesce(GEN.DEGER,'''') as varchar) LIKE ''%$Tur$%''
AND   R.FIRMA LIKE ''%$Firma$%''
GROUP BY RB.ID,RB.FIRMA,GEN.ANAHTAR
ORDER BY EKLEYEN,TÜR  DESC' WHERE id = 1192;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                                   
         RB.FIRMA AS EKLEYEN,
