UPDATE public.dokumler SET sql = '/*PGX*/select                                  
       TÜRÜ=(select ANAHTAR from GENINI G where BOLUM=-2112 and DIL=-1 and G.DEGER=P.TURU),
       (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2114 AND G.DEGER=P.DURUM LIMIT 1 ) AS DURUM ,
       (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-3401 AND G.DEGER=P.OLASILIK LIMIT 1 ) AS OLASILIK ,
       (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2113 AND G.DEGER=P.ASAMA LIMIT 1 ) AS ASAMA ,
       KONUSU,
    (select ANAHTAR  from GENINI G where G.BOLUM=''-2112''||cast(P.TURU as varchar) and G.DEGER=P.TIPI and DIL = -1) AS TIPI ,
       (SELECT FIRMA FROM REHBER R WHERE R.ID=P.EKLEYEN) AS EKLEYEN ,
       (SELECT FIRMA FROM REHBER R WHERE R.ID=P.PRJ_SORUMLUSU_ID) AS SORUMLU ,
       (select R.FIRMA from REHBER R where R.ID=R1.SUBEID LIMIT 1 ) AS SUBE ,
       PROJEADI,
       PROJEKODU,
       (SELECT FIRMA FROM REHBER R WHERE R.ID=P.REHBERID) AS MUSTERI ,
       (SELECT FIRMA FROM REHBER RP WHERE RP.ID=P.ILGILI LIMIT 1 ) AS ILGILI ,
       P.NOTLAR,
       LISTEFIYATI,
       LISTEKUR,
       SATISFIYATI,
        CASE WHEN  (SELECT COUNT(ID) FROM DOKUMAN WHERE MODUL = 70 AND MODULID = P.ID AND KLASOR <> -1  LIMIT 1 ) >0  THEN 1 ELSE 0 END AS DOSYAVAR ,
       BASLAMATARIHI,
       BITISTARIHI,
       year(P.BITISTARIHI) AS BITISYIL ,
       month(P.BITISTARIHI) AS BITISAY ,
         to_char((SELECT BITISTARIHI FROM GOREVLER A WHERE PROJEID = P.ID and ACKAPA=1 ORDER BY BITISTARIHI DESC  LIMIT 1 ),''DD/MM/YYYY'') AS SONAKTIVITETARIHI ,
       to_char((select TARIH from TEKLIF T where T.PROJEID = P.ID order by TARIH desc LIMIT 1 ),''DD/MM/YYYY'') AS SONTEKLIFTARIHI ,
       (select ANAHTAR from GENINI G where BOLUM=-2115 and DIL=-1 and G.DEGER=P.SONUC) AS SONUC ,
       SONUCACIKLAMA,
        (SELECT KONUSU FROM GOREVLER A WHERE PROJEID = P.ID and ACKAPA=1 ORDER BY BITISTARIHI DESC  LIMIT 1 ) AS SONAKTIVITEKONUSU ,
          to_char((SELECT TARIH FROM FATBASLIK F WHERE F.PROJEID = P.ID AND
   F.TUR  in (10,11,12,14,15,16)  ORDER BY TARIH DESC  LIMIT 1 ),''DD/MM/YYYY'') AS SONSATBELGETARIHI ,
     (SELECT FATURA_TUTARI FROM FATBASLIK F WHERE F.PROJEID = P.ID AND 
   F.TUR  in (10,11,12,14,15,16)  ORDER BY TARIH DESC  LIMIT 1 ) AS SONSATTUTARI ,
    P.DEGISTIRMETARIHI,
       (SELECT FIRMA FROM REHBER R WHERE R.ID=P.DEGISTIREN) AS DEGISTIREN ,
       P.EKLEMETARIHI,
       (select FIRMA from REHBER R5 inner join PROJEASAMA PA on R5.ID=PA.REHBERID
   where PA.PROJEID=P.ID and PA.ASAMA=P.ASAMA LIMIT 1 ) AS ASAMASORUMLU ,
       year(P.BASLAMATARIHI) AS BASLAMAYIL ,
       month(P.BASLAMATARIHI) AS BASLAMAAY ,
       (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2116 AND G.DEGER=P.SEBEBI LIMIT 1 ) AS SEBEBI ,
       (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2111 AND G.DEGER=P.APLIKASYON LIMIT 1 ) AS APLIKASYON ,
       (select DURUM from TEKLIF T where T.PROJEID = P.ID order by TARIH desc LIMIT 1 ) AS SONTEKLIFDURUMU ,
    (select KUR from TEKLIF T where T.PROJEID = P.ID order by TARIH desc LIMIT 1 ) AS SONTEKLIFKUR ,
       (select TEKLIF_MATRAHI from TEKLIF T where T.PROJEID = P.ID order by TARIH desc LIMIT 1 ) AS SONTEKLIFTUTARI ,
       RAKIP,
       (select FIRMA from REHBER RR where P.CARIID=RR.ID) AS ALANRAKIP ,
       KAYIPFIYATI,
       KAYIPKUR,
       (select sum(F.TUTAR)from FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID where F.PROJEID=P.ID AND FB.TUR IN (11,12)) AS PROJEMALIYETSATIR ,
       (select sum(F.TUTAR)from FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID where FB.PROJEID=P.ID AND FB.TUR IN (11,12))
 AS PROJEMALIYETBUTUN FROM PROJELER P
       INNER JOIN REHBER R1 on R1.ID=P.REHBERID
       LEFT OUTER JOIN REHBER RP on RP.ID=P.ILGILI
    LEFT OUTER JOIN GENINI ProjeTipi ON ProjeTipi.DEGER = P.TIPI AND ProjeTipi.BOLUM=cast(''''-2112||cast(P.TURU as varchar) as integer)
WHERE
--AND P.DURUM <> 2 
 P.SUBEID in(0,-6,-5,-4,-3,-2,-1) 
 ORDER BY SATISKUR' WHERE id = 1194;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT D.DEMIRBASNO,D.DEMIRBASADI,D.SUBEID, 
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2801 AND G.DEGER=D.DURUM) AS DURUM ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=D.TEKNIKSORUMLU) AS TENIKSORUMLU ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=D.TEKNIKBILGI) AS TEKNIKBILGI ,
 R.FIRMA AS ZIMMETLIADI ,
L.ACIKLAMA AS LOKASYONADI ,
 DU.STOKADI AS KATEGORIADI ,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2804 AND G.DEGER=D.MARKA) AS MARKA ,
G.ANAHTAR AS MODELAD
FROM DEMIRBAS D 
 LEFT OUTER JOIN DEMIRBAS_URUN AS DU ON DU.ID=D.KATEGORIID  
 LEFT OUTER JOIN GENINI G ON G.DEGER = D.MODEL AND G.BOLUM=cast(''-2804''||cast(D.MARKA as varchar) as integer)  
 LEFT OUTER JOIN REHBER AS R ON R.ID = D.REHBERID
LEFT OUTER JOIN LOKASYON AS L  ON L.ID = (select LOKASYONID from DEMIRBAS_TUTANAK DT inner join DEMIRBAS_TUTANAK_DETAY DTD on DT.ID=DTD.TUTANAKID and DTD.DEMIRBASID=D.ID  ORDER  BY ID DESC LIMIT 1 )
order by D.EKLEMETARIHI desc' WHERE id = 1195;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                                        
       G.ID AS GOREVID,
       CASE ACKAPA WHEN 1 THEN ''KAPALI'' WHEN 0 THEN ''AÇIK'' END AS DURUM ,
       G.BASLAMATARIHI,GY.YORUM,RB.FIRMA AS EKLEYEN,R.FIRMA AS CARİ,RP.FIRMA AS İLGİLİ,
                   (SELECT G1.ANAHTAR FROM GENINI G1 WHERE G1.BOLUM=-21045 AND G1.DEGER=G.TURU) AS TURU ,
       REH.FIRMA AS YORUMYAPAN,GY.EKLEMETARIHI, G.KONUSU,GY.TUR,
                   
       CASE GY.TUR WHEN 1 THEN ''NOTLAR'' WHEN 2 THEN ''YORUM'' END AS TÜRÜ
FROM GOREVLER G  
                            LEFT OUTER JOIN GOREVYORUM GY ON G.ID=GY.GOREVID 
                            LEFT OUTER JOIN REHBER R ON R.ID=G.REHBERID
                            LEFT OUTER JOIN REHBER RB  ON G.EKLEYEN=RB.ID
                            LEFT OUTER JOIN REHBER RP ON RP.ID=G.MUS_ILGILI
                            LEFT OUTER JOIN GENINI GEN ON GEN.DEGER=G.TURU and GEN.BOLUM=-21045 
                            LEFT OUTER JOIN REHBER REH ON GY.EKLEYEN=REH.ID
WHERE   G.YER=18
ORDER BY GY.GOREVID, GY.EKLEMETARIHI' WHERE id = 1196;
UPDATE public.dokumler SET sql = '/*PGX*/select G.ANAHTAR,FB.FATURATARIH,FB.FATURANO,S.KOD,S.STOKADI,SOM.KALAN
from 
            STOK_ORT_MALIYET SOM inner join
            FATBASLIK FB on SOM.FATBASID=FB.ID inner join 
            FATURA F on SOM.FATURAID=F.ID inner join 
            STOKLAR S on SOM.STOKID=S.ID inner join 
            GENINI G on G.BOLUM=-1005 and G.DIL=-1 and G.DEGER=FB.TUR
where SOM.KALAN<0.0' WHERE id = 1199;
UPDATE public.dokumler SET sql = '/*PGX*/select DISTINCT S.ID,s.SERVISNO,R.FIRMA,
S.BASLAMATARIHI,S.BITISTARIHI,
 CASE S.KAPSAM WHEN 0 THEN ''H'' 
            WHEN 1 THEN ''E'' END  AS GARANTI ,
ÜRÜN_ADI=(SELECT AD FROM EKIPMANLAR  E1 WHERE E1.ID=S.EKIPMANID),
S.SERINO,
S.KONUSU,
(SELECT AD FROM KATEGORI KA1 WHERE KA1.ID=E.KATEGORI) AS KATEGORI ,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=E.MARKA) AS MARKA ,
(SELECT G.KOD FROM EKIPMANLAR G WHERE S.EKIPMANID=G.URUNID) AS MODEL ,
SB.ACIKLAMA,SB.COZUM,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-3006 AND G.DEGER=S.TURU) AS TUR ,
 cast(SB.SERVISTUR as varchar(5))||''.''||(select KOD from SERVISLISTE SL where SL.ID=SB.SERVISLISTEID) AS KOD ,
(select ANAHTAR from GENINI G WHERE BOLUM=-3015 and DEGER=SB.SERVISTUR LIMIT 1 ) AS GRUP ,
(select AD from SERVISLISTE SL where SL.ID=SB.SERVISLISTEID) AS AD , 
SB.ACIKLAMA, SB.COZUM 

from SERVIS S inner join SERVISBILGI SB on S.ID=SB.SERVISID
                                                 INNER JOIN REHBER R ON S.REHBERID=R.ID
                          LEFT OUTER JOIN EKIPMANLAR E ON S.EKIPMANID=E.ID
                                                 LEFT OUTER JOIN KATEGORI KA ON E.KATEGORI=KA.ID
                                                 LEFT OUTER JOIN FATBASLIK FB ON FB.SERVISID=S.ID
                                                 LEFT OUTER JOIN FATURA F ON FB.ID=F.FATBASID
                                                 LEFT OUTER JOIN STOKLAR ST ON ST.ID=F.URUNID

where
S.TARIH>=''$Baslangic$ 00:00:00'' AND
S.TARIH<=''$Bitis$ 23:59:00''
AND R.FIRMA LIKE ''%$Firma$%''' WHERE id = 1200;
UPDATE public.dokumler SET sql = '/*PGX*/


select 
KOD,
AD,
CASE WHEN TARIH<''$Baslangic$ 00:00'' THEN ''Devir'' else TURAD end AS TURAD ,
CASE WHEN TARIH<''$Baslangic$ 00:00'' THEN ''$Baslangic$ 00:00'' else TARIH end AS TARIH ,
SUM(BORC) AS BORC ,SUM(ALACAK) AS ALACAK ,KUR,
CASE WHEN TARIH<''$Baslangic$ 00:00'' THEN ''$Baslangic$ 00:00'' else VADETARIHI end 

 AS VADETARIHI from (
SELECT KOD,AD,TURAD,TARIH,BORC,ALACAK,KUR,VADETARIHI 
FROM (

	Select K.ID AS CEKID , ISLEMTARIHI AS TARIH,PLANTARIHI as AKSIYONTARIH,BELGENO as NO, K.TUR,'''' as BASLIK,
	case when K.TUR like ''26__'' then (select ANAHTAR || '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
	when K.TUR like ''36__'' then (select ANAHTAR || '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
	else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end AS TURAD , K.REHBERID,
	 case when K.REHBERID=0 then M.KOD else R.KOD end AS KOD ,
	 case when K.REHBERID=0 then M.AD else R.FIRMA end AS AD , K.ACIKLAMA, HESAPID,
	case HESAPTURU when ''B'' then (select HESAPKODU from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
	when ''H'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''|| (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)||'')'','''')
	when ''K'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)
	when ''P'' then (select KODU from POS P where P.ID=K.HESAPID)
	when ''V'' then (select KODU from KREDIKARTI KK where KK.ID=K.HESAPID) end AS HESAPKODU ,
	case HESAPTURU when ''B'' then (select HESAPADI from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
	when ''H'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''|| (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)||'')'','''')
	when ''K'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)
	when ''P'' then (select ADI from POS P where P.ID=K.HESAPID)
	when ''V'' then (select ADI from KREDIKARTI KK where KK.ID=K.HESAPID) end AS HESAPADI ,
	K.DURUM,
	 case when EKSTREDEKULLAN=1 AND BORC>0 then K.DOVIZ_TUTARI else K.BORC end AS BORC ,
	 case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end AS ALACAK ,
	 case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end AS KUR ,
	

	case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0 then K.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0 THEN -1*K.DOVIZ_TUTARI else K.BORC-K.ALACAK end
	/ 
	CASE WHEN ((case when EKSTREDEKULLAN=1 AND BORC>0 then K.DOVIZ_TUTARI else K.BORC end)-(case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end))=0 THEN 1
	ELSE ((case when EKSTREDEKULLAN=1 AND BORC>0 then K.DOVIZ_TUTARI else K.BORC end)-(case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end)) END

	 AS YERELKUR ,

	K.MASRAFID, M.KOD AS MASRAFKOD , M.AD AS MASRAFAD ,0 AS BORCBAKIYE ,0  AS ALACAKBAKIYE ,

	 case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0 then K.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0 THEN -1*K.DOVIZ_TUTARI else K.BORC-K.ALACAK end AS YERELTUTAR ,
	 0 AS YERELBAKIYE ,
	K.SUBEID,ISLEMTARIHI AS VADETARIHI ,
	1.0 AS ADET ,'''' AS BIRIM ,0.0
	 AS BIRIMFIYAT From KASA K 
	left outer join REHBER R on K.REHBERID=R.ID left outer join KASALAR KS on KS.ID= K.HESAPID left outer join MASRAFGELIR M on M.ID=K.MASRAFID
	Where 
	--K.REHBERID=@RehberID
	year(K.ISLEMTARIHI) >= year(''$Baslangic$ 00:00'') and year(K.ISLEMTARIHI) <= year(''$Bitis$ 23:59'') AND K.ISLEMTARIHI<=''$Bitis$ 23:59'' and
	((K.TUR in (49))or(K.TUR not between 40 and 79))

	UNION ALL

	Select F.ID AS CEKID , FATURATARIH as TARIH, FATURATARIH AS AKSIYONTARIH, FATURANO as NO, F.TUR,F.BASLIK,
	(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ) AS TURAD ,
	F.REHBERID, R.KOD, R.FIRMA AS AD, F.ACIKLAMA, null AS HESAPID , null AS HESAPKODU , null AS HESAPADI ,F.DURUM,
	case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end  AS BORC ,
	case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end AS ALACAK ,
	 case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end AS KUR ,

	 (case when F.DOVIZ_CINSI=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.DOVIZ_TUTARI when F.DOVIZ_CINSI =(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.DOVIZ_TUTARI
	when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.FATURA_TUTARI when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.FATURA_TUTARI
	end)/
	CASE WHEN ((case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end)-
	(case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end))=0 THEN 1 ELSE
	((case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end)-
	(case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end))
	END AS YERELKUR ,

	F.MASRAFID, M.KOD AS MASRAFKOD , M.AD AS MASRAFAD ,0 AS BORCBAKIYE ,0  AS ALACAKBAKIYE ,
	 case when F.DOVIZ_CINSI=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.DOVIZ_TUTARI when F.DOVIZ_CINSI =(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.DOVIZ_TUTARI
	when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.FATURA_TUTARI when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.FATURA_TUTARI
	end AS YERELTUTAR ,
	 0 AS YERELBAKIYE ,
	F.SUBEID, F.FATURATARIH+coalesce(F.VADE,0) AS VADETARIHI ,
	1.0 AS ADET ,'''' AS BIRIM ,0.0
	 AS BIRIMFIYAT From FATBASLIK F 
	inner join REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6
	left outer join MASRAFGELIR M on M.ID=F.MASRAFID
	--Where F.REHBERID=@RehberID
	where year(FATURATARIH) >= year(''$Baslangic$ 00:00'') and year(FATURATARIH)<=year(''$Bitis$ 23:59'') and FATURATARIH<=''$Bitis$ 23:59''

	---- Çek
	UNION ALL
	Select C.ID  AS CEKID ,CH.TARIH, VADE as AKSIYONTARIH, MAKBUZNO as NO, case when CH.ISLEM in(130,141) then 23 else 33 end AS TUR ,'''',
	(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ) AS TURAD ,
	CH.REHBERID,R.KOD, R.FIRMA AS AD, ''Serino:''||cast(C.SERINO as varchar)||'' ''||rtrim(CH.ACIKLAMA) AS ACIKLAMA ,
	CH.BANKAHESAPLARID AS HESAPID , BH.HESAPKODU AS HESAPKODU , BH.HESAPADI AS HESAPADI ,C.DURUM,
	Case
	when CH.ISLEM in(140,131,132,133,134,137) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end)
	else 0 end AS BORC ,
	Case
	when CH.ISLEM in(130,141) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end)
	else 0 end AS ALACAK ,
	case when C.EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end AS KUR ,
	 (case when c.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI
	when c.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(130,141) then -1*C.DOVIZ_TUTARI
	end)/
	((Case when CH.ISLEM in(140,131,132,133,134,137) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end)-
	(Case when CH.ISLEM in(130,141) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end)) AS YERELKUR ,
	C.MASRAFID, M.KOD AS MASRAFKOD , M.AD AS MASRAFAD ,0 AS BORCBAKIYE ,0  AS ALACAKBAKIYE ,
	 case when c.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI
	when c.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(130,141) then -1*C.DOVIZ_TUTARI
	when c.DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(140,131,132,133,134,137) then C.TUTAR
	when c.DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(130,141) then -1*C.TUTAR
	end AS YERELTUTAR ,

	 0 AS YERELBAKIYE ,
	C.SUBEID, VADE AS VADETARIHI ,
	1.0 AS ADET ,'''' AS BIRIM ,0.0
	 AS BIRIMFIYAT From CEKLER C  inner join
	CEKHAREKET CH on C.ID=CH.CEKSENETLERID
	left outer join REHBER R on CH.REHBERID=R.ID
	left outer join BANKAHESAPLAR BH on CH.BANKAHESAPLARID=BH.ID
	left outer join MASRAFGELIR M on M.ID=C.MASRAFID
	Where CH.ISLEM in(130,131,132,134,137,140,141)
	--and CH.REHBERID=@RehberID
	and year(CH.TARIH) >= year(''$Baslangic$ 00:00'') and year(CH.TARIH) <= year(''$Bitis$ 23:59'') AND CH.TARIH <= ''$Bitis$ 23:59''

	--alter table CEKLER ADD EKSTREDEKULLAN BIT
	---- Senet
	UNION ALL
	Select C.ID  AS CEKID ,TARIH, VADE as AKSIYONTARIH, MAKBUZNO as NO,C.TUR,'''', (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ) AS TURAD ,
	C.REHBERID,R.KOD, R.FIRMA AS AD, rtrim(NOTLAR) AS ACIKLAMA , null AS HESAPID , null AS HESAPKODU , null AS HESAPADI ,C.DURUM,
	Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS BORC ,
	Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS ALACAK ,
	case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end AS KUR ,
	(case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.DOVIZ_TUTARI
	when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.DOVIZ_TUTARI
	when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.TUTAR when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.TUTAR
	end)/
	((Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end)-
	(Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end)) AS YERELKUR ,
	C.MASRAFID, M.KOD AS MASRAFKOD , M.AD AS MASRAFAD ,0 AS BORCBAKIYE ,0  AS ALACAKBAKIYE ,
	 case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.DOVIZ_TUTARI
	when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.TUTAR when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.TUTAR
	end AS YERELTUTAR ,
	 0 AS YERELBAKIYE ,
	C.SUBEID, VADE AS VADETARIHI ,
	1.0 AS ADET ,'''' AS BIRIM ,0.0
	 AS BIRIMFIYAT From SENETLER C 
	inner join REHBER R on C.REHBERID=R.ID left outer join MASRAFGELIR M on M.ID=C.MASRAFID
	--Where
	--C.REHBERID=@RehberID
	where year(C.TARIH) >= year(''$Baslangic$ 00:00'') and year(C.TARIH) <= year(''$Bitis$ 23:59'') and C.TARIH <= ''$Bitis$ 23:59''

) AS X
WHERE
 KOD LIKE ''$CariKod$%''
 AND AD LIKE ''$CariAd$%''
)AS Y
group by 
	KOD, AD, KUR,
	CASE WHEN TARIH<''$Baslangic$ 00:00'' THEN ''Devir'' else TURAD end,
	CASE WHEN TARIH<''$Baslangic$ 00:00'' THEN ''$Baslangic$ 00:00'' else TARIH end,
	CASE WHEN TARIH<''$Baslangic$ 00:00'' THEN ''$Baslangic$ 00:00'' else VADETARIHI end 
ORDER BY kur, KOD,TARIH
' WHERE id = 1266;
UPDATE public.dokumler SET sql = '/*PGX*/

select KR.ID,B.BANKAADI,KREDIKODU,ADI,count(P.ID) AS KREDITAKSIT , 
coalesce(sum(P.TAKSIT),0) AS TOPLAM_TUTAR ,

sum(case when P.TARIH<''$bitis$'' then 0.0 else P.TAKSIT end) AS ODENEN_TUTAR ,

sum(case when P.TARIH>=''$bitis$'' then 0.0 else P.TAKSIT end)

 AS KALAN_TUTAR from KREDILER KR
left join PLANKREDI P on P.KREDIID=KR.ID
inner join BANKAHESAPLAR BH ON  BH.ID = KR.BANKATICARIHESAPID
inner join BANKASUBELER BS ON BH.BANKASUBELERID=BS.ID
inner join BANKALAR B on B.BANKAKODU=BS.BANKAKODU
where GENELKREDITIPI=1
GROUP BY KR.ID,KREDIKODU,ADI,SOZLESMENO,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KAPANISTARIHI,KREDITAKSIT,
TAKSITTUTARI,KR.DURUM,KR.SUBEID,B.BANKAADI,BS.SUBEADI,BANKATICARIHESAPID
-----
union all
-----
select KR.ID,B.BANKAADI,KREDIKODU,ADI,case when GENELKREDITIPI=2 then count(BORC) else KR.KREDITAKSIT end AS KREDITAKSIT ,

coalesce(sum(BORC),0) AS TOPLAM_TUTAR ,
coalesce(sum(case when KS.ISLEMTARIHI <''$bitis$'' then 0.0 else ALACAK end),0.0) AS ODENEN_TUTAR ,
coalesce(sum(BORC),0)-coalesce(sum(case when KS.ISLEMTARIHI <''$bitis$'' then 0.0 else ALACAK end),0.0)
 AS KALAN_TUTAR from KREDILER KR
left outer join KASA KS on HESAPTURU=''R'' and KS.HESAPID=KR.ID
inner join BANKAHESAPLAR BH ON  BH.ID = KR.BANKATICARIHESAPID
inner join BANKASUBELER BS ON BH.BANKASUBELERID=BS.ID
inner join BANKALAR B on B.BANKAKODU=BS.BANKAKODU
where GENELKREDITIPI=2
GROUP BY KR.ID,KREDIKODU,ADI,SOZLESMENO,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KAPANISTARIHI,KREDITAKSIT,
TAKSITTUTARI,KR.DURUM,KR.SUBEID,B.BANKAADI,BS.SUBEADI,BANKATICARIHESAPID
' WHERE id = 1267;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                     
       G.ID AS GOREVID,
       CASE ACKAPA WHEN 1 THEN ''KAPALI'' WHEN 0 THEN ''AÇIK'' END AS DURUM ,
       G.BASLAMATARIHI,GEN.ANAHTAR AS TÜR,GY.YORUM,RB.FIRMA AS EKLEYEN,R.FIRMA AS CARİ,RP.FIRMA AS İLGİLİ,
       REH.FIRMA AS YORUMYAPAN,GY.EKLEMETARIHI, G.KONUSU,GY.TUR,
       CASE GY.TUR WHEN 1 THEN ''NOTLAR'' WHEN 2 THEN ''YORUM'' END AS TÜRÜ
FROM GOREVLER G  
                            LEFT OUTER JOIN GOREVYORUM GY ON G.ID=GY.GOREVID
                            LEFT OUTER JOIN REHBER R ON R.ID=G.REHBERID
                            LEFT OUTER JOIN REHBER RB  ON G.EKLEYEN=RB.ID
                            LEFT OUTER JOIN REHBER RP ON RP.ID=G.MUS_ILGILI
                            LEFT OUTER JOIN GENINI GEN ON GEN.DEGER=G.TURU and GEN.BOLUM=-21044
                            LEFT OUTER JOIN REHBER REH ON GY.EKLEYEN=REH.ID
WHERE   G.BASLAMATARIHI BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND   cast(G.EKLEYEN as varchar) LIKE ''$Ekleyen$%''
AND cast(coalesce(GEN.DEGER,'''') as varchar) LIKE ''%$Tur$%''
AND   R.FIRMA LIKE ''%$Firma$%''
ORDER BY GY.GOREVID, GY.EKLEMETARIHI' WHERE id = 1268;
UPDATE public.dokumler SET sql = '/*PGX*/select 
                               Y.GRUP,R.FIRMA,R.FIRMA AS UNVAN ,
                               (SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERILETISIM RI ON RB.YER_ID=RI.ID WHERE RI.REHBERID=R.ID AND ETIKET=''Ülke'' LIMIT 1 ) AS ULKE ,
                                case wheN R.STATU=0 then Y.VERGINO ELSE '''' END AS TCNO ,
                                case wheN R.STATU=1 then Y.VERGINO ELSE '''' END AS VGNO ,
                               Y.TOPTUTAR AS TUTAR ,
                               Y.ADET,
                               YIL,CASE WHEN AY=1 THEN ''Ocak''  WHEN AY=2  THEN ''Şubat''    WHEN AY=3  THEN ''Mart''   WHEN AY=4  THEN ''Nisan''
                                                                              WHEN AY=5 THEN ''Mayıs'' WHEN AY=6  THEN ''Haziran''  WHEN AY=7  THEN ''Temmuz'' WHEN AY=8  THEN ''Ağustos''
                                                                              WHEN AY=9 THEN ''Eylül'' WHEN AY=10 THEN ''Ekim''     WHEN AY=11 THEN ''Kasım''  WHEN AY=12 THEN ''Aralık'' end   AS AY ,
              
                               CASE WHEN SONRAKIAY=1 THEN ''Ocak''  WHEN SONRAKIAY=2  THEN ''Şubat''    WHEN SONRAKIAY=3  THEN ''Mart''    WHEN SONRAKIAY=4  THEN ''Nisan''
                                                                                 WHEN SONRAKIAY=5 THEN ''Mayıs'' WHEN SONRAKIAY=6  THEN ''Haziran''  WHEN SONRAKIAY=7  THEN ''Temmuz''  WHEN SONRAKIAY=8  THEN ''Ağustos''
                                                                                 WHEN SONRAKIAY=9 THEN ''Eylül'' WHEN SONRAKIAY=10 THEN ''Ekim''     WHEN SONRAKIAY=11 THEN ''Kasım''   WHEN SONRAKIAY=12 THEN ''Aralık'' end AS SONRAKIAY ,

                                (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İş Tel'' AND YERI=1 AND R.ID=-1 LIMIT 1 ) AS ISTEL ,
                                (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Faks'' AND YERI=1 AND R.ID=-1 LIMIT 1 ) AS FAX ,
                                (SELECT RB.BILGI FROM REHBERILETISIM RI INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE RB.ETIKET=''Faks'' AND YERI=1 AND R.ID=RI.REHBERID LIMIT 1 ) AS FAX_FIRMA ,
                                (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Eposta'' AND YERI=1 AND R.ID=-1 LIMIT 1 ) AS EPOSTA ,
                                (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Adres'' AND YERI=1 AND R.ID=-1 LIMIT 1 ) AS ADRES ,
                                (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''PK'' AND YERI=1 AND R.ID=-1 LIMIT 1 )
                               ||'' '' ||(SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İlçe'' AND YERI=1 AND R.ID=-1 LIMIT 1 )
                               ||'' '' ||(SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İl'' AND YERI=1 AND R.ID=-1 LIMIT 1 )

 AS ADRES1 from (
                select 
                               X.VERGINO,
                               X.GRUP,X.YIL,X.AY,
                               (select R.ID from REHBER R where X.VERGINO=(SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ) order by R.MUHKODU desc LIMIT 1 ) AS REHBERID ,
                               SUM(TUTAR) AS TOPTUTAR ,
                               count(*) AS ADET ,
                               CASE WHEN AY=12 THEN 1 ELSE AY+1 END
                 AS SONRAKIAY from 
                               (              select 
                                                               (SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ) AS VERGINO ,
                                                                CASE WHEN coalesce(KDVDURUM,'''')=''Dahil'' THEN FATURA_MATRAHI-KDV_TUTARI ELSE FATURA_MATRAHI END AS TUTAR ,
                                                                CASE WHEN FB.TUR=11 THEN ''BA''
                                                                                                              WHEN FB.TUR=12 THEN ''BA''
                                                                                                              WHEN FB.TUR=15 THEN ''BS''
                                                                                                              WHEN FB.TUR=16 THEN ''BS'' END  AS GRUP ,
                                                               YEAR(FATURATARIH)  AS YIL ,
                                                               MONTH(FATURATARIH)      
                                                AS AY from  REHBER R INNER JOIN FATBASLIK FB ON R.ID=FB.REHBERID
                                               where FATURATARIH BETWEEN ''$Baslama$ 00:00:00'' AND ''$Bitis$ 23:59:00'' 
                                                       AND FB.TUR IN (11,12,15,16)
                                                                              AND FB.DURUM NOT IN (6)
                                                                              AND coalesce(FB.FATURASERI,'''') NOT LIKE ''X%''
                               ) as X
                where VERGINO=''$Vergino$''
                AND GRUP LIKE ''$Grup$%''
                group by X.VERGINO,X.GRUP,X.YIL,X.AY
)as Y inner join REHBER R on Y.REHBERID=R.ID' WHERE id = 1269;
UPDATE public.dokumler SET sql = '/*PGX*/select 
T.TARIH,T.TEKLIFNO,
(SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2905 AND T.BILGI=G.DEGER) AS BILGI ,
T.KONUSU,
(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-2901 AND T.TURU=DEGER) AS TURU ,
(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-2902 AND T.DURUM=DEGER) AS DURUM ,
R1.KOD  AS CARIKOD ,RP.FIRMA  as MUS_ILGILIAD, R1.FIRMA,
case when TD.TUR=0 then (select KOD from MASRAFGELIR MG where MG.ID=TD.URUNID)
                  else (select KOD from STOKLAR S where S.ID=TD.URUNID) end AS URUN_KOD ,
case when TD.TUR=0 then (select AD from MASRAFGELIR MG where MG.ID=TD.URUNID)
                  else (select STOKADI from STOKLAR S where S.ID=TD.URUNID) end AS URUN_AD ,
(SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2702 AND G.DEGER=TD.BIRIM) AS BIRIM ,TD.MIKTAR,TD.BIRIMFIYAT,TD.ISKONTO,TD.KDV,TD.TUTAR,TD.KUR,R2.FIRMA as HAZIRLAYANAD,
(select ANAHTAR from GENINI where BOLUM=-2210 and DIL=-1 and DEGER=R1.BOLGE) AS BOLGE ,
(select ANAHTAR from GENINI where BOLUM=''-2210''||cast(R1.BOLGE as varchar) and DEGER=R1.ALTBOLGE and DIL = -1) AS ALTBOLGE ,
coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID  AND RA.VARSAYILAN=6 LIMIT 1 ),'''') AS ILCE ,
coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID    AND RA.VARSAYILAN=8 LIMIT 1 ),'''') AS IL ,
T.TEKLIF_MATRAHI,T.KDV_TUTARI,T.ISKONTO_TUTARI,T.ISKONTO_YUZDE,T.DOVIZ_TUTARI,T.KUR,T.DOVIZ_KURU,
P.PROJEKODU,P.PROJEADI,T.GECERLILIK_SURESI,
 case when 412 in (select YERI from SIPARISDETAY where YERID in (select ID from TEKLIFDETAY where TEKLIFID=T.ID)) then ''Var'' else '''' end  AS VERILENSIPARIS ,
 case when 413 in (select YERI from SIPARISDETAY where YERID in (select ID from TEKLIFDETAY where TEKLIFID=T.ID)) then ''Var'' else '''' end  AS ALINANSIPARIS ,
DATEDIFF(day,T.TARIH,now()) AS TEKLIFGUNSAYISI ,
DATEDIFF(day,DURUMTARIHI,now()) AS DURUMGUNSAYISI ,
--T.TEditODEME_SEKLI,(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-1007 AND T.FIYAT_LISTESI=DEGER) AS FIYAT ,
T.VADE,
(Select Min(TESLIMTARIHI) from TEKLIFDETAY Where TEKLIFID=T.ID ) AS TESLIMTARIHI ,
(Select Min(TESLIMTARIHI) from TEKLIFDETAY Where TEKLIFID=T.ID ) AS TESLIMTARIHI ,
T.ACIKLAMA,P.DURUM AS PRJ_DURUM ,P.SONUC AS PRJ_SONUC ,P.SEBEBI AS PRJ_SEBEBI ,
R3.FIRMA AS ONAYLAYACAK2 ,
case when coalesce(T.GECERLILIK_SURESI,0)=0 then 0 else DATEDIFF(day,now(),T.TARIH+GECERLILIK_SURESI) end AS GECERLILIK_KALAN ,
R4.FIRMA AS ONAYLAYAN ,
RP2.FIRMA AS DISONAYCI ,
(select ANAHTAR from GENINI where BOLUM=-2911 and DEGER=T.SONUC and DIL=-1) AS SONUCAD ,
 (select ANAHTAR from GENINI where BOLUM=-2912 and DEGER=T.SEBEBI and DIL=-1) AS SEBEBIAD ,
T.GECERLILIK_SURESI
      from TEKLIF T
                             left outer join REHBER R1 on R1.ID=T.REHBERID
                             left outer join REHBER R2 on R2.ID=T.HAZIRLAYAN
                             left outer join REHBER RP on RP.ID=T.MUS_ILGILI
                             left outer join PROJELER P on P.ID=T.PROJEID
                             left outer join REHBER R3 on T.ONAYLAYACAK=R3.ID
                             left outer join REHBER R4 on T.ONAYLAYAN=R4.ID
                             left outer join REHBER RP2 on T.DISONAY=RP2.ID
                             LEFT OUTER join REHBERILETISIM RI on RI.REHBERID=R1.ID and RI.VARSAYILAN=1
                             INNER JOIN TEKLIFDETAY TD ON TD.TEKLIFID=T.ID 
                             LEFT OUTER JOIN STOKLAR S ON S.ID=TD.URUNID
where 1=1  and T.TARIH BETWEEN ''$Baslama$ 00:00'' AND ''$Bitis$ 23:59''       
  Order by T.TARIH' WHERE id = 1270;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT D.DEMIRBASNO,D.DEMIRBASADI,D.SERINO,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2801 AND G.DEGER=DT.TIP) AS DURUM ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=D.TEKNIKSORUMLU) AS TENIKSORUMLU ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=D.TEKNIKBILGI) AS TEKNIKBILGI ,  
(SELECT FIRMA FROM REHBER R WHERE R.ID=DT.VERENID) AS VERENPERSONEL ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=DT.ALANID) AS ALANPERSONEL ,        
L.ACIKLAMA AS LOKASYONADI ,
 DU.STOKADI AS KATEGORIADI ,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2804 AND G.DEGER=D.MARKA) AS MARKA ,
G.ANAHTAR AS MODELAD,
dt.TIP
FROM 
	DEMIRBAS_TUTANAK AS DT inner join 
	DEMIRBAS_TUTANAK_DETAY DTD on DT.ID=DTD.TUTANAKID AND DT.TIP=21  inner join
	DEMIRBAS D on D.ID=DTD.DEMIRBASID AND D.REHBERID=DT.ALANID
	LEFT OUTER JOIN DEMIRBAS_URUN AS DU ON DU.ID=D.KATEGORIID  
	LEFT OUTER JOIN GENINI G ON G.DEGER = D.MODEL AND G.BOLUM=cast(''-2804''||cast(D.MARKA as varchar) as integer) 
	LEFT OUTER JOIN LOKASYON AS L  ON L.ID = dt.LOKASYONID 
        LEFT OUTER JOIN REHBER AS R ON R.ID = D.REHBERID
where DT.ID in (select XX.ID from (select DT2.ID,  row_number() over (partition by DTD2.DEMIRBASID order by DT2.ID desc)
				 AS SIRA from DEMIRBAS_TUTANAK DT2 inner join DEMIRBAS_TUTANAK_DETAY DTD2 on DT2.ID=DTD2.TUTANAKID AND DT2.TIP=21 )as XX
				where XX.SIRA=1)
AND D.DEMIRBASADI LIKE ''%$Demirbas$%''
AND cast(coalesce(D.DURUM,'''') as varchar) LIKE ''%$Durum$%''
AND coalesce(L.ACIKLAMA,'''') LIKE ''%$Lokasyon$%''
AND   R.FIRMA LIKE ''%$Firma$%''
order by 1' WHERE id = 1271;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
REVERSE(SUBSTRING(REVERSE(MASRAFKOD),CHARINDEX(''.'',REVERSE(MASRAFKOD),1)+1,length(MASRAFKOD)-(CHARINDEX(''.'',REVERSE(MASRAFKOD),1)-1))) AS USTMASRAFKOD ,
(select AD from MASRAFGELIR where KOD=REVERSE(SUBSTRING(REVERSE(MASRAFKOD),CHARINDEX(''.'',REVERSE(MASRAFKOD),1)+1,length(MASRAFKOD)-(CHARINDEX(''.'',REVERSE(MASRAFKOD),1)-1))) LIMIT 1 ) AS USTMASRAFAD ,
MASRAFKOD,MASRAFAD,
ROUND(coalesce(SUM(BORC),0),2) AS BORC,
ROUND(coalesce(SUM(ALACAK),0),2) AS ALACAK,
ROUND(coalesce(SUM(BORC),0),2)-ROUND(coalesce(SUM(ALACAK),0),2) AS BAKIYE ,
KUR
FROM (
SELECT * FROM (
SELECT
FB.SUBEID,
F.ID,                         
FB.TUR,
IT.AD,
FB.FATURANO AS BELGENO,                  
FB.FATURATARIH AS ISLEMTARIHI,
MG.KOD AS MASRAFKOD,
MG.AD AS MASRAFAD,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
 CASE WHEN F.TUR = 1 THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS KODU ,
 CASE WHEN F.TUR = 1 THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS ADI ,
CASE WHEN FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR IN (''€'',''$'') THEN F.DOVIZ_TUTARI /(1+(F.KDV/100.0))
          WHEN FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR IN (''€'',''$'') THEN F.DOVIZ_TUTARI /(1+(F.KDV/100.0)) + coalesce((-1*FB.EKVERGI),0)
          WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) 
          WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)
          WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) + coalesce((-1*FB.EKVERGI),0)
          WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)  + coalesce((-1*FB.EKVERGI),0)
        END AS BORC ,
CASE WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (15,16) and FB.KUR IN (''€'',''$'') THEN (F.DOVIZ_TUTARI)/(1+(F.KDV/100.0)) 
            WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (15,16) and FB.KUR IN (''€'',''$'') THEN (cast(F.DOVIZ_TUTARI as double precision))

            WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (15,16) and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) 
            WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (15,16) and FB.KUR NOT IN (''€'',''$'') THEN (cast(F.TUTAR as double precision))
END AS ALACAK ,
F.KUR
FROM FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
                                                 LEFT JOIN MASRAFGELIR MG ON F.TUR=0 AND F.URUNID=MG.ID
                                                 LEFT OUTER JOIN REHBER R ON F.REHBERID=R.ID
                                                 LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
WHERE 
     FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
     AND FB.TUR IN (11,12,15,16,1)
) AS X
WHERE coalesce(MASRAFKOD,'''')<>''''
UNION ALL
SELECT * FROM (
SELECT
FB.SUBEID,
F.ID,
FB.TUR,
IT.AD,
FB.FATURANO AS BELGENO,                  
FB.FATURATARIH AS ISLEMTARIHI,
(SELECT KOD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)) AS MASRAFKOD ,
(SELECT AD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)) AS MASRAFAD ,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
 (SELECT KOD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)) AS KODU ,
 (SELECT AD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)) AS ADI ,
0 AS BORC ,
-1*EKVERGI AS ALACAK ,
''TL''
 AS KUR FROM FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
                                                 LEFT JOIN MASRAFGELIR MG ON F.TUR=0 AND F.URUNID=MG.ID
                                                 LEFT OUTER JOIN REHBER R ON F.REHBERID=R.ID
                                                 LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
WHERE 
     FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
     AND FB.TUR IN (11)
     AND FB.TIPI = 4
) AS X
WHERE coalesce(MASRAFKOD,'''')<>''''
UNION ALL
SELECT * FROM (
SELECT
FB.SUBEID,
FB.ID,
FB.TUR,  
IT.AD,  
FB.FATURANO AS BELGENO,            
FB.FATURATARIH AS ISLEMTARIHI,
MG.KOD AS MASRAFKOD,
MG.AD AS MASRAFAD,
R.KOD AS CARIKOD,
R.FIRMA AS CARIAD,
 MG.KOD AS KODU ,
 MG.AD AS ADI ,
 case when FB.TUR=13 and FB.KUR IN (''€'',''$'') then FB.DOVIZ_TUTARI
              when FB.TUR=13 and FB.KUR NOT IN (''€'',''$'') then FB.FATURA_TUTARI END  AS BORC ,
 case when FB.TUR=17 and FB.KUR IN (''€'',''$'') then FB.DOVIZ_TUTARI
              when FB.TUR=17 and FB.KUR NOT IN (''€'',''$'') then FB.FATURA_TUTARI END AS ALACAK ,
''TL''

 AS KUR FROM FATBASLIK FB 
                                                 LEFT JOIN MASRAFGELIR MG ON FB.MASRAFID=MG.ID AND coalesce(FB.DURUM,0)<>6
                                                 LEFT OUTER JOIN REHBER R ON FB.REHBERID=R.ID
                                                 LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
WHERE 
     FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
     and FB.TUR IN (13,17,1)
) AS X
WHERE coalesce(MASRAFKOD,'''')<>''''
UNION ALL
SELECT * FROM (
Select 
K.SUBEID, 
K.ID,
K.TUR,
IT.AD,
K.BELGENO,
ISLEMTARIHI, 
M.KOD AS MASRAFKOD , M.AD AS MASRAFAD ,
 R.KOD AS CARIKOD , 
 R.FIRMA AS CARIAD , 
 M.KOD AS KODU ,
 M.AD AS ADI ,
 CASE	when K.TUR=1 and K.KUR <> ''TL'' and ALACAK>0.0 then K.DOVIZ_TUTARI
				when K.TUR=1 and K.KUR = ''TL'' and ALACAK>0.0 then K.ALACAK
                WHEN K.TUR<>1 and K.KUR <> ''TL'' AND BORC>0 THEN K.DOVIZ_TUTARI 
                WHEN K.TUR<>1 and K.KUR = ''TL'' AND BORC>0 THEN K.BORC 
                END AS BORC , 
  CASE when K.TUR=1 and K.KUR <> ''TL'' and BORC>0.0 then K.DOVIZ_TUTARI
				when K.TUR=1 and K.KUR = ''TL'' and BORC>0.0 then K.BORC
                WHEN K.TUR<>1 and K.KUR <> ''TL'' AND ALACAK>0 THEN K.DOVIZ_TUTARI 
                WHEN K.TUR<>1 and K.KUR = ''TL'' AND ALACAK>0 THEN K.ALACAK 
                END AS ALACAK ,  

 ''TL''
 AS KUR From KASA K 
                               left outer join REHBER R on K.REHBERID=R.ID left outer join KASALAR KS on KS.ID= K.HESAPID  
                               left outer join MASRAFGELIR M on M.ID=K.MASRAFID
                               LEFT JOIN ISLEMTURLERI IT ON K.TUR=IT.TUR AND IT.TIP IN (0,1)
Where 
    K.REHBERID=0 and 
    K.ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''  and
    K.TUR IN (21,22,23,31,32,33,35,44,58,1) 
) AS XYZ
WHERE coalesce(MASRAFKOD,'''')<>''''       
 ) AS X 
GROUP BY MASRAFKOD,MASRAFAD,KUR
ORDER BY 1,MASRAFKOD,KUR' WHERE id = 1274;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
       XXX.KOD,XXX.FIRMA,
       round(coalesce(BORC,0),2) as BORC,
       round(coalesce(ALACAK,0),2) as ALACAK,
       round(coalesce(BAKIYE,0),2) as BAKIYE,
       KUR  
--       round(coalesce(TLBORC,0),2) as TLBORC,
 --      round(coalesce(TLALACAK,0),2) as TLALACAK,
  --     round(coalesce(TLBAKIYE,0),2) as TLBAKIYE
FROM (
select  DISTINCT R.SUBEID,R.KOD ,R.FIRMA,GSnf.ANAHTAR AS SINIFADI ,GGrp.ANAHTAR AS GRUPADI ,cast(TOPLAM_BORC as double precision) AS BORC ,cast(TOPLAM_ALACAK as double precision) AS ALACAK,KUR ,cast(TOPLAM_BORC as double precision)-cast(TOPLAM_ALACAK as double precision)-- AS BAKIYE ,TLBORC,TLALACAK,(TLBORC-TLALACAK)

 AS TLBAKIYE FROM(
    select
                              REHBERID,SUM(coalesce(BORC,0)) AS TOPLAM_BORC ,SUM(coalesce(ALACAK,0)) AS TOPLAM_ALACAK ,coalesce(KUR,''TL'')-- AS KUR ,SUM(coalesce(TLBORC,0.0)) AS TLBORC ,SUM(coalesce(TLALACAK,0.0))
                 AS TLALACAK from (
                   SELECT
                               REHBERID,
                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
                               0.0 AS ALACAK,
                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                                                                                                                 --TLBORC=SUM(cast(F.FATURA_TUTARI as double precision)),
                                                                                                                 --TLALACAK=0.0
                               FROM FATBASLIK F
                               WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17))
                               AND FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
                               GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

                UNION ALL

                               SELECT REHBERID,
                               0 AS BORC,
                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                                                                                                                 --TLBORC=0.0,
                                                                                                                 --TLALACAK=SUM(cast(F.FATURA_TUTARI as double precision))
                               FROM FATBASLIK F
                               WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13))
                               AND FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
                               GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

                UNION ALL

                               SELECT REHBERID,
                               SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
                               SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
                               CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR
              --  TLBORC=sum(case when (K.TUR=88) then K.DOVIZ_TUTARI
               --                                                when (K.KUR=''TL'' and K.BORC>0.0) then K.BORC
              --                                                 when (K.DOVIZ_KURU=''TL'' and K.BORC>0.0) then K.DOVIZ_TUTARI
              --                                                 else 0.0 end),
               -- TLALACAK=sum(case when (K.TUR=98) then K.DOVIZ_TUTARI
               --                                                when (K.KUR=''TL'' and K.ALACAK>0.0) then K.ALACAK
               --                                                when (K.DOVIZ_KURU=''TL'' and K.ALACAK>0.0) then K.DOVIZ_TUTARI
                --                                               else 0.0 end)
                               FROM KASA K
                               WHERE TUR not between 60 and 79  AND
                               ISLEMTARIHI  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
                               GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

                UNION ALL
                               SELECT CH.REHBERID,
                               SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end) AS BORC ,
                               SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end) AS ALACAK ,
                               CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR
                                                                                                              --   TLBORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI else 0.0 end),
                                                                                                               --  TLALACAK=SUM(Case when CH.ISLEM in(130,141) then C.DOVIZ_TUTARI else 0.0 end)
                               FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                               WHERE CH.ISLEM in(130,131,132,134,137,140,141) and
                               CH.TARIH  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
                               GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end

                UNION ALL

                               SELECT REHBERID,
                               0 AS BORC,
                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                                                                                                              --   TLBORC=0.0,
                                                                                                               --  TLALACAK=SUM(S.DOVIZ_TUTARI)
                               FROM SENETLER S
                               WHERE TUR = 24
                               AND TARIH  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
                               GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END

                UNION ALL

                               SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
                               BORC,0 AS ALACAK,
                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                                                                                                               --  TLBORC=SUM(S.DOVIZ_TUTARI),
                                                                                                                -- TLALACAK=0.0
                               FROM SENETLER S
                               WHERE TUR = 34
                               AND TARIH  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59''
                               GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

                               ) as asd
                group by REHBERID,KUR) AS DSA
                               INNER JOIN REHBER R ON            DSA.REHBERID=R.ID
                               LEFT OUTER JOIN             REHBERPERSONEL P on R.ID = P.REHBERID
                               left outer join REHBER R2 on R2.ID=R.TEMSILCI
                               left outer join (Select R1.ID,RB.BILGI from REHBER R1
                               left outer join REHBERILETISIM RI on R1.ID=RI.REHBERID
                               Left outer join REHBERBILGI RB on RB.YER_ID=RI.ID
                               left outer join REHBERAYAR RA on RA.SIRA=RB.SIRA Where RI.VARSAYILAN=1 and RB.YERI=1 and RA.VARSAYILAN=8) X on X.ID=R.ID
                               left outer join GENINI GSnf on R.SINIF=GSnf.DEGER and GSnf.BOLUM=-2203 and GSnf.DIL=-1 --2203  sınıf
                               left outer join GENINI GGrp on R.GRUP=GGrp.DEGER and GGrp.BOLUM=-2202 and GGrp.DIL=-1  --2202  grup

 where R.GRUP<>335 and R.ID > 0
 and R.DURUM=1  and  coalesce(R.ID,'''')<>''''
   ) AS XXX
ORDER BY kur,kod' WHERE id = 1275;
UPDATE public.dokumler SET sql = '/*PGX*/select G.ANAHTAR,FB.FATURATARIH,FB.FATURANO,S.KOD,S.STOKADI,SOM.KALAN
from 
            STOK_ORT_MALIYET SOM inner join
            FATBASLIK FB on SOM.FATBASID=FB.ID inner join 
            FATURA F on SOM.FATURAID=F.ID inner join 
            STOKLAR S on SOM.STOKID=S.ID inner join 
            GENINI G on G.BOLUM=-1005 and G.DIL=-1 and G.DEGER=FB.TUR
where SOM.KALAN<0.0' WHERE id = 1276;
UPDATE public.dokumler SET sql = '/*PGX*/select 
       ID,KOD,STOKADI,FIRMAKOD,FIRMA,TUR,TIPI,BELGETARIH,FATURANO,OZELKOD,ZARF,ADET,GIREN,CIKAN,KALAN,
       BIRIMALISFIYAT,ADET*BIRIMALISFIYAT AS ALISTUTAR ,BIRIMEKMALIYET,ADET*BIRIMEKMALIYET AS EKMALIYET ,BIRIMMALIYET,TOPLAMMALIYET,
       SATISBIRIMSATISFIYAT,SATISBIRIMMALIYET,SATISTOPLAMSATISTUTARI,SATISBIRIMKARLILIK,STMM
FROM(

SELECT 
ID,KOD,STOKADI, FIRMAKOD,FIRMA,
TUR,TIPI,
BELGETARIH,FATURANO,
CASE WHEN ADET<0 THEN -1*ADET ELSE ADET END AS ADET , ZARF, OZELKOD,
GIREN,CIKAN,KALAN,
 coalesce((CASE WHEN TURDURUMU=''Giriş'' THEN ROUND(BIRIMFIYAT,2) END),0) AS BIRIMALISFIYAT ,
 coalesce((CASE WHEN TURDURUMU=''Giriş'' THEN ROUND(EKMALIYET,2)/ADET  END),0) AS BIRIMEKMALIYET ,
 coalesce((CASE WHEN TURDURUMU=''Giriş'' and TIPI<>''İade'' THEN ROUND(((EKMALIYET/ADET)+BIRIMFIYAT),2) WHEN TURDURUMU=''Giriş'' and TIPI=''İade'' THEN MALIYET END),0) AS BIRIMMALIYET ,
 coalesce((CASE WHEN TURDURUMU=''Giriş'' and TIPI<>''İade'' THEN ROUND(((EKMALIYET+(BIRIMFIYAT*ADET))),2)  WHEN TURDURUMU=''Giriş'' and TIPI=''İade'' THEN MALIYET*ADET END),0)  AS TOPLAMMALIYET ,

 coalesce((CASE WHEN TURDURUMU=''Çıkış'' THEN BIRIMFIYAT END),0) AS SATISBIRIMSATISFIYAT ,
 coalesce((CASE WHEN TURDURUMU=''Çıkış'' THEN MALIYET  END),0) AS SATISBIRIMMALIYET ,
 coalesce((CASE WHEN TURDURUMU=''Çıkış'' THEN -1*(BIRIMFIYAT*ADET) END),0) AS SATISTOPLAMSATISTUTARI ,  
 coalesce((CASE WHEN TURDURUMU=''Çıkış'' THEN BIRIMFIYAT-MALIYET  END),0) AS SATISBIRIMKARLILIK ,
 coalesce((CASE WHEN TURDURUMU=''Çıkış'' AND ADET<0 THEN -1*(MALIYET*ADET)  
                                   WHEN TURDURUMU=''Çıkış'' AND ADET>=0 THEN MALIYET*ADET  END),0) 

 AS STMM FROM (
SELECT   R.KOD AS FIRMAKOD,R.FIRMA,
	STK.ID,STK.KOD,FB.OZELKOD,
        STK.STOKADI,
        I.AD AS TUR ,
	I.ACIKLAMA AS TIPI ,
        I.TUR AS ISLEMTURU ,
         CASE WHEN FB.TUR IN (3,11,12) THEN ''Giriş''
                        WHEN FB.TUR IN (4,15,16) THEN ''Çıkış''
                        WHEN FB.TUR IN (2) AND coalesce(FB.CIKISDEPO,0)=0 THEN ''Giriş''
                        WHEN FB.TUR IN (2) AND coalesce(FB.GIRISDEPO,0)=0 THEN ''Çıkış'' END AS TURDURUMU ,
        FB.FATURATARIH AS BELGETARIH ,FB.FATURANO,
	ROUND(F.TUTAR/F.ADET,2) AS BIRIMFIYAT , BZ.AD AS ZARF ,
        S.MIKTAR AS ADET ,
	case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then 0.0
                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.MIKTAR
                                                    when F.MIKTAR>0 then F.MIKTAR
                                                    when F.MIKTAR<0 then 0.0 end AS GIREN ,

	case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then F.MIKTAR
                                                    when coalesce(FB.CIKISDEPO,0)=0 then 0.0
                                                    when F.MIKTAR>0 then 0.0
                                                    when F.MIKTAR<0 then -F.MIKTAR end AS CIKAN ,
	S.KALAN AS KALAN ,
        coalesce(F.EKMALIYET,0) AS EKMALIYET ,ROUND(F.TUTAR,2) AS TUTAR ,
		D.DEPOADI,
		ROUND(S.BIRIMMALIYET,2)
 AS MALIYET FROM 
	STOK_ORT_MALIYET S 
		INNER JOIN STOKLAR STK ON S.STOKID=STK.ID
		INNER JOIN FATBASLIK FB ON S.FATBASID=FB.ID
		INNER JOIN FATURA F ON S.FATURAID=F.ID
		LEFT JOIN ISLEMTURLERI I ON I.TUR=FB.TUR AND I.TIP=FB.TIPI
	        --LEFT JOIN ISLEMTURLERI I1 ON I1.TUR=FB.TUR AND FB.TUR IN (3,4)
		INNER JOIN DEPOLAR D ON D.ID=S.DEPOID
    LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
    LEFT JOIN REHBER R ON FB.REHBERID=R.ID
WHERE
	FB.TUR NOT IN (10,14)
	
	) AS X
	WHERE
		BELGETARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
		--AND DEPOADI LIKE ''$Depo$%''
	--	AND KOD LIKE ''$StokKodu$%''
) AS Y
ORDER BY ID,BELGETARIH' WHERE id = 1277;
UPDATE public.dokumler SET sql = '/*PGX*/

 

                  

                 -- 

                --  

 

                  --

                  --

                  --

                  

                 SELECT URUNID,STOKKOD,STOKADI,

         --RAF=(SELECT TEditRaf FROM STOKlar s WHERE S.KOD=Y.STOKKOD ),

         Envanter Adet (G-Ç)=ADET,

         Birim Maliyet=ROUND(BIRIMMALIYET,2),          

         Envanter Maliyet Toplam(G-Ç)=ROUND((ADET*ROUND(BIRIMMALIYET,2)),2) ,

         

         Envanter Adet (Maliyet)=MALIYETADET,

         Birim_Maliyet=ROUND(BIRIMMALIYET,2),          

         Envanter Maliyet Toplam(Maliyet)=ROUND((MALIYETADET*ROUND(BIRIMMALIYET,2)),2) ,

         

         ADETFARK=MALIYETADET-ADET,

         MALIYETFARK=ROUND((MALIYETADET*ROUND(BIRIMMALIYET,2)),2)- ROUND((ADET*ROUND(BIRIMMALIYET,2)),2)

         

         FROM(

 

                SELECT URUNID,STOKKOD,STOKADI,

         ADET=SUM(GIREN-CIKAN),

                MALIYETADET=coalesce((SELECT coalesce(KALAN,0) FROM STOK_ORT_MALIYET SOM WHERE SOM.STOKID=X.URUNID AND SOM.DEPOID=X.DEPO AND SOM.TARIH<=''2014-01-01 23:59:59''--''2015-11-24 23:59'' ORDER BY TARIH DESC LIMIT 1 ),0),

                               BIRIMMALIYET=coalesce((SELECT coalesce(BIRIMMALIYET,0) FROM STOK_ORT_MALIYET SOM WHERE SOM.STOKID=X.URUNID AND SOM.DEPOID=X.DEPO AND SOM.TARIH<=''2014-01-01 23:59:59''--''2015-11-24 23:59'' ORDER BY TARIH DESC LIMIT 1 ),0)

                FROM (

 

                  SELECT   

                    KOD=case when FB.REHBERID>0 then R.KOD else '''' end,

                    FIRMA=case when FB.REHBERID>0 and FB.TUR<>20 then R.FIRMA 

                                                   when FB.TUR=20 AND coalesce(FB.CIKISDEPO,0)<>0 then D2.DEPOADI

                                                   when FB.TUR=7 THEN ''Sayım Fişi''

                                                else '''' end,

                    OLAY=case                                        when coalesce(FB.TUR,0)=6 then ''Üretim''

                                                    when coalesce(FB.GIRISDEPO,0)=0 then (case when coalesce(FB.TIPI,0)=2 then ''Çıkış(iade)'' else ''Çıkış'' end)

                                                    when coalesce(FB.CIKISDEPO,0)=0 then (case when coalesce(FB.TIPI,0)=2 then ''Giriş(iade)'' else ''Giriş'' end)

                                                    when F.MIKTAR>0 then (case when coalesce(FB.TIPI,0)=2 then ''Giriş(iade)'' else ''Giriş'' end)

                                                    when F.MIKTAR<0 then (case when coalesce(FB.TIPI,0)=2 then ''Çıkış(iade)'' else ''Çıkış'' end) 

                                                                                         

                                                                                         end,

                    F.URUNID,S.KOD AS STOKKOD,S.STOKADI,

                                  FATBASID=FB.ID,FATURAID=F.ID,

                                  FB.TUR,

                                  --TURAD= IT.AD ,

                                  FB.FATURATARIH,FB.FATURASERI,

                                  FB.FATURANO,FB.REHBERID,

                                  F.BIRIM,F.BIRIMFIYAT,F.TUTAR,F.KUR, F.EKMALIYET, 

                    DEPO=case 

                                                    when coalesce(FB.GIRISDEPO,0)=0 then FB.CIKISDEPO

                                                    when coalesce(FB.CIKISDEPO,0)=0 then FB.GIRISDEPO

                                                    when F.MIKTAR>0 then FB.GIRISDEPO

                                                    when F.MIKTAR<0 then FB.CIKISDEPO end,

                    GIREN=case 

                                                    when coalesce(FB.GIRISDEPO,0)=0 then 0.0

                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.MIKTAR

                                                    when F.MIKTAR>0 then F.MIKTAR

                                                    when F.MIKTAR<0 then 0.0 end,

                    CIKAN=case 

                                                    when coalesce(FB.GIRISDEPO,0)=0 then F.MIKTAR

                                                    when coalesce(FB.CIKISDEPO,0)=0 then 0.0

                                                    when F.MIKTAR>0 then 0.0

                                                    when F.MIKTAR<0 then -F.MIKTAR end,

                    ADET =case 

                                                    when coalesce(FB.GIRISDEPO,0)=0 then F.ADET

                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.ADET

                                                    when F.ADET>0 then F.ADET

                                                    when F.ADET<0 then F.ADET end,

                    MIKTAR=case 

                                                    when coalesce(FB.GIRISDEPO,0)=0 then -F.MIKTAR

                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.MIKTAR

                                                    when F.MIKTAR>0 then F.MIKTAR

                                                    when F.MIKTAR<0 then F.MIKTAR end
    FROM           

        FATBASLIK FB 

                     inner join 

                           FATURA F on F.FATBASID=FB.ID 

                     left outer join 

                           REHBER R on FB.REHBERID=R.ID

                     left join depolar d1 on fb.GIRISDEPO=D1.ID AND coalesce(D1.MALIYETI_ETKILESIN,0)=1

                     left join depolar d2 on fb.CIKISDEPO=D2.ID AND coalesce(D1.MALIYETI_ETKILESIN,0)=1

                                                                              INNER JOIN STOKLAR S ON F.URUNID=S.ID

    where 

              FB.FATURATARIH <= ''2014-01-01 23:59:59''--''2015-11-24 23:59'' and

                                                 coalesce(FB.DURUM,1)<>6 and F.TUR=1 and 

              F.STOKDURUMDEGIS=1 and 

              FB.TUR NOT IN (20,109,119) AND

              1=case when 1=0 then 1 

                           when 1=(case 

                                                       when coalesce(FB.GIRISDEPO,0)=0 then FB.CIKISDEPO

                                                       when coalesce(FB.CIKISDEPO,0)=0 then FB.GIRISDEPO

                                                       when F.MIKTAR>0 then FB.GIRISDEPO

                                                      when F.MIKTAR<0 then FB.CIKISDEPO 

                                                       end) 

                           then 1 

                     else 0 

                     end

UNION ALL
SELECT   

                    KOD=case when FB.REHBERID>0 then R.KOD else '''' end,

                    FIRMA=case when FB.TUR IN (20) THEN D2.DEPOADI

                                                   when FB.TUR IN (109,119) THEN R.FIRMA
                                                else '''' end,

                    OLAY=case when coalesce(FB.TIPI,0)=2 then ''Çıkış(iade)'' else ''Çıkış'' end,

                    F.URUNID,S.KOD AS STOKKOD,S.STOKADI,FATBASID=FB.ID,FATURAID=F.ID,

                    FB.TUR,--= CASE WHEN (FB.TUR IN (109) AND FB.TIPI=2)THEN ''İade Konsinye'' ELSE FB.TUR END,

                    --TURAD= CASE WHEN FB.TUR =109 AND FB.TIPI = 2 THEN ''İade Konsinye'' ELSE IT.AD END,

                    FB.FATURATARIH,FB.FATURASERI,

                    FB.FATURANO,FB.REHBERID,F.BIRIM,F.BIRIMFIYAT,F.TUTAR,F.KUR,  F.EKMALIYET,

                    DEPO   = CIKISDEPO,

                    GIREN   = 0,

                    CIKAN   = F.MIKTAR,

                    ADET    = F.ADET,

                    MIKTAR  = -F.MIKTAR
    FROM           

        FATBASLIK FB 

                     inner join 

                           FATURA F on F.FATBASID=FB.ID 

                     left outer join 

                           REHBER R on FB.REHBERID=R.ID

                     left join depolar d1 on fb.GIRISDEPO=D1.ID AND coalesce(D1.MALIYETI_ETKILESIN,0)=1

                     left join depolar d2 on fb.CIKISDEPO=D2.ID AND coalesce(D1.MALIYETI_ETKILESIN,0)=1

                                                                              INNER JOIN STOKLAR S ON F.URUNID=S.ID

    where 

              FB.FATURATARIH <= ''2014-01-01 23:59:59''--''2015-11-24 23:59'' 

                                                 and coalesce(FB.DURUM,1)<>6 and F.TUR=1 and 

              (FB.TUR IN (20,119) OR (FB.TUR IN (109) AND FB.TIPI=2)) AND

              F.STOKDURUMDEGIS=1 and 

              1=case when 1=0 then 1 

                           when 1=CIKISDEPO 

                           then 1 

                     else 0 

                     end

UNION ALL

 

SELECT   

                    KOD=case when FB.REHBERID>0 then R.KOD else '''' end,

                    FIRMA=case when FB.TUR IN (20) THEN D1.DEPOADI

                                                   when FB.TUR IN (109,119) THEN R.FIRMA
                                                else '''' end,

                    OLAY=case when coalesce(FB.TIPI,0)=2 then ''Giriş(iade)'' else ''Giriş'' end,
                    F.URUNID,S.KOD AS STOKKOD,S.STOKADI,FATBASID=FB.ID,FATURAID=F.ID,

                                  FB.TUR,

                                  --TURAD= IT.AD ,

                                  FB.FATURATARIH,FB.FATURASERI,

                                  FB.FATURANO,FB.REHBERID,F.BIRIM,F.BIRIMFIYAT,F.TUTAR,F.KUR,  F.EKMALIYET,                             

                    DEPO   = GIRISDEPO,

                    GIREN  = F.MIKTAR,

                    CIKAN   = 0,

                    ADET   = F.ADET,

                    MIKTAR  = F.MIKTAR

    FROM           

        FATBASLIK FB 

                     inner join FATURA F on F.FATBASID=FB.ID 

                     left  joiN REHBER R on FB.REHBERID=R.ID

                     left  join depolar d1 on fb.GIRISDEPO=D1.ID AND coalesce(D1.MALIYETI_ETKILESIN,0)=1 

                     left  join depolar d2 on fb.CIKISDEPO=D2.ID AND coalesce(D1.MALIYETI_ETKILESIN,0)=1 

                                                                               INNER JOIN STOKLAR S ON F.URUNID=S.ID

    where 

              FB.FATURATARIH <= ''2014-01-01 23:59:59''--''2015-11-24 23:59'' 


                                                 and coalesce(FB.DURUM,1)<>6 and

              F.TUR=1 and 

              FB.TUR IN (20,109,119) AND

              F.STOKDURUMDEGIS=1 and 

              1=case when 1=0 then 1 

                           when 1=GIRISDEPO 

                           then 1 

                     else 0 

                     end

                               ) AS X

 

                GROUP BY URUNID,STOKKOD,STOKADI,DEPO


                ) AS Y

WHERE STOKKOD LIKE ''$StokKod$%''
' WHERE id = 1278;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT D.DEMIRBASNO,D.DEMIRBASADI,D.SERINO,  
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2801 AND G.DEGER=DT.TIP) AS DURUM ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=D.TEKNIKSORUMLU) AS TENIKSORUMLU ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=D.TEKNIKBILGI) AS TEKNIKBILGI ,  
  (SELECT FIRMA FROM REHBER R WHERE R.ID=DT.VERENID) AS VERENPERSONEL ,
(SELECT FIRMA FROM REHBER R WHERE R.ID=DT.ALANID) AS ALANPERSONEL ,        
L.ACIKLAMA AS LOKASYONADI ,
 DU.STOKADI AS KATEGORIADI ,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2804 AND G.DEGER=D.MARKA) AS MARKA ,
G.ANAHTAR AS MODELAD,
dt.TIP
FROM 
	DEMIRBAS_TUTANAK AS DT inner join 
	DEMIRBAS_TUTANAK_DETAY DTD on DT.ID=DTD.TUTANAKID AND DT.TIP=21  inner join
	DEMIRBAS D on D.ID=DTD.DEMIRBASID AND D.REHBERID=DT.ALANID
	LEFT OUTER JOIN DEMIRBAS_URUN AS DU ON DU.ID=D.KATEGORIID  
	LEFT OUTER JOIN GENINI G ON G.DEGER = D.MODEL AND G.BOLUM=cast(''-2804''||cast(D.MARKA as varchar) as integer) 
	LEFT OUTER JOIN LOKASYON AS L  ON L.ID = dt.LOKASYONID 
        LEFT OUTER JOIN REHBER AS R ON R.ID = D.REHBERID
where DT.ID in (select XX.ID from (select DT2.ID,  row_number() over (partition by DTD2.DEMIRBASID order by DT2.ID desc)
				 AS SIRA from DEMIRBAS_TUTANAK DT2 inner join DEMIRBAS_TUTANAK_DETAY DTD2 on DT2.ID=DTD2.TUTANAKID AND DT2.TIP=21 )as XX
				where XX.SIRA=1)
AND D.DEMIRBASADI LIKE ''%$Demirbas$%''
AND cast(coalesce(D.DURUM,'''') as varchar) LIKE ''%$Durum$%''
AND coalesce(L.ACIKLAMA,'''') LIKE ''%$Lokasyon$%''
AND   ( R.FIRMA LIKE ''%$Firma$%''  or R.FIRMA like''ORTAK%'' )
order by 1' WHERE id = 1279;
UPDATE public.dokumler SET sql = '/*PGX*/


select X.KREDIKODU,ADI,KREDITEMINAT,(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25008 AND DEGER=31) AS KREDI_TURU ,
	KREDILIMIT,--=BIRIMRISKPAYI*sum(YAPRAKADET),
	BIRIMRISKPAYI*(YAPRAKADET-sum(ODENMIS)) AS RISK ,
	KREDILIMIT-(BIRIMRISKPAYI*(YAPRAKADET-sum(ODENMIS))) AS LIMIT_BOSLUGU ,
	ALINISTARIHI,
	X.KUR,
	KREDILIMITSURE,X.KREDIKULLANIMSURE,KREDILIMITSURETIPI,
	--LIMITADET=KREDILIMIT/BIRIMRISKPAYI,
	FLOOR(KREDILIMIT/BIRIMRISKPAYI) AS LIMIT_ADET ,
	X.YAPRAKADET-sum(ODENMIS) AS RISK_ADET ,
	FLOOR(KREDILIMIT/BIRIMRISKPAYI)-(X.YAPRAKADET-sum(ODENMIS)) AS KALAN_ADET ,
	BIRIMRISKPAYI
from (
		select KR.KREDILIMIT,KR.KREDIKODU,ADI,KR.KREDITEMINAT,(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25008 AND DEGER=31) AS KREDI_TURU ,KR.ALINISTARIHI,
		KR.KREDILIMITSURETIPI,KR.KREDILIMITSURE,BANKAHESAPLARID,KR.KUR,KR.KREDIKULLANIMSURE,
			 (select SUM(1+BITSERINO-BASSERINO) from CEKKOCAN CKO where CKO.KREDIID=KR.ID) AS YAPRAKADET ,
			 coalesce((select COUNT(*) from CEKLER C where C.CEKKOCANID=CKO.ID and C.TUR in (140)),0) AS PIYASACEK ,
			 coalesce((select COUNT(*) from CEKLER C where C.CEKKOCANID=CKO.ID and C.TUR in (141,142,143)),0) AS ODENMIS ,
			cast((select ANAHTAR from GENINI where BOLUM=26015) as money)
		 AS BIRIMRISKPAYI from 
			KREDILER KR inner join
			CEKKOCAN CKO on CKO.KREDIID=KR.ID
			WHERE 	GENELKREDITIPI = 31 
	)as X  
	LEFT OUTER JOIN BANKAHESAPLAR BH ON BH.ID=X.BANKAHESAPLARID
	LEFT OUTER JOIN BANKASUBELER BS ON BS.ID=BH.BANKASUBELERID
	LEFT OUTER JOIN BANKALAR B ON B.BANKAKODU=BS.BANKAKODU  
	
group by YAPRAKADET,ADI,KREDIKODU,KREDILIMIT,KREDILIMITSURETIPI,KREDILIMITSURE,KREDITEMINAT,BIRIMRISKPAYI,X.KUR,ALINISTARIHI,KREDIKULLANIMSURE
' WHERE id = 1287;
UPDATE public.dokumler SET sql = '/*PGX*/select 
      REVERSE(SUBSTRING(REPLACE(REVERSE(KOD),'' '',''''),CHARINDEX(''.'',REVERSE(KOD),1)+1,length(REPLACE(KOD,'' '',''''))-(CHARINDEX(''.'',REVERSE(REPLACE(KOD,'' '','''')),1)-1))) AS ROOTKOD ,
      MG.KOD,PB.ID, PROJEID,MASRAFID, MG.AD,PB.MIKTAR,(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2702 AND G.DEGER=PB.BIRIMI) AS BIRIMI ,
	  PB.BIRIMFIYAT, PB.TUTAR,PB.KUR, P.PROJEKODU,
      (select YERELBAKIYE from fn_Proje_Ekstre(PB.PROJEID,''2000-01-01 00:00'', now(), 1,MG.ID, MG.OZELKOD) Ex order by Ex.TARIH desc LIMIT 1 ) AS GERCEKTAH ,
      (select YERELBAKIYE from fn_Proje_Ekstre(PB.PROJEID,''2000-01-01 00:00'', now(), 2,MG.ID, MG.OZELKOD) Ex order by Ex.TARIH desc LIMIT 1 )
 AS GERCEKODE from  PROJEBUTCE PB inner join MASRAFGELIR MG on MG.ID = PB.MASRAFID
                   INNER JOIN PROJELER P ON P.ID=PB.PROJEID
Where P.PROJEKODU=''$PROJEKODU$''                                      
--and coalesce(PROJEADI,'''') LIKE ''%$PROJEADI$%''
--coalesce(PB.PROJEKODU,'''') LIKE ''%$PROJEKODU$%''' WHERE id = 1290;
