      MG.KOD,PB.ID, PROJEID,MASRAFID, MG.AD,PB.MIKTAR,(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2702 AND G.DEGER=PB.BIRIMI) AS BIRIMI ,
