      (select YERELBAKIYE from fn_Proje_Ekstre(PB.PROJEID,''2000-01-01 00:00'', now(), 2,MG.ID, MG.OZELKOD) Ex order by Ex.TARIH desc LIMIT 1 )
 AS GERCEKODE from  PROJEBUTCE PB inner join MASRAFGELIR MG on MG.ID = PB.MASRAFID
