UPDATE public.dokumler SET sql = '/*PGX*/--İÇERİK HALİ


''$Bitis$ 23:59'' DATETIME,
''$StokAdi$%'' VARCHAR(10),
''$DepoAdi$'' VARCHAR(50)





SELECT GRUP,BELGETARIH,TARIH,KOD,STOKADI,CARIKOD,CARIAD,DEPO,GIREN,CIKAN,KALAN=GIREN-CIKAN,XX.ANAHTAR,MARKA=G.ANAHTAR
FROM(

SELECT HAREKET AS GRUP,BELGETARIH,TARIH,X.KOD,X.STOKADI,'''' AS CARIKOD,'''' AS CARIAD,''$DepoAdi$'' AS DEPO,SUM(MIKTAR) AS GIREN,0 AS CIKAN,S.MARKA,
--SUM(MIKTAR) AS KALAN,

R.ANAHTAR FROM 
(
                                               SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI, F.MIKTAR, F.ADET, F.BIRIM,  
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, GIRDEPO.ID AS STOKDEPOID, 
                                                                     GIRDEPO.DEPOADI AS STOKDEPO, coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID
                                               WHERE   F.STOKDURUMDEGIS=1 and    (F.TUR = 1) AND (FB.TARIH > coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND (FB.TUR IN (10, 11, 12, 19)) AND FB.TARIH < ''$Baslangic$ 00:00'' AND S.KOD LIKE ''$StokAdi$%''+''%'' AND GIRDEPO.DEPOADI LIKE ''$DepoAdi$''+''%'' 
                                               UNION ALL
                                               SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI, -1*(F.MIKTAR) AS MIKTAR, F.ADET, F.BIRIM,
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, CIKDEPO.ID AS STOKDEPOID, 
                                                                     CIKDEPO.DEPOADI AS STOKDEPO, coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID
                                               WHERE    F.STOKDURUMDEGIS=1 and   (F.TUR = 1) AND (FB.TARIH > coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND FB.TARIH < ''$Baslangic$ 00:00'' AND (FB.TUR IN (14, 15, 16, 19)) AND S.KOD LIKE ''$StokAdi$%''+''%'' AND CIKDEPO.DEPOADI LIKE ''$DepoAdi$''+''%''  
) AS X INNER JOIN STOKLAR S ON X.KOD=S.KOD  LEFT OUTER JOIN  REHBERINI R   ON R.DEGER=S.ANABIRIM AND  BOLUM=''StokKart_Anabirim''
GROUP BY HAREKET,BELGETARIH,TARIH,X.KOD,X.STOKADI,R.ANAHTAR,S.MARKA
-------------------------------------------------------------------------
UNION ALL
-------------------------------------------------------------------------
  SELECT HAREKET AS GRUP,BELGETARIH,TARIH,X.KOD,X.STOKADI, CARIKOD,FIRMA AS CARIAD,DEPO AS DEPO,GIREN,CIKAN,S.MARKA,
  --GIREN-CIKAN AS KALAN,
  R.ANAHTAR FROM 
(
                                               SELECT     ''Giren'' AS HAREKET,FATURATARIH AS BELGETARIH,TARIH AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI,R.KOD AS CARIKOD,R.FIRMA, F.MIKTAR AS GIREN ,0 AS CIKAN, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS DEPO,GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, GIRDEPO.ID AS STOKDEPOID, 
                                                                     GIRDEPO.DEPOADI AS STOKDEPO, coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID LEFT OUTER JOIN 
                                                                     REHBER AS R ON R.ID=FB.REHBERID
                                               WHERE    F.STOKDURUMDEGIS=1 and   (F.TUR = 1) AND (FB.TARIH > coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND (FB.TUR IN (10, 11, 12, 19)) AND FB.TARIH < ''$Bitis$ 23:59'' AND S.KOD LIKE ''$StokAdi$%''+''%'' AND GIRDEPO.DEPOADI LIKE ''$DepoAdi$''+''%'' 
                                               UNION ALL
                                               SELECT     ''Çıkan'' AS HAREKET,FATURATARIH AS BELGETARIH,TARIH AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI,R.KOD AS CARIKOD,R.FIRMA, 0 AS GIREN,F.MIKTAR AS CIKAN, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, CIKDEPO.DEPOADI AS DEPO,GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, CIKDEPO.ID AS STOKDEPOID, 
                                                                     CIKDEPO.DEPOADI AS STOKDEPO, coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID LEFT OUTER JOIN
                                                                     REHBER AS R ON R.ID=FB.REHBERID
                                               WHERE   F.STOKDURUMDEGIS=1 and    (F.TUR = 1) AND (FB.TARIH > coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND FB.TARIH < ''$Bitis$ 23:59'' AND (FB.TUR IN (14, 15, 16, 19)) AND S.KOD LIKE ''$StokAdi$%''+''%'' AND CIKDEPO.DEPOADI LIKE ''$DepoAdi$''+''%''  
) AS X LEFT OUTER JOIN STOKLAR S ON X.KOD=S.KOD  LEFT OUTER JOIN  REHBERINI R   ON R.DEGER=S.ANABIRIM AND  BOLUM=''StokKart_Anabirim''

) AS XX left join GENINI G on XX.MARKA=G.DEGER and G.BOLUM=-2804 and G.DIL=-1
' WHERE id = 1292;
UPDATE public.dokumler SET sql = '/*PGX*/select
    	R.GRUP,    
R.KOD AS HESAP_KODU,
R.FIRMA AS HESAP_ADI,
    	--KATEGORIADI=(select ANAHTAR from GENINI where BOLUM=-2204 and DEGER=KATEGORI LIMIT 1 ),
    	--GOREVADI=(select ANAHTAR from GENINI where BOLUM=-2205 and DEGER=KATEGORI LIMIT 1 ),
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=40 LIMIT 1 ) AS TEL1 ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=42 LIMIT 1 ) AS CEP ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=43 LIMIT 1 ) AS FAX ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=2 LIMIT 1 ) AS ADRES ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=4 LIMIT 1 ) AS PK ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 
		    and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=20 LIMIT 1 ) AS VERGIDAIRESI ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.ETIKET=RB.ETIKET 
		    AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=22 LIMIT 1 ) AS VERGINO ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=48 LIMIT 1 ) AS WEB ,
    	(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=46 LIMIT 1 ) AS EPOSTA ,
G1.ANAHTAR AS BOLGE,
R1.FIRMA AS TEMSILCI,
coalesce((SELECT ADSOYAD FROM(SELECT ADSOYAD FROM REHBERPERSONEL RP WHERE R.ID=RP.REHBERID AND VARSAYILAN=1 ) AS X LIMIT 1 ),'''') AS ILGILI_KISI ,
R.EKLEMETARIHI
      from
      	REHBER R
        left outer join REHBERILETISIM RI on RI.REHBERID=R.ID and VARSAYILAN=1
LEFT OUTER JOIN  GENINI G1 ON  R.BOLGE=G1.DEGER  AND G1.BOLUM=-2210 /*BOLGE*/ AND DIL=-1  
LEFT OUTER JOIN  REHBER R1 ON  R1.ID=R.TEMSILCI   /*Temsilci*/  
WHERE cast(R.GRUP as varchar) LIKE ''$Kod$''||''%''   AND R.GRUP <>334 AND R.GRUP <>335  AND R.GRUP<>1
ORDER BY R.GRUP' WHERE id = 1293;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                             
 VADE,TUTAR,BORCLU,CARIKODU,CARIADI,HESAPNO,X.DURUM,CEKNO,REFERANS TARİHİ,EVRAK NO,X.HESAPKODU,HP.HESAPADI,BANKAADI,SUBEADI
 
FROM (
SELECT C.VADE,C.TUTAR,coalesce(C.BORCLU,'''') as BORCLU,R.KOD AS CARIKODU,R.FIRMA AS CARIADI,C.HESAPNO,C.SERINO AS CEKNO,C.TARIH
 AS REFERANS TARİHİ,C.MAKBUZNO AS EVRAK NO,
 REVERSE( SUBSTRING(REVERSE(C.KOD),CHARINDEX(''.'',REVERSE(C.KOD),1)+1,length(C.KOD)-(CHARINDEX(''.'',REVERSE(C.KOD),1)-1))) AS HESAPKODU ,
 BN.BANKAADI,BS.SUBEADI,G.ANAHTAR AS DURUM

 FROM CEKLER C INNER JOIN BANKASUBELER BS ON C.BANKASUBELERID=BS.ID     
 INNER JOIN BANKALAR BN ON BN.BANKAKODU=BS.BANKAKODU INNER JOIN REHBER R ON R.ID=C.REHBERID 
 INNER JOIN GENINI G ON C.DURUM=G.DEGER AND G.BOLUM=''-2602'' AND DIL=-1
 WHERE C.TUR=33  AND C.CEKSENET=103
 ) AS X INNER JOIN HESAPPLANI HP ON X.HESAPKODU=HP.HESAPKODU 
 where
	X.DURUM LIKE ''$Durum$%'' AND
	VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''' WHERE id = 1295;
UPDATE public.dokumler SET sql = '/*PGX*/





select  DISTINCT
       C.ID,C.TARIH AS CEKTARIH ,C.VADE,CH.TARIH AS SONHAREKETTARIH ,
       (select I.AD from ISLEMTURLERI I where I.TUR=CH.ISLEM) AS HAREKETTUR ,
       C.SERINO,CH.ACIKLAMA,R.FIRMA,C.TUTAR,C.KUR,CH.DOVIZ_TUTARI,CH.DOVIZ_KURU,C.ACIKLAMA,G.ANAHTAR
from 
       CEKLER C inner join 
       (select RANK() OVER (PARTITION BY CEKSENETLERID ORDER BY TARIH DESC,ID DESC) AS rnk ,* from CEKHAREKET where TARIH<=''$Bitis$ 23:59:59'') CH on C.ID=CH.CEKSENETLERID and rnk=1 inner join 
       REHBER R on R.ID=C.REHBERID inner join
       HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM left outer join 
       GENINI G on G.BOLUM=-1005 and CH.ISLEM=G.DEGER and G.DIL=-1
where H.HESAPKODU like ''$Hesapkodu$''||''%'' and C.TARIH <= ''$Bitis$ 23:59:59''  AND C.CEKSENET IN (101,103)
 
order by 4
' WHERE id = 1299;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT S.BITISTARIHI,
             CASE S.KAPSAM WHEN 0 THEN ''H'' 
            WHEN 1 THEN ''E'' END  AS GARANTI ,
            ÜRÜN_ADI=(SELECT AD FROM EKIPMANLAR  E1 WHERE E1.ID=S.EKIPMANID),
            S.SERINO,
            (SELECT AD FROM KATEGORI KA1 WHERE KA1.ID=E.KATEGORI) AS KATEGORI ,
            (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=E.MARKA) AS MARKA ,
            (select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=E.MODEL AND GB.DEGER=E.MARKA
                                where GALT.BOLUM like ''-2701%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2701 ) AS MODEL ,
            (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-3006 AND G.DEGER=S.TURU) AS TUR ,
            R.FIRMA,
            FB.FATURA_MATRAHI AS Kdv Hariç Tutar,
            FB.KUR as Para Birimi ,
            (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-3013 AND G.DEGER=S.KAPSAM )
 AS GRANTI_DURUM FROM SERVIS S INNER JOIN EKIPMANLAR E ON S.EKIPMANID=E.ID
         LEFT OUTER JOIN  KATEGORI KA ON E.KATEGORI=KA.ID
         INNER JOIN REHBER R ON R.ID=S.REHBERID
         LEFT OUTER JOIN FATBASLIK FB ON FB.SERVISID=S.ID
WHERE S.ACKAPA=1 
and S.TARIH>=''$Baslangic$ 00:00:00'' AND
S.TARIH<=''$Bitis$ 23:59:00''
AND R.FIRMA LIKE ''%$Firma$%''
ORDER BY R.FIRMA,S.BITISTARIHI' WHERE id = 1300;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT  (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2114 AND G.DEGER=P.DURUM LIMIT 1 ) AS DURUM ,
       PROJEADI,
       PROJEKODU,
	   R.FIRMA,
F.ID,''Bütün'' AS KAYNAK ,case when FB.TUR=11 then ''Fatura'' when FB.TUR=12 then ''Fiş'' else ''Üretim'' end AS BelgeTipi ,
(select FIRMA from REHBER R where R.ID=FB.REHBERID) AS Satici ,
FB.FATURATARIH AS BelgeTarihi , FB.FATURANO AS BelgeNo ,
case when F.TUR=0 then (select AD from MASRAFGELIR MG where MG.ID=F.URUNID)
else (select STOKADI from STOKLAR S where S.ID=F.URUNID) end ||'' ''||coalesce(F.ACIKLAMA,'''') AS Aciklama ,
TUTAR/((100.0+KDV)/100.0) AS Tutar ,TUTAR-TUTAR/((100.0+KDV)/100.0) AS KDV , TUTAR AS Toplam ,F.KUR,
 (select R.FIRMA from REHBER R where R.ID=FB.SATICIKODU) AS Personel ,
 (select ALIs from DOVIZ D where D.CINSI=''€'' order by abs(datediff(day,D.TARIH,FB.FATURATARIH) ) LIMIT 1 ) AS KUR ,
 (Tutar/(select ALIs from DOVIZ D where D.CINSI=''€'' order by abs(datediff(day,D.TARIH,FB.FATURATARIH) ) LIMIT 1 ))
 AS TUTAR_EURO FROM FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID
inner join PROJELER P on P.ID=FB.PROJEID
			  LEFT join REHBER R on P.REHBERID=R.ID
			  
where FB.TUR in (6,11,12) and F.MIKTAR>0
and Fb.PROJEID>0
and coalesce(PROJEADI,'''') LIKE ''%$PROJEADI$%''
and coalesce(PROJEKODU,'''') LIKE ''%$PROJEKODU$%''
and coalesce(R.FIRMA,'''') LIKE ''%$FIRMA$%''
and 1 = case when ''Bütün'' LIKE ''%$KAYNAK$%'' then 1 else 0 end

union all 

 SELECT  (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2114 AND G.DEGER=P.DURUM LIMIT 1 ) AS DURUM ,
       PROJEADI,
       PROJEKODU,
	   R.FIRMA,
 F.ID,''Satır'' AS KAYNAK ,case when FB.TUR=11 then ''Fatura'' else ''Fiş'' end AS BelgeTipi ,
(select FIRMA from REHBER R where R.ID=FB.REHBERID) AS Satici ,
FB.FATURATARIH AS BelgeTarihi , FB.FATURANO AS BelgeNo ,
case when F.TUR=0 then (select AD from MASRAFGELIR MG where MG.ID=F.URUNID)
else (select STOKADI from STOKLAR S where S.ID=F.URUNID) end ||'' ''||coalesce(F.ACIKLAMA,'''') AS Aciklama ,
TUTAR/((100.0+KDV)/100.0) AS Tutar ,TUTAR-TUTAR/((100.0+KDV)/100.0) AS KDV , TUTAR AS Toplam ,F.KUR,
 (select R.FIRMA from REHBER R where R.ID=F.SATICIKODU) AS Personel ,
 (select ALIs from DOVIZ D where D.CINSI=''€'' order by abs(datediff(day,D.TARIH,FB.FATURATARIH) ) LIMIT 1 ) AS KUR ,
 (Tutar/(select ALIs from DOVIZ D where D.CINSI=''€'' order by abs(datediff(day,D.TARIH,FB.FATURATARIH) ) LIMIT 1 ))
 AS TUTAR_EURO FROM FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID
inner join PROJELER P on P.ID=F.PROJEID
			  LEFT join REHBER R on P.REHBERID=R.ID
where FB.TUR in (11,12)
and F.PROJEID>0
and coalesce(PROJEADI,'''') LIKE ''%$PROJEADI$%''
and coalesce(PROJEKODU,'''') LIKE ''%$PROJEKODU$%''
and coalesce(R.FIRMA,'''') LIKE ''%$FIRMA$%''
and 1 = case when ''Satır'' LIKE ''%$KAYNAK$%'' then 1 else 0 end

union all 

 SELECT  (SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2114 AND G.DEGER=P.DURUM LIMIT 1 ) AS DURUM ,
       PROJEADI,
       PROJEKODU,
	   R.FIRMA,
  F.ID,''Tahakkuk'' AS KAYNAK ,''Tahakkuk'' AS BelgeTipi ,
(select FIRMA from REHBER R where R.ID=FB.REHBERID) AS Satici ,
FB.FATURATARIH AS BelgeTarihi , FB.FATURANO AS BelgeNo ,
F.ACIKLAMA AS Aciklama ,
FATURA_TUTARI AS Tutar ,0 AS KDV , FATURA_TUTARI AS Toplam ,FB.KUR,
 (select R.FIRMA from REHBER R where R.ID=FB.SATICIKODU) AS Personel ,
 (select ALIs from DOVIZ D where D.CINSI=''€'' order by abs(datediff(day,D.TARIH,FB.FATURATARIH) ) LIMIT 1 ) AS KUR ,
 (Tutar/(select ALIs from DOVIZ D where D.CINSI=''€'' order by abs(datediff(day,D.TARIH,FB.FATURATARIH) ) LIMIT 1 ))
 AS TUTAR_EURO FROM FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID
inner join PROJELER P on P.ID=FB.PROJEID
			  LEFT join REHBER R on P.REHBERID=R.ID 
where FB.TUR= 13
and Fb.PROJEID>0
and coalesce(PROJEADI,'''') LIKE ''%$PROJEADI$%''
and coalesce(PROJEKODU,'''') LIKE ''%$PROJEKODU$%''
and coalesce(R.FIRMA,'''') LIKE ''%$FIRMA$%''
and 1 = case when ''Tahakkuk'' LIKE ''%$KAYNAK$%'' then 1 else 0 end

order by 3' WHERE id = 1302;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT CARİ KOD = R1.KOD,CARİ ADI=R1.FIRMA,C.KOD ASHESAP KODU,B.BANKAADI AS BANKA ADI,BS.SUBEADI as ŞUBE ADI,C.HESAPNO AS ÇEK HESAP NO,
C.SERINO AS ÇEK SERİ NO,C.TUTAR,C.KUR,C.VADE

FROM CEKLER C
  inner join CEKHAREKET CH on CH.ID=(select CH1.ID from CEKHAREKET CH1 where CH1.CEKSENETLERID=C.ID order by CH1.TARIH desc LIMIT 1 )
   INNER JOIN GENINI G ON C.TUR=G.DEGER
  left outer join REHBER R1 ON C.REHBERID=R1.ID
  left outer join BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
  left outer join BANKALAR B ON B.BANKAKODU = BS.BANKAKODU
  left outer join REHBER R2 on CH.REHBERID=R2.ID
  left outer join BANKAHESAPLAR BHSON on CH.BANKAHESAPLARID=BHSON.ID
  left outer join BANKAHESAPLAR BH2 on C.HESAPID=BH2.ID
 Where 1=1   AND C.CEKSENET=103
 and CH.ISLEM in (0,140,141,142,143) 
 AND G.BOLUM=-1005
AND    G.ANAHTAR LIKE ''%$Durum$'' 
AND coalesce(B.BANKAADI,'''') LIKE ''%$BANKAADI$%''
AND    VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
ORDER BY c.kur,C.VADE' WHERE id = 1306;
UPDATE public.dokumler SET sql = '/*PGX*/
@BIT   BIGINT,   
@CKID INT                                             

 

 --SELECT BASSERINO, BITSERINO from CEKKOCAN order by TARIH
 select BASSERINO, BITSERINO ,ck.ID--select *
  from CEKKOCAN CK inner join KREDILER C on CK.KREDIID= C.ID 
  --WHERE CK.ID LIKE ''$Durum$%''
   order by CK.TARIH
 
OPEN cek 
FETCH NEXT FROM cek INTO  @I + 1,@BIT,@CKID
WHILE @@FETCH_STATUS = 0 
begin
 WHILE @I + 1 <= @BIT
   BEGIN  
     if not exists(select * from CEKLER C1 where SERINO=@I + 1)
     begin
       INSERT INTO @GECICI (SERINO,KOCANNO)VALUES (@I + 1,@CKID)
     end
     
   END    
FETCH NEXT FROM cek INTO  @I + 1,@BIT,@CKID
end

CLOSE cek 
DEALLOCATE cek

 select B.BANKAADI,BH.HESAPADI,BH.HESAPKODU,BH.KUR,G.SERINO from @GECICI G INNER JOIN CEKKOCAN CK1 ON CK1.ID=G.KOCANNO
								 INNER JOIN KREDILER K ON CK1.KREDIID=K.ID
								  LEFT OUTER JOIN BANKAHESAPLAR BH ON BH.ID=K.BANKATICARIHESAPID
								  LEFT OUTER JOIN BANKASUBELER BS ON BS.ID=BH.BANKASUBELERID
								  LEFT OUTER JOIN BANKALAR B ON B.BANKAKODU=BS.BANKAKODU                                                        
WHERE BH.HESAPADI LIKE ''%$HESAPADI$%'' 
AND 	 coalesce( B.BANKAADI,'''') LIKE ''$BANKAADI$%''
   order by 5
' WHERE id = 1307;
UPDATE public.dokumler SET sql = '/*PGX*/-- Analist -> Fatura Özet Raporu 6-1




(
    KategoriKod   varchar(100),
	KategoriAdi   varchar(100),
    FaturaTur     varchar(50),
    GrupAdi       varchar(50), 
    IslemTur      varchar(10),
    SatisTutari   money,
    IskontoTutari money,
    IadeTutari    money,
    NetTutar      money,
	Marka		varchar(50)
)
insert into @AnaTablo (KategoriKod ,KategoriAdi,FaturaTur,GrupAdi,IslemTur,SatisTutari,IskontoTutari,IadeTutari,NetTutar,Marka)

select 
KategorıKod =CASE WHEN upper(GRUPADI) = ''BT'' THEN ''600.1.005'' 
				  WHEN upper(GRUPADI) = ''EA'' THEN ''600.1.006'' 
				  WHEN upper(GRUPADI) = ''EAYP'' THEN ''600.1.007'' 
				  WHEN upper(GRUPADI) = ''LT'' THEN ''600.1.002'' 
				  WHEN upper(GRUPADI) = ''MT'' THEN ''600.1.001'' 
				  WHEN upper(GRUPADI) = ''SW'' THEN ''600.1.003'' 
				  WHEN upper(GRUPADI) = ''SARF'' THEN ''600.1.008'' 
				  WHEN upper(GRUPADI) = ''PT'' THEN ''600.1.004'' 
				  WHEN upper(GRUPADI) = ''M'' THEN ''600.1.009''  
				  WHEN upper(GRUPADI) = ''YAĞ'' THEN ''600.1.010''
                                  WHEN upper(GRUPADI) = ''YP'' THEN ''600.1.011'' ELSE KategorıKod END, 
KATEGORIADI ,
FATURATUR,
upper(GRUPADI) as GRUPADI,
upper(ISLEMTUR) as ISLEMTUR,
Satış Tutarı   = ROUND((SUM(BIRIMFIYAT*ADET)),2),
İskonto Tutarı = ROUND((SUM(ISKONTOTUTARI)),2),
İade Tutarı    = ROUND((SUM(IADETOPLAM)),2),
Nert Tutar     = ROUND((SUM(BIRIMFIYAT*ADET) -(SUM(ISKONTOTUTARI) + SUM(IADETOPLAM))),2),
MARKA
from (

SELECT * FROM (

SELECT 

RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,
FB.FATURANO,
R.KOD AS CARIKOD,
R.FIRMA,
ISLEMTUR= CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END, 
KOD     = CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID  LIMIT 1 ) END,
AD      = CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID LIMIT 1 ) END,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
BIRIMFIYAT = CASE WHEN FB.KDVDURUM=''Hariç''  THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END,
TUTAR      = CASE WHEN FB.KDVDURUM=''Hariç''  THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END,
KDVLITOPLAM= CASE WHEN FB.KDVDURUM=''Hariç''  THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END,
ISKONTOTUTARI= (BIRIMFIYAT*ADET)-TUTAR,                                          
IADETOPLAM = CASE WHEN FB.KDVDURUM=''Hariç'' AND ((FB.TUR=8 AND FB.TIPI=1) OR (FB.TUR=11 AND FB.TIPI=2)) THEN F.TUTAR 
                  WHEN FB.KDVDURUM=''Dahil'' AND ((FB.TUR=8 AND FB.TIPI=1) OR (FB.TUR=11 AND FB.TIPI=2)) THEN F.TUTAR/(1+(F.KDV/100.0))
ELSE 0 END,
F.ISKONTO,
F.KDV,
MG.KOD AS MASRAFKODU,
MG.AD AS MASRAFADI,
KATEGORIADI= CASE WHEN F.TUR IN (1,11) THEN
			coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID) LIMIT 1 )),''Kategorisiz'')
			ELSE 
			coalesce(((SELECT MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')

			END,
KategorıKod = CASE WHEN F.TUR IN (1,11) THEN
			coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID) LIMIT 1 )),''Kategorisiz'')
			ELSE 
			coalesce(((SELECT MG1.kod FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')

			END,
GRUPADI   = CASE WHEN F.TUR IN (1,11) THEN
			coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID) LIMIT 1 )),''Grupsuz'')
			ELSE 
				''Grupsuz''

			END  ,

FB.KDVDURUM,
fb.TIPI,
MARKA=CASE WHEN F.TUR IN (1,11) THEN coalesce((SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA),''Markasız'') ELSE ''Markasız'' END

FROM 

FATBASLIK FB 
	INNER JOIN FATURA F ON 
		FB.ID=F.FATBASID 
	LEFT OUTER JOIN REHBER R ON 
		FB.REHBERID=R.ID
	LEFT OUTER JOIN MASRAFGELIR MG ON
		F.MASRAFID=MG.ID-- AND
	LEFT OUTER JOIN REHBERINI RI ON
		RI.BOLUM=''StokKart_Anabirim'' and
		RI.DEGER=F.BIRIM
	LEFT OUTER JOIN REHBERINI RI1 ON --BU EŞLEŞME GENINI DEN Mİ OLMALI ???
		RI1.BOLUM=''Kasa Türleri'' and
		RI1.DEGER=FB.TUR
        LEFT JOIN STOKLAR S ON S.ID=F.URUNID AND F.TUR=1

WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 

AND 
FB.TUR IN (8,11,12,15,16)
) AS X
WHERE     coalesce(GRUPADI,'''')     LIKE  ''$GrupAdi$%''
      AND FATURATUR   LIKE  ''%$FaturaTur$%''
      and KATEGORIADI LIKE  ''%$Kategori$%''
) AS Y
GROUP BY KategorıKod ,KATEGORIADI,FATURATUR,GRUPADI,ISLEMTUR,MARKA




select
KategoriKod ,
    KategoriAdi  ,
    FaturaTur    ,  --yeni eklenen
    GrupAdi      , 
    IslemTur     ,
    SatisTutari  ,
    IskontoTutari,
    IadeTutari   ,
    NetTutar     ,
    HizmetYuzde  = round((case when IslemTur=''HİZMET'' then NetTutar*100.0 / HizmetToplam when IslemTur=''MALZEME'' then NetTutar*100.0 / MalzemeToplam end),2),
    GenelYuzde   = round((case when IslemTur=''HİZMET'' then HizmetToplam*100.0 / GenelToplam  when IslemTur=''MALZEME'' then MalzemeToplam*100.0 / GenelToplam end),2),
	Marka
from( 

Select  
KategoriKod ,
    KategoriAdi  ,
    FaturaTur    ,
    GrupAdi      , 
    IslemTur     ,
    SatisTutari  ,
    IskontoTutari,
    IadeTutari   ,
    NetTutar     ,
    HizmetToplam   = (select sum(NetTutar) from @AnaTablo where Islemtur=''HİZMET''),
    MalzemeToplam  = (select sum(NetTutar) from @AnaTablo where Islemtur=''MALZEME''),
    GenelToplam    = (select sum(NetTutar) from @AnaTablo ) ,
	Marka

from   @AnaTablo

) as x
ORDER BY IslemTur,KategoriAdi,GrupAdi
 SET FMTONLY OFF
' WHERE id = 1310;
UPDATE public.dokumler SET sql = '/*PGX*/-- Analist -> Fatura Özet Raporu 6-1




(
    KategoriKod   varchar(100),
	KategoriAdi   varchar(100),
    FaturaTur     varchar(50),
    GrupAdi       varchar(50), 
    IslemTur      varchar(10),
    SatisTutari   money,
    IskontoTutari money,
    IadeTutari    money,
    NetTutar      money,
	Marka		varchar(50)
)
insert into @AnaTablo (KategoriKod ,KategoriAdi,FaturaTur,GrupAdi,IslemTur,SatisTutari,IskontoTutari,IadeTutari,NetTutar,Marka)

select 
KategorıKod =CASE WHEN upper(GRUPADI) = ''BT'' THEN ''600.1.005'' 
				  WHEN upper(GRUPADI) = ''EA'' THEN ''600.1.006'' 
				  WHEN upper(GRUPADI) = ''EAYP'' THEN ''600.1.007'' 
				  WHEN upper(GRUPADI) = ''LT'' THEN ''600.1.002'' 
				  WHEN upper(GRUPADI) = ''MT'' THEN ''600.1.001'' 
				  WHEN upper(GRUPADI) = ''SW'' THEN ''600.1.003'' 
				  WHEN upper(GRUPADI) = ''SARF'' THEN ''600.1.008'' 
				  WHEN upper(GRUPADI) = ''PT'' THEN ''600.1.004'' 
				  WHEN upper(GRUPADI) = ''M'' THEN ''600.1.009''  
				  WHEN upper(GRUPADI) = ''YAĞ'' THEN ''600.1.010''
                                  WHEN upper(GRUPADI) = ''YP'' THEN ''600.1.011'' ELSE KategorıKod END, 
KATEGORIADI ,
FATURATUR,
upper(GRUPADI) as GRUPADI,
upper(ISLEMTUR) as ISLEMTUR,
Satış Tutarı   = ROUND((SUM(BIRIMFIYAT*ADET)),2),
İskonto Tutarı = ROUND((SUM(ISKONTOTUTARI)),2),
İade Tutarı    = ROUND((SUM(IADETOPLAM)),2),
Nert Tutar     = ROUND((SUM(BIRIMFIYAT*ADET) -(SUM(ISKONTOTUTARI) + SUM(IADETOPLAM))),2),
MARKA
from (

SELECT * FROM (

SELECT 

RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,
FB.FATURANO,
R.KOD AS CARIKOD,
R.FIRMA,
ISLEMTUR= CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END, 
KOD     = CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID  LIMIT 1 ) END,
AD      = CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID LIMIT 1 ) END,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
BIRIMFIYAT = CASE WHEN FB.KDVDURUM=''Hariç''  THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END,
TUTAR      = CASE WHEN FB.KDVDURUM=''Hariç''  THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END,
KDVLITOPLAM= CASE WHEN FB.KDVDURUM=''Hariç''  THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END,
ISKONTOTUTARI= (BIRIMFIYAT*ADET)-TUTAR,                                          
IADETOPLAM = CASE WHEN FB.KDVDURUM=''Hariç'' AND ((FB.TUR=8 AND FB.TIPI=1) OR (FB.TUR=11 AND FB.TIPI=2)) THEN F.TUTAR 
                  WHEN FB.KDVDURUM=''Dahil'' AND ((FB.TUR=8 AND FB.TIPI=1) OR (FB.TUR=11 AND FB.TIPI=2)) THEN F.TUTAR/(1+(F.KDV/100.0))
ELSE 0 END,
F.ISKONTO,
F.KDV,
MG.KOD AS MASRAFKODU,
MG.AD AS MASRAFADI,
KATEGORIADI= CASE WHEN F.TUR IN (1,11) THEN
			coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID) LIMIT 1 )),''Kategorisiz'')
			ELSE 
			coalesce(((SELECT MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')

			END,
KategorıKod = CASE WHEN F.TUR IN (1,11) THEN
			coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID) LIMIT 1 )),''Kategorisiz'')
			ELSE 
			coalesce(((SELECT MG1.kod FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')

			END,
GRUPADI   = '''',

FB.KDVDURUM,
fb.TIPI,
MARKA=CASE WHEN F.TUR IN (1,11) THEN coalesce((SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA),''Markasız'') ELSE ''Markasız'' END

FROM 

FATBASLIK FB 
	INNER JOIN FATURA F ON 
		FB.ID=F.FATBASID 
	LEFT OUTER JOIN REHBER R ON 
		FB.REHBERID=R.ID
	LEFT OUTER JOIN MASRAFGELIR MG ON
		F.MASRAFID=MG.ID-- AND
	LEFT OUTER JOIN REHBERINI RI ON
		RI.BOLUM=''StokKart_Anabirim'' and
		RI.DEGER=F.BIRIM
	LEFT OUTER JOIN REHBERINI RI1 ON --BU EŞLEŞME GENINI DEN Mİ OLMALI ???
		RI1.BOLUM=''Kasa Türleri'' and
		RI1.DEGER=FB.TUR
        LEFT JOIN STOKLAR S ON S.ID=F.URUNID AND F.TUR=1

WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 

AND 
FB.TUR IN (8,11,12,15,16)
) AS X
WHERE     coalesce(GRUPADI,'''')     LIKE  ''$GrupAdi$%''
      AND FATURATUR   LIKE  ''%$FaturaTur$%''
      and KATEGORIADI LIKE  ''%$Kategori$%''
) AS Y
GROUP BY KategorıKod ,KATEGORIADI,FATURATUR,GRUPADI,ISLEMTUR,MARKA




select
KategoriKod ,
    KategoriAdi  ,
    FaturaTur    ,  --yeni eklenen
    GrupAdi      , 
    IslemTur     ,
    SatisTutari  ,
    IskontoTutari,
    IadeTutari   ,
    NetTutar     ,
    HizmetYuzde  = round((case when IslemTur=''HİZMET'' then NetTutar*100.0 / HizmetToplam when IslemTur=''MALZEME'' then NetTutar*100.0 / MalzemeToplam end),2),
    GenelYuzde   = round((case when IslemTur=''HİZMET'' then HizmetToplam*100.0 / GenelToplam  when IslemTur=''MALZEME'' then MalzemeToplam*100.0 / GenelToplam end),2),
	Marka
from( 

Select  
KategoriKod ,
    KategoriAdi  ,
    FaturaTur    ,
    GrupAdi      , 
    IslemTur     ,
    SatisTutari  ,
    IskontoTutari,
    IadeTutari   ,
    NetTutar     ,
    HizmetToplam   = (select sum(NetTutar) from @AnaTablo where Islemtur=''HİZMET''),
    MalzemeToplam  = (select sum(NetTutar) from @AnaTablo where Islemtur=''MALZEME''),
    GenelToplam    = (select sum(NetTutar) from @AnaTablo ) ,
	Marka

from   @AnaTablo

) as x
ORDER BY IslemTur,KategoriAdi,MARKA,GrupAdi
 SET FMTONLY OFF
' WHERE id = 1311;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT R.KOD,R.FIRMA,RK.TUTAR,RK.KUR FROM REHBER_KOTA RK INNER JOIN REHBER R ON R.ID=RK.REHBERID
WHERE R.FIRMA LIKE ''$FIRMA$%''' WHERE id = 1312;
UPDATE public.dokumler SET sql = '/*PGX*/IF EXISTS (SELECT 1 FROM tempdb..sysobjects WHERE name LIKE ''#tmp_BankaEkstre%'')
 DROP TABLE #tmp_BankaEkstre

  
 
 
 --
 --
 --


-- EXEC Sp_Prg_BankaEkstre 18305,''2015-01-01 00:00'',''2016-12-31 23:59''

BEGIN TRY
truncate table #tmp_BankaEkstre


END TRY
BEGIN CATCH
CREATE TABLE #tmp_BankaEkstre (   
       SIRANO int IDENTITY(1,1) NOT NULL,
       CEKID int NULL,
       TARIH datetime NULL,
       AKSIYONTARIH datetime NULL,
       NO varchar(20) NULL,
       TUR smallint NULL,
       BASLIK varchar(150) NULL,
       TURAD varchar(50) NULL,
       REHBERID int NULL,
       KOD varchar(20) NULL,
       AD varchar(100) NULL,
       ACIKLAMA varchar(500) NULL,
       HESAPID int NULL,
       HESAPKODU varchar(100) NULL,
       HESAPADI varchar(150) NULL,
       DURUM smallint NULL,
       BORC money NULL,
       ALACAK money NULL,
       KUR varchar(6) NULL,
       YERELKUR money NULL,
       MASRAFID int NULL,
       MASRAFKOD varchar(50) NULL,
       MASRAFAD varchar(100) NULL,
       YERELTUTAR money NULL,
       SUBEID int NULL , 
       VADETARIHI datetime NULL,
       PROJEKODU varchar(200) NULL)
END CATCH


INSERT INTO #tmp_BankaEkstre ( CEKID, TARIH, AKSIYONTARIH, NO, TUR, BASLIK, TURAD, REHBERID, KOD, AD, ACIKLAMA, HESAPID, HESAPKODU, HESAPADI, DURUM, BORC, ALACAK, KUR, YERELKUR, MASRAFID, MASRAFKOD, 
MASRAFAD, YERELTUTAR, SUBEID, VADETARIHI, PROJEKODU )

SELECT CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,
BORC=SUM(ALACAK),ALACAK=SUM(BORC), KUR, YERELKUR, MASRAFID,MASRAFKOD,MASRAFAD,YERELTUTAR,
SUBEID,VADETARIHI=NULL,PROJEKODU
FROM(

SELECT CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,
BORC=SUM(ALACAK),ALACAK=SUM(BORC), KUR, YERELKUR, MASRAFID,MASRAFKOD,MASRAFAD,YERELTUTAR,
SUBEID,VADETARIHI=NULL,PROJEKODU
FROM(
select 
       CEKID=0,TARIH=''2017-12-06 00:00'',AKSIYONTARIH=''2017-12-06 00:00'',NO=null,TUR=2,BASLIK='''',TURAD=''Ara Devir'',REHBERID=0,
       KOD = BH.HESAPKODU, AD = BH.HESAPADI, ACIKLAMA = ''Ara Devir'',HESAPID=null,HESAPKODU=null,HESAPADI=null,DURUM=1,
       BORC = K.ALACAK,
       ALACAK = K.BORC,
       K.KUR,YERELKUR=0,MASRAFID=0,MASRAFKOD='''',MASRAFAD='''',
       YERELTUTAR=
              (SELECT SUM(A) FROM (
              SELECT 
          
              A=case 
                        when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0 then -1*K1.DOVIZ_TUTARI 
                        when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0 THEN K1.DOVIZ_TUTARI 
                        when K1.TUR=88 THEN K1.DOVIZ_TUTARI --KUR FARKI
                        when K1.TUR=98 THEN -1*K1.DOVIZ_TUTARI --KUR FARKI                                         
                        else K1.ALACAK-K1.BORC  
                              end
              FROM KASA K1
              WHERE 
             BH.HESAPKODU LIKE ''$KOD$%'' AND K1.ISLEMTARIHI <= ''2017-12-06 00:00''
              And K.HESAPTURU=''B''
              ) AS S
              ),
       K.SUBEID,VADETARIHI=NULL,PROJEKODU =null
From KASA K 
left outer join REHBER R on R.ID=K.REHBERID left outer join GENINI KasaTurleri on K.TUR=KasaTurleri.DEGER AND KasaTurleri.DIL=-1 AND BOLUM=-1005 left outer join MASRAFGELIR M on M.ID=K.MASRAFID
LEFT OUTER JOIN BANKAHESAPLAR BH ON BH.ID=K.HESAPID
LEFT OUTER JOIN PROJELER P ON P.ID=K.PROJEID
Where 
       K.ISLEMTARIHI <= ''2017-12-06 00:00'' AND YEAR(K.ISLEMTARIHI) = YEAR (''2017-12-06 00:00'')
and BH.HESAPKODU LIKE ''$KOD$%'' and K.HESAPTURU=''B''
AND NOT EXISTS (SELECT ID FROM KASA K1 WHERE K1.ID=K.ID AND K1.TUR NOT IN (2) AND K.ISLEMTARIHI=K1.ISLEMTARIHI AND K1.ISLEMTARIHI>=''2017-12-06 00:00'')
       
    -- SELECT * FROM KASA   
) AS ABC
GROUP BY
CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,YERELTUTAR,
KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,SUBEID,VADETARIHI,PROJEKODU
) AS XYZ
GROUP BY
CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,YERELTUTAR,
KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,SUBEID,VADETARIHI,PROJEKODU

UNION ALL

select 
       CEKID=K.ID, K.ISLEMTARIHI AS TARIH, K.ISLEMTARIHI AS AKSIYONTARIH,BELGENO AS NO,K.TUR,'''',
       TURAD=KasaTurleri.ANAHTAR, HESAPID as REHBERID,
       KOD=case HESAPTURU
             when ''B'' then (select HESAPKODU from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
             when ''H'' then (select cast(ID as varchar(5)) from PARA_KUPON PK where PK.ID=K.HESAPID)
             when ''K'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)
             when ''P'' then (select KODU from POS P where P.ID=K.HESAPID)
             when ''R'' then (select KREDIKODU from KREDILER KR where KR.ID=K.HESAPID)
             when ''V'' then (select KODU from KREDIKARTI KK where KK.ID=K.HESAPID) end,
       AD=case HESAPTURU
             when ''B'' then (select HESAPADI from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
             when ''H'' then (select ADI from PARA_KUPON PK where PK.ID=K.HESAPID)
             when ''K'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)
             when ''P'' then (select ADI from POS P where P.ID=K.HESAPID)
             when ''R'' then (select ADI from KREDILER KR where KR.ID=K.HESAPID)
             when ''V'' then (select ADI from KREDIKARTI KK where KK.ID=K.HESAPID)
             end,
       K.ACIKLAMA, K.REHBERID as HESAPID,
       HESAPKODU = case when K.REHBERID=0 then M.KOD else R.KOD end,
       HESAPADI = case when K.REHBERID=0 then M.AD else R.FIRMA end,
       K.DURUM,
       BORC = K.ALACAK,
       ALACAK = K.BORC,
       K.KUR,
       YERELKUR = ABS((case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0 then -1*K.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0 THEN -K.DOVIZ_TUTARI else K.ALACAK-K.BORC end)/
       case when (ALACAK-BORC)=0 then 1 else 
       (ALACAK-BORC) end
       ) ,
       K.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,
       YERELTUTAR = case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0  then -1*K.DOVIZ_TUTARI 
                         when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0then K.DOVIZ_TUTARI 
                                         when K.TUR=88 THEN K.DOVIZ_TUTARI --KUR FARKI
                                        when K.TUR=98 THEN -1*K.DOVIZ_TUTARI --KUR FARKI                                         
                                        else K.ALACAK-K.BORC end,
       K.SUBEID,VADETARIHI=K.ISLEMTARIHI,P.PROJEKODU
From KASA K 
left outer join REHBER R on R.ID=K.REHBERID left outer join GENINI KasaTurleri on K.TUR=KasaTurleri.DEGER AND KasaTurleri.DIL=-1 AND BOLUM=-1005 left outer join MASRAFGELIR M on M.ID=K.MASRAFID
LEFT OUTER JOIN BANKAHESAPLAR BH ON BH.ID=K.HESAPID
LEFT OUTER JOIN PROJELER P ON P.ID=K.PROJEID
Where 
       K.ISLEMTARIHI BETWEEN ''2017-12-06 00:00'' AND ''2017-12-31 23:59''
and BH.HESAPKODU LIKE ''$KOD$%'' and K.HESAPTURU=''B''


--order by KUR,TARIH


	   ------------------------------------------------------


UNION ALL


SELECT CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,
BORC=SUM(ALACAK),ALACAK=SUM(BORC), KUR, YERELKUR, MASRAFID,MASRAFKOD,MASRAFAD,YERELTUTAR,
SUBEID,VADETARIHI=NULL,PROJEKODU
FROM(

SELECT CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,
BORC=SUM(BORC),ALACAK=SUM(ALACAK), KUR, YERELKUR, MASRAFID,MASRAFKOD,MASRAFAD,YERELTUTAR,
SUBEID,VADETARIHI=NULL,PROJEKODU
FROM(

SELECT
       CEKID=0,TARIH=''2017-12-06 00:00'',AKSIYONTARIH=''2017-12-06 00:00'',NO=null,TUR=2,BASLIK='''',TURAD=''Ara Devir'',REHBERID=0, 
       KOD=K3.KASAKODU,AD=K3.KASAADI,ACIKLAMA=''Ara Devir'',HESAPID=null,HESAPKODU=null,HESAPADI=null,DURUM=1,
       BORC=BORC,ALACAK=ALACAK,
	    K.KUR,YERELKUR=0,MASRAFID=0,MASRAFKOD='''',MASRAFAD='''',
       YERELTUTAR=
              (SELECT SUM(A) FROM (
              SELECT 
          
              A=case 
                        when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND BORC>0 then -1*K1.DOVIZ_TUTARI 
                        when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND ALACAK>0 THEN K1.DOVIZ_TUTARI 
                        when K1.TUR=88 THEN K1.DOVIZ_TUTARI --KUR FARKI
                        when K1.TUR=98 THEN -1*K1.DOVIZ_TUTARI --KUR FARKI                                         
                        else K1.ALACAK-K1.BORC  
                              end
              FROM KASA K1  
              WHERE K1.HESAPID=K3.ID and
          K3.KASAKODU LIKE ''$KOD$%'' AND K1.ISLEMTARIHI <= ''2017-12-06 00:00'' 
              and ((K1.HESAPTURU =''K'') or (K1.HESAPTURU=''B'' AND K1.KASA IN (195,196)) )
              ) AS S
              ),

      
       BORCBAKIYE=K.BORC,
       ALACAKBAKIYE=K.ALACAK,
       YERELBAKIYE = case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND BORC>0 then -1*K.DOVIZ_TUTARI 
                          when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND ALACAK>0 THEN K.DOVIZ_TUTARI 
                                         else K.ALACAK-K.BORC  end,
       K.SUBEID,VADETARIHI=K.ISLEMTARIHI ,PROJEKODU=null
 From KASA K 
  left outer join REHBER R on R.ID=K.REHBERID  left outer join GENINI KasaTurleri on K.TUR=KasaTurleri.DEGER AND KasaTurleri.DIL=-1 AND BOLUM=-1005  left outer join MASRAFGELIR M on M.ID=K.MASRAFID
	   
	   LEFT OUTER JOIN KASALAR K3 ON K.HESAPID=K3.ID
	   LEFT OUTER JOIN PROJELER P ON P.ID=K.PROJEID
Where 

       K.ISLEMTARIHI <= ''2017-12-06 00:00'' AND YEAR(K.ISLEMTARIHI) = YEAR (''2017-12-06 00:00'')
and K3.KASAKODU LIKE ''$KOD$%''
and ((K.HESAPTURU =''K'') or (K.HESAPTURU=''B'' AND KASA IN (195,196)) )
and NOT EXISTS (SELECT ID FROM KASA K1 WHERE K1.ID=K.ID AND K1.TUR NOT IN (2) AND K.ISLEMTARIHI=K1.ISLEMTARIHI AND K1.ISLEMTARIHI>=''2017-12-06 00:00'')
       



) AS X
GROUP BY
CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,YERELTUTAR,
KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,SUBEID,VADETARIHI,PROJEKODU
) AS Y
GROUP BY
CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,YERELTUTAR,
KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,SUBEID,VADETARIHI,PROJEKODU


UNION ALL

select CEKID=K.ID, K.ISLEMTARIHI AS TARIH, K.ISLEMTARIHI AS AKSIYONTARIH,BELGENO AS NO,K.TUR,'''' AS BASLIK, 
TURAD=KasaTurleri.ANAHTAR, HESAPID as REHBERID,
KOD=case HESAPTURU
when ''B'' then (select HESAPKODU from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
when ''H'' then (select cast(ID as varchar(5)) from PARA_KUPON PK where PK.ID=K.HESAPID)
when ''K'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)
when ''P'' then (select KODU from POS P where P.ID=K.HESAPID)     
when ''R'' then (select KREDIKODU from KREDILER KR where KR.ID=K.HESAPID) 
when ''V'' then (select KODU from KREDIKARTI KK where KK.ID=K.HESAPID) end,
AD=case HESAPTURU
when ''B'' then (select HESAPADI from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
when ''H'' then (select ADI from PARA_KUPON PK where PK.ID=K.HESAPID)
when ''K'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)
when ''P'' then (select ADI from POS P where P.ID=K.HESAPID)
when ''R'' then (select ADI from KREDILER KR where KR.ID=K.HESAPID)  
when ''V'' then (select ADI from KREDIKARTI KK where KK.ID=K.HESAPID)
end,
K.ACIKLAMA, K.REHBERID as HESAPID, 
 HESAPKODU = case when K.REHBERID=0 then M.KOD else R.KOD end, 
 HESAPADI = case when K.REHBERID=0 then M.AD else R.FIRMA end, 
 K.DURUM,  
 BORC      =  K.ALACAK, 
 ALACAK    =  K.BORC, 
 K.KUR,
YERELKUR  = ABS((case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND BORC>0 then -1*K.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND ALACAK>0 THEN K.DOVIZ_TUTARI else K.ALACAK-K.BORC  end)/
                      CASE WHEN ((K.ALACAK)-(K.BORC))=0 THEN 1 
                      ELSE
                      ((K.ALACAK)-(K.BORC)) END
                      ), 
 K.MASRAFID, 
 MASRAFKOD=M.KOD, MASRAFAD=M.AD,


YERELTUTAR = case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND BORC>0 then -1*K.DOVIZ_TUTARI 
                  when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND ALACAK>0 THEN K.DOVIZ_TUTARI 
                  when K.TUR=88 then K.DOVIZ_TUTARI 
                  when K.TUR=98 then -1*K.DOVIZ_TUTARI 
                  else K.ALACAK-K.BORC  end,


K.SUBEID,VADETARIHI=K.ISLEMTARIHI ,P.PROJEKODU
 From KASA K 
left outer join REHBER R on R.ID=K.REHBERID  left outer join GENINI KasaTurleri on K.TUR=KasaTurleri.DEGER AND KasaTurleri.DIL=-1 AND BOLUM=-1005  left outer join MASRAFGELIR M on M.ID=K.MASRAFID
LEFT OUTER JOIN KASALAR K3 ON K.HESAPID=K3.ID
LEFT OUTER JOIN PROJELER P ON P.ID=K.PROJEID
Where 
 --year(K.ISLEMTARIHI)>=year(''2017-12-06 00:00'') and year(K.ISLEMTARIHI)<=year(''2017-12-31 23:59'') and K.ISLEMTARIHI<=''2017-12-31 23:59''
  K.ISLEMTARIHI BETWEEN ''2017-12-06 00:00'' AND ''2017-12-31 23:59''
and K3.KASAKODU LIKE ''$KOD$%''
AND ((K.HESAPTURU =''K'') or (K.HESAPTURU=''B'' AND KASA IN (195,196)) )

UNION ALL

Select 
       CEKID=F.ID, FATURATARIH as TARIH, FATURATARIH AS AKSIYONTARIH, FATURANO as NO, F.TUR,F.BASLIK,
       TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ),
       F.REHBERID, R.KOD, R.FIRMA AS AD, F.ACIKLAMA, HESAPID=null, HESAPKODU=null, HESAPADI=null,F.DURUM,
       BORC=case when F.TUR in (13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end ,
       ALACAK=case when F.TUR in (17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end,
       KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else F.KUR end,

       YERELKUR= 
             ABS(
             (case when F.DOVIZ_CINSI=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (17) then F.DOVIZ_TUTARI when F.DOVIZ_CINSI =(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (13) then -1*F.DOVIZ_TUTARI
             when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (17) then F.FATURA_TUTARI when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (13) then -1*F.FATURA_TUTARI
             end)/
             CASE WHEN ((case when F.TUR in (13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end)-
             (case when F.TUR in (17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end))=0 THEN 1 ELSE
             ((case when F.TUR in (13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end)-
             (case when F.TUR in (17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end))
             END
             ),

       F.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,
       
       YERELTUTAR = case when F.DOVIZ_CINSI=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (17) then F.DOVIZ_TUTARI when F.DOVIZ_CINSI =(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (13) then -1*F.DOVIZ_TUTARI
       when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (17) then F.FATURA_TUTARI when F.DOVIZ_CINSI<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135 LIMIT 1 ) AND F.TUR IN (13) then -1*F.FATURA_TUTARI
       end,

       F.SUBEID, VADETARIHI=F.FATURATARIH+coalesce(F.VADE,0),P.PROJEKODU


From FATBASLIK F 
LEFT join REHBER R on F.REHBERID=R.ID and coalesce(F.DURUM,0)<>6
left outer join MASRAFGELIR M on M.ID=F.MASRAFID
LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
Where 
       F.REHBERID=0
AND F.FATURATARIH BETWEEN ''2017-12-06 00:00'' AND ''2017-12-31 23:59''
--AND F.KASA=@KasaID
AND F.TUR IN (13,17)

--) AS XYZ 
-- order by KOD,TARIH




SELECT 
       CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,
       BORC= CASE WHEN TUR=2 AND ACIKLAMA=''Ara Devir'' THEN 0 ELSE BORC END,
       ALACAK=CASE WHEN TUR=2 AND ACIKLAMA=''Ara Devir'' THEN 0 ELSE ALACAK END,
       YERELTUTAR,
       KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,SUBEID,VADETARIHI,
       CASE WHEN SUM(BORC-ALACAK) OVER (PARTITION BY KOD,AD ORDER BY KUR,SIRANO)>0 THEN SUM(BORC-ALACAK) OVER (PARTITION BY KOD,AD ORDER BY KUR,SIRANO) ELSE 0 END  AS BORCBAKIYE ,
       CASE WHEN SUM(ALACAK-BORC) OVER (PARTITION BY KOD,AD ORDER BY KUR,SIRANO)>0 THEN SUM(ALACAK-BORC) OVER (PARTITION BY KOD,AD ORDER BY KUR,SIRANO) ELSE 0 END  AS ALACAKBAKIYE ,
          YERELBAKIYE = SUM(YERELTUTAR) OVER (PARTITION BY KOD,AD ORDER BY KUR,SIRANO) ,
		  PROJEKODU
FROM #tmp_BankaEkstre A
WHERE   NOT EXISTS (SELECT CEKID FROM #tmp_BankaEkstre B WHERE B.TARIH=(SELECT TARIH FROM  #tmp_BankaEkstre C WHERE B.TARIH=C.TARIH AND C.TUR=2 AND C.CEKID=0) AND B.CEKID=A.CEKID AND B.TUR=2 AND CEKID<>0 ) 

       --AND NOT EXISTS (SELECT CEKID FROM #tmp_BankaEkstre B WHERE B.TARIH<>''2017-12-06 00:00'' AND B.CEKID=A.CEKID AND B.TUR=2 AND CEKID<>0 )

GROUP BY 
       SIRANO,CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,
       BORC,ALACAK,YERELTUTAR,KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,SUBEID,VADETARIHI,PROJEKODU

order by KOD,AD, KUR,TARIH



-- EXEC Sp_Prg_KasaNakitEkstre 103,''2016-01-21 00:00'',''2016-12-31 23:59''
-- SELECT CASE WHEN SUM(BORC-ALACAK)>0 THEN ABS(SUM(B.BORC-B.ALACAK)) ELSE 0 END FROM #tmp_KasaNakitEkstre AS B WHERE B.SIRANO <= A.SIRANO AND B.KUR=A.KUR AND B.TUR NOT IN (88,98)
' WHERE id = 1313;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
STOKID,S.KOD,S.STOKADI,D.DEPOADI,IZLEM,K.AD,X.ACIKLAMA,SUM(CASE WHEN TUR=''G'' THEN MIKTAR ELSE 0.0 END) AS GIREN ,
SUM(CASE WHEN TUR=''C'' THEN MIKTAR ELSE 0.0 END) AS CIKAN ,SUM(MIKTAR)
 AS KALAN FROM
	(SELECT STOKID,CIKISDEPO AS DEPO ,-MIKTAR AS MIKTAR ,IZLEM,ACIKLAMA,''C''
	 AS TUR FROM STOKIZLEME SI
	WHERE CIKISDEPO >0 AND DURUM=1 
	UNION ALL
	SELECT STOKID,GIRISDEPO AS DEPO ,MIKTAR,IZLEM,ACIKLAMA ,''G''
	 AS TUR FROM STOKIZLEME 
	WHERE GIRISDEPO >0 AND DURUM=1 
	)AS X INNER JOIN STOKLAR S ON X.STOKID=S.ID
		  LEFT OUTER JOIN KATEGORI K ON S.KATEGORI=K.ID
		  INNER JOIN DEPOLAR D ON D.ID=X.DEPO
 where S.KOD LIKE ''$StokKod$%''
AND D.DEPOADI  LIKE ''$DepoAdi$%''
AND K.AD  LIKE ''$Kategori$%''
GROUP BY S.KOD,S.STOKADI,STOKID,D.DEPOADI,IZLEM,X.ACIKLAMA,K.AD
HAVING SUM(MIKTAR)<>0.0' WHERE id = 1314;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT C.VADE,C.TUTAR,C.BORCLU,R1.KOD AS CARİ KOD,R1.FIRMA AS CARİ ADI,C.HESAPNO,G.ANAHTAR AS DURUM,C.SERINO AS ÇEK NO,
REFERANS TARİH =CH.TARIH,C.MAKBUZNO AS EVRAK NO,C.KOD ASHESAP KODU ,B.BANKAADI,BS.SUBEADI ,C.EKLEMETARIHI

FROM CEKLER C
  inner join CEKHAREKET CH on CH.ID=(select CH1.ID from CEKHAREKET CH1 where CH1.CEKSENETLERID=C.ID order by CH1.TARIH desc LIMIT 1 )
    INNER JOIN GENINI G ON C.TUR=G.DEGER 
  left outer join REHBER R1 ON C.REHBERID=R1.ID
  left outer join BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
  left outer join BANKALAR B ON B.BANKAKODU = BS.BANKAKODU
  left outer join REHBER R2 on CH.REHBERID=R2.ID
  left outer join BANKAHESAPLAR BHSON on CH.BANKAHESAPLARID=BHSON.ID
  left outer join BANKAHESAPLAR BH2 on C.HESAPID=BH2.ID
Where 1=1    AND C.CEKSENET=121
 and CH.ISLEM in (0,130,131,132,138,133,134,135,136,137)   AND G.BOLUM=-1005
AND    G.ANAHTAR LIKE ''$Durum$%'' AND
         VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND 1=case 
       when C.TUR<>136 then 1
       when (C.TUR=136)and(''Tahsil edilmişleri de listele''=''$Tur$'') then 1 
       else 0 end' WHERE id = 1315;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT R1.KOD AS CARİ KOD,R1.FIRMA AS CARİ ADI,C.BORCLU,C.KOD ASHESAP KODU , B.BANKAADI,BS.SUBEADI ,C.HESAPNO AS ÇEK HESAP NO,
C.SERINO AS ÇEK SERİ NO, C.TUTAR,C.KUR,C.VADE,G.ANAHTAR AS DURUM,case when coalesce(R2.FIRMA,''-'')<>''-'' then R2.FIRMA else BHSON.HESAPADI end  AS SONISLEMYERI ,

REFERANS TARİH =CH.TARIH,C.MAKBUZNO AS EVRAK NO,CH.TARIH

 AS EKLEMETARIHI FROM CEKLER C
  inner join CEKHAREKET CH on CH.ID=(select CH1.ID from CEKHAREKET CH1 where CH1.CEKSENETLERID=C.ID order by CH1.TARIH desc LIMIT 1 )
    INNER JOIN GENINI G ON C.TUR=G.DEGER 
  left outer join REHBER R1 ON C.REHBERID=R1.ID
  left outer join BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
  left outer join BANKALAR B ON B.BANKAKODU = BS.BANKAKODU
  left outer join REHBER R2 on CH.REHBERID=R2.ID
  left outer join BANKAHESAPLAR BHSON on CH.BANKAHESAPLARID=BHSON.ID
  left outer join BANKAHESAPLAR BH2 on C.HESAPID=BH2.ID
Where 1=1    AND C.CEKSENET=121
 and CH.ISLEM in (0,130,131,132,138,133,134,135,136,137)   AND G.BOLUM=-1005
AND    G.ANAHTAR LIKE ''$Durum$%'' AND
         VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND 1=case 
       when C.TUR<>136 then 1
       when (C.TUR=136)and(''Tahsil edilmişleri de listele''=''$Tur$'') then 1 
       else 0 end
ORDER BY  c.kur  , C.VADE' WHERE id = 1316;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                             
 VADE,TUTAR,BORCLU,CARIKODU,CARIADI,HESAPNO,X.DURUM,CEKNO,REFERANS TARİHİ,EVRAK NO,X.HESAPKODU,HP.HESAPADI,BANKAADI,SUBEADI
 
FROM (
SELECT C.VADE,C.TUTAR,coalesce(C.BORCLU,'''') as BORCLU,R.KOD AS CARIKODU,R.FIRMA AS CARIADI,C.HESAPNO,C.SERINO AS CEKNO,C.TARIH
 AS REFERANS TARİHİ,C.MAKBUZNO AS EVRAK NO,
 REVERSE( SUBSTRING(REVERSE(C.KOD),CHARINDEX(''.'',REVERSE(C.KOD),1)+1,length(C.KOD)-(CHARINDEX(''.'',REVERSE(C.KOD),1)-1))) AS HESAPKODU ,
 BN.BANKAADI,BS.SUBEADI,G.ANAHTAR AS DURUM

 FROM CEKLER C INNER JOIN BANKASUBELER BS ON C.BANKASUBELERID=BS.ID     
 INNER JOIN BANKALAR BN ON BN.BANKAKODU=BS.BANKAKODU INNER JOIN REHBER R ON R.ID=C.REHBERID 
 INNER JOIN GENINI G ON C.DURUM=G.DEGER AND G.BOLUM=''-2602'' AND DIL=-1
 WHERE C.TUR=33  AND C.CEKSENET=321
 ) AS X INNER JOIN HESAPPLANI HP ON X.HESAPKODU=HP.HESAPKODU 
 where
	X.DURUM LIKE ''$Durum$%'' AND
	VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''' WHERE id = 1317;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT CARİ KOD = R1.KOD,CARİ ADI=R1.FIRMA,C.KOD ASHESAP KODU,B.BANKAADI AS BANKA ADI,BS.SUBEADI as ŞUBE ADI,C.HESAPNO AS ÇEK HESAP NO,
C.SERINO AS ÇEK SERİ NO,C.TUTAR,C.KUR,C.VADE

FROM CEKLER C
  inner join CEKHAREKET CH on CH.ID=(select CH1.ID from CEKHAREKET CH1 where CH1.CEKSENETLERID=C.ID order by CH1.TARIH desc LIMIT 1 )
   INNER JOIN GENINI G ON C.TUR=G.DEGER
  left outer join REHBER R1 ON C.REHBERID=R1.ID
  left outer join BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
  left outer join BANKALAR B ON B.BANKAKODU = BS.BANKAKODU
  left outer join REHBER R2 on CH.REHBERID=R2.ID
  left outer join BANKAHESAPLAR BHSON on CH.BANKAHESAPLARID=BHSON.ID
  left outer join BANKAHESAPLAR BH2 on C.HESAPID=BH2.ID
 Where 1=1   AND C.CEKSENET=321
 and CH.ISLEM in (0,140,141,142,143) 
 AND G.BOLUM=-1005
AND    G.ANAHTAR LIKE ''$Durum$%'' 
AND coalesce(B.BANKAADI,'''') LIKE ''%$BANKAADI$%''
AND    VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
ORDER BY c.kur,C.VADE' WHERE id = 1318;
UPDATE public.dokumler SET sql = '/*PGX*/





select 
       C.ID,C.TARIH AS CEKTARIH ,C.VADE,CH.TARIH AS SONHAREKETTARIH ,
       (select I.AD from ISLEMTURLERI I where I.TUR=CH.ISLEM) AS HAREKETTUR ,
       C.SERINO,CH.ACIKLAMA,R.FIRMA,C.TUTAR,C.KUR,CH.DOVIZ_TUTARI,CH.DOVIZ_KURU,C.ACIKLAMA,G.ANAHTAR
from 
       CEKLER C inner join 
       (select RANK() OVER (PARTITION BY CEKSENETLERID ORDER BY TARIH DESC,ID DESC) AS rnk ,* from CEKHAREKET where TARIH<=''$Bitis$ 23:59:59'') CH on C.ID=CH.CEKSENETLERID and rnk=1 inner join 
       REHBER R on R.ID=C.REHBERID inner join
       HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM left outer join 
       GENINI G on G.BOLUM=-1005 and CH.ISLEM=G.DEGER and G.DIL=-1
where H.HESAPKODU like ''$Hesapkodu$''||''%'' and C.TARIH <= ''$Bitis$ 23:59:59''  AND C.CEKSENET IN (121,321)
 
order by 4
' WHERE id = 1319;
UPDATE public.dokumler SET sql = '/*PGX*/select R.KOD,R.FIRMA,E.AD,ER.SERINO 
from EKIPMANREHBER ER inner join REHBER R on ER.REHBERID=R.ID inner join EKIPMANLAR E on E.ID=ER.EKIPMANID

where ER.SERINO in (SELECT SERINO FROM EKIPMANREHBER group by SERINO,EKIPMANID having count(*)>1)
order by 4' WHERE id = 1320;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT ST.KOD,ST.STOKADI,P.PROJEKODU,SiparisDetay.MIKTAR,R1.FIRMA AS TALEPEDEN,TalepBaslik.TARIH AS TALEPTARIHI
,TalepDetay.TESLIMTARIHI AS TALTESLIMTARIH,R.FIRMA,R2.FIRMA AS SIPARISVEREN,Siparis.TARIH AS SIPTARIH,
SiparisDetay.TESLIMTARIHI AS SIPTESLITARIH
,cast((SiparisDetay.TESLIMTARIHI-TalepDetay.TESLIMTARIHI) as integer)
 AS FARK2 FROM 
       SIPARIS TalepBaslik inner JOIN 
       SIPARISDETAY TalepDetay ON TalepBaslik.ID=TalepDetay.SIPARISID inner JOIN 
       SIPARISDETAY SiparisDetay ON TalepDetay.ID=SiparisDetay.YERID AND SiparisDetay.YERI=428 inner join
       SIPARIS Siparis on Siparis.ID=SiparisDetay.SIPARISID

               LEFT OUTER JOIN REHBER R ON R.ID=Siparis.REHBERID
               LEFT OUTER JOIN STOKLAR ST ON ST.ID=SiparisDetay.URUNID
               LEFT OUTER JOIN PROJELER P ON P.ID=SiparisDetay.PROJEID
               LEFT OUTER JOIN REHBER R1 ON R1.ID=Siparis.SATICIKODU
               LEFT OUTER JOIN REHBER R2 ON R2.ID=TalepBaslik.SATICIKODU
WHERE  TalepBaslik.TUR=101' WHERE id = 1321;
UPDATE public.dokumler SET sql = '/*PGX*/select   R.KOD, R.FIRMA, 
 R2.FIRMA AS TEMSILCIAD , X.BILGI AS ILLER , 
   (SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=2 LIMIT 1 ) AS ADRES , 
   (SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,  
    (SELECT KONUSU FROM GOREVLER A WHERE A.REHBERID=R.ID ORDER BY BITISTARIHI DESC    LIMIT 1 )  AS SONISKONUSU ,
     (SELECT to_char((BITISTARIHI),''MM/DD/YYYY'') AS BITISTARIHI FROM GOREVLER A  WHERE  A.REHBERID =R.ID  ORDER BY BITISTARIHI DESC LIMIT 1 )  AS SONISTARIHI ,
    (SELECT to_char((FATURATARIH),''DD/MM/YYYY'') as FATURATARIH FROM FATBASLIK F  WHERE  F.TUR  in (10,11,12,14,15,16) and F.REHBERID =R.ID  ORDER BY FATURATARIH DESC LIMIT 1 )   AS SONSATBELGETARIHI ,
    (SELECT FATURA_TUTARI FROM FATBASLIK F  WHERE  F.TUR  in (10,11,12,14,15,16) and
	 F.REHBERID =R.ID  ORDER BY FATURATARIH DESC  LIMIT 1 ) AS SONSATTUTARI ,
 (SELECT to_char((TARIH),''DD/MM/YYYY'') as TEKLIFTARIH FROM TEKLIF T WHERE   T.REHBERID =R.ID  ORDER BY TARIH DESC LIMIT 1 )  AS SONTEKLIFTARIHI ,
  (SELECT R3.FIRMA FROM GOREVLER G INNER JOIN REHBER R3 ON G.EKLEYEN=R3.ID WHERE G.REHBERID=R.ID ORDER BY BITISTARIHI DESC   LIMIT 1 ) AS SONISYAPAN ,
(SELECT R.DEGISTIRMETARIHI FROM REHBER R4 WHERE   R4.ID =R.ID   LIMIT 1 )   AS SONGUNCELLEMETARIH ,
  (SELECT R3.FIRMA FROM REHBER R5 INNER JOIN REHBER R3 ON R5.DEGISTIREN=R3.ID WHERE R5.ID=R.ID    LIMIT 1 )
 
	   AS SONGUNCELLEMEYAPAN from 
    REHBER R 
 left outer join REHBER R2 on R2.ID=R.TEMSILCI 
  left outer join (Select R1.ID,RB.BILGI from REHBER R1 left outer join REHBERILETISIM RI on R1.ID=RI.REHBERID and RI.VARSAYILAN=1 Left outer join REHBERBILGI RB on RB.YER_ID=RI.ID  left outer join REHBERAYAR RA on RA.SIRA=RB.SIRA AND RA.YERI=1 Where RI.VARSAYILAN=1 and RB.YERI=1 and RA.VARSAYILAN=8
  ) X on X.ID=R.ID   where R.GRUP<>334 and R.GRUP<>335 and R.ID > 1 
 and R.DURUM> 0 
 and R.SUBEID in(0,-6,-5,-4,-3,-2,-1) 
 and R.GRUP > 1 
 and R.GRUP <> 334 order by 1' WHERE id = 1322;
UPDATE public.dokumler SET sql = '/*PGX*/
   

select KOD,AD,
Ocak     =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=1 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Şubat          =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=2 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Mart      =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=3 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Nisan          =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=4 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Mayıs          =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=5 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Haziran   =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=6 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Temmuz    =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=7 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Ağustos   =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=8 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Eylül          =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=9 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Ekim      =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=10 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Kasım     =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=11 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Aralık    =sum(cast(coalesce(case when MONTH(X.FATURATARIH)=12 and X.FATURATARIH BETWEEN @Baslama AND @Bitis then X.TUTAR else 0.0 end,0.0) as money)),
Toplam    =sum(cast(coalesce(CASE WHEN  X.FATURATARIH BETWEEN @Baslama AND @Bitis THEN X.TUTAR ELSE 0.0 END,0.0) as money))

from (

             SELECT 
                    MG1.KOD,MG1.AD,
                    P1.PROJEKODU AS PROJE ,FT.FATURATARIH,
                    CASE WHEN FT.KDVDURUM=''Dahil'' THEN F1.TUTAR ELSE F1.BIRIMFIYAT*F1.ADET*(1+(F1.KDV/100.0))END
              AS TUTAR FROM 
                    FATURA F1 INNER JOIN 
                    FATBASLIK FT ON F1.FATBASID=FT.ID left outer join
                    MASRAFGELIR MG1 on F1.MASRAFID=MG1.ID left outer join
                    PROJELER P1 on F1.PROJEID=P1.ID 
             WHERE 
                    FT.TARIH BETWEEN @Baslama AND @Bitis AND 
                    coalesce(P1.PROJEKODU,'''') like ''%''||@Projekod||''%'' and
                    FT.TUR in (11,12) 

             union all

             SELECT  
                    MG1.KOD,MG1.AD,
                    P1.PROJEKODU AS PROJE ,FT.FATURATARIH,
                    FATURA_TUTARI
              AS TUTAR FROM 
                    FATBASLIK FT left outer join
                    MASRAFGELIR MG1 on FT.MASRAFID=MG1.ID left outer join
                    PROJELER P1 on FT.PROJEID=P1.ID 
             WHERE 
                    FT.FATURATARIH BETWEEN @Baslama AND @Bitis AND 
                    coalesce(P1.PROJEKODU,'''') like ''%''||@Projekod||''%'' and
                    FT.TUR=13 
) as X

group by KOD,AD
order by KOD,AD
' WHERE id = 1326;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
FB.ID,FB.FATURATARIH,FB.FATURANO,R.KOD,S.KOD,S.STOKADI,FB.ACIKLAMA,F.MIKTAR,G.ANAHTAR,
(SELECT FIRMA FROM REHBER R1 WHERE FB.SATICIKODU=R1.ID) AS TESLIM_EDEN ,R.FIRMA AS TESLIM_ALAN,
P.PROJEKODU,P.PROJEADI,
D.DEPOADI AS GIRISDEPO,D1.DEPOADI AS CIKISDEPO


FROM FATBASLIK FB 
INNER JOIN FATURA F ON FB.ID=F.FATBASID 
INNER JOIN STOKLAR S ON F.URUNID=S.ID
INNER JOIN REHBER R ON R.ID=FB.REHBERID
LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
INNER JOIN GENINI G ON F.BIRIM=G.DEGER AND G.BOLUM=-2702 AND G.DIL=-1
INNER JOIN DEPOLAR D ON D.ID=FB.GIRISDEPO
INNER JOIN DEPOLAR D1 ON D1.ID=FB.CIKISDEPO
WHERE FB.TUR=20  AND
FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''' WHERE id = 1329;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT	TARIH,SERVISNO,FIRMA,KONUSU,MUS_ILGILI,AD,SERINO,PERSONEL,MUDAHALETUR,
SEYAHATBAS,
SERVISBAS,
SERVISBIT,
SEYAHATBIT,
(DATEDIFF(MINUTE,SEYAHATBAS,SERVISBAS)+DATEDIFF(MINUTE,SERVISBIT,SEYAHATBIT)-DATEDIFF(MINUTE,SMOLABAS,SMOLABIT))/60.0 AS SEYAHATSURESI ,
(DATEDIFF(MINUTE,SERVISBAS,SERVISBIT)-DATEDIFF(MINUTE,MOLABAS,MOLABIT))/60.0 AS TOPLAM_MESAI_SURESI ,
CASE WHEN DATEPART(WEEKDAY,SERVISBAS)=7 THEN DATEDIFF(MINUTE,SERVISBAS,SERVISBIT)/60.0 ELSE 0.0 END AS CMT_MESAI_SURESI ,
CASE WHEN DATEPART(WEEKDAY,SERVISBAS)=1 THEN DATEDIFF(MINUTE,SERVISBAS,SERVISBIT)/60.0 ELSE 0.0 END AS PZR_MESAI_SURESI ,
CASE WHEN DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6) 
						THEN (DATEDIFF(MINUTE,SERVISBAS,(CASE 
												WHEN DATEPART(HOUR,SERVISBIT)>=18 
												THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) 
												ELSE SERVISBIT
												END))-DATEDIFF(MINUTE,MOLABAS,MOLABIT))/60.0 
						ELSE 0.0 END AS NORMAL_MESAI_SURESI ,
CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) AND (DATEPART(HOUR,SERVISBIT)>=18)
						THEN (DATEDIFF(MINUTE,DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0),
						SERVISBIT)/60.0 )
						ELSE 0.0 END AS FAZLA_MESAI_SURESI ,
						CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) AND (DATEPART(HOUR,SERVISBIT)>=18)
						THEN (DATEDIFF(MINUTE,DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0),
						SERVISBIT) )
						ELSE 0.0 END AS FAZLA_MESAI_SURESI1 ,
 DATEDIFF(MINUTE,MOLABAS,MOLABIT) /60.0   AS MOLA_SURESI ,
DATEDIFF(MINUTE,SMOLABAS,SMOLABIT) /60.0
 AS SMOLA_SURESI FROM (
		SELECT 
		S.TARIH,S.SERVISNO,R.FIRMA,S.KONUSU,R1.FIRMA AS MUS_ILGILI ,E.AD,S.SERINO,R2.FIRMA AS PERSONEL ,
		(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=40 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SEYAHATBAS ,
		(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=5 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SERVISBAS ,
		(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=5 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SERVISBIT ,
		(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=42 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SEYAHATBIT ,
		(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=44 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS MOLABAS ,
		(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=44 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS MOLABIT ,
		(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=46 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SMOLABAS ,
		(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=46 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SMOLABIT ,
		G1.ANAHTAR AS MUDAHALETUR
                
                	FROM SERVIS S 
							   INNER JOIN (SELECT DISTINCT SERVISID,PERSONEL,ACIKLAMA FROM SERVISHAREKET WHERE DURUM <> 1 and DURUM <> 47 and DURUM <> 48 and DURUM <> 49) SH ON SH.SERVISID=S.ID
							   INNER JOIN EKIPMANREHBER ER ON ER.ID=S.EKIPMANREHBERID
							   INNER JOIN EKIPMANLAR E ON E.ID=S.EKIPMANID
							   INNER JOIN REHBER R ON R.ID=S.REHBERID
							   INNER JOIN REHBER R1 ON R1.ID=S.MUS_ILGILI
							   INNER JOIN REHBER R2 ON R2.ID=SH.PERSONEL
							   INNER JOIN GENINI G1 ON S.TURU=G1.DEGER AND G1.BOLUM=-3006  
		WHERE  S.TARIH>=''$Baslangic$ 00:00:00'' AND
S.TARIH<=''$Bitis$ 23:59:00''
) AS XXX

ORDER BY TARIH' WHERE id = 1330;
UPDATE public.dokumler SET sql = '/*PGX*/
''$Bitis$ 23:00'' DATETIME





--with---------------------------------------------------------------------------------------------------------------
with  BORC_ALACAK (REHBERID, TOPLAM_BORC, TOPLAM_ALACAK, KUR) as  
(select	
		REHBERID,TOPLAM_BORC=SUM(coalesce(BORC,0)),TOPLAM_ALACAK=SUM(coalesce(ALACAK,0)),KUR=coalesce(KUR,''TL'')
	from (
--FATURA----------------------------------------------------------------------------------------------------------	   
			   SELECT --FATURA BORÇLAR
					REHBERID,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,0 AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_CINSI else KUR end as KUR 
				FROM FATBASLIK F
				WHERE (F.TUR between 15 and 17) AND FATURATARIH >= ''$Baslangic$ 00:00'' and FATURATARIH<=''$Bitis$ 23:00'' and REHBERID>0
				GROUP BY F.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_CINSI else KUR end
			UNION ALL
				SELECT --FATURA ALACAKLAR
					REHBERID,0 AS BORC,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_CINSI else KUR end as KUR 
				FROM FATBASLIK F
				WHERE (F.TUR in (8,11,12,13)) AND FATURATARIH >= ''$Baslangic$ 00:00'' and FATURATARIH<=''$Bitis$ 23:00'' and REHBERID>0 
				GROUP BY F.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_CINSI else KUR end
			UNION ALL
				SELECT --KASA
					REHBERID,
					SUM(case when coalesce(K.BORC,0)>0 and coalesce(K.DOVIZ_TUTARI,0)>1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
					SUM(case when coalesce(K.ALACAK,0)>0 and coalesce(K.DOVIZ_TUTARI,0)>1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM KASA K  
				WHERE TUR IN (1,2,13,17,21,22,25,31,32,35,49)  AND ISLEMTARIHI >= ''$Baslangic$ 00:00'' and ISLEMTARIHI<=''$Bitis$ 23:00'' and REHBERID>0   
				GROUP BY K.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end
			UNION ALL
				SELECT --ÇEK ALACAKLAR
					REHBERID,0 AS BORC ,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END ) AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM CEKLER C
				WHERE TUR = 23   AND TARIH >= ''$Baslangic$ 00:00'' and TARIH<=''$Bitis$ 23:00'' and REHBERID>0   
				GROUP BY C.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1  THEN DOVIZ_KURU else KUR end
			UNION ALL
				SELECT --ÇEK BORÇLAR
					REHBERID,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS BORC,0 AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM CEKLER C
				WHERE TUR = 33  AND TARIH >= ''$Baslangic$ 00:00''  and TARIH<=''$Bitis$ 23:00'' and REHBERID>0    
				GROUP BY C.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end
			UNION ALL
				SELECT --Çek Ciro
					REHBERID,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS BORC,0 AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				From CEKLER C inner join REHBER R on C.REHBERID=R.ID
				WHERE TUR = 23  AND TARIH >= ''$Baslangic$ 00:00''  and TARIH<=''$Bitis$ 23:00'' AND coalesce(C.CIROLU,0)=1 and REHBERID>0 
				GROUP BY C.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end
			UNION ALL
				SELECT --Çek İade
					REHBERID,0 AS BORC ,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END ) AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM CEKLER C
				WHERE TUR = 33 AND C.DURUM=12 AND TARIH >= ''$Baslangic$ 00:00''  and TARIH<=''$Bitis$ 23:00'' and REHBERID>0   
				GROUP BY C.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1  THEN DOVIZ_KURU else KUR end
			UNION ALL
				SELECT --Çek İade
					REHBERID,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS BORC,0 AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM CEKLER C
				WHERE TUR = 23 AND C.DURUM=12 AND TARIH >= ''$Baslangic$ 00:00''   and TARIH<=''$Bitis$ 23:00'' and REHBERID>0   
				GROUP BY C.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end
			UNION ALL
				SELECT --SENET ALACAK
					REHBERID,0 AS BORC,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
					CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM SENETLER S
				WHERE TUR = 24   AND TARIH >= ''$Baslangic$ 00:00'' and TARIH<=''$Bitis$ 23:00'' and REHBERID>0   
				GROUP BY S.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR END
			UNION ALL
				SELECT --SENET BORÇ
					REHBERID,SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS 
					BORC,0 AS ALACAK,
				CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end as KUR 
				FROM SENETLER S
				WHERE TUR = 34  AND TARIH >= ''$Baslangic$ 00:00'' and REHBERID>0
				GROUP BY S.REHBERID,CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end
-----------------------------------------------------------------------------------------------------------------------
		) as asd group by REHBERID,KUR)
--with son-------------------------------------------------------------------------------------------------------------


--Satış Kurundan Hesap-------------------------------------------------------------------------------------------------
SELECT X.*,D.SATIS,CASE WHEN KUR=''TL'' THEN X.BAKIYE ELSE BAKIYE*SATIS END AS TL_BAKIYE FROM (

--AKTİFLER KASA--------------------------------------------------------------------------------------------------------
--Kontrol edildi tutarla programla aynı
-----------------------------------------------------------------------------------------------------------------------
SELECT ''AKTİFLER'' AS ANAGRUBU,''100 Kasa Hesabı'' AS HESAP,KASAADI AS GRUP,SUM(BORC-ALACAK)*-1 AS BAKIYE,KUR FROM
(SELECT 
 KS.ID,
 --RI2.ANAHTAR AS TUR,R.KOD AS CARIKOD,R.FIRMA AS CARIAD,
 KS.KASAKODU,
 KS.KASAADI,
 coalesce(K.ALACAK,0) AS ALACAK,
 coalesce(K.BORC,0) AS  BORC,
 KS.KUR 
 FROM KASA K 
LEFT OUTER JOIN REHBER R ON K.REHBERID=R.ID
LEFT OUTER JOIN KASALAR KS ON K.HESAPID=KS.ID AND K.HESAPTURU=''K''
LEFT OUTER JOIN REHBERINI RI2 ON RI2.BOLUM =''Kasa Türleri'' AND RI2.DEGER=K.TUR
  
WHERE 
     ISLEMTARIHI >=  ''$Baslangic$ 00:00'' AND        
     ISLEMTARIHI <=  ''$Bitis$ 23:00'' 
     AND coalesce(KS.KASAKODU,'''')<>'''') AS KASA    
     GROUP BY ID,KASAADI,KUR --ORDER BY ID,KASAADI,KUR
-----------------------------------------------------------------------------------------------------------------------     
UNION ALL 

--AKTİFLER BANKALAR---------------------------------------------------------------------------------------------------- 
--Ödeme palanları dahil değildir (Kontrol edildi ödeme farkı dışında programla arasında bir fark yok)
-----------------------------------------------------------------------------------------------------------------------
SELECT ANAGRUBU,HESAP,GRUP,CASE WHEN BAKIYE<0 THEN BAKIYE*-1 ELSE BAKIYE END AS BAKIYE,KUR FROM (
SELECT ''AKTİFLER'' AS ANAGRUBU, ''102 Bankalar Hesabı'' AS HESAP,HESAPADI AS GRUP,SUM(BORC-ALACAK) AS BAKIYE,KUR FROM
(SELECT
BH.ID,
 --ISLEMTARIHI,
 --RI2.ANAHTAR AS TUR,
 --R.KOD AS CARIKOD,
 --R.FIRMA AS CARIAD,
 BH.HESAPKODU,
 BH.HESAPADI,
 --KS.KASAADI,
 coalesce(K.ALACAK,0) AS ALACAK,
 coalesce(K.BORC,0) AS  BORC,
 BH.KUR 
 FROM KASA K 
--LEFT OUTER JOIN REHBER R ON K.REHBERID=R.ID
LEFT OUTER JOIN BANKAHESAPLAR BH ON K.HESAPID=BH.ID AND K.HESAPTURU=''B''
LEFT OUTER JOIN REHBERINI RI2 ON RI2.BOLUM =''Kasa Türleri'' AND RI2.DEGER=K.TUR
WHERE 
     ISLEMTARIHI >=  ''$Baslangic$ 00:00'' AND        
     ISLEMTARIHI <=  ''$Bitis$ 23:00'' AND TUR<>71 AND TUR<>61 AND
     coalesce(HESAPKODU,'''')<>'''') AS BANKA  
     GROUP BY ID,HESAPADI,KUR
) BANKA     
-----------------------------------------------------------------------------------------------------------------------------------     
 UNION ALL
--AKTİFLER ALICILAR----------------------------------------------------------------------------------------------------------------


    SELECT ''AKTİFLER''  AS ANAGRUBU ,''Alıcılar''  as HESAP,''''  AS GRUP,BAKIYE=SUM(TOPLAM_BORC-TOPLAM_ALACAK),KUR  FROM BORC_ALACAK DSA
    INNER JOIN REHBER R ON DSA.REHBERID=R.ID 
    where 1=1  and DURUM=1 and R.GRUP <>''400'' and  coalesce(R.ID,'''')<>'''' and (coalesce(TOPLAM_BORC,0) - coalesce(TOPLAM_ALACAK,0)) > 1.0
    GROUP BY KUR 

------------------------------------------------------------------------------------------------------------------------------------
UNION ALL
--AKTİFLER ÇEKLER Durumu portföyde olanlar alındı-----------------------------------------------------------------------------------

SELECT 
''AKTİFLER''  AS ANAGRUBU ,''Alınan Çekler''  as HESAP,''''  AS GRUP,
SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS BAKIYE, 
(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end) as KUR
FROM CEKLER WHERE DURUM=1 AND TUR=23 AND TARIH >=''$Baslangic$ 00:00'' AND TARIH <=''$Bitis$ 23:00''  
GROUP BY (CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end)
------------------------------------------------------------------------------------------------------------------------------------
UNION ALL
--ALINAN SENETLER-------------------------------------------------------------------------------------------------------------------

SELECT ''AKTİFLER''  AS ANAGRUBU ,''Alınan Senetler''  as HESAP,''''  AS GRUP,
SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS BAKIYE, 
(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end) as KUR
FROM SENETLER WHERE TUR=24 AND TARIH >=''$Baslangic$ 00:00'' AND TARIH <=''$Bitis$ 23:00'' 
GROUP BY (CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end)
------------------------------------------------------------------------------------------------------------------------------------
UNION ALL 
--AKTİFLER STOK---------------------------------------------------------------------------------------------------------------------
SELECT ''AKTİFLER'' AS ANAGRUBU,''Stok'' AS HESAP,'''' AS GRUP,SUM(coalesce(MIKTAR_TUTAR,0)*GIREN) AS BAKIYE,''TL'' AS KUR FROM 
 (SELECT X.KOD,S.ID,X.STOKADI,SUM(MIKTAR) AS GIREN,R.ANAHTAR FROM 
                                              
                                              (SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, 19 AS TUR, S.ID AS FATBASID, SK.STOKID AS URUNID,STOK.KOD, STOK.STOKADI, SK.SAYIMMIKTAR AS MIKTAR, 
                                                                      SK.SAYIMMIKTAR AS ADET, STOK.ANABIRIM, S.SAYIMDEPO AS GIRISDEPO, 
                                                                      GIRDEPO.DEPOADI AS GIRDEPO, 0 AS CIKISDEPO, '''' AS CIKDEPO, GIRDEPO.ID AS STOKDEPOID, GIRDEPO.DEPOADI AS STOKDEPO, 
                                                                      coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, S.SAYIMTARIHI AS HAREKETTARIH
                                               FROM          STOKSAYIM AS S INNER JOIN
                                                                      STOKSAYIMKALEMLERI AS SK ON S.ID = SK.SAYIMID INNER JOIN
                                                                      STOKLAR AS STOK ON SK.STOKID = STOK.ID INNER JOIN
                                                                      DEPOLAR AS GIRDEPO ON GIRDEPO.ID = S.SAYIMDEPO AND GIRDEPO.SONSAYIMTARIHI = S.SAYIMTARIHI  
                                                                                                          
                                               WHERE      (S.SAYIMONAY = 1) AND coalesce(GIRDEPO.SONSAYIMTARIHI,''1900-01-01'') <=''$Bitis$ 23:00''   
                                               UNION ALL
                                               SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI, F.MIKTAR, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, GIRDEPO.ID AS STOKDEPOID, 
                                                                     GIRDEPO.DEPOADI AS STOKDEPO, coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID
                                               WHERE     (F.TUR = 1) AND (FB.TARIH > coalesce(GIRDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND (FB.TUR IN (10, 11, 12, 19)) AND FB.TARIH < ''$Bitis$ 23:00''  
                                               UNION ALL
                                               SELECT     ''Devir'' AS HAREKET,NULL AS BELGETARIH,NULL AS TARIH, FB.TUR, F.FATBASID, F.URUNID,S.KOD, S.STOKADI, -1*(F.MIKTAR) AS MIKTAR, F.ADET, F.BIRIM, 
                                                                     FB.GIRISDEPO, GIRDEPO.DEPOADI AS GIRDEPO, FB.CIKISDEPO, CIKDEPO.DEPOADI AS CIKDEPO, CIKDEPO.ID AS STOKDEPOID, 
                                                                     CIKDEPO.DEPOADI AS STOKDEPO, coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'') AS STOKDEPOSONSAYIMTARIHI, 
                                                                     FB.TARIH AS HAREKETTARIH
                                               FROM         FATURA AS F INNER JOIN
                                                                     FATBASLIK AS FB ON F.FATBASID = FB.ID LEFT OUTER JOIN
                                                                     DEPOLAR AS GIRDEPO ON GIRDEPO.ID = FB.GIRISDEPO LEFT OUTER JOIN
                                                                     DEPOLAR AS CIKDEPO ON CIKDEPO.ID = FB.CIKISDEPO INNER JOIN
                                                                     STOKLAR AS S ON F.URUNID = S.ID
                                               WHERE     (F.TUR = 1) AND (FB.TARIH > coalesce(CIKDEPO.SONSAYIMTARIHI, ''1900-01-01'')) AND FB.TARIH < ''$Bitis$ 23:00'' AND (FB.TUR IN (14, 15, 16, 19)) 
) AS X INNER JOIN STOKLAR S ON X.KOD=S.KOD  LEFT OUTER JOIN  REHBERINI R   ON R.DEGER=S.ANABIRIM AND  BOLUM=''StokKart_Anabirim''
GROUP BY HAREKET,BELGETARIH,TARIH,X.KOD,X.STOKADI,R.ANAHTAR,S.ID) STOKDURUM

 LEFT OUTER JOIN
(SELECT F.URUNID,SUM(F.TUTAR/MIKTAR) AS MIKTAR_TUTAR FROM FATBASLIK FB INNER JOIN  FATURA F ON FB.ID=F.FATBASID INNER JOIN 
(SELECT F.URUNID,MAX(FB.FATURATARIH) as FATURATARIH FROM FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID 
WHERE FB.TUR IN (10, 11, 12, 19) GROUP BY F.URUNID) X ON FB.FATURATARIH=X.FATURATARIH AND X.URUNID=F.URUNID
GROUP BY F.URUNID) FIYAT
ON STOKDURUM.ID=FIYAT.URUNID
-------------------------------------------------------------------------------------------------------------------------------------
UNION
--PASİFLER KREDİ---------------------------------------------------------------------------------------------------------------------

SELECT ''PASİFLER'' AS ANAGRUBU,''Krediler'' AS HESAP,'''' AS GRUP,SUM(TAKSIT) AS BAKIYE,KUR FROM PLANKREDI   WHERE ODENMIS=0 AND TARIH > ''$Bitis$ 23:00'' GROUP BY KUR
-----------------------------------------------------------------------------------------------------------------------------------     
UNION ALL
--PASİFLER SATICILAR----------------------------------------------------------------------------------------------------------------

SELECT ''PASİFLER''  AS ANAGRUBU ,''Satıcılar''  as HESAP,''''  AS GRUP,BAKIYE=SUM(TOPLAM_ALACAK-TOPLAM_BORC),KUR  FROM BORC_ALACAK DSA
INNER JOIN REHBER R ON DSA.REHBERID=R.ID 
where 1=1  and DURUM=1 and R.KOD NOT LIKE ''400%'' and  coalesce(R.ID,'''')<>'''' and (coalesce(TOPLAM_ALACAK,0) - coalesce(TOPLAM_BORC,0)) > 1.0
GROUP BY KUR
-------------------------------------------------------------------------------------------------------------------------------------
/*UNION
--PASİFLER KREDİ---------------------------------------------------------------------------------------------------------------------
SELECT ''AKTİFLER'' AS ANAGRUBU,''Krediler'' AS HESAP,'''' AS GRUP,SUM(BORC-ALACAK) AS BAKIYE,KUR FROM
(SELECT K.KREDIKODU,
