(SELECT coalesce(SUM(ANAPARA),0) FROM PLANKREDI PK WHERE K.ID=PK.KREDIID AND ODENMIS=1)-K.TUTARI AS RISK,
(SELECT coalesce(SUM(ANAPARA),0) FROM PLANKREDI PK WHERE K.ID=PK.KREDIID AND ODENMIS=1) AS LIMIT_BOSLUGU,
K.KUR,
K.KREDILIMITSURETIPI,
