(SELECT COUNT(ODENMIS) FROM PLANKREDI PK WHERE K.ID=PK.KREDIID AND ODENMIS=1) AS ODENENTAKSITSAYISI,
K.KREDITAKSIT-(SELECT COUNT(ODENMIS) FROM PLANKREDI PK WHERE K.ID=PK.KREDIID AND ODENMIS=1) AS KALANTAKSIT
