K.ALINISTARIHI <= ''$Bitis$ 23:00'') AS KREDI GROUP BY KUR */
-------------------------------------------------------------------------------------------------------------------------------------
UNION ALL
--VERİLEN ÇEKLER---------------------------------------------------------------------------------------------------------------------
 
SELECT ''PASİFLER''  AS ANAGRUBU ,''Verilen Çekler''  as HESAP,''''  AS GRUP,
SUM(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS BAKIYE, 
(CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end) as KUR
FROM CEKLER WHERE TUR=33 AND TARIH >=''$Baslangic$ 00:00'' AND TARIH <=''$Bitis$ 23:00'' AND DURUM=1 
GROUP BY (CASE WHEN coalesce(DOVIZ_TUTARI,0)>1 THEN DOVIZ_KURU else KUR end)      
-------------------------------------------------------------------------------------------------------------------------------------
