WHERE coalesce(BAKIYE,0) <> 0
' WHERE id = 1332;
UPDATE public.dokumler SET sql = '/*PGX*/

select 
	KR.ID,KREDIKODU,ADI,(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25018 AND DEGER=KR.KREDITEMINAT) AS KREDITEMINAT ,
	(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25008 AND DEGER=GENELKREDITIPI) AS KREDI_TURU ,
--	KREDILIMIT=sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0.0 else P.ANAPARA end),
        case KR.KREDILIMITSURETIPI 
  when 1 then KR.KREDILIMIT
  ELSE sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0.0 else P.ANAPARA end) END AS KREDILIMIT,
        
        
        sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0.0 else P.ANAPARA end) AS RISK ,
	case KR.KREDILIMITSURETIPI 
  when 1 then KR.KREDILIMIT-sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0.0 else P.ANAPARA end)
  ELSE 0 END AS LIMIT_BOSLUGU,
	sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0 else 1 end)*(SELECT PK.TAKSIT FROM PLANKREDI PK WHERE PK.KREDIID=KR.ID ORDER BY TARIH DESC LIMIT 1 ) AS FAIZ_DAHIL_BAKIYE ,
	--LIMIT_BOSLUGU=(KR.KREDILIMIT-sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0.0 else P.ANAPARA end)),
	KR.KUR,KR.KREDILIMITSURE,ALINISTARIHI,
	count(P.ID) AS KREDITAKSIT ,
	sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 1 else 0 end) AS ODENENTAKSIT ,
	sum(case when P.ODENMIS=1 and P.TARIH<=''$TARIH$''--now() then 0 else 1 end) AS KALANTAKSIT ,
	GENELKREDITIPI,
	(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25019 AND DEGER=KR.KREDILIMITSURETIPI) AS KREDILIMITSURETIPI ,
	BH.HESAPKODU,BH.HESAPADI,KR.TAKSITTUTARI
from KREDILER KR
	left join PLANKREDI P on P.KREDIID=KR.ID
	inner join BANKAHESAPLAR BH ON  BH.ID = KR.BANKATICARIHESAPID
	inner join BANKASUBELER BS ON BH.BANKASUBELERID=BS.ID
	inner join BANKALAR B on B.BANKAKODU=BS.BANKAKODU
where 
	 GENELKREDITIPI=1 
	and ALINISTARIHI<=''$TARIH$''--now()+1
 -- and KREDIKODU LIKE ''$KREDIKODU$%''
  and KR.DURUM <>0
GROUP BY 
	KR.ID,KREDIKODU,ADI,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KREDITAKSIT,KR.KREDILIMIT,
	TAKSITTUTARI,KREDITEMINAT,
	KR.KREDILIMITSURETIPI,KR.KREDILIMITSURE,KR.KREDIKULLANIMSURE,BH.HESAPKODU,BH.HESAPADI,KR.TAKSITTUTARI
-----
union all
----- SÜREKLİYSE LİMİT BOŞLUĞU --SÜREKLİDEN FARKLIYSA 0
select 
	KR.ID,KREDIKODU,ADI,(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25018 AND DEGER=KR.KREDITEMINAT) AS KREDITEMINAT ,
	(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25008 AND DEGER=GENELKREDITIPI) AS KREDI_TURU ,
	KR.KREDILIMIT,abs(coalesce(sum(BORC-ALACAK),0)) AS RISK ,
	0 AS FAIZ_DAHIL_BAKIYE ,
	case KR.KREDILIMITSURETIPI 
  when 1 then KR.KREDILIMIT -abs(coalesce(sum(BORC-ALACAK),0.0)) 
  ELSE 0.0 END AS LIMIT_BOSLUGU,
	--LIMIT_BOSLUGU=(KR.KREDILIMIT-coalesce(sum(BORC-ALACAK),0)),	
	KR.KUR,KR.KREDILIMITSURE,ALINISTARIHI,
	0 AS KREDITAKSIT ,
	0 AS ODENENTAKSIT ,
	0 AS KALANTAKSIT ,
	GENELKREDITIPI,		
	(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25019 AND DEGER=KR.KREDILIMITSURETIPI) AS KREDILIMITSURETIPI ,
	BH.HESAPKODU,BH.HESAPADI,0
 AS TAKSITTUTARI from KREDILER KR
	left outer join KASA KS on HESAPTURU=''R'' and KS.HESAPID=KR.ID and KS.HESAPID=KR.ID and KS.TUR<>2 and KS.ISLEMTARIHI<=''$TARIH$''--now()+1
	inner join BANKAHESAPLAR BH ON  BH.ID = KR.BANKATICARIHESAPID
	inner join BANKASUBELER BS ON BH.BANKASUBELERID=BS.ID
	inner join BANKALAR B on B.BANKAKODU=BS.BANKAKODU
where 
	 GENELKREDITIPI = 2 
  -- and KREDIKODU LIKE ''$KREDIKODU$%''
   and KR.DURUM <>0
GROUP BY 
	KR.ID,KREDIKODU,ADI,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KREDITAKSIT,KR.KREDILIMIT,
	TAKSITTUTARI,KREDITEMINAT,
	KR.KREDILIMITSURETIPI,KR.KREDILIMITSURE,KR.KREDIKULLANIMSURE,BH.HESAPKODU,BH.HESAPADI,KR.TAKSITTUTARI

UNION ALL

select 
	KR.ID,KREDIKODU,ADI,(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25018 AND DEGER=KR.KREDITEMINAT) AS KREDITEMINAT ,
	(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25008 AND DEGER=GENELKREDITIPI) AS KREDI_TURU ,
	KR.KREDILIMIT,abs(coalesce(sum(BORC-ALACAK),0)) AS RISK ,
	0 AS FAIZ_DAHIL_BAKIYE ,
	case KR.KREDILIMITSURETIPI 
  when 1 then KR.KREDILIMIT -abs(coalesce(sum(BORC-ALACAK),0.0)) 
  ELSE 0.0 END AS LIMIT_BOSLUGU,
	--LIMIT_BOSLUGU=(KR.KREDILIMIT-coalesce(sum(BORC-ALACAK),0)),	
	KR.KUR,KR.KREDILIMITSURE,ALINISTARIHI,
	0 AS KREDITAKSIT ,
	0 AS ODENENTAKSIT ,
	0 AS KALANTAKSIT ,
	GENELKREDITIPI,		
	(SELECT ANAHTAR FROM GENINI WHERE BOLUM=25019 AND DEGER=KR.KREDILIMITSURETIPI) AS KREDILIMITSURETIPI ,
	BH.HESAPKODU,BH.HESAPADI,0
 AS TAKSITTUTARI from KREDILER KR
	left outer join KASA KS on HESAPTURU=''R'' and KS.HESAPID=KR.ID and KS.HESAPID=KR.ID and KS.TUR<>2 and KS.ISLEMTARIHI<=''$TARIH$''--now()+1
	inner join BANKAHESAPLAR BH ON  BH.ID = KR.BANKATICARIHESAPID
	inner join BANKASUBELER BS ON BH.BANKASUBELERID=BS.ID
	inner join BANKALAR B on B.BANKAKODU=BS.BANKAKODU
where 
	 GENELKREDITIPI = 11 
  -- and KREDIKODU LIKE ''$KREDIKODU$%''
   and KR.DURUM <>0
GROUP BY 
	KR.ID,KREDIKODU,ADI,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KREDITAKSIT,KR.KREDILIMIT,
	TAKSITTUTARI,KREDITEMINAT,
	KR.KREDILIMITSURETIPI,KR.KREDILIMITSURE,KR.KREDIKULLANIMSURE,BH.HESAPKODU,BH.HESAPADI,KR.TAKSITTUTARI

 order by   KR.KUR ,BH.HESAPKODU

 --SELECT * FROM GENINI WHERE ANAHTAR LIKE ''%İPOTEK%''
' WHERE id = 1333;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                    
ISLEMTUR,FATURATARIH,month(FATURATARIH) AS BELGE_AY ,FATURANO,CARIKOD,FIRMA,VERGINO,KOD,AD,ACIKLAMA,cast(ADET as double precision) AS ADET,ANAHTAR,
cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT,
cast(BIRIMFIYAT*ADET as double precision) AS TUTAR ,          
ISKONTO,
cast((BIRIMFIYAT*ADET) as double precision)-TUTAR AS ISKONTOTUTARI ,--ROUND((((BIRIMFIYAT*ADET)/100.0)*ISKONTO),2),
KDV,
cast(TUTAR as double precision) AS KDVMATRAHI ,
cast(KDVLITOPLAM as double precision)-TUTAR AS KDVTUTAR ,  KDV_TUTARI,
cast(KDVLITOPLAM as double precision) AS GENELTOPLAM ,
MASRAFKODU,
GRUPADI,KDVDURUM,OZELKOD_ ,PROJEKODU,SUBE,
ILCE,IL,PERSONEL,ACIKLAMA1,ACIKLAMA2,FATURASERI

FROM (

SELECT 
fb.OZELKOD,
BZ.AD AS ZARF ,FB.TUR,
 CASE WHEN FB.TIPI=1 THEN ''Alış/Satış'' WHEN FB.TIPI=2 THEN ''İade'' WHEN FB.TIPI=3 THEN ''Fiyat Farkı'' WHEN FB.TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR ,
(SELECT OZELKOD FROM STOKLAR S where  F.URUNID=S.ID  )   AS STOK_OZELKOD , 
 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
F.ISKONTO,F.KDV,
CASE WHEN FB.RAPORDOVIZ<>''TL'' AND F.DOVIZ_TUTARI>0 THEN ROUND(cast((F.TUTAR/F.ADET)/(F.DOVIZ_TUTARI/F.ADET) as double precision),4) ELSE 0 END  AS KURU ,MG.KOD AS MASRAFKODU,MG.AD AS MASRAFADI,
--KATEGORIADI = coalesce((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID)),''Kategorisiz''),
--GRUPADI     = coalesce((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID)),''Grupsuz''),
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                            ELSE 
                            coalesce(((SELECT DISTINCT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100))) ),''Kategorisiz'')

                            END AS KATEGORIADI ,
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                            ELSE 
                                      ''Grupsuz''
                            END   AS GRUPADI ,
FB.KDVDURUM ,
(SELECT OZELKOD FROM MASRAFGELIR S where  F.URUNID=S.ID  )   AS OZELKOD_ ,
P.PROJEADI,P.PROJEKODU,
(SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID=FB.SUBEID) AS SUBE ,
 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer) AND F.TUR=1)   AS MODEL ,
coalesce(ROUND(F.MIKTAR*coalesce(SOM.BIRIMMALIYET,0.0),2),0.0) as TOPLAM_MALİYET,(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA 
AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=22 LIMIT 1 )  AS VERGINO ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
(SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU=R1.ID) AS PERSONEL ,FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,FB.FATURASERI ,FB.KDV_TUTARI

FROM 

FATBASLIK FB 
         INNER JOIN FATURA F ON 
                   FB.ID=F.FATBASID 
          left outer join STOK_ORT_MALIYET SOM ON 
                                  F.ID=SOM.FATURAID          
         LEFT OUTER JOIN REHBER R ON 
                   FB.REHBERID=R.ID
         LEFT OUTER JOIN MASRAFGELIR MG ON
                   F.MASRAFID=MG.ID-- AND
         LEFT OUTER JOIN REHBERINI RI ON
                   RI.BOLUM=''StokKart_Anabirim'' and
                   RI.DEGER=F.BIRIM
         LEFT OUTER JOIN REHBERINI RI1 ON
                   RI1.BOLUM=''Kasa Türleri'' and
                   RI1.DEGER=FB.TUR
        LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
        LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
	LEFT OUTER JOIN STOKLAR S ON S.ID=F.URUNID  
        LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
        LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID

WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
AND coalesce(PROJEKODU,'''') LIKE ''$ProjeKod$'' 
AND FB.TUR IN (11)
AND ADET <>0.0

) AS X

ORDER BY GRUPADI,KATEGORIADI,FATURATARIH,ISLEMTUR' WHERE id = 1334;
UPDATE public.dokumler SET sql = '/*PGX*/--İndirilecek Kdv Dökümü
           
           
                               



SELECT * FROM (
SELECT                                                       
                FB.FATURATARIH,FB.FATURANO,F.KDV, 
                --KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' THEN (F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR
                --                                               WHEN FB.KDVDURUM=''Dahil'' THEN F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))
                --                                               END),
matrah=  SUM(CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN cast(F.TUTAR as double precision)
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN F.TUTAR/(1+(F.KDV/100.0))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN f.tutar * (1.0-(KDVMUHAFIYETI/100.0))
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR/(1+(F.KDV/100.0))) * (1.0-(KDVMUHAFIYETI/100.0))
                                                                  END) ,
KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN (cast(F.TUTAR as double precision)*(1+(F.KDV/100.0)))-F.TUTAR
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN ((F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR) * (1.0-(KDVMUHAFIYETI/100.0))
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))) * (1.0-(KDVMUHAFIYETI/100.0))
                                                                  END) ,
                IT.AD AS ISLEMADI,FB.ACIKLAMA,R.FIRMA,
                TIPI=CASE WHEN IT.TIP IN (1,3,4,5) AND FB.TUR IN (11) THEN ''Alış'' 
                                 WHEN IT.TIP IN (2)     AND FB.TUR IN (11) THEN ''İade'' 
                  WHEN FB.TUR IN (8) THEN ''Gider Pusulası''  
                                                END
FROM
                FATURA AS F 
                               INNER JOIN FATBASLIK FB ON 
                                               F.FATBASID = FB.ID 
                               INNER JOIN ISLEMTURLERI IT ON 
                                               FB.TUR  = IT.TUR and 
                                               FB.TIPI = coalesce(IT.TIP,'''')
                LEFT JOIN REHBER R ON
                        FB.REHBERID=R.ID
WHERE 
                    FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
                AND FB.TUR IN (8,11) AND coalesce(FB.DURUM,0)<>6
GROUP BY 
                F.KDV, IT.AD,FB.ACIKLAMA,FB.FATURANO,R.FIRMA,FB.FATURATARIH,FB.TUR,IT.TIP
) AS X
WHERE 
                coalesce(TIPI,'''') LIKE ''$IslemAdi$%''    
                AND coalesce(KDV,'''') LIKE  CASE WHEN ''$Kdv$''='''' THEN ''%'' ELSE ''$Kdv$'' END 

union all 
          
SELECT * FROM (
SELECT                                                       
                FB.FATURATARIH,FB.FATURANO,F.KDV, 
                --KDVTUTARI=SUM(CASE WHEN FB.KDVDURUM=''Hariç'' THEN (F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR
                --                                               WHEN FB.KDVDURUM=''Dahil'' THEN F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))
                --                                               END),
matrah=  CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN cast(F.TUTAR as double precision)
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN F.TUTAR/(1+(F.KDV/100.0))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN f.tutar * (1.0-(KDVMUHAFIYETI/100.0))
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR/(1+(F.KDV/100.0))) * (1.0-(KDVMUHAFIYETI/100.0))
                                                                  END ,
KDVTUTARI=CASE WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN (cast(F.TUTAR as double precision)*(1+(F.KDV/100.0)))-F.TUTAR
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)=0 THEN F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))
                    
                           WHEN FB.KDVDURUM=''Hariç'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN ((F.TUTAR*(1+(F.KDV/100.0)))-F.TUTAR) * (1.0-(KDVMUHAFIYETI/100.0))
                                                  WHEN FB.KDVDURUM=''Dahil'' AND coalesce(KDVMUHAFIYETI,0)<>0 THEN (F.TUTAR-(F.TUTAR/(1+(F.KDV/100.0)))) * (1.0-(KDVMUHAFIYETI/100.0))
                                                                  END ,
                IT.AD AS ISLEMADI,FB.ACIKLAMA,R.FIRMA,
                TIPI=CASE WHEN IT.TIP IN (1,3,4,5) AND FB.TUR IN (12) THEN ''Alış'' 
                                 WHEN IT.TIP IN (2)     AND FB.TUR IN (12) THEN ''İade'' 
                  WHEN FB.TUR IN (8) THEN ''Gider Pusulası''  
                                                END
FROM
                FATURA AS F 
                               INNER JOIN FATBASLIK FB ON 
                                               F.FATBASID = FB.ID 
                               INNER JOIN ISLEMTURLERI IT ON 
                                               FB.TUR  = IT.TUR and 
                                               FB.TIPI = coalesce(IT.TIP,'''')
                LEFT JOIN REHBER R ON
                        FB.REHBERID=R.ID
WHERE 
                    FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
                AND FB.TUR IN (8,12) AND coalesce(FB.DURUM,0)<>6
) AS X
WHERE 
                coalesce(TIPI,'''') LIKE ''$IslemAdi$%''    
                AND coalesce(KDV,'''') LIKE  CASE WHEN ''$Kdv$''='''' THEN ''%'' ELSE ''$Kdv$'' END 
ORDER BY ISLEMADI ,ACIKLAMA
' WHERE id = 1335;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                    
ISLEMTUR,FATURATARIH,month(FATURATARIH) AS BELGE_AY ,FATURANO,CARIKOD,FIRMA,VERGINO,KOD,AD,ACIKLAMA,cast(ADET as double precision) AS ADET,ANAHTAR,
cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT,
cast(BIRIMFIYAT*ADET as double precision) AS TUTAR ,          
ISKONTO,
cast((BIRIMFIYAT*ADET) as double precision)-TUTAR AS ISKONTOTUTARI ,--ROUND((((BIRIMFIYAT*ADET)/100.0)*ISKONTO),2),
KDV,
cast(TUTAR as double precision) AS KDVMATRAHI ,
cast(KDVLITOPLAM as double precision)-TUTAR AS KDVTUTAR ,
cast(KDVLITOPLAM as double precision) AS GENELTOPLAM ,
MASRAFKODU,
GRUPADI,KDVDURUM,OZELKOD_ ,PROJEKODU,SUBE,
ILCE,IL,PERSONEL,ACIKLAMA1,ACIKLAMA2,FATURASERI

FROM (

SELECT 
fb.OZELKOD,
BZ.AD AS ZARF ,FB.TUR,
 CASE WHEN FB.TIPI=1 THEN ''Alış/Satış'' WHEN FB.TIPI=2 THEN ''İade'' WHEN FB.TIPI=3 THEN ''Fiyat Farkı'' WHEN FB.TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR ,
(SELECT OZELKOD FROM STOKLAR S where  F.URUNID=S.ID  )   AS STOK_OZELKOD , 
 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
F.ISKONTO,F.KDV,
CASE WHEN FB.RAPORDOVIZ<>''TL'' AND F.DOVIZ_TUTARI>0 THEN ROUND(cast((F.TUTAR/F.ADET)/(F.DOVIZ_TUTARI/F.ADET) as double precision),4) ELSE 0 END  AS KURU ,MG.KOD AS MASRAFKODU,MG.AD AS MASRAFADI,
--KATEGORIADI = coalesce((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID)),''Kategorisiz''),
--GRUPADI     = coalesce((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID)),''Grupsuz''),
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                            ELSE 
                            coalesce(((SELECT DISTINCT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100))) ),''Kategorisiz'')

                            END AS KATEGORIADI ,
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                            ELSE 
                                      ''Grupsuz''
                            END   AS GRUPADI ,
FB.KDVDURUM ,
(SELECT OZELKOD FROM MASRAFGELIR S where  F.URUNID=S.ID  )   AS OZELKOD_ ,
P.PROJEADI,P.PROJEKODU,
(SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID=FB.SUBEID) AS SUBE ,
 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer) AND F.TUR=1)   AS MODEL ,
coalesce(ROUND(F.MIKTAR*coalesce(SOM.BIRIMMALIYET,0.0),2),0.0) as TOPLAM_MALİYET,(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA 
AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=22 LIMIT 1 )  AS VERGINO ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
(SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU=R1.ID) AS PERSONEL ,FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,E.AD AS EAD ,ER.SERINO,FB.FATURASERI

FROM 

FATBASLIK FB 
         INNER JOIN FATURA F ON 
                   FB.ID=F.FATBASID 
          left outer join STOK_ORT_MALIYET SOM ON 
                                  F.ID=SOM.FATURAID          
         LEFT OUTER JOIN REHBER R ON 
                   FB.REHBERID=R.ID
         LEFT OUTER JOIN MASRAFGELIR MG ON
                   F.MASRAFID=MG.ID-- AND
         LEFT OUTER JOIN REHBERINI RI ON
                   RI.BOLUM=''StokKart_Anabirim'' and
                   RI.DEGER=F.BIRIM
         LEFT OUTER JOIN REHBERINI RI1 ON
                   RI1.BOLUM=''Kasa Türleri'' and
                   RI1.DEGER=FB.TUR
        LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
        LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
	LEFT OUTER JOIN STOKLAR S ON S.ID=F.URUNID  
        LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
        LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID

WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
AND coalesce(PROJEKODU,'''') LIKE ''$ProjeKod$'' 
AND FB.TUR IN (11)
AND ADET <>0.0

) AS X

ORDER BY GRUPADI,KATEGORIADI,FATURATARIH,ISLEMTUR' WHERE id = 1338;
UPDATE public.dokumler SET sql = '/*PGX*/select * 
from(

       select *,sum(GIREN-CIKAN)over(partition by KOD order by BELGETARIH)
        AS KUMMIKTAR from (


                                 SELECT     ''Giren'' AS HAREKET,G.ANAHTAR,FATURATARIH AS BELGETARIH,S.KOD, S.STOKADI,R.FIRMA, F.MIKTAR AS GIREN ,0.0 AS CIKAN
                                 FROM         FATURA AS F INNER JOIN
                                              FATBASLIK AS FB ON F.FATBASID = FB.ID  INNER JOIN
                                              STOKLAR AS S ON F.URUNID = S.ID LEFT OUTER JOIN 
                                              REHBER AS R ON R.ID=FB.REHBERID
											  inner join 
            GENINI G on G.BOLUM=-1005 and G.DIL=-1 and G.DEGER=FB.TUR
                                 WHERE    F.STOKDURUMDEGIS=1 and F.TUR = 1 and coalesce(GIRISDEPO,-999)<>-999
                                 UNION ALL
                                 SELECT     ''Çıkan'' AS HAREKET,G.ANAHTAR,FATURATARIH AS BELGETARIH,S.KOD, S.STOKADI,R.FIRMA, 0.0 AS GIREN ,F.MIKTAR AS CIKAN
                                 FROM         FATURA AS F INNER JOIN
                                              FATBASLIK AS FB ON F.FATBASID = FB.ID INNER JOIN
                                              STOKLAR AS S ON F.URUNID = S.ID LEFT OUTER JOIN
                                              REHBER AS R ON R.ID=FB.REHBERID
											  inner join 
            GENINI G on G.BOLUM=-1005 and G.DIL=-1 and G.DEGER=FB.TUR
                                 WHERE   F.STOKDURUMDEGIS=1 and F.TUR = 1 and coalesce(CIKISDEPO,-999)<>-999
       )as XXX
)as YYY
where KUMMIKTAR<0.0
order by KOD,BELGETARIH' WHERE id = 1340;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT S.KOD,S.STOKADI FROM STOKLAR S  Where S.ID  NOT IN (SELECT M.YER_ID FROM MUHASEBEKOD M)' WHERE id = 1341;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT to_char(FATURATARIH,''DD/MM/YYYY'') AS FATURA_TARIHI,FATURANO,R.KOD AS HESAP_KODU,R.FIRMA AS HESAP_ADI,
F.FATURA_MATRAHI+coalesce((SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ),0) AS ARA_TOPLAM,
KDV_TUTARI AS KDV,
(SELECT SUM ((BIRIMFIYAT/100)*ISKONTO) FROM FATURA FT WHERE FT.FATBASID=F.ID ) AS INDIRIM,
FATURA_TUTARI AS NET_TOPLAM  FROM REHBER R INNER JOIN FATBASLIK F ON R.ID=F.REHBERID
WHERE
FATURATARIH>=''$Baslama$ 00:00:00''
AND FATURATARIH<=''$Bitis$ 23:59:00''
and TUR in (15)
order by  FATURATARIH' WHERE id = 1343;
UPDATE public.dokumler SET sql = '/*PGX*/select            
       KOD,FIRMA,ADSOYAD,
        case when PERS_ISTEL is not null then PERS_ISTEL else CARI_ISTEL end AS ISTEL ,
       
       case when PERS_CEP is not null then PERS_CEP else CARI_CEP end AS CEPTEL ,
          case when PERS_FAX is not null then PERS_FAX else CARI_FAX end AS FAX ,
        case when LTRIM(RTRIM(coalesce(PERS_ADRES,'''')))<>'''' then PERS_ADRES else CARI_ADRES end AS ADRES ,
        case when PERS_EMAIL is not null then PERS_EMAIL else CARI_EMAIL end AS EMAIL ,
       (select FIRMA from REHBER where ID=Y.SUBEID) AS SUBEAD ,
       (select ANAHTAR from GENINI where BOLUM=-2210 and DIL=-1 and DEGER=BOLGE) AS BOLGE ,
       (select ANAHTAR from GENINI where BOLUM=''-2210''||cast(BOLGE as varchar) and DEGER=ALTBOLGE and DIL = -1) AS ALTBOLGE ,
       (select ANAHTAR from GENINI where BOLUM=-2204 and DIL=-1 and DEGER=SEKTOR) AS SEKTOR ,
       (select ANAHTAR from GENINI where BOLUM=''-2204''||cast(SEKTOR as varchar) and DIL=-1 and DEGER=ALTSEKTOR) AS ALTSEKTOR ,
       (select FIRMA from REHBER where ID=Y.TEMSILCI) AS TEMSILCI ,
       EKIPMANSAYISI ,
                   MAIL_DAGITIM,POSTA ,VGNO


from(
       select * ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID AND RA.VARSAYILAN=40 LIMIT 1 ) AS CARI_ISTEL ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=42 LIMIT 1 ) AS CARI_CEP ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=43 LIMIT 1 ) AS CARI_FAX ,
             coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=2 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=6 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=4 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=8 LIMIT 1 ),'''') AS CARI_ADRES ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=46 LIMIT 1 ) AS CARI_EMAIL ,

             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID AND RA.VARSAYILAN=40 LIMIT 1 ) AS PERS_ISTEL ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=42 LIMIT 1 ) AS PERS_CEP ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=43 LIMIT 1 ) AS PERS_FAX ,
             coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=2 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=6 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=4 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=8 LIMIT 1 ),'''') AS PERS_ADRES ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=46 LIMIT 1 ) AS PERS_EMAIL ,
              (SELECT COUNT(*) FROM EKIPMANREHBER ER WHERE ER.REHBERID=X.REHBERID)  AS EKIPMANSAYISI ,
              Case wheN coalesce(STATU,1)=1 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=4795 AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END  
        AS VGNO from(
                    select 
                           Case when RP.ID is null then 1 else 4 end AS YER ,
                           R.ID AS REHBERID ,R.STATU,
                           (select ID from REHBERILETISIM RI where RI.REHBERID=RP.ID order by RI.VARSAYILAN desc LIMIT 1 ) AS ILGILIID ,
                           (select ID from REHBERILETISIM RI where RI.REHBERID=R.ID order by RI.VARSAYILAN desc LIMIT 1 ) AS ILETISIMID ,
                           R.KOD,R.FIRMA,RP.FIRMA AS ADSOYAD ,R.TEMSILCI,R.KATEGORI,R.SINIF,R.BOLGE,R.ALTBOLGE,R.SEKTOR,R.ALTSEKTOR,
coalesce((  SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON  RA.ETIKET=RB.ETIKET 
          WHERE  RA.ETIKET=''E-Mail Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=Rp.ID LIMIT 1 ),(
          SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON  RA.ETIKET=RB.ETIKET 
          WHERE  RA.ETIKET=''E-Mail Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=R.ID LIMIT 1 )) AS MAIL_DAGITIM , 
coalesce(( SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI                   
          WHERE  RA.ETIKET=''Posta Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=Rp.ID LIMIT 1 ),( 
          SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI                   
          WHERE  RA.ETIKET=''Posta Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=R.ID LIMIT 1 ))  
  AS POSTA , R.SUBEID

                    from 
                           REHBER R left outer join 
                           REHBER RP on R.ID=RP.BAGID and RP.DURUM <> 3
                    where R.ID>0 and R.DURUM<>0  AND R.GRUP IN (120,320)
                    
             ) as X
       ) as Y 

where
          FIRMA LIKE ''$Firma$%''
           AND coalesce((select ANAHTAR from GENINI where BOLUM=-2210 and DIL=-1 and DEGER=BOLGE),'''') LIKE ''$Bolge$%''
            
            and  coalesce((select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=ALTBOLGE AND GB.DEGER=BOLGE
                                where GALT.BOLUM like ''-2210%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2210 ),'''')  like ''$Altbolge$%''
           AND coalesce((select ANAHTAR from GENINI where BOLUM=-2204 and DIL=-1 and DEGER=SEKTOR),'''') LIKE ''$Sektor$%''
        AND coalesce((select ANAHTAR from GENINI where BOLUM=''-2204''||cast(SEKTOR as varchar) and DIL=-1 and DEGER=ALTSEKTOR),'''') LIKE ''$Altsektor$%''
       AND coalesce((select FIRMA from REHBER where ID=Y.TEMSILCI),'''') LIKE ''$Temsilci$%''
         and ISNULL ((select FIRMA from REHBER where ID=Y.SUBEID),'''') LIKE ''$Sube$%''
        and ISNULL (POSTA,'''') LIKE ''$Posta$%''
         and ISNULL (MAIL_DAGITIM,'''') LIKE ''$Mail$%''
        AND 1 = CASE WHEN ''$Ekipman$''=''Var'' AND EKIPMANSAYISI>0 THEN 1
                     WHEN ''$Ekipman$''=''Yok'' AND EKIPMANSAYISI=0 THEN 1
                     WHEN ''$Ekipman$''=''''THEN 1 ELSE 0 END' WHERE id = 1344;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT C.VADE,C.TUTAR,C.BORCLU,R1.KOD AS CARİ KOD,R1.FIRMA AS CARİ ADI,C.HESAPNO,G.ANAHTAR AS DURUM,C.SERINO AS ÇEK NO,
REFERANS TARİH =CH.TARIH,C.MAKBUZNO AS EVRAK NO,C.KOD ASHESAP KODU ,B.BANKAADI,BS.SUBEADI ,C.EKLEMETARIHI
      --a
FROM CEKLER C
  inner join CEKHAREKET CH on CH.ID=(select CH1.ID from CEKHAREKET CH1 where CH1.CEKSENETLERID=C.ID order by CH1.TARIH desc LIMIT 1 )
    INNER JOIN GENINI G ON C.TUR=G.DEGER 
  left outer join REHBER R1 ON C.REHBERID=R1.ID
  left outer join BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
  left outer join BANKALAR B ON B.BANKAKODU = BS.BANKAKODU
  left outer join REHBER R2 on CH.REHBERID=R2.ID
  left outer join BANKAHESAPLAR BHSON on CH.BANKAHESAPLARID=BHSON.ID
  left outer join BANKAHESAPLAR BH2 on C.HESAPID=BH2.ID
Where 1=1    AND C.CEKSENET=101
 and CH.ISLEM in (0,130,131,132,138,133,134,135,136,137)   AND G.BOLUM=-1005
AND    G.ANAHTAR LIKE ''$Durum$%'' AND
         VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND 1=case 
       when C.TUR<>136 then 1
       when (C.TUR=136)and(''Tahsil edilmişleri de listele''=''$Tur$'') then 1 
       else 0 end' WHERE id = 1346;
UPDATE public.dokumler SET sql = '/*PGX*/


          --deneme
--
--

IF EXISTS (SELECT 1 FROM tempdb..sysobjects WHERE name LIKE ''gt_KasaKurFark%'')
  DROP TABLE gt_KasaKurFark
CREATE TABLE gt_KasaKurFark
(              SIRANO int IDENTITY(1,1) NOT NULL,
                TIP varchar(20) ,
                CEKID int,
                TARIH datetime,
                AKSIYONTARIH datetime,
                NO varchar(20) ,
                TUR smallint,
                BASLIK varchar(150) ,
                TURAD varchar(50) ,
                REHBERID int,
                KOD varchar(20) ,
                AD varchar(100) ,
                ACIKLAMA varchar(2000) ,
                HESAPID int,
                HESAPKODU varchar(100) ,
                HESAPADI varchar(150) ,
                DURUM smallint,
                BORC money,
                ALACAK money,
                KUR varchar(6),
                MASRAFID int,
                MASRAFKOD varchar(50) ,
                MASRAFAD varchar(100) ,
                BORCBAKIYE money, 
                ALACAKBAKIYE money,  
                SUBEID int, 
                VADETARIHI datetime,
        YERELKUR MONEY,
        YERELTUTAR MONEY  )

open Crs1 
fetch next from Crs1 into @RehID 
while @@FETCH_STATUS = 0 
begin  
  insert into gt_KasaKurFark(TIP,CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,ALACAK,KUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,SUBEID,VADETARIHI,YERELKUR,YERELTUTAR)
  select TIP=''Cari'',CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,ALACAK,KUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,SUBEID,VADETARIHI,YERELKUR,YERELTUTAR
  from  fn_Cari_Ekstre(@RehID,''2015-01-01 00:00:00'',''2015-06-30 23:59:00'', 0)
  where TUR <> 2
fetch next from Crs1 into @RehID 
End 
close Crs1 
deallocate Crs1

open Crs2 
fetch next from Crs2 into @RehID 
while @@FETCH_STATUS = 0 
begin  
  insert into gt_KasaKurFark(TIP,CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,ALACAK,KUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,SUBEID,VADETARIHI,YERELKUR,YERELTUTAR)
  select TIP=''Banka'',CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,ALACAK,KUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,SUBEID,VADETARIHI,YERELKUR,YERELTUTAR
  from  fn_Banka_Ekstre(@RehID,''2015-01-01 00:00:00'',''2015-06-30 23:59:00'') 
  where TUR <> 2
fetch next from Crs2 into @RehID 
End 
close Crs2 
deallocate Crs2

open Crs3 
fetch next from Crs3 into @RehID 
while @@FETCH_STATUS = 0 
begin  
  insert into gt_KasaKurFark(TIP,CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,ALACAK,KUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,SUBEID,VADETARIHI,YERELKUR,YERELTUTAR)
  select TIP=''Kasa'',CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,ALACAK,KUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,SUBEID,VADETARIHI,YERELKUR,YERELTUTAR
  from  fn_Kasa_Nakit_Ekstre(@RehID,''2015-01-01 00:00:00'',''2015-06-30 23:59:00'')  
  where TUR <> 2
fetch next from Crs3 into @RehID   
End 
close Crs3 
deallocate Crs3

select 
                A.TIP,B.ID,B.KOD,B.AD,
                DOV_ISL_TUTARI=SUM(TUTAR),DOVIZ_TURU=A.KUR,
                           ISLEM_KURU=ROUND(SUM(TUTAR_TL_OGUN)/NULLIF(SUM(TUTAR),0),4),
                ISLEMIN_TL_KARSILIGI=SUM(TUTAR_TL_OGUN),
                           DONEM_SONU_KURU=ROUND(SUM(TUTAR_TL_BUGUN)/NULLIF(SUM(TUTAR),0),4),
                DEGERLENMIS_TL_KARSILIGI=SUM(TUTAR_TL_BUGUN),
                          FARK=SUM(TUTAR_TL_BUGUN-TUTAR_TL_OGUN),
                BASLAMA=''2015-01-01 00:00:00'',BITIS=''2015-06-30 23:59:00''
from 
                (select 
                               TIP,TARIH,TUR,TURAD,NO,TUTAR,KUR,REHBERID,
                               TUTAR_TL_OGUN=YERELTUTAR,--(TUTAR*KUROGUN),
                               TUTAR_TL_BUGUN=(TUTAR*KURBUGUN),
                               KURFARKI=(TUTAR*KURBUGUN)-YERELTUTAR--(TUTAR*KUROGUN)
                                                
                from
                               (select 
                                               TIP,TARIH,TUR,TURAD,NO,TUTAR=BORC-ALACAK,KUR,REHBERID,
                                               KUROGUN=YERELKUR,YERELTUTAR,
                                               KURBUGUN=(select $DovTur$ FROM DOVIZ D WHERE CINSI =EX.KUR  ORDER BY ABS(DATEDIFF(HOUR,D.TARIH+1,''2015-06-30 23:59:00'')) LIMIT 1 )
                                               --KURBUGUN=(select SATIS FROM DOVIZ D WHERE CINSI =EX.KUR  ORDER BY ABS(DATEDIFF(HOUR,D.TARIH+1,''2015-06-30 23:59:00'')) LIMIT 1 )
                               from 
                                               (select * from gt_KasaKurFark ) as EX) as E)as A inner join
                (select TIP=''Cari'',R.ID,R.KOD,AD=R.FIRMA from REHBER R
                               union all
                select TIP=''Kasa'',K.ID,KOD=K.KASAKODU,AD=K.KASAADI from KASALAR K
                               union all
                select TIP=''Banka'',B.ID,KOD=B.HESAPKODU,AD=B.HESAPADI from BANKAHESAPLAR B
               
                ) as B on A.TIP=B.TIP and A.REHBERID=B.ID

where A.KUR <> ''TL''
group by B.ID,B.KOD,B.AD,A.TIP,A.KUR
having SUM(TUTAR_TL_OGUN)<>SUM(TUTAR_TL_BUGUN) 
order by A.TIP
' WHERE id = 1348;
UPDATE public.dokumler SET sql = '/*PGX*/select distinct  ISLEMTARIHI AS KULLANICI ,G.ANAHTAR AS ISLEM , R.FIRMA,K.EKLEMETARIHI  AS SISTEM , DATEDIFF(day,ISLEMTARIHI,K.EKLEMETARIHI) AS ''Gün Farkı''
from kasa K LEFT JOIN REHBER R ON R.ID=K.REHBERID
LEFT JOIN GENINI G ON K.TUR=G.DEGER AND G.BOLUM=-1005
 WHERE cast(ISLEMTARIHI as varchar) <> K.EKLEMETARIHI 
AND K.EKLEMETARIHI BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
UNION ALL
select distinct  FATURATARIH AS KULLANICI ,G.ANAHTAR AS ISLEM , R.FIRMA, FB.EKLEMETARIHI  AS SISTEM ,DATEDIFF(day,FATURATARIH,FB.EKLEMETARIHI) AS ''Gün Farkı''
from FATBASLIK FB LEFT JOIN REHBER R ON R.ID=FB.REHBERID
LEFT JOIN GENINI G ON FB.TUR=G.DEGER AND G.BOLUM=-1005
 WHERE cast(FATURATARIH as varchar) <> FB.EKLEMETARIHI 
AND FB.EKLEMETARIHI  BETWEEN ''$Baslangic$ 00:00'' and  ''$Bitis$ 23:59'' 
order by 4' WHERE id = 1350;
UPDATE public.dokumler SET sql = '/*PGX*/
''$Bitis$ 23:58'' DATETIME 





''$Bitis$ 23:58''--''2016-12-31 23:59'' DATETIME 




SELECT HESAPKODU,HESAPADI,
       BORC=ROUND(SUM(cast(BORC as double precision)),2),
       ALACAK=ROUND(SUM(cast(ALACAK as double precision)),2),
       BAKIYE=ROUND(SUM(cast(KALAN as double precision)),2),
       KUR,
       TLBORC=ROUND(SUM(cast(TLBORC as double precision)),2),
       TLALACAK=ROUND(SUM(cast(TLALACAK as double precision)),2),
       TLBAKIYE=ROUND(SUM(cast(TLKALAN as double precision)),2)
FROM(
-- pos 
SELECT  HESAPKODU,HESAPADI,BORC=SUM(BORC),ALACAK=SUM(ALACAK),KALAN=SUM(BORC)-SUM(ALACAK),KUR,TLBORC=SUM(BORC),TLALACAK=SUM(ALACAK),TLKALAN=SUM(BORC)-SUM(ALACAK),TLKUR=''TL''
FROM(
	SELECT 
		ID,
		KODU as HESAPKODU,
		ADI as HESAPADI, 
		BORC= (SELECT coalesce(SUM(B),0.0) FROM (
							select  B=  case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0.0 then K2.DOVIZ_TUTARI else K2.ALACAK end
							from KASA K2  
							where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''P'' AND TUR <> 2) AS X ),
		ALACAK=(SELECT coalesce(SUM(A),0.0) FROM (
							select A=           case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0.0 then K2.DOVIZ_TUTARI else K2.BORC end
							from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''P'' --AND TUR <> 2
				) AS X ),
		KUR=''TL''	
	FROM 
		POS k1 
) AS X
WHERE ((BORC<>0.0) or (ALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
union all
--KASA
SELECT HESAPKODU,HESAPADI,SUM(BORC) AS BORC,SUM(ALACAK) AS ALACAK,KALAN=SUM(BORC)-SUM(ALACAK),KUR,TLBORC=SUM(TLBORC),TLALACAK=SUM(TLALACAK),TLKALAN=SUM(TLBORC)-SUM(TLALACAK),TLKUR=''TL''
FROM(  
	SELECT 
		ID,
		KASAKODU as HESAPKODU,
		KASAADI as HESAPADI, 
		BORC= (SELECT coalesce(SUM(B),0) FROM (select  B=case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND K2.ALACAK>0 then K2.DOVIZ_TUTARI when K2.TUR=88 then K2.DOVIZ_TUTARI else K2.ALACAK end from KASA K2   where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
			) AS X ),
				ALACAK=(SELECT coalesce(SUM(A),0) FROM (select  A= case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND K2.BORC>0 then K2.DOVIZ_TUTARI 
		when K2.TUR=98 then K2.DOVIZ_TUTARI  else K2.BORC end from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
		) AS X ),
		TLBORC= (SELECT coalesce(SUM(B),0) FROM (select  B=case when K2.ALACAK>0.0 then K2.DOVIZ_TUTARI when K2.TUR=88 then K2.DOVIZ_TUTARI else 0.0 end  from KASA K2  
		where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
		) AS X ),
		TLALACAK=(SELECT coalesce(SUM(A),0) FROM (select  A= case when K2.BORC>0.0 then K2.DOVIZ_TUTARI when K2.TUR=98 then K2.DOVIZ_TUTARI else 0.0 end from KASA K2   where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
		) AS X ),
		KUR=''TL''  
	FROM KASALAR K1  
) AS X
WHERE 
	((BORC<>0.0) or (ALACAK<>0.0) or (TLBORC<>0.0) or (TLALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
--BANKA 
union all 
SELECT HESAPKODU,HESAPADI,BORC=SUM(BORC),ALACAK=SUM(ALACAK),KALAN=SUM(BORC)-SUM(ALACAK),KUR,TLBORC=SUM(TLBORC),TLALACAK=SUM(TLALACAK),TLKALAN=SUM(TLBORC)-SUM(TLALACAK),TLKUR=''TL''
FROM(
	SELECT
		ID,
		HESAPKODU,
		HESAPADI, 
		BORC   =  (SELECT coalesce(SUM(B),0) FROM (select B= K2.ALACAK from KASA K2  where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2
                ) AS X ),
		ALACAK = (SELECT coalesce(SUM(A),0) FROM (select  A= K2.BORC from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2
                 ) AS X ), 

		TLBORC   =  (SELECT coalesce(SUM(B),0) FROM (select  B= case when K2.TUR=88 then K2.DOVIZ_TUTARI when ALACAK>0.0 then (case when K2.DOVIZ_KURU=''TL'' then K2.DOVIZ_TUTARI else K2.ALACAK end)  else 0.0 end from KASA K2  where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2 
                ) AS X ),
		TLALACAK = (SELECT coalesce(SUM(A),0) FROM (select  A= case when K2.TUR=98 then K2.DOVIZ_TUTARI when BORC>0.0 then (case when K2.DOVIZ_KURU=''TL'' then K2.DOVIZ_TUTARI else K2.ALACAK end) else 0.0 end  from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2
                ) AS X ),
		K1.KUR
	FROM BANKAHESAPLAR K1   
) AS X
WHERE ((BORC<>0.0) or (ALACAK<>0.0) or (TLBORC<>0.0) or (TLALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
--ÇEKLER
union all 
select HESAPKODU,HESAPADI,BORC=SUM(BORC),ALACAK=SUM(ALACAK),KALAN=SUM(BAKIYE),KUR,TLBORC=SUM(TLBORC),TLALACAK=SUM(TLALACAK),TLKALAN=SUM(TLBORC)-SUM(TLALACAK),TLKUR=''TL''
from (
	select 
		HESAPKODU,HESAPADI,
		BORC=case when SUM(BAKIYE)>0.0 then SUM(BAKIYE) else 0.0 end,
		ALACAK=case when SUM(BAKIYE)>0.0 then 0.0 else -SUM(BAKIYE)end,
		BAKIYE=SUM(BAKIYE),
		KUR,
		TLBORC=case when SUM(TLBAKIYE)>0.0 then SUM(TLBAKIYE) else 0.0 end,
		TLALACAK=case when SUM(TLBAKIYE)>0.0 then 0.0 else -SUM(TLBAKIYE)end,
		TLBAKIYE=SUM(TLBAKIYE)
	from (
	--devir borc
		select 
			H.HESAPKODU,H.HESAPADI,BORC=C.TUTAR,ALACAK=0.0,BAKIYE=C.TUTAR,KUR=C.KUR,TLBORC=CH.DOVIZ_TUTARI,TLALACAK=0.0,TLBAKIYE=CH.DOVIZ_TUTARI
        from
			CEKLER C inner join 
			CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
			HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM AND H.VARSAYILAN = C.CEKSENET
		where
			CH.TARIH < ''$Baslangic$ 00:00''--''2000-01-01 00:00''

		union all
		--devir alacak
		select 
			H.HESAPKODU,H.HESAPADI,BORC=0.0,ALACAK=C.TUTAR,BAKIYE=-C.TUTAR,KUR=C.KUR,TLBORC=0.0,TLALACAK=CH.DOVIZ_TUTARI,TLBAKIYE=CH.DOVIZ_TUTARI
		from 
			CEKLER C inner join 
			CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join
			CEKHAREKET CHD on CH.GERIDONUSID=CHD.ID inner join 
			HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CHD.ISLEM AND H.VARSAYILAN = C.CEKSENET
		where 
			CH.TARIH < ''$Baslangic$ 00:00''--''2000-01-01 00:00'' 
	)as XX
	group by 
		HESAPKODU,HESAPADI,KUR

	union all
	--çekin ilgili tarihteki hareketi /hesabın borcuna
	select 
		H.HESAPKODU,H.HESAPADI,BORC=C.TUTAR,ALACAK=0.0,BAKIYE=C.TUTAR,KUR=C.KUR,TLBORC=CH.DOVIZ_TUTARI,TLALACAK=0.0,TLBAKIYE=CH.DOVIZ_TUTARI
	from 

                    CEKLER C inner join 
                    CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join
                    HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM AND H.VARSAYILAN = C.CEKSENET
             where CH.TARIH between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
             union all
             --çekin ilgili tarihteki hareketinin karşı hesabı /hesabın alacağına
             select H.HESAPKODU,H.HESAPADI,BORC=0.0,ALACAK=C.TUTAR,BAKIYE=-C.TUTAR,KUR=C.KUR,TLBORC=0.0,TLALACAK=CH.DOVIZ_TUTARI,TLBAKIYE=CH.DOVIZ_TUTARI
             from 
                    CEKLER C inner join 
                    CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                    CEKHAREKET CHD on CH.GERIDONUSID=CHD.ID inner join 
                    HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CHD.ISLEM AND H.VARSAYILAN = C.CEKSENET
             where CH.TARIH between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
)as XX
WHERE ((BORC<>0.0) or (ALACAK<>0.0) or (TLBORC<>0.0) or (TLALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
) AS X
GROUP BY HESAPKODU,HESAPADI,KUR
ORDER BY HESAPKODU,KUR
' WHERE id = 1354;
UPDATE public.dokumler SET sql = '/*PGX*/


SELECT @RaporDoviz = ANAHTAR FROM GENINI WHERE BOLUM=-10135

                
if OBJECT_ID(''tempdb..#tmpYaslandirma'') is not null
                drop table #tmpYaslandirma
create table #tmpYaslandirma (
                ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),ISLEMACIKLAMA varchar(500),
                BORCTUTARI money, ODEMETARIHI datetime, ODEMETURU varchar(100), ODEMEACIKLAMA varchar(500), ODEMETUTARI money, ODENENTUTAR money)
  
select ID from REHBER where KOD like  ''$Kod$%''

open crs
fetch next from crs into @RehberID
while @@FETCH_STATUS =0
BEGIN
                if OBJECT_ID(''tempdb..#tmpAlacaklar'') is not null
                               drop table #tmpAlacaklar
                if OBJECT_ID(''tempdb..#tmpBorclar'') is not null
                               drop table #tmpBorclar
                create table #tmpAlacaklar (
                               ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),
                               BELGENO varchar(100),ACIKLAMA varchar(500), ALACAK money, KUR varchar(5), 
                               ISLEMTUTARI money,KUMULATIFALACAK money)
                create table #tmpBorclar (
                               ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),
                               BELGENO varchar(100),ACIKLAMA varchar(500), BORC money, KUR varchar(5), 
                               ISLEMTUTARI money, KUMULATIFBORC money, )



                insert #tmpAlacaklar
                select @RehberID,
                                dateadd(millisecond,ISLEMID,TARIH) AS ISLEMTARIHI ,dateadd(millisecond,ISLEMID,VADE) AS VADESONU ,TURAD AS ISLEMTURU ,NO AS BELGENO ,ACIKLAMA,ALACAK,KUR,
                               -(ISLEMTUTARI) AS ISLEMTUTARI ,
                               SUM(case when ALACAK>0.0 then -(ISLEMTUTARI) else 0.0 end) OVER ( ORDER BY dateadd(millisecond,ISLEMID,VADE)) 
                 AS KUMULATIFALACAK from
                               (
                               Select 
                                               K.ID AS ISLEMID ,
                                               ISLEMTARIHI AS TARIH,BELGENO as NO, K.TUR,
                                                           case when K.TUR like ''26__'' then (select ANAHTAR || '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
                                                                                                              when K.TUR like ''36__'' then (select ANAHTAR || '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
                                                                                              else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end AS TURAD , 
                                               K.ACIKLAMA, 
                                               case HESAPTURU when ''B'' then (select HESAPKODU from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
                                                                                                                                             when ''H'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''|| (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)||'')'','''')
                                                                                                                                             when ''K'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)
                                                                                                                                             when ''P'' then (select KODU from POS P where P.ID=K.HESAPID)
                                                                                                                                             when ''V'' then (select KODU from KREDIKARTI KK where KK.ID=K.HESAPID) end AS HESAPKODU ,
                                               case HESAPTURU  when ''B'' then (select HESAPADI from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
                                                                                                                                             when ''H'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''|| (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)||'')'','''')
                                                                                                                                             when ''K'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)
                                                                                                                                             when ''P'' then (select ADI from POS P where P.ID=K.HESAPID)
                                                                                                                                             when ''V'' then (select ADI from KREDIKARTI KK where KK.ID=K.HESAPID) end AS HESAPADI ,
                                                case when (TUR = 88)or(EKSTREDEKULLAN=1 AND BORC>0)   then K.DOVIZ_TUTARI else K.BORC end AS BORC ,
                                                case when (TUR = 98)or(EKSTREDEKULLAN=1) AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end AS ALACAK ,
                                                case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end AS KUR ,
                                                case when DOVIZ_KURU=@RaporDoviz AND BORC>0   THEN K.DOVIZ_TUTARI 
                                                                                                                when DOVIZ_KURU=@RaporDoviz AND ALACAK>0 THEN -1*K.DOVIZ_TUTARI 
                                                                                                                when K.TUR=88 then K.DOVIZ_TUTARI 
                                                                                                                when K.TUR=98 then -1*K.DOVIZ_TUTARI 
                                                                                else K.BORC-K.ALACAK end AS ISLEMTUTARI ,
                                               ISLEMTARIHI

                                                AS VADE From 
                                                               KASA K  left outer join 
                                                               REHBER R on K.REHBERID=R.ID left outer join 
                                                               KASALAR KS on KS.ID= K.HESAPID                                          
                                               Where 
                                                                              K.REHBERID=@RehberID  and 
                                                                             -- ((K.BORC<>0.0)or(K.ALACAK<>0.0)) and
                                                                              K.ISLEMTARIHI<=''$Bitis$ 23:59:59'' and 
                                                                              ((K.TUR in (49))or(K.TUR not between 40 and 79)) and 
                                                                              K.TUR<>2
                               UNION ALL
                                               Select F.ID AS ISLEMID , FATURATARIH as TARIH,FATURANO as NO, F.TUR,
                                                               (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ) AS TURAD ,
                                                               case
                                                                              when F.TIPI=2 
                                                                                              then ''IADE ''||coalesce(F.ACIKLAMA,'''')
                                                                              when 1 in (select 1 from FATURA where FATBASID=F.ID and ID in (select YERID from FATURA where REHBERID=@RehberID and YERI in (416,417)))  
                                                                                              then ''IADESI VAR ''||coalesce(F.ACIKLAMA,'''')
                                                                              else coalesce(F.ACIKLAMA,'''') end AS ACIKLAMA , 
                                                               null AS HESAPKODU , null AS HESAPADI ,
                                                               case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end  AS BORC ,
                                                               case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end AS ALACAK ,
                                                                case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end AS KUR ,
                                                                
                                                                                              case when F.RAPORDOVIZ =  @RaporDoviz AND F.TUR IN (15,16,17) then F.DOVIZ_TUTARI 
                                                                                                               when F.RAPORDOVIZ =  @RaporDoviz AND F.TUR IN (8,11,12,13) then -1*F.DOVIZ_TUTARI
                                                                                                              when F.RAPORDOVIZ <> @RaporDoviz AND F.TUR IN (15,16,17) then F.FATURA_TUTARI 
                                                                                                               when F.RAPORDOVIZ <> @RaporDoviz AND F.TUR IN (8,11,12,13) then -1*F.FATURA_TUTARI
                                                               end AS ISLEMTUTARI ,
                                                               F.FATURATARIH+coalesce(F.VADE,0)
                                                AS VADE From 
                                                               FATBASLIK F  inner join 
                                                               REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6 
                                               Where 
                                                               F.FATURA_TUTARI <> 0.0 and
                                                               F.REHBERID=@RehberID and F.FATURATARIH<=''$Bitis$ 23:59:59''

                               ---- Çek
                               UNION ALL

                                               Select CH.ID AS ISLEMID ,
                                                               CH.TARIH, MAKBUZNO as NO, case when CH.ISLEM in(130,141) then 23 else 33 end AS TUR ,
                                                               (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ) AS TURAD ,
                                                               case when CH.ISLEM in (137,141) then ''IADE ''
                                                                                                              when C.ID in (select CH1.CEKSENETLERID from CEKHAREKET CH1 where CH1.TARIH <= ''$Bitis$ 23:59:59'' and CH1.ISLEM in (137,141)) then ''IADESI VAR ''
                                                                                                              else '''' end || ''Serino:''||cast(C.SERINO as varchar)||'' ''||rtrim(coalesce(CH.ACIKLAMA,'''')) AS ACIKLAMA ,
                                                               BH.HESAPKODU AS HESAPKODU , BH.HESAPADI AS HESAPADI ,
                                                               Case when CH.ISLEM in(140,131,132,133,134,137) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS BORC ,
                                                               Case when CH.ISLEM in(130,141) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS ALACAK ,
                                                               case when C.EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end AS KUR ,
                                                                case      when C.DOVIZ_KURU=@RaporDoviz AND CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI
                                                                                                                                             when C.DOVIZ_KURU=@RaporDoviz AND CH.ISLEM in(130,141) then -1*C.DOVIZ_TUTARI
                                                                                                                                             when C.DOVIZ_KURU<>@RaporDoviz AND CH.ISLEM in(140,131,132,133,134,137) then C.TUTAR
                                                                                                                                             when C.DOVIZ_KURU<>@RaporDoviz AND CH.ISLEM in(130,141) then -1*C.TUTAR
                                                                                                                             end AS ISLEMTUTARI ,
                                                               VADE
                                               From 
                                                               CEKLER C  inner join
                                                               CEKHAREKET CH on C.ID=CH.CEKSENETLERID left outer join 
                                                               REHBER R on CH.REHBERID=R.ID left outer join 
                                                               BANKAHESAPLAR BH on CH.BANKAHESAPLARID=BH.ID
                                               Where 
                                                               CH.ISLEM in(130,131,132,134,137,140,141) and
                                                               C.TUTAR <> 0.0 and
                                                               CH.REHBERID=@RehberID and 
                                                               CH.TARIH <= ''$Bitis$ 23:59:59''

                               ---- Senet

                               UNION ALL

                               Select C.ID AS ISLEMID ,
                                               TARIH, MAKBUZNO as NO,C.TUR, (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ) AS TURAD ,
                                               rtrim(NOTLAR) AS ACIKLAMA , null AS HESAPKODU , null AS HESAPADI ,
                                               Case when C.TUR=34 then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS BORC ,
                                               Case when C.TUR=24 then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS ALACAK ,
                                               case when C.EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end AS KUR ,
                                                case when DOVIZ_KURU=@RaporDoviz AND C.TUR=34 then C.DOVIZ_TUTARI when DOVIZ_KURU=@RaporDoviz AND C.TUR=24 then -1*C.DOVIZ_TUTARI
                                               when DOVIZ_KURU<>@RaporDoviz AND C.TUR=34 then C.TUTAR when DOVIZ_KURU<>@RaporDoviz AND C.TUR=24 then -1*C.TUTAR
                                               end AS ISLEMTUTARI ,
                                               VADE
                               From 
                                               SENETLER C  inner join 
                                               REHBER R on C.REHBERID=R.ID 
                               Where
                                                               C.REHBERID=@RehberID and 
                                                               C.TUTAR <> 0.0 and
                                                               C.TARIH <= ''$Bitis$ 23:59:59'' 

                               ) as xxx
                where ALACAK>0.0
                order by dateadd(millisecond,ISLEMID,VADE)



                insert #tmpBorclar
                select @RehberID,
                                dateadd(millisecond,ISLEMID,TARIH) AS ISLEMTARIHI ,dateadd(millisecond,ISLEMID,VADE) AS VADESONU ,TURAD AS ISLEMTURU ,NO AS BELGENO ,ACIKLAMA,BORC,KUR,
                               ISLEMTUTARI AS ISLEMTUTARI ,
                               SUM(case when BORC>0.0 then ISLEMTUTARI else 0.0 end) OVER ( ORDER BY dateadd(millisecond,ISLEMID,VADE)) 
                 AS KUMULATIFBORC from
                               (
                               Select K.ID AS ISLEMID ,
                                               ISLEMTARIHI AS TARIH,BELGENO as NO, K.TUR,
                                                           case when K.TUR like ''26__'' then (select ANAHTAR || '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
                                                                                                              when K.TUR like ''36__'' then (select ANAHTAR || '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
                                                                                              else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end AS TURAD , 
                                               K.ACIKLAMA, 
                                               case HESAPTURU when ''B'' then (select HESAPKODU from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
                                                                                                                                             when ''H'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''|| (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)||'')'','''')
                                                                                                                                             when ''K'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)
                                                                                                                                             when ''P'' then (select KODU from POS P where P.ID=K.HESAPID)
                                                                                                                                             when ''V'' then (select KODU from KREDIKARTI KK where KK.ID=K.HESAPID) end AS HESAPKODU ,
                                               case HESAPTURU  when ''B'' then (select HESAPADI from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
                                                                                                                                             when ''H'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''|| (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)||'')'','''')
                                                                                                                                             when ''K'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)
                                                                                                                                             when ''P'' then (select ADI from POS P where P.ID=K.HESAPID)
                                                                                                                                             when ''V'' then (select ADI from KREDIKARTI KK where KK.ID=K.HESAPID) end AS HESAPADI ,
                                                case when (TUR = 88)or(EKSTREDEKULLAN=1 AND BORC>0)   then K.DOVIZ_TUTARI else K.BORC end AS BORC ,
                                                case when (TUR = 98)or(EKSTREDEKULLAN=1 AND ALACAK>0) then K.DOVIZ_TUTARI else K.ALACAK end AS ALACAK ,
                                                case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end AS KUR ,
                                                case when DOVIZ_KURU=@RaporDoviz AND BORC>0   THEN K.DOVIZ_TUTARI 
                                                                                                                when DOVIZ_KURU=@RaporDoviz AND ALACAK>0 THEN -1*K.DOVIZ_TUTARI 
                                                                                                                when K.TUR=88 then K.DOVIZ_TUTARI 
                                                                                                                when K.TUR=98 then -1*K.DOVIZ_TUTARI 
                                                                                else K.BORC-K.ALACAK end AS ISLEMTUTARI ,
                                               ISLEMTARIHI

                                                AS VADE From --select * from REHBER where ID=4118
                                                               KASA K  left outer join 
                                                               REHBER R on K.REHBERID=R.ID left outer join 
                                                               KASALAR KS on KS.ID= K.HESAPID                                          
                                               Where 
                                                                              K.REHBERID=@RehberID  and 
                                                                              --((K.BORC<>0.0)or(K.ALACAK<>0.0)) and
                                                                              K.ISLEMTARIHI<=''$Bitis$ 23:59:59'' and 
                                                                              ((K.TUR in (49))or(K.TUR not between 40 and 79)) and 
                                                                              K.TUR<>2
                               UNION ALL
                                               Select F.ID AS ISLEMID , FATURATARIH as TARIH,FATURANO as NO, F.TUR,
                                                               (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ) AS TURAD ,
                                                               case
                                                                              when F.TIPI=2 
                                                                                              then ''IADE ''||coalesce(F.ACIKLAMA,'''')
                                                                              when 1 in (select 1 from FATURA where FATBASID=F.ID and ID in (select YERID from FATURA where REHBERID=@RehberID and YERI in (416,417)))  
                                                                                              then ''IADESI VAR ''||coalesce(F.ACIKLAMA,'''')
                                                                              else coalesce(F.ACIKLAMA,'''') end AS ACIKLAMA , 
                                                               null AS HESAPKODU , null AS HESAPADI ,
                                                               case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end  AS BORC ,
                                                               case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end AS ALACAK ,
                                                                case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end AS KUR ,
                                                                
                                                                                              case when F.RAPORDOVIZ =  @RaporDoviz AND F.TUR IN (15,16,17) then F.DOVIZ_TUTARI 
                                                                                                               when F.RAPORDOVIZ =  @RaporDoviz AND F.TUR IN (8,11,12,13) then -1*F.DOVIZ_TUTARI
                                                                                                              when F.RAPORDOVIZ <> @RaporDoviz AND F.TUR IN (15,16,17) then F.FATURA_TUTARI 
                                                                                                               when F.RAPORDOVIZ <> @RaporDoviz AND F.TUR IN (8,11,12,13) then -1*F.FATURA_TUTARI
                                                               end AS ISLEMTUTARI ,
                                                               F.FATURATARIH+coalesce(F.VADE,0)
                                                AS VADE From 
                                                               FATBASLIK F  inner join 
                                                               REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6 
                                               Where 
                                                               F.FATURA_TUTARI <> 0.0 and
                                                               F.REHBERID=@RehberID and F.FATURATARIH<=''$Bitis$ 23:59:59''

                               ---- Çek
                               UNION ALL

                                               Select CH.ID AS ISLEMID ,
                                                               CH.TARIH, MAKBUZNO as NO, case when CH.ISLEM in(130,141) then 23 else 33 end AS TUR ,
                                                               (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ) AS TURAD ,
                                                               case when CH.ISLEM in (137,141) then ''IADE ''
                                                                                                              when C.ID in (select CH1.CEKSENETLERID from CEKHAREKET CH1 where CH1.TARIH <= ''$Bitis$ 23:59:59'' and CH1.ISLEM in (137,141)) then ''IADESI VAR ''
                                                                                                              else '''' end || ''Serino:''||cast(C.SERINO as varchar)||'' ''||rtrim(coalesce(CH.ACIKLAMA,'''')) AS ACIKLAMA ,
                                                               BH.HESAPKODU AS HESAPKODU , BH.HESAPADI AS HESAPADI ,
                                                               Case when CH.ISLEM in(140,131,132,133,134,137) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS BORC ,
                                                               Case when CH.ISLEM in(130,141) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS ALACAK ,
                                                              case when C.EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end AS KUR ,
                                                                case      when C.DOVIZ_KURU=@RaporDoviz AND CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI
                                                                                                                                             when C.DOVIZ_KURU=@RaporDoviz AND CH.ISLEM in(130,141) then -1*C.DOVIZ_TUTARI
                                                                                                                                             when C.DOVIZ_KURU<>@RaporDoviz AND CH.ISLEM in(140,131,132,133,134,137) then C.TUTAR
                                                                                                                                             when C.DOVIZ_KURU<>@RaporDoviz AND CH.ISLEM in(130,141) then -1*C.TUTAR
                                                                                                                             end AS ISLEMTUTARI ,
                                                               VADE
                                               From 
                                                               CEKLER C  inner join
                                                               CEKHAREKET CH on C.ID=CH.CEKSENETLERID left outer join 
                                                               REHBER R on CH.REHBERID=R.ID left outer join 
                                                               BANKAHESAPLAR BH on CH.BANKAHESAPLARID=BH.ID
                                               Where 
                                                               CH.ISLEM in(130,131,132,134,137,140,141) and
                                                               C.TUTAR <> 0.0 and
                                                               CH.REHBERID=@RehberID and 
                                                               CH.TARIH <= ''$Bitis$ 23:59:59''

                               ---- Senet

                               UNION ALL

                               Select C.ID AS ISLEMID ,
                                               TARIH, MAKBUZNO as NO,C.TUR, (select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ) AS TURAD ,
                                               rtrim(NOTLAR) AS ACIKLAMA , null AS HESAPKODU , null AS HESAPADI ,
                                               Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS BORC ,
                                               Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end AS ALACAK ,
                                               case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end AS KUR ,
                                                case when DOVIZ_KURU=@RaporDoviz AND C.TUR=34 then C.DOVIZ_TUTARI when DOVIZ_KURU=@RaporDoviz AND C.TUR=24 then -1*C.DOVIZ_TUTARI
                                               when DOVIZ_KURU<>@RaporDoviz AND C.TUR=34 then C.TUTAR when DOVIZ_KURU<>@RaporDoviz AND C.TUR=24 then -1*C.TUTAR
                                               end AS ISLEMTUTARI ,
                                               VADE
                               From 
                                               SENETLER C  inner join 
                                               REHBER R on C.REHBERID=R.ID 
                               Where
                                                               C.REHBERID=@RehberID and 
                                                               C.TUTAR <> 0.0 and
                                                               C.TARIH <= ''$Bitis$ 23:59:59'' 

                               ) as xxx
                where BORC>0.0
                order by dateadd(millisecond,ISLEMID,VADE)


                if coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0)>coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0)
                               insert into #tmpAlacaklar(REHBERID, ISLEMTARIHI, VADESONU ,ISLEMTURU, BELGENO, ACIKLAMA, ALACAK, KUR, ISLEMTUTARI, KUMULATIFALACAK)
                               values (@RehberID,''$Bitis$ 23:59:59'',''$Bitis$ 23:59:59'',''Kalan Borç'',''-'',''Kalan Borç'',(coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0)-coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0)),
                               @RaporDoviz,(coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0)-coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0)),coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0))
                if coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0)<coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0)
                               insert into #tmpBorclar(REHBERID, ISLEMTARIHI, VADESONU ,ISLEMTURU, BELGENO, ACIKLAMA, BORC, KUR, ISLEMTUTARI, KUMULATIFBORC)
                               values (@RehberID,''$Bitis$ 23:59:59'',''$Bitis$ 23:59:59'',''Kalan Alacak'',''-'',''Kalan Alacak'',(coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0)-coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0)),
                               @RaporDoviz,(coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0)-coalesce((select sum(ISLEMTUTARI) from #tmpBorclar),0.0)),coalesce((select sum(ISLEMTUTARI) from #tmpAlacaklar),0.0))
                

                
                insert into #tmpYaslandirma (REHBERID , ISLEMTARIHI , VADESONU , ISLEMTURU ,ISLEMACIKLAMA , BORCTUTARI , ODEMETARIHI , ODEMETURU , ODEMEACIKLAMA , ODEMETUTARI , ODENENTUTAR )
                select @RehberID AS REHBERID ,
                               B.ISLEMTARIHI,
                               B.VADESONU,
                               B.ISLEMTURU||''(''||B.BELGENO||'')'' AS ISLEMTURU ,
                               B.ACIKLAMA AS ISLEMACIKLAMA ,
                               B.ISLEMTUTARI AS BORCTUTARI ,
                               A.ISLEMTARIHI AS ODEMETARIHI ,
                               A.ISLEMTURU||''(''||A.BELGENO||'')'' AS ODEMETURU ,
                               A.ACIKLAMA AS ODEMEACIKLAMA ,
                               A.ISLEMTUTARI AS ODEMETUTARI ,
                               (case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end) - coalesce(lag(case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end) over (order by case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end),0.0)


                 AS ODENENTUTAR from 
                               #tmpAlacaklar as A join
                               #tmpBorclar as B on
                                               B.KUMULATIFBORC-B.ISLEMTUTARI<A.KUMULATIFALACAK and
                                               A.KUMULATIFALACAK-A.ISLEMTUTARI<B.KUMULATIFBORC
                fetch next from crs into @RehberID
END
close crs
deallocate crs

--select * from #tmpYaslandirma

select
                KOD,FIRMA,TUTAR AS AÇIK HESAP R.L (TL),
                BORC TOPLAM=cast(sum(BORC TOPLAM) as money),
                BORC 0-=cast(sum(BORC 0-) as money),
                BORC 1-30=cast(sum(BORC 1-30) as money),
                BORC 30-60=cast(sum(BORC 30-60) as money),
                BORC 60-90=cast(sum(BORC 60-90) as money),
                BORC 90-120=cast(sum(BORC 90-120) as money),
                BORC 120-180=cast(sum(BORC 120-180) as money),
                BORC 180-360=cast(sum(BORC 180-360) as money),
                BORC 360+=cast(sum(BORC 360+) as money)

from (
                select 
                               R.KOD,R.FIRMA,RK.TUTAR,
                               BORC TOPLAM=(case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end),
                               BORC 0-=case when cast((ODEMETARIHI-VADESONU) as integer) <= 0 then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 1-30=case when (cast((ODEMETARIHI-VADESONU) as integer) > 0) and (cast((ODEMETARIHI-VADESONU) as integer) <= 30) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 30-60=case when (cast((ODEMETARIHI-VADESONU) as integer) > 30) and (cast((ODEMETARIHI-VADESONU) as integer) <= 60) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 60-90=case when (cast((ODEMETARIHI-VADESONU) as integer) > 60) and (cast((ODEMETARIHI-VADESONU) as integer) <= 90) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 90-120=case when (cast((ODEMETARIHI-VADESONU) as integer) > 90) and (cast((ODEMETARIHI-VADESONU) as integer) <= 120) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 120-180=case when (cast((ODEMETARIHI-VADESONU) as integer) > 120) and (cast((ODEMETARIHI-VADESONU) as integer) <= 180) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 180-360=case when (cast((ODEMETARIHI-VADESONU) as integer) > 180) and (cast((ODEMETARIHI-VADESONU) as integer) <= 360) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                               BORC 360+=case when (cast((ODEMETARIHI-VADESONU) as integer) > 360) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end 
                from #tmpYaslandirma T inner join REHBER R on T.REHBERID=R.ID
				LEFT OUTER JOIN REHBER_KOTA RK ON RK.REHBERID=R.ID
                where ODEMEACIKLAMA = ''Kalan Borç'' or ISLEMACIKLAMA=''Kalan Alacak''
)as XX 
group by KOD,FIRMA,TUTAR
' WHERE id = 1356;
UPDATE public.dokumler SET sql = '/*PGX*/select URUNID,S.KOD,S.STOKADI,(SELECT AD FROM KATEGORI K WHERE K.ID=S.KATEGORI) AS KATEGORI ,
(SELECT DEPOADI FROM DEPOLAR WHERE ID=DEPO) AS DEPO ,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA) AS MARKA ,
round(GIREN,2) AS GIREN ,round(CIKAN,2) AS CIKAN ,round(KALAN,2) AS KALAN ,Mlt.BIRIMMALIYET,DRM.KALAN*Mlt.BIRIMMALIYET
 AS MALIYET from STOKLAR S inner join 
                (SELECT DEPO,URUNID,
                               round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN , 
                               round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN , 
                               round(SUM(NETMIKTAR),2)
                 AS KALAN FROM( SELECT GIRISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
                                               FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
                                               WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1
                                               AND FB.FATURATARIH <= ''$Bitis$ 23:59''             AND FB.TUR <> 2
                                               UNION ALL
                                               SELECT CIKISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
                                               FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
                                               WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1 AND FB.TUR <> 2
                                               AND FB.FATURATARIH <= ''$Bitis$ 23:59''
                               ) AS ASD GROUP BY URUNID,DEPO
                HAVING SUM(NETMIKTAR)<>0.0
                )as DRM on S.ID=DRM.URUNID left join 
                (select STOKID,BIRIMMALIYET,ROW_NUMBER() OVER(PARTITION BY STOKID ORDER BY TARIH desc)  AS NUM from STOK_ORT_MALIYET SM)as Mlt on Mlt.STOKID=S.ID
                LEFT JOIN DEPOLAR D ON D.ID = DRM.DEPO
where Mlt.NUM=1 and S.KOD LIKE ''$StokKod$%''
AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
and  coalesce(D.DEPOADI,'''') LIKE ''$DepoAdi$%''' WHERE id = 1357;
UPDATE public.dokumler SET sql = '/*PGX*/



   --DENEME
SELECT * FROM 
(
SELECT *,GECEN_GUN=DATEDIFF( DAY,SONHAREKETTARIHI,''$Bitis$ 23:59''),
	YIL=year(SONHAREKETTARIHI),
	AY=month(SONHAREKETTARIHI),TOPMALIYET= KALAN*SONBIRIMMALIYET,
    0-120=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI<121.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    121-180=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=121.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<181.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    181-480=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=181.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<481.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    481-990=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=481.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<991.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    991-1500=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=991.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<1501.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    1501-3000=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=1501.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<3001.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    3001+=case when KALAN >= 3001 then KALAN*SONBIRIMMALIYET else 0.0 end  	        
FROM(
	SELECT 
		S.KOD,S.STOKADI,
		SONHAREKETTARIHI=(SELECT FATURATARIH FROM FATBASLIK FB 
			WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND 
			FB.TUR<>2 AND	FB.FATURATARIH <= ''$Bitis$ 23:59'' AND FB.ID IN (SELECT FATBASID FROM FATURA F WHERE URUNID = S.ID AND F.TUR = 1) ORDER BY 1 DESC LIMIT 1 ),
		SONBIRIMMALIYET=(SELECT SOM.BIRIMMALIYET FROM STOK_ORT_MALIYET SOM  WHERE  STOKID=S.ID ORDER BY TARIH DESC LIMIT 1 ),
		KALAN=(	SELECT SUM(KALAN) FROM
		(
    
	    SELECT KALAN=CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END 
            FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
            WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND
			FB.TUR<>2 AND FB.FATURATARIH <= ''$Bitis$ 23:59'' AND  F.URUNID=S.ID AND (F.STOKDURUMDEGIS = 1) AND 
			(coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1
                                               
            UNION ALL
            SELECT KALAN= CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END 
            FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
            WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND
			FB.TUR<>2 AND   FB.FATURATARIH <= ''$Bitis$ 23:59'' AND F.URUNID=S.ID AND (F.STOKDURUMDEGIS = 1) AND 
			(coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
                )
		AS aaa )  											   
	FROM  
		STOKLAR S  
		)AS BBB     
	) AS XXX

WHERE SONHAREKETTARIHI IS NOT NULL
AND KALAN>0  
ORDER BY 6
' WHERE id = 1358;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT  TARIH,SERVISNO,FIRMA,KONUSU,MUS_ILGILI,AD,SERINO,PERSONEL,MUDAHALETUR, IL,
SEYAHATBAS,
SERVISBAS,
SERVISBIT,
SEYAHATBIT,
(SERVISBAS-SEYAHATBAS)+(SEYAHATBIT-SERVISBIT)-(SMOLABIT-SMOLABAS) AS SEYAHATSURESI ,
(SERVISBIT-SERVISBAS)-(MOLABIT-MOLABAS) AS TOPLAM_MESAI_SURESI ,
CASE WHEN DATEPART(WEEKDAY,SERVISBAS)=7 THEN SERVISBIT-SERVISBAS ELSE 0.0 END AS CMT_MESAI_SURESI ,
CASE WHEN DATEPART(WEEKDAY,SERVISBAS)=1 THEN SERVISBIT-SERVISBAS ELSE 0.0 END AS PZR_MESAI_SURESI ,
case 
       when cast(SERVISBAS as varchar) like '' 2/10/%'' then SERVISBIT-SERVISBAS --''Ramazan Bayrami 1.Günü''
       when cast(SERVISBAS as varchar) like '' 3/10/%'' then SERVISBIT-SERVISBAS --''Ramazan Bayrami 2.Günü''
       when cast(SERVISBAS as varchar) like '' 4/10/%'' then SERVISBIT-SERVISBAS --''Ramazan Bayrami 3.Günü''
       when cast(SERVISBAS as varchar) like ''10/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 1.Günü''
       when cast(SERVISBAS as varchar) like ''11/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 2.Günü''
       when cast(SERVISBAS as varchar) like ''12/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 3.Günü''
       when cast(SERVISBAS as varchar) like ''13/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 4.Günü''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-01-01%'' then SERVISBIT-SERVISBAS --''Yilbasi''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-04-23%'' then SERVISBIT-SERVISBAS --''Ulusal Egemenlik ve Çocuk Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-05-19%'' then SERVISBIT-SERVISBAS --''Atatürk’ü Anma Gençlik ve Spor Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-08-30%'' then SERVISBIT-SERVISBAS --''Zafer Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-10-29%'' then SERVISBIT-SERVISBAS --''Cumhuriyet Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-05-01%'' then SERVISBIT-SERVISBAS --''Isçi Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-07-15%'' then SERVISBIT-SERVISBAS --''Demokrasi ve Milli Birlik''
       ELSE 0.0 END AS RESMI_TATIL_MESAI ,

--NORMAL_MESAI_SURESI=CASE WHEN DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6) THEN (DATEDIFF(MINUTE,SERVISBAS,(CASE 
--                                                    WHEN DATEPART(HOUR,SERVISBIT)>=18 
--                                                    THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) 
--                                                    ELSE SERVISBIT
--                                                    END))-DATEDIFF(MINUTE,MOLABAS,MOLABIT))/60.0 
--                                                                                              ELSE 0.0 END,
CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) AND to_char(SERVISBIT,''HH24:MI:SS'')>=''18:01''
                   THEN SERVISBIT-
						CASE WHEN to_char(SERVISBAS,''HH24:MI:SS'')<=''18:00''
								THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) 
							 WHEN to_char(SERVISBAS,''HH24:MI:SS'')>''18:00''
								THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),DATEPART(HOUR,SERVISBAS),DATEPART(MINUTE,SERVISBAS),0,0)
							 END 
				   ELSE 0.0 END AS FAZLA_MESAI_SURESI , -- DÜZELTME IRMAK ÖNDER 2018.12.19
					--CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) AND (DATEPART(HOUR,SERVISBIT)>=18)
     --              THEN SERVISBIT-DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) ELSE 0.0 END,
CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBIT,''HH24:MI:SS'')>=''18:00''
				THEN SEYAHATBIT-SERVISBIT
              
                          WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBIT,''HH24:MI:SS'')<=''18:00''
                          AND to_char(SEYAHATBIT,''HH24:MI:SS'')>=''18:00''
				THEN SEYAHATBIT-DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0)
              
		 WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBAS,''HH24:MI:SS'')>=''18:00''
				THEN (SERVISBAS- DATETIMEFROMPARTS(YEAR(SERVISBAS),MONTH(SERVISBAS),DAY(SERVISBAS),18,0,0,0))
					 +SEYAHATBIT-SERVISBIT
		 WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')>=''18:00''			  
				THEN (SERVISBAS- SEYAHATBAS)
					 +(SEYAHATBIT-SERVISBIT)
                           WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (1,7)) 
			  			  
				THEN SEYAHATBIT-SERVISBIT
		ELSE 0.0
		END AS FAZLA_MESAI_SEYAHAT , -- DÜZELTME IRMAK ÖNDER 2018.12.19
								 --case 
         --                        when (DATEPART(HOUR,SERVISBIT)<18) and (DATEPART(HOUR,SEYAHATBIT)>=18) 
         --                        then SEYAHATBIT-DATETIMEFROMPARTS(YEAR(SEYAHATBIT),MONTH(SEYAHATBIT),DAY(SEYAHATBIT),18,0,0,0)
         --                        when (DATEPART(HOUR,SERVISBIT)>=18) and (DATEPART(HOUR,SEYAHATBIT)>=18) 
         --                        then SEYAHATBIT-SERVISBIT
         --                        else 0.0 end,

 MOLABIT-MOLABAS AS MOLA_SURESI ,
SMOLABIT-SMOLABAS AS SMOLA_SURESI ,DURUM 
FROM (
    SELECT 
    S.TARIH,S.SERVISNO,R.FIRMA,S.KONUSU,R1.FIRMA AS MUS_ILGILI ,E.AD,S.SERINO,R2.FIRMA AS PERSONEL ,
    (SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=40 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SEYAHATBAS ,
    (SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=5 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SERVISBAS ,
    (SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=5 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SERVISBIT ,
    (SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=42 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SEYAHATBIT ,
    (SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=44 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS MOLABAS ,
    (SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=44 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS MOLABIT ,
    (SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=46 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SMOLABAS ,
    (SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=46 AND SH1.ACIKLAMA=SH.ACIKLAMA) AS SMOLABIT ,
       coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=(SELECT ID FROM REHBERILETISIM RI WHERE RI.REHBERID=R.ID ORDER BY RI.VARSAYILAN DESC LIMIT 1 )   AND RA.VARSAYILAN=8 LIMIT 1 ),'''')  AS IL ,
    G1.ANAHTAR AS MUDAHALETUR , 
 CASE WHEN S.ACKAPA = 0 THEN ''AÇIK'' ELSE ''KAPALI'' END
                
     AS DURUM FROM SERVIS S 
        INNER JOIN (SELECT DISTINCT SERVISID,PERSONEL,ACIKLAMA FROM SERVISHAREKET WHERE DURUM <> 1 and DURUM <> 47 and DURUM <> 48 and DURUM <> 49 and DURUM <> 15) SH ON SH.SERVISID=S.ID 
        INNER JOIN EKIPMANREHBER ER ON ER.ID=S.EKIPMANREHBERID
        INNER JOIN EKIPMANLAR E ON E.ID=S.EKIPMANID
        INNER JOIN REHBER R ON R.ID=S.REHBERID
        INNER JOIN REHBER R1 ON R1.ID=S.MUS_ILGILI
        INNER JOIN REHBER R2 ON R2.ID=SH.PERSONEL
        INNER JOIN GENINI G1 ON S.TURU=G1.DEGER AND G1.BOLUM=-3006  


		WHERE  S.TARIH>=''$Baslangic$ 00:00:00'' AND  S.TARIH<=''$Bitis$ 23:59:00''
    

) AS XXX
    WHERE DURUM  LIKE ''%$Ackapa$%''
    AND  PERSONEL  LIKE ''%$Firma$%''
ORDER BY TARIH' WHERE id = 1360;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT DISTINCT --A
UE.ID,fn_TarihFarkiFormatli( UOP.BASLAMA, UOP.BITIS-UOP.MOLA-2.0 ) AS SURE ,
UOP.TARIH,R.FIRMA AS PERSONEL ,PDK.GIRIS,
(SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2211 AND G.DEGER=PDK.DURUM AND R.ID=PDK.REHBERID) AS PERS_DURUM ,
UOP.KONUSU,UOP.BASLAMA,UOP.BITIS,UOP.MOLA,G.ANAHTAR AS DURUM,P.PROJEADI,P.PROJEKODU,S.KOD,S.STOKADI

FROM REHBER R INNER JOIN PERS_PDKS PDK ON PDK.REHBERID=R.ID AND PDK.GIRIS between ''$baslama$ 00:00''  and ''$baslama$ 23:59''
		LEFT OUTER JOIN URETIMOPERASYONPERSONEL UOP ON UOP.PERSONEL=R.ID AND UOP.TARIH between ''$baslama$ 00:00''  and ''$baslama$ 23:59''
		LEFT OUTER JOIN  URETIMOPERASYON UO ON UOP.OPERASYONID=UO.ID
		LEFT OUTER JOIN  URETIMEMRI UE ON UE.ID=UO.URETIMEMRIID
		LEFT OUTER JOIN PROJELER P ON P.ID=UE.PROJEID
		LEFT OUTER JOIN GENINI G ON G.DEGER=UOP.DURUM AND G.BOLUM=-3027
		LEFT OUTER JOIN STOKLAR S ON S.ID=UE.STOKID
	
WHERE PDK.ID IS NOT NULL AND            
exists(select 1 from KULLANICI K 
								 inner join ROLLER RO on RO.ID=K.ROLID
								 inner join YETKI Y on Y.ROLID=K.ROLID and Y.MODULID=33062010 and Y.HAK=1 
								 where R.ID=K.REHBERID and ((Y.HAK=1)or(RO.TY=1))) and R.KOD not like ''102.%'' 
								 and R.ID > 0  and R.DURUM > 0    and R.GRUP =335  
								 order by 6 ,4 ,8' WHERE id = 1361;
UPDATE public.dokumler SET sql = '/*PGX*/--AA
SELECT *FROM (
SELECT  TARIH,SERVISNO,FIRMA,KONUSU,MUS_ILGILI,AD,SERINO,PERSONEL,MUDAHALETUR, IL,
SEYAHATBAS,
SERVISBAS,
SERVISBIT,
SEYAHATBIT,
SEYAHATSURESI=(SERVISBAS-SEYAHATBAS)+(SEYAHATBIT-SERVISBIT)-(SMOLABIT-SMOLABAS),
TOPLAM_MESAI_SURESI=(SERVISBIT-SERVISBAS)-(MOLABIT-MOLABAS),
CMT_MESAI_SURESI=CASE WHEN DATEPART(WEEKDAY,SERVISBAS)=7 THEN SERVISBIT-SERVISBAS ELSE 0.0 END,
PZR_MESAI_SURESI=CASE WHEN DATEPART(WEEKDAY,SERVISBAS)=1 THEN SERVISBIT-SERVISBAS ELSE 0.0 END,
RESMI_TATIL_MESAI=case 
       when cast(SERVISBAS as varchar) like '' 2/10/%'' then SERVISBIT-SERVISBAS --''Ramazan Bayrami 1.Günü''
       when cast(SERVISBAS as varchar) like '' 3/10/%'' then SERVISBIT-SERVISBAS --''Ramazan Bayrami 2.Günü''
       when cast(SERVISBAS as varchar) like '' 4/10/%'' then SERVISBIT-SERVISBAS --''Ramazan Bayrami 3.Günü''
       when cast(SERVISBAS as varchar) like ''10/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 1.Günü''
       when cast(SERVISBAS as varchar) like ''11/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 2.Günü''
       when cast(SERVISBAS as varchar) like ''12/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 3.Günü''
       when cast(SERVISBAS as varchar) like ''13/12/%'' then SERVISBIT-SERVISBAS --''Kurban Bayrami 4.Günü''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-01-01%'' then SERVISBIT-SERVISBAS --''Yilbasi''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-04-23%'' then SERVISBIT-SERVISBAS --''Ulusal Egemenlik ve Çocuk Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-05-19%'' then SERVISBIT-SERVISBAS --''Atatürk’ü Anma Gençlik ve Spor Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-08-30%'' then SERVISBIT-SERVISBAS --''Zafer Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-10-29%'' then SERVISBIT-SERVISBAS --''Cumhuriyet Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-05-01%'' then SERVISBIT-SERVISBAS --''Isçi Bayrami''
       when to_char(SERVISBAS,''YYYY-MM-DD HH24:MI:SS'') like ''____-07-15%'' then SERVISBIT-SERVISBAS --''Demokrasi ve Milli Birlik''
       ELSE 0.0 END,

--NORMAL_MESAI_SURESI=CASE WHEN DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6) THEN (DATEDIFF(MINUTE,SERVISBAS,(CASE 
--                                                    WHEN DATEPART(HOUR,SERVISBIT)>=18 
--                                                    THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) 
--                                                    ELSE SERVISBIT
--                                                    END))-DATEDIFF(MINUTE,MOLABAS,MOLABIT))/60.0 
--                                                                                              ELSE 0.0 END,
FAZLA_MESAI_SURESI=CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) AND to_char(SERVISBIT,''HH24:MI:SS'')>=''18:01''
                   THEN SERVISBIT-
						CASE WHEN to_char(SERVISBAS,''HH24:MI:SS'')<=''18:00''
								THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) 
							 WHEN to_char(SERVISBAS,''HH24:MI:SS'')>''18:00''
								THEN DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),DATEPART(HOUR,SERVISBAS),DATEPART(MINUTE,SERVISBAS),0,0)
							 END 
				   ELSE 0.0 END, -- DÜZELTME IRMAK ÖNDER 2018.12.19
					--CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) AND (DATEPART(HOUR,SERVISBIT)>=18)
     --              THEN SERVISBIT-DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0) ELSE 0.0 END,
FAZLA_MESAI_SEYAHAT=CASE WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBIT,''HH24:MI:SS'')>=''18:00''
				THEN SEYAHATBIT-SERVISBIT
              
                          WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBIT,''HH24:MI:SS'')<=''18:00''
                          AND to_char(SEYAHATBIT,''HH24:MI:SS'')>=''18:00''
				THEN SEYAHATBIT-DATETIMEFROMPARTS(YEAR(SERVISBIT),MONTH(SERVISBIT),DAY(SERVISBIT),18,0,0,0)
              
		 WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')<=''18:00''
			  AND to_char(SERVISBAS,''HH24:MI:SS'')>=''18:00''
				THEN (SERVISBAS- DATETIMEFROMPARTS(YEAR(SERVISBAS),MONTH(SERVISBAS),DAY(SERVISBAS),18,0,0,0))
					 +SEYAHATBIT-SERVISBIT
		 WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (2,3,4,5,6)) 
			  AND to_char(SEYAHATBAS,''HH24:MI:SS'')>=''18:00''			  
				THEN (SERVISBAS- SEYAHATBAS)
					 +(SEYAHATBIT-SERVISBIT)
                           WHEN (DATEPART(WEEKDAY,SERVISBAS)IN (1,7)) 
			  			  
				THEN SEYAHATBIT-SERVISBIT
		ELSE 0.0
		END, -- DÜZELTME IRMAK ÖNDER 2018.12.19
								 --case 
         --                        when (DATEPART(HOUR,SERVISBIT)<18) and (DATEPART(HOUR,SEYAHATBIT)>=18) 
         --                        then SEYAHATBIT-DATETIMEFROMPARTS(YEAR(SEYAHATBIT),MONTH(SEYAHATBIT),DAY(SEYAHATBIT),18,0,0,0)
         --                        when (DATEPART(HOUR,SERVISBIT)>=18) and (DATEPART(HOUR,SEYAHATBIT)>=18) 
         --                        then SEYAHATBIT-SERVISBIT
         --                        else 0.0 end,

MOLA_SURESI= MOLABIT-MOLABAS,
SMOLA_SURESI=SMOLABIT-SMOLABAS,DURUM 
FROM (
    SELECT 
    S.TARIH,S.SERVISNO,R.FIRMA,S.KONUSU,MUS_ILGILI=R1.FIRMA,E.AD,S.SERINO,PERSONEL=R2.FIRMA,
    SEYAHATBAS=(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=40 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    SERVISBAS=(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=5 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    SERVISBIT=(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=5 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    SEYAHATBIT=(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=42 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    MOLABAS=(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=44 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    MOLABIT=(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=44 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    SMOLABAS=(SELECT BASLAMA FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=46 AND SH1.ACIKLAMA=SH.ACIKLAMA),
    SMOLABIT=(SELECT BITIS FROM SERVISHAREKET SH1 WHERE SH1.SERVISID=SH.SERVISID AND DURUM=46 AND SH1.ACIKLAMA=SH.ACIKLAMA),
       IL=coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI WHERE RB.YER_ID=(SELECT ID FROM REHBERILETISIM RI WHERE RI.REHBERID=R.ID ORDER BY RI.VARSAYILAN DESC LIMIT 1 )   AND RA.VARSAYILAN=8 LIMIT 1 ),'''') ,
    G1.ANAHTAR AS MUDAHALETUR , 
DURUM= CASE WHEN S.ACKAPA = 0 THEN ''AÇIK'' ELSE ''KAPALI'' END
                
    FROM SERVIS S 
        INNER JOIN (SELECT DISTINCT SERVISID,PERSONEL,ACIKLAMA FROM SERVISHAREKET WHERE DURUM <> 1 and DURUM <> 47 and DURUM <> 48 and DURUM <> 15 and DURUM <> 49) SH ON SH.SERVISID=S.ID 
        INNER JOIN EKIPMANREHBER ER ON ER.ID=S.EKIPMANREHBERID
        INNER JOIN EKIPMANLAR E ON E.ID=S.EKIPMANID
        INNER JOIN REHBER R ON R.ID=S.REHBERID
        INNER JOIN REHBER R1 ON R1.ID=S.MUS_ILGILI
        INNER JOIN REHBER R2 ON R2.ID=SH.PERSONEL
        INNER JOIN GENINI G1 ON S.TURU=G1.DEGER AND G1.BOLUM=-3006  


		WHERE  S.TARIH>=''$Baslangic$ 00:00:00'' AND  S.TARIH<=''$Bitis$ 23:59:00''
    

) AS XXX
    WHERE DURUM  LIKE ''%$Ackapa$%''
    AND  PERSONEL  LIKE ''%$Firma$%''
)AS YY 
    WHERE ((FAZLA_MESAI_SURESI<>0)OR(FAZLA_MESAI_SEYAHAT<>0)OR(CMT_MESAI_SURESI<>0)OR(PZR_MESAI_SURESI<>0)OR(RESMI_TATIL_MESAI<>0)) 
ORDER BY TARIH' WHERE id = 1362;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
ZARF AS ZARF_NO ,FATURATARIH AS BELGE_TARIH ,BELGE_SERI,FATURANO AS BELGE_NO ,CARIKOD AS FIRMA_KOD ,FIRMA,KDVLITOPLAM AS UST_TUTAR ,ISLEMTUR AS TURU ,KOD,AD,ADET AS MIKTAR ,
BIRIMFIYAT*ADET AS IC_TUTAR ,EKMALIYET,
((EKMALIYET/ADET)+BIRIMFIYAT) AS BIRIM_MALIYET ,
EK_MALIYET_YANSIMA
FROM (
SELECT 
fb.OZELKOD,
BZ.AD AS ZARF ,FB.TUR,
 CASE WHEN TIPI=1 THEN ''Alış/Satış'' WHEN TIPI=2 THEN ''İade'' WHEN TIPI=3 THEN ''Fiyat Farkı'' WHEN TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR , 

 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
F.ISKONTO,F.KDV,
FB.KDVDURUM ,
coalesce(ROUND(F.MIKTAR*coalesce(SOM.BIRIMMALIYET,0.0),2),0.0) as TOPLAM_MALİYET,
FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,E.AD AS EAD ,ER.SERINO,E.ACIKLAMA AS SEGMENT ,
F.EKMALIYET,
--CASE WHEN MG.ZARFMALIYETDURUMU =1 AND F.TUR=0 THEN ''Var'' ELSE ''Yok'' END
			CASE WHEN MG.ZARFMALIYETDURUMU =1 THEN ''VAR'' WHEN MG.ZARFMALIYETDURUMU =0 THEN ''YOK'' ELSE '''' END AS EK_MALIYET_YANSIMA ,
FB.FATURASERI
 AS BELGE_SERI FROM 
FATBASLIK FB 
                INNER JOIN FATURA F ON 
                               FB.ID=F.FATBASID							   
			    left outer join STOK_ORT_MALIYET SOM on F.ID=SOM.FATURAID 
                LEFT OUTER JOIN REHBER R ON 
                               FB.REHBERID=R.ID
                LEFT OUTER JOIN MASRAFGELIR MG ON
                               F.MASRAFID=MG.ID-- AND
                LEFT OUTER JOIN REHBERINI RI ON
                               RI.BOLUM=''StokKart_Anabirim'' and
                               RI.DEGER=F.BIRIM
                LEFT OUTER JOIN REHBERINI RI1 ON
                               RI1.BOLUM=''Kasa Türleri'' and
                               RI1.DEGER=FB.TUR
        LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
		 LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
 LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID

WHERE ZARFID >0 AND
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
AND  BZ.AD like ''$AD$%'' AND
FB.TUR IN (8,11,12,15,16)

) AS X

WHERE ADET<>0

ORDER BY ZARF,FATURATUR,FATURATARIH,ISLEMTUR' WHERE id = 1364;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT R.KOD,R.FIRMA,RB.BILGI  AS VADE FROM REHBERBILGI RB INNER JOIN REHBER R ON R.ID=RB.YER_ID WHERE ETIKET LIKE ''%VADE%''  order by 1' WHERE id = 1365;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
FATURATARIH,FATURANO,CARIKOD,FIRMA,MUH_KODU,KOD,AD,ACIKLAMA,ADET,ANAHTAR,
BIRIMFIYAT,
BIRIMFIYAT*ADET AS TUTAR ,
KDV,
TUTAR AS KDVMATRAHI ,
KDVLITOPLAM-TUTAR AS KDVTUTAR ,
KDVLITOPLAM AS GENELTOPLAM ,
DOVIZ_CINSI,
MASRAFKODU,
MASRAFADI,KATEGORIADI,PERSONEL,ACIKLAMA1
FROM (
SELECT 
fb.OZELKOD,
BZ.AD AS ZARF ,FB.TUR,
 CASE WHEN TIPI=1 THEN ''Alış/Satış'' WHEN TIPI=2 THEN ''İade'' WHEN TIPI=3 THEN ''Fiyat Farkı'' WHEN TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
(SELECT R.FIRMA FROM STOKLAR S  INNER JOIN REHBER R ON R.ID=S.URETICI WHERE F.URUNID=S.ID AND F.TUR=1 LIMIT 1 ) AS URETICI_FIRMA ,
 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR , 
 CASE  WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=15 AND F.KDV=0 THEN ''600.1.00'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=15 AND F.KDV=1 THEN ''600.1.01'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=15 AND F.KDV=8 THEN ''600.1.08'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=15 AND F.KDV=18 THEN ''600.1.18'' 
                            
                                WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=11 AND F.KDV=0 THEN ''153.1.00'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=11 AND F.KDV=1 THEN ''153.1.01'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=11 AND F.KDV=8 THEN ''153.1.08'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=1 AND FB.TUR=11 AND F.KDV=18 THEN ''153.1.18''
              
                                WHEN F.TUR IN (1,11)  AND TIPI=2 AND FB.TUR=11 AND F.KDV=0 THEN ''610.1.00'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=2 AND FB.TUR=11 AND F.KDV=1 THEN ''610.1.01'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=2 AND FB.TUR=11 AND F.KDV=8 THEN ''610.1.08'' 
                                                               WHEN F.TUR IN (1,11)  AND TIPI=2 AND FB.TUR=11 AND F.KDV=18 THEN ''610.1.18'' 
                            
                                                               WHEN F.TUR=11 THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID )

END AS MUH_KODU ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID  LIMIT 1 ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
F.ISKONTO,F.KDV,
FB.RAPORDOVIZ AS DOVIZ_CINSI , --F.DOVIZ_TUTARI,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.DOVIZ_TUTARI ELSE F.DOVIZ_TUTARI/(1+(F.KDV/100.0)) END AS DOVIZ_TUTARI ,
CASE WHEN FB.RAPORDOVIZ <> ''TL'' THEN F.DOVIZ_BIRIMFIYAT ELSE 0 END AS DOVIZ_BIRIMFIYAT ,
CASE WHEN FB.RAPORDOVIZ<>''TL'' AND F.DOVIZ_TUTARI>0 THEN ROUND(cast((F.TUTAR/F.ADET)/(F.DOVIZ_TUTARI/F.ADET) as double precision),4) ELSE 0 END  AS KURU ,MG.KOD AS MASRAFKODU,MG.AD AS MASRAFADI,

 CASE WHEN F.TUR IN (1,11) THEN
                                               coalesce(((select K.KOD||''-''||K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ) LIMIT 1 )),''Kategorisiz'')
                                               ELSE 
                                               coalesce(((SELECT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')
                                               END AS KATEGORIADI ,
 CASE WHEN F.TUR IN (1,11) THEN

                                               coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ) LIMIT 1 )),''Grupsuz'')
                                               ELSE 
                                                               ''Grupsuz''
                                               END   AS GRUPADI ,
FB.KDVDURUM ,

(SELECT OZELKOD FROM MASRAFGELIR S where  F.URUNID=S.ID  )   AS OZELKOD_ ,
(SELECT YETKIKODU FROM MASRAFGELIR S where  F.URUNID=S.ID  ) AS YETKIKODU_ ,
coalesce(ROUND(F.MIKTAR*coalesce(SOM.BIRIMMALIYET,0.0),2),0.0) as TOPLAM_MALİYET,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
(SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU=R1.ID) AS PERSONEL ,FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,E.AD AS EAD ,ER.SERINO,E.ACIKLAMA AS SEGMENT ,
(SELECT SERVISNO FROM SERVIS S WHERE S.ID=FB.SERVISID)
 AS SERVISNO FROM 
FATBASLIK FB 
                INNER JOIN FATURA F ON 

                               FB.ID=F.FATBASID
                                                                                                                 
                                                   left outer join STOK_ORT_MALIYET SOM on F.ID=SOM.FATURAID 

                LEFT OUTER JOIN REHBER R ON 

                               FB.REHBERID=R.ID

                LEFT OUTER JOIN MASRAFGELIR MG ON

                               F.MASRAFID=MG.ID-- AND

                LEFT OUTER JOIN REHBERINI RI ON

                               RI.BOLUM=''StokKart_Anabirim'' and

                               RI.DEGER=F.BIRIM

                LEFT OUTER JOIN REHBERINI RI1 ON

                               RI1.BOLUM=''Kasa Türleri'' and

                               RI1.DEGER=FB.TUR

        LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
                               LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID

WHERE

FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 


AND 
FB.TUR IN (11,12)

) AS X

WHERE ADET<>0
                  AND KOD LIKE ''7%''
                  AND KOD LIKE ''$Kod$%''

ORDER BY FATURATUR,GRUPADI,KATEGORIADI,FATURATARIH,ISLEMTUR' WHERE id = 1366;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT          
    FB.ID, 
    FB.SIPARISTARIH AS TALAP_TARIHI,
    FB.SIPARISNO AS TALEP_NO,
    P.PROJEADI,
	P.PROJEKODU,
	S.KOD,
	S.STOKADI,
	F.ADET,
    (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2702 AND G.DEGER=S.ANABIRIM) AS BIRIM ,
    --SONALIS_TL_BIRIM_FIYAT=(SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON F.URUNID=SF.STOKID AND SF.FIYATADI=-1 AND F.TUR=1 LIMIT 1 ),
	(SELECT F1.ISKONTOLUBRMFIYAT FROM FATBASLIK FB1 INNER JOIN FATURA F1 ON F1.FATBASID=FB1.ID
WHERE F1.URUNID=S.ID AND FB1.TUR IN (11,3,12)  AND F1.BIRIMFIYAT <>0.0 ORDER BY FATURATARIH DESC  LIMIT 1 ) AS SONALIS_TL_BIRIM_FIYAT ,
(SELECT F1.ISKONTOLUBRMFIYAT FROM FATBASLIK FB1 INNER JOIN FATURA F1 ON F1.FATBASID=FB1.ID
WHERE F1.URUNID=S.ID AND FB1.TUR IN (11,3,12) AND F1.BIRIMFIYAT <>0.0 ORDER BY FATURATARIH DESC  LIMIT 1 )*F.ADET AS TOPLAM ,
    K.AD as KATEGORI,
    (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2804 AND G.DEGER=S.MARKA) AS MARKA ,
     (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer)) AS MODEL ,         
    (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2704 AND G.DEGER=S.GRUBU) AS GRUBU ,
    D.DEPOADI
FROM 
	SIPARIS FB 
	INNER JOIN SIPARISDETAY F ON FB.ID=F.SIPARISID
    INNER JOIN STOKLAR S ON S.ID=F.URUNID
    INNER JOIN KATEGORI K ON K.ID=S.KATEGORI
    INNER JOIN REHBER R ON R.ID=FB.REHBERID
    INNER JOIN DEPOLAR D ON D.ID=FB.GIRISDEPO
	LEFT OUTER JOIN STOKIZLEME SI ON SI.STOKID=S.ID AND SI.BASLIKID=FB.ID AND SI.SATIRID=F.ID
	LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
WHERE 
	FB.TUR=105 
AND P.PROJEKODU LIKE ''$Kod$%''
AND FB.SIPARISTARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''' WHERE id = 1367;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT                    
ISLEMTUR,FATURATARIH,
--BELGE_AY=month(FATURATARIH), CARIKOD, KOD, ISKONTO, cast((BIRIMFIYAT*ADET) as double precision)-TUTAR AS ISKONTOTUTARI ,--ROUND((((BIRIMFIYAT*ADET)/100.0)*ISKONTO),2),
--ILCE,IL,PERSONEL,ACIKLAMA1,ACIKLAMA2,GRUPADI,KDVDURUM,OZELKOD_ ,MASRAFKODU,ANAHTAR, KDV,
FATURANO,FIRMA,VERGINO,AD,ACIKLAMA,cast(ADET as double precision) AS ADET,
cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT,
cast(BIRIMFIYAT*ADET as double precision) AS TUTAR ,          
cast(TUTAR as double precision) AS KDVMATRAHI ,
cast(KDVLITOPLAM as double precision)-TUTAR AS KDVTUTAR ,
cast(KDVLITOPLAM as double precision) AS GENELTOPLAM ,
FATURASERI ,FATURA_MATRAHI,KDV_TUTARI  ,
PROJEKODU
FROM (
SELECT 
fb.OZELKOD,
BZ.AD AS ZARF ,FB.TUR,
 CASE WHEN FB.TIPI=1 THEN ''Alış/Satış'' WHEN FB.TIPI=2 THEN ''İade'' WHEN FB.TIPI=3 THEN ''Fiyat Farkı'' WHEN FB.TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR ,
(SELECT OZELKOD FROM STOKLAR S where  F.URUNID=S.ID  )   AS STOK_OZELKOD , 
 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
F.ISKONTO,F.KDV,
CASE WHEN FB.RAPORDOVIZ<>''TL'' AND F.DOVIZ_TUTARI>0 THEN ROUND(cast((F.TUTAR/F.ADET)/(F.DOVIZ_TUTARI/F.ADET) as double precision),4) ELSE 0 END  AS KURU ,MG.KOD AS MASRAFKODU,MG.AD AS MASRAFADI,
--KATEGORIADI = coalesce((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID)),''Kategorisiz''),
--GRUPADI     = coalesce((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID)),''Grupsuz''),
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                            ELSE 
                            coalesce(((SELECT DISTINCT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100))) ),''Kategorisiz'')

                            END AS KATEGORIADI ,
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                            ELSE 
                                      ''Grupsuz''
                            END   AS GRUPADI ,
FB.KDVDURUM ,
(SELECT OZELKOD FROM MASRAFGELIR S where  F.URUNID=S.ID  )   AS OZELKOD_ ,
P.PROJEADI,P.PROJEKODU,
(SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID=FB.SUBEID) AS SUBE ,
 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer) AND F.TUR=1)   AS MODEL ,
coalesce(ROUND(F.MIKTAR*coalesce(SOM.BIRIMMALIYET,0.0),2),0.0) as TOPLAM_MALİYET,(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA 
AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=22 LIMIT 1 )  AS VERGINO ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
(SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU=R1.ID) AS PERSONEL ,FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,FB.FATURASERI ,FB.FATURA_MATRAHI,FB.KDV_TUTARI

FROM 

FATBASLIK FB 
         INNER JOIN FATURA F ON 
                   FB.ID=F.FATBASID 
          left outer join STOK_ORT_MALIYET SOM ON 
                                  F.ID=SOM.FATURAID          
         LEFT OUTER JOIN REHBER R ON 
                   FB.REHBERID=R.ID
         LEFT OUTER JOIN MASRAFGELIR MG ON
                   F.MASRAFID=MG.ID-- AND
         LEFT OUTER JOIN REHBERINI RI ON
                   RI.BOLUM=''StokKart_Anabirim'' and
                   RI.DEGER=F.BIRIM
         LEFT OUTER JOIN REHBERINI RI1 ON
                   RI1.BOLUM=''Kasa Türleri'' and
                   RI1.DEGER=FB.TUR
        LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
        LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
	LEFT OUTER JOIN STOKLAR S ON S.ID=F.URUNID  
        LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
        LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID

WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
--AND FB.TUR BETWEEN 10 AND 17
AND FB.TUR IN (11)
AND ADET <>0.0

) AS X

ORDER BY GRUPADI,KATEGORIADI,FATURATARIH,ISLEMTUR' WHERE id = 1368;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT * FROM (
SELECT DISTINCT S.KOD,S.STOKADI,K.AD AS KATEGORI,G.ANAHTAR AS MARKA ,
D.DEPOADI,GRN,CKN,ROUND(KLN,2)AS KLN,ORTMALIYET,cast(SONALISFIYAT as double precision) AS SONALISFIYAT,ROUND((ORTMALIYET*KLN),2) AS ORTTUTAR ,ROUND((SONALISFIYAT*KLN),2)
 AS ORTSONTUTAR FROM(
SELECT URUNID,DSA.GIRISDEPO,GRN,CKN,KLN,ORTMALIYET,
              ROUND((SELECT BIRIMFIYAT--CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT*(1+(KDV/100.0)) ELSE BIRIMFIYAT END
                                                                                               AS TUTAR FROM 
                                                                                                              FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                                                                                              WHERE 
                                                                                                              F.URUNID=DSA.URUNID AND
                                                                                                              F.STOKDURUMDEGIS = 1 AND coalesce(FB.GIRISDEPO,0)<>0 AND F.TUR=1 ORDER BY TARIH DESC  LIMIT 1 ),2)
 AS SONALISFIYAT FROM
                (SELECT ASD.URUNID,ASD.GIRISDEPO,SUM(CASE WHEN GC=''G'' THEN MIKTAR ELSE -MIKTAR END) AS MIKTAR ,
        case when coalesce(MIKTAR,0)<>0 THEN ROUND((ROUND(SUM(TUTAR),2)/SUM(MIKTAR)),2)  ELSE 0 END
                 AS ORTMALIYET FROM
                 (SELECT 
                        ''G'' AS GC ,URUNID,
                        SUM(MIKTAR) AS MIKTAR,
                        FB.GIRISDEPO,
                        SUM(TUTAR)--CASE WHEN FB.KDVDURUM=''Hariç'' THEN TUTAR*(1+(KDV/100.0)) ELSE TUTAR END AS TUTAR ,
                        --FB.TUR,FB.KDVDURUM,F.KDV
                 FROM 
                      FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                               WHERE F.STOKDURUMDEGIS = 1 AND coalesce(FB.GIRISDEPO,0)<>0 AND F.TUR=1
                               GROUP BY URUNID,FB.GIRISDEPO
                               )AS ASD

                GROUP BY ASD.URUNID,ASD.GIRISDEPO,ASD.MIKTAR
                )AS DSA INNER JOIN 
                               (SELECT STOKID,DEPOID,SUM(GIREN) AS GRN ,SUM(CIKAN) AS CKN ,SUM(KALAN) 
                                AS KLN FROM STOKDURUM
                
                               GROUP BY STOKID,DEPOID)AS XXX
                
                ON DSA.URUNID=XXX.STOKID     AND XXX.DEPOID=DSA.GIRISDEPO
                
) AS X INNER JOIN STOKLAR S  ON X.URUNID=S.ID AND S.DURUM=1
       INNER JOIN DEPOLAR D  ON D.ID=X.GIRISDEPO
	   LEFT JOIN  KATEGORI K ON S.KATEGORI=K.ID
	   LEFT JOIN GENINI G ON G.DEGER=S.MARKA AND G.BOLUM=-2701
where
    S.KOD LIKE ''$StokKod$%''
	 --S.KOD LIKE ''%''
) AS Y
  WHERE
    coalesce(DEPOADI,'''') LIKE ''$DepoAdi$%''
	--   DEPOADI  LIKE ''%'' 
	 AND coalesce(KATEGORI,'''') LIKE ''$Kategori$%''
       
ORDER BY DEPOADI,KATEGORI,KOD,STOKADI' WHERE id = 1372;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
R.FIRMA,
EK.KOD,                        
EK.AD AS EKIPMAN,
ER.SERINO,
ER.ACIKLAMA,
ER.GARANTIBITTAR,
L.ACIKLAMA AS İÇ LOKASYON,
RI.AD AS DIŞ LOKASYON,
--RP.ADSOYAD AS ILGILI, 
coalesce((SELECT ADSOYAD FROM(SELECT ADSOYAD FROM REHBERPERSONEL RP WHERE R.ID=RP.REHBERID AND VARSAYILAN=1 ) AS X LIMIT 1 ),'''') AS ILGILI_KISI ,
                (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=40 LIMIT 1 ) AS TEL1 ,
                (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=31 LIMIT 1 ) AS TEL2 ,
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=2 LIMIT 1 ) AS ADRES ,
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 )
                
 AS IL FROM 
EKIPMANREHBER ER
                LEFT OUTER JOIN REHBER R ON
                               ER.REHBERID=R.ID
                LEFT OUTER JOIN EKIPMANLAR EK ON
                               ER.EKIPMANID=EK.ID
                LEFT OUTER JOIN LOKASYON L ON
                               ER.LOKASYONID=L.ID
                LEFT OUTER JOIN REHBERPERSONEL RP ON
                               ER.MUS_ILGILI=RP.ID
                        LEFT OUTER JOIN REHBERILETISIM RI ON
                               RI.REHBERID=R.ID and ER.DISLOKASYONID=RI.ID

                               
WHERE
                R.FIRMA LIKE ''$Firma$%'' AND
                EK.AD LIKE ''$Ekipman$%''

 order by R.FIRMA,EK.KOD,EK.AD' WHERE id = 1373;
UPDATE public.dokumler SET sql = '/*PGX*/select 
	DISTINCT URUNID,S.KOD,S.STOKADI,(SELECT AD FROM KATEGORI K WHERE K.ID=S.KATEGORI) AS KATEGORI ,
	(SELECT DEPOADI FROM DEPOLAR WHERE ID=DEPO) AS DEPO ,
	(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA) AS MARKA ,
	round(GIREN,2) AS GIREN ,round(CIKAN,2) AS CIKAN ,round(KALAN,2) AS KALAN ,
	(SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= ''$Bitis$ 23:59'' and  coalesce(DEPO,'''') LIKE ''$DepoAdi$%'' ORDER BY SM.TARIH DESC  LIMIT 1 ) AS BIRIMMALIYET ,
	DRM.KALAN*(SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= ''$Bitis$ 23:59'' and  coalesce(DEPO,'''') LIKE ''$DepoAdi$%'' ORDER BY SM.TARIH DESC  LIMIT 1 ) AS MALIYET ,
	GUNCEL_SATIS_FIYATI_EURO,GUNCEL_SATIS_FIYATI_EURO*KALAN AS GUNCEL_SATIS_TUTARI_EURO ,SONALIS_TL,SONALIS_TL*  KALAN
 AS TOPLAM from 
	STOKLAR S inner join 
                (SELECT 
					DEPO,
					URUNID, 
                    round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN , 
                    round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN , 
                    round(SUM(NETMIKTAR),2) AS KALAN ,
                    (SELECT SF.FIYAT FROM STOKFIYAT SF WHERE SF.STOKID=ASD.URUNID AND SF.FIYATADI=34 LIMIT 1 ) AS GUNCEL_SATIS_FIYATI_EURO ,
                    (SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON asd.URUNID=SF.STOKID AND SF.FIYATADI=-1  LIMIT 1 )
                  AS SONALIS_TL FROM( 
					SELECT 
						GIRISDEPO AS DEPO ,
						F.URUNID, 
						CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
                    FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
					WHERE 
						(F.STOKDURUMDEGIS = 1) 
						AND (coalesce(FB.DURUM, 1) <> 6)  
						AND (coalesce(FB.GIRISDEPO, 0) > 0)
						AND F.TUR=1
						AND FB.TUR <> 2
						--  AND FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''2024-01-12 23:59''
						AND FB.FATURATARIH <= ''$Bitis$ 23:59''
					UNION ALL
					SELECT 
						CIKISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
					FROM 
						FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
					WHERE 
						(F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
						--AND FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''2024-01-12 23:59'' 
						AND FB.FATURATARIH <= ''$Bitis$ 23:59''
						AND FB.TUR <> 2
                    ) AS ASD GROUP BY URUNID,DEPO
                HAVING SUM(NETMIKTAR)<>0.0
                )as DRM on S.ID=DRM.URUNID --left join 
                --(select STOKID,BIRIMMALIYET,ROW_NUMBER() OVER(PARTITION BY STOKID ORDER BY TARIH desc) AS NUM ,D.ID 
                --from STOK_ORT_MALIYET SM INNER JOIN DEPOLAR D ON D.ID = SM.DEPOID where SM.TARIH<= ''2019-05-02 23:59'' AND coalesce(D.DEPOADI,'''') LIKE ''%'' )as Mlt on Mlt.STOKID=S.ID AND Mlt.ID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END
where --Mlt.NUM=1 and 
	S.KOD LIKE ''$StokKod$%'' 
	AND KALAN>0 
	AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
	and  coalesce(DEPO,'''') LIKE ''$DepoAdi$%''' WHERE id = 1374;
UPDATE public.dokumler SET sql = '/*PGX*/
          --a



SELECT
                ULKE,TCNO,VGNO,ISTEL,FAX,FAX_FIRMA,EPOSTA,ADRES,PK,ILCE,IL,ADRES1=ILCE+'' ''+IL,KOD,UNVAN,UNVANADRES=ADRES1+'' ''+ILCE1+'' ''+IL1,KUR,BAKIYE,BAKIYETURU,FIRMA  ,
                BAKIYEYAZI=fn_ParaTextOlarakTumDiller(BAKIYE,ANABIRIMIFADE,KURUSIFADE,0,-1) 
FROM(

SELECT 
             ULKE   = (SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERILETISIM RI ON RB.YER_ID=RI.ID WHERE RI.REHBERID=R.ID AND ETIKET=''Ülke'' LIMIT 1 ),
             TCNO   = case wheN R.STATU=0 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END,
                VGNO = case wheN coalesce(R.STATU,1)=1  then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=R.ID AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END,
                ISTEL      = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İş Tel'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
             FAX_FIRMA= (SELECT RB.BILGI FROM REHBERILETISIM RI INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE RB.ETIKET=''Faks'' AND YERI=1 AND R.ID=RI.REHBERID LIMIT 1 ),
             FAX    = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Faks'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
             EPOSTA = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Eposta'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
             ADRES  = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''Adres'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
                ADRES1     = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE RB.ETIKET=''Adres'' AND YERI=1 AND R.KOD=C.KOD LIMIT 1 ),
    
             PK     = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''PK'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
             ILCE   = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İlçe'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
             IL     = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE R.ID<0 and RB.ETIKET=''İl'' AND YERI=1 AND R.ID=-1 LIMIT 1 ),
                ILCE1      = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE RB.ETIKET=''İlçe'' AND YERI=1 AND R.KOD=C.KOD LIMIT 1 ),
             IL1    = (SELECT RB.BILGI FROM REHBER R INNER JOIN REHBERILETISIM RI ON R.ID=RI.REHBERID INNER JOIN REHBERBILGI RB ON RI.ID=RB.YER_ID WHERE RB.ETIKET=''İl'' AND YERI=1 AND R.KOD=C.KOD LIMIT 1 ),
        
             C.KOD,AD as UNVAN,KUR,BAKIYE,
                ANABIRIMIFADE = CASE WHEN KUR=''TL'' THEN ''TL''
                                  WHEN KUR=''€'' THEN ''Euro''
                                  WHEN KUR=''$'' THEN ''Dolar''  end,
                KURUSIFADE = CASE WHEN KUR=''TL'' THEN ''Kuruş''
                                  WHEN KUR=''€'' THEN ''Sent''
                                  WHEN KUR=''$'' THEN ''Sent''  end,
    
             BAKIYETURU,C.FIRMA
FROM(

SELECT 
              
             A.KOD,AD,KUR,A.REHBERID,A.SUBEID,
             BAKIYE=ABS(SUM(BORC-ALACAK)),
             BAKIYETURU=CASE WHEN SUM(BORC-ALACAK)>0 THEN ''Borç Bakiyesi'' ELSE ''Alacak Bakiyesi'' END,
             FIRMA   = (SELECT FIRMA FROM REHBER R1 WHERE R1.ID=A.SUBEID LIMIT 1 ) 
       
             
       
FROM
(



Select CEKID=K.ID, ISLEMTARIHI AS TARIH,PLANTARIHI as AKSIYONTARIH,BELGENO as NO, K.TUR,'''' as BASLIK,
TURAD=case when K.TUR like ''26__'' then (select ANAHTAR + '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
when K.TUR like ''36__'' then (select ANAHTAR + '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end, 
K.REHBERID,
KOD = case when K.REHBERID=0 then M.KOD else R.KOD end,AD = case when K.REHBERID=0 then M.AD else R.FIRMA end, K.ACIKLAMA, HESAPID,
HESAPKODU=case HESAPTURU when ''B'' then (select HESAPKODU from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
when ''H'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''+ (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)+'')'','''')
when ''K'' then (select KASAKODU from KASALAR K2 where K2.ID=K.HESAPID)
when ''P'' then (select KODU from POS P where P.ID=K.HESAPID)
when ''V'' then (select KODU from KREDIKARTI KK where KK.ID=K.HESAPID) end,
HESAPADI=case HESAPTURU when ''B'' then (select HESAPADI from BANKAHESAPLAR BH where BH.ID=K.HESAPID)
when ''H'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)+coalesce('' (''+ (select ADI from PARA_KUPON PK where PK.ID=K.CEKSENETID)+'')'','''')
when ''K'' then (select KASAADI from KASALAR K2 where K2.ID=K.HESAPID)
when ''P'' then (select ADI from POS P where P.ID=K.HESAPID)
when ''V'' then (select ADI from KREDIKARTI KK where KK.ID=K.HESAPID) end,
K.DURUM,
BORC = case when EKSTREDEKULLAN=1 AND BORC>0 then cast(K.DOVIZ_TUTARI as double precision) else K.BORC end,
ALACAK = case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end,
KUR = case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end,
YERELKUR=
ABS(
case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0 then K.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0 THEN -1*K.DOVIZ_TUTARI else K.BORC-K.ALACAK end
/ 
CASE WHEN ((case when EKSTREDEKULLAN=1 AND BORC>0 then K.DOVIZ_TUTARI else K.BORC end)-(case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end))=0 THEN 1
ELSE ((case when EKSTREDEKULLAN=1 AND BORC>0 then K.DOVIZ_TUTARI else K.BORC end)-(case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end)) END
)
,

K.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,BORCBAKIYE=0,ALACAKBAKIYE=0 ,

YERELTUTAR = case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0 then K.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0 THEN -1*K.DOVIZ_TUTARI else K.BORC-K.ALACAK end,
YERELBAKIYE= 0,
K.SUBEID,VADETARIHI=ISLEMTARIHI,
ADET=1.0,BIRIM='''',BIRIMFIYAT=0.0
From KASA K 
left outer join REHBER R on K.REHBERID=R.ID left outer join KASALAR KS on KS.ID= K.HESAPID left outer join MASRAFGELIR M on M.ID=K.MASRAFID
Where K.ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''
and ((K.TUR in (49))or(K.TUR not between 40 and 79))

UNION ALL

Select CEKID=F.ID, FATURATARIH as TARIH, FATURATARIH AS AKSIYONTARIH, FATURANO as NO, F.TUR,F.BASLIK,
TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ),
F.REHBERID, R.KOD, R.FIRMA AS AD, F.ACIKLAMA, HESAPID=null, HESAPKODU=null, HESAPADI=null,F.DURUM,
BORC=case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end ,
ALACAK=case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end,
KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
YERELKUR= 
ABS(
(case when F.RAPORDOVIZ = (SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.DOVIZ_TUTARI 
         when F.RAPORDOVIZ = (SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.DOVIZ_TUTARI
         when F.RAPORDOVIZ <>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.FATURA_TUTARI 
         when F.RAPORDOVIZ <>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.FATURA_TUTARI
end)/

CASE WHEN ((case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end)-

(case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end))=0 THEN 1 ELSE
((case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end)-
(case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end))
END
),

F.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,BORCBAKIYE=0,ALACAKBAKIYE=0 ,
YERELTUTAR = 
             case when F.RAPORDOVIZ =  (SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.DOVIZ_TUTARI 
                     when F.RAPORDOVIZ =  (SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.DOVIZ_TUTARI
                    when F.RAPORDOVIZ <> (SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (15,16,17) then F.FATURA_TUTARI 
                     when F.RAPORDOVIZ <> (SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND F.TUR IN (8,11,12,13) then -1*F.FATURA_TUTARI
end,
YERELBAKIYE= 0,
F.SUBEID, VADETARIHI=F.FATURATARIH+coalesce(F.VADE,0),
ADET=1.0,BIRIM='''',BIRIMFIYAT=0.0
From FATBASLIK F 
inner join REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6
left outer join MASRAFGELIR M on M.ID=F.MASRAFID
Where FATURATARIH BETWEEN ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

---- Çek
UNION ALL
Select CEKID=C.ID ,CH.TARIH, VADE as AKSIYONTARIH, MAKBUZNO as NO, TUR=case when CH.ISLEM in(130,141) then 23 else 33 end,'''',
TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ),
CH.REHBERID,R.KOD, R.FIRMA AS AD, ACIKLAMA=''Serino:''+cast(C.SERINO as varchar)+'' ''+rtrim(CH.ACIKLAMA),
HESAPID=CH.BANKAHESAPLARID, HESAPKODU=BH.HESAPKODU, HESAPADI=BH.HESAPADI,C.DURUM,
BORC=Case
when CH.ISLEM in(140,131,132,133,134,137) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end)
else 0 end,
ALACAK=Case
when CH.ISLEM in(130,141) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end)
else 0 end,
KUR=case when C.EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end,
YERELKUR =ABS( (case when C.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI
when C.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(130,141) then -1*C.DOVIZ_TUTARI
end)/
((Case when CH.ISLEM in(140,131,132,133,134,137) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end)-
(Case when CH.ISLEM in(130,141) then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end))),
C.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,BORCBAKIYE=0,ALACAKBAKIYE=0 ,
YERELTUTAR = case when C.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI
when C.DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(130,141) then -1*C.DOVIZ_TUTARI
when C.DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(140,131,132,133,134,137) then C.TUTAR
when C.DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND CH.ISLEM in(130,141) then -1*C.TUTAR
end
,

YERELBAKIYE = 0,
C.SUBEID, VADETARIHI=VADE,
ADET=1.0,BIRIM='''',BIRIMFIYAT=0.0
From CEKLER C  inner join
CEKHAREKET CH on C.ID=CH.CEKSENETLERID
left outer join REHBER R on CH.REHBERID=R.ID
left outer join BANKAHESAPLAR BH on CH.BANKAHESAPLARID=BH.ID
left outer join MASRAFGELIR M on M.ID=C.MASRAFID
Where CH.ISLEM in(130,131,132,134,137,140,141)
and CH.TARIH BETWEEN ''$Baslangic$ 00:00'' and ''$Bitis$ 23:59''

--alter table CEKLER ADD EKSTREDEKULLAN BIT
---- Senet
UNION ALL
Select CEKID=C.ID ,TARIH, VADE as AKSIYONTARIH, MAKBUZNO as NO,C.TUR,'''', TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ),
C.REHBERID,R.KOD, R.FIRMA AS AD, ACIKLAMA=rtrim(NOTLAR), HESAPID=null, HESAPKODU=null, HESAPADI=null,C.DURUM,
BORC=Case when C.TUR=34 then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end,
ALACAK=Case when C.TUR=24 then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end,
KUR=case when C.EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end,
YERELKUR=
ABS(
(case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.DOVIZ_TUTARI
when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.DOVIZ_TUTARI
when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.TUTAR when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.TUTAR
end)/
((Case when C.TUR=34 then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end)-
(Case when C.TUR=24 then (case when C.EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0 end))
)
,


C.MASRAFID, MASRAFKOD=M.KOD, MASRAFAD=M.AD,BORCBAKIYE=0,ALACAKBAKIYE=0 ,
YERELTUTAR = case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.DOVIZ_TUTARI when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.DOVIZ_TUTARI
when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=34 then C.TUTAR when DOVIZ_KURU<>(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND C.TUR=24 then -1*C.TUTAR
end,
YERELBAKIYE= 0,
C.SUBEID, VADETARIHI=VADE,
ADET=1.0,BIRIM='''',BIRIMFIYAT=0.0
From SENETLER C 
inner join REHBER R on C.REHBERID=R.ID left outer join MASRAFGELIR M on M.ID=C.MASRAFID
Where
C.TARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''

) AS A 
 GROUP BY A.KOD,AD,KUR,REHBERID,SUBEID
) AS C INNER JOIN REHBER R ON C.REHBERID=R.ID
WHERE
       C.KOD LIKE ''$Kod$%'' AND
       C.BAKIYE>1
) AS ABC
WHERE
     UNVAN LIKE ''%$Unvan$%''
ORDER BY kur, 2
' WHERE id = 1375;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT R.OZELKOD,
R.FIRMA,
EK.KOD AS MARKA,            
EK.AD AS MODEL,
ER.SERINO,
ER.ACIKLAMA,
ER.GARANTIBITTAR,
L.ACIKLAMA AS İÇ LOKASYON,
RI.AD AS DIŞ LOKASYON,
coalesce((SELECT ADSOYAD FROM(SELECT ADSOYAD FROM REHBERPERSONEL RP WHERE R.ID=RP.REHBERID AND VARSAYILAN=1 ) AS X LIMIT 1 ),'''')  AS ILGILI_KISI ,
                (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=40 LIMIT 1 ) AS TEL1 ,
                (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=31 LIMIT 1 ) AS TEL2 ,
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI
WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=2 LIMIT 1 ) AS ADRES ,
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
       (select ANAHTAR from GENINI where BOLUM=-2210 and DEGER=R.BOLGE and DIL = -1) AS BOLGE ,
       (select ANAHTAR from GENINI where BOLUM=''-2210''||cast(R.BOLGE as varchar) and DEGER=R.ALTBOLGE and DIL = -1) AS ALTBOLGE ,
       (select FIRMA from REHBER where ID=R.SUBEID)  AS SUBEAD ,
       fn_TarihFarkiGunAyYilTextOlarak(now(),ER.GARANTIBITTAR) AS SURE ,
	   case when ER.GARANTIBITTAR <now() then ''YOK'' else ''VAR'' end        
 AS GARANTI FROM 
EKIPMANREHBER ER
                LEFT OUTER JOIN REHBER R ON
                               ER.REHBERID=R.ID
                LEFT OUTER JOIN EKIPMANLAR EK ON
                               ER.EKIPMANID=EK.ID
                LEFT OUTER JOIN LOKASYON L ON
                               ER.LOKASYONID=L.ID
                LEFT OUTER JOIN REHBERPERSONEL RP ON
                               ER.MUS_ILGILI=RP.ID
                        LEFT OUTER JOIN REHBERILETISIM RI ON
                               RI.REHBERID=R.ID and ER.DISLOKASYONID=RI.ID                             
WHERE
               R.FIRMA LIKE ''$Firma$%'' 
           AND coalesce((select ANAHTAR from GENINI where BOLUM=-2210 and DEGER=R.BOLGE and DIL = -1),'''') LIKE ''$Bolge$%''
            
            and  coalesce((select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=R.ALTBOLGE AND GB.DEGER=R.BOLGE
                                where GALT.BOLUM like ''-2210%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2210 ),'''')  like ''$Altbolge$%'' 
                                                                 
           AND  coalesce((select ANAHTAR from GENINI where BOLUM=-2701 and DEGER=ER.MARKA and DIL = -1),'''') LIKE ''$Marka$%''
            
            
            and  coalesce((select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=ER.MODEL AND GB.DEGER=ER.MARKA
                                where GALT.BOLUM like ''-2701%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2701 ),'''')  like ''$Model$%'' 
            and coalesce((SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI 
 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ),'''') LIKE ''$Il$%''
            AND coalesce(ER.ACIKLAMA,'''')  LIKE ''$Erid$%''         
order by R.FIRMA,EK.KOD,EK.AD' WHERE id = 1376;
UPDATE public.dokumler SET sql = '/*PGX*/
	''$BitTar$ 23:59'' DATETIME,
	'''' VARCHAR(100),
	'''' VARCHAR(100)


--
--

SELECT --TARIH=to_char(TARIH,''DD.MM.YYYY''),
	   SH.BASLAMA,
       SH.BITIS,
	   S.SERVISNO,
	   S.KONUSU,
	   MARKA=(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=E.MARKA),
       MODEL=(select BOLGE=GB.ANAHTAR+'' - ''+GALT.ANAHTAR from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM+cast(GB.DEGER as varchar)
                                and GALT.DEGER=E.MODEL AND GB.DEGER=E.MARKA
                                where GALT.BOLUM like ''-2701%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2701 ),
        TUR=(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-3006 AND G.DEGER=S.TURU),
	 --  S.ID,
       R.FIRMA,
       --PERSONEL=(SELECT fn_GorevVerilenKisilerUzunAd(12, S.ID)),
      -- SB.ACIKLAMA,
      -- SB.COZUM,
       E.AD AS EKİPMAN_AD,
	   S.SERINO,
	   GARANTI= CASE S.KAPSAM WHEN 0 THEN ''H'' 
            WHEN 1 THEN ''E'' END ,
       PERSONEL=RR.FIRMA ,
       G.ANAHTAR AS DURUM,
       SURE=DATEDIFF(MINUTE,SH.BASLAMA,SH.BITIS) --,
	   --SH.BASLAMA
       --,GK.LISTGOREVID

FROM SERVIS S --LEFT OUTER JOIN SERVISBILGI SB ON S.ID=SB.SERVISID
              LEFT OUTER JOIN REHBER R ON R.ID=S.REHBERID
              LEFT OUTER JOIN EKIPMANLAR E ON E.ID=S.EKIPMANID
			  LEFT OUTER JOIN SERVISHAREKET SH ON SH.SERVISID=S.ID
			  LEFT OUTER JOIN GENINI G ON G.DEGER=SH.DURUM AND G.BOLUM=-3007
			  LEFT OUTER JOIN REHBER RR ON RR.ID=SH.PERSONEL
             -- LEFT OUTER JOIN GOREVKULLANICI GK ON GK.LISTGOREVID=S.ID
             -- LEFT OUTER JOIN REHBER RR ON RR.ID=GK.REHBERID
			  --WHERE S.ID=4164
			  
WHERE 
  --S.BASLAMATARIHI BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
  S.REHBERID=6053
	  --AND ISNULL (R.FIRMA,'''')  LIKE ''%$Kurum$%''
	  --AND ISNULL (RR.FIRMA,'''') LIKE ''%$Personel$%''
ORDER BY S.BASLAMATARIHI,R.FIRMA,S.ID
' WHERE id = 1377;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT     
	 CASE WHEN F.MIKTAR < -0.0 THEN ''SARF'' ELSE ''ÜRÜN'' END  AS TURU ,  
	K.AD AS KATEGORI,
	S.KOD as  STOKKODU,
	S.STOKADI,    
	FB.FATURATARIH AS TARIH,
	FB.FATURANO as URETIMNO,
	(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA) AS MARKA ,
	 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer)) AS MODEL ,
	(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2704 AND G.DEGER=S.GRUBU) AS GRUBU ,
	(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2703 AND G.DEGER=S.TIPI) AS STOKTIPI ,
	F.MIKTAR AS MIKTAR , --coalesce(SI.MIKTAR,F.MIKTAR),
	 (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2702 AND G.DEGER=S.ANABIRIM) AS BIRIM ,
	F.BIRIMFIYAT AS BIRIMMALIYET , 
	F.BIRIMFIYAT*F.MIKTAR-- AS TUTAR ,--F.BIRIMFIYAT*coalesce(SI.MIKTAR,F.MIKTAR),
	--SI.IZLEM
FROM FATBASLIK FB INNER JOIN FATURA F ON  FB.ID=F.FATBASID
                  INNER JOIN STOKLAR S ON F.URUNID=S.ID                                 
                  LEFT JOIN KATEGORI K ON K.ID=S.KATEGORI
				  --LEFT JOIN STOKIZLEME SI ON SI.STOKID=S.ID AND SI.BASLIKID=FB.ID AND SI.SATIRID=F.ID
                                  
WHERE FB.TUR=6                 
AND FB.FATURATARIH  between ''$baslama$ 00:00'' and ''$bitis$ 23:59''
and coalesce(K.AD,'''') LIKE ''%$kategori$%''
AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
	AND coalesce(S.GRUBU,'''') LIKE ''$grubu$%''
	AND coalesce(S.MODEL,'''') LIKE ''$model$%''
ORDER BY K.AD' WHERE id = 1378;
UPDATE public.dokumler SET sql = '/*PGX*/
	:PDonemSon DATETIME




select
KDR_POS=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=SUM(ALACAK-BORC)*(select D.SATIS from DOVIZ D where D.CINSI=K1.KUR order by D.TARIH desc LIMIT 1 )
                           from POS K inner join KASA K1 on K.ID=K1.HESAPID
                           where K1.ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon AND K1.HESAPTURU=''P''
                           group by K1.KUR)as X),0.0),
KDR_ALINAN_ÇEK=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=SUM(CASE WHEN DOVIZ_KURU = ''TL'' THEN cast(DOVIZ_TUTARI as double precision)WHEN C.KUR = ''TL'' THEN cast(C.TUTAR as double precision) END)
from CEKLER C inner join REHBER R on C.REHBERID=R.ID
where C.TUR in (130,132,133,134,135,138) AND C.CEKSENET = 101 AND C.VADE BETWEEN :PDonemBas AND :PDonemSon)as X),0.0),
KDR_ALINAN_SENET=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=SUM(CASE WHEN DOVIZ_KURU = ''TL'' THEN cast(DOVIZ_TUTARI as double precision)WHEN C.KUR = ''TL'' THEN cast(C.TUTAR as double precision) END)
from CEKLER C inner join REHBER R on C.REHBERID=R.ID
where C.TUR in (130,132,133,134,135,138) AND C.CEKSENET = 121 AND C.VADE BETWEEN :PDonemBas AND :PDonemSon)as X),0.0),
KDR_KASA=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=cast((SUM(ALACAK-BORC)*(select D.SATIS from DOVIZ D where D.CINSI=K1.KUR order by D.TARIH desc LIMIT 1 )) as double precision)
                           from KASALAR K inner join KASA K1 on K.ID=K1.HESAPID
                           where K1.ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon AND K1.HESAPTURU=''K''
                           group by K.KASAKODU,K.KASAADI,K1.KUR)as X),0.0),
KDR_STOK=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=DRM.KALAN*(coalesce((SELECT SOM.BIRIMMALIYET FROM STOK_ORT_MALIYET SOM INNER JOIN (SELECT SM.STOKID,SM.BIRIMMALIYET,FB.TUR,SM.DEPOID,FB.CIKISDEPO,NUM=ROW_NUMBER() OVER(PARTITION BY STOKID ORDER BY SM.TARIH desc) FROM STOK_ORT_MALIYET SM INNER JOIN FATBASLIK FB ON FB.ID = SM.FATBASID WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = (SELECT ID FROM DEPOLAR WHERE DEPOADI = ''Konsinye Çıkış'') THEN 1 ELSE DRM.DEPO END ORDER BY SM.TARIH DESC LIMIT 1 ) AS X ON X.STOKID = SOM.STOKID AND CASE WHEN X.BIRIMMALIYET = 0 THEN 1 ELSE X.DEPOID END = SOM.DEPOID  WHERE SOM.TARIH <= :PDonemSon ORDER BY SOM.TARIH DESC,X.NUM DESC LIMIT 1 ),0))
                           from STOKLAR S inner join 
                                                      (SELECT DEPO,URUNID,
                                                                             GIREN=round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2), 
                                                                             CIKAN=round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2), 
                                                                             KALAN=round(SUM(NETMIKTAR),2)
                                                      FROM( SELECT DEPO=GIRISDEPO,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
                                                                                                        FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
                                                                                                        WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1 AND FB.FATURATARIH <= :PDonemSon
                                                                                                        UNION ALL
                                                                                                        SELECT DEPO=CIKISDEPO,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
                                                                                                        FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
                                                                                                        WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1 AND FB.FATURATARIH <= :PDonemSon
                                                                             ) AS ASD GROUP BY URUNID,DEPO
                                                      HAVING SUM(NETMIKTAR)<>0.0
                                                      )as DRM on S.ID=DRM.URUNID --left join 
                                                      --(select STOKID,BIRIMMALIYET,NUM=ROW_NUMBER() OVER(PARTITION BY STOKID ORDER BY TARIH desc) from STOK_ORT_MALIYET SM)as Mlt on Mlt.STOKID=S.ID
                           where --Mlt.NUM=1 and 
                                  S.DURUM=1 AND S.TIPI NOT IN (SELECT DEGER FROM GENINI G WHERE G.DEGER=S.TIPI AND BOLUM=-2703 AND G.DEGER LIKE ''%-%''))as X),0.0),
KDR_ALACAKLILAR=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      SELECT KALAN=-1.0*cast((BAKIYE*(select D.SATIS from DOVIZ D where D.CINSI=XXX.KUR order by D.TARIH desc LIMIT 1 )) as double precision)  
                           FROM ( select  DISTINCT R.SUBEID,R.KOD ,R.FIRMA,cast(TOPLAM_BORC as float) AS BORC ,cast(TOPLAM_ALACAK as float) AS ALACAK,KUR ,BAKIYE=TOPLAM_BORC-TOPLAM_ALACAK 
                                        FROM(  select
                                               REHBERID,TOPLAM_BORC=SUM(coalesce(BORC,0)),TOPLAM_ALACAK=SUM(coalesce(ALACAK,0)),KUR=coalesce(KUR,''TL'')
                                        from (
                                           SELECT
                                               REHBERID,
                                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
                                               0 AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                                               FROM FATBASLIK F
                                               WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17)) 
                                               AND FATURATARIH BETWEEN :PDonemBas AND :PDonemSon
                                               GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end
                                        UNION ALL
                                               SELECT REHBERID,
                                               0 AS BORC,
                                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                                               FROM FATBASLIK F
                                               WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13)) 
                                               AND FATURATARIH BETWEEN :PDonemBas AND :PDonemSon
                                               GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end
                                        UNION ALL
                                               SELECT REHBERID,
                                               SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
                                               SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR
                                               FROM KASA K
                                               WHERE TUR not between 60 and 79 
                                               AND ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon
                                               GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end
                                        UNION ALL
                                               SELECT CH.REHBERID,
                                               BORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                                               ALACAK=SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                                               CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR
                                               FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                                               WHERE CH.ISLEM in(130,131,132,134,137,140,141) 
                                               AND CH.TARIH BETWEEN :PDonemBas AND :PDonemSon
                                               GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_KURU else c.KUR end
                                        UNION ALL
                                               SELECT REHBERID,
                                               0 AS BORC,
                                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                                               FROM SENETLER S
                                               WHERE TUR = 24   
                                               AND TARIH BETWEEN :PDonemBas AND :PDonemSon
                                               GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END
                                        UNION ALL
                                               SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
                                               BORC,0 AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                                               FROM SENETLER S
                                               WHERE TUR = 34  
                                               AND TARIH BETWEEN :PDonemBas AND :PDonemSon
                                               GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end
                                        ) as asd
                                  group by REHBERID,KUR) AS DSA
                                  INNER JOIN REHBER R ON     DSA.REHBERID=R.ID AND coalesce(R.KDR_Disi,''False'') =''False''
                           where  R.ID > 0 and coalesce(R.ID,'''')<>'''' and R.GRUP<>335 
                           AND TOPLAM_BORC<=TOPLAM_ALACAK
   ) AS XXX )as X),0.0),
--KREDİLER
KDR_KREDİLER=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=cast((sum(case when P.ODENMIS=1 and P.TARIH<=:PDonemSon then 0.0 else P.TAKSIT end)*(select D.SATIS from DOVIZ D where D.CINSI=KR.KUR order by D.TARIH desc LIMIT 1 )) as double precision)
                           from KREDILER KR left join PLANKREDI P on P.KREDIID=KR.ID
                           where KR.DURUM>0 and GENELKREDITIPI=1 and exists(select 1 from PLANKREDI P2 where P2.KREDIID=KR.ID and P2.TARIH<=:PDonemSon)
                           GROUP BY KR.ID,KREDIKODU,ADI,SOZLESMENO,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KAPANISTARIHI,KREDITAKSIT
                           union all
                           select KALAN=cast((coalesce(sum(BORC),0)-coalesce(sum(ALACAK),0)*(select D.SATIS from DOVIZ D where D.CINSI=KR.KUR order by D.TARIH desc LIMIT 1 )) as double precision)
                           from KREDILER KR left outer join KASA KS on HESAPTURU=''R'' and KS.HESAPID=KR.ID
                           where KR.DURUM>0 and KS.TUR<>2 and GENELKREDITIPI=2 and KS.ISLEMTARIHI<=:PDonemSon
                           GROUP BY KR.ID,KREDIKODU,ADI,SOZLESMENO,GENELKREDITIPI,KR.KUR,ALINISTARIHI,KAPANISTARIHI,KREDITAKSIT)as X),0.0),
KDR_KREDİ_KARTI=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=cast((SUM(ALACAK-BORC)*(select D.SATIS from DOVIZ D where D.CINSI=K1.KUR order by D.TARIH desc LIMIT 1 )) as double precision)
                           from KREDIKARTI K inner join KASA K1 on K.ID=K1.HESAPID
                           where K1.ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon and K1.HESAPTURU=''V''
                           group by K.KODU,K.ADI,K1.KUR)as X),0.0),
KDR_VERİLEN_ÇEK=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=SUM(CASE WHEN DOVIZ_KURU = ''TL'' THEN cast(DOVIZ_TUTARI as double precision)WHEN C.KUR = ''TL'' THEN cast(C.TUTAR as double precision) END)
from CEKLER C inner join REHBER R on C.REHBERID=R.ID
where C.TUR in (140) AND C.CEKSENET = 103 AND C.VADE BETWEEN :PDonemBas AND :PDonemSon)as X),0.0),
KDR_VERİLEN_SENET=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=SUM(CASE WHEN DOVIZ_KURU = ''TL'' THEN cast(DOVIZ_TUTARI as double precision)WHEN C.KUR = ''TL'' THEN cast(C.TUTAR as double precision) END)
from CEKLER C inner join REHBER R on C.REHBERID=R.ID
where C.TUR in (140) AND C.CEKSENET = 321 AND C.VADE BETWEEN :PDonemBas AND :PDonemSon)as X),0.0),
KDR_BORÇLULAR=coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      SELECT KALAN=cast((BAKIYE*(select D.SATIS from DOVIZ D where D.CINSI=XXX.KUR order by D.TARIH desc LIMIT 1 )) as double precision)  
                           FROM (
                           select  DISTINCT R.SUBEID,R.KOD ,R.FIRMA,cast(TOPLAM_BORC as float) AS BORC ,cast(TOPLAM_ALACAK as float) AS ALACAK,KUR ,BAKIYE=TOPLAM_BORC-TOPLAM_ALACAK 

                           FROM(
                                  select
                                         REHBERID,TOPLAM_BORC=SUM(coalesce(BORC,0)),TOPLAM_ALACAK=SUM(coalesce(ALACAK,0)),KUR=coalesce(KUR,''TL'')
                                  from (
                                     SELECT
                                        REHBERID,
                                        SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
                                        0 AS ALACAK,
                                        CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                                        FROM FATBASLIK F
                                        WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17)) 
                                        AND FATURATARIH BETWEEN :PDonemBas AND :PDonemSon
                                        GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end
                                  UNION ALL
                                        SELECT REHBERID,
                                        0 AS BORC,
                                        SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
                                        CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                                        FROM FATBASLIK F
                                        WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13)) 
                                        AND FATURATARIH BETWEEN :PDonemBas AND :PDonemSon 
                                        GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end
                                  UNION ALL
                                        SELECT REHBERID,
                                        SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
                                        SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
                                        CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR
                                        FROM KASA K
                                        WHERE TUR not between 60 and 79 
                                        AND ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon
                                        GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end
                                  UNION ALL
                                        SELECT CH.REHBERID,
                                        BORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                                        ALACAK=SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                                        CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR
                                        FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                                        WHERE CH.ISLEM in(130,131,132,134,137,140,141) 
                                        AND CH.TARIH BETWEEN :PDonemBas AND :PDonemSon
                                        GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_KURU else c.KUR end
                                  UNION ALL
                                        SELECT REHBERID,
                                        0 AS BORC,
                                        SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
                                        CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                                        FROM SENETLER S
                                        WHERE TUR = 24   
                                        AND TARIH BETWEEN :PDonemBas AND :PDonemSon
                                        GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END
                                  UNION ALL
                                        SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
                                        BORC,0 AS ALACAK,
                                        CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                                        FROM SENETLER S
                                        WHERE TUR = 34  
                                        AND TARIH BETWEEN :PDonemBas AND :PDonemSon
                                        GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end
                                        ) as asd
                                  group by REHBERID,KUR) AS DSA
                                  INNER JOIN REHBER R ON     DSA.REHBERID=R.ID AND coalesce(R.KDR_Disi,''False'') =''False''
                           where  R.ID > 0 and coalesce(R.ID,'''')<>'''' and R.GRUP<>335  
                           AND TOPLAM_BORC>=TOPLAM_ALACAK
                              ) AS XXX       )as X),0.0),
KDR_BANKA = coalesce((select SUM(coalesce(KALAN,0.0)) from
                    (      select KALAN=SUM(ALACAK-BORC)*(select D.SATIS from DOVIZ D where D.CINSI=K1.KUR order by D.TARIH desc LIMIT 1 )
                           from BANKAHESAPLAR K inner join KASA K1 on K.ID=K1.HESAPID
                           where K1.ISLEMTARIHI BETWEEN :PDonemBas AND :PDonemSon and K1.HESAPTURU=''B'' AND coalesce(ONLINEHESAPHAREKETI,0) = 0
                           group by K1.KUR)as X),0.0)
' WHERE id = 1379;
UPDATE public.dokumler SET sql = '/*PGX*/
	:PDonemSon DATETIME



SELECT 
	KOD,STOKADI,DEPO,KALAN,cast(TUTAR as double precision) AS TUTAR ,KUR,cast(TLTUTAR as double precision) AS TLTUTAR, Satış Fiyatı,SF_KUR,Satış Fiyatı TL,Satış Fiyat TL TOPLAM
FROM 
(
	SELECT 
		S.KOD,
		S.STOKADI,
		DEPO,
		KALAN=round(KALAN,2),
		TUTAR=DRM.KALAN*(SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = (SELECT ID FROM DEPOLAR WHERE DEPOADI = ''Konsinye Çıkış'') THEN 1 ELSE DRM.DEPO END AND SM.TARIH <= :PDonemSon ORDER BY SM.TARIH DESC  LIMIT 1 ),
		KUR=''TL'',
		TLTUTAR=DRM.KALAN*(SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = (SELECT ID FROM DEPOLAR WHERE DEPOADI = ''Konsinye Çıkış'') THEN 1 ELSE DRM.DEPO END AND SM.TARIH <= :PDonemSon ORDER BY SM.TARIH DESC LIMIT 1 ),
		CASE WHEN coalesce(SF.FIYAT,-1) = -1 THEN 0 ELSE SF.FIYAT END  AS Satış Fiyatı, 
		SF.KUR AS SF_KUR, 
		CASE WHEN coalesce(SF.FIYAT,-1) = -1 THEN 0 ELSE CASE WHEN SF.KUR = ''TL'' THEN SF.FIYAT ELSE SF.FIYAT*CASE 
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''SATIS'' THEN D.SATIS
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''ALIS'' THEN D.ALIS
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''EFALIS'' THEN D.EFALIS
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''EFSATIS'' THEN D.EFSATIS
	END END END AS Satış Fiyatı TL, 
		CASE WHEN coalesce(SF.FIYAT,-1) = -1 THEN 0 ELSE CASE WHEN SF.KUR = ''TL'' THEN SF.FIYAT ELSE SF.FIYAT*CASE 
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''SATIS'' THEN D.SATIS
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''ALIS'' THEN D.ALIS
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''EFALIS'' THEN D.EFALIS
		WHEN (SELECT ANAHTAR FROM GENINI WHERE BOLUM = -10005) = ''EFSATIS'' THEN D.EFSATIS
	END END * round(KALAN,2) END AS Satış Fiyat TL TOPLAM
	FROM 
		STOKLAR S   LEFT JOIN STOKFIYAT SF ON SF.STOKID = S.ID AND SF.FIYATADI = 36
					LEFT JOIN DOVIZ D ON to_char(D.TARIH,''YYYY-MM-DD HH24:MI:SS'') = to_char(:PDonemSon,''YYYY-MM-DD HH24:MI:SS'') AND D.CINSI = SF.KUR
					INNER JOIN
					(SELECT DEPO,
							URUNID,
							GIREN=round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2), 
							CIKAN=round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2), 
							KALAN=round(SUM(NETMIKTAR),2)
					FROM( 
						  SELECT 
							DEPO=GIRISDEPO,
							F.URUNID, 
							CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
						  FROM 
							FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID
						  WHERE 
							(F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1
							AND FB.FATURATARIH <= :PDonemSon
						  UNION ALL
						  SELECT 
							DEPO=CIKISDEPO,
							F.URUNID, 
							CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
						  FROM 
							FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID
						  WHERE 
							(F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
							AND FB.FATURATARIH <= :PDonemSon
						) AS ASD 
					GROUP BY 
						URUNID,DEPO
					HAVING 
						SUM(NETMIKTAR)<>0.0
					)AS DRM on S.ID=DRM.URUNID
	WHERE 
		S.DURUM=1 AND S.TIPI NOT IN (SELECT DEGER FROM GENINI G WHERE G.DEGER=S.TIPI AND BOLUM=-2703 AND G.DEGER LIKE ''%-%'') 
)AS XX
' WHERE id = 1380;
UPDATE public.dokumler SET sql = '/*PGX*/



 --DENEME
SELECT * FROM 
(
SELECT *,GECEN_GUN=DATEDIFF( DAY,SONHAREKETTARIHI,''$Bitis$ 23:59''),
	YIL=year(SONHAREKETTARIHI),
	AY=month(SONHAREKETTARIHI),TOPMALIYET= KALAN*SONBIRIMMALIYET,
    0-120=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI<121.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    121-180=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=121.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<181.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    181-480=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=181.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<481.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    481-990=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=481.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<991.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    991-1500=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=991.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<1501.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    1501-3000=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=1501.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<3001.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    3001+=case when KALAN >= 3001 then KALAN*SONBIRIMMALIYET else 0.0 end  	        
FROM(
	SELECT 
		S.KOD,S.STOKADI,
		SONHAREKETTARIHI=(SELECT FATURATARIH FROM FATBASLIK FB 
			WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND 
			FB.TUR<>2 AND	FB.FATURATARIH <= ''$Bitis$ 23:59'' AND FB.ID IN (SELECT FATBASID FROM FATURA F WHERE URUNID = S.ID AND F.TUR = 1) ORDER BY 1 DESC LIMIT 1 ),
		SONBIRIMMALIYET=(SELECT SOM.BIRIMMALIYET FROM STOK_ORT_MALIYET SOM  WHERE  STOKID=S.ID and SOM.TARIH<=''$Bitis$ 23:59'' ORDER BY TARIH DESC LIMIT 1 ),
		KALAN=(	SELECT SUM(KALAN) FROM
		(
    
	    SELECT KALAN=CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END 
            FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
            WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND
			FB.TUR<>2 AND FB.FATURATARIH <= ''$Bitis$ 23:59'' AND  F.URUNID=S.ID AND (F.STOKDURUMDEGIS = 1) AND 
			(coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1
                                               
            UNION ALL
            SELECT KALAN= CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END 
            FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
            WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND
			FB.TUR<>2 AND   FB.FATURATARIH <= ''$Bitis$ 23:59'' AND F.URUNID=S.ID AND (F.STOKDURUMDEGIS = 1) AND 
			(coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
                )
		AS aaa )  											   
	FROM  
		STOKLAR S  
		)AS BBB     
	) AS XXX

WHERE SONHAREKETTARIHI IS NOT NULL
AND KALAN>0  
ORDER BY 6
' WHERE id = 1382;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT R1.KOD AS CARİ KOD,R1.FIRMA AS CARİ ADI,C.BORCLU,C.KOD ASHESAP KODU , B.BANKAADI,BS.SUBEADI ,C.HESAPNO AS ÇEK HESAP NO,
C.SERINO AS ÇEK SERİ NO, C.TUTAR,C.KUR,C.VADE,G.ANAHTAR AS DURUM,case when coalesce(R2.FIRMA,''-'')<>''-'' then R2.FIRMA else BHSON.HESAPADI end  AS SONISLEMYERI ,

REFERANS TARİH =CH.TARIH,C.MAKBUZNO AS EVRAK NO,C.EKLEMETARIHI
            
FROM CEKLER C
  inner join CEKHAREKET CH on CH.ID=(select CH1.ID from CEKHAREKET CH1 where CH1.CEKSENETLERID=C.ID order by CH1.TARIH desc LIMIT 1 )
    INNER JOIN GENINI G ON C.TUR=G.DEGER 
  left outer join REHBER R1 ON C.REHBERID=R1.ID
  left outer join BANKASUBELER BS ON BS.ID = C.BANKASUBELERID
  left outer join BANKALAR B ON B.BANKAKODU = BS.BANKAKODU
  left outer join REHBER R2 on CH.REHBERID=R2.ID
  left outer join BANKAHESAPLAR BHSON on CH.BANKAHESAPLARID=BHSON.ID
  left outer join BANKAHESAPLAR BH2 on C.HESAPID=BH2.ID
Where 1=1    AND C.CEKSENET=101
 and CH.ISLEM in (0,130,131,132,138,133,134,135,136,137)   AND G.BOLUM=-1005
AND    G.ANAHTAR LIKE ''$Durum$%'' AND
         VADE BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
AND 1=case 
       when C.TUR<>136 then 1
       when (C.TUR=136)and(''Tahsil edilmişleri de listele''=''$Tur$'') then 1 
       else 0 end
ORDER BY  c.kur  , C.VADE' WHERE id = 1383;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT     
                CASE WHEN F.MIKTAR < -0.0 THEN ''SARF'' ELSE ''ÜRÜN'' END  AS TURU ,  
               K.AD AS KATEGORI,
               R.FIRMA ,
               S.KOD as  STOKKODU,
               S.STOKADI,    
               FB.FATURATARIH AS TARIH,
               FB.FATURANO as URETIMNO,
               FB.ACIKLAMA,   
               (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA) AS MARKA ,
                (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer)) AS MODEL ,
               (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2704 AND G.DEGER=S.GRUBU) AS GRUBU ,
               (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2703 AND G.DEGER=S.TIPI) AS STOKTIPI ,
               F.MIKTAR AS MIKTAR ,--coalesce(SI.MIKTAR,F.MIKTAR),
                (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2702 AND G.DEGER=S.ANABIRIM) AS BIRIM ,
               BirMalSon(TL)=F.BIRIMFIYAT, 
               TutMalSon(TL)=F.BIRIMFIYAT*F.MIKTAR, --F.BIRIMFIYAT*coalesce(SI.MIKTAR,F.MIKTAR),
               F.KUR AS P.B,
               BirMalSon(Döv)=F.DOVIZ_BIRIMFIYAT, 
               TutMalSon(Döv)=F.DOVIZ_BIRIMFIYAT*ADET,
               F.DOVIZ_KURU AS P.B,
	       BirMalOrt(TL)=ABS(NULLIF((ADET*TUTAR),0)/NULLIF(ADET,0)), 			  
               TutMalOrt(TL)=ABS(ADET*TUTAR),
               F.KUR AS P.B,
               BirMalOrt(Döv)=ABS((NULLIF((ADET*TUTAR),0)/NULLIF(ADET,0))/NULLIF(FB.DOVIZKUR,0)), 
               TutMalOrt(Döv)=ABS(ADET*F.DOVIZ_TUTARI),
               F.DOVIZ_KURU AS P.B,
               --SI.IZLEM,
               FB.DOVIZKUR,
               P.PROJEKODU,
               (SELECT FIRMA FROM REHBER R WHERE R.ID=FB.EKLEYEN)
 AS URETIMSORUMLUSU FROM FATBASLIK FB INNER JOIN FATURA F ON  FB.ID=F.FATBASID
                  INNER JOIN STOKLAR S ON F.URUNID=S.ID                                 
                  LEFT JOIN KATEGORI K ON K.ID=S.KATEGORI
                  --LEFT JOIN STOKIZLEME SI ON SI.STOKID=S.ID AND SI.BASLIKID=FB.ID AND SI.SATIRID=F.ID
                  LEFT OUTER JOIN PROJELER P ON P.ID=FB.PROJEID
                  LEFT JOIN REHBER R ON FB.REHBERID=R.ID
                                  
WHERE FB.TUR=6                 
AND FB.FATURATARIH  between ''$baslama$ 00:00'' and ''$bitis$ 23:59''
and coalesce(K.AD,'''') LIKE ''%$kategori$%''
AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
               AND coalesce(S.GRUBU,'''') LIKE ''$grubu$%''
               AND coalesce(S.MODEL,'''') LIKE ''$model$%''
ORDER BY K.AD' WHERE id = 1384;
UPDATE public.dokumler SET sql = '/*PGX*/select *,
       (select BIRIMMALIYET from STOK_ORT_MALIYET SOM where XX.STOKID=SOM.STOKID AND DEPOID<>8 order by TARIH desc LIMIT 1 ) AS ORT_BIRIM_MAL ,
       coalesce((select sum(MIKTAR) 
                                 from SIPARISDETAY SD inner join SIPARIS S on SD.SIPARISID=S.ID 
                                 where SD.PROJEID=XX.PROJEID and SD.URUNID=XX.STOKID and SD.TUR=1 and S.TUR=101),0.0) AS SATINALMA_TALEP ,
       coalesce((select sum(MIKTAR) 
                                 from FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID 
                                 where F.PROJEID=XX.PROJEID and F.URUNID=XX.STOKID and F.TUR=1 and FB.TUR=11),0.0) AS ALIS_FATURA_MIKTAR ,
       coalesce((select sum(MIKTAR) 
                                 from FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID 
                                 where F.PROJEID=XX.PROJEID and F.URUNID=XX.STOKID and F.TUR=1 and FB.TUR=11),0.0)*(select BIRIMMALIYET from STOK_ORT_MALIYET SOM where XX.STOKID=SOM.STOKID AND DEPOID<>8 order by TARIH desc LIMIT 1 ) AS ALIS_FATURA_TUTAR ,                                 
       coalesce((select sum(MIKTAR) 
                                 from FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID 
                                 where FB.PROJEID=XX.PROJEID and F.URUNID=XX.STOKID and F.TUR=1 and FB.TUR=6),0.0) AS URETIM_FISI ,
       coalesce((select sum(MIKTAR) 
                                 from FATURA F inner join FATBASLIK FB on F.FATBASID=FB.ID 
                                 where F.PROJEID=XX.PROJEID and F.URUNID=XX.STOKID and F.TUR=1 and FB.TUR=20),0.0)

 AS STOKTAN_TRANSFER from(
select P.ID AS PROJEID ,S.ID AS STOKID ,PROJEKODU,S.KOD,S.STOKADI
from 
       PROJELER P join
       STOKLAR S on 1=1
where P.MODUL=11 and
       (exists(select 1 from FATURA F where F.TUR=1 and F.URUNID=S.ID and F.PROJEID=P.ID) or 
       exists(select 1 from SIPARISDETAY SD where SD.TUR=1 and SD.URUNID=S.ID and SD.PROJEID=P.ID))
)as XX

WHERE XX.PROJEKODU LIKE ''%$PROJEKODU$%''' WHERE id = 1385;
UPDATE public.dokumler SET sql = '/*PGX*/


select
coalesce((select SUM(coalesce(MALIYET,0.0)) from ( SELECT * FROM (SELECT KOD,STOKADI,DEPO,KALAN,cast(BIRIMMALIYET as double precision) AS BIRIMMALIYET,cast(MALIYET as double precision) AS MALIYET FROM (  select DISTINCT S.KOD,S.STOKADI,  (SELECT DEPOADI FROM DEPOLAR WHERE ID=DEPO) AS DEPO ,  round(KALAN,2) AS KALAN ,  (SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= :PDonemBas ||'' 00:00''  ORDER BY SM.TARIH DESC  LIMIT 1 ) AS BIRIMMALIYET ,  DRM.KALAN*(SELECT BIRIMMALIYET  FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= :PDonemBas ||'' 00:00''   ORDER BY SM.TARIH DESC  LIMIT 1 )   AS MALIYET from STOKLAR S inner join (SELECT DEPO,URUNID, round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN ,  round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN , round(SUM(NETMIKTAR),2) AS KALAN ,  (SELECT SF.FIYAT FROM STOKFIYAT SF WHERE SF.STOKID=ASD.URUNID AND SF.FIYATADI=34 LIMIT 1 ) AS GUNCEL_SATIS_FIYATI_EURO , (SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON asd.URUNID=SF.STOKID AND SF.FIYATADI=-1  LIMIT 1 )  AS SONALIS_TL FROM( SELECT GIRISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1                                                 AND FB.FATURATARIH <= :PDonemBas ||'' 00:00'' UNION ALL SELECT CIKISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1  AND FB.FATURATARIH <= :PDonemBas ||'' 00:00'' ) AS ASD GROUP BY URUNID,DEPO  HAVING SUM(NETMIKTAR)<>0.0 )as DRM on S.ID=DRM.URUNID)AS AA) AS X)as XS),0.0) AS KDR_DONEM_BASI ,

coalesce((SELECT SUM(coalesce(TUTAR,0.0)) FROM (SELECT   FB.FATURATARIH,   S.KOD,    S.STOKADI AS AD ,   F.ADET,    CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,    CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END   AS TUTAR FROM    FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID       INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR IN (1,11)  WHERE   FB.FATURATARIH BETWEEN :PDonemBas AND :PDonemSon   AND FB.TUR IN (15)   and F.TUR = 1   AND ADET <> 0.0) AS X),0.0) AS KDR_SATIS_FATURA_TUTAR ,

coalesce((SELECT SUM(coalesce(TUTAR,0.0)) FROM (SELECT   FB.FATURATARIH,   S.KOD,    S.STOKADI AS AD ,   F.ADET,    CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,    CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END   AS TUTAR FROM    FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID       INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR IN (1,11)  WHERE   FB.FATURATARIH BETWEEN :PDonemBas AND :PDonemSon   AND FB.TUR IN (11)   and F.TUR = 1   AND ADET <> 0.0) AS X),0.0) AS KDR_ALIS_FATURA_TUTAR ,

coalesce((SELECT SUM(coalesce(MALIYET,0.0)) FROM (SELECT    KOD,STOKADI,DEPO,KALAN,cast(BIRIMMALIYET as double precision) AS BIRIMMALIYET ,cast(MALIYET as double precision) AS MALIYET   FROM(   select     DISTINCT S.KOD,S.STOKADI,    (SELECT DEPOADI FROM DEPOLAR WHERE ID=DEPO) AS DEPO ,    round(KALAN,2) AS KALAN ,    (SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= :PDonemSon    ORDER BY SM.TARIH DESC  LIMIT 1 ) AS BIRIMMALIYET ,    DRM.KALAN*(SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<=:PDonemSon  ORDER BY SM.TARIH DESC  LIMIT 1 )    AS MALIYET from STOKLAR S inner join    (    SELECT      DEPO,URUNID,      round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN ,      round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN ,      round(SUM(NETMIKTAR),2) AS KALAN ,     (SELECT SF.FIYAT FROM STOKFIYAT SF WHERE SF.STOKID=ASD.URUNID AND SF.FIYATADI=34 LIMIT 1 ) AS GUNCEL_SATIS_FIYATI_EURO ,     (SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON asd.URUNID=SF.STOKID AND SF.FIYATADI=-1  LIMIT 1 )     AS SONALIS_TL FROM(      SELECT       GIRISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR     FROM       FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID       WHERE       (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1      AND FB.FATURATARIH <= :PDonemSon      UNION ALL     SELECT       CIKISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR     FROM       FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID      WHERE       (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1      AND FB.FATURATARIH <= :PDonemSon     ) AS ASD     GROUP BY      URUNID,DEPO    HAVING      SUM(NETMIKTAR)<>0.0   )as DRM on S.ID=DRM.URUNID  )AS AA) AS XX),0.0)
 AS KDR_DONEM_SONU ' WHERE id = 1388;
UPDATE public.dokumler SET sql = '/*PGX*/


SELECT KOD,STOKADI,DEPO,KALAN,cast(BIRIMMALIYET as double precision) AS BIRIMMALIYET,cast(MALIYET as double precision) AS MALIYET FROM (
select DISTINCT S.KOD,S.STOKADI,
(SELECT DEPOADI FROM DEPOLAR WHERE ID=DEPO) AS DEPO ,
round(KALAN,2) AS KALAN ,
(SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= :PDonemBas ||'' 00:00''  ORDER BY SM.TARIH DESC  LIMIT 1 ) AS BIRIMMALIYET ,
DRM.KALAN*(SELECT BIRIMMALIYET  FROM STOK_ORT_MALIYET SM WHERE SM.STOKID = DRM.URUNID AND SM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SM.TARIH<= :PDonemBas ||'' 00:00''   ORDER BY SM.TARIH DESC  LIMIT 1 )
 AS MALIYET from STOKLAR S inner join 
                (SELECT DEPO,URUNID, 
                               round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN , 
                               round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN , 
                               round(SUM(NETMIKTAR),2) AS KALAN ,
                                                                                (SELECT SF.FIYAT FROM STOKFIYAT SF WHERE SF.STOKID=ASD.URUNID AND SF.FIYATADI=34 LIMIT 1 ) AS GUNCEL_SATIS_FIYATI_EURO ,
                                                                                (SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON asd.URUNID=SF.STOKID AND SF.FIYATADI=-1  LIMIT 1 )
                  AS SONALIS_TL FROM( SELECT GIRISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
                                               FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
                                               WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1
                                               AND FB.FATURATARIH <= :PDonemBas ||'' 00:00'' 
                                               UNION ALL
                                               SELECT CIKISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
                                               FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
                                               WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
                                               AND FB.FATURATARIH <= :PDonemBas ||'' 00:00'' 
                               ) AS ASD GROUP BY URUNID,DEPO
                HAVING SUM(NETMIKTAR)<>0.0
                )as DRM on S.ID=DRM.URUNID
				)AS AA
' WHERE id = 1389;
