UPDATE public.dokumler SET sql = '/*PGX*/
SELECT 
	PVT.URUNID,
	S.KOD,
	S.STOKADI,
	coalesce(PVT.Sipariş Girecek,0) as Sipariş Girecek,
	coalesce(PVT.Sipariş Çıkacak,0) as Sipariş Çıkacak,
	coalesce(PVT.Depo Toplam,0) as Depo Toplam,
	coalesce(PVT.Genel Toplam,0) as Genel Toplam
FROM (
		select URUNID,
			   TIP,
			   coalesce(CASE WHEN SUM(SMIKTAR)>SUM(FMIKTAR) THEN (SUM(SMIKTAR)-SUM(FMIKTAR))
						 ELSE (SUM(SMIKTAR)-SUM(FMIKTAR))*-1 
					END,0)
		 AS ADET from(
			select 
				SD.URUNID,
				''Sipariş Girecek'' AS TIP ,
				MIKTAR AS SMIKTAR ,
				coalesce((select sum(MIKTAR) from FATURA F where F.YERI between 400 and 420 and F.YERID=SD.ID),0.0)
			 AS FMIKTAR from 
				SIPARIS S inner join SIPARISDETAY SD on S.ID=SD.SIPARISID
			where 
				1=(case when @DepoID<=0 then 1 when S.GIRISDEPO=@DepoID then 1 else 0 end) and
				SD.TUR=1 and 
				S.TUR=9 and
				S.DURUM <> 6
	union all
		select 
				SD.URUNID,
				''Sipariş Çıkacak'' AS TIP ,
				MIKTAR AS SMIKTAR ,
				coalesce((select sum(F.MIKTAR)
								from FATURA F 
								where F.YERI between 400 and 420 and F.YERID=SD.ID and F.YERI <> 415),0.0)
						-
						coalesce((select sum(F2.MIKTAR) 
								from FATURA F2 
								where F2.YERI in (425,426) and F2.YERID in (select F.ID from FATURA F where F.YERI =415 and F.YERID=SD.ID) ),0.0)
			 AS FMIKTAR from SIPARIS S inner join SIPARISDETAY SD on S.ID=SD.SIPARISID
			where 
				1=(case when @DepoID<=0 then 1 when S.CIKISDEPO=@DepoID then 1 else 0 end) and 
				SD.TUR=1 and 
				S.TUR=19 and
				S.DURUM <> 6
		
		)as AA
	group by TIP,URUNID
	union all
	select 
		D.STOKID as URUNID,''Depo Toplam'' AS TIP ,coalesce(sum(GIREN),0.0)-coalesce(sum(CIKAN),0.0) 
	 AS ADET from 
		STOKDURUM D
	where 
		1=(case when @DepoID<=0 then 1 when D.DEPOID=@DepoID then 1 else 0 end)	
	group by
		D.STOKID
	union all
	select URUNID,''Genel Toplam'' AS TIP ,SUM(ADET)
	 AS ADET from(
			select
				D.STOKID as URUNID,
				coalesce(sum(GIREN),0.0)-coalesce(sum(CIKAN),0.0)
			 AS ADET from STOKDURUM D
			where 
				1=(case when @DepoID<=0 then 1 when D.DEPOID=@DepoID then 1 else 0 end)
			group by
				D.STOKID				 
			union all

			select URUNID,sum(ADET)

			 AS ADET from(

				select URUNID,''Sipariş Toplam'' AS TIP ,sum(ADET)
				 AS ADET FROM(
					select URUNID,TIP,CASE WHEN SUM(SMIKTAR)>SUM(FMIKTAR) THEN (SUM(SMIKTAR)-SUM(FMIKTAR))
					ELSE (SUM(SMIKTAR)-SUM(FMIKTAR))*-1 END
					 AS ADET from(
						select 
							SD.URUNID,
							''Sipariş Girecek'' AS TIP ,
							MIKTAR AS SMIKTAR ,
							coalesce((select sum(MIKTAR) from FATURA F where F.YERI between 400 and 420 and F.YERID=SD.ID),0.0)
						 AS FMIKTAR from 
							SIPARIS S inner join SIPARISDETAY SD on S.ID=SD.SIPARISID
						where 
							1=(case when @DepoID<=0 then 1 when S.GIRISDEPO=@DepoID then 1 else 0 end) and 
							SD.TUR=1 and 
							S.TUR=9 and
							S.DURUM <> 6	
						)as AA
					group by TIP,URUNID

				union all

				select URUNID,TIP,CASE WHEN SUM(SMIKTAR)>SUM(FMIKTAR) THEN -1*(SUM(SMIKTAR)-SUM(FMIKTAR))
									ELSE SUM(SMIKTAR)-SUM(FMIKTAR) END
					 AS ADET from(
				select 
							URUNID,
							''Sipariş Çıkacak'' AS TIP ,
							MIKTAR AS SMIKTAR ,
							coalesce((select sum(F.MIKTAR)
											from FATURA F 
											where F.YERI between 400 and 420 and F.YERID=SD.ID and F.YERI <> 415),0.0)
									-
									coalesce((select sum(F2.MIKTAR) 
											from FATURA F2 
											where F2.YERI in (425,426) and F2.YERID in (select F.ID from FATURA F where F.YERI =415 and F.YERID=SD.ID) ),0.0)
						 AS FMIKTAR from SIPARIS S inner join SIPARISDETAY SD on S.ID=SD.SIPARISID
						where 
							1=(case when @DepoID<=0 then 1 when S.CIKISDEPO=@DepoID then 1 else 0 end) and
							SD.TUR=1 and 
							S.TUR=19 and
							S.DURUM <> 6

						)as AA
				group by TIP,URUNID
				) AS XYZ
			group by URUNID
			)as AA
			group by URUNID
		)as asd
		group by URUNID
) AS PIVOT_TABLE
PIVOT
(
	SUM(ADET) FOR TIP IN (Sipariş Girecek,Sipariş Çıkacak,Depo Toplam,Genel Toplam)
)
AS PVT INNER JOIN STOKLAR S ON S.ID = PVT.URUNID
where
	Sipariş Girecek <> 0 or Sipariş Çıkacak <> 0 or Depo Toplam <> 0 or Genel Toplam<> 0
' WHERE id = 1393;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT DISTINCT --A
UE.ID,fn_TarihFarkiFormatli( UOP.BASLAMA, UOP.BITIS-UOP.MOLA-2.0 ) AS SURE ,
UOP.TARIH,R.FIRMA AS PERSONEL ,--PDK.GIRIS,
--PERS_DURUM=(SELECT ANAHTAR FROM GENINI G WHERE BOLUM=-2211 AND G.DEGER=PDK.DURUM AND R.ID=PDK.REHBERID),
UOP.KONUSU,UOP.BASLAMA,UOP.BITIS,UOP.MOLA,G.ANAHTAR AS DURUM,P.PROJEADI,P.PROJEKODU,S.KOD,S.STOKADI

FROM REHBER R LEFT OUTER JOIN PERS_PDKS PDK ON PDK.REHBERID=R.ID --AND PDK.GIRIS between ''$baslama$ 00:00''  and ''$baslama$ 23:59''
		LEFT OUTER JOIN URETIMOPERASYONPERSONEL UOP ON UOP.PERSONEL=R.ID-- AND UOP.TARIH between ''$baslama$ 00:00''  and ''$baslama$ 23:59''
		LEFT OUTER JOIN  URETIMOPERASYON UO ON UOP.OPERASYONID=UO.ID
		LEFT OUTER JOIN  URETIMEMRI UE ON UE.ID=UO.URETIMEMRIID
		LEFT OUTER JOIN PROJELER P ON P.ID=UE.PROJEID
		LEFT OUTER JOIN GENINI G ON G.DEGER=UOP.DURUM AND G.BOLUM=-3027
		LEFT OUTER JOIN STOKLAR S ON S.ID=UE.STOKID
	
WHERE R.KOD not like ''102.%'' 
								 and R.ID > 0  and R.DURUM > 0    and R.GRUP =335
								  AND UOP.TARIH between ''$baslama$ 00:00''  and ''$bitis$ 23:59''  
								 order by 6 ,4 ,8' WHERE id = 1395;
UPDATE public.dokumler SET sql = '/*PGX*/



 --DENEME
SELECT * FROM 
(
SELECT *,GECEN_GUN=DATEDIFF( DAY,SONHAREKETTARIHI,''$Bitis$ 23:59''),
	YIL=year(SONHAREKETTARIHI),
	AY=month(SONHAREKETTARIHI),
	TOPMALIYET= KALAN*SONBIRIMMALIYET,
    0-120=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI<121.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    121-180=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=121.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<181.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    181-480=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=181.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<481.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    481-990=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=481.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<991.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    991-1500=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=991.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<1501.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    1501-3000=case when ''$Bitis$ 23:59''-SONHAREKETTARIHI>=1501.0 and ''$Bitis$ 23:59''-SONHAREKETTARIHI<3001.0 then KALAN*SONBIRIMMALIYET else 0.0 end,
    3001+=case when KALAN >= 3001 then KALAN*SONBIRIMMALIYET else 0.0 end  	        
FROM(
	SELECT 
		DRM.DEPO,
		S.KOD,S.STOKADI,
		SONHAREKETTARIHI=(SELECT FATURATARIH FROM FATBASLIK FB 
			WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND 
			FB.TUR<>2 AND	FB.FATURATARIH <= ''$Bitis$ 23:59'' AND FB.ID IN (SELECT FATBASID FROM FATURA F WHERE URUNID = S.ID AND F.TUR = 1) ORDER BY 1 DESC LIMIT 1 ),
		SONBIRIMMALIYET=(SELECT SOM.BIRIMMALIYET FROM STOK_ORT_MALIYET SOM  WHERE  STOKID=DRM.URUNID AND  SOM.DEPOID = CASE WHEN DRM.DEPO = 5 THEN 1 ELSE DRM.DEPO END AND SOM.TARIH<= ''$Bitis$ 23:59'' and  coalesce(DEPOID,'''') LIKE ''%'' ORDER BY SOM.TARIH DESC LIMIT 1 ),

		KALAN=DRM.KALAN									   
	FROM  
		STOKLAR S  INNER JOIN
		(		
			SELECT 
				DEPO,
				URUNID,
				SUM(KALAN) AS KALAN 
			FROM(    
				SELECT DEPO=GIRISDEPO,
					   F.URUNID,
					   KALAN=CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END 
				FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
				WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND
				FB.TUR<>2 AND FB.FATURATARIH <= ''$Bitis$ 23:59'' AND (F.STOKDURUMDEGIS = 1) AND 
				(coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1                                               
				UNION ALL
				SELECT 
					DEPO=CIKISDEPO,
					F.URUNID,
					KALAN= CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END 
				FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
				WHERE 1=CASE WHEN ''$Depo$''=0 THEN 1 WHEN ''$Depo$''=coalesce(FB.GIRISDEPO,-1) THEN 1 WHEN ''$Depo$''=coalesce(FB.CIKISDEPO,-1) THEN 1 ELSE 0 END AND
				FB.TUR<>2 AND   FB.FATURATARIH <= ''$Bitis$ 23:59''  AND (F.STOKDURUMDEGIS = 1) AND 
				(coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
                )AS ICSORGU GROUP BY DEPO,URUNID
		 )  AS DRM ON S.ID = DRM.URUNID
	--WHERE  
	--	S.ID=151075
		)AS BBB     
	) AS XXX

WHERE SONHAREKETTARIHI IS NOT NULL
AND KALAN>0  
ORDER BY 6
' WHERE id = 1396;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT XX.REFERANSNO,XX.KONUSU,XX.KATEGORİ,XX.TIPI,XX.BASLATAN,XX.TARIH,XX.DURUMU,XX.FARK AS GÜN_FARKI FROM 
(
SELECT X.*,
CASE WHEN X.KATEGORİ=''Majör'' THEN  X.Gün_Farkı+30
		  WHEN X.KATEGORİ=''Minör'' THEN  X.Gün_Farkı+90
		  else x.Gün_Farkı end AS FARK ,
CASE WHEN X.DURUM=1 THEN  ''Yeni''
		    WHEN X.DURUM=2 THEN  ''İncelemede''
		    WHEN X.DURUM=3 THEN  ''Onaylandı''
		    else ''Kapandı'' end
  AS DURUMU FROM (
SELECT SO.REFERANSNO,SO.KONUSU,G.ANAHTAR AS KATEGORİ,CASE WHEN TIPI=1 THEN ''Sapma'' else ''Olay'' end AS TIPI ,
R.FIRMA AS BASLATAN,TARIH,DATEDIFF(day,now(),TARIH) AS Gün_Farkı,SO.DURUM--,*
 FROM KY_SAPMAOLAY SO 
			LEFT JOIN GENINI G ON G.DEGER=SO.KATEGORI AND BOLUM=-32100 
			INNER JOIN REHBER R ON R.ID=SO.BASLATAN

) AS X 
) AS XX WHERE XX.FARK<=-1 and XX.DURUM<>4' WHERE id = 1397;
UPDATE public.dokumler SET sql = '/*PGX*/select            
       KOD,FIRMA,ADSOYAD,
        case when PERS_ISTEL is not null then PERS_ISTEL else CARI_ISTEL end AS ISTEL ,
       
       case when PERS_CEP is not null then PERS_CEP else CARI_CEP end AS CEPTEL ,
          case when PERS_FAX is not null then PERS_FAX else CARI_FAX end AS FAX ,
        case when LTRIM(RTRIM(coalesce(PERS_ADRES,'''')))<>'''' then PERS_ADRES else CARI_ADRES end AS ADRES ,
	   ILCE,
	   IL,
	   NOTLAR,
        case when PERS_EMAIL is not null then PERS_EMAIL else CARI_EMAIL end AS EMAIL ,
       (select FIRMA from REHBER where ID=Y.SUBEID) AS SUBEAD ,
       (select ANAHTAR from GENINI where BOLUM=-2210 and DIL=-1 and DEGER=BOLGE) AS BOLGE ,
       (select ANAHTAR from GENINI where BOLUM=''-2210''||cast(BOLGE as varchar) and DEGER=ALTBOLGE and DIL = -1) AS ALTBOLGE ,
       (select ANAHTAR from GENINI where BOLUM=-2204 and DIL=-1 and DEGER=SEKTOR) AS SEKTOR ,
       (select ANAHTAR from GENINI where BOLUM=''-2204''||cast(SEKTOR as varchar) and DIL=-1 and DEGER=ALTSEKTOR) AS ALTSEKTOR ,
       (select FIRMA from REHBER where ID=Y.TEMSILCI) AS TEMSILCI ,
       EKIPMANSAYISI ,
                   MAIL_DAGITIM,POSTA ,VGNO


from(
       select * ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID AND RA.VARSAYILAN=40 LIMIT 1 ) AS CARI_ISTEL ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=42 LIMIT 1 ) AS CARI_CEP ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=43 LIMIT 1 ) AS CARI_FAX ,
             coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=2 LIMIT 1 ),'''')
                    
                   ||'' ''|| coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=4 LIMIT 1 ),'''') AS CARI_ADRES ,
				   coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=6 LIMIT 1 ),'''') AS ILCE ,
                    coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=8 LIMIT 1 ),'''') AS IL ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILETISIMID  AND RA.VARSAYILAN=46 LIMIT 1 ) AS CARI_EMAIL ,

             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID AND RA.VARSAYILAN=40 LIMIT 1 ) AS PERS_ISTEL ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=42 LIMIT 1 ) AS PERS_CEP ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=43 LIMIT 1 ) AS PERS_FAX ,
             coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=2 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=6 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=4 LIMIT 1 ),'''')
                    ||'' ''||coalesce((SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=8 LIMIT 1 ),'''') AS PERS_ADRES ,
             (SELECT BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI WHERE RB.YER_ID=X.ILGILIID  AND RA.VARSAYILAN=46 LIMIT 1 ) AS PERS_EMAIL ,
              (SELECT COUNT(*) FROM EKIPMANREHBER ER WHERE ER.REHBERID=X.REHBERID)  AS EKIPMANSAYISI ,
              Case wheN coalesce(STATU,1)=1 then coalesce((SELECT RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.SIRA=RB.SIRA AND RA.VARSAYILAN=22 WHERE RA.YERI=2 AND RB.YER_ID=4795 AND RB.YERI=2  LIMIT 1 ),'''') ELSE '''' END
        AS VGNO from(
                    select 
                           Case when RP.ID is null then 1 else 4 end AS YER ,
						   
			 (Select GY.YORUM from GOREVYORUM GY where R.ID=GY.GOREVID and GY.TUR=11 order by GY.TARIH desc LIMIT 1 )   AS NOTLAR ,
                           R.ID AS REHBERID ,R.STATU,
                           (select ID from REHBERILETISIM RI where RI.REHBERID=RP.ID order by RI.VARSAYILAN desc LIMIT 1 ) AS ILGILIID ,
                           (select ID from REHBERILETISIM RI where RI.REHBERID=R.ID order by RI.VARSAYILAN desc LIMIT 1 ) AS ILETISIMID ,
                           R.KOD,R.FIRMA,RP.FIRMA AS ADSOYAD ,R.TEMSILCI,R.KATEGORI,R.SINIF,R.BOLGE,R.ALTBOLGE,R.SEKTOR,R.ALTSEKTOR,
coalesce((  SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON  RA.ETIKET=RB.ETIKET 
          WHERE  RA.ETIKET=''E-Mail Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=Rp.ID LIMIT 1 ),(
          SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON  RA.ETIKET=RB.ETIKET 
          WHERE  RA.ETIKET=''E-Mail Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=R.ID LIMIT 1 )) AS MAIL_DAGITIM , 
coalesce(( SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI                   
          WHERE  RA.ETIKET=''Posta Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=Rp.ID LIMIT 1 ),( 
          SELECT BILGI 
          FROM   REHBERILETISIM RI inner join
                 REHBERBILGI RB ON RI.ID=RB.YER_ID INNER JOIN 
                 REHBERAYAR RA  ON RA.ETIKET=RB.ETIKET AND RA.YERI=RB.YERI                   
          WHERE  RA.ETIKET=''Posta Dağıtım'' AND
                 RA.YERI=1 and Rb.YERI=1 and RI.REHBERID=R.ID LIMIT 1 ))  
  AS POSTA , R.SUBEID

                    from 
                           REHBER R left outer join 
                           REHBER RP on R.ID=RP.BAGID and RP.DURUM <> 3
                    where R.ID>0 and R.DURUM<>0  AND R.GRUP IN (1)
                    
             ) as X
       ) as Y 

where
          FIRMA LIKE ''$Firma$%''
           AND coalesce((select ANAHTAR from GENINI where BOLUM=-2210 and DIL=-1 and DEGER=BOLGE),'''') LIKE ''$Bolge$%''
            
            and  coalesce((select GB.ANAHTAR||'' - ''||GALT.ANAHTAR  AS BOLGE from GENINI GB inner join GENINI GALT on
                                cast(GALT.BOLUM as varchar)=GB.BOLUM||cast(GB.DEGER as varchar)
                                and GALT.DEGER=ALTBOLGE AND GB.DEGER=BOLGE
                                where GALT.BOLUM like ''-2210%'' and length(GALT.BOLUM)>5 and GB.BOLUM=-2210 ),'''')  like ''$Altbolge$%''
           AND coalesce((select ANAHTAR from GENINI where BOLUM=-2204 and DIL=-1 and DEGER=SEKTOR),'''') LIKE ''$Sektor$%''
        AND coalesce((select ANAHTAR from GENINI where BOLUM=''-2204''||cast(SEKTOR as varchar) and DIL=-1 and DEGER=ALTSEKTOR),'''') LIKE ''$Altsektor$%''
       AND coalesce((select FIRMA from REHBER where ID=Y.TEMSILCI),'''') LIKE ''$Temsilci$%''
         and ISNULL ((select FIRMA from REHBER where ID=Y.SUBEID),'''') LIKE ''$Sube$%''
        and ISNULL (POSTA,'''') LIKE ''$Posta$%''
         and ISNULL (MAIL_DAGITIM,'''') LIKE ''$Mail$%''
        AND 1 = CASE WHEN ''$Ekipman$''=''Var'' AND EKIPMANSAYISI>0 THEN 1
                     WHEN ''$Ekipman$''=''Yok'' AND EKIPMANSAYISI=0 THEN 1
                     WHEN ''$Ekipman$''=''''THEN 1 ELSE 0 END' WHERE id = 1398;
UPDATE public.dokumler SET sql = '/*PGX*/-- ENVANTER RAPORUNDAKİ ANADEPO ADETİ İLE ANADEPODAKİ KALAN ADETİ KARŞILAŞTIRIR. 


SELECT * INTO #ENVANTER FROM (
SELECT KOD,SUM(KLN) AS ENVANTER FROM (
SELECT DISTINCT S.KOD,S.STOKADI,K.AD AS KATEGORI,G.ANAHTAR AS MARKA ,
D.DEPOADI,GRN,CKN,ROUND(KLN,2)AS KLN,ORTMALIYET,cast(SONALISFIYAT as double precision) AS SONALISFIYAT,ORTTUTAR =ROUND((ORTMALIYET*KLN),2),ORTSONTUTAR=ROUND((SONALISFIYAT*KLN),2)
FROM(
SELECT URUNID,DSA.GIRISDEPO,GRN,CKN,KLN,ORTMALIYET,
              SONALISFIYAT=ROUND((SELECT TUTAR=BIRIMFIYAT--CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT*(1+(KDV/100.0)) ELSE BIRIMFIYAT END
                                                                                              FROM 
                                                                                                              FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                                                                                              WHERE 
                                                                                                              F.URUNID=DSA.URUNID AND
                                                                                                              F.STOKDURUMDEGIS = 1 AND coalesce(FB.GIRISDEPO,0)<>0 AND F.TUR=1 ORDER BY TARIH DESC  LIMIT 1 ),2)
FROM
                (SELECT ASD.URUNID,ASD.GIRISDEPO,MIKTAR=SUM(CASE WHEN GC=''G'' THEN MIKTAR ELSE -MIKTAR END),
        ORTMALIYET=case when coalesce(MIKTAR,0)<>0 THEN ROUND((ROUND(SUM(TUTAR),2)/SUM(MIKTAR)),2)  ELSE 0 END
                FROM
                 (SELECT 
                        GC=''G'',URUNID,
                        SUM(MIKTAR) AS MIKTAR,
                        FB.GIRISDEPO,
                        TUTAR=SUM(TUTAR)--CASE WHEN FB.KDVDURUM=''Hariç'' THEN TUTAR*(1+(KDV/100.0)) ELSE TUTAR END,
                        --FB.TUR,FB.KDVDURUM,F.KDV
                 FROM 
                      FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                               WHERE F.STOKDURUMDEGIS = 1 AND coalesce(FB.GIRISDEPO,0)<>0 AND F.TUR=1
                               GROUP BY URUNID,FB.GIRISDEPO
                               )AS ASD

                GROUP BY ASD.URUNID,ASD.GIRISDEPO,ASD.MIKTAR
                )AS DSA INNER JOIN 
                               (SELECT STOKID,DEPOID,GRN=SUM(GIREN),CKN=SUM(CIKAN),KLN=SUM(KALAN) 
                               FROM STOKDURUM
                
                               GROUP BY STOKID,DEPOID)AS XXX
                
                ON DSA.URUNID=XXX.STOKID     AND XXX.DEPOID=DSA.GIRISDEPO
                
) AS X INNER JOIN STOKLAR S  ON X.URUNID=S.ID AND S.DURUM=1
       INNER JOIN DEPOLAR D  ON D.ID=X.GIRISDEPO
          LEFT JOIN  KATEGORI K ON S.KATEGORI=K.ID
          LEFT JOIN GENINI G ON G.DEGER=S.MARKA AND G.BOLUM=-2701
where
    S.KOD LIKE ''%''
       --S.KOD LIKE ''%''
) AS Y
  WHERE
    coalesce(DEPOADI,'''') LIKE ''Anadepo%''
       --   DEPOADI  LIKE ''%'' 
        AND coalesce(KATEGORI,'''') LIKE ''%''
GROUP BY 
       KOD
) AS ENVANTER

SELECT *, FARK = A.ANADEPO-E.ENVANTER FROM (
SELECT KOD,SUM(KALAN) AS ANADEPO FROM (
       SELECT 
             S.KOD,
             S.URUNNO,
             S.STOKADI,
             S.OZELKOD,
             GI.ANAHTAR AS MARKA,
             GG.ANAHTAR AS GRUBU,
             GE.ANAHTAR AS TIPI,
             SL.LOTNO,
             SL.SKT,
             SDI.KALAN,
             KALANGUN=DATEDIFF(DAY,now(),SL.SKT)
       FROM 
             STOKLAR S INNER JOIN STOKDURUMIZLEME SDI ON S.ID = SDI.STOKID
                             LEFT JOIN GENINI GI ON GI.BOLUM = -2701 AND S.MARKA = GI.DEGER
                             LEFT JOIN GENINI GG ON GG.BOLUM = -2704 AND S.GRUBU = GG.DEGER
                             LEFT JOIN GENINI GE ON GE.BOLUM = -2703 AND S.TIPI = GE.DEGER
                             INNER JOIN STOKSERILOT SL ON SL.ID=SDI.SERILOTID
                           --INNER JOIN STOKDURUMIZLEME SDI ON SDI.SERILOTID=SL.ID
       WHERE
             SDI.DEPOID = 1
             AND SDI.KALAN>0
             AND S.DURUM=1       
) AS X 
WHERE
       KALANGUN <= 9999999
GROUP BY
       KOD
) AS A INNER JOIN #ENVANTER E ON E.KOD = A.KOD
WHERE A.ANADEPO-E.ENVANTER <> 0
DROP TABLE #ENVANTER' WHERE id = 1400;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	URETIMEMRIID,
	S.KOD,
	S.STOKADI,
	UO.MIKTAR,
	coalesce(ASD.GERCEKLESEN,0.0) AS GERCEKLESEN ,
	UO.MIKTAR-coalesce(ASD.GERCEKLESEN,0.0) AS FARK
FROM 
	URETIMOPERASYON UO LEFT OUTER JOIN
	(	SELECT 
			UO1.ID AS UOID ,min(FB.TARIH) AS GBASTAR ,max(FB.FATURATARIH) AS GBITTAR ,SUM(F.MIKTAR) 
		 AS GERCEKLESEN FROM 
			URETIMOPERASYON UO1 INNER JOIN 
			FATBASLIK FB on FB.YERI=142 AND FB.YERID=UO1.ID INNER JOIN
			FATURA F on F.FATBASID=FB.ID AND F.TUR=1 AND UO1.STOKID=F.URUNID
		GROUP BY 
			UO1.ID
	) as ASD on
	UO.ID=ASD.UOID
		LEFT OUTER JOIN LOKASYON L1 on UO.LOKASYON=L1.ID
		LEFT OUTER JOIN LOKASYON L2 on UO.ISMERKEZI=L2.ID
		LEFT OUTER JOIN STOKLAR S on UO.STOKID=S.ID
		LEFT OUTER JOIN URETIMEMRI UE ON UE.ID = UO.URETIMEMRIID 
WHERE
	UO.MIKTAR <> coalesce(ASD.GERCEKLESEN,0.0)
	AND UE.DURUM = 0' WHERE id = 1401;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT     --asas               
ISLEMTUR,FATURATUR,OZELKOD,ZARF,TIPI,FATURATARIH,month(FATURATARIH) AS BELGE_AY ,FATURANO,CARIKOD,FIRMA,VERGINO,STOK_OZELKOD,KOD,AD,ACIKLAMA,cast(ADET as double precision) AS ADET,ANAHTAR,
cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT,
cast(BIRIMFIYAT*ADET as double precision) AS TUTAR ,          
ISKONTO,
cast((BIRIMFIYAT*ADET) as double precision)-TUTAR AS ISKONTOTUTARI ,--ROUND((((BIRIMFIYAT*ADET)/100.0)*ISKONTO),2),
KDV,
cast(TUTAR as double precision) AS KDVMATRAHI ,
cast(KDVLITOPLAM as double precision)-TUTAR AS KDVTUTAR ,
cast(KDVLITOPLAM as double precision) AS GENELTOPLAM ,
DOVIZ_CINSI,
   CASE WHEN DOVIZ_CINSI<>''TL'' THEN ROUND(DOVIZ_BIRIMFIYAT,2)
                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12) THEN  ROUND((BIRIMFIYAT/coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)
                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN ROUND((BIRIMFIYAT/coalesce((SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)
                    
                         ELSE 0 END AS DOVIZ_BIRIMFIYAT ,
                         
 CASE WHEN DOVIZ_CINSI<>''TL'' THEN KURU
                       WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12)   THEN  (SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp))
                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN  (SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp))
                    END AS KURU ,


                   -- CASE WHEN DOVIZ_CINSI<>''TL'' AND KURU>0 THEN ROUND((((BIRIMFIYAT*ADET)-TUTAR)/KURU),2) 
                   CASE WHEN DOVIZ_CINSI<>''TL'' THEN (BIRIMFIYAT*ADET)-TUTAR
                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12) THEN  ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)
                                                                  /coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)
                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN  ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)
                                                                  /coalesce((SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)
                    
                         ELSE 0 END AS DOVIZ_ISKONTOTUTARI ,

                                               CASE WHEN DOVIZ_CINSI<>''TL'' AND KURU>0 THEN (ROUND(BIRIMFIYAT/KURU,2)*ADET)-ROUND((((BIRIMFIYAT*ADET)-TUTAR)/KURU),2) 
                                                    WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12) THEN (ROUND(BIRIMFIYAT/(coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)*ADET)-ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)/
                                                                            (coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1))
                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN  (ROUND(BIRIMFIYAT/(coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)*ADET)-ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)/
                                                                    coalesce((SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)
                                               ELSE 0 END AS DOVIZ_MATRAHI , 
  DOVIZ_TUTARI + ((DOVIZ_TUTARI*KDV)/100) AS DOVIZ_GENEL_TOPLAM ,                                               
MASRAFKODU,
TOPLAM_MALİYET/ADET AS BIRIM_MALIYET ,
TOPLAM_MALİYET,
(TUTAR-TOPLAM_MALİYET)/ADET AS BIRIM_KARLILIK ,
TUTAR-TOPLAM_MALİYET AS TOPLAM_KARLILIK ,
MASRAFADI,KATEGORIADI,GRUPADI,KDVDURUM,OZELKOD_ ,YETKIKODU_,ALICI_SATICI(BÜTÜN),ALICI_SATICI(SATIR),PROJEADI,PROJEKODU,SUBE,SONALIS_TL,
MARKA,MODEL,ILCE,IL,PERSONEL,ACIKLAMA1,ACIKLAMA2,EAD,SERINO,FATURASERI,F_OZELKOD,F_OZELKOD2 ,
Alım_İndirimleri, Alım_İadeler, Alım_Hesabı,Satışlar_Hesabı,  Satış_İadeler,  Satış_İndirimler


FROM (

SELECT 
fb.OZELKOD,
BZ.AD AS ZARF ,FB.TUR,
 CASE WHEN FB.TIPI=1 THEN ''Alış/Satış'' WHEN FB.TIPI=2 THEN ''İade'' WHEN FB.TIPI=3 THEN ''Fiyat Farkı'' WHEN FB.TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
RI1.ANAHTAR AS FATURATUR,
FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR ,
(SELECT OZELKOD FROM STOKLAR S where  F.URUNID=S.ID  )   AS STOK_OZELKOD , 
 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
F.ACIKLAMA,F.ADET,RI.ANAHTAR,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
F.ISKONTO,F.KDV,
FB.RAPORDOVIZ AS DOVIZ_CINSI , --F.DOVIZ_TUTARI,
 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.DOVIZ_TUTARI ELSE F.DOVIZ_TUTARI/(1+(F.KDV/100.0)) END AS DOVIZ_TUTARI ,
CASE WHEN FB.RAPORDOVIZ <> ''TL'' THEN F.DOVIZ_BIRIMFIYAT ELSE 0 END AS DOVIZ_BIRIMFIYAT ,
CASE WHEN FB.RAPORDOVIZ<>''TL'' AND F.DOVIZ_TUTARI>0 THEN ROUND(cast((F.TUTAR/F.ADET)/(F.DOVIZ_TUTARI/F.ADET) as double precision),4) ELSE 0 END  AS KURU ,MG.KOD AS MASRAFKODU,MG.AD AS MASRAFADI,
--KATEGORIADI = coalesce((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID)),''Kategorisiz''),
--GRUPADI     = coalesce((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID)),''Grupsuz''),
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                            ELSE 
                            coalesce(((SELECT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')

                            END AS KATEGORIADI ,
 CASE WHEN F.TUR IN (1,11) THEN
                            coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                            ELSE 
                                      ''Grupsuz''

                            END   AS GRUPADI ,
FB.KDVDURUM ,
(SELECT OZELKOD FROM MASRAFGELIR S where  F.URUNID=S.ID  )   AS OZELKOD_ ,
(SELECT YETKIKODU FROM MASRAFGELIR S where  F.URUNID=S.ID  ) AS YETKIKODU_ ,
ALICI_SATICI(BÜTÜN)=(SELECT FIRMA FROM REHBER WHERE FB.SATICIKODU=REHBER.ID) ,
ALICI_SATICI(SATIR)=(SELECT FIRMA FROM REHBER WHERE F.SATICIKODU=REHBER.ID) ,
P.PROJEADI,P.PROJEKODU,
(SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID=FB.SUBEID) AS SUBE ,
(SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON F.URUNID=SF.STOKID AND SF.FIYATADI=-1 AND F.TUR=1 LIMIT 1 ) AS SONALIS_TL ,
(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA AND F.TUR=1) AS MARKA ,
 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer) AND F.TUR=1)   AS MODEL ,
coalesce(ROUND(F.MIKTAR*coalesce(SOM.BIRIMMALIYET,0.0),2),0.0) as TOPLAM_MALİYET,(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA 
AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=22 LIMIT 1 )  AS VERGINO ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
(SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
(SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU=R1.ID) AS PERSONEL ,FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,E.AD AS EAD ,ER.SERINO,FB.FATURASERI,
F.OZELKOD AS F_OZELKOD ,F.OZELKOD2 AS F_OZELKOD2 ,
Alım_İndirimleri=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=-3),
Alım_İadeler=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=-2),
Alım_Hesabı=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=-1),
Satışlar_Hesabı=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=1),
Satış_İadeler=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=2),
Satış_İndirimler=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=3) 



FROM 

FATBASLIK FB 
         INNER JOIN FATURA F ON 
                   FB.ID=F.FATBASID 
          left outer join STOK_ORT_MALIYET SOM ON 
                                  F.ID=SOM.FATURAID AND F.URUNID = SOM.STOKID  
                                  AND SOM.DEPOID = CASE WHEN FB.TUR IN (11,12) THEN FB.GIRISDEPO 
                                                        WHEN FB.TUR IN (15,16) THEN FB.CIKISDEPO
                                                    END      
         LEFT OUTER JOIN REHBER R ON 
                   FB.REHBERID=R.ID
         LEFT OUTER JOIN MASRAFGELIR MG ON
                   F.MASRAFID=MG.ID-- AND
         LEFT OUTER JOIN REHBERINI RI ON
                   RI.BOLUM=''StokKart_Anabirim'' and
                   RI.DEGER=F.BIRIM
         LEFT OUTER JOIN REHBERINI RI1 ON
                   RI1.BOLUM=''Kasa Türleri'' and
                   RI1.DEGER=FB.TUR
        LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
        LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
	LEFT OUTER JOIN STOKLAR S ON S.ID=F.URUNID  
        LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
        LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID



WHERE
FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
--AND FB.TUR BETWEEN 10 AND 17
AND FB.TUR IN (8,11,12,15,16)
AND ADET <>0.0


) AS X
--WHERE coalesce(GRUPADI,'''') LIKE ''$GrupAdi$%''
--      AND FATURATUR LIKE  ''$FaturaTur$%''
--      and KATEGORIADI LIKE ''%$Kategori$%''
 --     and ISLEMTUR LIKE ''$IslemTuru$%''
ORDER BY FATURATUR,GRUPADI,KATEGORIADI,FATURATARIH,ISLEMTUR' WHERE id = 1402;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT * FROM (
	SELECT 
		S.KOD,
		S.URUNNO,
		S.STOKADI,
		S.OZELKOD,
		GI.ANAHTAR AS MARKA,
		GG.ANAHTAR AS GRUBU,
		GE.ANAHTAR AS TIPI,
    		CASE S.BILDIRIM WHEN ''2'' THEN ''ÜTS'' ELSE ''YOK''END AS BILDIRIM ,		
		SL.LOTNO,
                SL.SERINO,
		SL.SKT,
		SDI.KALAN,
		DATEDIFF(DAY,now(),SL.SKT)
	 AS KALANGUN FROM 
		STOKLAR S INNER JOIN STOKDURUMIZLEME SDI ON S.ID = SDI.STOKID
				  LEFT JOIN GENINI GI ON GI.BOLUM = -2701 AND S.MARKA = GI.DEGER
				  LEFT JOIN GENINI GG ON GG.BOLUM = -2704 AND S.GRUBU = GG.DEGER
				  LEFT JOIN GENINI GE ON GE.BOLUM = -2703 AND S.TIPI = GE.DEGER
				  INNER JOIN STOKSERILOT SL ON SL.ID=SDI.SERILOTID AND SL.STOKID = S.ID
                                  INNER JOIN DEPOLAR D ON D.ID = SDI.DEPOID
				--INNER JOIN STOKDURUMIZLEME SDI ON SDI.SERILOTID=SL.ID
	WHERE
		D.DEPOADI LIKE ''$DEPOADI$%''
		AND SDI.KALAN>0
		AND S.DURUM=1 		
) AS X
WHERE    
	KALANGUN <= ''$SKTKALANGUN$''
        AND coalesce(MARKA,'''') LIKE ''$MARKA$%''
        AND coalesce(GRUBU,'''') LIKE ''$GRUBU$%''
        AND KOD LIKE ''$STOKKOD$%''
        ORDER BY 11' WHERE id = 1403;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
       FIRMA,KONSINYETARIHI,KONSINYENO,URUNGRUBU,BILDIRIM,URUNKOD,URUNNO,URUNAD,
       KALAN,SKT,LOT,SERINO,
       KALANGUN,
          BIRIMMALIYET,
          T.MALIYET
    FROM(
             SELECT
                    R.FIRMA AS FIRMA,
                    FB.FATURATARIH AS KONSINYETARIHI,
                    FATURANO AS KONSINYENO,
                     (SELECT ANAHTAR FROM GENINI G,STOKLAR S WHERE G.BOLUM=''-2704'' AND G.DEGER=S.GRUBU AND S.ID=F.URUNID) AS URUNGRUBU ,
                     (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID) AS URUNKOD ,
                     (SELECT URUNNO FROM STOKLAR WHERE ID = F.URUNID) AS URUNNO ,
                     (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID) AS URUNAD ,
                    CASE S.BILDIRIM WHEN ''2'' THEN ''ÜTS'' ELSE ''YOK''END AS BILDIRIM ,		
                     SL.SKT AS SKT ,
                     SL.LOTNO AS LOT ,
					 SL.SERINO AS SERINO ,
                    datediff(day,now(),SL.SKT) AS KALANGUN ,
                    SI.KALAN,
                    SOM.BIRIMMALIYET,
                    SI.KALAN*SOM.BIRIMMALIYET AS T.MALIYET
             FROM
                    FATURA F INNER JOIN FATBASLIK FB on F.FATBASID=FB.ID 
                                  LEFT OUTER JOIN STOKIZLEME SI on SI.BASLIKID=F.FATBASID and SI.SATIRID=F.ID
                                  LEFT JOIN REHBER R ON FB.REHBERID=R.ID
                                  INNER JOIN STOKSERILOT SL ON SL.ID=SI.SERILOTID
                                  INNER JOIN STOKDURUMIZLEME SDI ON SDI.SERILOTID=SL.ID AND SDI.STOKID = SI.STOKID
                                  INNER JOIN STOKLAR S ON SI.STOKID=S.ID AND S.DURUM=1
                                  INNER JOIN DEPOLAR D ON D.ID = SDI.DEPOID
                                  LEFT JOIN STOK_ORT_MALIYET SOM ON SOM.STOKID = S.ID AND SOM.FATBASID = FB.ID AND SOM.FATURAID = F.ID AND SOM.DEPOID = D.ID
             WHERE
                    FB.TUR=119 AND D.DEPOADI = ''Konsinye Çıkış'' AND --SDI.STOKID=2337
                    --AND R.FIRMA LIKE ''%GRANİT%''
                    -- 0=case when ''$Bolge$''=0 then 0 when ''$Bolge$''=R.BOLGE then 0 else 1 end and
                    R.FIRMA like ''$FirmaAdi$%'' --AND
                    --FB.FATURATARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
) AS X 
WHERE
       coalesce(X.URUNNO,'''') LIKE ''%$URUNNO$%''  AND   
       coalesce(X.LOT,'''') LIKE ''%$LOTNO$%'' AND
	   coalesce(X.SERINO,'''') LIKE ''%$SERINO$%'' AND
       X.KALANGUN <= ''$SKTKALANGUN$'' AND
       KALAN>0
ORDER BY 11' WHERE id = 1404;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT ''URT'' AS DURUM , S.URUNNO,SL.LOTNO,SL.SERINO,URT,SKT FROM STOKSERILOT SL INNER JOIN STOKLAR S ON S.ID=SL.STOKID WHERE URT=''1990-01-01''
UNION ALL 
SELECT ''SKT'' AS DURUM , S.URUNNO,SL.LOTNO,SL.SERINO,URT,SKT FROM STOKSERILOT SL INNER JOIN STOKLAR S ON S.ID=SL.STOKID WHERE SKT=''1990-01-01''' WHERE id = 1405;
UPDATE public.dokumler SET sql = '/*PGX*/-- ENVANTER RAPORUNDAKİ KONSİNYE DEPO ADETİ İLE KONSİNYE DEPOSUNDAKİ KALAN ADETİ KARŞILAŞTIRIR. 

SELECT 
       * INTO gt_ENVANTER
FROM (
SELECT 
       KOD AS ENVANTER,
       SUM(KLN) AS TOPLAM
FROM (
SELECT DISTINCT S.KOD,S.STOKADI,K.AD AS KATEGORI,G.ANAHTAR AS MARKA ,
D.DEPOADI,GRN,CKN,ROUND(KLN,2)AS KLN,ORTMALIYET,cast(SONALISFIYAT as double precision) AS SONALISFIYAT,ORTTUTAR =ROUND((ORTMALIYET*KLN),2),ORTSONTUTAR=ROUND((SONALISFIYAT*KLN),2)
FROM(
SELECT URUNID,DSA.GIRISDEPO,GRN,CKN,KLN,ORTMALIYET,
              SONALISFIYAT=ROUND((SELECT TUTAR=BIRIMFIYAT--CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT*(1+(KDV/100.0)) ELSE BIRIMFIYAT END
                                                                                              FROM 
                                                                                                              FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                                                                                              WHERE 
                                                                                                              F.URUNID=DSA.URUNID AND
                                                                                                              F.STOKDURUMDEGIS = 1 AND coalesce(FB.GIRISDEPO,0)<>0 AND F.TUR=1 ORDER BY TARIH DESC  LIMIT 1 ),2)
FROM
                (SELECT ASD.URUNID,ASD.GIRISDEPO,MIKTAR=SUM(CASE WHEN GC=''G'' THEN MIKTAR ELSE -MIKTAR END),
        ORTMALIYET=case when coalesce(MIKTAR,0)<>0 THEN ROUND((ROUND(SUM(TUTAR),2)/SUM(MIKTAR)),2)  ELSE 0 END
                FROM
                 (SELECT 
                        GC=''G'',URUNID,
                        SUM(MIKTAR) AS MIKTAR,
                        FB.GIRISDEPO,
                        TUTAR=SUM(TUTAR)--CASE WHEN FB.KDVDURUM=''Hariç'' THEN TUTAR*(1+(KDV/100.0)) ELSE TUTAR END,
                        --FB.TUR,FB.KDVDURUM,F.KDV
                 FROM 
                      FATBASLIK FB INNER JOIN FATURA F ON FB.ID=F.FATBASID
                               WHERE F.STOKDURUMDEGIS = 1 AND coalesce(FB.GIRISDEPO,0)<>0 AND F.TUR=1
                               GROUP BY URUNID,FB.GIRISDEPO
                               )AS ASD

                GROUP BY ASD.URUNID,ASD.GIRISDEPO,ASD.MIKTAR
                )AS DSA INNER JOIN 
                               (SELECT STOKID,DEPOID,GRN=SUM(GIREN),CKN=SUM(CIKAN),KLN=SUM(KALAN) 
                               FROM STOKDURUM
                
                               GROUP BY STOKID,DEPOID)AS XXX
                
                ON DSA.URUNID=XXX.STOKID     AND XXX.DEPOID=DSA.GIRISDEPO
                
) AS X INNER JOIN STOKLAR S  ON X.URUNID=S.ID AND S.DURUM=1
       INNER JOIN DEPOLAR D  ON D.ID=X.GIRISDEPO
          LEFT JOIN  KATEGORI K ON S.KATEGORI=K.ID
          LEFT JOIN GENINI G ON G.DEGER=S.MARKA AND G.BOLUM=-2701
where
    S.KOD LIKE ''%''
       --S.KOD LIKE ''%''
) AS Y
  WHERE
    coalesce(DEPOADI,'''') LIKE ''Konsinye Çıkış%''
       --   DEPOADI  LIKE ''%'' 
        AND coalesce(KATEGORI,'''') LIKE ''%''
GROUP BY 
       KOD
) AS ENVANTER

--KONSINYE TOPLAM URUNE GORE KALAN LISTESI
SELECT *,FARK = KTOPLAM-TOPLAM 
FROM (
SELECT 
       URUNKOD AS KONSINYE,
       SUM(KALAN) AS KTOPLAM
FROM (
SELECT
       FIRMA,KONSINYETARIHI,KONSINYENO,URUNGRUBU,URUNKOD,URUNNO,URUNAD,
       KALAN,SKT,LOT,SERINO,
       KALANGUN,
          BIRIMMALIYET,
          T.MALIYET
    FROM(
             SELECT
                    R.FIRMA AS FIRMA,
                    FB.FATURATARIH AS KONSINYETARIHI,
                    FATURANO AS KONSINYENO,
                    URUNGRUBU= (SELECT ANAHTAR FROM GENINI G,STOKLAR S WHERE G.BOLUM=''-2704'' AND G.DEGER=S.GRUBU AND S.ID=F.URUNID),
                    URUNKOD = (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID),
                    URUNNO = (SELECT URUNNO FROM STOKLAR WHERE ID = F.URUNID),
                    URUNAD = (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID),
                    SKT = SL.SKT,
                    LOT = SL.LOTNO,
                    SERINO = SL.SERINO,
                    KALANGUN=datediff(day,now(),SL.SKT),
                    SI.KALAN,
                    SOM.BIRIMMALIYET,
                    SI.KALAN*SOM.BIRIMMALIYET AS T.MALIYET
             FROM
                    FATURA F INNER JOIN FATBASLIK FB on F.FATBASID=FB.ID 
                                  LEFT OUTER JOIN STOKIZLEME SI on SI.BASLIKID=F.FATBASID and SI.SATIRID=F.ID
                                  LEFT JOIN REHBER R ON FB.REHBERID=R.ID
                                  INNER JOIN STOKSERILOT SL ON SL.ID=SI.SERILOTID
                                  INNER JOIN STOKDURUMIZLEME SDI ON SDI.SERILOTID=SL.ID AND SDI.STOKID = SI.STOKID
                                  INNER JOIN STOKLAR S ON SI.STOKID=S.ID AND S.DURUM=1
                                  INNER JOIN DEPOLAR D ON D.ID = SDI.DEPOID
                                  LEFT JOIN STOK_ORT_MALIYET SOM ON SOM.STOKID = S.ID AND SOM.FATBASID = FB.ID AND SOM.FATURAID = F.ID AND SOM.DEPOID = D.ID
                                  
             WHERE
                    FB.TUR=119 AND D.DEPOADI = ''Konsinye Çıkış'' AND --SDI.STOKID=2337
                    --AND R.FIRMA LIKE ''%GRANİT%''
                    -- 0=case when ''$Bolge$''=0 then 0 when ''$Bolge$''=R.BOLGE then 0 else 1 end and
                    R.FIRMA like ''%'' --AND
                    --FB.FATURATARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
) AS X 
WHERE
       coalesce(X.URUNNO,'''') LIKE ''%%''  AND   
       coalesce(X.LOT,'''') LIKE ''%%'' AND
       X.KALANGUN <= ''999999'' AND
       KALAN>0 
) AS XXX
GROUP BY
       URUNKOD
) AS KONSINYE INNER JOIN gt_ENVANTER E ON E.ENVANTER = KONSINYE.KONSINYE
WHERE
       KTOPLAM-TOPLAM <> 0
DROP TABLE gt_ENVANTER' WHERE id = 1406;
UPDATE public.dokumler SET sql = '/*PGX*/-- sql query

SELECT SS.*,S.KOD, S.URUNNO, S.STOKADI FROM
(
SELECT SD.STOKID, KALAN1=SUM(SD.KALAN),
IZLEM=coalesce((SELECT SUM(SDI.KALAN) FROM STOKDURUMIZLEME SDI WHERE SD.STOKID = SDI.STOKID),0)
FROM STOKDURUM SD 
GROUP BY STOKID

) AS SS
INNER JOIN STOKLAR S ON S.ID=SS.STOKID
WHERE KALAN1 <> IZLEM AND S.DURUM=1  AND S.IZLEME = 5' WHERE id = 1407;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT * FROM (
	SELECT 
		S.KOD,
		S.URUNNO AS UNO,
		S.STOKADI,
		S.OZELKOD,
		GI.ANAHTAR AS MARKA,
		GG.ANAHTAR AS GRUBU,
		GE.ANAHTAR AS TIPI,
                GN.ANAHTAR AS OZELLIK,
    		CASE S.BILDIRIM WHEN ''2'' THEN ''ÜTS'' ELSE ''YOK''END AS BILDIRIM ,		
		SL.LOTNO AS LNO,
                SL.SERINO AS SNO,
                RB.BILGI AS UIK,
                SL.URT,
		SL.SKT,
		SDI.KALAN AS ADT,
                D.DEPOADI,
		DATEDIFF(DAY,now(),SL.SKT)
	 AS KALANGUN FROM 
		STOKLAR S INNER JOIN STOKDURUMIZLEME SDI ON S.ID = SDI.STOKID
				  LEFT JOIN GENINI GI ON GI.BOLUM = -2701 AND S.MARKA = GI.DEGER
				  LEFT JOIN GENINI GG ON GG.BOLUM = -2704 AND S.GRUBU = GG.DEGER
				  LEFT JOIN GENINI GE ON GE.BOLUM = -2703 AND S.TIPI = GE.DEGER
                                  LEFT JOIN GENINI GN ON GN.BOLUM = -2705 AND S.OZELLIK = GN.DEGER
				  INNER JOIN STOKSERILOT SL ON SL.ID=SDI.SERILOTID AND SL.STOKID = S.ID
                                  INNER JOIN DEPOLAR D ON D.ID = SDI.DEPOID
				--INNER JOIN STOKDURUMIZLEME SDI ON SDI.SERILOTID=SL.ID
                                  LEFT JOIN REHBER R ON R.ID = S.URETICI
                                  LEFT JOIN REHBERBILGI RB ON RB.YER_ID = R.ID AND RB.ETIKET = ''Kurum ÜTS No''
	WHERE
		D.DEPOADI LIKE ''$DEPOADI$%''
		AND SDI.KALAN>0
		AND S.DURUM=1 		
) AS X
WHERE    
	KALANGUN <= ''$SKTKALANGUN$''
        AND coalesce(MARKA,'''') LIKE ''$MARKA$%''
        AND coalesce(GRUBU,'''') LIKE ''$GRUBU$%''
        AND KOD LIKE ''$STOKKOD$%''
        ORDER BY 11' WHERE id = 1408;
UPDATE public.dokumler SET sql = '/*PGX*/





if OBJECT_ID(''tempdb..gt_tmpAlacaklar2'') is not null
	drop table gt_tmpAlacaklar2
if OBJECT_ID(''tempdb..gt_tmpBorclar2'') is not null
	drop table gt_tmpBorclar2
create table gt_tmpAlacaklar2 (
	ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),
	BELGENO varchar(100),ACIKLAMA varchar(500), ALACAK money, KUR varchar(5), KUMULATIFALACAK money)
create table gt_tmpBorclar2 (
	ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),
	BELGENO varchar(100),ACIKLAMA varchar(500), BORC money, KUR varchar(5), KUMULATIFBORC money)

insert gt_tmpAlacaklar2
select REHBERID,
	ISLEMTARIHI=dateadd(millisecond,ISLEMID,TARIH),VADESONU=dateadd(millisecond,ISLEMID,VADE),ISLEMTURU=TURAD,BELGENO=NO,ACIKLAMA,ALACAK,KUR,
	KUMULATIFALACAK=SUM(case when ALACAK>0.0 then ALACAK else 0.0 end) OVER (PARTITION BY REHBERID ORDER BY dateadd(millisecond,ISLEMID,VADE))
from
	(
				Select 
					K.REHBERID,
					ISLEMID=K.ID,
					ISLEMTARIHI AS TARIH,BELGENO as NO, K.TUR,
					TURAD  =	case when K.TUR like ''26__'' then (select ANAHTAR + '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
									 when K.TUR like ''36__'' then (select ANAHTAR + '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
								else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end, 
					K.ACIKLAMA, 
					BORC	= case when EKSTREDEKULLAN=1 AND BORC>0   then K.DOVIZ_TUTARI else K.BORC end,
					ALACAK	= case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end,
					KUR		= case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end,
					VADE=ISLEMTARIHI

				From 
					KASA K 	
				Where 
						--K.REHBERID=@RehberID  and 
						K.ALACAK-K.BORC>0.0 and
						K.ISLEMTARIHI<=now() and 
						((K.TUR in (49))or(K.TUR not between 40 and 79)) and 
						K.TUR<>2 and
						''TL''=case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end
			UNION ALL
				Select F.REHBERID,ISLEMID=F.ID, FATURATARIH as TARIH,FATURANO as NO, F.TUR,
					TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ),
					ACIKLAMA=case
						when F.TIPI=2 --(select distinct TUR from FATBASLIK)
							then ''IADE ''+coalesce(F.ACIKLAMA,'''')
						when 1 in (select 1 from FATURA where FATBASID=F.ID and ID in (select YERID from FATURA X where X.REHBERID=F.REHBERID and YERI in (416,417)))  
							then ''IADESI VAR ''+coalesce(F.ACIKLAMA,'''')
						else coalesce(F.ACIKLAMA,'''') end, 
					BORC=case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end ,
					ALACAK=case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end,
					KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
					VADE=F.FATURATARIH+coalesce(F.VADE,0)
				From 
					FATBASLIK F  inner join 
					REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6 
				Where 
					F.FATURA_TUTARI <> 0.0 and
					case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end > 0.0 and
					--F.REHBERID=@RehberID and
					F.FATURATARIH<=now() and
					''TL''=case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end

			---- Çek
			UNION ALL

				Select CH.REHBERID,ISLEMID=CH.ID,
					CH.TARIH, MAKBUZNO as NO, TUR=case when CH.ISLEM in(130,141) then 23 else 33 end,
					TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ),
					ACIKLAMA=case when CH.ISLEM in (137,141) then ''IADE ''
								when C.ID in (select CH1.CEKSENETLERID from CEKHAREKET CH1 where CH1.TARIH <= now() and CH1.ISLEM in (137,141)) then ''IADESI VAR ''
								else '''' end + ''Serino:''+cast(C.SERINO as varchar)+'' ''+rtrim(coalesce(CH.ACIKLAMA,'''')),
					BORC=Case when CH.ISLEM in(140,131,132,133,134,137) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
					ALACAK=Case when CH.ISLEM in(130,141) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
					KUR=case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end,
					VADE
				From 
					CEKLER C  inner join
					CEKHAREKET CH on C.ID=CH.CEKSENETLERID 
				Where 
					CH.ISLEM in(130,131,132,134,137,140,141) and
					C.TUTAR <> 0.0 and
					--CH.REHBERID=@RehberID and 
					CH.TARIH <= now() and 
					''TL''=case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end

			---- Senet

			UNION ALL

			Select C.REHBERID,ISLEMID=C.ID,
				TARIH, MAKBUZNO as NO,C.TUR, TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ),
				ACIKLAMA=C.ACIKLAMA,
				BORC=Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
				ALACAK=Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
				KUR=case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end,
				VADE
			From 
				SENETLER C
			Where
					--C.REHBERID=@RehberID and 
					C.TUTAR <> 0.0 and
					Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0.0 end > 0.0 and
					C.TARIH <= now() and
					''TL''=case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end

	) as xxx
where ALACAK>0.0
 order by dateadd(millisecond,ISLEMID,VADE)

--SELECT * FROM gt_tmpAlacaklar2 WHERE REHBERID = 1276

insert gt_tmpBorclar2
select REHBERID,
	ISLEMTARIHI=dateadd(millisecond,ISLEMID,TARIH),VADESONU=dateadd(millisecond,ISLEMID,VADE),ISLEMTURU=TURAD,BELGENO=NO,ACIKLAMA,BORC,KUR,
	KUMULATIFBORC=SUM(case when BORC>0.0 then BORC else 0.0 end) OVER (PARTITION BY REHBERID ORDER BY dateadd(millisecond,ISLEMID,VADE)) 
from
	(
			Select K.REHBERID,ISLEMID=K.ID,
				ISLEMTARIHI AS TARIH,BELGENO as NO, K.TUR,
				TURAD  =	case when K.TUR like ''26__'' then (select ANAHTAR + '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
								 when K.TUR like ''36__'' then (select ANAHTAR + '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
							else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end, 
				K.ACIKLAMA, 
				BORC	= case when EKSTREDEKULLAN=1 AND BORC>0   then K.DOVIZ_TUTARI else K.BORC end,
				ALACAK	= case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end,
				KUR		= case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end,
				VADE=ISLEMTARIHI

				From --select * from REHBER where ID=4118
					KASA K 		
				Where 
						--K.REHBERID=@RehberID  and 
						K.BORC-K.ALACAK>0.0 and
						K.ISLEMTARIHI<=now() and 
						((K.TUR in (49))or(K.TUR not between 40 and 79)) and 
						K.TUR<>2 and
						''TL''=case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end
			UNION ALL
				Select F.REHBERID,ISLEMID=F.ID, FATURATARIH as TARIH,FATURANO as NO, F.TUR,
					TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ),
					ACIKLAMA=case
						when F.TIPI=2 
							then ''IADE ''+coalesce(F.ACIKLAMA,'''')
						when 1 in (select 1 from FATURA where FATBASID=F.ID and ID in (select YERID from FATURA X where X.REHBERID=F.REHBERID and YERI in (416,417)))  
							then ''IADESI VAR ''+coalesce(F.ACIKLAMA,'''')
						else coalesce(F.ACIKLAMA,'''') end, 
					BORC=case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end ,
					ALACAK=case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end,
					KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
					VADE=F.FATURATARIH+coalesce(F.VADE,0)
				From 
					FATBASLIK F  inner join 
					REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6 
				Where 
					F.FATURA_TUTARI <> 0.0 and
					case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end > 0.0 and 
					--F.REHBERID=@RehberID and 
					F.FATURATARIH<=now() and
					''TL''=case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end

			---- Çek
			UNION ALL

				Select CH.REHBERID,ISLEMID=CH.ID,
					CH.TARIH, MAKBUZNO as NO, TUR=case when CH.ISLEM in(130,141) then 23 else 33 end,
					TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ),
					ACIKLAMA=case when CH.ISLEM in (137,141) then ''IADE ''
								when C.ID in (select CH1.CEKSENETLERID from CEKHAREKET CH1 where CH1.TARIH <= now() and CH1.ISLEM in (137,141)) then ''IADESI VAR ''
								else '''' end + ''Serino:''+cast(C.SERINO as varchar)+'' ''+rtrim(coalesce(CH.ACIKLAMA,'''')),
					BORC=Case when CH.ISLEM in(140,131,132,133,134,137) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
					ALACAK=Case when CH.ISLEM in(130,141) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
					KUR=case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end,
					VADE
				From 
					CEKLER C  inner join
					CEKHAREKET CH on C.ID=CH.CEKSENETLERID
				Where 
					CH.ISLEM in(130,131,132,134,137,140,141) and
					C.TUTAR <> 0.0 and
					Case when CH.ISLEM in(140,131,132,133,134,137) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end > 0.0 and
					--CH.REHBERID=@RehberID and 
					CH.TARIH <= now() and 
					''TL'' = case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end

			---- Senet

			UNION ALL

			Select C.REHBERID,ISLEMID=C.ID,
				TARIH, MAKBUZNO as NO,C.TUR, TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ),
				ACIKLAMA=rtrim(C.ACIKLAMA),
				BORC=Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
				ALACAK=Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
				KUR=case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end,
				VADE
			From 
				SENETLER C 
			Where
					--C.REHBERID=@RehberID and 
					C.TUTAR <> 0.0 and
					Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0.0 end > 0.0 and
					C.TARIH <= now()  and 
					''TL'' = case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end

	) as xxx
where BORC>0.0
order by dateadd(millisecond,ISLEMID,VADE)

--SELECT * FROM gt_tmpBorclar2 WHERE REHBERID = 1276

--SELECT * FROM gt_tmpAlacaklar2
insert into gt_tmpAlacaklar2(REHBERID, ISLEMTARIHI, VADESONU ,ISLEMTURU, BELGENO, ACIKLAMA, ALACAK, KUR, KUMULATIFALACAK)
SELECT 
	R.ID,
	now(),
	now(),
	''Kalan Borç'',
	''-'',
	''Kalan Borç'',
	coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0) - coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0),
	''TL'',
	coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0)
FROM 
	REHBER R
WHERE 
	--SINIF <> 1
     coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0) > coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0)

insert into gt_tmpBorclar2(REHBERID, ISLEMTARIHI, VADESONU ,ISLEMTURU, BELGENO, ACIKLAMA, BORC, KUR, KUMULATIFBORC)
SELECT 
	R.ID,
	now(),
	now(),
	''Kalan Alacak'',
	''-'',
	''Kalan Alacak'',
	coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0) - coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0),
	''TL'',
	coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0)
FROM 
	REHBER R
WHERE 
	--SINIF <> 1
	 coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0) < coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0)



select
	R.KOD,R.FIRMA,
	ISLEMTARIHI,VADESONU,ODEMETARIHI,
	GECIKENGUNSAYISI=cast((ODEMETARIHI-VADESONU) as integer), 
	ISLEMTURU,ISLEMACIKLAMA,ODEMETURU,ODEMEACIKLAMA,
	BORCTUTARI,ODEMETUTARI,ODENENTUTAR,
	GECIKENTUTAR=case 
		when (ODEMETURU=''Kalan Borç(-)'' and cast((ODEMETARIHI-VADESONU) as integer)>=0) then ODENENTUTAR 
		when (ISLEMTURU=''Kalan Alacak(-)'' and cast((ODEMETARIHI-VADESONU) as integer)>=0)  then ODENENTUTAR else 0.0 end,
	AGIRLIKLIGECIKME=ODENENTUTAR*cast((ODEMETARIHI-VADESONU) as integer)
from
( 
select A.REHBERID,
	B.ISLEMTARIHI,
	B.VADESONU,
	ISLEMTURU=B.ISLEMTURU+''(''+B.BELGENO+'')'',
	ISLEMACIKLAMA=B.ACIKLAMA,
	BORCTUTARI=B.BORC,
	ODEMETARIHI=A.ISLEMTARIHI,
	ODEMETURU=A.ISLEMTURU+''(''+A.BELGENO+'')'',
	ODEMEACIKLAMA=A.ACIKLAMA,
	ODEMETUTARI=A.ALACAK,
	ODENENTUTAR=(case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end) - coalesce(lag(case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end) over (PARTITION BY A.REHBERID order by case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end),0.0),
	KUR=''TL''


from 
	gt_tmpAlacaklar2 as A join
	gt_tmpBorclar2 as B on
		B.KUMULATIFBORC-B.BORC<A.KUMULATIFALACAK and
		A.KUMULATIFALACAK-A.ALACAK<B.KUMULATIFBORC AND A.REHBERID = B.REHBERID

)as x inner join REHBER R on x.REHBERID=R.ID
	  inner join REHBER_BAKIYE RB ON RB.REHBERID = R.ID
WHERE
	RB.TUTAR > = 1.0
        AND ODEMETURU = ''Kalan Borç(-)''
        AND R.FIRMA <> ''-''
ORDER BY
      R.FIRMA
' WHERE id = 1409;
UPDATE public.dokumler SET sql = '/*PGX*/
''$Bitis$ 23:58''--''2016-12-31 23:59'' DATETIME 




--Mizan Varlıklar
SELECT HESAPKODU,HESAPADI,
       BORC=ROUND(SUM(cast(BORC as double precision)),2),
       ALACAK=ROUND(SUM(cast(ALACAK as double precision)),2),
       BAKIYE=ROUND(SUM(cast(KALAN as double precision)),2),
       KUR,
       TLBORC=ROUND(SUM(cast(TLBORC as double precision)),2),
       TLALACAK=ROUND(SUM(cast(TLALACAK as double precision)),2),
       TLBAKIYE=ROUND(SUM(cast(TLKALAN as double precision)),2)
FROM(
-- pos 
SELECT  HESAPKODU,HESAPADI,BORC=SUM(BORC),ALACAK=SUM(ALACAK),KALAN=SUM(BORC)-SUM(ALACAK),KUR,TLBORC=SUM(BORC),TLALACAK=SUM(ALACAK),TLKALAN=SUM(BORC)-SUM(ALACAK),TLKUR=''TL''
FROM(
                SELECT 
                               ID,
                               KODU as HESAPKODU,
                               ADI as HESAPADI, 
                               BORC= (SELECT coalesce(SUM(B),0.0) FROM (
                                                                                                              select  B=  case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND ALACAK>0.0 then K2.DOVIZ_TUTARI else K2.ALACAK end
                                                                                                              from KASA K2  
                                                                                                              where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''P'' AND TUR <> 2) AS X ),
                               ALACAK=(SELECT coalesce(SUM(A),0.0) FROM (
                                                                                                              select A=           case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND BORC>0.0 then K2.DOVIZ_TUTARI else K2.BORC end
                                                                                                              from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''P'' --AND TUR <> 2
                                                               ) AS X ),
                               KUR=''TL''              
                FROM 
                               POS k1 
) AS X
WHERE ((BORC<>0.0) or (ALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
union all
--KASA
SELECT HESAPKODU,HESAPADI,SUM(BORC) AS BORC,SUM(ALACAK) AS ALACAK,KALAN=SUM(BORC)-SUM(ALACAK),KUR,TLBORC=SUM(TLBORC),TLALACAK=SUM(TLALACAK),TLKALAN=SUM(TLBORC)-SUM(TLALACAK),TLKUR=''TL''
FROM(  
                SELECT 
                               ID,
                               KASAKODU as HESAPKODU,
                               KASAADI as HESAPADI, 
                               BORC= (SELECT coalesce(SUM(B),0) FROM (select  B=case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND K2.ALACAK>0 then K2.DOVIZ_TUTARI when K2.TUR=88 then K2.DOVIZ_TUTARI else K2.ALACAK end from KASA K2   where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
                                               ) AS X ),
                                                               ALACAK=(SELECT coalesce(SUM(A),0) FROM (select  A= case when DOVIZ_KURU=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-10135) AND K2.BORC>0 then K2.DOVIZ_TUTARI 
                               when K2.TUR=98 then K2.DOVIZ_TUTARI  else K2.BORC end from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
                               ) AS X ),
                               TLBORC= (SELECT coalesce(SUM(B),0) FROM (select  B=case when K2.ALACAK>0.0 then K2.DOVIZ_TUTARI when K2.TUR=88 then K2.DOVIZ_TUTARI else 0.0 end  from KASA K2  
                               where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
                               ) AS X ),
                               TLALACAK=(SELECT coalesce(SUM(A),0) FROM (select  A= case when K2.BORC>0.0 then K2.DOVIZ_TUTARI when K2.TUR=98 then K2.DOVIZ_TUTARI else 0.0 end from KASA K2   where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 AND ((K2.HESAPTURU =''K'') or (K2.HESAPTURU=''B'' AND KASA IN (195,196)) ) --and K2.TUR <> 2
                               ) AS X ),
                               KUR=''TL''  
                FROM KASALAR K1  
) AS X
WHERE 
                ((BORC<>0.0) or (ALACAK<>0.0) or (TLBORC<>0.0) or (TLALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
--BANKA 
union all 
SELECT HESAPKODU,HESAPADI,BORC=SUM(BORC),ALACAK=SUM(ALACAK),KALAN=SUM(BORC)-SUM(ALACAK),KUR,TLBORC=SUM(TLBORC),TLALACAK=SUM(TLALACAK),TLKALAN=SUM(TLBORC)-SUM(TLALACAK),TLKUR=''TL''
FROM(
                SELECT
                               ID,
                               HESAPKODU,
                               HESAPADI, 
                               BORC   =  (SELECT coalesce(SUM(B),0) FROM (select B= K2.ALACAK from KASA K2  where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2
                ) AS X ),
                               ALACAK = (SELECT coalesce(SUM(A),0) FROM (select  A= K2.BORC from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2
                 ) AS X ), 

                               TLBORC   =  (SELECT coalesce(SUM(B),0) FROM (select  B= case when K2.TUR=88 then K2.DOVIZ_TUTARI when ALACAK>0.0 then (case when K2.DOVIZ_KURU=''TL'' then K2.DOVIZ_TUTARI else K2.ALACAK end)  else 0.0 end from KASA K2  where  K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2 
                ) AS X ),
                               TLALACAK = (SELECT coalesce(SUM(A),0) FROM (select  A= case when K2.TUR=98 then K2.DOVIZ_TUTARI when BORC>0.0 then (case when K2.DOVIZ_KURU=''TL'' then K2.DOVIZ_TUTARI else K2.ALACAK end) else 0.0 end  from KASA K2  where K1.ID=K2.HESAPID AND ISLEMTARIHI between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59'' and K2.TUR not between 60 and 79 and K2.HESAPTURU=''B'' --and K2.TUR <> 2
                ) AS X ),
                               K1.KUR
                FROM BANKAHESAPLAR K1   
) AS X
WHERE ((BORC<>0.0) or (ALACAK<>0.0) or (TLBORC<>0.0) or (TLALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
--ÇEKLER
union all 
select HESAPKODU,HESAPADI,BORC=SUM(BORC),ALACAK=SUM(ALACAK),KALAN=SUM(BAKIYE),KUR,TLBORC=SUM(TLBORC),TLALACAK=SUM(TLALACAK),TLKALAN=SUM(TLBORC)-SUM(TLALACAK),TLKUR=''TL''
from (
                select 
                               HESAPKODU,HESAPADI,
                               BORC=case when SUM(BAKIYE)>0.0 then SUM(BAKIYE) else 0.0 end,
                               ALACAK=case when SUM(BAKIYE)>0.0 then 0.0 else -SUM(BAKIYE)end,
                               BAKIYE=SUM(BAKIYE),
                               KUR,
                               TLBORC=case when SUM(TLBAKIYE)>0.0 then SUM(TLBAKIYE) else 0.0 end,
                               TLALACAK=case when SUM(TLBAKIYE)>0.0 then 0.0 else -SUM(TLBAKIYE)end,
                               TLBAKIYE=SUM(TLBAKIYE)
                from (
                --devir borc
                               select 
                               H.HESAPKODU,H.HESAPADI,BORC=C.TUTAR,ALACAK=0.0,BAKIYE=C.TUTAR,KUR=C.KUR,TLBORC=CH.DOVIZ_TUTARI,TLALACAK=0.0,TLBAKIYE=CH.DOVIZ_TUTARI
        from
                                               CEKLER C inner join 
                                               CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                                               HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM AND H.VARSAYILAN = C.CEKSENET
                               where
                                               CH.TARIH < ''$Baslangic$ 00:00''--''2000-01-01 00:00''

                               union all
                               --devir alacak
                               select 
                                               H.HESAPKODU,H.HESAPADI,BORC=0.0,ALACAK=C.TUTAR,BAKIYE=-C.TUTAR,KUR=C.KUR,TLBORC=0.0,TLALACAK=CH.DOVIZ_TUTARI,TLBAKIYE=CH.DOVIZ_TUTARI
                               from 
                                               CEKLER C inner join 
                                               CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join
                                               CEKHAREKET CHD on CH.GERIDONUSID=CHD.ID inner join 
                                               HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CHD.ISLEM AND H.VARSAYILAN = C.CEKSENET
                               where 
                                               CH.TARIH < ''$Baslangic$ 00:00''--''2000-01-01 00:00'' 
                )as XX
                group by 
                               HESAPKODU,HESAPADI,KUR

                union all
                --çekin ilgili tarihteki hareketi /hesabın borcuna
                select 
                H.HESAPKODU,H.HESAPADI,BORC=C.TUTAR,ALACAK=0.0,BAKIYE=C.TUTAR,KUR=C.KUR,TLBORC=CH.DOVIZ_TUTARI,TLALACAK=0.0,TLBAKIYE=CH.DOVIZ_TUTARI
                from 

                    CEKLER C inner join 
                    CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join
                    HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CH.ISLEM AND H.VARSAYILAN = C.CEKSENET
             where CH.TARIH between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
             union all
             --çekin ilgili tarihteki hareketinin karşı hesabı /hesabın alacağına
             select H.HESAPKODU,H.HESAPADI,BORC=0.0,ALACAK=C.TUTAR,BAKIYE=-C.TUTAR,KUR=C.KUR,TLBORC=0.0,TLALACAK=CH.DOVIZ_TUTARI,TLBAKIYE=CH.DOVIZ_TUTARI
             from 
                    CEKLER C inner join 
                    CEKHAREKET CH on C.ID=CH.CEKSENETLERID inner join 
                    CEKHAREKET CHD on CH.GERIDONUSID=CHD.ID inner join 
                    HESAPPLANI H on H.KUR=C.KUR and H.MUHASEBE=CHD.ISLEM AND H.VARSAYILAN = C.CEKSENET
             where CH.TARIH between ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
)as XX
WHERE ((BORC<>0.0) or (ALACAK<>0.0) or (TLBORC<>0.0) or (TLALACAK<>0.0))
GROUP BY HESAPKODU,HESAPADI,KUR
) AS X
GROUP BY HESAPKODU,HESAPADI,KUR
--Mizan Borç Alacak
UNION ALL
SELECT
       XXX.KOD,
                   XXX.FIRMA,
       round(SUM(coalesce(BORC,0)),2) as BORC,
       round(SUM(coalesce(ALACAK,0)),2) as ALACAK,
       round(SUM(coalesce(BAKIYE,0)),2) as BAKIYE,
       KUR,
       TLBORC=ROUND(SUM(cast(TLBORC as double precision)),2),
       TLALACAK=ROUND(SUM(cast(TLALACAK as double precision)),2),
       TLBAKIYE=ROUND(SUM(cast(TLBAKIYE as double precision)),2)
FROM (
select  DISTINCT R.SUBEID,R.KOD ,R.FIRMA,SINIFADI=GSnf.ANAHTAR,GRUPADI=GGrp.ANAHTAR,cast(TOPLAM_BORC as double precision) AS BORC ,cast(TOPLAM_ALACAK as double precision) AS ALACAK,KUR ,BAKIYE=cast(TOPLAM_BORC as double precision)-cast(TOPLAM_ALACAK as double precision),TLBORC,TLALACAK,TLBAKIYE=(TLBORC-TLALACAK)

FROM(
    select
                REHBERID,TOPLAM_BORC=SUM(coalesce(BORC,0)),TOPLAM_ALACAK=SUM(coalesce(ALACAK,0)),KUR=coalesce(KUR,''TL''),TLBORC=SUM(coalesce(TLBORC,0.0)),TLALACAK=SUM(coalesce(TLALACAK,0.0))
                from (
                               SELECT
                                               REHBERID,
                                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
                                               0.0 AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR,
                                               TLBORC=SUM(cast(F.FATURA_TUTARI as double precision)),
                                               TLALACAK=0.0
                                               FROM FATBASLIK F
                                               WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17))
                                               AND FATURATARIH BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

                                               UNION ALL

                                               SELECT REHBERID,
                                               0 AS BORC,
                                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR,
                                               TLBORC=0.0,
                                               TLALACAK=SUM(cast(F.FATURA_TUTARI as double precision))
                                               FROM FATBASLIK F
                                               WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13))
                                               AND FATURATARIH BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

                                               UNION ALL

                                               SELECT REHBERID,
                                               SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
                                               SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR,
                                               TLBORC=sum(case when (K.TUR=88) then K.DOVIZ_TUTARI
                                                                                           when (K.KUR=''TL'' and K.BORC>0.0) then K.BORC
                                                                                               when (K.DOVIZ_KURU=''TL'' and K.BORC>0.0) then K.DOVIZ_TUTARI
                                                                                               else 0.0 end),
                                               TLALACAK=sum(case when (K.TUR=98) then K.DOVIZ_TUTARI
                                                                                           when (K.KUR=''TL'' and K.ALACAK>0.0) then K.ALACAK
                                                                                           when (K.DOVIZ_KURU=''TL'' and K.ALACAK>0.0) then K.DOVIZ_TUTARI
                                                                                           else 0.0 end)
                                               FROM KASA K
                                               WHERE TUR not between 60 and 79  AND
                                               ISLEMTARIHI  BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

                                               UNION ALL
                                               SELECT CH.REHBERID,
                                               BORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                                               ALACAK=SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                                               CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR,
                                               TLBORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then C.DOVIZ_TUTARI else 0.0 end),
                                               TLALACAK=SUM(Case when CH.ISLEM in(130,141) then C.DOVIZ_TUTARI else 0.0 end)
                                               FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                                               WHERE CH.ISLEM in(130,131,132,134,137,140,141) and
                                               CH.TARIH  BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end

                                               UNION ALL

                                               SELECT REHBERID,
                                               0 AS BORC,
                                               SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR,
                                               TLBORC=0.0,
                                               TLALACAK=SUM(S.DOVIZ_TUTARI)
                                               FROM SENETLER S
                                               WHERE TUR = 24
                                               AND TARIH  BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END

                                               UNION ALL

                                               SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
                                               BORC,0 AS ALACAK,
                                               CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR,
                                               TLBORC=SUM(S.DOVIZ_TUTARI),
                                               TLALACAK=0.0
                                               FROM SENETLER S
                                               WHERE TUR = 34
                                               AND TARIH  BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

           ) as asd
           group by REHBERID,KUR) AS DSA
                               INNER JOIN REHBER R ON            DSA.REHBERID=R.ID
                               LEFT OUTER JOIN             REHBERPERSONEL P on R.ID = P.REHBERID
                               left outer join REHBER R2 on R2.ID=R.TEMSILCI
                               left outer join (Select R1.ID,RB.BILGI from REHBER R1
                               left outer join REHBERILETISIM RI on R1.ID=RI.REHBERID
                               Left outer join REHBERBILGI RB on RB.YER_ID=RI.ID
                               left outer join REHBERAYAR RA on RA.SIRA=RB.SIRA Where RI.VARSAYILAN=1 and RB.YERI=1 and RA.VARSAYILAN=8) X on X.ID=R.ID
                               left outer join GENINI GSnf on R.SINIF=GSnf.DEGER and GSnf.BOLUM=-2203 and GSnf.DIL=-1 --2203  sınıf
                               left outer join GENINI GGrp on R.GRUP=GGrp.DEGER and GGrp.BOLUM=-2202 and GGrp.DIL=-1  --2202  grup

where R.GRUP<>335 and R.ID > 0
and R.DURUM=1  and  coalesce(R.ID,'''')<>''''
   ) AS XXX
GROUP BY
                KOD,FIRMA,KUR
--Mizan Masraf Gelir Gider
UNION ALL
SELECT
                MASRAFKOD,MASRAFAD,
                ROUND(coalesce(SUM(BORC),0),2) AS BORC,
                ROUND(coalesce(SUM(ALACAK),0),2) AS ALACAK,
                BAKIYE=ROUND(coalesce(SUM(BORC),0),2)-ROUND(coalesce(SUM(ALACAK),0),2),
                KUR,
                TLBORC=ROUND(coalesce(SUM(BORC),0),2),
                TLALACAK=ROUND(coalesce(SUM(ALACAK),0),2),
                TLBAKIYE=ROUND(coalesce(SUM(BORC),0),2)-ROUND(coalesce(SUM(ALACAK),0),2)
FROM (
                SELECT * FROM (
                SELECT
                               FB.SUBEID,
                               F.ID,                         
                               FB.TUR,
                               IT.AD,
                               FB.FATURANO AS BELGENO,                  
                               FB.FATURATARIH AS ISLEMTARIHI,
                               MG.KOD AS MASRAFKOD,
                               MG.AD AS MASRAFAD,
                               R.KOD AS CARIKOD,
                               R.FIRMA AS CARIAD,
                               KODU= CASE WHEN F.TUR = 1 THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END,
                               ADI = CASE WHEN F.TUR = 1 THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END,
                               BORC=CASE WHEN FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR IN (''€'',''$'') THEN F.DOVIZ_TUTARI /(1+(F.KDV/100.0))
                                                                 WHEN FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR IN (''€'',''$'') THEN F.DOVIZ_TUTARI /(1+(F.KDV/100.0)) + coalesce((-1*FB.EKVERGI),0)
                                                                 WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) 
                                                                 WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (11,12) AND FB.TIPI<>4 and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)
                                                                 WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) + coalesce((-1*FB.EKVERGI),0)
                                                                 WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (11,12) AND FB.TIPI=4  and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)  + coalesce((-1*FB.EKVERGI),0)
                                                               END,
                               ALACAK=CASE WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (15,16) and FB.KUR IN (''€'',''$'') THEN (F.DOVIZ_TUTARI)/(1+(F.KDV/100.0)) 
                                                                               WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (15,16) and FB.KUR IN (''€'',''$'') THEN (cast(F.DOVIZ_TUTARI as double precision))

                                                                               WHEN FB.KDVDURUM=''Dahil'' AND FB.TUR IN (15,16) and FB.KUR NOT IN (''€'',''$'') THEN (F.TUTAR)/(1+(F.KDV/100.0)) 
                                                                               WHEN FB.KDVDURUM=''Hariç'' AND FB.TUR IN (15,16) and FB.KUR NOT IN (''€'',''$'') THEN (cast(F.TUTAR as double precision))
                               END,
                               F.KUR
                               FROM FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
                                                                                                                                                                                                                            LEFT JOIN MASRAFGELIR MG ON F.TUR=0 AND F.URUNID=MG.ID
                                                                                                                                                                                                                            LEFT OUTER JOIN REHBER R ON F.REHBERID=R.ID
                                                                                                                                                                                                                            LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                                                                                              LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
                               WHERE 
                                                FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               AND FB.TUR IN (11,12,15,16,1)
                ) AS X
                WHERE coalesce(MASRAFKOD,'''')<>''''
                UNION ALL
                SELECT * FROM (
                               SELECT
                               FB.SUBEID,
                               F.ID,
                               FB.TUR,
                               IT.AD,
                               FB.FATURANO AS BELGENO,                  
                               FB.FATURATARIH AS ISLEMTARIHI,
                               MASRAFKOD=(SELECT KOD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)),
                               MASRAFAD=(SELECT AD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)),
                               R.KOD AS CARIKOD,
                               R.FIRMA AS CARIAD,
                               KODU= (SELECT KOD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)),
                               ADI = (SELECT AD FROM MASRAFGELIR MG WHERE KOD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM=-24045)),
                               BORC=0,
                               ALACAK=-1*EKVERGI,
                               KUR=''TL''
                               FROM FATURA F INNER JOIN FATBASLIK FB ON F.FATBASID=FB.ID
                                                                                                                                                                                                                            LEFT JOIN MASRAFGELIR MG ON F.TUR=0 AND F.URUNID=MG.ID
                                                                                                                                                                                                                            LEFT OUTER JOIN REHBER R ON F.REHBERID=R.ID
                                                                                                                                                                                                                            LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                                                                                              LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
                               WHERE 
                                                FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               AND FB.TUR IN (11)
                                               AND FB.TIPI = 4
                ) AS X
                WHERE coalesce(MASRAFKOD,'''')<>''''
                UNION ALL
                SELECT * FROM (
                               SELECT
                               FB.SUBEID,
                               FB.ID,
                               FB.TUR,  
                               IT.AD,  
                               FB.FATURANO AS BELGENO,            
                               FB.FATURATARIH AS ISLEMTARIHI,
                               MG.KOD AS MASRAFKOD,
                               MG.AD AS MASRAFAD,
                               R.KOD AS CARIKOD,
                               R.FIRMA AS CARIAD,
                               KODU= MG.KOD,
                               ADI = MG.AD,
                               BORC   = case when FB.TUR=13 and FB.KUR IN (''€'',''$'') then FB.DOVIZ_TUTARI
                                                                                 when FB.TUR=13 and FB.KUR NOT IN (''€'',''$'') then FB.FATURA_TUTARI END ,
                               ALACAK = case when FB.TUR=17 and FB.KUR IN (''€'',''$'') then FB.DOVIZ_TUTARI
                                                                                 when FB.TUR=17 and FB.KUR NOT IN (''€'',''$'') then FB.FATURA_TUTARI END,
                               KUR=''TL''

                               FROM FATBASLIK FB 
                                                                                                                                                                                                                             LEFT JOIN MASRAFGELIR MG ON FB.MASRAFID=MG.ID AND coalesce(FB.DURUM,0)<>6
                                                                                                                                                                                                                            LEFT OUTER JOIN REHBER R ON FB.REHBERID=R.ID
                                                                                                                                                                                                                            LEFT OUTER JOIN KULLANICI KL ON R.ID=KL.REHBERID
                                                                                              LEFT JOIN ISLEMTURLERI IT ON FB.TUR=IT.TUR AND IT.TIP IN (0,1)
                               WHERE 
                                                FB.FATURATARIH BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''
                                               and FB.TUR IN (13,17,1)
                ) AS X
                WHERE coalesce(MASRAFKOD,'''')<>''''
                UNION ALL
                SELECT * FROM (
                               Select 
                               K.SUBEID, 
                               K.ID,
                               K.TUR,
                               IT.AD,
                               K.BELGENO,
                               ISLEMTARIHI, 
                               MASRAFKOD=M.KOD, MASRAFAD=M.AD,
                               CARIKOD = R.KOD, 
                               CARIAD  = R.FIRMA, 
                               KODU    = M.KOD,
                               ADI     = M.AD,
                               BORC    = CASE  when K.TUR=1 and K.KUR <> ''TL'' and ALACAK>0.0 then K.DOVIZ_TUTARI
                                                                                              when K.TUR=1 and K.KUR = ''TL'' and ALACAK>0.0 then K.ALACAK
                                                                                              WHEN K.TUR<>1 and K.KUR <> ''TL'' AND BORC>0 THEN K.DOVIZ_TUTARI 
                                                                                              WHEN K.TUR<>1 and K.KUR = ''TL'' AND BORC>0 THEN K.BORC 
                                                                                              END, 
                                ALACAK  = CASE when K.TUR=1 and K.KUR <> ''TL'' and BORC>0.0 then K.DOVIZ_TUTARI
                                                                                              when K.TUR=1 and K.KUR = ''TL'' and BORC>0.0 then K.BORC
                                                                                              WHEN K.TUR<>1 and K.KUR <> ''TL'' AND ALACAK>0 THEN K.DOVIZ_TUTARI 
                                                                                              WHEN K.TUR<>1 and K.KUR = ''TL'' AND ALACAK>0 THEN K.ALACAK 
                                                                                              END,  

                               KUR     = ''TL''
                               From KASA K 
                                                                                                                                                 left outer join REHBER R on K.REHBERID=R.ID left outer join KASALAR KS on KS.ID= K.HESAPID  
                                                                                                                                                 left outer join MASRAFGELIR M on M.ID=K.MASRAFID
                                                                                                                                                 LEFT JOIN ISLEMTURLERI IT ON K.TUR=IT.TUR AND IT.TIP IN (0,1)
                               Where 
                                               K.REHBERID=0 and 
                                               K.ISLEMTARIHI BETWEEN ''$Baslangic$ 00:00''--''2000-01-01 00:00'' and ''$Bitis$ 23:58''--''2016-12-31 23:59''  and
                                               K.TUR IN (21,22,23,31,32,33,35,44,58,1) 
                ) AS XYZ
                WHERE coalesce(MASRAFKOD,'''')<>''''       
 ) AS X 
GROUP BY MASRAFKOD,MASRAFAD,KUR
' WHERE id = 1410;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
                STOKID,
                KOD,
                URUNNO,
                STOKADI,
                DEPOADI,
                SKT,
                URT,
                OZELKOD,
                LOTNO,
                SERINO,
                 SUM(GIREN) AS GIREN ,
                 SUM(CIKAN) AS CIKAN ,
                 SUM(GIREN) + SUM(CIKAN)
 AS KALAN FROM(
                SELECT 
                               SI.STOKID,
                               S.KOD,
                               S.URUNNO,
                               S.STOKADI,
                               S.OZELKOD,
                               D.DEPOADI,
                               SL.SKT,
                               SL.URT,
                               SL.LOTNO,
                               SL.SERINO,
                               CASE WHEN SD.ADET > 0 THEN SUM(SD.ADET) ELSE 0 END AS GIREN,
                               CASE WHEN SD.ADET < 0 THEN SUM(SD.ADET) ELSE 0 END AS CIKAN                
                FROM 
                               STOKIZLEME SI INNER JOIN STOKIZLEMEDEPO SD ON SD.IZLEMID = SI.ID
                                                                                 INNER JOIN STOKSERILOT SL ON SL.ID = SI.SERILOTID
                                                                                 INNER JOIN STOKLAR S ON S.ID = SI.STOKID
                                                                                 INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID

                GROUP BY
                               SI.STOKID,
                               S.KOD,
                               S.URUNNO,
                               S.STOKADI,
                               S.OZELKOD,
                               D.DEPOADI,
                               SL.SKT,
                               SL.URT,
                               SL.LOTNO,
                               SL.SERINO,
                               SD.ADET
) AS X
WHERE
     KOD LIKE ''$StokKod$%''
     AND DEPOADI LIKE ''%$DepoAdi$%''
GROUP BY
                STOKID,
                KOD,
                URUNNO,
                STOKADI,
                OZELKOD,
                DEPOADI,
                SKT,
                URT,
                LOTNO,
                SERINO
HAVING
      SUM(GIREN) + SUM(CIKAN) <> 0
ORDER BY KOD' WHERE id = 1411;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT FB.TUR, FB.FATURATARIH, RR.FIRMA,FB.FATURANO, S.KOD, F.ADET , FB.ID AS FATBASID, F.ID AS FATURAID, R.FIRMA, F.EKLEMETARIHI
FROM FATURA F
INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
INNER JOIN STOKLAR S ON S.ID = F.URUNID
INNER JOIN REHBER R ON  R.ID = F.EKLEYEN
INNER JOIN REHBER RR ON RR.ID = FB.REHBERID
WHERE FB.FATURATARIH >= ''2020-01-01 00:00'' AND 
F.IZLEME <> 0 AND FB.TUR <> 2 AND FB.TIPI NOT IN (2,3) AND FB.DURUM <> 6 AND F.TUR = 1
AND NOT EXISTS (
  SELECT *
  FROM STOKIZLEME SI
  WHERE F.ID = SI.SATIRID AND F.FATBASID = SI.BASLIKID
)' WHERE id = 1412;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
        S.KOD,D.DEPOADI,SUM(SDI.KALAN) AS SDI_KALAN, SD.KALAN,  0 AS KONSINYE_KALAN ,  ROUND(SUM(SDI.KALAN) - SD.KALAN,2)
 AS FARK FROM 
        STOKLAR S 
                INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
                INNER JOIN STOKDURUM SD ON SD.STOKID = S.ID AND SD.DEPOID = SDI.DEPOID
                INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
WHERE
        D.DEPOADI <> ''Konsinye Çıkış''
GROUP BY 
        S.KOD,D.DEPOADI,SD.KALAN
HAVING
        CAST(SUM(SDI.KALAN) AS decimal(18,4)) <>  CAST(SD.KALAN AS decimal(18,4))
UNION ALL
SELECT 
        S.KOD,D.DEPOADI,SUM(SDI.KALAN) AS SDI_KALAN, SD.KALAN,  (SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119) AS KONSINYE_KALAN ,  ROUND(SUM(SDI.KALAN) - (SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119),2)
 AS FARK FROM 
        STOKLAR S 
                INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
                INNER JOIN STOKDURUM SD ON SD.STOKID = S.ID AND SD.DEPOID = SDI.DEPOID
                INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
WHERE
        D.DEPOADI = ''Konsinye Çıkış''
GROUP BY 
        S.KOD,D.DEPOADI,SD.KALAN,S.ID
HAVING
        (CAST(SUM(SDI.KALAN) AS decimal(18,4)) <>  CAST(SD.KALAN AS decimal(18,4))
        OR CAST(SUM(SDI.KALAN) AS decimal(18,4)) <> CAST((SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119) AS decimal(18,4))
        OR CAST(SD.KALAN AS decimal(18,4)) <> CAST((SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119) AS decimal(18,4))
        )' WHERE id = 1413;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
        DEPOADI,
        KOD,
        STOKADI,
        LOT,
         CAST(SUM(KALAN) AS decimal(18,4)) AS KALAN ,
        SDI_KALAN
FROM(
        SELECT
                D.DEPOADI,
                 D.ID AS DEPOID ,
                 S1.ID AS STOKID ,
                F1.ID,
                S1.KOD,
                S1.STOKADI,
                SL.SKT,
                coalesce(SL.LOTNO,'''') AS LOT ,
                R1.FIRMA,
                G1.ANAHTAR,
                FB1.FATURATARIH as FATURATARIH,
                FB1.FATURANO,
                 SD.ADET AS KALAN ,
                 SDI.KALAN
         AS SDI_KALAN FROM 
                STOKIZLEME SE1 
                        INNER JOIN FATURA F1 ON SE1.SATIRID=F1.ID 
                        INNER JOIN FATBASLIK FB1 ON F1.FATBASID=FB1.ID AND SE1.BASLIKID=FB1.ID 
                        INNER JOIN STOKLAR S1 ON S1.ID=F1.URUNID INNER JOIN REHBER R1 on R1.ID=FB1.REHBERID 
                        INNER JOIN GENINI G1 ON G1.BOLUM=-1005 AND G1.DEGER=FB1.TUR and G1.DIL=-1 
                        INNER JOIN STOKSERILOT SL ON SL.ID=SE1.SERILOTID AND SL.STOKID = SE1.STOKID 
                        INNER JOIN STOKIZLEMEDEPO SD ON SD.IZLEMID = SE1.ID
                        INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
                        INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = SE1.STOKID AND SDI.DEPOID = D.ID AND SDI.SERILOTID = SE1.SERILOTID
        WHERE 
                coalesce(FB1.DURUM,0) <> 6
                AND SD.ADET <> 0
) AS X
GROUP BY
        DEPOADI,
        KOD,
        STOKADI,
        LOT,
        SDI_KALAN
HAVING
        CAST(SUM(KALAN) AS decimal(18,4)) < 0 OR CAST(SUM(KALAN) AS decimal(18,4)) <> SDI_KALAN' WHERE id = 1414;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
	F1.ID,
	S1.KOD,
	S1.STOKADI,
	SL.SKT,
	coalesce(SL.LOTNO,'''') AS LOT ,
	R1.FIRMA,
	G1.ANAHTAR,
	FB1.FATURATARIH as FATURATARIH,
	FB1.FATURANO,
	 CASE 
				WHEN SE1.BELGETUR IN(4,16,20,119) THEN -1*(SE1.ADET)
				WHEN SE1.BELGETUR IN (14,15) AND SE1.DONUSID = 0  THEN -1*(SE1.ADET)
				ELSE SE1.KALAN 
			END
 AS KALAN FROM 
	STOKIZLEME SE1 inner join 
	FATURA F1 on SE1.SATIRID=F1.ID inner join
	FATBASLIK FB1 on F1.FATBASID=FB1.ID and SE1.BASLIKID=FB1.ID inner join 
	STOKLAR S1 on S1.ID=F1.URUNID inner join REHBER R1 on R1.ID=FB1.REHBERID inner join
	GENINI G1 on G1.BOLUM=-1005 and G1.DEGER=FB1.TUR and G1.DIL=-1 INNER JOIN
	STOKSERILOT SL ON SL.ID=SE1.SERILOTID AND SL.STOKID = SE1.STOKID
WHERE 
	S1.ID = ''$StokId$'' and FB1.DURUM <> 6 AND CASE WHEN SE1.BELGETUR = 109 AND SE1.DONUSID <> 0 THEN 0 WHEN SE1.BELGETUR = 11 AND FB1.TIPI = 2 THEN 0 WHEN SE1.DONUSID = 0 THEN 0 ELSE 1 END = 0
ORDER BY 
	SL.LOTNO,SKT,G1.ANAHTAR,coalesce(SL.LOTNO,''''),FB1.FATURATARIH,SE1.ID' WHERE id = 1415;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	F1.ID,
	S1.KOD,
	S1.STOKADI,
	SL.SKT,
	coalesce(SL.LOTNO,'''') AS LOT ,
	R1.FIRMA,
	G1.ANAHTAR,
	FB1.FATURATARIH as FATURATARIH,
	FB1.FATURANO,
	 CASE WHEN FB1.GIRISDEPO = 6 AND FB1.TUR <> 14 THEN 1*(SE1.ADET)
	           WHEN FB1.CIKISDEPO = 6 AND FB1.TUR <> 14 THEN -1*(SE1.ADET)
			   WHEN FB1.CIKISDEPO = 6 AND FB1.TUR = 14 AND NOT EXISTS(SELECT * FROM STOKIZLEME SI WHERE SI.DONUSID = SE1.ID) THEN -1*(SE1.ADET)
			   ELSE SE1.KALAN 
		    END
 AS KALAN FROM 
	STOKIZLEME SE1 INNER JOIN FATURA F1 on SE1.SATIRID=F1.ID 
				   INNER JOIN FATBASLIK FB1 on F1.FATBASID=FB1.ID AND SE1.BASLIKID=FB1.ID 
				   INNER JOIN STOKLAR S1 on S1.ID=F1.URUNID 
				   INNER JOIN REHBER R1 on R1.ID=FB1.REHBERID 
				   INNER JOIN GENINI G1 on G1.BOLUM=-1005 AND G1.DEGER=FB1.TUR AND G1.DIL=-1 
				   INNER JOIN STOKSERILOT SL ON SL.ID=SE1.SERILOTID
WHERE 
	S1.ID=''$StokId$''
	AND FB1.DURUM<>6   --AND SE1.DONUSID = 0
	AND (GIRISDEPO = 6 OR CIKISDEPO = 6)
	AND NOT EXISTS(SELECT * FROM STOKIZLEME SI WHERE SI.DONUSID = SE1.ID AND SE1.BELGETUR = 14)
ORDER BY 
	SL.LOTNO,SKT,G1.ANAHTAR,coalesce(SL.LOTNO,''''),FB1.FATURATARIH,SE1.ID' WHERE id = 1416;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
	KOD,URUNNO,KATEGORI,STOKADI,MARKA,MODEL,GRUBU,IZLEME,coalesce(STOK,0) AS STOK,coalesce(ANADEPO,0) AS ANADEPO,coalesce(UŞAK,0) AS UŞAK,coalesce(KÜTAHYA,0) AS KÜTAHYA,coalesce(Konsinye Giriş,0) AS Konsinye Giriş,coalesce(Konsinye Çıkış,0) AS Konsinye Çıkış,coalesce(FAİL DEPO,0) AS FAİL DEPO, coalesce(Yedek Depo,0) AS Yedek Depo
FROM(
	SELECT
		S.KOD,		
		URUNNO,
		 K.AD AS KATEGORI ,
		S.STOKADI,
		(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA) AS MARKA ,
		 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer))  AS MODEL ,
		 (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=''-2704'' AND G.DEGER=S.GRUBU) AS GRUBU ,
		(SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2706 AND G.DEGER=S.IZLEME) AS IZLEME ,
		 (SELECT SUM(KALAN) FROM STOKDURUM SD1 WHERE SD1.STOKID = S.ID) AS STOK ,
		D.DEPOADI,		
		coalesce(SD.KALAN,0) AS KALAN
	FROM
		STOKLAR S
			LEFT JOIN STOKDURUM SD ON SD.STOKID = S.ID
			LEFT JOIN DEPOLAR D ON D.ID = SD.DEPOID
			LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
) AS X
PIVOT(
	MAX(KALAN) FOR DEPOADI IN (ANADEPO,UŞAK,KÜTAHYA,Konsinye Giriş,Konsinye Çıkış,FAİL DEPO,Yedek Depo)
)  PVT
WHERE
	KOD LIKE ''$StokKod$%''' WHERE id = 1417;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
	URUNID,
        S.URUNNO,
	S.KOD,
	S.STOKADI,
	 K.AD AS KATEGORI ,
	 D.DEPOADI AS DEPO ,
	 G.ANAHTAR AS MARKA ,
	 G1.ANAHTAR AS MODEL ,
	SI.LOTNO,
	SI.SKT,
	SI.URT,
	 CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.GIREN,2) ELSE ROUND(DRM.GIREN,2) END AS DECIMAL(26,6)) AS GIREN ,
	 CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.CIKAN,2) ELSE ROUND(DRM.CIKAN,2) END AS DECIMAL(26,6)) AS CIKAN , 
	 CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.KALAN,2) ELSE ROUND(DRM.KALAN,2) END AS DECIMAL(26,6)) AS KALAN ,
	Mlt.BIRIMMALIYET,
	CAST(DRM.KALAN*Mlt.BIRIMMALIYET AS MONEY)
 AS MALIYET FROM 
	STOKLAR S 
		INNER JOIN 
                (SELECT 
					DEPO,
					URUNID,
                    round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN , 
                    round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN , 
                    round(SUM(NETMIKTAR),2)
                 AS KALAN FROM( 
					SELECT GIRISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
					FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID  
					WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR=1
						AND FB.FATURATARIH <= ''$Bitis$ 23:59''
					UNION ALL
					SELECT CIKISDEPO AS DEPO ,F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
					FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID 
					WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6)  AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR=1
					AND FB.FATURATARIH <= ''$Bitis$ 23:59''
				) AS ASD GROUP BY URUNID,DEPO
                HAVING SUM(NETMIKTAR)<>0.0) AS DRM ON S.ID=DRM.URUNID 
		LEFT JOIN 
                (SELECT STOKID,BIRIMMALIYET,ROW_NUMBER() OVER (PARTITION BY STOKID ORDER BY TARIH desc)  AS NUM FROM STOK_ORT_MALIYET SM) AS Mlt ON Mlt.STOKID=S.ID
		INNER JOIN DEPOLAR D ON D.ID = DRM.DEPO
		LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
		LEFT JOIN GENINI G ON G.BOLUM = -2701 AND G.DEGER = S.MARKA
		LEFT JOIN GENINI G1 ON G1.DEGER = S.MODEL AND G1.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer) AND G1.DIL<0
		LEFT JOIN
		(
			SELECT
				S.KOD,
				SL.LOTNO,
				coalesce(SL.SKT,'''') AS SKT,
				coalesce(SL.URT,'''') AS URT,
				SID.DEPOID,
				 SUM(CASE WHEN SID.ADET > 0 THEN SID.ADET ELSE 0 END) AS GIREN ,
				 ABS(SUM(CASE WHEN SID.ADET < 0 THEN SID.ADET ELSE 0 END)) AS CIKAN ,
				 SUM(CASE WHEN SID.ADET > 0 THEN SID.ADET ELSE 0 END) - ABS(SUM(CASE WHEN SID.ADET < 0 THEN SID.ADET ELSE 0 END))
			 AS KALAN FROM
				STOKIZLEME SI INNER JOIN STOKIZLEMEDEPO SID ON SID.IZLEMID = SI.ID
							  INNER JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
							  INNER JOIN STOKLAR S ON S.ID = SI.STOKID
							  INNER JOIN FATBASLIK FB ON FB.ID = SI.BASLIKID AND FB.TUR = CASE WHEN SI.BELGETUR = 101 THEN 6 ELSE SI.BELGETUR END
			WHERE
				FB.FATURATARIH <= ''$Bitis$ 23:59''
			GROUP BY
				S.KOD,
				SL.LOTNO,
				SL.SKT,
				SL.URT,
				SID.DEPOID
		--	HAVING
		--		SUM(CASE WHEN SID.ADET > 0 THEN SID.ADET ELSE 0 END) - ABS(SUM(CASE WHEN SID.ADET < 0 THEN SID.ADET ELSE 0 END)) <> 0
		) SI ON SI.KOD = S.KOD AND SI.DEPOID = DRM.DEPO
WHERE
	coalesce(Mlt.NUM,1) = 1
	and S.KOD LIKE ''$StokKod$%''
	AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
	and  coalesce(DEPO,'''') LIKE ''$DepoAdi$%''' WHERE id = 1418;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$BITTAR$ 23:59'' DATETIME,
        ''$REHBER$'' varchar(1000)





SELECT
        FIRMA,
        KOD,
        AD,
        SUM(IRSALIYE) AS IRSALIYE,
        SUM(FATURA) AS FATURA,
        SUM(FIS) AS FIS,
        SUM(KONSINYE) AS KONSINYE,
        SUM(IADE) AS IADE INTO gt_FATURA
FROM(
SELECT
        FB.TUR,
        R.FIRMA,
        K.KOD,
        K.AD,
        coalesce(CASE WHEN FB.TUR = 14 THEN SUM(F.ADET) ELSE 0 END,0) AS IRSALIYE, 
        coalesce(CASE WHEN FB.TUR = 15 THEN SUM(F.ADET) ELSE 0 END,0) AS FATURA,
        coalesce(CASE WHEN FB.TUR = 16 THEN SUM(F.ADET) ELSE 0 END,0) AS FIS,
        coalesce(CASE WHEN FB.TUR = 119 THEN SUM(F.ADET) ELSE 0 END,0) AS KONSINYE,
        coalesce(CASE WHEN FB.TUR = 11 THEN SUM(F.ADET) ELSE 0 END,0) AS IADE
FROM
        FATURA F
                INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
                INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
                INNER JOIN KATEGORI K ON K.ID = S.KATEGORI
                INNER JOIN REHBER R ON R.ID = FB.REHBERID
WHERE
        (
        (FB.TUR IN (14,15,16) AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR = 15 AND F1.YERI = 411 AND F1.YERID = F.ID))
        OR  (FB.TUR = 119        AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR IN (14,15) AND F1.YERI IN (462,468) AND F1.YERID = F.ID))
        OR (FB.TUR = 11 AND FB.TIPI = 2))
        AND FB.FATURATARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
        AND R.FIRMA LIKE ''$REHBER$''+''%''
GROUP BY
        FB.TUR,
        R.FIRMA,
        K.KOD,
        K.AD
) AS X
GROUP BY
        FIRMA,
        KOD,
        AD

SELECT
        R.FIRMA,
        ST.STOKADI,
        CAST(SUM(SD.ADET) AS INT) AS Sipariş Miktarı,
        CAST(coalesce(F.IRSALIYE,0) AS INT) AS İrsaliye,
        CAST(coalesce(F.FATURA,0) AS INT) AS Fatura,
        CAST(coalesce(F.FIS,0) AS INT) AS Fiş,
        CAST(coalesce(F.KONSINYE,0) AS INT) AS Konsinye,
        CAST(coalesce(F.IADE,0) AS INT) AS Gelen İade,
        CAST(coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) AS INT) AS Karşılanan,
        CAST(SUM(SD.ADET) - coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) + coalesce(F.IADE,0)  AS INT) AS Kalan
FROM 
        SIPARISDETAY SD 
                INNER JOIN SIPARIS S ON S.ID = SD.SIPARISID AND S.TUR = 19 
                INNER JOIN REHBER R ON R.ID = S.REHBERID 
                INNER JOIN STOKLAR ST ON ST.ID = SD.URUNID AND SD.TUR = 1
                INNER JOIN KATEGORI K ON K.KOD = ST.KOD
                LEFT JOIN gt_FATURA F ON F.FIRMA = R.FIRMA AND F.KOD = ST.KOD --(11,14,15,16)
WHERE 
        S.SIPARISTARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
        AND R.FIRMA LIKE ''$REHBER$''+''%''
GROUP BY
        R.FIRMA,
        ST.KOD,
        ST.STOKADI,
        F.IRSALIYE,
        F.FATURA,
        F.FIS,
        F.IADE,
        F.KONSINYE
ORDER BY
        ST.KOD

DROP TABLE gt_FATURA
' WHERE id = 1419;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
        D.DEPOADI,
        F1.ID,
        S1.KOD,
        S1.STOKADI,
        SL.SKT,
        coalesce(SL.LOTNO,'''') AS LOT ,
        R1.FIRMA,
        G1.ANAHTAR,
        FB1.FATURATARIH as FATURATARIH,
        FB1.FATURANO,
         SD.ADET
 AS KALAN FROM 
        STOKIZLEME SE1 
                INNER JOIN FATURA F1 ON SE1.SATIRID=F1.ID 
                INNER JOIN FATBASLIK FB1 ON F1.FATBASID=FB1.ID AND SE1.BASLIKID=FB1.ID 
                INNER JOIN STOKLAR S1 ON S1.ID=F1.URUNID INNER JOIN REHBER R1 on R1.ID=FB1.REHBERID 
                INNER JOIN GENINI G1 ON G1.BOLUM=-1005 AND G1.DEGER=FB1.TUR and G1.DIL=-1 
                INNER JOIN STOKSERILOT SL ON SL.ID=SE1.SERILOTID AND SL.STOKID = SE1.STOKID 
                INNER JOIN STOKIZLEMEDEPO SD ON SD.IZLEMID = SE1.ID
                INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
WHERE 
        S1.ID = ''$StokId$'' 
        AND coalesce(FB1.DURUM,0) <> 6 
        AND SD.ADET <> 0
 --AND SL.LOTNO = ''20240704''
ORDER BY 
        D.DEPOADI,SL.LOTNO,SKT,G1.ANAHTAR,coalesce(SL.LOTNO,''''),FB1.FATURATARIH,SE1.ID' WHERE id = 1429;
UPDATE public.dokumler SET sql = '/*PGX*/BEGIN TRY
   DROP TABLE #tmpUrunHareketleri_Rapor
        
  END TRY
  BEGIN CATCH
   create table #tmpUrunHareketleri_Rapor
                (        SIRANO int IDENTITY(1,1) not NULL,
                        KOD varchar(150) NULL,
                        FIRMA varchar(750) NULL,
                        OLAY varchar(50) NULL,
                        URUNID int NULL,
                        FATBASID int NULL,
                        FATURAID int NULL,
                        TUR int NULL,
                        TURAD varchar(50) NULL,
                        FATURATARIH Datetime NULL,
                        FATURASERI varchar(50) NULL,
                        FATURANO varchar(20) NULL,
                        REHBERID int NULL,
                        BIRIM int NULL,
                        BIRIMFIYAT Money NULL,
                        TUTAR Money NULL,
                        KUR varchar(5) NULL,
                        EKMALIYET money NULL,
                        DEPO int NULL,
                        GIREN Float NULL,
                        CIKAN Float NULL,
                        ADET Float NULL,
                        MIKTAR Float NULL
                )

        
  END CATCH
         --SET @YedekBasTar = @BasTar
         --set @AraBasTar= to_char(to_char(@BasTar-1,''YYYY-MM-DD HH24:MI:SS'')+'' 23:59:59'',''YYYY-MM-DD HH24:MI:SS'')

         --SET @BasTar =to_char(cast(YEAR(@BasTar) as varchar)+''-01-01'',''YYYY-MM-DD HH24:MI:SS'')


        INSERT INTO        #tmpUrunHareketleri_Rapor(KOD, FIRMA, OLAY, URUNID, FATBASID,FATURAID, TUR, TURAD, FATURATARIH, FATURASERI, FATURANO, REHBERID, BIRIM, BIRIMFIYAT, TUTAR, KUR,EKMALIYET, DEPO, GIREN, CIKAN , ADET, MIKTAR)
        SELECT   
                    KOD=case when FB.REHBERID>0 then R.KOD else '''' end,
                    FIRMA=case when FB.REHBERID>0 and FB.TUR<>20 then R.FIRMA 
                                                           when FB.TUR=20 AND coalesce(FB.CIKISDEPO,0)<>0 then D2.DEPOADI
                                                           when FB.TUR=7 THEN ''Sayım Fişi''
                                                        else '''' end,
                    OLAY=case                                                when coalesce(FB.TUR,0)=6 then ''Üretim''
                                                    when coalesce(FB.GIRISDEPO,0)=0 then (case when coalesce(FB.TIPI,0)=2 then ''Çıkış(iade)'' else ''Çıkış'' end)
                                                    when coalesce(FB.CIKISDEPO,0)=0 then (case when coalesce(FB.TIPI,0)=2 then ''Giriş(iade)'' else ''Giriş'' end)
                                                    when F.MIKTAR>0 then (case when coalesce(FB.TIPI,0)=2 then ''Giriş(iade)'' else ''Giriş'' end)
                                                    when F.MIKTAR<0 then (case when coalesce(FB.TIPI,0)=2 then ''Çıkış(iade)'' else ''Çıkış'' end) 
                                                                                                        
                                                                                                        end,

                    F.URUNID,
                                        FATBASID=FB.ID,FATURAID=F.ID,
                                        FB.TUR,
                                        TURAD= IT.AD ,
                                        FB.FATURATARIH,FB.FATURASERI,
                                        FB.FATURANO,FB.REHBERID,
                                        F.BIRIM,F.BIRIMFIYAT,F.TUTAR,F.KUR, F.EKMALIYET, 

                                           
                    DEPO=case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then FB.CIKISDEPO
                                                    when coalesce(FB.CIKISDEPO,0)=0 then FB.GIRISDEPO
                                                    when F.MIKTAR>0 then FB.GIRISDEPO
                                                    when F.MIKTAR<0 then FB.CIKISDEPO end,
                    GIREN=case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then 0.0
                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.MIKTAR
                                                    when F.MIKTAR>0 then F.MIKTAR
                                                    when F.MIKTAR<0 then 0.0 end,
                    CIKAN=case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then F.MIKTAR
                                                    when coalesce(FB.CIKISDEPO,0)=0 then 0.0
                                                    when F.MIKTAR>0 then 0.0
                                                    when F.MIKTAR<0 then -F.MIKTAR end,
                    ADET =case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then F.ADET
                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.ADET
                                                    when F.ADET>0 then F.ADET
                                                    when F.ADET<0 then F.ADET end,
                    MIKTAR=case 
                                                    when coalesce(FB.GIRISDEPO,0)=0 then -F.MIKTAR
                                                    when coalesce(FB.CIKISDEPO,0)=0 then F.MIKTAR
                                                    when F.MIKTAR>0 then F.MIKTAR
                                                    when F.MIKTAR<0 then F.MIKTAR end
                                        --,KALAN=0
    FROM           
        FATBASLIK FB 
                        inner join 
                                FATURA F on F.FATBASID=FB.ID 
                        left outer join 
                                REHBER R on FB.REHBERID=R.ID
                        left join depolar d1 on fb.GIRISDEPO=D1.ID
                        left join depolar d2 on fb.CIKISDEPO=D2.ID
                        inner join ISLEMTURLERI IT ON IT.TUR = FB.TUR and IT.TIP IN (0,1)

                        
    where 
                coalesce(FB.DURUM,1)<>6 and
                F.TUR=1 and 
                F.STOKDURUMDEGIS=1 and 
                FB.TUR NOT IN (20,109,119)
UNION ALL

SELECT   
                    KOD=case when FB.REHBERID>0 then R.KOD else '''' end,
                    FIRMA=case when FB.TUR IN (20) THEN D2.DEPOADI
                                                           when FB.TUR IN (109,119) THEN R.FIRMA
                
                                                        else '''' end,
                    OLAY=case when coalesce(FB.TIPI,0)=2 then ''Çıkış(iade)'' else ''Çıkış'' end,

                    F.URUNID,FATBASID=FB.ID,FATURAID=F.ID,
                                        FB.TUR,--= CASE WHEN (FB.TUR IN (109) AND FB.TIPI=2)THEN ''İade Konsinye'' ELSE FB.TUR END,
                                        TURAD= CASE WHEN FB.TUR =109 AND FB.TIPI = 2 THEN ''İade Konsinye'' ELSE IT.AD END,
--                                        TURAD=(SELECT DISTINCT CASE WHEN (FB.TUR IN (109) AND FB.TIPI=2) THEN ''İade Konsinye'' ELSE IT.AD END FROM ISLEMTURLERI IT WHERE IT.TUR=FB.TUR),
                                        FB.FATURATARIH,FB.FATURASERI,
                                        FB.FATURANO,FB.REHBERID,F.BIRIM,F.BIRIMFIYAT,F.TUTAR,F.KUR,  F.EKMALIYET,
                                   
                    DEPO        = CIKISDEPO,
                    GIREN   = 0,
                    CIKAN   = F.MIKTAR,
                    ADET    = F.ADET,
                    MIKTAR  = -F.MIKTAR
                                        --,KALAN=0
    FROM           
        FATBASLIK FB 
                        inner join 
                                FATURA F on F.FATBASID=FB.ID 
                        left outer join 
                                REHBER R on FB.REHBERID=R.ID
                        left join depolar d1 on fb.GIRISDEPO=D1.ID
                        left join depolar d2 on fb.CIKISDEPO=D2.ID
                        inner join ISLEMTURLERI IT ON IT.TUR = FB.TUR and IT.TIP IN (0,1)
    where 
                coalesce(FB.DURUM,1)<>6 and
                F.TUR=1 and 
                (FB.TUR IN (20,119) OR (FB.TUR IN (109) AND FB.TIPI=2)) AND
                F.STOKDURUMDEGIS=1

UNION ALL

SELECT   
                    KOD=case when FB.REHBERID>0 then R.KOD else '''' end,
                    FIRMA=case when FB.TUR IN (20) THEN D1.DEPOADI
                                                           when FB.TUR IN (109,119) THEN R.FIRMA
                                                           
                                                        else '''' end,
                    OLAY=case when coalesce(FB.TIPI,0)=2 then ''Giriş(iade)'' else ''Giriş'' end,

                    F.URUNID,FATBASID=FB.ID,FATURAID=F.ID,
                                        FB.TUR,
                                        TURAD= IT.AD ,
                                        FB.FATURATARIH,FB.FATURASERI,
                                        FB.FATURANO,FB.REHBERID,F.BIRIM,F.BIRIMFIYAT,F.TUTAR,F.KUR,  F.EKMALIYET,
                                   
                    DEPO        = GIRISDEPO,
                    GIREN        = F.MIKTAR,
                    CIKAN   = 0,
                    ADET        = F.ADET,
                    MIKTAR  = F.MIKTAR
                                        --,KALAN=0
    FROM           
        FATBASLIK FB 
                        inner join 
                                FATURA F on F.FATBASID=FB.ID 
                        left outer join 
                                REHBER R on FB.REHBERID=R.ID
                        left join depolar d1 on fb.GIRISDEPO=D1.ID
                        left join depolar d2 on fb.CIKISDEPO=D2.ID
                        inner join ISLEMTURLERI IT ON IT.TUR = FB.TUR and IT.TIP IN (0,1)
    where 
                coalesce(FB.DURUM,1)<>6 and
                F.TUR=1 and 
                FB.TUR IN (20,109,119) AND
                F.STOKDURUMDEGIS=1


        SELECT t.KOD, FIRMA, OLAY, 
        --URUNID, 
        t.FATBASID,
        --t.FATURAID, TUR, 
        TURAD, FATURATARIH, FATURASERI, FATURANO, 
        --REHBERID, BIRIM, BIRIMFIYAT, TUTAR, KUR, EKMALIYET,
         D.DEPOADI AS DEPO,S.KOD,S.STOKADI,SL.SERINO,SL.LOTNO, coalesce(SI.ADET,t.ADET) AS ADET --coalesce(SI.ADET,t.MIKTAR) AS MIKTAR --KALAN = (SUM(t.MIKTAR) OVER (ORDER BY SIRANO))--,SM.BIRIMMALIYET
        FROM 
                #tmpUrunHareketleri_Rapor t left outer join STOK_ORT_MALIYET SM on t.DEPO=SM.DEPOID and t.FATBASID=SM.FATBASID and t.FATURAID=SM.FATURAID
                        INNER JOIN STOKIZLEME SI ON SI.BASLIKID = t.FATBASID AND SI.SATIRID = t.FATURAID AND SI.BELGETUR = t.TUR
                        INNER JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
                        INNER JOIN STOKLAR S ON S.ID = t.URUNID
                        INNER JOIN DEPOLAR D ON D.ID = t.DEPO
        WHERE
                SL.SERINO LIKE ''$SeriNo$''+''%''        
                AND SL.LOTNO LIKE ''$LotNo$''+''%''
    
   DROP TABLE #tmpUrunHareketleri_Rapor' WHERE id = 1430;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$KOD$'' VARCHAR(100),
                coalesce(''$BORC$'',0) MONEY,
                coalesce(''$GUN$'',0) INT
        





IF OBJECT_ID(''tempdb..#YaslandirmaSonuc'') IS NOT NULL
    DROP TABLE #YaslandirmaSonuc

CREATE TABLE #YaslandirmaSonuc (
    KOD VARCHAR(50),
    FIRMA VARCHAR(255),
    ISLEMTARIHI DATETIME,
    VADESONU DATETIME,
    ODEMETARIHI DATETIME,
    GECIKENGUNSAYISI INT,
    ISLEMTURU varchar(100),
    ISLEMACIKLAMA varchar(500),
    ODEMETURU varchar(100),
    ODEMEACIKLAMA varchar(500),
    BORCTUTARI MONEY,
    ODEMETUTARI MONEY,
    ODENENTUTAR MONEY,
    GECIKENTUTAR MONEY,
    AGIRLIKGECIKME MONEY,
        KUR varchar(100)
)



SELECT 
        ID, KUR
FROM 
        uv_Cari_Borclu_Listesi
WHERE
        KOD LIKE ''$KOD$''+''%''
                AND BAKIYE >= coalesce(''$BORC$'',0)

OPEN CariCursor
FETCH NEXT FROM CariCursor INTO @ID, @Kur

WHILE @@FETCH_STATUS = 0
BEGIN
    INSERT INTO #YaslandirmaSonuc (KOD,FIRMA, ISLEMTARIHI, VADESONU, ODEMETARIHI, GECIKENGUNSAYISI, ISLEMTURU, ISLEMACIKLAMA, ODEMETURU, ODEMEACIKLAMA, BORCTUTARI, ODEMETUTARI, ODENENTUTAR, GECIKENTUTAR, AGIRLIKGECIKME)
    EXEC Sp_Prg_CariYaslandirma @ID, ''$TARIH$ 23:59'', @Kur

    UPDATE 
                T
    SET 
                T.KUR = @Kur
    FROM 
                #YaslandirmaSonuc T 
                        INNER JOIN REHBER R ON R.KOD = T.KOD 
        WHERE 
                KUR IS NULL AND R.ID = @ID

        FETCH NEXT FROM CariCursor INTO @ID, @Kur

END

CLOSE CariCursor
DEALLOCATE CariCursor

SELECT
        KOD,
        FIRMA,
        TEMSILCI,
        KUR,
        round(TUTAR,2) AS AÇIK HESAP R.L (TL),
        BORC TOPLAM=round(cast(sum(BORC TOPLAM) as money),2),
        BORC 0-=round(cast(sum(BORC 0-) as money),2),
        BORC 1-30=round(cast(sum(BORC 1-30) as money),2),
        BORC 30-60=round(cast(sum(BORC 30-60) as money),2),
        BORC 60-90=round(cast(sum(BORC 60-90) as money),2),
        BORC 90-120=round(cast(sum(BORC 90-120) as money),2),
        BORC 120-180=round(cast(sum(BORC 120-180) as money),2),
        BORC 180-360=round(cast(sum(BORC 180-360) as money),2),
        BORC 360+=round(cast(sum(BORC 360+) as money),2)
FROM(
        SELECT 
                R.KOD,R.FIRMA,RT.FIRMA AS TEMSILCI,RK.TUTAR,
                BORC TOPLAM=(case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end),
                                GECIKMEGUN = cast((ODEMETARIHI-VADESONU) as integer),
                BORC 0-=case when cast((ODEMETARIHI-VADESONU) as integer) <= 0 then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 1-30=case when (cast((ODEMETARIHI-VADESONU) as integer) > 0) and (cast((ODEMETARIHI-VADESONU) as integer) <= 30) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 30-60=case when (cast((ODEMETARIHI-VADESONU) as integer) > 30) and (cast((ODEMETARIHI-VADESONU) as integer) <= 60) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 60-90=case when (cast((ODEMETARIHI-VADESONU) as integer) > 60) and (cast((ODEMETARIHI-VADESONU) as integer) <= 90) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 90-120=case when (cast((ODEMETARIHI-VADESONU) as integer) > 90) and (cast((ODEMETARIHI-VADESONU) as integer) <= 120) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 120-180=case when (cast((ODEMETARIHI-VADESONU) as integer) > 120) and (cast((ODEMETARIHI-VADESONU) as integer) <= 180) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 180-360=case when (cast((ODEMETARIHI-VADESONU) as integer) > 180) and (cast((ODEMETARIHI-VADESONU) as integer) <= 360) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end,
                BORC 360+=case when (cast((ODEMETARIHI-VADESONU) as integer) > 360) then (case when ODEMEACIKLAMA = ''Kalan Borç'' then ODENENTUTAR else -1.0*ODENENTUTAR end) else 0.0 end ,
                T.KUR
        FROM 
                #YaslandirmaSonuc T 
                INNER JOIN REHBER R ON T.KOD = R.KOD 
                LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
                LEFT JOIN REHBER_KOTA RK ON RK.REHBERID=R.ID
        WHERE
                (ODEMEACIKLAMA = ''Kalan Borç'' or ISLEMACIKLAMA=''Kalan Alacak'')
) AS XX
WHERE
        GECIKMEGUN >= coalesce(''$GUN$'',0)
GROUP BY 
        KOD,FIRMA,TUTAR,TEMSILCI,KUR
' WHERE id = 1431;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$BitTar$ 23:59'' DATETIME




SELECT 
       XXX.KOD,XXX.FIRMA,RT.FIRMA AS TEMSILCI, BAKIYE = cast(BAKIYE as double precision),KUR,TLKARSILIK=cast((BAKIYE*(select D.SATIS from DOVIZ D where D.CINSI=XXX.KUR order by D.TARIH desc LIMIT 1 )) as double precision)  
FROM(
        select  
                DISTINCT REHBERID,R.SUBEID,R.KOD ,R.FIRMA,cast(TOPLAM_BORC as float) AS BORC ,cast(TOPLAM_ALACAK as float) AS ALACAK,KUR ,BAKIYE=TOPLAM_BORC-TOPLAM_ALACAK 
        FROM(
    select
                REHBERID,TOPLAM_BORC=SUM(coalesce(BORC,0)),TOPLAM_ALACAK=SUM(coalesce(ALACAK,0)),KUR=coalesce(KUR,''TL'')
        from (
           SELECT
                REHBERID,
                SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
                0 AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR

                --KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
                FROM FATBASLIK F
                WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17)) 
                AND FATURATARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
                GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

        UNION ALL

                SELECT REHBERID,
                0 AS BORC,
                SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
                CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR
                FROM FATBASLIK F
                WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13)) 
                AND FATURATARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
                GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

        UNION ALL

                SELECT REHBERID,
                SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
                SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR
                FROM KASA K
                WHERE TUR not between 60 and 79  
                AND ISLEMTARIHI BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
                GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

        UNION ALL
                SELECT CH.REHBERID,
                BORC=SUM(Case when CH.ISLEM in(140,131,132,133,134,137) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                ALACAK=SUM(Case when CH.ISLEM in(130,141) then (CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_TUTARI ELSE c.TUTAR END) else 0.0 end),
                CASE WHEN c.EKSTREDEKULLAN=1 THEN C.DOVIZ_KURU else c.KUR end as KUR
                FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                WHERE CH.ISLEM in(130,131,132,134,137,140,141) 
                AND CH.TARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
                GROUP BY CH.REHBERID,CASE WHEN c.EKSTREDEKULLAN=1 THEN c.DOVIZ_KURU else c.KUR end

        UNION ALL

                SELECT REHBERID,
                0 AS BORC,
                SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                FROM SENETLER S
                WHERE TUR = 24   
                AND TARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
                GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR END

        UNION ALL

                SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE TUTAR END) AS
                BORC,0 AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end as KUR
                FROM SENETLER S
                WHERE TUR = 34  
                AND TARIH BETWEEN ''$BasTar$ 00:00'' AND ''$BitTar$ 23:59''
                GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

                ) as asd
        group by REHBERID,KUR
        ) AS DSA
                INNER JOIN REHBER R ON         DSA.REHBERID=R.ID AND coalesce(R.KDR_Disi,''False'') =''False''
    where  
                R.ID > 0 and coalesce(R.ID,'''')<>'''' and R.GRUP <> 335 
                AND TOPLAM_BORC>TOPLAM_ALACAK          
) AS XXX       
                INNER JOIN REHBER R2  ON  XXX.SUBEID=R2.ID
                INNER JOIN REHBER RF ON RF.ID = XXX.REHBERID
                LEFT JOIN REHBER RT ON RT.ID = RF.TEMSILCI
ORDER BY KUR,XXX.FIRMA
' WHERE id = 1432;
UPDATE public.dokumler SET sql = '/*PGX*/






if OBJECT_ID(''tempdb..gt_tmpAlacaklar2'') is not null
        drop table gt_tmpAlacaklar2
if OBJECT_ID(''tempdb..gt_tmpBorclar2'') is not null
        drop table gt_tmpBorclar2
create table gt_tmpAlacaklar2 (
        ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),
        BELGENO varchar(100),ACIKLAMA varchar(500), ALACAK money, KUR varchar(5), KUMULATIFALACAK money)
create table gt_tmpBorclar2 (
        ID int identity(1,1), REHBERID int, ISLEMTARIHI datetime, VADESONU datetime, ISLEMTURU varchar(100),
        BELGENO varchar(100),ACIKLAMA varchar(500), BORC money, KUR varchar(5), KUMULATIFBORC money)

insert gt_tmpAlacaklar2
select REHBERID,
        ISLEMTARIHI=dateadd(millisecond,ISLEMID,TARIH),VADESONU=dateadd(millisecond,ISLEMID,VADE),ISLEMTURU=TURAD,BELGENO=NO,ACIKLAMA,ALACAK,KUR,
        KUMULATIFALACAK=SUM(case when ALACAK>0.0 then ALACAK else 0.0 end) OVER (PARTITION BY REHBERID ORDER BY dateadd(millisecond,ISLEMID,VADE))
from
        (
                                Select 
                                        K.REHBERID,
                                        ISLEMID=K.ID,
                                        ISLEMTARIHI AS TARIH,BELGENO as NO, K.TUR,
                                        TURAD  =        case when K.TUR like ''26__'' then (select ANAHTAR + '' tahsilatı '' from GENINI where BOLUM=-2329 and 2600+DEGER=K.TUR LIMIT 1 )
                                                                         when K.TUR like ''36__'' then (select ANAHTAR + '' ödemesi '' from GENINI where BOLUM=-2329 and 3600+DEGER=K.TUR LIMIT 1 )
                                                                else (select ANAHTAR from GENINI where BOLUM=-1005 and DEGER=K.TUR LIMIT 1 )end, 
                                        K.ACIKLAMA, 
                                        BORC        = case when EKSTREDEKULLAN=1 AND BORC>0   then K.DOVIZ_TUTARI else K.BORC end,
                                        ALACAK        = case when EKSTREDEKULLAN=1 AND ALACAK>0 then K.DOVIZ_TUTARI else K.ALACAK end,
                                        KUR                = case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end,
                                        VADE=ISLEMTARIHI

                                From 
                                        KASA K         
                                Where 
                                                --K.REHBERID=@RehberID  and 
                                                K.ALACAK-K.BORC>0.0 and
                                                K.ISLEMTARIHI<=''$BitTar$ 23:59'' and 
                                                ((K.TUR in (49))or(K.TUR not between 40 and 79)) and 
                                                K.TUR<>2 and
                                                ''TL''=case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end
                        UNION ALL
                                Select F.REHBERID,ISLEMID=F.ID, FATURATARIH as TARIH,FATURANO as NO, F.TUR,
                                        TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ),
                                        ACIKLAMA=case
                                                when F.TIPI=2 --(select distinct TUR from FATBASLIK)
                                                        then ''IADE ''+coalesce(F.ACIKLAMA,'''')
                                                when 1 in (select 1 from FATURA where FATBASID=F.ID and ID in (select YERID from FATURA X where X.REHBERID=F.REHBERID and YERI in (416,417)))  
                                                        then ''IADESI VAR ''+coalesce(F.ACIKLAMA,'''')
                                                else coalesce(F.ACIKLAMA,'''') end, 
                                        BORC=case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end ,
                                        ALACAK=case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end,
                                        KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
                                        VADE=F.FATURATARIH+coalesce(F.VADE,0)
                                From 
                                        FATBASLIK F  inner join 
                                        REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6 
                                Where 
                                        F.FATURA_TUTARI <> 0.0 and
                                        case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end > 0.0 and
                                        --F.REHBERID=@RehberID and
                                        F.FATURATARIH<=''$BitTar$ 23:59'' and
                                        ''TL''=case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end

                        ---- Çek
                        UNION ALL

                                Select CH.REHBERID,ISLEMID=CH.ID,
                                        CH.TARIH, MAKBUZNO as NO, TUR=case when CH.ISLEM in(130,141) then 23 else 33 end,
                                        TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ),
                                        ACIKLAMA=case when CH.ISLEM in (137,141) then ''IADE ''
                                                                when C.ID in (select CH1.CEKSENETLERID from CEKHAREKET CH1 where CH1.TARIH <= ''$BitTar$ 23:59'' and CH1.ISLEM in (137,141)) then ''IADESI VAR ''
                                                                else '''' end + ''Serino:''+cast(C.SERINO as varchar)+'' ''+rtrim(coalesce(CH.ACIKLAMA,'''')),
                                        BORC=Case when CH.ISLEM in(140,131,132,133,134,137) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
                                        ALACAK=Case when CH.ISLEM in(130,141) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
                                        KUR=case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end,
                                        VADE
                                From 
                                        CEKLER C  inner join
                                        CEKHAREKET CH on C.ID=CH.CEKSENETLERID 
                                Where 
                                        CH.ISLEM in(130,131,132,134,137,140,141) and
                                        C.TUTAR <> 0.0 and
                                        --CH.REHBERID=@RehberID and 
                                        CH.TARIH <= ''$BitTar$ 23:59'' and 
                                        ''TL''=case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end

                        ---- Senet

                        UNION ALL

                        Select C.REHBERID,ISLEMID=C.ID,
                                TARIH, MAKBUZNO as NO,C.TUR, TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ),
                                ACIKLAMA=C.ACIKLAMA,
                                BORC=Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
                                ALACAK=Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
                                KUR=case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end,
                                VADE
                        From 
                                SENETLER C
                        Where
                                        --C.REHBERID=@RehberID and 
                                        C.TUTAR <> 0.0 and
                                        Case when C.TUR=24 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0.0 end > 0.0 and
                                        C.TARIH <= ''$BitTar$ 23:59'' and
                                        ''TL''=case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end

        ) as xxx
where ALACAK>0.0
 order by dateadd(millisecond,ISLEMID,VADE)

--SELECT * FROM gt_tmpAlacaklar2 WHERE REHBERID = 1276

insert gt_tmpBorclar2
select REHBERID,
        ISLEMTARIHI=dateadd(millisecond,ISLEMID,TARIH),VADESONU=dateadd(millisecond,ISLEMID,VADE),ISLEMTURU=TURAD,BELGENO=NO,ACIKLAMA,BORC,KUR,
        KUMULATIFBORC=SUM(case when BORC>0.0 then BORC else 0.0 end) OVER (PARTITION BY REHBERID ORDER BY dateadd(millisecond,ISLEMID,VADE)) 
