                                                K.TUR<>2 and
                                                ''TL''=case when EKSTREDEKULLAN=1 then K.DOVIZ_KURU else K.KUR end
                        UNION ALL
                                Select F.REHBERID,ISLEMID=F.ID, FATURATARIH as TARIH,FATURANO as NO, F.TUR,
                                        TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=F.TUR LIMIT 1 ),
                                        ACIKLAMA=case
                                                when F.TIPI=2 
                                                        then ''IADE ''+coalesce(F.ACIKLAMA,'''')
                                                when 1 in (select 1 from FATURA where FATBASID=F.ID and ID in (select YERID from FATURA X where X.REHBERID=F.REHBERID and YERI in (416,417)))  
                                                        then ''IADESI VAR ''+coalesce(F.ACIKLAMA,'''')
                                                else coalesce(F.ACIKLAMA,'''') end, 
                                        BORC=case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end ,
                                        ALACAK=case when F.TUR in (15,16,17) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end,
                                        KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
                                        VADE=F.FATURATARIH+coalesce(F.VADE,0)
                                From 
                                        FATBASLIK F  inner join 
                                        REHBER R on F.REHBERID=R.ID and F.TUR in (8,11,12,13,15,16,17) and coalesce(F.DURUM,0)<>6 
                                Where 
                                        F.FATURA_TUTARI <> 0.0 and
                                        case when F.TUR in (8,11,12,13) then 0.0 else (case when EKSTREDEKULLAN=1 then DOVIZ_TUTARI else FATURA_TUTARI end) end > 0.0 and 
                                        --F.REHBERID=@RehberID and 
                                        F.FATURATARIH<=''$BitTar$ 23:59'' and
                                        ''TL''=case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end

                        ---- Çek
                        UNION ALL

                                Select CH.REHBERID,ISLEMID=CH.ID,
                                        CH.TARIH, MAKBUZNO as NO, TUR=case when CH.ISLEM in(130,141) then 23 else 33 end,
                                        TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=(case when CH.ISLEM in(130,141) then 23 else 33 end)and DIL=-1 LIMIT 1 ),
                                        ACIKLAMA=case when CH.ISLEM in (137,141) then ''IADE ''
                                                                when C.ID in (select CH1.CEKSENETLERID from CEKHAREKET CH1 where CH1.TARIH <= ''$BitTar$ 23:59'' and CH1.ISLEM in (137,141)) then ''IADESI VAR ''
                                                                else '''' end + ''Serino:''+cast(C.SERINO as varchar)+'' ''+rtrim(coalesce(CH.ACIKLAMA,'''')),
                                        BORC=Case when CH.ISLEM in(140,131,132,133,134,137) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
                                        ALACAK=Case when CH.ISLEM in(130,141) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0.0 end,
                                        KUR=case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'') end,
                                        VADE
                                From 
