                        UNION ALL

                        Select C.REHBERID,ISLEMID=C.ID,
                                TARIH, MAKBUZNO as NO,C.TUR, TURAD=(select ANAHTAR from GENINI where BOLUM=''-1005'' and DEGER=C.TUR LIMIT 1 ),
                                ACIKLAMA=rtrim(C.ACIKLAMA),
                                BORC=Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0.0)end) else 0.0 end,
