                        Where
                                        --C.REHBERID=@RehberID and 
                                        C.TUTAR <> 0.0 and
                                        Case when C.TUR=34 then (case when EKSTREDEKULLAN=1 then C.DOVIZ_TUTARI else coalesce(C.TUTAR,0)end) else 0.0 end > 0.0 and
                                        C.TARIH <= ''$BitTar$ 23:59''  and 
                                        ''TL'' = case when EKSTREDEKULLAN=1 then C.DOVIZ_KURU else coalesce(C.KUR,''TL'') end

        ) as xxx
where BORC>0.0
order by dateadd(millisecond,ISLEMID,VADE)

--SELECT * FROM gt_tmpBorclar2 WHERE REHBERID = 1276

--SELECT * FROM gt_tmpAlacaklar2
insert into gt_tmpAlacaklar2(REHBERID, ISLEMTARIHI, VADESONU ,ISLEMTURU, BELGENO, ACIKLAMA, ALACAK, KUR, KUMULATIFALACAK)
SELECT 
        R.ID,
        ''$BitTar$ 23:59'',
        ''$BitTar$ 23:59'',
        ''Kalan Borç'',
        ''-'',
        ''Kalan Borç'',
        coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0) - coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0),
        ''TL'',
        coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0)
FROM 
        REHBER R
WHERE 
        --SINIF <> 1
     coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0) > coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0)

insert into gt_tmpBorclar2(REHBERID, ISLEMTARIHI, VADESONU ,ISLEMTURU, BELGENO, ACIKLAMA, BORC, KUR, KUMULATIFBORC)
SELECT 
        R.ID,
        ''$BitTar$ 23:59'',
        ''$BitTar$ 23:59'',
        ''Kalan Alacak'',
        ''-'',
        ''Kalan Alacak'',
        coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0) - coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0),
        ''TL'',
        coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0)
FROM 
        REHBER R
WHERE 
        --SINIF <> 1
         coalesce((select sum(BORC) from gt_tmpBorclar2 B WHERE B.REHBERID = R.ID ),0.0) < coalesce((select sum(ALACAK) from gt_tmpAlacaklar2 A WHERE A.REHBERID = R.ID ),0.0)


SELECT *,BORCSIRALAMA = SUM(ODENENTUTAR) OVER (PARTITION BY KOD,FIRMA)
FROM(
        select
                R.KOD,R.FIRMA,R1.FIRMA AS TEMSILCI,RBI.BILGI AS IL,
                ISLEMTARIHI,VADESONU,ODEMETARIHI,
                GECIKENGUNSAYISI=cast((ODEMETARIHI-VADESONU) as integer), 
                ISLEMTURU,ISLEMACIKLAMA,ODEMETURU,ODEMEACIKLAMA,
                BORCTUTARI,ODEMETUTARI,ODENENTUTAR,
                GECIKENTUTAR=case 
                        when (ODEMETURU=''Kalan Borç(-)'' and cast((ODEMETARIHI-VADESONU) as integer)>=0) then ODENENTUTAR 
                        when (ISLEMTURU=''Kalan Alacak(-)'' and cast((ODEMETARIHI-VADESONU) as integer)>=0)  then ODENENTUTAR else 0.0 end,
                AGIRLIKLIGECIKME=ODENENTUTAR*cast((ODEMETARIHI-VADESONU) as integer)
        from
        ( 
        select A.REHBERID,
                B.ISLEMTARIHI,
                B.VADESONU,
                ISLEMTURU=B.ISLEMTURU+''(''+B.BELGENO+'')'',
                ISLEMACIKLAMA=B.ACIKLAMA,
                BORCTUTARI=B.BORC,
                ODEMETARIHI=A.ISLEMTARIHI,
                ODEMETURU=A.ISLEMTURU+''(''+A.BELGENO+'')'',
                ODEMEACIKLAMA=A.ACIKLAMA,
                ODEMETUTARI=A.ALACAK,
                ODENENTUTAR=(case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end) - coalesce(lag(case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end) over (PARTITION BY A.REHBERID order by case when A.KUMULATIFALACAK<B.KUMULATIFBORC then A.KUMULATIFALACAK else B.KUMULATIFBORC end),0.0),
                KUR=''TL''

        from 
                gt_tmpAlacaklar2 as A join
                gt_tmpBorclar2 as B on B.KUMULATIFBORC-B.BORC<A.KUMULATIFALACAK and A.KUMULATIFALACAK-A.ALACAK<B.KUMULATIFBORC AND A.REHBERID = B.REHBERID

        )as x inner join REHBER R on x.REHBERID=R.ID
                  left join GENINI GT ON GT.BOLUM = -2207 AND GT.DEGER = R.TEMAS
                  inner join REHBER_BAKIYE RB ON RB.REHBERID = R.ID
                  left JOIN REHBERILETISIM RI ON RI.REHBERID = R.ID AND RI.VARSAYILAN = 1
                  left JOIN REHBERBILGI RBI ON RBI.YER_ID =  RI.ID AND RBI.ETIKET = ''İl''
                  LEFT JOIN REHBER R1 ON R1.ID = R.TEMSILCI    
        WHERE
                RB.TUTAR > = 1.0
                AND ODEMETURU = ''Kalan Borç(-)''
                AND coalesce(GT.ANAHTAR,'''') LIKE ''$TEMAS$%''
                AND R.FIRMA LIKE ''$FIRMA$%''
                AND R.KOD LIKE ''120%''   
                AND coalesce(R1.FIRMA,'''') LIKE ''$TEMSILCI$%''
        ) AS X
        WHERE
                CASE WHEN ''$Gecikme$'' = ''Vadesi geçen'' AND GECIKENGUNSAYISI >= 0 THEN 1 WHEN ''$Gecikme$'' = ''Vadesi geçmemiş'' AND GECIKENGUNSAYISI < 0 THEN 1 WHEN coalesce(''$Gecikme$'',''Tümü'') = ''Tümü'' THEN 1 ELSE 0 END = 1
        ORDER BY
                  BORCSIRALAMA DESC --FIRMA
' WHERE id = 1433;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$BitTar$ 23:59'' datetime




if OBJECT_ID(''tempdb..gt_tmpTahsilat'') is not null
       drop table gt_tmpTahsilat
create table gt_tmpTahsilat (
       REHBERID int, KOD varchar(100), KUR varchar(5), POS ile Tahsilat money,Banka Tahsilat money, Çekle Tahsilat money, Senetle Tahsilat money, Nakit Tahsilat money, Toplam Tahsilat money)

insert gt_tmpTahsilat
SELECT
        *,
        coalesce(POS ile Tahsilat,0)+coalesce(Banka Tahsilat,0)+coalesce(Çekle Tahsilat,0)+coalesce(Senetle Tahsilat,0)+coalesce(Nakit Tahsilat,0) AS Toplam Tahsilat
FROM(
        SELECT
                R.ID,
                R.KOD,
                IT.AD,
                CASE WHEN K.EKSTREDEKULLAN = 1 AND KUR <> ''TL'' THEN DOVIZ_TUTARI ELSE ABS(BORC-ALACAK) END AS BAKIYE,
                CASE WHEN K.EKSTREDEKULLAN = 1 AND KUR <> ''TL'' THEN DOVIZ_KURU ELSE K.KUR END AS KUR
        FROM
                KASA K 
                        INNER JOIN ISLEMTURLERI IT ON IT.TUR = K.TUR
                        INNER JOIN REHBER R ON R.ID = K.REHBERID
        WHERE
                K.ISLEMTARIHI BETWEEN ''$BasTar$ 23:59'' AND ''$BitTar$ 23:59''
                AND IT.AD LIKE ''%Tahsilat%''
        UNION ALL
        SELECT
                CH.REHBERID,
                R.KOD,
                IT.AD,        
                BAKIYE = ABS(case when CH.ISLEM in(131,132,133,134,135,136,137,138,140) then  C.TUTAR else 0 end - case when CH.ISLEM in(130,141) then C.TUTAR else 0 end),
                C.KUR
        FROM 
                CEKLER C 
                        INNER JOIN CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                        INNER JOIN REHBER R on R.ID=CH.REHBERID
                        INNER JOIN ISLEMTURLERI IT ON IT.TUR = CASE WHEN CH.ISLEM between 130 and 139 and CEKSENET=101 THEN 23 WHEN CH.ISLEM between 130 and 139 and CEKSENET=121 then 24  END 

        WHERE 
                CH.ISLEM in(130,131,132,133,134,135,137,138,140,141) 
                AND CH.TARIH BETWEEN ''$BasTar$ 23:59'' AND ''$BitTar$ 23:59''
) AS X
PIVOT
(
        SUM(BAKIYE) FOR AD IN (POS ile Tahsilat,Banka Tahsilat,Çekle Tahsilat,Senetle Tahsilat,Nakit Tahsilat)
)AS PVT

SELECT 
         R.KOD AS Kod,
         R.FIRMA AS Cari,
         GN.ANAHTAR AS Bölge,
         RBI.BILGI AS İl,
         RT.FIRMA AS Satıcı,
         KUR as Para Birimi,
         POS ile Tahsilat,
         Banka Tahsilat,
         Çekle Tahsilat,
         Senetle Tahsilat,
         Nakit Tahsilat,
         Toplam Tahsilat
FROM 
        gt_tmpTahsilat X
                INNER JOIN REHBER R on X.REHBERID=R.ID
                LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
                LEFT JOIN REHBERILETISIM RI ON RI.REHBERID = R.ID AND RI.VARSAYILAN = 1
                LEFT JOIN REHBERBILGI RBI ON RBI.YER_ID =  RI.ID AND RBI.ETIKET = ''İl''
                LEFT JOIN GENINI GN ON GN.BOLUM = -2210 AND GN.DEGER = R.BOLGE
                LEFT JOIN GENINI GT ON GT.BOLUM = -2207 AND GT.DEGER = R.TEMAS
' WHERE id = 1434;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$BitTar$ 23:59'' datetime




if OBJECT_ID(''tempdb..gt_tmpTahsilat'') is not null
       drop table gt_tmpTahsilat
create table gt_tmpTahsilat (
       REHBERID int, KOD varchar(100), KUR varchar(5), POS ile Tahsilat money,Banka Tahsilat money, Çekle Tahsilat money, Senetle Tahsilat money, Nakit Tahsilat money, Toplam Tahsilat money)

insert gt_tmpTahsilat
SELECT
        *,
        coalesce(POS ile Tahsilat,0)+coalesce(Banka Tahsilat,0)+coalesce(Çekle Tahsilat,0)+coalesce(Senetle Tahsilat,0)+coalesce(Nakit Tahsilat,0) AS Toplam Tahsilat
FROM(
        SELECT
                R.ID,
                R.KOD,
                IT.AD,
                CASE WHEN K.EKSTREDEKULLAN = 1 AND KUR <> ''TL'' THEN DOVIZ_TUTARI ELSE ABS(BORC-ALACAK) END AS BAKIYE,
                CASE WHEN K.EKSTREDEKULLAN = 1 AND KUR <> ''TL'' THEN DOVIZ_KURU ELSE K.KUR END AS KUR
        FROM
                KASA K 
                        INNER JOIN ISLEMTURLERI IT ON IT.TUR = K.TUR
                        INNER JOIN REHBER R ON R.ID = K.REHBERID
        WHERE
                K.ISLEMTARIHI BETWEEN ''$BasTar$ 23:59'' AND ''$BitTar$ 23:59''
                AND IT.AD LIKE ''%Tahsilat%''
        UNION ALL
        SELECT
                CH.REHBERID,
                R.KOD,
                IT.AD,        
                BAKIYE = ABS(case when CH.ISLEM in(131,132,133,134,135,136,137,138,140) then  C.TUTAR else 0 end - case when CH.ISLEM in(130,141) then C.TUTAR else 0 end),
                C.KUR
        FROM 
                CEKLER C 
                        INNER JOIN CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                        INNER JOIN REHBER R on R.ID=CH.REHBERID
                        INNER JOIN ISLEMTURLERI IT ON IT.TUR = CASE WHEN CH.ISLEM between 130 and 139 and CEKSENET=101 THEN 23 WHEN CH.ISLEM between 130 and 139 and CEKSENET=121 then 24  END 

        WHERE 
                CH.ISLEM in(130,131,132,133,134,135,137,138,140,141) 
                AND CH.TARIH BETWEEN ''$BasTar$ 23:59'' AND ''$BitTar$ 23:59''
) AS X
PIVOT
(
        SUM(BAKIYE) FOR AD IN (POS ile Tahsilat,Banka Tahsilat,Çekle Tahsilat,Senetle Tahsilat,Nakit Tahsilat)
)AS PVT

SELECT
        Satıcı,
        Para Birimi,
        SUM(POS ile Tahsilat) AS POS ile Tahsilat,
        SUM(Banka Tahsilat) AS Banka Tahsilat,
        SUM(Çekle Tahsilat) AS Çekle Tahsilat,
        SUM(Senetle Tahsilat) AS Senetle Tahsilat,
        SUM(Nakit Tahsilat) AS Nakit Tahsilat, 
        SUM(Toplam Tahsilat) AS Toplam Tahsilat
FROM(
        SELECT 
                 R.KOD AS Kod,
                 R.FIRMA AS Cari,
                 GN.ANAHTAR AS Bölge,
                 RBI.BILGI AS İl,
                 RT.FIRMA AS Satıcı,
                 KUR as Para Birimi,
                 POS ile Tahsilat,
                 Banka Tahsilat,
                 Çekle Tahsilat,
                 Senetle Tahsilat,
                 Nakit Tahsilat,
                 Toplam Tahsilat
        FROM 
                gt_tmpTahsilat X
                        INNER JOIN REHBER R on X.REHBERID=R.ID
                        LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
                        LEFT JOIN REHBERILETISIM RI ON RI.REHBERID = R.ID AND RI.VARSAYILAN = 1
                        LEFT JOIN REHBERBILGI RBI ON RBI.YER_ID =  RI.ID AND RBI.ETIKET = ''İl''
                        LEFT JOIN GENINI GN ON GN.BOLUM = -2210 AND GN.DEGER = R.BOLGE
                        LEFT JOIN GENINI GT ON GT.BOLUM = -2207 AND GT.DEGER = R.TEMAS
) AS X
WHERE
        X.Cari <> ''-''
GROUP BY
        Satıcı,
        Para Birimi
' WHERE id = 1435;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$TEMSILCI$'' VARCHAR(100)




IF OBJECT_ID(''tempdb..gt_temp_cari_ekstre_liste'') IS NOT NULL
    DROP TABLE gt_temp_cari_ekstre_liste

CREATE TABLE gt_temp_cari_ekstre_liste (
           SIRANO int IDENTITY(1,1) NOT NULL,
       CEKID int NULL,
       TARIH datetime NULL,
       AKSIYONTARIH datetime NULL,
       NO varchar(20) NULL,
       TUR smallint NULL,
       BASLIK varchar(250) NULL,
       TURAD varchar(50) NULL,
       REHBERID int NULL,
       KOD varchar(20) NULL,
       AD varchar(150) NULL,
       ACIKLAMA varchar(500) NULL,
       HESAPID int NULL,
       HESAPKODU varchar(100) NULL,
       HESAPADI varchar(250) NULL,
       DURUM smallint NULL,
       BORC money NULL,
       ALACAK money NULL,
       KUR varchar(6) NULL,
       YERELKUR money NULL,
       MASRAFID int NULL,
       MASRAFKOD varchar(50) NULL,
       MASRAFAD varchar(200) NULL,
       BORCBAKIYE money NULL,
       ALACAKBAKIYE money NULL,
       YERELTUTAR money NULL,
       YERELBAKIYE money NULL,
       SUBEID int NULL ,
       VADETARIHI datetime NULL,
       ADET float NULL,
       BIRIM varchar(30) NULL,
       BIRIMFIYAT money NULL
)



        CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59'' DATETIME,
        0 INT,
        0 INT,
        @RehberID INT






SELECT R.ID, R.KOD, R.FIRMA, ADSOYAD=P.FIRMA, FATBASLIK=X1.BILGI, R.GRUP, R.TEMAS, R.SEKTOR, R.KATEGORI, R.SINIF, R.DURUM, R.OZELKOD, TEMSILCIAD=R2.FIRMA  ,TOPLAM_BORC,TOPLAM_ALACAK,KUR,BAKIYE=TOPLAM_BORC-TOPLAM_ALACAK, TAKIPTE INTO gt_TEMP_CARI_BAKIYE_LISTE
 FROM(
    select
                REHBERID,TOPLAM_BORC= SUM(coalesce(BORC,0)), TOPLAM_ALACAK= SUM(coalesce(ALACAK,0)),TAKIPTE = SUM(coalesce(TAKIPTE,0)),KUR=coalesce(KUR,''TL'')
        from (
           SELECT
                REHBERID,
                SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS BORC,
                0 AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR,
        TAKIPTE = 0
                --KUR = case when EKSTREDEKULLAN=1 then DOVIZ_CINSI else KUR end,
                FROM FATBASLIK F
                WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (15,16,17)) AND FATURATARIH BETWEEN cast(Year(now()) as varchar)+''-01-01 00:00:00'' AND CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59''
                GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

        UNION ALL

                SELECT REHBERID,
                0 AS BORC,
                SUM(CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_TUTARI ELSE F.FATURA_TUTARI END) AS FATURA_ALACAK, -- alınan fatura BORCA YAZ
                CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end as KUR,
                TAKIPTE = 0
                FROM FATBASLIK F
                WHERE  coalesce(F.DURUM,0)<>6 and (F.TUR in (8,11,12,13)) AND FATURATARIH BETWEEN cast(Year(now()) as varchar)+''-01-01 00:00:00'' AND CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59''
                GROUP BY F.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_CINSI else KUR end

        UNION ALL

                SELECT REHBERID,
                SUM(case when coalesce(K.BORC,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.BORC end) AS  BORC,
                SUM(case when coalesce(K.ALACAK,0)>0 and EKSTREDEKULLAN=1 then K.DOVIZ_TUTARI else K.ALACAK end) AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1  THEN DOVIZ_KURU else KUR end as KUR,
                TAKIPTE = 0
                FROM KASA K
                WHERE TUR not between 60 and 79  AND ISLEMTARIHI BETWEEN cast(Year(now()) as varchar)+''-01-01 00:00:00'' AND CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59''
                GROUP BY K.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN DOVIZ_KURU else KUR end

        UNION ALL
                SELECT CH.REHBERID,
                 BORC  = sum(Case when CH.ISLEM in(140,131,132,133,134,137) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0 end),
                ALACAK= sum(Case when CH.ISLEM in(130,141) then (case when CH.EKSTREDEKULLAN=1 then CH.TUTAR else coalesce(C.TUTAR,0)end) else 0 end),
                 KUR   = case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'')end,
        TAKIPTE = 0
                FROM CEKLER C inner join CEKHAREKET CH on C.ID=CH.CEKSENETLERID
                WHERE CH.ISLEM in(130,131,132,134,137,140,141) and CH.TARIH BETWEEN cast(Year(now()) as varchar)+''-01-01 00:00:00'' AND CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59''
                GROUP BY CH.REHBERID,CH.ISLEM,CH.EKSTREDEKULLAN,case when CH.EKSTREDEKULLAN=1 then CH.KUR else coalesce(C.KUR,''TL'')end

        UNION ALL

                SELECT REHBERID,
                0 AS BORC,
                SUM(CASE WHEN EKSTREDEKULLAN=1 THEN S.DOVIZ_TUTARI ELSE TUTAR END) AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1 THEN S.DOVIZ_KURU else KUR end as KUR,
                TAKIPTE = 0
                FROM SENETLER S
                WHERE TUR = 24   AND TARIH BETWEEN cast(Year(now()) as varchar)+''-01-01 00:00:00'' AND CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59''
                GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN S.DOVIZ_KURU else KUR END

        UNION ALL

                SELECT REHBERID,SUM(CASE WHEN EKSTREDEKULLAN=1 THEN S.DOVIZ_TUTARI ELSE TUTAR END) AS
                BORC,0 AS ALACAK,
                CASE WHEN EKSTREDEKULLAN=1 THEN S.DOVIZ_KURU else KUR end as KUR,
                TAKIPTE = 0
                FROM SENETLER S
                WHERE TUR = 34  AND TARIH BETWEEN cast(Year(now()) as varchar)+''-01-01 00:00:00'' AND CAST(to_char(now(),''YYYY-MM-DD HH24:MI:SS'') AS DATETIME) + '' 23:59:59''
                GROUP BY S.REHBERID,CASE WHEN EKSTREDEKULLAN=1 THEN S.DOVIZ_KURU else KUR end

                ) as asd
        group by REHBERID,KUR) AS DSA
 INNER JOIN REHBER R ON         DSA.REHBERID=R.ID
LEFT OUTER JOIN         REHBER P on R.ID = P.BAGID and
                ( 1 = CASE WHEN  0 = 1 THEN 1
                                   WHEN  0 = 0 AND isnull (P.STATU,1) = 1 THEN 1 ELSE 0
                                   END  )

 left outer join REHBER R2 on R2.ID=R.TEMSILCI  left outer join (Select R1.ID,RB.BILGI from REHBER R1 left outer join REHBERILETISIM RI on R1.ID=RI.REHBERID and RI.VARSAYILAN=1 Left outer join REHBERBILGI RB on RB.YER_ID=RI.ID  left outer join REHBERAYAR RA on RA.SIRA=RB.SIRA AND RA.YERI=1 Where RI.VARSAYILAN=1 and RB.YERI=1 and RA.VARSAYILAN=8) X on X.ID=R.ID   LEFT OUTER JOIN (SELECT YER_ID,RB.BILGI FROM REHBERBILGI RB INNER JOIN REHBERAYAR RA ON RA.YERI = 2 AND RA.SIRA = RB.SIRA AND RA.YERI = RB.YERI AND RA.VARSAYILAN = 10) X1 ON X1.YER_ID = R.ID         where R.GRUP<>334 and R.GRUP<>335 and R.ID > 1 
 and R.GRUP<>334 and R.GRUP<>335  and R.GRUP > 1  and R.DURUM> 0 
ORDER BY KUR 

SELECT DISTINCT ID AS REHBERID FROM gt_TEMP_CARI_BAKIYE_LISTE

OPEN cari_cursor
FETCH NEXT FROM cari_cursor INTO @RehberID

WHILE @@FETCH_STATUS = 0
BEGIN
    INSERT INTO gt_temp_cari_ekstre_liste (
        CEKID, TARIH, AKSIYONTARIH, NO, TUR, BASLIK, TURAD,
        REHBERID, KOD, AD, ACIKLAMA, HESAPID, HESAPKODU, HESAPADI,
        DURUM, BORC, ALACAK, KUR, YERELKUR, MASRAFID, MASRAFKOD,
        MASRAFAD, BORCBAKIYE, ALACAKBAKIYE, YERELTUTAR, YERELBAKIYE,
        SUBEID, VADETARIHI, ADET, BIRIM, BIRIMFIYAT
    )
    SELECT 
        CEKID, TARIH, AKSIYONTARIH, NO, TUR, BASLIK, TURAD,
        REHBERID, KOD, AD, ACIKLAMA, HESAPID, HESAPKODU, HESAPADI,
        DURUM, BORC, ALACAK, KUR, YERELKUR, MASRAFID, MASRAFKOD,
        MASRAFAD, BORCBAKIYE, ALACAKBAKIYE, YERELTUTAR, YERELBAKIYE,
        SUBEID, VADETARIHI, ADET, BIRIM, BIRIMFIYAT
    FROM fn_Cari_Ekstre(@RehberID, ''2000-01-01 00:00'', ''$BITTAR$'', 0)

    FETCH NEXT FROM cari_cursor INTO @RehberID
END

CLOSE cari_cursor
DEALLOCATE cari_cursor

SELECT
        TURAD AS Tür,
        DURUM AS Durum,
        FIRMA AS Cari Ünvanı,
        SERINO AS Seri No,
        TARIH AS Tarih,
        VADE AS Vade,
        TUTAR AS Tutar,
        KUR AS P.Birimi,
        BORCBAKIYE AS Açık Hesap Borç Bakiye,
        CASE WHEN SIRA = 1 THEN ALACAKBAKIYE ELSE LAG(CASE WHEN TUTAR + Takipte Kalan Bakiye > 0 THEN 0 ELSE Takipte Kalan Bakiye END) OVER(PARTITION BY FIRMA,KUR ORDER BY FIRMA,KUR,VADE) END AS Alacak Bakiye,
        TALACAKBAKIYE AS Toplam Alacak Bakiye,
        Takipte Kalan Bakiye,
        (SELECT SUM(T.BORC -T.ALACAK) FROM gt_temp_cari_ekstre_liste T WHERE T.REHBERID = XXX.REHBERID AND T.KUR = ''DTL'') AS DTLBAKIYE,
        TEMSILCI AS Temsilci
FROM(
        SELECT
            REHBERID,
                SIRA,
                TURAD,
                DURUM,
                FIRMA,
                SERINO,
                TARIH,
                VADE,
                TUTAR,
                KUR,
                BORCBAKIYE,
                ALACAKBAKIYE,
                SUM(TUTAR-ALACAKBAKIYE) OVER(PARTITION BY FIRMA,KUR ORDER BY FIRMA,KUR,VADE) AS Takipte Kalan Bakiye,
                TALACAKBAKIYE,
                TEMSILCI
        FROM(
                SELECT
                    REHBERID,
                        SIRA,
                        TURAD,
                        DURUM,
                        FIRMA,
                        SERINO,
                        TARIH,
                        VADE,
                        TUTAR,
                        KUR,
                        BORCBAKIYE,
                        CASE WHEN SIRA = 1 THEN ALACAKBAKIYE ELSE CASE WHEN FIRST_VALUE (TUTAR -ALACAKBAKIYE) OVER (PARTITION BY FIRMA,KUR  ORDER BY FIRMA,KUR,VADE) >0 THEN 0 ELSE 0 END END AS ALACAKBAKIYE,
                        TALACAKBAKIYE,
                        --SUM(TUTAR-ALACAKBAKIYE) OVER(PARTITION BY FIRMA,KUR ORDER BY FIRMA,KUR,VADE) AS Takipte Kalan Bakiye,
                        TEMSILCI
                FROM(
                        SELECT
                                ROW_NUMBER() OVER(PARTITION BY R.FIRMA,CASE WHEN C1.EKSTREDEKULLAN=1 then C1.DOVIZ_KURU else coalesce(C1.KUR,''TL'') END ORDER BY R.FIRMA,CASE WHEN C1.EKSTREDEKULLAN=1 then C1.DOVIZ_KURU else coalesce(C1.KUR,''TL'') END,VADE) AS SIRA,
                                TURAD=(SELECT ANAHTAR FROM GENINI WHERE BOLUM = -1005 and DEGER=(CASE WHEN C1.TUR BETWEEN 130 AND 139 AND CEKSENET=101 THEN 23 WHEN C1.TUR BETWEEN 130 AND 139 AND CEKSENET = 121 THEN 24 
                                ELSE 0 END) AND DIL=-1 LIMIT 1 ),
                                DURUM = IT.AD,
                                R.ID AS REHBERID,
                                R.FIRMA,
                                C1.SERINO,
                                C1.TARIH,
                                C1.VADE,
                                TUTAR = CASE WHEN C1.EKSTREDEKULLAN=1 then C1.DOVIZ_TUTARI else coalesce(C1.TUTAR,0) END,
                                KUR = CASE WHEN C1.EKSTREDEKULLAN=1 then C1.DOVIZ_KURU else coalesce(C1.KUR,''TL'') END,
                                BORCBAKIYE = CASE WHEN T.TOPLAM_BORC - T.TOPLAM_ALACAK >= 0 THEN T.TOPLAM_BORC - T.TOPLAM_ALACAK ELSE 0 END,
                                ALACAKBAKIYE = ABS(CASE WHEN T.TOPLAM_BORC - T.TOPLAM_ALACAK < 0 THEN T.TOPLAM_BORC - T.TOPLAM_ALACAK ELSE 0 END),
                                TALACAKBAKIYE = ABS(CASE WHEN T.TOPLAM_BORC - T.TOPLAM_ALACAK < 0 THEN T.TOPLAM_BORC - T.TOPLAM_ALACAK ELSE 0 END),
                                KALANBAKIYE = 0,
                                TEMSILCI = RT.FIRMA
                        FROM  
                                CEKLER C1
                                        INNER JOIN ISLEMTURLERI IT ON IT.TUR = C1.TUR
                                        INNER JOIN REHBER R ON R.ID = C1.REHBERID
                                        LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
                                        LEFT JOIN gt_TEMP_CARI_BAKIYE_LISTE T ON T.FIRMA = R.FIRMA AND T.KUR = CASE WHEN C1.EKSTREDEKULLAN=1 then C1.DOVIZ_KURU else coalesce(C1.KUR,''TL'') END
                        WHERE 
                                C1.CEKSENET IN (101,121) 
                                AND C1.TUR IN (130,131,132,133,134,135,138)
                                AND C1.VADE <= ''$BITTAR$''
                                AND coalesce(RT.FIRMA,'''') LIKE ''$TEMSILCI$''+''%''
                                AND EXISTS(SELECT * FROM CEKHAREKET CH WHERE CH.CEKSENETLERID = C1.ID)
                ) AS X
        ) AS XX
) AS XXX
UNION ALL
SELECT 
        '' Diğer'' AS Tür,
        TURAD  AS Durum,
        T.AD  AS Cari Ünvanı,
        T.NO AS Seri No,
        TARIH AS Tarih,
        T.AKSIYONTARIH AS Vade,
        T.BORC -T.ALACAK AS Tutar,
        T.KUR  AS P.Birimi,
        T.BORCBAKIYE AS Açık Hesap Borç Bakiye,
        T.ALACAKBAKIYE AS Alacak Bakiye,
        T.ALACAKBAKIYE AS Toplam Alacak Bakiye,
        0 AS Takipte Kalan Bakiye,
        0 AS DTLBAKIYE,
        RT.FIRMA AS Temsilci
FROM 
        gt_temp_cari_ekstre_liste T
                INNER JOIN REHBER R ON R.ID = T.REHBERID
                LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI 
WHERE 
        T.KUR = ''DTL''
        AND coalesce(RT.FIRMA,'''') LIKE ''$TEMSILCI$''+''%''
ORDER BY 
        Cari Ünvanı,P.Birimi DESC,VADE

