CREATE TABLE gt_TEMP_EKSTRE_TOPLU(
        X varchar(100),
        CEKSENET INT,
        SIRANO INT,
        CEKID INT,
        TARIH DATETIME,
        AKSIYONTARIH DATETIME,
        NO varchar(100),
        TUR varchar(100),
        BASLIK varchar(100),
        TURAD varchar(100),
        REHBERID INT,
        KOD varchar(100),
        AD varchar(100),
        ACIKLAMA varchar(100),
        HESAPID INT,
        HESAPKODU varchar(100),
        HESAPADI varchar(100),
        DURUM varchar(100),
        BORC MONEY,  
        ALACAK MONEY,
        KUR varchar(100),
        YERELKUR varchar(100),
        MASRAFID INT,
        MASRAFKOD varchar(100),
        MASRAFAD varchar(100),
        BORCBAKIYE MONEY,
        ALACAKBAKIYE MONEY,
        YERELTUTAR MONEY,
        YERELBAKIYE MONEY,
        SUBEID INT,
        VADETARIHI DATETIME,
        ADET FLOAT,
        BIRIM INT,
        BIRIMFIYAT MONEY,
        SERINO varchar(100),
        BANKAADI varchar(100),
        BASKASININ varchar(100), 
        BORCLU varchar(100)
)


SELECT R.ID FROM REHBER R LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI WHERE R.KOD LIKE ''$KOD$''+''%'' AND R.FIRMA LIKE ''$FIRMA$''+''%'' AND RT.FIRMA LIKE ''$TEMSILCI$''+''%''

OPEN ekstre_cursor;

FETCH NEXT FROM ekstre_cursor INTO @ID

WHILE @@FETCH_STATUS = 0
BEGIN
        INSERT INTO gt_TEMP_EKSTRE_TOPLU
        SELECT
                X = ''1'',CEKSENET = '''',SIRANO,CEKID,TARIH,AKSIYONTARIH,NO,TUR,BASLIK,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPID,HESAPKODU,HESAPADI,DURUM,BORC,  ALACAK,KUR,YERELKUR,MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,ABS(YERELTUTAR) AS YERELTUTAR,YERELBAKIYE,SUBEID,VADETARIHI,ADET,BIRIM,BIRIMFIYAT,SERINO = '''',BANKAADI = '''',BASKASININ = '''', BORCLU = ''''
        FROM 
                fn_Cari_Ekstre( @ID, ''$BASTAR$ 00:00'', ''$BITTAR$ 23:59'',0) C1
        UNION ALL
        SELECT
                X = ''2'',C2.CEKSENET,SIRANO,CEKID,C1.TARIH,AKSIYONTARIH,NO,C1.TUR,BASLIK,TURAD,C1.REHBERID,C1.KOD,AD,C1.ACIKLAMA,C1.HESAPID,HESAPKODU,HESAPADI,C1.DURUM,BORC,  ALACAK,C1.KUR,YERELKUR,C1.MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,ABS(YERELTUTAR) AS YERELTUTAR,YERELBAKIYE,C1.SUBEID,VADETARIHI,ADET,BIRIM,BIRIMFIYAT,SERINO,B2.BANKAADI,BASKASININ =CASE WHEN C2.BASKASININ = 0 THEN ''Hayır'' ELSE ''Evet'' END,C2.BORCLU  
        FROM 
                fn_Cari_Ekstre( @ID, ''2010-01-01 00:00'', ''$BITTAR$ 23:59'',0) C1  
                        INNER JOIN CEKLER C2 ON C1.CEKID = C2.ID
                        LEFT JOIN BANKASUBELER B1 ON B1.ID = C2.BANKASUBELERID
                        LEFT JOIN BANKALAR B2 ON B2.BANKAKODU = B1.BANKAKODU
        WHERE 
                TURAD = ''Senetle Tahsilat'' 
                AND C2.CEKSENET = 121
                AND C2.TUR IN (130,131,132,133,134,135,138)
        UNION ALL
        SELECT
                X = ''3'',C2.CEKSENET,SIRANO,CEKID,C1.TARIH,AKSIYONTARIH,NO,C1.TUR,BASLIK,TURAD,C1.REHBERID,C1.KOD,AD,C1.ACIKLAMA,C1.HESAPID,HESAPKODU,HESAPADI,C1.DURUM,BORC,  ALACAK,C1.KUR,YERELKUR,C1.MASRAFID,MASRAFKOD,MASRAFAD,BORCBAKIYE,ALACAKBAKIYE,ABS(YERELTUTAR) AS YERELTUTAR,YERELBAKIYE,C1.SUBEID,VADETARIHI,ADET,BIRIM,BIRIMFIYAT,SERINO,B2.BANKAADI,BASKASININ =CASE WHEN C2.BASKASININ = 0 THEN ''Hayır'' ELSE ''Evet'' END,C2.BORCLU                      
        FROM 
                fn_Cari_Ekstre( @ID, ''2010-01-01 00:00'', ''$BITTAR$ 23:59'',0) C1  
                        INNER JOIN CEKLER C2 ON C1.CEKID = C2.ID
                        LEFT JOIN BANKASUBELER B1 ON B1.ID = C2.BANKASUBELERID
                        LEFT JOIN BANKALAR B2 ON B2.BANKAKODU = B1.BANKAKODU
        WHERE 
                TURAD = ''Çekle Tahsilat'' 
                AND C2.CEKSENET = 101
                AND C2.TUR IN (130,131,132,133,134,135,138)

        FETCH NEXT FROM ekstre_cursor INTO @ID
END

CLOSE ekstre_cursor
DEALLOCATE ekstre_cursor

SELECT XX = KOD +''-''+X+''-''+KUR,SIRANO,CEKID,TARIH,AKSIYONTARIH,NO,TUR,TURAD,REHBERID,KOD,AD,ACIKLAMA,HESAPKODU,HESAPADI,BORC,ALACAK,KUR,BORCBAKIYE,ALACAKBAKIYE,X,SERINO,BANKAADI,BASKASININ,BORCLU FROM gt_TEMP_EKSTRE_TOPLU WHERE REHBERID <> 0 ORDER BY KOD,X,KUR,TARIH

DROP TABLE gt_TEMP_EKSTRE_TOPLU
' WHERE id = 1437;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
                CASE WHEN FB.TUR = 15 THEN ''Satış'' WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN ''İade'' ELSE '''' END AS Tür,
                FB.FATURATARIH AS Tarih,
                FB.FATURANO AS Belge Numarası,
                R.FIRMA AS Cari Ünvan,
                S.OZELKOD AS Üretici,
        CASE WHEN F.TUR = 0 THEN ''Hizmet'' ELSE ''Malzeme'' END AS Stok/Hizmet,
                coalesce(S.KOD,MG.KOD) AS Kod,
                coalesce(S.STOKADI,MG.AD) AS Stok/Hizmet Adı,
                CASE 
                        WHEN F.TUR IN (1,11) THEN
                        coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                        ELSE 
                        coalesce(((SELECT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')
                END AS KATEGORIADI,
                CASE 
                        WHEN F.TUR IN (1,11) THEN
                        coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                        ELSE 
                        ''Grupsuz''
                END AS GRUPADI,          
                F.MIKTAR,
                BR.ANAHTAR AS BIRIM,
                GB.ANAHTAR AS Bölge,
                RB.BILGI AS İl,
                RS.FIRMA AS Personel,
                coalesce(GN.ANAHTAR,'''') AS İlk Temas,
                FB.VADE AS VADE,                
                CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.BIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.BIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS FATURA_MALIYETI_ORT,
                CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS FATURA_MALIYETI_ORT_USD,
                CAST(CASE WHEN FB.TUR = 15 THEN F.TUTAR WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.TUTAR *-1 END AS FLOAT) AS TL TUTAR (KDV HARİÇ),
                CAST(coalesce(CASE WHEN FB.TUR = 15 THEN F.KDVDAHILFIYAT WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.KDVDAHILFIYAT *-1 END,0) AS FLOAT) AS TL TUTAR (KDVDAHİL),
                CAST(CASE WHEN FB.TUR = 15 THEN F.TUTAR WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.TUTAR *-1 END AS FLOAT)-CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.BIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.BIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS (KDV HARİÇ) KAR TL,
                CAST(coalesce(CASE WHEN FB.TUR = 15 THEN F.KDVDAHILFIYAT WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.KDVDAHILFIYAT *-1 END,0) AS FLOAT) - CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.BIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.BIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2))AS ( KDV DAHİL) KAR TL,
                CAST(CASE 
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN F.TUTAR/D.SATIS
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (F.TUTAR*-1)/D.SATIS
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR*-1
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI*-1 
                END AS decimal(15,4)) AS USD TUTAR (KDV HARİÇ),
                CAST(CASE 
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN KDVDAHILFIYAT/D.SATIS
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN KDVDAHILFIYAT/FB.DOVIZKUR 
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100) 
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (KDVDAHILFIYAT*-1)/D.SATIS
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN (KDVDAHILFIYAT/FB.DOVIZKUR)*-1 
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN (F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100))*-1 
                END AS decimal(15,4)) AS USD TUTAR (KDV DAHİL),
                CAST(CASE 
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN F.TUTAR/D.SATIS
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (F.TUTAR*-1)/D.SATIS
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR*-1
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI*-1 
                END AS decimal(15,4))-CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS (KDV HARİÇ) KAR USD,
                CAST(CASE 
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN KDVDAHILFIYAT/D.SATIS
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN KDVDAHILFIYAT/FB.DOVIZKUR 
                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100) 
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (KDVDAHILFIYAT*-1)/D.SATIS
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN (KDVDAHILFIYAT/FB.DOVIZKUR)*-1 
                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN (F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100))*-1 
                END AS decimal(15,4))-CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2))  AS (KDV DAHİL) KAR USD,
                CAST(CASE WHEN DOVIZKUR = 1 THEN D.SATIS ELSE DOVIZKUR END AS decimal(15,4)) AS Döviz Kuru
from
        FATBASLIK FB  
        INNER JOIN FATURA F ON F.FATBASID = FB.ID 
        LEFT JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
        --LEFT JOIN GENINI GM ON GM.BOLUM = -2701 AND GM.DEGER = S.MARKA
        INNER JOIN REHBER R on R.ID = FB.REHBERID
        LEFT JOIN REHBERILETISIM RI ON RI.REHBERID = R.ID AND ((coalesce( FB.REHBERILETID,0) = 0 AND RI.VARSAYILAN = 1) OR ( RI.ID = FB.REHBERILETID))
        LEFT JOIN REHBERBILGI RB ON RB.YER_ID = RI.ID AND RB.YERI = 1 AND RB.ETIKET = ''İl''
        LEFT JOIN REHBER RS ON RS.ID = FB.SATICIKODU
        LEFT JOIN MASRAFGELIR MG ON MG.ID = F.URUNID AND F.TUR = 0
        LEFT OUTER JOIN REHBER SATICIBILGI ON FB.SATICIKODU = SATICIBILGI.ID
        INNER JOIN ISLEMTURLERI IT ON IT.TUR = FB.TUR AND IT.TIP = FB.TIPI
        LEFT JOIN GENINI GN ON GN.BOLUM = -2207 AND GN.DEGER = R.TEMAS
        LEFT JOIN GENINI GB ON GB.BOLUM = -2210 AND GB.DEGER = R.BOLGE
        LEFT JOIN GENINI BR ON BR.BOLUM = -2702 AND BR.DEGER = F.BIRIM 
        LEFT JOIN STOK_ORT_MALIYET SOM ON SOM.FATBASID = FB.ID AND SOM.FATURAID = F.ID AND SOM.STOKID = F.URUNID AND SOM.DEPOID = CASE WHEN FB.TUR = 15 THEN FB.CIKISDEPO WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN FB.GIRISDEPO END
        LEFT JOIN DOVIZ D ON to_char(D.TARIH,''YYYY-MM-DD HH24:MI:SS'') = to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'') AND D.CINSI = ''$''
WHERE 
        1=1 AND (FB.TUR = 15 OR (FB.TUR = 11 AND FB.TIPI = 2))
        --AND FB.FATURATARIH >= ''2024-08-01 00:00'' and  FATURATARIH <= ''2024-08-30 23:59:59''
        AND FATURATARIH >= ''$BASTAR$ 00:00'' and  FATURATARIH <= ''$BITTAR$ 23:59:59''
        --AND DOVIZKUR = 1
        AND FB.DURUM <> 6
        AND coalesce(R.KarZararDisi,''False'') <> ''True''
   AND coalesce(MG.KOD,'''') <> ''840.01''
   AND R.FIRMA LIKE ''$FIRMA$%''
ORDER BY
        FB.TARIH' WHERE id = 1438;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT     --asas               
        ISLEMTUR,FATURATUR,OZELKOD,ZARF,TIPI,FATURATARIH,month(FATURATARIH) AS BELGE_AY ,FATURANO,CARIKOD,FIRMA,VERGINO,STOK_OZELKOD,KOD,AD,ACIKLAMA,cast(ADET as double precision) AS ADET,coalesce(cast(DONUSEN as double precision),0) AS DONUSEN,cast(ADET as double precision) - coalesce(cast(DONUSEN as double precision),0) AS KALAN, ANAHTAR,
        cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT,
        cast(BIRIMFIYAT*ADET as double precision) AS TUTAR ,          
        ISKONTO,
        cast((BIRIMFIYAT*ADET) as double precision)-TUTAR AS ISKONTOTUTARI ,--ROUND((((BIRIMFIYAT*ADET)/100.0)*ISKONTO),2),
        KDV,
        cast(TUTAR as double precision) AS KDVMATRAHI ,
        cast(KDVLITOPLAM as double precision)-TUTAR AS KDVTUTAR ,
        cast(KDVLITOPLAM as double precision) AS GENELTOPLAM ,
        DOVIZ_CINSI,
           CASE WHEN DOVIZ_CINSI<>''TL'' THEN ROUND(DOVIZ_BIRIMFIYAT,2)
                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12) THEN  ROUND((BIRIMFIYAT/coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)
                                                                                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN ROUND((BIRIMFIYAT/coalesce((SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)
                    
                                                         ELSE 0 END AS DOVIZ_BIRIMFIYAT ,
                         
         CASE WHEN DOVIZ_CINSI<>''TL'' THEN KURU
                                                   WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12)   THEN  (SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp))
                                                                                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN  (SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp))
                                                END AS KURU ,

        
                                           -- CASE WHEN DOVIZ_CINSI<>''TL'' AND KURU>0 THEN ROUND((((BIRIMFIYAT*ADET)-TUTAR)/KURU),2) 
                                           CASE WHEN DOVIZ_CINSI<>''TL'' THEN (BIRIMFIYAT*ADET)-TUTAR
                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12) THEN  ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)
                                                                                                                                          /coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)
                                                                                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN  ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)
                                                                                                                                          /coalesce((SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)
                    
                                                         ELSE 0 END AS DOVIZ_ISKONTOTUTARI ,
        
                                                                                                   CASE WHEN DOVIZ_CINSI<>''TL'' AND KURU>0 THEN (ROUND(BIRIMFIYAT/KURU,2)*ADET)-ROUND((((BIRIMFIYAT*ADET)-TUTAR)/KURU),2) 
                                                                                                                WHEN DOVIZ_CINSI=''TL'' AND TUR IN (11,12) THEN (ROUND(BIRIMFIYAT/(coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)*ADET)-ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)/
                                                                                                                                                                (coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1))
                                                                                                                         WHEN DOVIZ_CINSI=''TL'' AND TUR IN (8,15,16) THEN  (ROUND(BIRIMFIYAT/(coalesce((SELECT coalesce(ALIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)),2)*ADET)-ROUND(((BIRIMFIYAT*ADET)-TUTAR),2)/
                                                                                                                                                coalesce((SELECT coalesce(SATIS,1) FROM DOVIZ D WHERE D.CINSI=''€'' AND D.TARIH=cast((to_char(FATURATARIH,''YYYY-MM-DD HH24:MI:SS'')) as timestamp) ),1)
                                                                                                   ELSE 0 END AS DOVIZ_MATRAHI , 
          DOVIZ_TUTARI + ((DOVIZ_TUTARI*KDV)/100) AS DOVIZ_GENEL_TOPLAM ,                                               
        MASRAFKODU,
        TOPLAM_MALİYET/ADET AS BIRIM_MALIYET ,
        TOPLAM_MALİYET,
        (TUTAR-TOPLAM_MALİYET)/ADET AS BIRIM_KARLILIK ,
        TUTAR-TOPLAM_MALİYET AS TOPLAM_KARLILIK ,
        MASRAFADI,KATEGORIADI,GRUPADI,KDVDURUM,OZELKOD_ ,YETKIKODU_,ALICI_SATICI(BÜTÜN),ALICI_SATICI(SATIR),PROJEADI,PROJEKODU,SUBE,SONALIS_TL,
        MARKA,MODEL,ILCE,IL,PERSONEL,ACIKLAMA1,ACIKLAMA2,EAD,SERINO,FATURASERI,F_OZELKOD,F_OZELKOD2 ,
        Alım_İndirimleri, Alım_İadeler, Alım_Hesabı,Satışlar_Hesabı,  Satış_İadeler,  Satış_İndirimler, HEDEF
FROM(
        SELECT 
                FB.OZELKOD,
                BZ.AD AS ZARF ,FB.TUR,
                 CASE WHEN FB.TIPI=1 THEN ''Alış/Satış'' WHEN FB.TIPI=2 THEN ''İade'' WHEN FB.TIPI=3 THEN ''Fiyat Farkı'' WHEN FB.TIPI=4 THEN ''S.Mes.Mak.'' END AS TIPI ,
                RI1.ANAHTAR AS FATURATUR,
                FB.FATURATARIH,FB.FATURANO,R.KOD AS CARIKOD,R.FIRMA,
                 CASE WHEN F.TUR IN (1,11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR ,
                (SELECT OZELKOD FROM STOKLAR S where  F.URUNID=S.ID  )   AS STOK_OZELKOD , 
                 CASE WHEN F.TUR IN (1,11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID= F.URUNID ) END AS KOD ,
                 CASE WHEN F.TUR IN (1,11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID ) ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) END AS AD ,
                F.ACIKLAMA,
                F.ADET,
                 CASE WHEN FB.TUR = 11 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) END AS DONUSEN ,
                RI.ANAHTAR,
                 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT/(1+(F.KDV/100.0)) END AS BIRIMFIYAT ,
                 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR ELSE F.TUTAR/(1+(F.KDV/100.0)) END AS TUTAR ,
                 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.TUTAR*(1+(F.KDV/100.0)) ELSE F.TUTAR END AS KDVLITOPLAM ,
                F.ISKONTO,F.KDV,
                FB.RAPORDOVIZ AS DOVIZ_CINSI , --F.DOVIZ_TUTARI,
                 CASE WHEN FB.KDVDURUM=''Hariç'' THEN F.DOVIZ_TUTARI ELSE F.DOVIZ_TUTARI/(1+(F.KDV/100.0)) END AS DOVIZ_TUTARI ,
                CASE WHEN FB.RAPORDOVIZ <> ''TL'' THEN F.DOVIZ_BIRIMFIYAT ELSE 0 END AS DOVIZ_BIRIMFIYAT ,
                CASE WHEN FB.RAPORDOVIZ<>''TL'' AND F.DOVIZ_TUTARI>0 THEN ROUND(cast((F.TUTAR/F.ADET)/(F.DOVIZ_TUTARI/F.ADET) as double precision),4) ELSE 0 END  AS KURU ,MG.KOD AS MASRAFKODU,MG.AD AS MASRAFADI,
                 CASE WHEN F.TUR IN (1,11) THEN
                                                                        coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                                                                        ELSE 
                                                                        coalesce(((SELECT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')

                                                                        END AS KATEGORIADI ,
                 CASE WHEN F.TUR IN (1,11) THEN
                                                                        coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                                                                        ELSE 
                                                                                          ''Grupsuz''

                                                                        END   AS GRUPADI ,
                FB.KDVDURUM ,
                (SELECT OZELKOD FROM MASRAFGELIR S where  F.URUNID=S.ID  )   AS OZELKOD_ ,
                (SELECT YETKIKODU FROM MASRAFGELIR S where  F.URUNID=S.ID  ) AS YETKIKODU_ ,
                ALICI_SATICI(BÜTÜN)=(SELECT FIRMA FROM REHBER WHERE FB.SATICIKODU=REHBER.ID) ,
                ALICI_SATICI(SATIR)=(SELECT FIRMA FROM REHBER WHERE F.SATICIKODU=REHBER.ID) ,
                P.PROJEADI,P.PROJEKODU,
                (SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID=FB.SUBEID) AS SUBE ,
                (SELECT FIYAT FROM STOKFIYAT SF INNER JOIN STOKLAR S ON F.URUNID=SF.STOKID AND SF.FIYATADI=-1 AND F.TUR=1 LIMIT 1 ) AS SONALIS_TL ,
                (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA AND F.TUR=1) AS MARKA ,
                 (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL  AND G.DIL = -1 AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer) AND F.TUR=1)   AS MODEL ,
                coalesce(ROUND(F.MIKTAR*coalesce((SELECT BIRIMMALIYET FROM STOK_ORT_MALIYET SOM WHERE SOM.TARIH <= FB.FATURATARIH AND MIKTAR > 0 AND SOM.STOKID = F.URUNID AND SOM.DEPOID = CASE WHEN FB.TUR IN (11,12) THEN FB.GIRISDEPO WHEN FB.TUR IN (14,15,16) THEN FB.CIKISDEPO END  ORDER BY SOM.TARIH DESC  LIMIT 1 ) ,0.0),2),0.0) as TOPLAM_MALİYET,(SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=2 and RA.SIRA=RB.SIRA 
                AND RA.YERI=RB.YERI WHERE RB.YER_ID=R.ID AND RA.VARSAYILAN=22 LIMIT 1 )  AS VERGINO ,
                (SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=6 LIMIT 1 ) AS ILCE ,
                (SELECT BILGI FROM REHBERBILGI RB    INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI    INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL ,
                (SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU=R1.ID) AS PERSONEL ,FB.ACIKLAMA AS ACIKLAMA1 ,FB.ACIKLAMA2,E.AD AS EAD ,ER.SERINO,FB.FATURASERI,
                F.OZELKOD AS F_OZELKOD ,F.OZELKOD2 AS F_OZELKOD2 ,
                Alım_İndirimleri=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=-3),
                Alım_İadeler=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=-2),
                Alım_Hesabı=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=-1),
                Satışlar_Hesabı=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=1),
                Satış_İadeler=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=2),
                Satış_İndirimler=(SELECT HP.HESAPKODU FROM HESAPPLANI HP INNER JOIN MUHASEBEKOD MK ON MK.HESAPID=HP.ID WHERE F.URUNID=MK.YER_ID AND F.TUR=1 AND MK.MUHASEBEID=3),
                 case    
                                                when (FB.TUR=10)and(408 in (select F.YERI from FATURA F where F.YERID in (select F.ID from FATURA F where F.FATBASID=FB.ID))) then ''Faturaya'' 
                                                when (FB.TUR=14)and(411 in (select YERI from FATURA where YERID in (select ID from FATURA F where F.FATBASID=FB.ID))) then ''Faturaya''      
                                                when (FB.TUR=109)and(461 in (select YERI from FATURA where YERID in (select ID from FATURA F where F.FATBASID=FB.ID))) then ''Faturaya''      
                                                when (FB.TUR=119)and(462 in (select YERI from FATURA where YERID in (select ID from FATURA F where F.FATBASID=FB.ID))) then ''Faturaya''      
                                                when (FB.TUR=119)and(468 in (select YERI from FATURA where YERID in (select ID from FATURA F where F.FATBASID=FB.ID))) then ''İrsaliyeye''      
                                                else '''' 
                                          end
         AS HEDEF FROM 

                FATBASLIK FB 
                                INNER JOIN FATURA F ON FB.ID=F.FATBASID      
                                LEFT OUTER JOIN REHBER R ON FB.REHBERID=R.ID
                                LEFT OUTER JOIN MASRAFGELIR MG ON F.MASRAFID=MG.ID-- AND
                                LEFT OUTER JOIN REHBERINI RI ON RI.BOLUM=''StokKart_Anabirim'' and RI.DEGER=F.BIRIM
                                LEFT OUTER JOIN REHBERINI RI1 ON RI1.BOLUM=''Kasa Türleri'' and RI1.DEGER=FB.TUR
                                LEFT JOIN BELGEZARFI BZ ON FB.ZARFID=BZ.ID
                                LEFT OUTER JOIN PROJELER P ON P.ID=F.PROJEID
                                LEFT OUTER JOIN STOKLAR S ON S.ID=F.URUNID  
                                LEFT OUTER JOIN EKIPMANREHBER ER ON ER.ID=F.EKIPMANID
                                LEFT OUTER JOIN EKIPMANLAR E ON E.ID=ER.EKIPMANID
        WHERE
                FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59'' 
                and FB.TUR IN (10,14)
                AND ADET <> 0.0
) AS X
WHERE
     FIRMA LIKE ''$FIRMA$%''
ORDER BY 
        FATURATUR,GRUPADI,KATEGORIADI,FATURATARIH,ISLEMTUR' WHERE id = 1439;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
        Personel,
        ''$'' AS Para Birimi,
        CAST(SUM(Satış) as decimal(18,2)) AS Satış,
        CAST(SUM(İade)as decimal(18,2)) AS İade,
        CAST(SUM(Satış) - ABS(SUM(İade))as decimal(18,2)) AS Toplam
FROM(        
        SELECT
                Personel,
                CASE WHEN Tür = ''Satış'' THEN SUM(USD TUTAR (KDV HARİÇ)) ELSE 0 END AS Satış,
                CASE WHEN Tür = ''İade'' THEN SUM(USD TUTAR (KDV HARİÇ)) ELSE 0 END AS İade
        FROM (        
                SELECT
                                CASE WHEN FB.TUR = 15 THEN ''Satış'' WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN ''İade'' ELSE '''' END AS Tür,
                                FB.FATURATARIH AS Tarih,
                                FB.FATURANO AS Belge Numarası,
                                R.FIRMA AS Cari Ünvan,
                                S.OZELKOD AS Üretici,
                                CASE WHEN F.TUR = 0 THEN ''Hizmet'' ELSE ''Malzeme'' END AS Stok/Hizmet,
                                coalesce(S.KOD,MG.KOD) AS Kod,
                                coalesce(S.STOKADI,MG.AD) AS Stok/Hizmet Adı,
                                CASE 
                                        WHEN F.TUR IN (1,11) THEN
                                        coalesce(((select K.AD from KATEGORI K where K.ID=(SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))),''Kategorisiz'')
                                        ELSE 
                                        coalesce(((SELECT MG1.KOD||''-''||MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD=REVERSE(SUBSTRING(REVERSE(MG.KOD),CHARINDEX(''.'',REVERSE(MG.KOD))+1,100)) LIMIT 1 ) ),''Kategorisiz'')
                                END AS KATEGORIADI,
                                CASE 
                                        WHEN F.TUR IN (1,11) THEN
                                        coalesce(((select ANAHTAR from GENINI where BOLUM=-2704 and DIL=-1 and DEGER=(SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))),''Grupsuz'')
                                        ELSE 
                                        ''Grupsuz''
                                END AS GRUPADI,          
                                F.MIKTAR,
                                BR.ANAHTAR AS BIRIM,
                                GB.ANAHTAR AS Bölge,
                                RB.BILGI AS İl,
                                RS.FIRMA AS Personel,
                                coalesce(GN.ANAHTAR,'''') AS İlk Temas,
                                FB.VADE AS VADE,                
                                CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.BIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.BIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS FATURA_MALIYETI_ORT,
                                CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS FATURA_MALIYETI_ORT_USD,
                                CAST(CASE WHEN FB.TUR = 15 THEN F.TUTAR WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.TUTAR *-1 END AS FLOAT) AS TL TUTAR (KDV HARİÇ),
                                CAST(coalesce(CASE WHEN FB.TUR = 15 THEN F.KDVDAHILFIYAT WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.KDVDAHILFIYAT *-1 END,0) AS FLOAT) AS TL TUTAR (KDVDAHİL),
                                CAST(CASE WHEN FB.TUR = 15 THEN F.TUTAR WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.TUTAR *-1 END AS FLOAT)-CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.BIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.BIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS (KDV HARİÇ) KAR TL,
                                CAST(coalesce(CASE WHEN FB.TUR = 15 THEN F.KDVDAHILFIYAT WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN F.KDVDAHILFIYAT *-1 END,0) AS FLOAT) - CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.BIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.BIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2))AS ( KDV DAHİL) KAR TL,
                                CAST(CASE 
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN F.TUTAR/D.SATIS
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (F.TUTAR*-1)/D.SATIS
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR*-1
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI*-1 
                                END AS decimal(15,4)) AS USD TUTAR (KDV HARİÇ),
                                CAST(CASE 
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN KDVDAHILFIYAT/D.SATIS
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN KDVDAHILFIYAT/FB.DOVIZKUR 
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100) 
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (KDVDAHILFIYAT*-1)/D.SATIS
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN (KDVDAHILFIYAT/FB.DOVIZKUR)*-1 
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN (F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100))*-1 
                                END AS decimal(15,4)) AS USD TUTAR (KDV DAHİL),
                                CAST(CASE 
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN F.TUTAR/D.SATIS
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (F.TUTAR*-1)/D.SATIS
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN F.TUTAR/FB.DOVIZKUR*-1
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI*-1 
                                END AS decimal(15,4))-CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2)) AS (KDV HARİÇ) KAR USD,
                                CAST(CASE 
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ = ''TL'' THEN KDVDAHILFIYAT/D.SATIS
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN KDVDAHILFIYAT/FB.DOVIZKUR 
                                WHEN FB.TUR = 15 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100) 
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ = ''TL'' THEN (KDVDAHILFIYAT*-1)/D.SATIS
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU = ''TL'' THEN (KDVDAHILFIYAT/FB.DOVIZKUR)*-1 
                                WHEN FB.TUR = 11 AND FB.TIPI = 2 AND FB.RAPORDOVIZ <> ''TL'' AND F.DOVIZ_KURU <> ''TL'' THEN (F.DOVIZ_TUTARI+(F.DOVIZ_TUTARI*F.KDV/100))*-1 
                                END AS decimal(15,4))-CAST(CASE WHEN FB.TUR = 15 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET,0) WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN coalesce(SOM.DOVIZBIRIMMALIYET*F.ADET*-1,0) END AS decimal(15,2))  AS (KDV DAHİL) KAR USD,
                                CAST(CASE WHEN DOVIZKUR = 1 THEN D.SATIS ELSE DOVIZKUR END AS decimal(15,4)) AS Döviz Kuru
                from
                        FATBASLIK FB  
                        INNER JOIN FATURA F ON F.FATBASID = FB.ID 
                        LEFT JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
                        --LEFT JOIN GENINI GM ON GM.BOLUM = -2701 AND GM.DEGER = S.MARKA
                        INNER JOIN REHBER R on R.ID = FB.REHBERID
                        LEFT JOIN REHBERILETISIM RI ON RI.REHBERID = R.ID AND ((coalesce( FB.REHBERILETID,0) = 0 AND RI.VARSAYILAN = 1) OR ( RI.ID = FB.REHBERILETID))
                        LEFT JOIN REHBERBILGI RB ON RB.YER_ID = RI.ID AND RB.YERI = 1 AND RB.ETIKET = ''İl''
                        LEFT JOIN REHBER RS ON RS.ID = FB.SATICIKODU
                        LEFT JOIN MASRAFGELIR MG ON MG.ID = F.URUNID AND F.TUR = 0
                        LEFT OUTER JOIN REHBER SATICIBILGI ON FB.SATICIKODU = SATICIBILGI.ID
                        INNER JOIN ISLEMTURLERI IT ON IT.TUR = FB.TUR AND IT.TIP = FB.TIPI
                        LEFT JOIN GENINI GN ON GN.BOLUM = -2207 AND GN.DEGER = R.TEMAS
                        LEFT JOIN GENINI GB ON GB.BOLUM = -2210 AND GB.DEGER = R.BOLGE
                        LEFT JOIN GENINI BR ON BR.BOLUM = -2702 AND BR.DEGER = F.BIRIM 
                        LEFT JOIN STOK_ORT_MALIYET SOM ON SOM.FATBASID = FB.ID AND SOM.FATURAID = F.ID AND SOM.STOKID = F.URUNID AND SOM.DEPOID = CASE WHEN FB.TUR = 15 THEN FB.CIKISDEPO WHEN FB.TUR = 11 AND FB.TIPI = 2 THEN FB.GIRISDEPO END
                        LEFT JOIN DOVIZ D ON to_char(D.TARIH,''YYYY-MM-DD HH24:MI:SS'') = to_char(FB.FATURATARIH,''YYYY-MM-DD HH24:MI:SS'') AND D.CINSI = ''$''
                WHERE 
                        1=1 AND (FB.TUR = 15 OR (FB.TUR = 11 AND FB.TIPI = 2))
                        --AND FB.FATURATARIH >= ''2021-10-21 00:00'' and  FATURATARIH <= ''2024-10-24 23:59:59''
                        AND FATURATARIH >= ''$BASTAR$ 00:00'' and  FATURATARIH <= ''$BITTAR$ 23:59:59''
                        --AND DOVIZKUR = 1
                        AND FB.DURUM <> 6
                        AND coalesce(R.KarZararDisi,''False'') <> ''True''
                   AND coalesce(MG.KOD,'''') <> ''840.01''
        ) AS X
        GROUP BY
                Personel,
                Tür
) AS Y
GROUP BY
        Personel' WHERE id = 1440;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
         CASE WHEN FB.TUR = 10 THEN ''Alış İrsaliyesi'' WHEN FB.TUR = 11 THEN ''Alış Faturası'' WHEN FB.TUR = 14 THEN ''Satış İrsaliyesi'' WHEN FB.TUR = 15 THEN ''Satış Faturası'' END AS BELGETUR ,
        FB.FATURATARIH,
        FB.FATURANO,
        R.FIRMA,
         RT.FIRMA AS TEMSILCI ,
        FB.OZELKOD,
        S.KOD,
        S.URUNNO,
        S.STOKADI,
         K.AD AS KATEGORI ,
        F.ADET,
         coalesce(CASE WHEN FB.TUR = 10 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) END,0) AS DONUSEN ,
         F.ADET - coalesce(CASE WHEN FB.TUR = 10 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) END,0)
 AS KALAN FROM 

        FATBASLIK FB 
                        INNER JOIN FATURA F ON FB.ID=F.FATBASID      
                        INNER JOIN REHBER R ON FB.REHBERID=R.ID
                        LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
                        INNER JOIN STOKLAR S ON S.ID=F.URUNID
                        LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
WHERE
        FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
        AND R.FIRMA LIKE ''$FIRMA$%''
        AND RT.FIRMA LIKE ''$TEMSILCI$%''
        AND FB.TUR IN (10,11,14,15)
        AND FB.TIPI = 1
        AND F.TUR IN (1,2)
        AND ADET <> 0.0
        AND FB.OZELKOD LIKE ''T%''
        AND F.ADET - coalesce(CASE WHEN FB.TUR = 10 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) END,0) <> 0
ORDER BY
     R.FIRMA,FB.FATURATARIH' WHERE id = 1441;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
        FIRMA,
        TEMSILCI,
        KATEGORI,
        coalesce(SUM(GIDEN_IRSALIYE),0) AS GIDEN_IRSALIYE,
         coalesce(SUM(GELEN_IRSALIYE),0) AS GELEN_IRSALIYE,
        CAST(SUM(coalesce(GIDEN_IRSALIYE,0) - coalesce(GELEN_IRSALIYE,0)) AS DECIMAL(18,2)) AS FARK_IRSALIYE,
         coalesce(SUM(GIDEN_FATURA),0) AS GIDEN_FATURA,
        coalesce(SUM(GELEN_FATURA),0) AS GELEN_FATURA,
        CAST(SUM(coalesce(GIDEN_FATURA,0) - coalesce(GELEN_FATURA,0)) AS DECIMAL(18,2)) AS FARK_FATURA
FROM(        
        SELECT 
                FB.OZELKOD,
                R.FIRMA,
                 RT.FIRMA AS TEMSILCI ,
                FB.TUR,
                CASE FB.TUR WHEN 10 THEN ''GELEN_IRSALIYE'' WHEN 11 THEN ''GELEN_FATURA'' WHEN 14 THEN ''GIDEN_IRSALIYE'' WHEN 15 THEN ''GIDEN_FATURA'' END AS TURAD,
                 ''Alış/Satış'' AS TIPI ,
                 S.KOD AS KOD ,
                 S.STOKADI AS AD ,
                F.ADET,
                 K.AD AS KATEGORI ,
                 K.KOD
         AS KATEGORIKOD FROM 

                FATBASLIK FB 
                                INNER JOIN FATURA F ON FB.ID=F.FATBASID      
                                INNER JOIN REHBER R ON FB.REHBERID=R.ID
                                LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
                                INNER JOIN STOKLAR S ON S.ID=F.URUNID
                                LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
        WHERE
                FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
                AND R.FIRMA LIKE ''$FIRMA$%''
                AND RT.FIRMA LIKE ''$TEMSILCI$%''
                AND FB.TUR IN (10,11,14,15)
                AND FB.TIPI IN (1,2)
                AND F.TUR = 1
                AND ADET <> 0.0
                AND FB.OZELKOD LIKE ''T%''        
) AS X
PIVOT
(
        SUM(ADET) FOR TURAD IN (GELEN_IRSALIYE,GELEN_FATURA,GIDEN_IRSALIYE,GIDEN_FATURA)
) PVT
GROUP BY
        FIRMA,
        TEMSILCI,
        KATEGORI' WHERE id = 1442;
UPDATE public.dokumler SET sql = '/*PGX*/
        ''$BITTAR$ 23:59'' DATETIME,
        ''$REHBER$'' varchar(1000)





SELECT
        FIRMA,
        KOD,
        AD,
        SUM(IRSALIYE) AS IRSALIYE,
        SUM(FATURA) AS FATURA,
        SUM(FIS) AS FIS,
        SUM(KONSINYE) AS KONSINYE,
        SUM(IADE) AS IADE INTO gt_FATURA
FROM(
SELECT
        FB.TUR,
        R.FIRMA,
        K.KOD,
        K.AD,
        coalesce(CASE WHEN FB.TUR = 14 THEN SUM(F.ADET) ELSE 0 END,0) AS IRSALIYE, 
        coalesce(CASE WHEN FB.TUR = 15 THEN SUM(F.ADET) ELSE 0 END,0) AS FATURA,
        coalesce(CASE WHEN FB.TUR = 16 THEN SUM(F.ADET) ELSE 0 END,0) AS FIS,
        coalesce(CASE WHEN FB.TUR = 119 THEN SUM(F.ADET) ELSE 0 END,0) AS KONSINYE,
        coalesce(CASE WHEN FB.TUR = 11 THEN SUM(F.ADET) ELSE 0 END,0) AS IADE
FROM
        FATURA F
                INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
                INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
                INNER JOIN KATEGORI K ON K.ID = S.KATEGORI
                INNER JOIN REHBER R ON R.ID = FB.REHBERID
WHERE
        (
        (FB.TUR IN (14,15,16) AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR = 15 AND F1.YERI = 411 AND F1.YERID = F.ID))
        OR  (FB.TUR = 119        AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR IN (14,15) AND F1.YERI IN (462,468) AND F1.YERID = F.ID))
        OR (FB.TUR = 11 AND FB.TIPI = 2))
        AND FB.FATURATARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
        AND R.FIRMA LIKE ''$REHBER$''+''%''
GROUP BY
        FB.TUR,
        R.FIRMA,
        K.KOD,
        K.AD
) AS X
GROUP BY
        FIRMA,
        KOD,
        AD

SELECT
        ST.STOKADI,
        CAST(SUM(SD.ADET) AS INT) AS Sipariş Miktarı,
        CAST(SUM(coalesce(F.IRSALIYE,0)) AS INT) AS İrsaliye,
        CAST(SUM(coalesce(F.FATURA,0)) AS INT) AS Fatura,
        CAST(SUM(coalesce(F.FIS,0)) AS INT) AS Fiş,
        CAST(SUM(coalesce(F.KONSINYE,0)) AS INT) AS Konsinye,
        CAST(SUM(coalesce(F.IADE,0)) AS INT) AS Gelen İade,
        CAST(SUM(coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0)) AS INT) AS Karşılanan,
        CAST(SUM(SD.ADET) - SUM(coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0)) + SUM(coalesce(F.IADE,0)) AS INT) AS Kalan,
        SD1.KALAN AS Anadepo Stok,
        coalesce(SD1.KALAN,0) - CAST(SUM(SD.ADET) - SUM(coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0)) + SUM(coalesce(F.IADE,0)) AS INT) AS Bize Kalan
FROM 
        SIPARISDETAY SD 
                INNER JOIN SIPARIS S ON S.ID = SD.SIPARISID AND S.TUR = 19 
                INNER JOIN REHBER R ON R.ID = S.REHBERID 
                INNER JOIN STOKLAR ST ON ST.ID = SD.URUNID AND SD.TUR = 1
                INNER JOIN KATEGORI K ON K.KOD = ST.KOD
                LEFT JOIN gt_FATURA F ON F.FIRMA = R.FIRMA AND F.KOD = ST.KOD --(11,14,15,16)
                LEFT JOIN (SELECT ST1.KATEGORI,SUM(KALAN) AS KALAN FROM STOKLAR ST1 INNER JOIN KATEGORI K1 ON K1.ID = ST1.KATEGORI AND K1.KOD <> ST1.KOD INNER JOIN STOKDURUM SD1 ON SD1.STOKID = ST1.ID AND SD1.DEPOID = 1 GROUP BY ST1.KATEGORI) SD1 ON SD1.KATEGORI = K.ID
WHERE 
        S.SIPARISTARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
        AND R.FIRMA LIKE ''$REHBER$''+''%''
GROUP BY
        ST.KOD,
        ST.STOKADI,
        SD1.KALAN
ORDER BY
        ST.KOD

DROP TABLE gt_FATURA
' WHERE id = 1444;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
	(SELECT SUBSTRING(FIRMA,1,CHARINDEX('' '',FIRMA,1)) FROM REHBER WHERE ID = -1) AS KURUM_ADI,
	(SELECT BILGI FROM REHBERBILGI WHERE YER_ID = -1 AND YERI = 2 AND SIRA = 40) AS KURUM_UTS_NO,
	S.URUNNO,
	SL.SERINO,
	SL.LOTNO,
	SUM(SDI.KALAN) AS ADET,
	1 AS FIYAT,
	SL.URT,
        SL.SKT	
FROM
	STOKLAR S 
		INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
		INNER JOIN STOKSERILOT SL ON SL.STOKID = S.ID AND SL.ID = SDI.SERILOTID
GROUP BY
	S.URUNNO,
	SL.SERINO,
	SL.LOTNO,
	SL.SKT,
	SL.URT
HAVING
	SUM(SDI.KALAN) > 0
ORDER BY
	S.URUNNO' WHERE id = 1445;
UPDATE public.dokumler SET sql = '/*PGX*/
        (SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$''-- ''Satış İrsaliyesi'' --''Satış Faturası'' LIMIT 1 ) INT,
        ''$BELGENO$'' varchar(100),
        ''$KOD$'' varchar(100),
        ''$LOTNO$'' varchar(100)







IF ((SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$''-- ''Satış İrsaliyesi'' --''Satış Faturası'' LIMIT 1 ) IN (3,10,14))
BEGIN
        SELECT
                F.ID AS SATIRID,
                S.KOD,
                S.URUNNO,
                S.STOKADI,
                                S.SMKODU,
                                S.SUTKODU,
                                S.DMOKODU,
                F.ACIKLAMA,
                coalesce(SI.ADET,F.ADET) AS ADET,
                G.ANAHTAR AS BIRIM,
                SL.LOTNO,
                SL.URT,
                SL.SKT,
                F1.ID AS HEDEF SATIR ID,
                FB1.FATURANO AS HEDEF BELGENO,
                FB1.FATURATARIH AS HEDEF TARIH,
                coalesce(SI1.ADET,F1.ADET) AS HEDEF ADET
        FROM
                FATURA F
                        INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
                        INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
                        LEFT JOIN STOKIZLEME SI ON SI.BASLIKID = F.FATBASID AND SI.SATIRID = F.ID
                        LEFT JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
                        LEFT JOIN GENINI G ON G.BOLUM = -2702 AND G.DEGER = F.BIRIM
                        LEFT JOIN FATURA F1 ON F1.YERID = F.ID AND F1.YERI = CASE WHEN FB.TUR = 14 THEN 411 ELSE 408 END
                        LEFT JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID
                        LEFT JOIN STOKIZLEME SI1 ON SI1.BASLIKID = FB1.ID AND SI1.SATIRID = F1.ID
        WHERE
                FB.TUR = (SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$''-- ''Satış İrsaliyesi'' --''Satış Faturası'' LIMIT 1 )
                AND FB.FATURANO LIKE ''$BELGENO$'' + ''%''
                AND S.KOD LIKE ''$KOD$''+''%''
                AND SL.LOTNO LIKE ''$LOTNO$''+''%''
END

IF ((SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$''-- ''Satış İrsaliyesi'' --''Satış Faturası'' LIMIT 1 ) IN (11,15))
BEGIN
        SELECT
                F.ID AS SATIRID,
                S.KOD,
                S.URUNNO,
                S.STOKADI,
                                S.SMKODU,
                                S.SUTKODU,
                                S.DMOKODU,
                F.ACIKLAMA,
                coalesce(SI.ADET,F.ADET) AS ADET,
                G.ANAHTAR AS BIRIM,
                SL.LOTNO,
                SL.URT,
                SL.SKT,
                F1.ID AS KAYNAK SATIR ID,
                FB1.FATURANO AS KAYNAK BELGENO,
                FB1.FATURATARIH AS KAYNAK TARIH,
                coalesce(SI1.ADET,F1.ADET) AS KAYNAK ADET
        FROM
                FATURA F
                        INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
                        INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
                        LEFT JOIN STOKIZLEME SI ON SI.BASLIKID = F.FATBASID AND SI.SATIRID = F.ID
                        LEFT JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
                        LEFT JOIN GENINI G ON G.BOLUM = -2702 AND G.DEGER = F.BIRIM
                        LEFT JOIN FATURA F1 ON F1.ID = F.YERID AND F.YERI = CASE WHEN FB.TUR = 15 THEN 411 ELSE 408 END
                        LEFT JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID
                        LEFT JOIN STOKIZLEME SI1 ON SI1.BASLIKID = FB1.ID AND SI1.SATIRID = F1.ID AND SI1.ID = SI.DONUSID
        WHERE
                FB.TUR = (SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$''-- ''Satış İrsaliyesi'' --''Satış Faturası'' LIMIT 1 )
                AND FB.FATURANO LIKE ''$BELGENO$'' + ''%''
                AND S.KOD LIKE ''$KOD$''+''%''
                AND SL.LOTNO LIKE ''$LOTNO$''+''%''
END
' WHERE id = 1446;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT
    --ID,
    Tarih,
    Yıl,
    Ay,
    Hafta,
    Bayi,
    Hastane,
    Şehir,
    Marka,
    MAX(PS/CR) AS PS/CR,
    Kategori,
    MAX(Fem.Comp.) AS Fem.Comp.,
    MAX(Tibial Comp.) AS Tibial Comp.,
    MAX(İnsert) AS İnsert,
    MAX(Patella) AS Patella,
    MAX(Stem) AS Stem,
    MAX(Head) AS Head,
    MAX(Shell) AS Shell,
    MAX(Liner) AS Liner,
    MAX(Screw1) AS Screw1,
    MAX(Screw2) AS Screw2,
    MAX(Screw3) AS Screw3,
    Hekim
FROM
(
    SELECT
        FB.ID,
        FB.FATURATARIH AS Tarih,
        YEAR(FB.FATURATARIH) AS Yıl,
        MONTH(FB.FATURATARIH) AS Ay,
        cast(DATEPART(WEEK, FB.FATURATARIH) as varchar)||''. Hafta'' AS Hafta,
        R.FIRMA AS Bayi,
        CASE WHEN R1.OZELKOD = ''DMO'' THEN FB.KURUM ELSE R1.FIRMA END AS Hastane,
        '''' AS Şehir,
        G.ANAHTAR AS Marka,
        G1.ANAHTAR AS PS/CR,
        K.AD AS Kategori,
        CASE WHEN G2.ANAHTAR = ''Screw'' THEN ''Screw''||cast(ROW_NUMBER() OVER(PARTITION BY FB.ID,G2.ANAHTAR ORDER BY FB.ID) as varchar) ELSE G2.ANAHTAR END AS Ozellik,
        S.KOD AS Kod,
        FB.DOKTOR AS Hekim
    FROM FATURA F
        INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
        INNER JOIN STOKLAR S ON S.ID = F.URUNID
        LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
        INNER JOIN REHBER R ON R.ID = -1
        INNER JOIN REHBER R1 ON R1.ID = FB.REHBERID
        LEFT JOIN GENINI G ON G.BOLUM = -2701 AND G.DEGER = S.MARKA
        LEFT JOIN GENINI G1 ON G1.BOLUM = -2704 AND G1.DEGER = S.GRUBU
        LEFT JOIN GENINI G2 ON G2.BOLUM = -2705 AND G2.DEGER = S.OZELLIK

    WHERE
        FB.TUR = 14
        AND FB.FATURATARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
) AS X

PIVOT
(
    MAX(Kod)
    FOR Ozellik IN
    (Fem.Comp.,Tibial Comp.,İnsert,Patella,Stem,Head,Shell,Liner,Screw1,Screw2,Screw3)
) AS PVT
GROUP BY
    ID,
    Tarih,
    Yıl,
    Ay,
    Hafta,
    Bayi,
    Hastane,
    Şehir,
    Marka,
    Kategori,
    Hekim
ORDER BY Tarih,ID' WHERE id = 1448;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
        S.KOD,
        S.URUNNO,
        S.STOKADI,
        K.AD AS KATEGORI,
        D.DEPOADI,
        SL.LOTNO,
        SDI.KALAN
FROM 
        STOKLAR S
                INNER JOIN KATEGORI K ON K.ID = S.KATEGORI
                INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
                INNER JOIN STOKSERILOT SL ON SL.STOKID = S.ID AND SDI.SERILOTID = SL.ID
                INNER JOIN DEPOLAR D ON D.ID = SDI.DEPOID' WHERE id = 1449;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    ''İzlemi olmayan kayıt'' AS BILGI,
    I.AD,
    FB.TUR,
    FB.FATURATARIH,
    RR.FIRMA,
    FB.FATURANO,
    S.KOD,
    F.ADET,
    0 AS IZLEMADET,
    FB.ID AS FATBASID,
    F.ID AS FATURAID,
    R.FIRMA,
    F.EKLEMETARIHI
FROM FATURA F
INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
INNER JOIN STOKLAR S ON S.ID = F.URUNID
INNER JOIN REHBER R ON R.ID = F.EKLEYEN
INNER JOIN REHBER RR ON RR.ID = FB.REHBERID
LEFT JOIN ISLEMTURLERI I ON I.TUR = FB.TUR 
    AND CASE WHEN I.TIP = 0 THEN 1 WHEN I.TUR = 109 THEN 2 ELSE I.TIP END = FB.TIPI
WHERE FB.FATURATARIH >= ''2020-01-01 00:00''
    AND F.IZLEME <> 0 
    AND FB.TUR <> 2 
    AND FB.TIPI NOT IN (3) 
    AND FB.DURUM <> 6 
    AND F.TUR = 1
    AND NOT EXISTS (
        SELECT * FROM STOKIZLEME SI WHERE F.ID = SI.SATIRID AND F.FATBASID = SI.BASLIKID
    )

UNION ALL

SELECT 
    ''F.adet ile izlem adet farklı kayıt'' AS BILGI,
    I.AD,
    FB.TUR,
    FB.FATURATARIH,
    RR.FIRMA,
    FB.FATURANO,
    S.KOD,
    F.ADET,
    (SELECT SUM(SI.ADET) FROM STOKIZLEME SI WHERE F.FATBASID = SI.BASLIKID AND F.ID = SI.SATIRID) AS IZLEMADET,
    FB.ID AS FATBASID,
    F.ID AS FATURAID,
    R.FIRMA,
    F.EKLEMETARIHI
FROM FATURA F
INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
INNER JOIN STOKLAR S ON S.ID = F.URUNID
LEFT JOIN ISLEMTURLERI I ON I.TUR = FB.TUR 
    AND CASE WHEN I.TIP = 0 THEN 1 WHEN I.TUR = 109 THEN 2 ELSE I.TIP END = FB.TIPI
INNER JOIN REHBER R ON R.ID = F.EKLEYEN
INNER JOIN REHBER RR ON RR.ID = FB.REHBERID
WHERE F.ADET <> (
    SELECT SUM(SI.ADET) FROM STOKIZLEME SI WHERE F.FATBASID = SI.BASLIKID AND F.ID = SI.SATIRID
)' WHERE id = 1450;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    URUNID,
    S.KOD,
    S.URUNNO,
    S.STOKADI,
     K.AD AS KATEGORI ,
     D.DEPOADI AS DEPO ,
     G.ANAHTAR AS MARKA ,
     G1.ANAHTAR AS MODEL ,
    SI.LOTNO,
    SI.SKT,
    SI.URT,
     CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.GIREN,2) ELSE ROUND(DRM.GIREN,2) END AS INT) AS GIREN ,
     CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.CIKAN,2) ELSE ROUND(DRM.CIKAN,2) END AS INT) AS CIKAN ,
     CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.KALAN,2) ELSE ROUND(DRM.KALAN,2) END AS INT) AS KALAN ,
    Mlt.BIRIMMALIYET,
     CAST(DRM.KALAN * Mlt.BIRIMMALIYET AS MONEY)
 AS MALIYET FROM STOKLAR S
INNER JOIN (
    SELECT 
        DEPO,
        URUNID,
         round(SUM(CASE WHEN NETMIKTAR > 0.0 THEN NETMIKTAR ELSE 0.0 END),2) AS GIREN ,
         round(SUM(CASE WHEN NETMIKTAR < 0.0 THEN -1.0*NETMIKTAR ELSE 0.0 END),2) AS CIKAN ,
         round(SUM(NETMIKTAR),2)
     AS KALAN FROM (
        SELECT GIRISDEPO AS DEPO, F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR >= 0) THEN F.MIKTAR WHEN (FB.TUR = 6) AND (F.MIKTAR < 0) THEN 0 ELSE F.MIKTAR END AS NETMIKTAR
        FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID
        WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6) AND (coalesce(FB.GIRISDEPO, 0) > 0) and F.TUR = 1
            AND FB.FATURATARIH <= ''$Bitis$ 23:59''
        UNION ALL
        SELECT CIKISDEPO AS DEPO, F.URUNID, CASE WHEN (FB.TUR = 6) AND (F.MIKTAR > 0) THEN 0 WHEN (FB.TUR = 6) AND (F.MIKTAR <= 0) THEN F.MIKTAR ELSE - F.MIKTAR END AS NETMIKTAR
        FROM FATBASLIK AS FB INNER JOIN FATURA AS F ON F.FATBASID = FB.ID
        WHERE (F.STOKDURUMDEGIS = 1) AND (coalesce(FB.DURUM, 1) <> 6) AND (coalesce(FB.CIKISDEPO, 0) > 0) and F.TUR = 1
            AND FB.FATURATARIH <= ''$Bitis$ 23:59''
    ) AS ASD GROUP BY URUNID, DEPO
    HAVING SUM(NETMIKTAR) <> 0.0
) AS DRM ON S.ID = DRM.URUNID
LEFT JOIN (
    SELECT STOKID, BIRIMMALIYET, ROW_NUMBER() OVER (PARTITION BY STOKID ORDER BY TARIH desc) as NUM FROM STOK_ORT_MALIYET SM
) AS Mlt ON Mlt.STOKID = S.ID AND Mlt.NUM = 1
INNER JOIN DEPOLAR D ON D.ID = DRM.DEPO
LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
LEFT JOIN GENINI G ON G.BOLUM = -2701 AND G.DEGER = S.MARKA
LEFT JOIN GENINI G1 ON G1.DEGER = S.MODEL AND G1.BOLUM = cast(''-2701''||cast(S.MARKA as varchar) as integer) AND G1.DIL < 0
LEFT JOIN (
    SELECT 
        S.KOD,
        SL.LOTNO,
        coalesce(SL.SKT,'''') AS SKT,
        coalesce(SL.URT,'''') AS URT,
        SID.DEPOID,
         SUM(CASE WHEN SID.ADET > 0 THEN SID.ADET ELSE 0 END) AS GIREN ,
         ABS(SUM(CASE WHEN SID.ADET < 0 THEN SID.ADET ELSE 0 END)) AS CIKAN ,
         SUM(CASE WHEN SID.ADET > 0 THEN SID.ADET ELSE 0 END) - ABS(SUM(CASE WHEN SID.ADET < 0 THEN SID.ADET ELSE 0 END))
     AS KALAN FROM STOKIZLEME SI 
    INNER JOIN STOKIZLEMEDEPO SID ON SID.IZLEMID = SI.ID
    INNER JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
    INNER JOIN STOKLAR S ON S.ID = SI.STOKID
    INNER JOIN FATBASLIK FB ON FB.ID = SI.BASLIKID AND FB.TUR = CASE WHEN SI.BELGETUR = 101 THEN 6 ELSE SI.BELGETUR END
    WHERE FB.FATURATARIH <= ''$Bitis$ 23:59''
    GROUP BY S.KOD, SL.LOTNO, SL.SKT, SL.URT, SID.DEPOID
) SI ON SI.KOD = S.KOD AND SI.DEPOID = DRM.DEPO
WHERE S.KOD LIKE ''$StokKod$%''
    AND coalesce(S.MARKA,'''') LIKE ''$marka$%''
    AND coalesce(D.DEPOADI,'''') LIKE ''$DepoAdi$%''
    AND CAST(CASE WHEN coalesce(S.IZLEME,0) <> 0 THEN ROUND(SI.KALAN,2) ELSE ROUND(DRM.KALAN,2) END AS INT) > 0' WHERE id = 1451;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    S.KOD,
    D.DEPOADI,
    SUM(SDI.KALAN) AS SDI_KALAN,
    SD.KALAN,
     0
 AS KONSINYE_KALAN FROM STOKLAR S
INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
INNER JOIN STOKDURUM SD ON SD.STOKID = S.ID AND SD.DEPOID = SDI.DEPOID
INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
WHERE D.DEPOADI <> ''Konsinye Çıkış''
GROUP BY S.KOD, D.DEPOADI, SD.KALAN
HAVING CAST(SUM(SDI.KALAN) AS decimal(18,4)) <> CAST(SD.KALAN AS decimal(18,4))

UNION ALL

SELECT 
    S.KOD,
    D.DEPOADI,
    SUM(SDI.KALAN) AS SDI_KALAN,
    SD.KALAN,
     (
        SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119
    )
 AS KONSINYE_KALAN FROM STOKLAR S
INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
INNER JOIN STOKDURUM SD ON SD.STOKID = S.ID AND SD.DEPOID = SDI.DEPOID
INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
WHERE D.DEPOADI = ''Konsinye Çıkış''
GROUP BY S.KOD, D.DEPOADI, SD.KALAN, S.ID
HAVING (
    CAST(SUM(SDI.KALAN) AS decimal(18,4)) <> CAST(SD.KALAN AS decimal(18,4))
    OR CAST(SUM(SDI.KALAN) AS decimal(18,4)) <> CAST((SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119) AS decimal(18,4))
    OR CAST(SD.KALAN AS decimal(18,4)) <> CAST((SELECT SUM(SI.KALAN) FROM STOKIZLEME SI WHERE SI.STOKID = S.ID AND SI.BELGETUR = 119) AS decimal(18,4))
)' WHERE id = 1452;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    DEPOADI,
    KOD,
    STOKADI,
    LOT,
     CAST(SUM(KALAN) AS decimal(18,4)) AS KALAN ,
     CAST(SDI_KALAN AS decimal(18,4))
 AS SDI_KALAN FROM (
    SELECT 
        D.DEPOADI,
         D.ID AS DEPOID ,
         S1.ID AS STOKID ,
        F1.ID,
        S1.KOD,
        S1.STOKADI,
        SL.SKT,
         coalesce(SL.LOTNO,'''') AS LOT ,
        R1.FIRMA,
        G1.ANAHTAR,
        FB1.FATURATARIH as FATURATARIH,
        FB1.FATURANO,
         SD.ADET AS KALAN ,
         SDI.KALAN
     AS SDI_KALAN FROM STOKIZLEME SE1
    INNER JOIN FATURA F1 ON SE1.SATIRID = F1.ID
    INNER JOIN FATBASLIK FB1 ON F1.FATBASID = FB1.ID AND SE1.BASLIKID = FB1.ID
    INNER JOIN STOKLAR S1 ON S1.ID = F1.URUNID 
    INNER JOIN REHBER R1 on R1.ID = FB1.REHBERID
    INNER JOIN GENINI G1 ON G1.BOLUM = -1005 AND G1.DEGER = FB1.TUR and G1.DIL = -1
    INNER JOIN STOKSERILOT SL ON SL.ID = SE1.SERILOTID AND SL.STOKID = SE1.STOKID
    INNER JOIN STOKIZLEMEDEPO SD ON SD.IZLEMID = SE1.ID
    INNER JOIN DEPOLAR D ON D.ID = SD.DEPOID
    INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = SE1.STOKID AND SDI.DEPOID = D.ID AND SDI.SERILOTID = SE1.SERILOTID
    WHERE coalesce(FB1.DURUM,0) <> 6 
        AND SD.ADET <> 0
) AS X
GROUP BY DEPOADI, KOD, STOKADI, LOT, SDI_KALAN
HAVING CAST(SUM(KALAN) AS decimal(18,4)) < 0 
    OR CAST(SUM(KALAN) AS decimal(18,4)) - CAST(SDI_KALAN AS decimal(18,4)) NOT BETWEEN -0.1 AND 0.1' WHERE id = 1453;
UPDATE public.dokumler SET sql = '/*PGX*/






IF ((SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$'' LIMIT 1 ) IN (10,14,3))
BEGIN
    SELECT 
        F.ID AS SATIRID,
        S.KOD,
        S.URUNNO,
        S.STOKADI,
        F.ACIKLAMA,
        coalesce(SI.ADET,F.ADET) AS ADET,
        G.ANAHTAR AS BIRIM,
        SL.LOTNO,
        SL.URT,
        SL.SKT,
        F1.ID AS HEDEF SATIR ID,
        FB1.FATURANO AS HEDEF BELGENO,
        FB1.FATURATARIH AS HEDEF TARIH,
        coalesce(SI1.ADET,F1.ADET) AS HEDEF ADET,
        G1.ANAHTAR AS IZLEME,
        CASE WHEN S.BILDIRIM = 2 THEN ''ÜTS'' ELSE ''Yok'' END AS UTS
    FROM FATURA F
    INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
    INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
    LEFT JOIN STOKIZLEME SI ON SI.BASLIKID = F.FATBASID AND SI.SATIRID = F.ID
    LEFT JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
    LEFT JOIN GENINI G ON G.BOLUM = -2702 AND G.DEGER = F.BIRIM
    LEFT JOIN FATURA F1 ON F1.YERID = F.ID AND F1.YERI = CASE WHEN FB.TUR = 14 THEN 411 ELSE 408 END
    LEFT JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID
    LEFT JOIN STOKIZLEME SI1 ON SI1.BASLIKID = FB1.ID AND SI1.SATIRID = F1.ID AND SI1.SERILOTID = SI.SERILOTID
    LEFT JOIN GENINI G1 ON G1.BOLUM = -2706 AND G1.DEGER = S.IZLEME
    WHERE FB.TUR = (SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$'' LIMIT 1 ) 
        AND FB.FATURANO LIKE ''$BELGENO$'' + ''%'' 
        AND S.KOD LIKE ''$KOD$''+''%'' 
        AND SL.LOTNO LIKE ''$LOTNO$''+''%''
END

IF ((SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$'' LIMIT 1 ) IN (11,15))
BEGIN
    SELECT 
        F.ID AS SATIRID,
        S.KOD,
        S.URUNNO,
        S.STOKADI,
        F.ACIKLAMA,
        coalesce(SI.ADET,F.ADET) AS ADET,
        G.ANAHTAR AS BIRIM,
        SL.LOTNO,
        SL.URT,
        SL.SKT,
        F1.ID AS KAYNAK SATIR ID,
        FB1.FATURANO AS KAYNAK BELGENO,
        FB1.FATURATARIH AS KAYNAK TARIH,
        coalesce(SI1.ADET,F1.ADET) AS KAYNAK ADET,
        G1.ANAHTAR AS IZLEME,
        CASE WHEN S.BILDIRIM = 2 THEN ''ÜTS'' ELSE ''Yok'' END AS UTS
    FROM FATURA F
    INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
    INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
    LEFT JOIN STOKIZLEME SI ON SI.BASLIKID = F.FATBASID AND SI.SATIRID = F.ID
    LEFT JOIN STOKSERILOT SL ON SL.STOKID = SI.STOKID AND SL.ID = SI.SERILOTID
    LEFT JOIN GENINI G ON G.BOLUM = -2702 AND G.DEGER = F.BIRIM
    LEFT JOIN FATURA F1 ON F1.ID = F.YERID AND F.YERI = CASE WHEN FB.TUR = 15 THEN 411 ELSE 408 END
    LEFT JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID
    LEFT JOIN STOKIZLEME SI1 ON SI1.BASLIKID = FB1.ID AND SI1.SATIRID = F1.ID AND SI1.ID = SI.DONUSID
    LEFT JOIN GENINI G1 ON G1.BOLUM = -2706 AND G1.DEGER = S.IZLEME
    WHERE FB.TUR = (SELECT TUR FROM ISLEMTURLERI WHERE AD = ''$TURAD$'' LIMIT 1 ) 
        AND FB.FATURANO LIKE ''$BELGENO$'' + ''%'' 
        AND S.KOD LIKE ''$KOD$''+''%'' 
        AND SL.LOTNO LIKE ''$LOTNO$''+''%''
END
' WHERE id = 1454;
UPDATE public.dokumler SET sql = '/*PGX*/




SELECT 
    FIRMA,
    KOD,
    AD,
    SUM(IRSALIYE) AS IRSALIYE,
    SUM(FATURA) AS FATURA,
    SUM(FIS) AS FIS,
    SUM(KONSINYE) AS KONSINYE,
    SUM(IADE) AS IADE 
INTO gt_FATURA
FROM (
    SELECT 
        FB.TUR,
        R.FIRMA,
        K.KOD,
        K.AD,
        coalesce(CASE WHEN FB.TUR = 14 THEN SUM(F.ADET) ELSE 0 END,0) AS IRSALIYE,
        coalesce(CASE WHEN FB.TUR = 15 THEN SUM(F.ADET) ELSE 0 END,0) AS FATURA,
        coalesce(CASE WHEN FB.TUR = 16 THEN SUM(F.ADET) ELSE 0 END,0) AS FIS,
        coalesce(CASE WHEN FB.TUR = 119 THEN SUM(F.ADET) ELSE 0 END,0) AS KONSINYE,
        coalesce(CASE WHEN FB.TUR = 11 THEN SUM(F.ADET) ELSE 0 END,0) AS IADE
    FROM FATURA F
    INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
    INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
    INNER JOIN KATEGORI K ON K.ID = S.KATEGORI
    INNER JOIN REHBER R ON R.ID = FB.REHBERID
    WHERE (
        ( (FB.TUR IN (14,15,16) AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR IN (15,16) AND F1.YERI IN (411,424) AND F1.YERID = F.ID)))
        OR (FB.TUR = 119 AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR IN (14,15) AND F1.YERI IN (462,468) AND F1.YERID = F.ID))
        OR (FB.TUR = 11 AND FB.TIPI = 2)
    )
    AND FB.FATURATARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
    AND R.FIRMA LIKE ''$REHBER$''||''%''
    AND coalesce(FB.OZELKOD,'''') NOT IN (''Takas'',''Fail'',''Münferit'')
    GROUP BY FB.TUR, R.FIRMA, K.KOD, K.AD
) AS X GROUP BY FIRMA, KOD, AD

SELECT 
    R.FIRMA,
    ST.STOKADI,
    CAST(SUM(SD.ADET) AS INT) AS Sipariş Miktarı,
    CAST(coalesce(F.IRSALIYE,0) AS INT) AS İrsaliye,
    CAST(coalesce(F.FATURA,0) AS INT) AS Fatura,
    CAST(coalesce(F.FIS,0) AS INT) AS Fiş,
    CAST(coalesce(F.KONSINYE,0) AS INT) AS Konsinye,
    CAST(coalesce(F.IADE,0) AS INT) AS Gelen İade,
    CAST(coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) AS INT) AS Karşılanan,
    CAST(SUM(SD.ADET) - coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) + coalesce(F.IADE,0) AS INT) AS Kalan
FROM SIPARISDETAY SD
INNER JOIN SIPARIS S ON S.ID = SD.SIPARISID AND S.TUR = 19
INNER JOIN REHBER R ON R.ID = S.REHBERID
INNER JOIN STOKLAR ST ON ST.ID = SD.URUNID AND SD.TUR = 1
INNER JOIN KATEGORI K ON K.KOD = ST.KOD
LEFT JOIN gt_FATURA F ON F.FIRMA = R.FIRMA AND F.KOD = ST.KOD
WHERE S.SIPARISTARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
    AND R.FIRMA LIKE ''$REHBER$''||''%''
GROUP BY R.FIRMA, ST.KOD, ST.STOKADI, F.IRSALIYE, F.FATURA, F.FIS, F.IADE, F.KONSINYE
ORDER BY ST.KOD
DROP TABLE gt_FATURA
' WHERE id = 1455;
UPDATE public.dokumler SET sql = '/*PGX*/




SELECT 
    FIRMA,
    KOD,
    AD,
    SUM(IRSALIYE) AS IRSALIYE,
    SUM(FATURA) AS FATURA,
    SUM(FIS) AS FIS,
    SUM(KONSINYE) AS KONSINYE,
    SUM(IADE) AS IADE 
INTO gt_FATURA
FROM (
    SELECT 
        FB.TUR,
        R.FIRMA,
        K.KOD,
        K.AD,
        coalesce(CASE WHEN FB.TUR = 14 THEN SUM(F.ADET) ELSE 0 END,0) AS IRSALIYE,
        coalesce(CASE WHEN FB.TUR = 15 THEN SUM(F.ADET) ELSE 0 END,0) AS FATURA,
        coalesce(CASE WHEN FB.TUR = 16 THEN SUM(F.ADET) ELSE 0 END,0) AS FIS,
        coalesce(CASE WHEN FB.TUR = 119 THEN SUM(F.ADET) ELSE 0 END,0) AS KONSINYE,
        coalesce(CASE WHEN FB.TUR = 11 THEN SUM(F.ADET) ELSE 0 END,0) AS IADE
    FROM FATURA F
    INNER JOIN FATBASLIK FB ON FB.ID = F.FATBASID
    INNER JOIN STOKLAR S ON S.ID = F.URUNID AND F.TUR = 1
    INNER JOIN KATEGORI K ON K.ID = S.KATEGORI
    INNER JOIN REHBER R ON R.ID = FB.REHBERID
    WHERE (
        ( (FB.TUR IN (14,15,16) AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR IN (15,16) AND F1.YERI IN (411,424) AND F1.YERID = F.ID)))
        OR (FB.TUR = 119 AND NOT EXISTS(SELECT * FROM FATURA F1 INNER JOIN FATBASLIK FB1 ON FB1.ID = F1.FATBASID AND FB1.TUR IN (14,15) AND F1.YERI IN (462,468) AND F1.YERID = F.ID))
        OR (FB.TUR = 11 AND FB.TIPI = 2)
    )
    AND FB.FATURATARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
    AND R.FIRMA LIKE ''$REHBER$''||''%''
    AND coalesce(FB.OZELKOD,'''') NOT IN (''Takas'',''Fail'',''Münferit'')
    GROUP BY FB.TUR, R.FIRMA, K.KOD, K.AD
) AS X GROUP BY FIRMA, KOD, AD

SELECT 
    ST.STOKADI,
    CAST(SUM(SD.ADET) AS INT) AS Sipariş Miktarı,
    CAST(coalesce(F.IRSALIYE,0) AS INT) AS İrsaliye,
    CAST(coalesce(F.FATURA,0) AS INT) AS Fatura,
    CAST(coalesce(F.FIS,0) AS INT) AS Fiş,
    CAST(coalesce(F.KONSINYE,0) AS INT) AS Konsinye,
    CAST(coalesce(F.IADE,0) AS INT) AS Gelen İade,
    CAST(coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) AS INT) AS Karşılanan,
    CAST(SUM(SD.ADET) - coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) + coalesce(F.IADE,0) AS INT) AS Kalan,
    SD1.KALAN AS Anadepo Stok,
    coalesce(SD1.KALAN,0) - CAST(SUM(SD.ADET) - coalesce((F.IRSALIYE+F.FATURA+F.FIS+F.KONSINYE),0) + coalesce(F.IADE,0) AS INT) AS Bize Kalan
FROM SIPARISDETAY SD
INNER JOIN SIPARIS S ON S.ID = SD.SIPARISID AND S.TUR = 19
INNER JOIN REHBER R ON R.ID = S.REHBERID
INNER JOIN STOKLAR ST ON ST.ID = SD.URUNID AND SD.TUR = 1
INNER JOIN KATEGORI K ON K.KOD = ST.KOD
LEFT JOIN gt_FATURA F ON F.FIRMA = R.FIRMA AND F.KOD = ST.KOD
LEFT JOIN (
    SELECT 
        ST1.KATEGORI,
        SUM(KALAN) AS KALAN 
    FROM STOKLAR ST1 
    INNER JOIN KATEGORI K1 ON K1.ID = ST1.KATEGORI AND K1.KOD <> ST1.KOD 
    INNER JOIN STOKDURUM SD1 ON SD1.STOKID = ST1.ID AND SD1.DEPOID = 1 
    GROUP BY ST1.KATEGORI
) SD1 ON SD1.KATEGORI = K.ID
WHERE S.SIPARISTARIH BETWEEN ''$BASTAR$ 00:00'' AND ''$BITTAR$ 23:59''
    AND R.FIRMA LIKE ''$REHBER$''||''%''
GROUP BY ST.KOD, ST.STOKADI, SD1.KALAN, F.IRSALIYE, F.FATURA, F.FIS, F.IADE, F.KONSINYE
ORDER BY ST.KOD
DROP TABLE gt_FATURA
