UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
     CASE 
        WHEN FB.TUR = 10 THEN ''Alış İrsaliyesi'' 
        WHEN FB.TUR = 11 THEN ''Alış Faturası'' 
        WHEN FB.TUR = 14 THEN ''Satış İrsaliyesi'' 
        WHEN FB.TUR = 15 THEN ''Satış Faturası'' 
    END AS BELGETUR ,
    FB.FATURATARIH,
    FB.FATURANO,
    R.FIRMA,
     RT.FIRMA AS TEMSILCI ,
    FB.OZELKOD,
    S.KOD,
    S.URUNNO,
    S.STOKADI,
     K.AD AS KATEGORI ,
    F.ADET,
     coalesce(
        CASE 
            WHEN FB.TUR = 10 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) 
            ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) 
        END, 0) AS DONUSEN ,
     F.ADET - coalesce(
        CASE 
            WHEN FB.TUR = 10 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) 
            ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) 
        END, 0)
 AS KALAN FROM FATBASLIK FB
INNER JOIN FATURA F ON FB.ID=F.FATBASID
INNER JOIN REHBER R ON FB.REHBERID=R.ID
LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
INNER JOIN STOKLAR S ON S.ID=F.URUNID
LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
WHERE FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
    AND R.FIRMA LIKE ''$FIRMA$%''
    AND RT.FIRMA LIKE ''$TEMSILCI$%''
    AND FB.TUR IN (10,11,14,15)
    AND FB.TIPI = 1
    AND F.TUR IN (1,2)
    AND ADET <> 0.0
    AND FB.OZELKOD LIKE ''T%''
    AND F.ADET - coalesce(
        CASE 
            WHEN FB.TUR = 10 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) 
            ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) 
        END, 0) <> 0
ORDER BY R.FIRMA, FB.FATURATARIH' WHERE id = 1457;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    FIRMA,
    TEMSILCI,
    KATEGORI,
    KOD,
    URUNNO,
    AD,
    coalesce(SUM(GIDEN_IRSALIYE),0) AS GIDEN_IRSALIYE,
    coalesce(SUM(GELEN_IRSALIYE),0) AS GELEN_IRSALIYE,
    CAST(SUM(coalesce(GIDEN_IRSALIYE,0) - coalesce(GELEN_IRSALIYE,0)) AS DECIMAL(18,2)) AS FARK_IRSALIYE,
    coalesce(SUM(GIDEN_FATURA),0) AS GIDEN_FATURA,
    coalesce(SUM(GELEN_FATURA),0) AS GELEN_FATURA,
    CAST(SUM(coalesce(GIDEN_FATURA,0) - coalesce(GELEN_FATURA,0)) AS DECIMAL(18,2)) AS FARK_FATURA,
    coalesce(SUM(GIDEN_FIS),0) AS GIDEN_FIS,
    coalesce(SUM(GELEN_FIS),0) AS GELEN_FIS,
    CAST(SUM(coalesce(GIDEN_FIS,0) - coalesce(GELEN_FIS,0)) AS DECIMAL(18,2)) AS FARK_FIS
FROM (
    SELECT 
        FB.OZELKOD,
        R.FIRMA,
         RT.FIRMA AS TEMSILCI ,
        FB.TUR,
        CASE FB.TUR 
            WHEN 10 THEN ''GELEN_IRSALIYE'' 
            WHEN 11 THEN ''GELEN_FATURA'' 
            WHEN 12 THEN ''GELEN_FIS'' 
            WHEN 14 THEN ''GIDEN_IRSALIYE'' 
            WHEN 15 THEN ''GIDEN_FATURA'' 
            WHEN 16 THEN ''GIDEN_FIS'' 
        END AS TURAD,
         ''Alış/Satış'' AS TIPI ,
         S.KOD AS KOD ,
        S.URUNNO,
         S.STOKADI AS AD ,
        F.ADET,
         K.AD AS KATEGORI ,
         K.KOD
     AS KATEGORIKOD FROM FATBASLIK FB
    INNER JOIN FATURA F ON FB.ID=F.FATBASID
    INNER JOIN REHBER R ON FB.REHBERID=R.ID
    LEFT JOIN REHBER RT ON RT.ID = R.TEMSILCI
    INNER JOIN STOKLAR S ON S.ID=F.URUNID
    LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
    WHERE FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
        AND R.FIRMA LIKE ''$FIRMA$%''
        AND RT.FIRMA LIKE ''$TEMSILCI$%''
        AND FB.TUR IN (10,11,12,14,15,16)
        AND FB.TIPI IN (1,2)
        AND F.TUR = 1
        AND ADET <> 0.0
        AND FB.OZELKOD LIKE ''T%''
) AS X
PIVOT (
    SUM(ADET) FOR TURAD IN (
        GELEN_IRSALIYE,GELEN_FATURA,GELEN_FIS,
        GIDEN_IRSALIYE,GIDEN_FATURA,GIDEN_FIS,
        DONUSMEYEN_IRSALIYE,DONUSEN_IRSALIYE
    )
) PVT
GROUP BY FIRMA, TEMSILCI, KATEGORI, KOD, URUNNO, AD' WHERE id = 1458;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    ISLEMTUR, FATURATUR, OZELKOD, TIPI, FATURATARIH,  MONTH(FATURATARIH) AS BELGE_AY , 
    FATURANO, CARIKOD, FIRMA, STOK_OZELKOD, KOD, AD, DOKTOR, HASTA, ACIKLAMA, 
    cast(ADET as double precision) AS ADET, coalesce(cast(DONUSEN as double precision), 0) AS DONUSEN, 
    cast(ADET as double precision) - coalesce(cast(DONUSEN as double precision), 0) AS KALAN, 
    BIRIM, cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT,  cast(BIRIMFIYAT * ADET as double precision) AS TUTAR , 
    ISKONTO,  cast((BIRIMFIYAT * ADET) as double precision) - TUTAR AS ISKONTOTUTARI , 
    KDV,  cast(TUTAR as double precision) AS KDVMATRAHI ,  cast(KDVLITOPLAM as double precision) - TUTAR AS KDVTUTAR , 
     cast(KDVLITOPLAM as double precision) AS GENELTOPLAM , DOVIZ_CINSI, KATEGORIADI, GRUPADI, 
    ALICI_SATICI(BÜTÜN), ALICI_SATICI(SATIR), SUBE, MARKA, MODEL, 
    IL, PERSONEL, ACIKLAMA1, ACIKLAMA2, FATURASERI, F_OZELKOD, F_OZELKOD2, HEDEF, LOTNO
FROM (
    SELECT 
        FB.OZELKOD, FB.TUR, 
         CASE 
            WHEN FB.TIPI = 1 THEN ''Alış/Satış'' 
            WHEN FB.TIPI = 2 THEN ''İade'' 
            WHEN FB.TIPI = 3 THEN ''Fiyat Farkı'' 
            WHEN FB.TIPI = 4 THEN ''S.Mes.Mak.'' 
        END AS TIPI ,
        RI1.ANAHTAR AS FATURATUR, FB.FATURATARIH, FB.FATURANO, R.KOD AS CARIKOD, R.FIRMA, 
         CASE WHEN F.TUR IN (1, 11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR , 
         (SELECT OZELKOD FROM STOKLAR S WHERE F.URUNID = S.ID) AS STOK_OZELKOD , 
         CASE 
            WHEN F.TUR IN (1, 11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID) 
            ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID = F.URUNID) 
        END AS KOD ,
         CASE 
            WHEN F.TUR IN (1, 11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID) 
            ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) 
        END AS AD ,
        F.ACIKLAMA, F.ADET, 
         CASE 
            WHEN FB.TUR = 11 THEN (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 408) 
            ELSE (SELECT SUM(F1.ADET) FROM FATURA F1 WHERE F1.YERID = F.ID AND F1.YERI = 411) 
        END AS DONUSEN ,
        RI.ANAHTAR AS BIRIM, 
         CASE WHEN FB.KDVDURUM = ''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT / (1 + (F.KDV / 100.0)) END AS BIRIMFIYAT , 
         CASE WHEN FB.KDVDURUM = ''Hariç'' THEN F.TUTAR ELSE F.TUTAR / (1 + (F.KDV / 100.0)) END AS TUTAR , 
         CASE WHEN FB.KDVDURUM = ''Hariç'' THEN F.TUTAR * (1 + (F.KDV / 100.0)) ELSE F.TUTAR END AS KDVLITOPLAM , 
        F.ISKONTO, F.KDV,  FB.RAPORDOVIZ AS DOVIZ_CINSI , 
         CASE 
            WHEN F.TUR IN (1, 11) THEN coalesce(((SELECT K.AD FROM KATEGORI K WHERE K.ID = (SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))), ''Kategorisiz'') 
            ELSE coalesce(((SELECT MG1.KOD || ''-'' || MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD = REVERSE(SUBSTRING(REVERSE(MG.KOD), CHARINDEX(''.'', REVERSE(MG.KOD)) + 1, 100)) LIMIT 1 )), ''Kategorisiz'') 
        END AS KATEGORIADI , 
         CASE 
            WHEN F.TUR IN (1, 11) THEN coalesce(((SELECT ANAHTAR FROM GENINI WHERE BOLUM = -2704 AND DIL = -1 AND DEGER = (SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))), ''Grupsuz'') 
            ELSE ''Grupsuz'' 
        END AS GRUPADI , 
        ALICI_SATICI(BÜTÜN) = (SELECT FIRMA FROM REHBER WHERE FB.SATICIKODU = REHBER.ID), 
        ALICI_SATICI(SATIR) = (SELECT FIRMA FROM REHBER WHERE F.SATICIKODU = REHBER.ID), 
         (SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID = FB.SUBEID) AS SUBE , 
         (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM = -2701 AND G.DEGER = S.MARKA AND F.TUR = 1) AS MARKA , 
         (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.DIL = -1 AND G.BOLUM = cast(''-2701'' || cast(S.MARKA as varchar) as integer) AND F.TUR = 1) AS MODEL , 
         (SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU = R1.ID) AS PERSONEL , 
         FB.ACIKLAMA AS ACIKLAMA1 , FB.ACIKLAMA2, FB.FATURASERI, 
        (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI=1 and RA.SIRA=RB.SIRA AND RA.YERI=RB.YERI INNER JOIN REHBERILETISIM RI  on R.ID=RI.REHBERID and RI.VARSAYILAN=1 WHERE RB.YER_ID=RI.ID AND RA.VARSAYILAN=8 LIMIT 1 ) AS IL , 
         F.OZELKOD AS F_OZELKOD ,  F.OZELKOD2 AS F_OZELKOD2 , 
         CASE 
            WHEN (FB.TUR = 10) AND (408 IN (SELECT F1.YERI FROM FATURA F1 WHERE F1.YERID IN (SELECT F2.ID FROM FATURA F2 WHERE F2.FATBASID = FB.ID))) THEN ''Faturaya'' 
            WHEN (FB.TUR = 14) AND (411 IN (SELECT YERI FROM FATURA WHERE YERID IN (SELECT ID FROM FATURA F3 WHERE F3.FATBASID = FB.ID))) THEN ''Faturaya'' 
            ELSE '''' 
        END AS HEDEF , 
        FB.DOKTOR, FB.HASTA, fn_rpr_fatura_lot_Listesi(FB.ID, F.ID) AS LOTNO
    FROM FATBASLIK FB
    INNER JOIN FATURA F ON FB.ID = F.FATBASID
    LEFT OUTER JOIN REHBER R ON FB.REHBERID = R.ID
    LEFT OUTER JOIN MASRAFGELIR MG ON F.MASRAFID = MG.ID
    LEFT OUTER JOIN REHBERINI RI ON RI.BOLUM = ''StokKart_Anabirim'' AND RI.DEGER = F.BIRIM
    LEFT OUTER JOIN REHBERINI RI1 ON RI1.BOLUM = ''Kasa Türleri'' AND RI1.DEGER = FB.TUR
    LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
    WHERE FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
        AND FB.TUR IN (10, 14) AND ADET <> 0.0
) AS X WHERE FIRMA LIKE ''$FIRMA$%''
ORDER BY FATURATUR, GRUPADI, KATEGORIADI, FATURATARIH, ISLEMTUR;' WHERE id = 1459;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    ISLEMTUR, FATURATUR, OZELKOD, TIPI, FATURATARIH,  MONTH(FATURATARIH) AS BELGE_AY , 
    FATURANO, CARIKOD, FIRMA, STOK_OZELKOD, KOD, URUNNO, AD, DOKTOR, HASTA, ACIKLAMA, 
    cast(ADET as double precision) AS ADET, BIRIM, cast(BIRIMFIYAT as double precision) AS BIRIMFIYAT, 
     cast(BIRIMFIYAT * ADET as double precision) AS TUTAR , ISKONTO, 
     cast((BIRIMFIYAT * ADET) as double precision) - TUTAR AS ISKONTOTUTARI , 
    KDV,  cast(TUTAR as double precision) AS KDVMATRAHI ,  cast(KDVLITOPLAM as double precision) - TUTAR AS KDVTUTAR , 
     cast(KDVLITOPLAM as double precision) AS GENELTOPLAM , DOVIZ_CINSI, KATEGORIADI, GRUPADI, 
    ALICI_SATICI(BÜTÜN), ALICI_SATICI(SATIR), SUBE, MARKA, MODEL, 
    IL, PERSONEL, ACIKLAMA1, ACIKLAMA2, FATURASERI, F_OZELKOD, F_OZELKOD2, KAYNAK, LOTNO
FROM (
    SELECT 
        FB.OZELKOD, FB.TUR, 
         CASE 
            WHEN FB.TIPI = 1 THEN ''Alış/Satış'' 
            WHEN FB.TIPI = 2 THEN ''İade'' 
            WHEN FB.TIPI = 3 THEN ''Fiyat Farkı'' 
            WHEN FB.TIPI = 4 THEN ''S.Mes.Mak.'' 
        END AS TIPI ,
        RI1.ANAHTAR AS FATURATUR, FB.FATURATARIH, FB.FATURANO, R.KOD AS CARIKOD, R.FIRMA, 
         CASE WHEN F.TUR IN (1, 11) THEN ''Malzeme'' ELSE ''Hizmet'' END AS ISLEMTUR , 
         (SELECT OZELKOD FROM STOKLAR S WHERE F.URUNID = S.ID) AS STOK_OZELKOD , 
         CASE 
            WHEN F.TUR IN (1, 11) THEN (SELECT KOD FROM STOKLAR WHERE ID = F.URUNID) 
            ELSE (SELECT KOD FROM MASRAFGELIR WHERE ID = F.URUNID) 
        END AS KOD ,
         CASE 
            WHEN F.TUR IN (1, 11) THEN (SELECT STOKADI FROM STOKLAR WHERE ID = F.URUNID) 
            ELSE (SELECT AD FROM MASRAFGELIR WHERE ID = F.URUNID) 
        END AS AD ,
         CASE 
            WHEN F.TUR IN (1, 11) THEN (SELECT URUNNO FROM STOKLAR WHERE ID = F.URUNID) 
            ELSE '''' 
        END AS URUNNO ,
        F.ACIKLAMA, F.ADET, RI.ANAHTAR AS BIRIM, 
         CASE WHEN FB.KDVDURUM = ''Hariç'' THEN F.BIRIMFIYAT ELSE F.BIRIMFIYAT / (1 + (F.KDV / 100.0)) END AS BIRIMFIYAT , 
         CASE WHEN FB.KDVDURUM = ''Hariç'' THEN F.TUTAR ELSE F.TUTAR / (1 + (F.KDV / 100.0)) END AS TUTAR , 
         CASE WHEN FB.KDVDURUM = ''Hariç'' THEN F.TUTAR * (1 + (F.KDV / 100.0)) ELSE F.TUTAR END AS KDVLITOPLAM , 
        F.ISKONTO, F.KDV,  FB.RAPORDOVIZ AS DOVIZ_CINSI , 
         CASE 
            WHEN F.TUR IN (1, 11) THEN coalesce(((SELECT K.AD FROM KATEGORI K WHERE K.ID = (SELECT KATEGORI FROM STOKLAR WHERE ID = F.URUNID LIMIT 1 ))), ''Kategorisiz'') 
            ELSE coalesce(((SELECT MG1.KOD || ''-'' || MG1.AD FROM MASRAFGELIR MG1 WHERE MG1.KOD = REVERSE(SUBSTRING(REVERSE(MG.KOD), CHARINDEX(''.'', REVERSE(MG.KOD)) + 1, 100)) LIMIT 1 )), ''Kategorisiz'') 
        END AS KATEGORIADI , 
         CASE 
            WHEN F.TUR IN (1, 11) THEN coalesce(((SELECT ANAHTAR FROM GENINI WHERE BOLUM = -2704 AND DIL = -1 AND DEGER = (SELECT S1.GRUBU FROM STOKLAR S1 WHERE S1.ID = F.URUNID LIMIT 1 ))), ''Grupsuz'') 
            ELSE ''Grupsuz'' 
        END AS GRUPADI , 
        ALICI_SATICI(BÜTÜN) = (SELECT FIRMA FROM REHBER WHERE FB.SATICIKODU = REHBER.ID), 
        ALICI_SATICI(SATIR) = (SELECT FIRMA FROM REHBER WHERE F.SATICIKODU = REHBER.ID), 
         (SELECT RE.FIRMA FROM REHBER RE WHERE RE.ID = FB.SUBEID) AS SUBE , 
         (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM = -2701 AND G.DEGER = S.MARKA AND F.TUR = 1) AS MARKA , 
         (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM = cast(''-2701'' || cast(S.MARKA as varchar) as integer) AND F.TUR = 1) AS MODEL , 
         (SELECT BILGI FROM REHBERBILGI RB  INNER JOIN REHBERAYAR RA  ON RA.YERI = 1 AND RA.SIRA = RB.SIRA AND RA.YERI = RB.YERI INNER JOIN REHBERILETISIM RI  ON R.ID = RI.REHBERID AND RI.VARSAYILAN = 1 WHERE RB.YER_ID = RI.ID AND RA.VARSAYILAN = 8 LIMIT 1 ) AS IL , 
         (SELECT FIRMA FROM REHBER R1 WHERE F.SATICIKODU = R1.ID) AS PERSONEL , 
         FB.ACIKLAMA AS ACIKLAMA1 , FB.ACIKLAMA2, FB.FATURASERI,  F.OZELKOD AS F_OZELKOD ,  F.OZELKOD2 AS F_OZELKOD2 , 
         CASE 
            WHEN FB.TUR = 11 AND F.YERI = 407 THEN ''Sipariş'' 
            WHEN FB.TUR = 11 AND F.YERI = 408 THEN ''İrsaliye'' 
            WHEN FB.TUR = 15 AND F.YERI = 410 THEN ''Sipariş'' 
            WHEN FB.TUR = 15 AND F.YERI = 411 THEN ''İrsaliye'' 
            WHEN FB.TUR = 15 AND F.YERI = 462 THEN ''Konsinye'' 
            WHEN FB.TUR = 16 AND F.YERI = 473 THEN ''Sipariş'' 
            WHEN FB.TUR = 16 AND F.YERI = 424 THEN ''İrsaliye'' 
            ELSE '''' 
        END AS KAYNAK , 
        FB.DOKTOR, FB.HASTA, fn_rpr_fatura_lot_Listesi(FB.ID, F.ID) AS LOTNO
    FROM FATBASLIK FB
    INNER JOIN FATURA F ON FB.ID = F.FATBASID
    LEFT OUTER JOIN REHBER R ON FB.REHBERID = R.ID
    LEFT OUTER JOIN MASRAFGELIR MG ON F.MASRAFID = MG.ID
    LEFT OUTER JOIN REHBERINI RI ON RI.BOLUM = ''StokKart_Anabirim'' AND RI.DEGER = F.BIRIM
    LEFT OUTER JOIN REHBERINI RI1 ON RI1.BOLUM = ''Kasa Türleri'' AND RI1.DEGER = FB.TUR
    LEFT OUTER JOIN STOKLAR S ON S.ID = F.URUNID
    WHERE FATURATARIH BETWEEN ''$Baslangic$ 00:00'' AND ''$Bitis$ 23:59''
        AND FB.TUR IN (8, 11, 12, 15, 16) AND ADET <> 0.0
) AS X WHERE coalesce(FIRMA,'''') LIKE ''$FIRMA$%''
ORDER BY FATURATUR, GRUPADI, KATEGORIADI, FATURATARIH, ISLEMTUR' WHERE id = 1460;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    KOD, URUNNO, KATEGORI, STOKADI, MARKA, MODEL, GRUBU, IZLEME,
    coalesce(STOK,0) AS STOK,
    coalesce(ANADEPO,0) AS ANADEPO,
    coalesce(UŞAK,0) AS UŞAK,
    coalesce(KÜTAHYA,0) AS KÜTAHYA,
    coalesce(Konsinye Giriş,0) AS Konsinye Giriş,
    coalesce(Konsinye Çıkış,0) AS Konsinye Çıkış,
    coalesce(FAİL DEPO,0) AS FAİL DEPO, 
    coalesce(Yedek Depo,0) AS Yedek Depo
FROM (
    SELECT 
        S.KOD, URUNNO,  K.AD AS KATEGORI , S.STOKADI, 
        (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2701 AND G.DEGER=S.MARKA) AS MARKA , 
         (SELECT ANAHTAR FROM GENINI G WHERE G.DEGER = S.MODEL AND G.BOLUM=cast(''-2701''||cast(S.MARKA as varchar) as integer)) AS MODEL , 
         (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=''-2704'' AND G.DEGER=S.GRUBU) AS GRUBU , 
        (SELECT ANAHTAR FROM GENINI G WHERE G.BOLUM=-2706 AND G.DEGER=S.IZLEME) AS IZLEME , 
         (SELECT SUM(KALAN) FROM STOKDURUM SD1 WHERE SD1.STOKID = S.ID) AS STOK , 
        D.DEPOADI, coalesce(SD.KALAN,0) AS KALAN
    FROM STOKLAR S
    LEFT JOIN STOKDURUM SD ON SD.STOKID = S.ID
    LEFT JOIN DEPOLAR D ON D.ID = SD.DEPOID
    LEFT JOIN KATEGORI K ON K.ID = S.KATEGORI
) AS X 
PIVOT (
    MAX(KALAN) FOR DEPOADI IN (
        ANADEPO,UŞAK,KÜTAHYA,Konsinye Giriş,
        Konsinye Çıkış,FAİL DEPO,Yedek Depo
    )
) PVT
WHERE KOD LIKE ''$StokKod$%''' WHERE id = 1461;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    S.KOD, S.URUNNO, S.STOKADI, K.AD AS KATEGORI, D.DEPOADI, SL.LOTNO, SDI.KALAN
FROM STOKLAR S
INNER JOIN KATEGORI K ON K.ID = S.KATEGORI
INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
INNER JOIN STOKSERILOT SL ON SL.STOKID = S.ID AND SDI.SERILOTID = SL.ID
INNER JOIN DEPOLAR D ON D.ID = SDI.DEPOID' WHERE id = 1462;
UPDATE public.dokumler SET sql = '/*PGX*/SELECT 
    (SELECT SUBSTRING(FIRMA,1,CHARINDEX('' '',FIRMA,1)) FROM REHBER WHERE ID = -1) AS KURUM_ADI, 
    (SELECT BILGI FROM REHBERBILGI WHERE YER_ID = -1 AND YERI = 2 AND SIRA = 40) AS KURUM_UTS_NO, 
    S.URUNNO, SL.SERINO, SL.LOTNO, SUM(SDI.KALAN) AS ADET, 1 AS FIYAT, SL.URT, SL.SKT
FROM STOKLAR S
INNER JOIN STOKDURUMIZLEME SDI ON SDI.STOKID = S.ID
INNER JOIN STOKSERILOT SL ON SL.STOKID = S.ID AND SL.ID = SDI.SERILOTID
GROUP BY S.URUNNO, SL.SERINO, SL.LOTNO, SL.SKT, SL.URT
HAVING SUM(SDI.KALAN) > 0
ORDER BY S.URUNNO' WHERE id = 1463;
