			</tr>
		</xsl:template>
		<xsl:template name="Party_Title">
			<xsl:param name="PartyType"></xsl:param>
			<td style="width:469px; " align="left">
				<xsl:if test="cac:PartyName">
					<xsl:value-of select="cac:PartyName/cbc:Name"></xsl:value-of>
					<br />
				</xsl:if>
				<xsl:for-each select="cac:Person">
					<xsl:for-each select="cbc:Title">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:FirstName">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:MiddleName">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160; </xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:FamilyName">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:NameSuffix">
						<xsl:apply-templates></xsl:apply-templates>
					</xsl:for-each>
					<xsl:if test="$PartyType=''TAXFREE''">
						<br />
						<xsl:text>Pasaport No: </xsl:text>
						<xsl:value-of select="cac:IdentityDocumentReference/cbc:ID"></xsl:value-of>
						<br />
						<xsl:text>Ülkesi: </xsl:text>
						<xsl:value-of select="cbc:NationalityID"></xsl:value-of>
					</xsl:if>
				</xsl:for-each>
			</td>
		</xsl:template>
		<xsl:template name="Party_Adress">
			<xsl:param name="PartyType"></xsl:param>
			<td style="width:469px; " align="left">
				<xsl:for-each select="cac:PostalAddress">
					<xsl:for-each select="cbc:StreetName">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:BuildingName">
						<xsl:apply-templates></xsl:apply-templates>
					</xsl:for-each>
					<xsl:for-each select="cbc:BuildingNumber">
						<xsl:text> No:</xsl:text>
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<br />
					<xsl:for-each select="cbc:Room">
						<xsl:text>Kapı No:</xsl:text>
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<br />
					<xsl:for-each select="cbc:PostalZone">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:CitySubdivisionName">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>/ </xsl:text>
					</xsl:for-each>
					<xsl:for-each select="cbc:CityName">
						<xsl:apply-templates></xsl:apply-templates>
						<xsl:text>&#160;</xsl:text>
					</xsl:for-each>
					<xsl:if test="$PartyType=''TAXFREE''">
						<br />
						<xsl:value-of select="cac:Country/cbc:Name"></xsl:value-of>
						<br />
					</xsl:if>
				</xsl:for-each>
			</td>
		</xsl:template>
		<xsl:template name=''Party_Other''>
			<xsl:param name="PartyType"></xsl:param>
			<xsl:for-each select="cbc:WebsiteURI">
				<tr align="left">
					<td>
						<xsl:text>Web Sitesi: </xsl:text>
						<xsl:value-of select="."></xsl:value-of>
					</td>
				</tr>
			</xsl:for-each>
			<xsl:for-each select="cac:Contact/cbc:ElectronicMail">
				<tr align="left">
					<td>
						<xsl:text>E-Posta: </xsl:text>
						<xsl:value-of select="."></xsl:value-of>
					</td>
				</tr>
			</xsl:for-each>
			<xsl:for-each select="cac:Contact">
				<xsl:if test="cbc:Telephone or cbc:Telefax">
					<tr align="left">
						<td style="width:469px; " align="left">
							<xsl:for-each select="cbc:Telephone">
								<xsl:text>Tel: </xsl:text>
								<xsl:apply-templates></xsl:apply-templates>
							</xsl:for-each>
							<xsl:for-each select="cbc:Telefax">
								<xsl:text> Fax: </xsl:text>
								<xsl:apply-templates></xsl:apply-templates>
							</xsl:for-each>
							<xsl:text>&#160;</xsl:text>
						</td>
					</tr>
				</xsl:if>
			</xsl:for-each>
			<xsl:if test="$PartyType!=''TAXFREE''">
				<xsl:for-each select="cac:PartyTaxScheme/cac:TaxScheme/cbc:Name">
					<tr align="left">
						<td>
							<xsl:text>Vergi Dairesi: </xsl:text>
							<xsl:apply-templates></xsl:apply-templates>
						</td>
					</tr>
				</xsl:for-each>
				<xsl:for-each select="cac:PartyIdentification">
					<tr align="left">
						<td>
							<xsl:value-of select="cbc:ID/@schemeID"></xsl:value-of>
							<xsl:text>: </xsl:text>
							<xsl:value-of select="cbc:ID"></xsl:value-of>
						</td>
					</tr>
				</xsl:for-each>
			</xsl:if>
		</xsl:template>
		<xsl:template name="Curr_Type">
			<xsl:value-of select="format-number(., ''###.gt_0,00'', ''european'')"></xsl:value-of>
			<xsl:if test="@currencyID">
				<xsl:text> </xsl:text>
				<xsl:choose>
					<xsl:when test="@currencyID = ''TRL'' or @currencyID = ''TRY''">
						<xsl:text>TL</xsl:text>
					</xsl:when>
					<xsl:otherwise>
						<xsl:value-of select="@currencyID"></xsl:value-of>
					</xsl:otherwise>
				</xsl:choose>
			</xsl:if>
		</xsl:template>
	</xsl:stylesheet>
' WHERE id = 1465;

SELECT
    count(*) AS sql_dolu,
    count(*) FILTER (WHERE sql LIKE '/*PGX*/%') AS pgxli
FROM public.dokumler
WHERE coalesce(sql, '') <> '';
